window.SZYF_DATA.shizheng = [{"month": "2025年1月", "year": 2025, "items": [{"title": "12月30日12时，随着第二批沙戈荒项目哈密玉山风电场并网，新疆新能源装机规模突", "detail": "破1亿千瓦大\n关，占到全疆电力总装机的55%，成为新疆第一大电源。截至12月30日，新疆年内新增新能源装机规模\n3557万千瓦，位居全国第一。"}, {"title": "中国人民政治协商会议全国委员会12月31日上午在全国政协礼堂举行新年茶话会。", "detail": "习近平强调，人\n民政协要坚持党的领导、统一战线、协商民主有机结合，围绕中心、服务大局，充分发挥专门协商机构作\n用，加强思想政治引领，积极议政建言，更加广泛地凝聚人心、凝聚共识、凝聚智慧、凝聚力量。"}, {"title": "新年前夕，国家主席习近平通过中央广播电视总台和互联网，发表了二〇二五年新年贺词。", "detail": "习近平指\n出，2024年，我国经济回暖向好，国内生产总值预计超过130万亿元。粮食产量突破1.4万亿斤，中国碗装\n了更多中国粮。2025年，我们将全面完成“十四五”规划。要实施更加积极有为的政策，聚精会神抓好高质\n量发展，推动高水平科技自立自强，保持经济社会发展良好势头。中国愿同各国一道，做友好合作的践行\n者、文明互鉴的推动者、构建人类命运共同体的参与者，共同开创世界的美好未来。"}, {"title": "国家电网12月31日宣布，当前世界规模最大的抽水蓄能电站——国家电网河北丰宁抽水", "detail": "蓄能电站最\n后一台变速机组正式投入商业运行，丰宁电站实现全面投产发电。"}, {"title": "2025年1月1日出版的第1期《求是》杂志发表习近平的重要文章《以中国式现代化全", "detail": "面推进强国建\n设、民族复兴伟业》。文章指出，党的领导直接关系中国式现代化的根本方向、前途命运、最终成败。党\n的领导决定中国式现代化的根本性质。党的领导确保中国式现代化锚定奋斗目标行稳致远。党的领导激发\n建设中国式现代化的强劲动力。党的领导凝聚建设中国式现代化的磅礴力量。\n文章指出，中国式现代化是强国建设、民族复兴的康庄大道。中国式现代化既有各国现代化的共同特\n征，更有基于自己国情的鲜明特色。第一，人口规模巨大的现代化。第二，全体人民共同富裕的现代化。\n第三，物质文明和精神文明相协调的现代化。第四，人与自然和谐共生的现代化。第五，走和平发展道路\n的现代化。"}, {"title": "1月1日，人力资源社会保障部等三部门发布《实施弹性退休制度暂行办法》，就弹性退休", "detail": "的办理程\n序、基本养老金领取等方面作出明确规定。办法提出，自2025年1月1日起，职工达到国家规定的按月领\n取基本养老金最低缴费年限，可以自愿选择弹性提前退休，提前时间距法定退休年龄最长不超过3年，且\n退休年龄不得低于女职工50周岁、55周岁及男职工60周岁的原法定退休年龄。"}, {"title": "1月1日0时17分，全球最大“华龙一号”核电基地迎来新年“开门红”，中核集团旗下", "detail": "中国核电投资控\n股的漳州核电1号机组正式投入商业运行，标志着“华龙一号”批量化建设取得重大进展。漳州核电基地是“华\n龙一号”批量化建设的始发地，规划建设6台百万千瓦级“华龙一号”核电机组，其中4台机组已开工建设，\n安全质量均处于良好受控状态。"}, {"title": "1月1日，随着“东方澳洲”轮最后一个集装箱顺利装船，青岛港自动化码头桥吊平均单机", "detail": "作业效率达\n到60.9自然箱/小时，第12次刷新集装箱自动化码头装卸效率世界纪录。"}, {"title": "1月1日，我国在建海拔最高的双曲拱坝电站——叶巴滩水电站将进行首台机组定子的吊装", "detail": "工作。叶\n巴滩水电站位于西南地区金沙江上游，装机容量224万千瓦，是国家“十四五”规划102项重大工程之一，也\n是国家清洁能源基地——金沙江上游水风光一体化清洁能源基地的重要支撑项目。"}, {"title": "1月2日，中国国家铁路集团有限公司召开工作会议。", "detail": "会议发布的最新统计数据显示，截至2024年\n底，全国铁路营业里程达到16.2万公里，其中高铁4.8万公里，我国高铁运营里程再创新纪录。"}, {"title": "列满载新鲜果蔬的中老铁路国际货物列车1月2日从中国昆明启程驶向老挝，标志着中老铁", "detail": "路自2021\n1\n(cid:3)\n年12月3日开通运营至今，货物运输量已突破5000万吨。中老铁路北起中国昆明，南至老挝万象，全长\n1035公里。"}, {"title": "1月2日，中国担任上海合作组织2024－2025年轮值主席国徽标发布。", "detail": "轮值主席国徽标以上合组织\n徽标为主体，同中国特色有机结合。主席国口号“弘扬‘上海精神’：上合组织在行动”以中俄英三种文字环状\n嵌入其中。"}, {"title": "华能金坛盐穴压缩空气储能发电二期项目日前在江苏常州正式开工建设。", "detail": "建成后，它将成为世界上\n单机功率最大、总容量最大、综合效率最高的压缩空气储能电站。"}, {"title": "1月3日，国新办举行“中国经济高质量发展成效”系列新闻发布会，2024年，我国全", "detail": "球创新指数排名\n升到第11位，比上年提升1位。"}, {"title": "国务院办公厅日前印发《关于严格规范涉企行政检查的意见》，《意见》明确，除行政执法", "detail": "机关、\n法律法规授权组织、受委托组织外，任何组织和个人不得实施行政检查。规范行政检查行为，防止逐利检\n查、任性检查，涉企行政检查要做到“五个严禁”、“八个不得”。"}, {"title": "近日，中办、国办印发《关于加快建设统一开放的交通运输市场的意见》。", "detail": "目前，国家综合立体交\n通网主骨架“6轴7廊8通道”已建成路线里程超过26万公里，建成率约90%。"}, {"title": "1月4日，“中山大学极地”号破冰科考船从广州南沙出发，前往渤海冰区，开展渤海冬季", "detail": "冰-海系统\n关键过程及其生态环境效应重大科学考察。这是国内首次在冬季对渤海冰区开展海冰-海洋-生态综合调查。\n“中山大学极地”号是我国高校首艘极地破冰科考船，具备极地全海深科考能力。"}, {"title": "2025年中国人民银行工作会议1月3日—4日召开。", "detail": "会议强调，要坚持稳中求进工作总基调，完整\n准确全面贯彻新发展理念，实施适度宽松的货币政策，防范化解重点领域金融风险，进一步深化金融改革\n和高水平对外开放，着力扩大内需、稳定预期、激发活力，为推动经济持续回升向好营造良好的货币金融\n环境。"}, {"title": "1月4日，第十七届精神文明建设“五个一工程”表彰座谈会在北京举行。", "detail": "与会代表认为，要深入学习\n实践习近平文化思想，树立继往开来、文泽后代的抱负，把文化追求和艺术理想融入中国式现代化的伟大\n事业中，不断攀登中国历史上新的文化高峰。"}, {"title": "国务院办公厅日前印发《关于全面深化药品医疗器械监管改革促进医药产业高质量发展的意", "detail": "见》，\n《意见》提出，到2027年，药品医疗器械监管法律法规制度更加完善，监管体系、监管机制、监管方式更\n好适应医药创新和产业高质量发展需求，创新药和医疗器械审评审批质量效率明显提升，全生命周期监管\n显著加强，质量安全水平全面提高，建成与医药创新和产业发展相适应的监管体系。到2035年，药品医疗\n器械质量安全、有效、可及得到充分保障，医药产业具有更强的创新创造力和全球竞争力，基本实现监管\n现代化。"}, {"title": "全国规模最大的光氢储一体化海上光伏示范项目——国家能源集团国华投资江苏分公司如东", "detail": "光氢储\n一体化项目日前成功并网发电。这标志着国内首个集光伏发电、制氢加氢和储能电站于一体的“综合能源利\n用+滨海生态治理”项目投运。"}, {"title": "全国宣传部长会议1月3日至4日在京召开。", "detail": "蔡奇强调，要深入学习贯彻习近平文化思想，深刻领\n悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，着力用党的创新理论凝\n心铸魂，着力巩固壮大主流思想舆论，着力弘扬社会主义核心价值观，着力深化文化体制机制改革，着力\n构建更有效力的国际传播体系，为以中国式现代化全面推进强国建设、民族复兴伟业提供坚强思想保证、\n强大精神力量、有利文化条件。\n2\n(cid:3)"}, {"title": "1月5日，由上海振华重工为中交二航局建造的150米打桩船“二航长青”轮交船仪式在", "detail": "江苏启东举行，\n这也意味着我国水工建设领域再添一座“定海神器”。“二航长青”轮于2024年1月18日开工建造，该轮总长"}, {"title": "5米，型宽40.8米，型深8.4米，是目前世界最大的打桩船。", "detail": ""}, {"title": "1月5日上午，中国自主研制最大直径双护盾TBM“江汉平安号”，在湖北省宜昌市夷陵", "detail": "区引江补汉\n工程6号平洞始发。TBM指的是硬岩隧道掘进机。"}, {"title": "1月5日，《中国冰雪旅游发展报告（2025）》发布。", "detail": "报告显示，2023—2024冰雪季中国冰雪休闲旅\n游人数为4.3亿人次，冰雪休闲旅游收入为5247亿元，预计2024—2025冰雪季中国冰雪休闲旅游人数有望\n达到5.2亿人次。"}, {"title": "习近平1月6日上午在中国共产党第二十届中央纪律检查委员会第四次全体会议上发表重要", "detail": "讲话。\n习近平强调，腐败是我们党面临的最大威胁，反腐败是最彻底的自我革命。习近平指出，要推进政治监督\n具体化、精准化、常态化。同党中央保持高度一致必须说到做到。思想上，要坚持不懈强化党的创新理论\n武装；政治上，要坚持党中央集中统一领导；行动上，要坚持把党中央各项决策部署落实情况作为政治监\n督重点。"}, {"title": "1(cid:1)月(cid:1)6(cid:1)日，国家主席习近平同博茨瓦纳总统", "detail": "博科互致贺电，庆祝两国建交(cid:3)50(cid:3)周年。习近平指出，建\n交(cid:1)50(cid:1)年来，无论国际形势如何变幻，中博关系始终保持良好发展势头，成为平等相待的好朋友、携手发展\n的好伙伴。"}, {"title": "国家发展改革委、国家数据局、工业和信息化部三部门近日联合印发《国家数据基础设施建", "detail": "设指引》，\n提出到(cid:3)2029(cid:3)年，国家数据基础设施建设和运营体制机制基本建立。"}, {"title": "2025(cid:1)年(cid:1)1(cid:1)月(cid:1)7(cid", "detail": ":1)日(cid:1)04(cid:1)时(cid:1)00(cid:1)分，我国在西昌卫星发射中心使用长征三号乙运载火箭，成功将实践二十\n五号卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。该卫星主要用于卫星燃料补加与延\n寿服务技术验证。"}, {"title": "1(cid:1)月(cid:1)7(cid:1)日，我国最大滩涂光伏储能电站——", "detail": "华电莱州大型盐碱滩涂光储一体化项目投产发电，大片的\n盐碱地变身清洁能源新绿洲。项目的建设对于我国盐碱地资源的高效利用和推动能源结构转型具有重要意\n义。"}, {"title": "1(cid:1)月(cid:1)7(cid:1)日从(cid:1)2025(ci", "detail": "d:1)年全国知识产权局局长会议上获悉，2024(cid:3)年，我国国内发明专利有效量达到(cid:3)475.6\n万件，战略性新兴产业发明专利有效量达到(cid:1)134.9(cid:1)万件，同比增长(cid:1)15.7%。PCT(cid:1)国际专利、马德里国际商标、\n海牙体系外观设计申请量均位居世界前列。"}, {"title": "1(cid:1)月(cid:1)7(cid:1)日，国家发展改革委印发的《全国统", "detail": "一大市场建设指引（试行）》对外公布。其中提出，健全\n全国统一的社保公共服务平台，全面取消在就业地参保户籍限制，完善社保关系转移接续政策。"}, {"title": "1(cid:1)月(cid:1)7(cid:1)日，《中共中央(cid:3)国务", "detail": "院关于深化养老服务改革发展的意见》发布。这是我国首次以党中央、\n国务院名义印发关于养老服务工作的意见。总体要求是坚持尽力而为、量力而行，增强科学预判、做好前\n瞻部署，加快健全养老服务网络，优化居家为基础、社区为依托、机构为专业支撑、医养相结合的养老服\n务供给格局，强化以失能老年人照护为重点的基本养老服务，健全分级分类、普惠可及、覆盖城乡、持续\n发展的养老服务体系，加强老年健康促进，推动养老服务扩容提质，进一步激发养老事业和养老产业发展\n活力，更好满足老年人多层次多样化养老服务需求。"}, {"title": "中国共产党第二十届中央纪律检查委员会第四次全体会议，于(cid:1)2025(c", "detail": "id:1)年(cid:1)1(cid:1)月(cid:1)6(cid:1)日至(cid:1)8(cid:1)日在北京举行。\n全会强调，以中国式现代化全面推进强国建设、民族复兴伟业，对反腐败斗争提出了新的更高要求。纪检\n3\n(cid:3)\n监察机关要切实把思想和行动统一到以习近平同志为核心的党中央对形势的准确判断、对任务的科学部署\n上来，深刻把握新时代反腐败斗争取得的历史性成就，坚定打赢反腐败这场攻坚战的必胜信心；深刻把握\n当前反腐败斗争仍然严峻复杂的形势，坚定打赢反腐败这场持久战的如磐恒心；深刻把握一体推进不敢腐、\n不能腐、不想腐方针方略，坚定打赢反腐败这场总体战的坚强决心。\n会议指出，要持续发力惩治“蝇贪蚁腐”，聚焦县以下这一关键环节、薄弱环节持续抓下去。深化“校园\n餐”、农村集体“三资”管理、乡村振兴资金使用监管、医保基金管理、养老服务等方面突出问题治理，扎实\n推进整治殡葬领域腐败乱象专项行动。\n开展“纪检监察工作规范化法治化正规化建设年”行动，着力推动纪检监察铁军建设再上新台阶。加强政\n治建设，敬畏信仰、敬畏组织；加强能力建设，敬畏责任、敬畏使命；加强作风建设，敬畏权力、敬畏人\n民；加强廉洁建设，敬畏纪律、敬畏法律。"}, {"title": "自然资源部中国地质调查局1月8日宣布，我国锂矿找矿取得一系列重大突破，锂矿储量从", "detail": "全球占\n比6%升至16.5%，从世界第六跃至第二，重塑了全球锂资源格局。"}, {"title": "中国航天员科研训练中心1月8日下午在北京航天城举行神舟十八号航天员乘组与记者见面", "detail": "会，叶\n光富、李聪、李广苏3名航天员从太空返回两个多月后首次正式公开亮相。神舟十八号载人飞船于2024年\n4月25日从酒泉卫星发射中心发射升空，3名航天员在轨驻留192天，完成了大量空间科学实验和试验，进\n行了2次出舱活动，刷新了中国航天员单次出舱活动时间纪录，于2024年11月4日安全返回。"}, {"title": "中共中央政治局常务委员会1月9日全天召开会议，会议指出，坚持党的全面领导，是我们", "detail": "的最大\n政治优势。坚持党中央集中统一领导，是我们不断取得胜利的根本所在。"}, {"title": "国家统计局1月9日发布数据显示，2024年全年，全国居民消费价格指数（CPI）比", "detail": "上年上涨0.2%。"}, {"title": "国家邮政局最新数据显示，2024年快递业务量和业务收入分别完成1745亿件和1.", "detail": "4万亿元，同比分\n别增长21%和13%。我国快递业务量连续11年稳居世界第一。"}, {"title": "近日，国务院办公厅印发《关于促进政府投资基金高质量发展的指导意见》，《指导意见》", "detail": "强调，\n突出政府引导和政策性定位，按照市场化、法治化、专业化原则规范运作政府投资基金，发展耐心资本，\n注重发挥实效。合理统筹基金布局，防止同质化竞争和对社会资本产生挤出效应。健全权责一致、激励约\n束相容的责任机制，促进形成规模适度、布局合理、运作规范、科学高效、风险可控的政府投资基金高质\n量发展格局。"}, {"title": "1月9日，中国能建投资建设的“能储一号”全球首座300兆瓦级压气储能示范工程，在", "detail": "湖北应城全容\n量并网发电。项目创造了单机功率、储能规模和转换效率三项世界纪录，实现关键核心装备和深地空间利\n用产品100%国产化。"}, {"title": "1月9日，中国—东盟医药区域集采平台启动仪式在广西防城港市举行。", "detail": "据悉，该平台为国家医疗保\n障局指导地方建设的首个跨境医药区域集采平台，平台的建设将赋能防城港国际医学开放试验区高水平开\n放发展，推动中国医药“走出去”。"}, {"title": "中国法学会第九次全国会员代表大会1月10日上午在北京开幕，会上传达习近平致信。", "detail": "习近平强调，\n新时代新征程，各级法学会要坚持以新时代中国特色社会主义思想为指导，全面贯彻新时代中国特色社会\n主义法治思想，坚持党的全面领导，坚持走中国特色社会主义法治道路，坚持服务党和国家工作大局，进\n一步加强自身建设，更好发挥桥梁纽带作用，扎实做好繁荣法学研究、服务法治实践、加强法治宣传、培\n养法治人才等工作，努力开创法学会事业发展新局面。"}, {"title": "2025年1月10日是第五个中国人民警察节。", "detail": "2020年7月21日，《国务院关于同意设立“中国人民警\n4\n(cid:3)\n察节”的批复》发布，同意自2021年起，将每年1月10日设立为“中国人民警察节”，是在国家层面专门为\n人民警察队伍设立的节日，是对人民警察队伍为党和人民利益英勇奋斗的充分肯定。"}, {"title": "国务院新闻办公室1月10日举行发布会，市场监管总局相关负责人表示，中国经营主体发", "detail": "展总体上\n实现了量的合理增长和质的有效提升，截至2024年11月底，全国实有登记注册经营主体1.89亿，同比增\n长3.1%。"}, {"title": "1月10日，国家重大科技基础设施先进阿秒激光设施在广东东莞正式开工，该设施由中国", "detail": "科学院承\n担建设，共布局10条束线和22个应用终端。阿秒，是人类目前能够掌握的最短时间尺度，1阿秒仅为一百\n亿亿分之一秒（10-18秒）。"}, {"title": "习近平近日对审计工作作出重要指示指出，新征程上，要坚持党中央对审计工作的集中统一", "detail": "领导，\n聚焦主责主业，深化改革创新，加强自身建设，着力构建集中统一、全面覆盖、权威高效的审计监督体系，\n不断提高审计监督质效，以高质量审计监督护航经济社会高质量发展，为以中国式现代化全面推进强国建\n设、民族复兴伟业作出新的贡献。"}, {"title": "据国家卫生健康委网站消息，2024年我国居民健康素养水平达到31.87%，比20", "detail": "23年提高2.17个百\n分点，保持较快增幅。"}, {"title": "1月11日至12日，全国商务工作会议在北京召开，总结2024年商务工作，研究部署", "detail": "2025年工作任\n务。会议明确，2025年全国商务系统要推进提振消费专项行动，加力扩围实施消费品以旧换新。创新多元\n化消费场景，扩大服务消费，发展数字消费，加快构建高标准市场体系，完善现代商贸流通体系。要全力\n以赴稳外贸，推动贸易高质量发展。加快培育外贸新动能，拓展跨境电商，发展绿色贸易，推动贸易数字\n化。多措并举支持企业开拓多元化国际市场。积极扩大进口。创新提升服务贸易，创新发展数字贸易。"}, {"title": "海关总署1月12日公布出台16条重点措施，支持新时代中部地区加快崛起。", "detail": "支持中部地区打造更\n具竞争力的内陆开放高地方面，主要措施包括：拓展“铁海联运”“空陆联运”“空空中转”业务，优化铁路快通、\n过境班列集拼、集散监管模式，支持和保障鄂州花湖机场新开和加密国际定期货运航班，支持提升合肥国\n际陆港在国家集结中心规划层级，支持郑州国际陆港新址建设，助推内陆开放通道建设。\n获取后续更新及更多时政考试资料，请加微信：yumi9938。"}, {"title": "截至2025年1月，我国已与30个国家和地区签署了23个自贸协定，自贸伙伴遍及五", "detail": "大洲，自贸区\n网络不断扩展深化。"}, {"title": "1月11日，第十一次中英经济财金对话在北京举行。", "detail": "此次对话是时隔近6年后再次举办。这一高级\n别对话机制建于2008年，是就经济财金领域战略性、全局性、长期性重大问题开展对话合作的重要平台。"}, {"title": "1月8日至10日，第二十届中国会展经济国际合作论坛（CEFCO论坛）在天津举办。", "detail": "本届论坛以“聚\n新质生产力谋可持续未来”为主题。"}, {"title": "1月13日11时，我国太原卫星发射中心在山东海阳附近海域使用捷龙三号运载火箭，成", "detail": "功将微厘空\n间01组10颗卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "全国科技工作会议1月13日在北京召开。", "detail": "丁薛祥表示，要准确把握我国科技工作的总体格局，坚持\n全国“一盘棋”，加强战略规划、政策措施、重大任务、科研力量、资源平台、区域创新等方面的统筹。"}, {"title": "1月13日上午，国务院新闻办公室召开新闻发布会，介绍我国2024年全年进出口情况。", "detail": "据海关统计，\n2024年，我国货物贸易进出口总值43.85万亿元，同比增长5%。其中，出口规模首次突破25万亿元，达到"}, {"title": "45万亿元，同比增长7.1%，连续第8年保持增长，展现出较强的竞争力；", "detail": "进口18.39万亿元，增长2.3%。"}, {"title": "中国汽车工业协会1月13日发布最新数据，2024年我国汽车产销量双双超过3100", "detail": "万辆，再创历史\n5\n(cid:3)\n新高。其中，汽车出口585.9万辆，同比增长19.3%，进一步巩固第一大汽车出口国地位。最新数据同时显\n示，2024年，我国新能源汽车产销量分别完成1288.8万辆和1286.6万辆，同比分别增长34.4%和35.5%。"}, {"title": "我国首个百万千瓦级居民虚拟电厂1月14日在江苏启动建设，旨在将省内海量居民家中的", "detail": "大功率智\n能电器整合进云端虚拟能量池，配合新能源发电特性开展灵活调配，助力全社会绿色低碳转型。"}, {"title": "1月14日，国家移民管理局召开新闻发布会，发布2024年移民管理工作主要数据。", "detail": "2024年，全国移\n民管理机构累计查验出入境人员6.1亿人次，同比上升43.9%。免签入境外国人2011.5万人次、同比上升\n112.3%。"}, {"title": "1月13日，第32届世界大学生冬季运动会在意大利都灵开幕。", "detail": "来自54个国家和地区的1655名运动\n员将在11个大项中展开角逐。大冬会每两年举办一次。2023年，在美国普莱西德湖举办的第31届大冬会\n上，中国代表团获得1金2银1铜共4枚奖牌。"}, {"title": "从1月15日开幕的广东省十四届人大三次会议上获悉，2024年广东地区生产总值预计", "detail": "将迈上14万\n亿元新台阶、连续36年居全国首位。这是我国首个经济总量突破14万亿元的省份。"}, {"title": "1月15日，纪念遵义会议90周年大会在贵州遵义举行。", "detail": "会议强调，遵义会议重大贡献永载史册，遵\n义会议精神永放光芒。新征程上传承弘扬遵义会议精神，要始终坚持独立自主走自己的路，坚定以中国式\n现代化全面推进强国建设、民族复兴伟业的信心决心；大力发扬敢于斗争、敢于胜利的革命传统，凝聚攻\n坚克难、勇毅前行的强大力量。"}, {"title": "1月16日出版的第2期《求是》杂志将发表习近平的重要文章《进一步全面深化改革中的", "detail": "几个重大\n理论和实践问题》。文章指出，坚持守正创新是进一步全面深化改革必须牢牢把握、始终坚守的重大原则。\n守正和创新是辩证统一的，只有守正才能保证创新始终沿着正确方向前进，只有持续创新才能更好地守正。\n我们的改革是有方向、有原则的。坚持党的全面领导、坚持马克思主义、坚持中国特色社会主义、坚持人\n民民主专政，以促进社会公平正义、增进人民福祉为出发点和落脚点，这些都是管根本、管方向、管长远\n的，体现党的性质和宗旨，符合我国国情，符合人民根本利益，任何时候任何情况下都不能有丝毫动摇。\n文章指出，要坚持用科学方法指导和推进改革。改革是一项系统工程，需要处理好方方面面的关系，\n需要讲求科学方法。一是坚持改革和法治相统一。二是坚持破和立的辩证统一。三是坚持改革和开放相统\n一。四是处理好部署和落实的关系。"}, {"title": "韩国共同调查本部1月15日说，已于当天10时33分执行对被停职总统尹锡悦的逮捕令。", "detail": "尹锡悦是\n韩国宪政史上第一个被逮捕的现职总统。"}, {"title": "截至2024年底，我国国内发明专利有效量达到475.6万件，成为世界上首个突破4", "detail": "00万件的国家。\n我国每万人口高价值发明专利拥有量达到14件，提前完成国家“十四五”的规划预期目标。"}, {"title": "2025年全国春节文化和旅游消费月主场活动1月15日在吉林省长春市举办，正式开启", "detail": "全国春节文化\n和旅游消费月。2025年全国春节文化和旅游消费月以“文旅惠民乐民共享美好生活”为主题，各地将结合冬\n季及春节文化和旅游消费特点，围绕过年民俗、美食、冰雪等重点消费需求，举办超4000项约2.7万场次\n文旅消费活动。"}, {"title": "1月16日，工业和信息化部发布了我国2024年全年造船业的最新数据，中国造船业三", "detail": "大指标：造船\n完工量、新接订单量、手持订单量，继续稳步增长，连续15年全球第一。"}, {"title": "《京津冀水土保持公报（2023年）》日前发布，这是京津冀首次联合发布水土保持公报。", "detail": "公报显示，\n2023年，京津冀水土流失面积40727平方公里，其中水力侵蚀36445平方公里，风力侵蚀4282平方公里，\n水土保持率81.10%。\n6\n(cid:3)"}, {"title": "1(cid:1)月(cid:1)17(cid:1)日，国家统计局发布(cid:1", "detail": ")2024(cid:1)年中国经济年报。初步核算，全年国内生产总值(cid:3)1349084(cid:3)亿元，按\n不变价格计算，比上年增长(cid:3)5.0%。2024(cid:1)年末全国人口（包括(cid:1)31(cid:1)个省、自治区、直辖市和现役军人的人口，\n不包括居住在(cid:1)31(cid:1)个省、自治区、直辖市的港澳台居民和外籍人员）140828(cid:3)万人，比上年末减少(cid:1)139(cid:1)万人。\n全年出生人口(cid:3)954(cid:3)万人，人口出生率为(cid:1)6.77‰；死亡人口(cid:1)1093(cid:1)万人，人口死亡率为(cid:1)7.76‰；人口自然增长\n率为-0.99‰。"}, {"title": "中国互联网络信息中心(cid:1)1(cid:1)月(cid:1)17(cid:", "detail": "1)日在京发布第(cid:3)55(cid:3)次《中国互联网络发展状况统计报告》。报告显示，\n截至(cid:1)2024(cid:1)年(cid:1)12(cid:1)月，我国网民规模达(cid:3)11.08(cid:3)亿人，较(cid:1)2023(cid:1)年(cid:1)12(cid:1)月增长(cid:1)1608(cid:1)万人，互联网普及率达(cid:3)78.6%。"}, {"title": "随着最后一段重约(cid:1)215(cid:1)吨的钢桁梁精准吊装至指定位置，", "detail": "在建世界第一高桥——花江峡谷大桥于(cid:1)1\n月(cid:1)17(cid:1)日成功合龙，为今年通车运营打下坚实基础。项目资料显示，大桥为钢桁梁悬索桥，全长(cid:3)2890(cid:3)米，其\n中主桥跨径(cid:3)1420(cid:3)米，桥面至水面高度(cid:3)625(cid:3)米。建成后，会成为新的世界第一高桥、世界第一的山区跨径桥\n梁。"}, {"title": "1(cid:1)月(cid:1)17(cid:1)日(cid:1)12(cid:", "detail": "1)时(cid:1)7(cid:1)分，我国在酒泉卫星发射中心使用长征二号丁运载火箭，成功将巴基斯坦(cid:3)PRSC-EO1\n卫星、天路一号卫星和蓝碳一号卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。其中，\n天路一号卫星是一颗中高层大气临边探测遥感卫星，将为卫星应用及科学研究提供精确的大气数据。中高\n层大气一般是指距地面(cid:1)20—200(cid:1)公里这一段“飞机上不去，卫星下不来”的空间，处于传统航空器的最高飞行\n高度和卫星的最低轨道高度之间，尚未被完全开发和利用，天路一号就是用于探测这个区域的卫星。"}, {"title": "1(cid:1)月(cid:1)17(cid:1)日，国务院国资委发布了中央企业", "detail": "经济运行的最新数据。2024(cid:3)年，中央企业的资产规模突破\n了(cid:3)90(cid:3)万亿元，同比增长(cid:1)5.9%；实现增加值(cid:1)10.6(cid:1)万亿元，完成利润总额(cid:1)2.6(cid:1)万亿元，上交税费(cid:1)2.6(cid:1)万亿元，\n均实现了高质量的稳定增长。"}, {"title": "1(cid:1)月(cid:1)17(cid:1)日，国务院召开第三次廉政工作会", "detail": "议，李强强调，各级政府党组和各部门党组（党委）要压\n紧压实全面从严治党主体责任，把严的基调、严的措施、严的氛围一贯到底、落实到位。"}, {"title": "1(cid:1)月(cid:1)18(cid:1)日，习近平同越共中央总书记苏林", "detail": "、越南国家主席梁强互致贺电，热烈庆祝两国建交7(cid:3)5(cid:3)周年。\n习近平指出，中越是社会主义友好邻邦和具有战略意义的命运共同体。建交(cid:1)75(cid:1)年来，在争取国家独立和民\n族解放的峥嵘岁月中，双方并肩战斗、相互支持，“越中情谊深、同志加兄弟”成为两党两国关系最生动写照。"}, {"title": "巴西外交部(cid:1)1(cid:1)月(cid:1)17(cid:1)日发表", "detail": "公报说，作为金砖国家轮值主席国，巴西宣布尼日利亚正式成为金砖伙伴\n国。尼日利亚是第九个金砖伙伴国。白俄罗斯、玻利维亚、哈萨克斯坦、古巴、马来西亚、泰国、乌干达\n和乌兹别克斯坦(cid:1)8(cid:1)个国家已于本月(cid:1)1(cid:1)日成为金砖伙伴国。"}, {"title": "近日，2024(cid:1)年度十大科技名词评选结果在京揭晓，人工智能+、低空经", "detail": "济、月背采样、量子科技、\n具身智能、混合现实、生物制造、近零碳、实景三维、微核糖核酸等科技名词入选。"}, {"title": "1(cid:1)月(cid:1)19(cid:1)日，我国在航天科技集团六院(c", "detail": "id:1)165(cid:1)所抱龙峪试验区，首次实现了液氧煤油火箭发动机“一日三\n试”，标志着我国新一代运载火箭主动力发动机，适应批产交付的试验验证的能力再获提升，将有力支撑未\n来长征系列火箭高密度发射。"}, {"title": "日前，国家统计局网站发布(cid:1)2024(cid:1)年居民收入和消费支出", "detail": "情况。2024年，全国居民人均可支配收入41314\n元，比上年名义增长(cid:1)5.3%，扣除价格因素，实际增长(cid:1)5.1%。2024(cid:3)年，全国居民人均消费支出(cid:3)28227(cid:3)元，比\n上年名义增长(cid:1)5.3%，扣除价格因素，实际增长(cid:1)5.1%。"}, {"title": "近日，从自然资源部中国地质调查局获悉，我国在云南省红河地区发现超大规模离子吸附型", "detail": "稀土矿。\n这次发现的超大规模离子吸附型稀土矿，潜在资源达(cid:1)115(cid:1)万吨，其中，镨、钕、镝、铽等关键稀土元素超过\n7\n(cid:3)\n47万吨，这是1969年在江西首次发现离子吸附型稀土矿以后的又一重大突破，有望成为中国最大的中重稀\n土矿床。"}, {"title": "习近平1月20日下午在人民大会堂同各民主党派中央、全国工商联负责人和无党派人士代", "detail": "表欢聚一\n堂，共迎佳节。习近平强调，2025年是“十四五”规划收官之年。要坚持稳中求进工作总基调，实施更加积\n极有为的宏观政策，聚精会神抓好高质量发展，推动高水平科技自立自强，保持经济社会发展良好势头，\n圆满完成“十四五”规划目标任务，为“十五五”良好开局打牢基础。各民主党派、工商联和无党派人士要围绕\n中心、服务大局，发挥各自优势，更加广泛地凝聚人心、凝聚共识、凝聚智慧、凝聚力量。"}, {"title": "1月20日，中国有“人造太阳”之称的全超导托卡马克核聚变实验装置（EAST）在安", "detail": "徽合肥创造新世\n界纪录，首次完成1亿摄氏度1000秒“高质量燃烧”，标志我国聚变能源研究实现从基础科学向工程实践的\n重大跨越，对人类加快实现聚变发电具有重要意义。"}, {"title": "2025年1月20日18时11分，我国在酒泉卫星发射中心使用谷神星一号运载火箭，", "detail": "成功将云遥一号\n37~40星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。此次任务还搭载发射了吉天星A-05\n星。此次任务是谷神星一号运载火箭的第17次飞行。"}, {"title": "近日，中共中央、国务院印发了《教育强国建设规划纲要（2024—2035年）》，《", "detail": "纲要》强调坚持\n教育优先发展，全面贯彻党的教育方针，坚定不移走中国特色社会主义教育发展道路，坚持社会主义办学\n方向，全面把握教育的政治属性、人民属性、战略属性，落实立德树人根本任务，为党育人、为国育才，\n全面服务中国式现代化建设，扎根中国大地办教育，加快建设高质量教育体系，培养德智体美劳全面发展\n的社会主义建设者和接班人，加快建设具有强大思政引领力、人才竞争力、科技支撑力、民生保障力、社\n会协同力、国际影响力的中国特色社会主义教育强国，为建设社会主义现代化强国、全面推进中华民族伟\n大复兴提供有力支撑。\n《纲要》提出，要坚持党对教育事业的全面领导，突出促进公平、提高质量，强化战略引领、支撑发\n展，深化改革创新、协同融合，坚持自主自信、胸怀天下。正确处理支撑国家战略和满足民生需求、知识\n学习和全面发展、培养人才和满足社会需要、规范有序和激发活力、扎根中国大地和借鉴国际经验的关系，\n全面构建固本铸魂的思想政治教育体系、公平优质的基础教育体系、自强卓越的高等教育体系、产教融合\n的职业教育体系、泛在可及的终身教育体系、创新牵引的科技支撑体系、素质精良的教师队伍体系、开放\n互鉴的国际合作体系，实现由大到强的系统跃升。"}, {"title": "国家能源局1月20日发布数据显示：2024年，国内油气产量当量首次超过4亿吨，连", "detail": "续8年保持千\n万吨级快速增长势头。"}, {"title": "1月21日从人力资源社会保障部获悉，2024年，全国城镇新增就业1256万人，顺", "detail": "利完成“1200万人\n以上”的全年城镇新增就业目标；城镇调查失业率平均为5.1%，同比下降0.1个百分点。"}, {"title": "1月21日下午，国家主席习近平在北京人民大会堂同俄罗斯总统普京举行视频会晤。", "detail": "习近平指出，\n2024年，我们3次会晤，达成许多重要共识。两国隆重庆祝建交75周年，以永久睦邻友好、全面战略协作、\n互利合作共赢为精神内核的中俄关系不断焕发新的活力。新的一年，我愿同总统先生一道，继续引领中俄\n关系登高望远，以中俄关系的稳定性和坚韧性应对外部环境的不确定性，共同促进两国发展振兴，维护国\n际公平正义。"}, {"title": "当地时间1月20日，北京时间21日凌晨，在美国首都华盛顿国会大厦圆形大厅，特朗普", "detail": "宣誓就任\n美国第47任总统。"}, {"title": "1月21日，国家能源局发布2024年全国电力工业统计数据。", "detail": "截至12月底，全国累计发电装机容量\n8\n(cid:3)\n约33.5亿千瓦，同比增长14.6%。其中，太阳能发电装机容量约8.9亿千瓦，同比增长45.2%；风电装机容\n量约5.2亿千瓦，同比增长18.0%。"}, {"title": "1月22日从文化和旅游部获悉，根据国内旅游抽样调查统计结果，2024年，国内出游", "detail": "人次56.15亿，\n比上年同期增加7.24亿，同比增长14.8%。"}, {"title": "从水利部了解到，2024年我国完成2.3万处农村供水工程建设，提升1.1亿农村人", "detail": "口供水保障水平，\n全国农村自来水普及率达到94%，规模化供水工程覆盖农村人口比例达到65%，千人以上集中供水工程全\n部配备净化消毒设施设备。"}, {"title": "中共中央、国务院近日印发《乡村全面振兴规划（2024—2027年）》。", "detail": "《规划》指出，要坚持以习\n近平新时代中国特色社会主义思想为指导，锚定建设农业强国目标，学习运用“千万工程”经验，健全推动乡\n村全面振兴长效机制，以确保国家粮食安全、确保农村人口不发生规模性返贫致贫为底线，巩固拓展脱贫\n攻坚成果，以提升乡村产业发展水平、提升乡村建设水平、提升乡村治理水平为重点，强化科技和改革双\n轮驱动，强化农民增收举措，扎实推进乡村产业、人才、文化、生态、组织“五个振兴”，加快农业农村现代\n化，推动农业全面升级、农村全面进步、农民全面发展，为全面建设社会主义现代化国家提供坚强支撑。\n主要目标是：到2027年，乡村全面振兴取得实质性进展，农业农村现代化迈上新台阶。到2035年，乡村全\n面振兴取得决定性进展，农业现代化基本实现，农村基本具备现代生活条件。"}, {"title": "2025年1月23日13时15分，我国在太原卫星发射中心使用长征六号改运载火箭，", "detail": "以一箭18星方\n式，成功将千帆极轨06组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。千帆极轨06\n组卫星是“千帆星座”第四批组网卫星。"}, {"title": "中共中央、国务院、中央军委决定，给叶光富同志颁发“二级航天功勋奖章”，授予李聪、", "detail": "李广苏同\n志“英雄航天员”荣誉称号并颁发“三级航天功勋奖章”。2024年4月25日，神舟十八号载人飞船成功发射，\n航天员叶光富、李聪、李广苏驾乘飞船顺利进驻天和核心舱，在轨驻留6个月，先后进行2次出舱活动，\n实施6次载荷货物气闸舱进出舱任务，完成80余项空间站建设升级维护维修任务，开展近百项空间科学实\n验与应用载荷在轨实（试）验，于2024年11月4日安全返回。"}, {"title": "据国家统计局网站消息，初步测算，2024年我国全社会研究与试验发展（R&D）经费", "detail": "投入超过3.6\n万亿元，为36130亿元，比上年增长8.3%；研究与试验发展（R&D）经费投入强度（指研究与试验发展经\n费与国内生产总值之比）达到2.68%，比上年提高0.10个百分点。"}, {"title": "中央组织部组织编写了《习近平总书记关于党的建设的重要思想概论》一书，已由党建读物", "detail": "出版社\n出版，即日起在全国发行。《概论》内容丰富、观点鲜明，论述深刻、逻辑严密，政治性、思想性、系统\n性、指导性强，是广大党员、干部深入学习领会习近平总书记关于党的建设的重要思想的权威辅助读物。"}, {"title": "2024年1月23日23时32分，我国在西昌卫星发射中心使用长征三号乙运载火箭，", "detail": "成功将通信技术\n试验卫星十四号发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。通信技术试验卫星十四号主\n要用于卫星通信、广播电视、数据传输等业务，并开展相关技术试验验证。"}, {"title": "1月22日至24日，习近平在辽宁省考察，给基层干部群众送上党中央的关怀和祝福。", "detail": "习近平强调，\n东北全面振兴，归根到底靠改革开放。抓改革要进一步聚焦问题、突出重点、破解难点，在建设法治政府、\n优化营商环境、坚持和落实“两个毫不动摇”、完善中国特色现代企业制度等方面多下功夫。现在，我们国家\n开放的大门越开越大，各级干部要提高在开放条件下想问题、作决策、抓工作的本领。"}, {"title": "据财政部网站消息，1月24日，财政部公布2024年财政收支情况。", "detail": "2024年，全国一般公共预算收入\n219702亿元，比上年增长1.3%。2024年，全国一般公共预算支出284612亿元，比上年增长3.6%。\n9\n(cid:3)"}, {"title": "生态环境部1月24日公布了2024年1—12月，全国339个地级及以上城市PM2", "detail": ".5平均浓度为29.3\n微克/立方米，同比下降2.7%。全国339个地级及以上城市平均空气质量优良天数比例为87.2%，同比上升"}, {"title": "7个百分点。", "detail": ""}, {"title": "据国家市场监督管理总局所属中国物品编码中心统计，2024年，全国消费品新增216", "detail": "3.9万种，同比\n增长14.1%。截至2024年12月31日，全国消费品总量达21110.6万种，涵盖食品饮料、服装鞋帽、医疗卫\n生、家用电器、文教用品、家居建材等数百个行业的社会生活消费品，涉及企业97.8万家。"}, {"title": "国务院办公厅日前印发《关于推动文化高质量发展的若干经济政策》，其中明确，深化公共", "detail": "文化领\n域财政事权和支出责任划分改革。统筹用好中央对地方文化领域转移支付资金，向农村地区、革命老区、\n民族地区、边疆地区、欠发达地区倾斜，推动城乡文化资源均衡配置、优质文化资源直达基层。\n获取后续更新及更多时政考试资料，请加微信：yumi9938。"}, {"title": "据统计，截至2024年底，全国已建成投运新型储能项目累计装机规模达7376万千瓦", "detail": "/1.68亿千瓦时，\n约为“十三五”末的20倍，较2023年底增长超过130%；平均储能时长2.3小时，较2023年底增加约0.2小时。"}, {"title": "我国“天关”卫星（爱因斯坦探针卫星）观测到一例产生于约125亿光年之外的伽马暴E", "detail": "P240315a，\n这是人类首次探测到宇宙早期爆发现象的软X射线信号，将为开展早期宇宙相关研究开启一扇新窗口。"}, {"title": "1月26日在全国林业和草原工作视频会议上了解到，2024年我国科学开展大规模国土", "detail": "绿化行动，完\n成国土绿化面积超1亿亩，包括造林6669万亩、种草改良4836万亩，其中，治理沙化石漠化土地3683万\n亩。目前我国森林覆盖率超过25%，森林蓄积量超200亿立方米。"}, {"title": "工业和信息化部1月26日发布的2024年通信业统计公报显示，初步核算2024年电", "detail": "信业务收入累计\n完成1.74万亿元，比上年增长3.2%。"}, {"title": "近日，应用于沙戈荒地区的超大功率等级风电机组——“凌风号”在吉林中车松原基地成功", "detail": "下线，这\n是国内首个成功下线的12兆瓦级陆上风电机组。“凌风号”的功率等级可实现11兆瓦—14兆瓦的柔性配置，\n风轮直径可拓展至超过250米。"}, {"title": "市场监管总局已于2024年底建成“全国个体工商户名录”，涵盖符合分型条件的个体工", "detail": "商户共7746.5\n万户，其中“生存型”6438.2万户、“成长型”1004.1万户、“发展型”304.2万户，为每户正在经营的个体工商户“画\n像”。"}, {"title": "中共中央、国务院1月27日上午在人民大会堂举行2025年春节团拜会。", "detail": "习近平在讲话中指出，过\n去一年，我们扎实推动高质量发展，有效落实各项存量政策，加力推出一揽子增量政策，促进经济回暖向\n好。放眼全球，我国仍然是世界经济增长的重要引擎。我们注重各项事业协调并进，社会主义民主法治建\n设、文化建设、社会建设、生态文明建设、国防和军队建设都取得新进步。隆重庆祝新中国成立75周年。\n习近平指出，在中华文化里，蛇是灵性、智慧和生命力的象征，寓意着丰收、吉祥和福瑞。乙巳蛇年，\n希望全国各族人民以蛇行千里的劲头，坚定信心、满怀希望，开拓进取、顽强奋斗，共同书写中国式现代\n化新篇章。"}, {"title": "国家能源局发布数据显示：截至2024年底，全国累计发电装机容量约33.5亿千瓦，", "detail": "同比增长14.6%。\n其中，太阳能发电装机容量约8.9亿千瓦，同比增长45.2%；风电装机容量约5.2亿千瓦，同比增长18.0%。\n我国风电太阳能发电装机首次超过14亿千瓦。"}, {"title": "截至2024年底，我国国内企业有效发明专利已超350万件，占国内有效发明专利总量", "detail": "的73.7%，较\n上年提高2.6个百分点。企业创新活跃的同时，转化运用能力也持续提升。"}, {"title": "近日从国家林草局了解到。", "detail": "2024年，我国持续推进集体林权制度改革和林业产业高质量发展，全国\n10\n(cid:3)\n林业产业总产值达10.17万亿元，同比增长9.6%。"}, {"title": "1月28日晚8点，在“欢乐吉祥、喜气洋洋”的主基调中，中央广播电视总台《2025", "detail": "年春节联欢晚会》\n以“巳巳如意，生生不息”为主题，用满屏新意奉上一道充满欢声笑语的文化大餐，向海内外受众送上乙巳蛇\n年的真挚祝福。"}, {"title": "根据国家电影局统计，2025年春节大年初一票房为18.05亿元，观影人次为351", "detail": "5.12万，创造了新的\n单日票房和观影人次纪录。\n11\n(cid:3)"}]}, {"month": "2025年2月", "year": 2025, "items": [{"title": "2月1日出版的第3期《求是》杂志将发表习近平总书记重要文章《注重家庭，注重家教，", "detail": "注重家风》，\n文章强调，中华民族历来重视家庭。尊老爱幼、妻贤夫安，母慈子孝、兄友弟恭，耕读传家、勤俭持家，\n知书达礼、遵纪守法，家和万事兴等中华民族传统家庭美德，是支撑中华民族生生不息、薪火相传的重要\n精神力量，是家庭文明建设的宝贵精神财富。\n广大家庭都要重言传、重身教，教知识、育品德，身体力行、耳濡目染，帮助孩子扣好人生的第一粒\n扣子，迈好人生的第一个台阶。要在家庭中培育和践行社会主义核心价值观，引导家庭成员特别是下一代\n热爱党、热爱祖国、热爱人民、热爱中华民族。要积极传播中华民族传统美德，传递尊老爱幼、男女平等、\n夫妻和睦、勤俭持家、邻里团结的观念，倡导忠诚、责任、亲情、学习、公益的理念，推动人们在为家庭\n谋幸福、为他人送温暖、为社会作贡献的过程中提高精神境界、培育文明风尚。"}, {"title": "近日从国家知识产权局获悉，我国持续压减知识产权审查周期，发明专利平均审查周期已缩", "detail": "短至15.5\n个月，商标注册平均审查周期稳定在4个月，均达到相同审查制度下国际领先水平。"}, {"title": "2025年2月2日是第29个世界湿地日，今年世界湿地日主题是“保护湿地共筑未来”。", "detail": "国家林草局最\n新数据显示，党的十八大以来，累计实施湿地保护修复项目3700多个，新增和修复湿地100多万公顷，全\n国湿地面积稳定保持在5635万公顷以上。建立各类湿地自然保护地2200多处。"}, {"title": "国务院总理李强日前签署国务院令，公布《古树名木保护条例》，自2025年3月15日", "detail": "起施行。条例\n所称古树，是指树龄100年以上的树木，不包括人工培育、以生产木材为主要目的的商品林中的树木。条例\n所称名木，是指具有重要历史、文化、科学、景观价值或者具有重要纪念意义的树木。《条例》规定，坚\n持保护第一、合理利用、分级管理的原则，构建政府主导、属地负责、社会参与的工作机制。"}, {"title": "中国基金业协会最新数据显示，截至2024年12月底，个人养老金基金销售机构达52", "detail": "家。其中商业\n银行19家，证券公司25家，独立基金销售机构8家。"}, {"title": "白俄罗斯中央选举委员会2月3日正式确认总统选举结果，现任总统卢卡申科以86.82", "detail": "%的得票率当选。"}, {"title": "近日从水利部获悉，我国2025年计划新增水土流失治理面积6.2万平方公里以上，建", "detail": "设400条生态清\n洁小流域，并加强生产建设项目水土保持监管。"}, {"title": "国家统计局发布的最新数据显示，2024年我国全社会研究与试验发展（R&D）经费总", "detail": "量超过3.6万亿\n元，达到36130亿元，比上年增长8.3%，投入总量稳居世界第二位。"}, {"title": "商务部数据显示，2024年，我国全年服务进出口总额75238亿元，同比增长14.", "detail": "4%。其中，出口31755.6\n亿元，增长18.2%；进口43482.4亿元，增长11.8%；服务贸易逆差11726.8亿元，比上年减少314.3亿元。"}, {"title": "近日，从国家林草局了解到，目前我国红树林面积已达3.03万公顷，较本世纪初增加了", "detail": "约0.83万公\n顷，是世界上少数几个红树林面积净增加的国家之一。红树林是生长在热带、亚热带海岸潮间带，由红树\n植物为主体的常绿乔木或灌木组成的湿地木本植物群落，在净化海水、防风消浪、固碳储碳、维护生物多\n样性等方面发挥着重要作用。"}, {"title": "2025年综合运输春运工作专班数据显示：春节假期8天（1月28日至2月4日），全", "detail": "社会跨区域人\n员流动量超23亿人次，比去年同期增长6%。"}, {"title": "国家电影局2月5日发布数据，2025年春节档（1月28日至2月4日）电影票房为9", "detail": "5.10亿元，观影\n人次为1.87亿，创造了新的春节档票房和观影人次纪录。"}, {"title": "国务院总理李强2月5日主持召开国务院第七次全体会议，李强指出，新的一年面对新的形", "detail": "势和任\n务，党中央的大政方针、战略部署已经非常明确，要系统化创造性地抓好落实。既要注重整体把握，综合\n1\n(cid:3)\n平衡好国内和国外、当前和长远、宏观和微观、发展和安全等关系，在多重目标中找到有效路径，也要寻\n求突破突围，找准潜力足、空间大的发展领域，谋划好牵引性强、撬动性强的工作抓手，打造更多能够带\n动全局的突出亮点。"}, {"title": "最新统计核算结果显示，2024年，我国社会物流总费用与GDP的比率为14.1%，", "detail": "比2023年下降0.3\n个百分点，降至2006年正式建立统计以来的最低水平。"}, {"title": "美国总统特朗普2月4日签署行政令，宣布美国退出联合国人权理事会。", "detail": "联合国人权理事会由47个\n成员组成。联大每年改选三分之一左右的理事会成员，成员每届任期三年，可连任一届。"}, {"title": "文化和旅游部2月5日公布2025年春节假期文化和旅游市场情况。", "detail": "经文化和旅游部数据中心测算，\n春节假期8天，全国国内出游5.01亿人次，同比增长5.9%；国内出游总花费6770.02亿元，同比增长7.0%。"}, {"title": "哈尔滨亚冬会开幕式中国体育代表团旗手2月5日揭晓，男子速度滑冰运动员宁忠岩和女子", "detail": "滑雪运\n动员刘梦婷将出任开幕式旗手。"}, {"title": "据网络平台数据，截至2月6日12时28分，电影《哪吒之魔童闹海》（含点映及预售）", "detail": "总票房突\n破57.76亿元，已超越《长津湖》票房成绩，位列中国电影票房总榜榜首。"}, {"title": "中央军委主席习近平日前签署命令，发布新修订的《军队装备科研条例》，自2025年3", "detail": "月1日起施\n行。《条例》共8章49条，适应创新构建新时代武器装备现代化管理体系要求，鲜明立起高质量、高效益、\n低成本、可持续发展新理念，推动构建自主创新、自主研制、自主可控与开放交流相结合的发展新格局，\n加快实现装备科研自立自强。"}, {"title": "当地时间2月5日，阿根廷政府发表声明，宣布阿总统米莱已决定该国退出世界卫生组织。", "detail": ""}, {"title": "2月7日中午，国家主席习近平和夫人彭丽媛在黑龙江省哈尔滨市太阳岛宾馆举行宴会，欢", "detail": "迎来华出\n席哈尔滨第九届亚洲冬季运动会开幕式的国际贵宾。习近平强调，本届亚冬会以“冰雪同梦、亚洲同心”为主\n题，承载着亚洲人民对于和平、发展、友谊的共同愿望和追求。要坚守安宁和睦的共同梦想，为平等有序\n的世界多极化贡献亚洲力量。要坚持繁荣发展的共同追求，为普惠包容的经济全球化注入不竭动力。要实\n现交融相亲的共同心愿，为人类文明发展进步作出更大贡献。"}, {"title": "海关总署党委书记孙梅君2月7日在全国海关工作会议上表示，2024年我国外贸首次突", "detail": "破43万亿元\n大关，同比增长5%，连续第8年保持货物贸易第一大国地位。"}, {"title": "2月7日，位于我国渤海的亿吨级油田渤中26-6油田开发项目顺利投产，标志着全球最", "detail": "大变质岩潜\n山油田正式进入生产阶段，对保障国家能源安全具有重要意义。渤中26-6油田的储层位于埋深超4500米的\n太古界潜山变质岩地层，其潜山基岩以高硬度的花岗岩为主，地层温度高达178摄氏度，高温高强度的极端\n环境给油气钻采作业带来严峻考验。\n获取后续更新及更多时政考试资料，请加微信：yumi9938。"}, {"title": "我国首个商用堆在线辐照生产同位素装置日前在中国核工业集团有限公司秦山核电基地正式", "detail": "投运，\n在此生产的首批镥-177医用同位素也同步出堆，对助力健康中国建设、推动我国核技术应用具有深远意义。"}, {"title": "第九届亚洲冬季运动会开幕式2月7日晚在黑龙江省哈尔滨市举行。", "detail": "国家主席习近平出席开幕式并\n宣布本届亚冬会开幕。本届亚冬会是继北京冬奥会后我国举办的又一重大综合性国际冰雪运动盛会，也是\n继1996年哈尔滨亚冬会和2007年长春亚冬会后，我国第三次举办亚冬会。这同时意味着哈尔滨成为一座“双\n亚冬之城”。本届亚冬会为期8天，共设置6个大项、11个分项和64个小项，冰上赛事在哈尔滨赛区举行，\n雪上赛事在亚布力赛区举行。本届亚冬会以“冰雪同梦，亚洲同心”为口号，秉持“绿色、共享、开放、廉洁”\n的办赛理念和“简约、安全、精彩”的办赛要求。\n2\n(cid:3)"}, {"title": "2月8日上午，习近平在吉林省长春市听取吉林省委和省政府工作汇报，发表了重要讲话。", "detail": "习近平指\n出，高质量发展离不开创新驱动和产业支撑。要守牢实体经济这个根基，统筹推动传统产业转型、优势产\n业壮大和新质生产力培育，构建体现吉林特色的现代化产业体系。习近平指出，保障国家粮食安全，是农\n业大省、粮食大省的政治责任。吉林要以发展现代化大农业为主攻方向，完善强农惠农富农支持制度，统\n筹发展科技农业、绿色农业、质量农业、品牌农业。"}, {"title": "在2月8日结束的第九届亚冬会自由式滑雪女子U型场地技巧决赛中，李方慧以95.25", "detail": "分的成绩夺冠，\n夺得中国代表团本届赛事首枚金牌。"}, {"title": "近日，国家林草局、国家发展改革委、财政部、人力资源社会保障部、自然资源部、金融监", "detail": "管总局\n六部门联合印发《天然林保护修复中长期规划》。《规划》提出，到2035年，天然林保护修复制度体系基\n本健全，天然林面积保持在25.8亿亩左右，质量实现根本好转，天然林生态系统健康稳定、功能完备。"}, {"title": "我国大科学装置——江门中微子实验2月8日开始液体闪烁体灌注，预计今年8月完成灌注", "detail": "并正式\n运行取数。江门中微子实验以测量中微子质量顺序为首要科学目标，并将开展其他多项重大前沿研究，建\n成后将成为国际中微子研究的中心之一。"}, {"title": "据市场监管大数据中心数据显示，截至2024年12月底，全国共有45.17万家智能", "detail": "机器人产业企业，\n注册资本共计64445.57亿元，企业数量较2020年底增长206.73%，较2023年底增长19.39%，呈稳健上扬态\n势。"}, {"title": "国家市场监督管理总局日前发布数据显示：2024年，我国登记在册的企业数量达612", "detail": "2.6万户，比2023\n年底增长5.1%。2024年，企业信用指数上升到160左右，处于较好区间。"}, {"title": "新修订的《中小学生学籍管理办法》近日正式印发。", "detail": "《办法》规定学校应当至少每学期核准一次学\n生学籍，确保人籍一致、学籍变动手续完备、学生基础学籍信息和学籍变动信息准确；严肃、及时处理检\n查中发现的人籍分离、空挂学籍等问题。"}, {"title": "2月8日，民政部官网披露了2024年全国婚姻登记数据。", "detail": "2024年全国结婚登记数为610.6万对，离\n婚登记数为262.1万对。"}, {"title": "南水北调东线北延应急供水工程2月10日启动2024至2025年度调水，计划向黄河", "detail": "以北调水1.51亿\n立方米。统计显示，南水北调东线北延工程近年来已累计向黄河以北调水8.25亿立方米。"}, {"title": "国务院总理李强日前签署国务院令，公布《公共安全视频图像信息系统管理条例》，自20", "detail": "25年4月\n1日起施行。《条例》明确县级以上地方人民政府加强统筹规划，避免重复建设，政府有关部门、经营管理\n单位按照规划、标准建设公共安全视频系统。禁止在民宿、宿舍、更衣室等能够拍摄、窥视、窃听他人隐\n私的区域、部位安装图像采集设备设施。"}, {"title": "波罗的海三国立陶宛、拉脱维亚和爱沙尼亚2月8日至9日断开与俄罗斯控制的电网连接，", "detail": "随后接\n入欧洲电网系统。三国于2004年加入欧盟，2009年开始启动并入欧洲电网项目。2018年，三国同波兰和欧\n盟委员会正式签署协议，以将三国电网与欧洲大陆电网连接，从而脱离连接白俄罗斯、俄罗斯及三国的\n“BRELL能源圈”、摆脱对俄用电依赖。"}, {"title": "2025年2月11日17时30分，我国在文昌航天发射场使用长征八号改运载火箭，成", "detail": "功将卫星互联网\n低轨02组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "商务部、文化和旅游部、国铁集团等9单位近日印发的《关于增开银发旅游列车促进服务消", "detail": "费发展\n的行动计划》2月11日对外公布，行动计划提出，到2027年，构建覆盖全国、线路多样、主题丰富、服务\n全面的银发旅游列车产品体系。\n3\n(cid:3)"}, {"title": "当地时间2月10日，美国总统特朗普签署行政命令，宣布对所有进口至美国的钢铁和铝征", "detail": "收25%关\n税。此外，最新措施还取消对部分贸易伙伴的钢铝免税配额和豁免政策。"}, {"title": "国际奥委会2月11日宣布，首届电竞奥运会将于2027年在沙特阿拉伯利雅得举行。", "detail": ""}, {"title": "中国物流与采购联合会2月11日公布2024年全年物流运行数据。", "detail": "数据显示：2024年，全国物流运\n行总体平稳，社会物流总额360.6万亿元，同比增长5.8%，增速比上年提高0.6个百分点，社会物流总额增\n速稳中有升，社会物流成本稳步下降，物流运行效率有所改善。"}, {"title": "据中国载人航天工程办公室消息，经公开征集评选，近日，中国载人月球探测任务登月服和", "detail": "载人月\n球车名称已经确定，登月服命名为“望宇”，载人月球车命名为“探索”。"}, {"title": "近日，国家税务总局发布的最新数据显示，2024年，现行支持科技创新和制造业发展的", "detail": "主要政策减\n税降费及退税达26293亿元，助力我国新质生产力加速培育、制造业高质量发展。\n获取后续更新及更多时政考试资料，请加微信：yumi9938。"}, {"title": "近日，市场监管总局批准建立大长度基准装置，该基准装置测量范围达80米，测量范围内", "detail": "误差仅为"}, {"title": "45微米，相当于人在1600米之外分辨出头发丝的直径，达到国际领先水平。", "detail": ""}, {"title": "2月13日下午，记者从中国体育代表团获悉，女子自由式滑雪空中技巧运动员徐梦桃将担", "detail": "任哈尔滨\n亚冬会闭幕式中国体育代表团旗手。"}, {"title": "2月13日，据猫眼专业版数据，电影《哪吒之魔童闹海》全球票房（含预售及海外）突破", "detail": "100亿，\n成为中国影史首部票房破100亿电影！"}, {"title": "中共中央统一战线工作部、国家民族事务委员会组织编写的《习近平总书记关于加强和改进", "detail": "民族工\n作的重要思想学习读本》一书，近日由人民出版社、民族出版社联合出版，在全国发行。党的十八大以来，\n以习近平同志为核心的党中央坚持“两个结合”，不断推进马克思主义民族理论中国化时代化，鲜明提出把铸\n牢中华民族共同体意识作为新时代党的民族工作的主线、民族地区各项工作的主线，形成了习近平总书记\n关于加强和改进民族工作的重要思想，指引党的民族工作取得新的历史性成就。"}, {"title": "新版《食品安全国家标准食品添加剂使用标准》（GB2760-2024）于2025年", "detail": "2月8日起正式实施，\n修订了部分食品添加剂品种和/或使用规定\n●删除了落葵红、密蒙黄、酸枣色、2,4-二氯苯氧乙酸、海萝胶、偶氮甲酰胺等经过调查不再具有工\n艺必要性的食品添加剂品种及其使用规定；\n●删除了罐头类食品中防腐剂、食醋中冰乙酸、果蔬汁浆中纳他霉素、蒸馏酒中β-胡萝卜素和双乙酰\n酒石酸单双甘油酯等的使用规定。"}, {"title": "2月13日，国际数据公司（IDC）与浪潮信息联合发布《中国人工智能计算力发展评估", "detail": "报告》。《报\n告》显示，大模型和生成式人工智能推高算力需求，中国智能算力增速高于预期。2024年，中国智能算力\n规模达725.3百亿亿次/秒（EFLOPS），同比增长74.1%，增幅是同期通用算力增幅（20.6%）的3倍以上；\n市场规模为190亿美元，同比增长86.9%。"}, {"title": "2月13日从中国海油获悉，2024年，我国海上钻井总数首次突破1000口大关。", "detail": "海上钻完井具有高风\n险、高成本、高技术的“三高”特点。在2024年实施的海上钻井中，恩平21-4-A1H井创造了海上井深最深、\n水平位移最大的两项“全国之最”。"}, {"title": "第九届哈尔滨亚冬会2月14日晚闭幕，64枚金牌各归其主。", "detail": "中国体育代表团收获32金、27银、26\n铜共计85枚奖牌，位列本届亚冬会金牌榜和奖牌榜首位，创造亚冬会历史参赛最好成绩。"}, {"title": "日前，农业农村部发布关于印发《全国农业科技创新重点领域（2024–2028年）》", "detail": "的通知，关于耕\n4\n(cid:3)\n地质量提升，建立健全耕地保育关键技术体系，加强黑土地保护、退化耕地治理和盐碱地综合改造利用，\n促进耕地数量、质量、生态“三位一体”协同提升，以科技创新支撑实现“藏粮于地”，牢牢守住粮食生产的“命\n根子”。"}, {"title": "国家外汇管理局2月14日发布数据显示，2024年，我国国际收支继续保持基本平衡。", "detail": "其中，经常账\n户顺差4220亿美元，与同期国内生产总值（GDP）之比为2.2%，处于合理均衡区间。"}, {"title": "2月14日晚，第九届亚洲冬季运动会在黑龙江省哈尔滨市闭幕。", "detail": "下一届亚洲冬季运动会将于2029年\n在沙特阿拉伯特鲁吉纳举行，这也是西亚地区首次举办冬季运动的洲际运动会。"}, {"title": "2月15日，国家主席习近平致电第38届非洲联盟峰会，向非洲国家和人民表示热烈祝贺。", "detail": "习近平指\n出，面对当前变乱交织的国际形势，以中国和非洲为代表的“全球南方”卓然壮大。我愿同非洲国家领导人一\n道，推动落实中非携手推进现代化六大主张和“十大伙伴行动”，以更多实实在在的成果造福28亿多中非人\n民。"}, {"title": "2月15日，在江苏启东长江水域，我国首艘、自主研发全电驱拼装式深水环保绞吸挖泥船", "detail": "“浚澜”轮\n下水。船体总长67米，宽11.95米，最大挖深25米，总装机功率4520千瓦，铰刀功率600千瓦，标准疏浚\n产量每小时2200立方米，是目前国内环保型拼装式绞吸疏浚船舶中综合性能最优的船舶装备。"}, {"title": "李强2月15日在黑龙江调研。", "detail": "他强调，要深入贯彻习近平总书记关于发展冰雪运动和冰雪经济的重\n要指示精神，着眼于满足人民美好生活需要，用好特色优势资源，丰富优质产品供给，激发冰雪经济活力，\n打造服务消费新亮点和经济新增长点，持续增进民生福祉。"}, {"title": "2月16日出版的第4期《求是》杂志将发表习近平的重要文章《健全全面从严治党体系》。", "detail": "文章指\n出，党的十八大以来，我们坚定不移推进全面从严治党，取得一系列理论创新、实践创新、制度创新成果，\n构建起全面从严治党体系，开辟了百年大党自我革命新境界。\n文章强调，新时代党的建设是以党的政治建设为统领、党的各项建设同向发力综合发力的系统工程，\n必须以党中央关于党的建设的重要思想、关于党的自我革命的重要思想为根本遵循，坚持和加强党的全面\n领导和党中央集中统一领导，贯彻落实新时代党的建设总要求，用系统思维、科学方法推进管党治党内容\n全涵盖、对象全覆盖、责任全链条、制度全贯通，进一步健全要素齐全、功能完备、科学规范、运行高效\n的全面从严治党体系。"}, {"title": "复旦大学高分子科学系、纤维材料与器件研究院彭慧胜、高悦团队的最新研究打破了传统设", "detail": "计规则，\n对电池进行“精准治疗”，帮助其突破了现有寿命极限，未来应用前景广泛。他们创新设计出锂载体分子，这\n种分子可像药物一样，以“打一针”的方式注入废旧或衰减的锂电池中，精准补充损失的锂离子，实现容量恢\n复，从而大幅延长电池的寿命。"}, {"title": "当地时间2月15日，经第38届非洲联盟峰会首脑会议选举，马哈茂德·阿里·优素福当", "detail": "选新一届\n非盟委员会主席。\n获取后续更新及更多时政考试资料，请加微信：yumi9938。"}, {"title": "习近平2月17日上午在京出席民营企业座谈会并发表重要讲话。", "detail": "他强调，新时代新征程民营经济发\n展前景广阔、大有可为，广大民营企业和民营企业家大显身手正当其时。要统一思想、坚定信心，促进民\n营经济健康发展、高质量发展。希望广大民营企业和民营企业家胸怀报国志、一心谋发展、守法善经营、\n先富促共富，为推进中国式现代化作出新的更大的贡献。\n习近平强调，企业是经营主体，企业发展内生动力是第一位的。广大民营企业和民营企业家要坚定不\n移走高质量发展之路，坚守主业、做强实业，加强自主创新，转变发展方式，不断提高企业质量、效益和\n5\n(cid:3)\n核心竞争力，努力为推动科技创新、培育新质生产力、建设现代化产业体系、全面推进乡村振兴、促进区\n域协调发展、保障和改善民生等多作贡献。"}, {"title": "市场监管总局和国家档案局近日联合制定出台《经营主体登记档案管理办法》，将于202", "detail": "5年3月20\n日正式施行。办法明确经营主体存续期间，登记档案应当持续保存，经营主体注销后，登记档案保管期限\n一般为20年，登记机关应当定期对保管期限届满的登记档案的保存价值进行鉴定，决定予以销毁或者移交\n给同级国家综合档案馆永久保存。"}, {"title": "中国电动汽车充电基础设施促进联盟2月17日发布的最新数据显示，截止到2025年1", "detail": "月底，全国充\n电基础设施累计数量为1321.3万台，同比上升49.1%。"}, {"title": "近日，西安市发布《网约货车运营服务规范》，这是全国首个网约货车运营服务地方标准，", "detail": "填补了\n网约货车行业规范空白。《规范》于2025年2月14日起正式实施。"}, {"title": "《以文明交流互鉴推动人类文明发展进步》智库报告2月18日在东京发布。", "detail": "报告认为，中国倡导平\n等、互鉴、对话、包容的文明观，强调以文明交流超越文明隔阂、以文明互鉴超越文明冲突、以文明包容\n超越文明优越，为破解人类文明发展困境、促进世界文明多元发展提供了更多选择。"}, {"title": "目前，已基本摸清资源底数，构建了智慧精准的保护管理模式，全国现有古树名木508.", "detail": "19万株，均\n录入数据库，初步实现精准保护管理。"}, {"title": "工业和信息化部等八部门近日联合印发《新型储能制造业高质量发展行动方案》，提出到2", "detail": "027年，\n我国新型储能制造业全链条国际竞争优势凸显，优势企业梯队进一步壮大，产业创新力和综合竞争力显著\n提升，实现高端化、智能化、绿色化发展。"}, {"title": "近日，由中国科学院空天信息创新研究院研制的我国首套直升机航空大地电磁探测系统，顺", "detail": "利完成\n5000米高寒高海拔、复杂地形地貌地区的地质勘查任务，为国家重大铁路建设工程的设计与施工提供了重\n要支撑。"}, {"title": "世界桩架最高、吊桩能力最大、施打桩长最长、抗风浪能力最强的打桩船“二航长青”轮2", "detail": "月17日从\n江苏南通启东启航，标志着我国水工建设领域又一重器正式入列。"}, {"title": "2月19日，“中国社会科学院考古学论坛·2024年中国考古新发现”揭晓。", "detail": "吉林和龙市大洞旧石器时\n代遗址、浙江仙居县下汤新石器时代遗址、甘肃临洮县寺洼遗址马家窑文化聚落、陕西宝鸡市周原遗址、\n安徽淮南市武王墩战国晚期一号墓、江西景德镇市元明清制瓷业遗址群6个项目入选。"}, {"title": "《2025年稳外资行动方案》2月19日对外发布。", "detail": "方案提出，扩大电信、医疗、教育等领域开放试点。\n支持试点地区抓好增值电信、生物技术、外商独资医院领域开放试点政策宣贯落实，对相关领域外商洽谈\n项目开展“专班式”跟踪服务，及时协调解决问题，推动项目尽早落地。"}, {"title": "2月18—19日，水利部在安徽省六安市召开农村水利水电工作会议，会议指出，202", "detail": "4年农村水利水\n电高质量发展成效明显，农村供水“3+1”标准化建设和管护模式全面推行，农村自来水普及率达到94%，规\n模化供水工程覆盖农村人口比例达到65%。"}, {"title": "巴西矿业和能源部长亚历山大·西尔韦拉当地时间2月18日宣布，巴西加入由石油输出国", "detail": "组织（欧\n佩克）成员国和非欧佩克产油国组成的“欧佩克+”。“欧佩克+”由12个主要欧佩克成员国以及10个主要非欧\n佩克产油国组成，这些国家共同合作调节石油生产和定价。"}, {"title": "中国石油集团2月20日宣布，我国首口超万米科探井——深地塔科1井日前在地下109", "detail": "10米胜利完\n钻，成为亚洲第一、世界第二垂直深度井。这是我国在“深地”领域取得的重大突破。"}, {"title": "2月20日，中国行星探测工程天问二号任务探测器运抵西昌卫星发射中心。", "detail": "天问二号任务将通过一\n6\n(cid:3)\n次发射，实施小行星2016HO3伴飞、取样、返回和主带彗星311P伴飞探测等多项任务。"}, {"title": "2月20日，国务院以“坚持促消费和惠民生相结合，大力提振消费扩大国内需求”为主题", "detail": "，进行第十\n二次专题学习。李强在听取讲座和交流发言后指出，内部可循环、内需为主导，是大国经济的独有优势。\n提振消费既是当前扩内需、稳增长的重要抓手，也是中长期转变发展方式的重大举措。要把消费放在更加\n突出的位置，更多依靠提振消费扩大国内需求、畅通经济循环、拉动经济增长。"}, {"title": "市场监管总局、国家发展改革委、工业和信息化部、商务部、文化和旅游部五部门近日印发", "detail": "《优化\n消费环境三年行动方案（2025—2027年）》，行动方案提出，到2027年，消费供给提质、消费秩序优化、\n消费维权提效、消费环境共治、消费环境引领等五大行动深入开展，供给质量不高、市场秩序失范、维权\n效能不足等问题得到系统治理，商品、服务质量显著提高，消费风险明显降低，消费纠纷源头治理效果显\n著，经营者诚信意识普遍增强，消费便利度、舒适度、满意度大幅提升，全国消费环境明显优化。"}, {"title": "《2025年全球软实力指数》2月20日在英国伦敦发布，中国的软实力排名从去年的第", "detail": "三上升至第二。\n美国继续位列第一，英国、日本和德国分列第三至第五名。"}, {"title": "我国海上首个规模化特超稠油热采开发油田——旅大5-2北油田Ⅱ期开发项目2月21日", "detail": "投产。旅大\n5-2北油田是我国海上首个规模化特超稠油热采开发油田，I期项目于2022年投产。旅大5-2北油田Ⅱ期开\n发项目位于渤海中部海域，平均水深约30米。\n获取后续更新及更多时政考试资料，请加微信：yumi9938。"}, {"title": "2月21日，米兰-科尔蒂纳丹佩佐冬奥组委发布了2026年冬奥会主题口号——IT'", "detail": "syourvibe，这句口\n号被译为意韵由你。米兰-科尔蒂纳丹佩佐冬奥会将于2026年2月6日至22日举行，冬残奥会将于3月6\n日至15日举行。"}, {"title": "2月21日，从中航工业了解到，我国自主研制的电动型载人飞艇AS700D在湖北完成", "detail": "了首次科研飞\n行试验，标志着我国低空经济领域的绿色航空新装备取得重大突破。AS700D是我国自主研制的全电动力飞\n艇，最大设计飞行速度每小时80千米，最大飞行高度3100米、含驾驶员最大载客量10人。"}, {"title": "中央军委主席习近平日前签署命令，发布新修订的《中国人民解放军内务条令》、《中国人", "detail": "民解放\n军纪律条令》、《中国人民解放军队列条令》（统称共同条令），自2025年4月1日起施行。新修订的共\n同条令，以习近平新时代中国特色社会主义思想为指导，深入贯彻习近平强军思想，深入贯彻新时代军事\n战略方针，着眼实现党在新时代的强军目标、把人民军队全面建成世界一流军队，聚焦备战打仗，回应部\n队关切，创新完善军队内务建设、纪律维护、队列生活各项制度，是新时代军队正规化建设的基本法规和\n全体军人共同遵守的行为准则。"}, {"title": "2月22日，为期40天的春运正式落下帷幕。", "detail": "根据专班数据，预计春运40天（2025年1月14日至2\n月22日），全社会跨区域人员流动量为90.25亿人次。"}, {"title": "2月22日，2025全球开发者先锋大会开幕式上海徐汇区举办，大会以“模塑全球无限", "detail": "可能”为主题，\n吸引开发者相聚申城，共探人工智能前沿发展。"}, {"title": "2月21日，国务院常务会议审议通过《健全新能源汽车动力电池回收利用体系行动方案》。", "detail": "会议指\n出，当前我国新能源汽车动力电池已进入规模化退役阶段，全面提升动力电池回收利用能力水平尤为重要。\n要强化全链条管理，着力打通堵点卡点，构建规范、安全、高效的回收利用体系，运用数字化技术加强动\n力电池全生命周期流向监测，实现生产、销售、拆解、利用全程可追溯。要用法治化手段规范回收利用，\n制定完善相关行政法规，加强监督管理。要加快制定修订动力电池绿色设计、产品碳足迹核算等相关标准，\n以标准引领带动回收利用。\n7\n(cid:3)"}, {"title": "在“全球深渊深潜探索计划”支持下，中国与新西兰联合科考队2月21日再次启航，进行", "detail": "两国载人深\n潜联合科考第二航次第二航段的项目，继续完成人类对普伊斯哥海沟的首次科考。第二航段开启后，搭载“奋\n斗者”号全海深载人潜水器的“探索一号”科考船再次驶入新西兰海域。"}, {"title": "2025年2月22日20时11分，我国在西昌卫星发射中心使用长征三号乙运载火箭，", "detail": "成功将中星10R\n卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。此次任务是长征系列运载火箭的第560\n次飞行。"}, {"title": "2月23日，2025年中央一号文件发布，这是党的十八大以来第13个指导“三农”工", "detail": "作的中央一号文件，\n文件题为《中共中央国务院关于进一步深化农村改革扎实推进乡村全面振兴的意见》，全文共六个部分。\n文化提出，做好2025年及今后一个时期“三农”工作，要坚持和加强党对“三农”工作的全面领导，完整准确\n全面贯彻新发展理念，坚持稳中求进工作总基调，坚持农业农村优先发展，坚持城乡融合发展，坚持守正\n创新，锚定推进乡村全面振兴、建设农业强国目标，以改革开放和科技创新为动力，巩固和完善农村基本\n经营制度，深入学习运用“千万工程”经验，确保国家粮食安全，确保不发生规模性返贫致贫，提升乡村产业\n发展水平、乡村建设水平、乡村治理水平，千方百计推动农业增效益、农村增活力、农民增收入，为推进\n中国式现代化提供基础支撑。"}, {"title": "中国人民银行近日召开的2025年宏观审慎工作会议透露，截至2024年末，人民币位", "detail": "列全球第四位支\n付货币、第三位贸易融资货币，人民币国际化水平稳步提升。"}, {"title": "2月23日，我国自主研发的第四代海洋工程安装船“志高号”和“志远号”在江苏南通顺", "detail": "利竣工。这两\n艘船的主要任务是将风机，也就是我们常说的“大风车”运送至深远海，并进行安装等施工作业。这两艘第四\n代海洋工程安装船的制造完工，对推动深远海风电规模化开发、加速能源绿色低碳转型有着重要意义。"}, {"title": "截至2025年2月24日，南水北调中线工程累计调水突破700亿立方米，惠及河南、", "detail": "河北、天津、北\n京近1.14亿人，为沿线26座大中城市200多个县（市、区）经济社会发展提供有力的水资源支撑。"}, {"title": "2月24日下午，国家主席习近平应约同俄罗斯总统普京通电话。", "detail": "习近平指出，中国春节前夕我同总\n统先生视频会晤，对全年中俄关系发展作出规划引领，就一系列重大国际和地区问题加强协调。两国各部\n门正按照我们达成的共识，稳步推进各领域合作，包括开展纪念中国人民抗日战争胜利80周年和世界反法\n西斯战争胜利80周年活动。历史和现实昭示我们，中俄是搬不走的好邻居，是患难与共、相互支持、共同\n发展的真朋友。\n获取后续更新及更多时政考试资料，请加微信：yumi9938。"}, {"title": "自然资源部2月24日发布《2024年中国海洋经济统计公报》。", "detail": "《公报》显示，2024年我国海洋经济\n呈现强劲发展势头，海洋经济总量再上新台阶，首次突破10万亿，达到105438亿元，比上年增长5.9%，\n拉动国民经济增长0.4个百分点。"}, {"title": "近日，北京量子信息科学研究院与清华大学、北方工业大学相关团队合作，提出单向量子直", "detail": "接通信\n理论，并成功研制出实用化系统，创造了在104.8公里标准光纤通信实验测试中连续168小时、速率为2.38kbps\n的稳定传输世界纪录，标志着量子直接通信从理论构想成功迈向实际应用阶段。"}, {"title": "2025年中央一号文件明确，制定帮扶项目资产管理办法，健全资产形成、确权移交、管", "detail": "护运营、收\n益分配等全程监管制度，推动经营性资产保值增效、公益性资产持续发挥作用。"}, {"title": "2月24日，大连市长海跨海大桥项目启动仪式暨全市一季度重点项目开工动员大会在普兰", "detail": "店区皮口\n街道长海大桥登陆点举行。大连市长海跨海大桥项目是国道G507的重要组成部分，是我国在建投资规模最\n大的陆岛公路项目，也是东北里程最长的跨海大桥项目，项目全长25.5公里，其中陆域段6.5公里，海域段\n8\n(cid:3)\n19公里，计划2029年建成通车。"}, {"title": "2月25日，从中船集团获悉，我国自主研制的全球最大功率甲醇双燃料船用发动机在上海", "detail": "正式发布，\n一起去看一看这颗最新的船舶“心脏”。该甲醇双燃料发动机拥有完全自主知识产权，将工业酒精甲醇作为燃\n料，设计最大功率可达64500千瓦，重量达到1953吨，被称为船舶“心脏”中的巨无霸。"}, {"title": "自然资源部等部门发布《关于推动海洋能规模化利用的指导意见》。", "detail": "力争到2030年，海洋能装机规\n模达到40万千瓦，建成一批海岛多能互补电力系统和海洋能规模化示范工程，海洋能应用场景不断拓展丰\n富，形成系列高效、稳定、经济的海洋能技术装备产品。海洋能是重要的绿色可再生能源，包括潮汐能（含\n潮差能和潮流能）、波浪能、温差能、盐差能等。"}, {"title": "日前，中共中央、国务院印发《国家突发事件总体应急预案》。", "detail": "《国家突发事件总体应急预案》要\n求，坚持以习近平新时代中国特色社会主义思想为指导，坚持和加强党的全面领导，坚持人民至上、生命\n至上，坚持底线思维、极限思维，坚持预防为主、预防与应急相结合，全面贯彻总体国家安全观，统筹发\n展和安全，建立健全统一指挥、专常兼备、反应灵敏、上下联动的应急管理体制和综合协调、分类管理、\n分级负责、属地管理为主的工作体系，完善应急预案体系，压实各方责任，完善大安全大应急框架下应急\n指挥机制，深入推进应急管理体系和能力现代化。"}, {"title": "从2月25日在浙江杭州召开的全国中小学校园食品安全和膳食经费管理现场推进会上获悉", "detail": "，自2024\n年“校园餐”专项整治开展以来，全国各地共投入103亿元改善学校食堂，“互联网+明厨亮灶”覆盖率已达到\n98.5%。"}, {"title": "2月26日，工业和信息化部举行2024年国家高新区发展情况新闻发布会，介绍202", "detail": "4年国家高新区\n发展情况。2024年，国家高新区园区生产总值（GDP）19.3万亿元，同比名义增长7.6%；其中工业增加值\n约9.8万亿元，同比名义增长5.8%。\n获取后续更新及更多时政考试资料，请加微信：yumi9938。"}, {"title": "近日，中央政治局委员、书记处书记等向党中央和习近平总书记述职，习近平强调今年是“", "detail": "十四五”\n规划收官之年，也是进一步全面深化改革的重要一年，改革发展稳定任务繁重。要增强政治能力，沉着应\n对国内外形势变化带来的挑战，坚持稳中求进工作总基调，完整准确全面贯彻新发展理念，加快构建新发\n展格局，扎实推动高质量发展，进一步全面深化改革，扩大高水平对外开放，推动经济持续回升向好，稳\n步提高人民生活水平，确保社会大局稳定。"}, {"title": "联合国人权理事会第58届会议2月24日举行人权主流化问题年度高级别主题会议，纪念", "detail": "1995年举\n行的第四次世界妇女大会通过《北京宣言》和《行动纲领》30周年。中国首位进入太空的女航天员刘洋作\n为世界杰出妇女代表以视频方式做主旨发言，介绍新时代中国妇女事业高质量发展理念和成就。"}, {"title": "2025年2月27日15时08分，我国在酒泉卫星发射中心使用长征二号丙运载火箭，", "detail": "成功将四维高\n景一号03、04星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "国家能源局2月27日发布了《2025年能源工作指导意见》，今年，全国发电总装机达", "detail": "到36亿千瓦\n以上，新增新能源发电装机规模2亿千瓦以上。"}, {"title": "中共中央办公厅印发了《全国党员教育培训工作规划（2024－2028年）》，《规划", "detail": "》提出，深入落\n实新时代党的建设总要求和新时代党的组织路线，以用党的创新理论武装全党为首要政治任务，以增强党\n性、提高素质、发挥作用为重点，坚持政治引领、分类指导、守正创新、服务大局，教育引导全体党员深\n刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，开拓进取、干事创\n业，为以中国式现代化全面推进强国建设、民族复兴伟业提供思想政治保证和能力支撑。\n9\n(cid:3)\n《规划》要求，党员5年内参加各类集中学习培训累计不少于20天或160学时。基层党组织书记5年\n内参加各类集中学习培训累计不少于35天或280学时，其中每年参加县级以上党委举办的脱产培训累计一\n般不少于5天或40学时。党的创新理论教育学时应占总学时的50%以上。"}, {"title": "农业农村部近日印发的《促进再生稻发展重点工作导引（2025—2030年）》指出，", "detail": "力争到2030年\n全国再生稻面积新增1000万亩左右，进一步增强我国水稻生产保障能力。\n10\n(cid:3)"}]}, {"month": "2025年3月", "year": 2025, "items": [{"title": "2月28日，我国自主研制的大型水陆两栖飞机AG600在陕西蒲城圆满完成了取证前所", "detail": "有试飞科目，\n向取得型号合格证的目标又迈出关键一步。AG600飞机与运-20、C919并称为国产大飞机三兄弟。这型飞机\n是我国为了满足森林灭火和水上救援的迫切需要，自主研制的大型特种用途民用飞机，是国家应急救援体\n系和自然灾害防治体系建设急需的重大航空装备。"}, {"title": "中国和巴基斯坦2月28日签署合作协议选拔训练航天员，外籍航天员将在未来几年内进入", "detail": "中国空间\n站执行短期飞行任务。这次协议的签署，标志着中国政府将首次为外国选拔训练航天员，中国空间站将迎\n来首位外籍航天员造访。"}, {"title": "2月28日，“十四五”国家重大科技基础设施——冷泉生态系统研究装置在广州南沙正式", "detail": "开工建设。该\n装置总耗资26.6亿元，由水面保障母船、海底实验室、保真模拟系统三大部分组成，计划用5年时间建设。\n其中，海底实验室长33米，内部由5个耐压球体串联而成，体积相当于3个中国空间站的大小，将是国际\n首个2000米级的坐底式深海载人驻留实验室。"}, {"title": "国家统计局2月28日发布《2024年国民经济和社会发展统计公报》。", "detail": "经初步核算，2024年，我国国\n内生产总值达1349084亿元，比上年增长5.0%，经济社会发展主要目标任务顺利完成。2024年，我国粮食\n总产量达14130亿斤，迈上新台阶。"}, {"title": "2月28日上午，中国贸促会举行2月例行新闻发布会。", "detail": "会上正式发布2025年日本大阪世博会中国馆\n标志（LOGO）和吉祥物。2025年日本大阪世博会将于4月13日至10月13日在日本大阪举行，主题为“构\n想焕发生机的未来社会”。中国馆是大阪世博会用地面积最大的外国自建馆之一，以“共同构建人与自然生命\n共同体—绿色发展的未来社会”为主题。"}, {"title": "中共中央政治局2月28日上午就建设更高水平平安中国进行第十九次集体学习。", "detail": "习近平在主持学习\n时强调，建设更高水平平安中国，事关事业兴旺发达、事关人民美好生活、事关国家长治久安。要坚定不\n移贯彻总体国家安全观，在国家更加安全、社会更加有序、治理更加有效、人民更加满意上持续用力，把\n平安中国建设推向更高水平。\n习近平指出，平安中国建设为了人民，也依靠人民。要不断增进民生福祉，扎实推进共同富裕，切实\n维护人民群众合法权益，维护社会公平正义。要完善社会治理体系、健全社会工作体制机制，建设人人有\n责、人人尽责、人人享有的社会治理共同体。要培育自尊自信、理性平和、积极向上的社会心态，弘扬锐\n意进取、甘于奉献、崇尚法治、文明礼让的时代新风。"}, {"title": "国家统计局2月28日发布《2024年国民经济和社会发展统计公报》截止到2024年", "detail": "年末全国人口140828。\n万人，比上年末减少139万人，其中城镇常住人口94350万人。全年全国居民人均可支配收入41314元，比\n上年增长5.3%，扣除价格因素，实际增长5.1%。全年全国居民人均消费支出28227元，比上年增长5.3%，\n扣除价格因素，实际增长5.1%。"}, {"title": "3月1日，我国在秦岭站建设的首个规模化新能源系统正式交付使用。", "detail": "这是我国第一次在南极极端环\n境下，能够运行以新能源为主体的规模化的绿色能源系统。"}, {"title": "3月1日出版的第5期《求是》杂志将发表习近平的重要文章《经济工作必须统筹好几对重", "detail": "要关系》。\n文章指出，分析形势要坚持“两点论”，既把成绩讲够，也把问题说透。当前，外部环境变化带来的不利影响\n加深，我国经济运行仍面临不少困难和挑战。同时必须看到，我国经济基础稳、优势多、韧性强、潜能大，\n长期向好的支撑条件和基本趋势没有变。\n文章指出，经济工作千头万绪，必须统筹好几对重要关系。一是必须统筹好有效市场和有为政府的关\n1\n(cid:3)\n系，形成既“放得活”又“管得住”的经济秩序。二是必须统筹好总供给和总需求的关系，畅通国民经济循环。\n三是必须统筹好培育新动能和更新旧动能的关系，因地制宜发展新质生产力。四是必须统筹好做优增量和\n盘活存量的关系，全面提高资源配置效率。五是必须统筹好提升质量和做大总量的关系，夯实中国式现代\n化的物质基础。"}, {"title": "2025年3月1日是东江—深圳供水工程（简称“东深供水工程”）正式通水暨广东对香", "detail": "港供水60周年\n的日子。60年来，该工程累计供水达671亿立方米，其中对香港供水达300亿立方米，占香港淡水总用量\n近八成。"}, {"title": "中共中央党史和文献研究院编辑的《习近平经济文选》第一卷，近日由中央文献出版社出版", "detail": "，在全\n国发行。党的十八大以来，面对严峻复杂的国际环境和艰巨繁重的国内改革发展稳定任务，以习近平同志\n为核心的党中央坚持观大势、谋全局、干实事，全面加强党对经济工作的战略谋划和统一领导，不断深化\n对经济工作的规律性认识，提出一系列新理念新思想新战略，引领我国经济发展取得历史性成就、发生历\n史性变革，形成了习近平经济思想。习近平经济思想是习近平新时代中国特色社会主义思想的重要组成部\n分，是对新时代经济发展实践经验的系统理论概括，是中国共产党不懈探索社会主义经济发展道路形成的\n宝贵思想结晶，开拓了中国特色社会主义政治经济学新境界，为丰富发展马克思主义政治经济学作出了重\n要原创性贡献，为推动我国经济高质量发展、科学应对重大风险挑战、全面建设社会主义现代化国家提供\n了锐利思想武器。"}, {"title": "北京大学常林研究团队与中国科学院空天信息创新研究院合作，成功开发出世界首款光子时", "detail": "钟芯片，\n可将芯片上的时间调控速度提升100倍，从而极大提升未来智能计算、6G通信、空天遥感等一系列现实应\n用的性能。"}, {"title": "当地时间3月1日，美国总统特朗普发布行政命令，将英语指定为美国官方语言。", "detail": "此前，美国没有\n在联邦层面指定任何官方语言。几十年来，美国国会议员一直提出立法，将英语指定为美国的官方语言。"}, {"title": "3月1日，执行中国第41次南极考察任务的“雪龙2”号大洋队完成了本航次的大洋调查", "detail": "任务。“雪龙\n2”号是中国第一艘自主建造的极地科学考察破冰船。中国第41次南极考察由自然资源部组织，依托“雪龙”\n号、“雪龙2”号和各考察站开展一系列综合调查和科学研究。"}, {"title": "3月1日，政府间气候变化专门委员会(IPCC)第62次会议在杭州闭幕。", "detail": "这是IPCC全会第一次在中国\n召开，来自130余个国家的IPCC成员国政府代表、有关观察员组织和国际组织代表参会。"}, {"title": "3月3日从中国载人航天工程办公室获悉，瞄准2030年前实现中国人首次登陆月球的目", "detail": "标，我国载\n人月球探测工程登月阶段任务各项研制建设工作按计划稳步推进。2025年，中国载人航天工程将扎实推进\n空间站应用与发展和载人月球探测两大任务，为推动科技强国、航天强国建设作出更大贡献。"}, {"title": "3月3日从中国载人航天工程办公室了解到，我国2025年将发射神舟二十号、神舟二十", "detail": "一号载人飞\n船和一艘货运飞船，执行二次载人飞行任务的航天员乘组已经选定，正在开展相关训练。二次载人飞行任\n务期间，主要任务是实施航天员出舱活动和货物气闸舱出舱任务，继续开展空间科学实验和技术试验，开\n展平台管理工作、航天员保障相关工作以及科普教育等重要活动。"}, {"title": "中国石化3月3日宣布，经自然资源部评审认定，旗下新兴、溱潼油田均为典型的陆相断陷", "detail": "盆地页\n岩油，新增探明地质储量1.8亿吨。这标志着我国东部陆相断陷盆地两个页岩油田诞生，对我国陆相页岩油\n资源高效勘探开发部署意义重大。"}, {"title": "在近日举行的中国气象局新闻发布会上，《中国气候公报（2024年）》正式发布。", "detail": "《公报》指出，\n2024年，在全球气候变暖背景下，全国平均气温10.9摄氏度，为1951年以来历史最高，全国平均降水量为\n2\n(cid:3)"}, {"title": "7毫米，比常年偏多9.0%。", "detail": ""}, {"title": "3月3日，由中国科学技术大学科研团队联合国内多家科研机构研制的105比特超导量子", "detail": "计算原型机\n“祖冲之三号”正式对外发布。我国继超导量子计算原型机“祖冲之二号”之后，再一次打破超导体系量子计算\n优越性纪录。"}, {"title": "国务院新闻办公室3月4日发布《中国的芬太尼类物质管控》白皮书。", "detail": "白皮书指出，中国加强国际\n禁毒合作，务实开展对话交流、联合侦查和经验分享，推动建立平等互信、合作共赢的合作关系，与包括\n美国在内的有关国家在应对芬太尼类物质及其前体问题方面深入开展合作并取得明显成效。\n中国积极应对芬太尼类物质问题的新挑战，综合采取增加列管品种、强化日常监管、加大查缉力度、\n创新管控手段等措施，最大限度防范芬太尼类物质发生滥用，最大限度打击整治芬太尼类物质违法犯罪活\n动。获取后续更新及更多考试资料，请加微信：YM188357"}, {"title": "中国人民政治协商会议第十四届全国委员会第三次会议3月4日下午在人民大会堂开幕。", "detail": "王沪宁代\n表政协第十四届全国委员会常务委员会，向大会报告工作。王沪宁表示，要坚持中国共产党对人民政协的\n全面领导，持续深化党的创新理论武装，强化思想政治引领、广泛凝聚共识，紧扣推进中国式现代化议政\n建言，健全人民政协协商民主机制，坚定必胜信心，汇聚奋进力量，推动新时代新征程人民政协工作迈上\n新台阶，不断夯实团结奋斗的共同思想政治基础，为中国式现代化广泛凝聚人心、凝聚共识、凝聚智慧、\n凝聚力量。\n全国政协副主席蒋作君代表政协第十四届全国委员会常务委员会，向大会报告政协十四届二次会议以\n来的提案工作情况。全国政协十四届二次会议以来，共提出提案6019件，经审查立案5091件，99.9%的提\n案已经办复。"}, {"title": "3月5日，第十四届全国人民代表大会第三次会议在北京人民大会堂开幕。", "detail": "十四届全国人大三次会议\n应出席代表2929人。5日上午的会议，出席2880人，缺席49人，出席人数符合法定人数。根据会议议程，\n国务院总理李强代表国务院向大会作政府工作报告。报告共分三个部分：一、2024年工作回顾；二、2025\n年经济社会发展总体要求和政策取向；三、2025年政府工作任务。\n李强在报告中指出，今年是“十四五”规划收官之年。今年发展主要预期目标是：国内生产总值增长5%\n左右；城镇调查失业率5.5%左右，城镇新增就业1200万人以上；居民消费价格涨幅2%左右；居民收入增\n长和经济增长同步；国际收支保持基本平衡；粮食产量1.4万亿斤左右；单位国内生产总值能耗降低3%左\n右，生态环境质量持续改善。"}, {"title": "3月5日下午，习近平参加他所在的十四届全国人大三次会议江苏代表团审议。", "detail": "习近平指出，科技创\n新和产业创新，是发展新质生产力的基本路径。抓科技创新，要着眼建设现代化产业体系，坚持教育、科\n技、人才一起抓，既多出科技成果，又把科技成果转化为实实在在的生产力。抓产业创新，要守牢实体经\n济这个根基，坚持推动传统产业改造升级和开辟战略性新兴产业、未来产业新赛道并重。"}, {"title": "埃及总统塞西3月4日晚宣布，当天在埃及新行政首都召开的阿拉伯国家紧急峰会通过了埃", "detail": "及提出\n的加沙重建计划，同意设立独立委员会暂管巴勒斯坦的加沙地带。"}, {"title": "根据3月5日公布的2025年中央和地方财政预算草案报告，2025年我国国防支出为", "detail": "17846.65亿元，\n增长7.2%。这是中国国防费自2023年以来增幅连续三年持平，均为7.2%。"}, {"title": "3月6日从市场监管总局获悉，截至2025年1月底，我国民营企业数量5670.7万", "detail": "户，是2012年民营\n企业数量的5.2倍。国家高新技术企业中，民营企业从2012年的2.8万家增长至42万多家，占比由62.4%\n扩大至92%以上。\n3\n(cid:3)"}, {"title": "日前，国务院办公厅印发《关于做好金融“五篇大文章”的指导意见》，提出相关意见，《", "detail": "指导意\n见》明确金融“五篇大文章”重点领域和主要着力点。科技金融加强对国家重大科技任务和科技型中小企业的\n金融支持，着力投早、投小、投长期、投硬科技。绿色金融坚持“先立后破”，统筹对绿色发展和低碳转型的\n支持。普惠金融完善多层次、广覆盖、可持续的体系，优化中小微企业、民营企业、乡村振兴、社会民生\n等普惠重点领域产品服务供给。养老金融强化银发经济金融支持，服务多层次、多支柱养老保险体系发展。\n数字金融加快推进金融机构数字化转型，健全数字金融治理体系。"}, {"title": "习近平3月6日下午看望了参加全国政协十四届三次会议的民盟、民进、教育界委员，并参", "detail": "加联组\n会，听取意见和建议。习近平强调，建设教育强国、科技强国、人才强国，必须坚持正确办学方向，培养\n德智体美劳全面发展的社会主义建设者和接班人。要聚焦用新时代中国特色社会主义思想铸魂育人，把德\n育贯穿于智育、体育、美育、劳动教育全过程。\n习近平强调，实现科技自主创新和人才自主培养良性互动，教育要进一步发挥先导性、基础性支撑作\n用。\n习近平指出，建设教育强国、科技强国、人才强国，是全党全社会的共同责任。人民政协要充分发挥\n专门协商机构作用，广泛凝聚人心、凝聚共识、凝聚智慧、凝聚力量，促进教育科技人才事业高质量发展。"}, {"title": "3月5日，位于广西梧州市藤县的藤州浔江大桥主桥成功实现合龙，顺利实现主体结构贯通", "detail": "，后续将\n进入桥面铺装阶段。藤州浔江大桥是世界首座最大跨径的独塔空间缆斜拉—悬索协作体系桥梁。"}, {"title": "3月7日，习近平出席解放军和武警部队代表团全体会议，在认真听取代表发言后，习近平", "detail": "发表重要\n讲话。他指出，我军建设“十四五”规划实施4年多来，取得一系列重大成果，同时也面临不少矛盾和问题。\n要处理好进度和质量、成本和效益、全局和重点、发展和监管、规划执行和能力形成的关系，走高质量、\n高效益、低成本、可持续发展路子，确保建设成果经得起历史和实战检验。\n习近平强调，要开展规划执行全过程专业化评估，评出发展质量、评出建设效益、评出体系作战能力。\n要把监管摆在更加突出的位置，构建完备有效的监管体系，加强融合监督、联合审计，深入查处腐败问题。\n要更好发挥监管对规划执行的服务和促进功能，确保规划收官质量托底、能力托底、廉洁托底。"}, {"title": "借助我国“奋斗者”号载人潜水器及全国产化科研体系，我国科学家成功绘制出全球首个海", "detail": "洋最深生\n态系统图景，并揭示了深渊生命的适应策略和资源潜能。3月7日，这一研究成果在国际顶级期刊《细胞》\n上发表，标志着我国深海微生物研究走在了世界前列。"}, {"title": "北京大学王剑威和龚旗煌团队与浙江大学戴道锌等研究人员合作，成功实现了基于集成光量", "detail": "子芯片\n的涡旋光量子纠缠源，研发出全球首例量子纠缠涡旋光发射芯片，为高维量子通信、量子精密测量、片上\n离子与原子操控等领域开辟了新的应用途径。"}, {"title": "3月6日，全国温室气体自愿减排交易市场（简称“自愿碳市场”）首批核证自愿减排量（", "detail": "CCER）完\n成登记，我国自愿碳市场建设取得重要实质进展。自愿碳市场是我国利用市场机制控制和减少温室气体排\n放的重要政策工具。"}, {"title": "3月7日上午，十四届全国人大三次会议举行记者会。", "detail": "中共中央政治局委员、外交部长王毅就“中国\n外交政策和对外关系”相关问题回答中外记者提问时介绍，今年秋天，中国将在天津主办上合组织峰会，届\n时上合国家领导人将齐聚海河之滨，总结成功经验，擘画发展蓝图，凝聚合作共识，让上合组织从中国再\n出发，推动构建更加紧密的上合命运共同体。获取后续更新及更多考试资料，请加微信：YM188357"}, {"title": "十四届全国人大三次会议3月8日上午在北京人民大会堂举行第二次全体会议，听取和审议", "detail": "全国人\n大常委会工作报告和最高人民法院工作报告、最高人民检察院工作报告。受全国人大常委会委托，赵乐际\n4\n(cid:3)\n委员长向大会报告全国人大常委会工作。赵乐际在报告中指出，一年来，共审议法律案39件，通过其中24\n件，包括制定法律6件、修改法律14件、作出有关法律问题和重大问题的决定4件。\n2025年是“十四五”规划收官之年。全国人大常委会要发展全过程人民民主，认真行使宪法法律赋予的\n立法权、监督权、决定权、任免权，稳中求进推动人大工作高质量发展，为以中国式现代化全面推进强国\n建设、民族复兴伟业作出新贡献。"}, {"title": "3月8日，中国商务部发布反歧视调查报告，认定加拿大对自中国进口的相关产品采取加征", "detail": "高额关税\n的做法存在明显的歧视情形，并建议对加拿大采取反歧视措施。这是中国首次发起反歧视调查并采取反歧\n视措施，放眼世界，这也是全球首次有国家采取反歧视措施。"}, {"title": "十四届全国人大三次会议3月9日下午举行记者会，民政部、人力资源和社会保障部、住房", "detail": "和城乡\n建设部、国家卫健委四位负责人就相关问题回答中外记者提问。国家卫生健康委员会主任雷海潮介绍，2024\n年，中国居民的期望寿命已经达到了79岁，比2023年提高了0.4岁，提前实现了“十四五”国民经济和社会\n发展规划目标的既定的努力方向。"}, {"title": "国家卫生健康委主任雷海潮3月9日在十四届全国人大三次会议民生主题记者会上说，国家", "detail": "卫生健\n康委将推进心理援助热线建设，今年5月1日前推动全国统一使用12356心理援助热线，帮助群众得到精神\n卫生方面的服务。"}, {"title": "中央网信办、农业农村部、商务部、中国人民银行近日联合印发《关于开展数字乡村强农惠", "detail": "农富农\n专项行动的通知》，在浙江省、安徽省、福建省、山东省、河南省、重庆市、四川省、陕西省等8个重点\n省市部署开展数字乡村强农惠农富农专项行动。"}, {"title": "联合国国际劳动妇女节纪念活动暨北京世界妇女大会三十周年对话会3月7日在瑞士日内瓦", "detail": "万国宫\n举行。与会嘉宾一致肯定1995年北京世界妇女大会通过的《北京宣言》和《行动纲领》的里程碑意义，强\n调《北京宣言》通过三十年来在全球范围内催生积极变化，至今仍是最全面、最权威的全球妇女议程，呼\n吁各方继续团结合作，携手推进全球妇女事业。"}, {"title": "3月9日从十四届全国人大三次会议秘书处获悉，到大会主席团决定的代表提出议案截止时", "detail": "间3月8\n日12时，大会秘书处共收到代表提出的议案269件。此外，大会秘书处目前已收到代表建议8000余件。"}, {"title": "2025年3月10日1时17分，我国在西昌卫星发射中心使用长征三号乙运载火箭，成", "detail": "功将通信技术\n试验卫星十五号发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。通信技术试验卫星十五号主\n要用于开展多频段、高速率卫星通信技术验证。"}, {"title": "中国人民政治协商会议第十四届全国委员会第三次会议圆满完成各项议程，3月10日上午", "detail": "在人民大\n会堂闭幕。王沪宁在讲话中说，全国政协十四届三次会议是一次高举旗帜、凝心聚力、求真务实、团结奋\n进的大会，充分彰显了人民政协的显著政治优势，彰显了我国全过程人民民主的蓬勃生机活力。\n王沪宁表示，要毫不动摇坚持中国共产党的全面领导，坚持人民政协性质定位，坚持团结和民主两大\n主题，扎实做好凝聚人心、凝聚共识、凝聚智慧、凝聚力量工作，紧紧围绕推进中国式现代化履职尽责，\n切实发挥最广泛爱国统一战线组织的政治作用，更好发挥人民政协作为社会主义协商民主重要渠道和专门\n协商机构作用，不断提高政治协商、民主监督、参政议政水平，更好担负起把中共中央决策部署和对人民\n政协工作要求落实下去、把海内外中华儿女智慧和力量凝聚起来的政治责任。"}, {"title": "世界坝体最高抽水蓄能电站——国网新源江苏句容抽水蓄能电站3号机组3月10日并网发", "detail": "电。至此，\n包含已投运的1、2号机组在内，该电站首批3台机组全部投运，当前并网发电容量达67.5万千瓦，长三角\n地区再添一大型清洁能源“调节器”。该电站上水库大坝高达182.3米，是世界坝体最高的抽水蓄能电站，发\n5\n(cid:3)\n挥着调峰、调频等作用。"}, {"title": "3月11日，十四届全国人大三次会议在北京闭幕。", "detail": "会议经表决，通过了关于修改全国人民代表大会\n和地方各级人民代表大会代表法的决定。决定自2025年3月12日起施行。《中华人民共和国全国人民代表\n大会和地方各级人民代表大会代表法》根据决定作相应修改，重新公布。"}, {"title": "3月11日，十四届全国人大三次会议第三场“部长通道”在人民大会堂举行，自然资源部", "detail": "部长关志鸥\n接受记者采访。关志鸥表示，我们牢牢守住了18亿亩的耕地红线，为粮食连续丰收提供了重要支撑。做好\n耕地保护，重点要做好这三方面：第一要稳数量、强监管；第二要提质量、优布局；第三要优生态、惠民\n生。获取后续更新及更多考试资料，请加微信：YM188357"}, {"title": "据上海海关信息，2024年，上海港完成汽车吞吐量363万辆，同比增长15%，首次", "detail": "跃升世界第一，\n其中外贸汽车吞吐量占比超六成。"}, {"title": "近日，中国农业科学院作物科学研究所作物智能设计算法模型创新研究组成功研发一套新的", "detail": "人工智\n能算法——自动化机器学习框架，通过将农作物的气象环境大数据与基因组信息深度融合，实现了作物精\n准遗传分析与基因组预测，为作物智能设计育种提供了有效工具。"}, {"title": "2025年3月12日是我国第47个植树节。", "detail": "全国绿化委员会办公室当天发布的2024年中国国土绿化状\n况公报显示，2024年全国完成营造林444.6万公顷、种草改良322.4万公顷、治理沙化石漠化土地278.3万公\n顷，森林覆盖率超25%，森林蓄积量超200亿立方米。"}, {"title": "3月12日0时38分，长征八号遥六运载火箭以“一箭十八星”的方式，在海南文昌商业", "detail": "航天发射场一\n号发射工位将千帆星座第五批组网卫星送入预定轨道，发射任务取得圆满成功。至此，海南商业航天发射\n场双工位首发成功，标志着我国首个商业航天发射场具备了全系统发射能力。"}, {"title": "中央党的建设工作领导小组3月12日召开会议，学习贯彻习近平总书记关于深入贯彻中央", "detail": "八项规定\n精神学习教育的重要讲话和重要指示精神，研究部署学习教育工作。会议指出，党中央决定，自2025年全\n国两会后至7月在全党开展深入贯彻中央八项规定精神学习教育。\n会议强调，开展深入贯彻中央八项规定精神学习教育，是巩固深化主题教育和党纪学习教育成果、纵\n深推进全面从严治党的重要举措，是密切党群干群关系、巩固党的执政基础的必然要求，是推进中国式现\n代化的有力保障。"}, {"title": "国务院总理李强3月12日主持召开国务院常务会议，会议审议通过《国务院关于修改〈快", "detail": "递暂行条\n例〉的决定（草案）》。会议指出，针对快递包装问题对《条例》进行专项修改，有利于推动快递包装绿\n色化、减量化、可循环，加快形成绿色生产和生活方式。"}, {"title": "当地时间3月12日，美国总统唐纳德·特朗普对所有进口至美国的钢铁和铝征收25%关", "detail": "税的举措，\n已正式生效。"}, {"title": "3月13日，国家主席习近平致电康斯坦丁诺斯·塔苏拉斯，祝贺他就任希腊共和国总统。", "detail": "习近平指\n出，中国和希腊都拥有悠久历史和灿烂文化，两国友好关系源远流长、历久弥新，是相知相亲、互利共赢\n的全面战略伙伴。近年来，双方持续推进比雷埃夫斯港项目，推动共建“一带一路”合作高质量发展，合作建\n设中希文明互鉴中心、雅典中国古典文明研究院，展现了两个古老文明的和合之美和时代担当。"}, {"title": "工业和信息化部等15部门办公厅（秘书局、办公室、综合司）发布关于促进中小企业提升", "detail": "合规意识\n加强合规管理的指导意见，到2030年，中小企业合规发展环境进一步优化，中小企业合规服务工作体系基\n本形成，企业基本具备适应高质量发展要求的合规管理意识和能力，依法合规经营水平显著提升，合规成\n为中小企业核心竞争力的重要组成部分。\n6\n(cid:3)"}, {"title": "中国科学院物理研究所科研团队近期成功研制出厚度仅为头发丝直径的二十万分之一的单原", "detail": "子层金\n属，这是国际上首次实现大面积二维金属材料的制备，开创了二维金属研究新领域。"}, {"title": "3月14日，自然资源部发布《2024年自然资源统计公报》，《公报》显示，根据20", "detail": "23年度全国国土\n变更调查成果，全国共有耕地12860.88万公顷、园地1961.09万公顷、林地28369.57万公顷、草地26321.57\n万公顷、湿地2351.98万公顷、城镇村及工矿用地3610.37万公顷、交通运输用地1042.91万公顷、水域及水\n利设施用地3626.48万公顷。"}, {"title": "《反分裂国家法》实施20周年座谈会3月14日在京举行。", "detail": "赵乐际强调，解决台湾问题，实现祖国\n完全统一，是大势所趋、大义所在、民心所向，是全体中华儿女的共同愿望，是实现中华民族伟大复兴的\n必然要求。要坚定信心决心，扎实推动祖国统一进程。坚定捍卫国家主权和领土完整，守护中华民族共同\n家园。坚定促进两岸交流合作，共创中华民族绵长福祉。坚定弘扬中华文化，铸牢中华民族共同体意识。"}, {"title": "近日，国家互联网信息办公室、工业和信息化部、公安部、国家广播电视总局联合发布《人", "detail": "工智能\n生成合成内容标识办法》，自2025年9月1日起施行。《标识办法》明确，人工智能生成合成内容标识主\n要包括显式标识和隐式标识两种形式，显式标识是指在生成合成内容或者交互场景界面中添加的，以文字、\n声音、图形等方式呈现并可以被用户明显感知到的标识；隐式标识是指采取技术措施在生成合成内容文件\n数据中添加的，不易被用户明显感知到的标识。"}, {"title": "教育部日前印发通知，部署实施高校学生就业能力提升“双千”计划，推动全国范围内开设", "detail": "1000个“微\n专业”（或专业课程群）和1000个职业能力培训课程。“双千”计划面向未来产业和战略性新兴产业发展、传\n统产业转型、数字经济、绿色经济、低空经济以及民生服务保障等人才急需，建设“微专业”和职业能力培训\n课程，主要面向本科、高职（专科）中高年级学生开设。"}, {"title": "国务院总理李强3月14日主持召开国务院第八次全体会议，李强指出，今后一个时期，我", "detail": "们面临的\n形势更加复杂多变，承担的任务更为艰巨繁重，进一步履行好职责使命，必须更加坚定更加自觉地贯彻落\n实好习近平总书记重要指示精神和党中央决策部署，做雷厉风行的执行者、攻坚克难的行动派、善作善成\n的实干家。"}, {"title": "2025年3月15日12时11分，我国在酒泉卫星发射中心使用长征二号丁运载火箭，", "detail": "成功将四维高景\n三号02星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。这次任务还搭载发射了天雁23星。"}, {"title": "3月15日，《古树名木保护条例》开始施行。", "detail": "最新数据显示，全国普查范围内的古树名木共计508.19\n万株，各地采取多种举措不断加强保护古树名木，创新实践守护“绿色记忆”，助力生态文明建设高质量发展。"}, {"title": "3月16日出版的第6期《求是》杂志将发表习近平的重要文章《坚持和落实“两个毫不动", "detail": "摇”》。这\n是习近平总书记2013年11月至2025年2月期间有关重要论述的节录。文章指出，我国是中国共产党领导\n的社会主义国家，公有制经济是长期以来在国家发展历程中形成的，为国家建设、国防安全、人民生活改\n善作出了突出贡献，是全体人民的宝贵财富。国有企业为我国经济社会发展、科技进步、国防建设、民生\n改善作出了历史性贡献，是我们党执政兴国的重要支柱和依靠力量。把国有企业建设好，把工人阶级作用\n发挥好，对巩固党的执政地位、巩固我国社会主义制度具有十分重大的意义。\n文章指出，我国非公有制经济从小到大、由弱变强，是在我们党和国家方针政策指引下实现的。长期\n以来，我国非公有制经济快速发展，在稳定增长、促进创新、增加就业、改善民生等方面发挥了重要作用。"}, {"title": "中国消费者协会主办的2025年“3·15”国际消费者权益日主题活动3月15日在北", "detail": "京举行。现场举办\n了“全国消协智慧315”平台正式上线启动仪式，重点围绕智能化与共治化建设，部署DeepSeek实现面向消\n费者的智能问答，优化新增行业公示、指数公示、协作共治等功能，确保消费者投诉有门、处置高效。\n7\n(cid:3)"}, {"title": "3月15日，国内首款按照适航标准研制的载重1吨级大型无人运输机TP1000在山东", "detail": "烟台成功首飞。\nTP1000起飞重量3.3吨，载重1000公斤，满载航程1000公里，与此前的TP500相比，具有载重更大、航程\n更远的特点。"}, {"title": "民航局日前发布的2024年全国民用运输机场生产统计公报显示，2024年，我国境内", "detail": "运输机场（港澳\n台地区数据另行统计，下同）共有263个，其中定期航班通航运输机场262个，定期航班通航城市（或地区）\n258个。2024年我国民用运输机场完成旅客吞吐量145951.8万人次，较上年增长15.9%，较2019年增长8.0%。"}, {"title": "中共中央办公厅、国务院办公厅近日印发《提振消费专项行动方案》。", "detail": "行动方案部署了8方面30项\n重点任务，包括城乡居民增收促进行动、消费能力保障支持行动、服务消费提质惠民行动、大宗消费更新\n升级行动、消费品质提升行动、消费环境改善提升行动、限制措施清理优化行动、完善支持政策。\n《方案》促进工资性收入合理增长。实施重点领域、重点行业、城乡基层和中小微企业就业支持计划。\n延续实施失业保险稳岗返还政策。结合形势变化加大就业支持力度，促进重点群体就业。"}, {"title": "2025年3月17日16时07分，我国在酒泉卫星发射中心使用谷神星一号运载火箭，", "detail": "成功将云遥一号\n55-60星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。这次任务还搭载发射了中科卫星06\n星、07星。此次任务是谷神星一号运载火箭的第18次飞行。"}, {"title": "3月17日，国新办举行新闻发布会介绍提振消费有关情况。", "detail": "会上，国家发展改革委副主任李春临介\n绍，总体来看，我国已连续十余年稳居全球第二大商品消费市场和最大网络零售市场，居民消费需求和结\n构不断升级，服务性消费支出占比持续提高，新的市场空间还在不断地拓展。"}, {"title": "近日，中共中央办公厅印发《关于在全党开展深入贯彻中央八项规定精神学习教育的通知》", "detail": "，《通\n知》指出，经党中央同意，在全党开展深入贯彻中央八项规定精神学习教育。学习教育于2025年全国两会\n后启动、7月底前基本结束。\n《通知》强调，坚持聚焦主题、简约务实，不分批次、不划阶段，一体推进学查改，融入日常、抓在\n经常。开门教育要注重群众参与，接受群众监督，各级领导干部要带头走好新时代党的群众路线，组织党\n员、干部立足岗位，在推动高质量发展、加强基层治理、完成急难险重任务中担当作为、服务群众，让群\n众可感可及。"}, {"title": "据工信微报微信公众号消息，2024年，我国数字产业总体运行平稳，2024年，数字", "detail": "产业重点监测的\n核心指标中九成以上实现同比提升。数字产业完成业务收入35万亿元，同比增长5.5%。"}, {"title": "3月17日至18日，习近平在贵州考察，习近平强调，一个地方的发展活力同营商环境密", "detail": "切相关。贵\n州要积极融入全国统一大市场建设，坚决破除地方保护、市场分割、“内卷式”竞争，为全社会创业创新营造\n稳定公平透明、可预期的环境。优化营商环境要一手抓改革，打通制约高质量发展的堵点卡点；一手抓干\n部教育管理，引导干部增强大局意识、服务意识、诚信意识、廉洁意识。开放也是重要的营商环境。贵州\n要用好西部陆海新通道建设机遇，积极对接粤港澳大湾区、成渝地区双城经济圈建设，主动融入陆海内外\n联动、东西双向互济的全面开放格局。获取后续更新及更多考试资料，请加微信：YM188357\n习近平强调，贵州历史底蕴深厚，红色文化丰富，民族文化多姿多彩，要利用这一优势，增强文化自\n信、化风育人，助推经济社会发展。要深化文旅体融合，丰富旅游业态，打造“多彩贵州”文旅新品牌。"}, {"title": "国家电网3月18日宣布，大同—怀来—天津南1000千伏特高压交流工程当日开工建设", "detail": "，这是我国“西\n电东送”的新通道，计划于2027年6月建成投运。截至2024年底，国家电网已建成“22交16直”38项特高压\n工程，形成全球最大规模的特高压输电网络，为保障电力安全可靠供应、促进绿色低碳发展提供坚强支撑。"}, {"title": "文化和旅游部于近日确定并公布了第六批国家级非物质文化遗产代表性传承人名单，共94", "detail": "2人。目\n8\n(cid:3)\n时政/公基/笔试/面试/真题资料，请加微信：YM188357\n前，国家级非遗代表性传承人队伍总规模达到3998人，传承人队伍结构进一步优化，代表性项目的传承力\n量进一步强化。"}, {"title": "国际奥委会执委会3月17日建议，将拳击纳入2028年洛杉矶奥运会正式比赛项目。", "detail": ""}, {"title": "3月19日在上海开幕的2025集装箱多式联运亚洲展上了解到的最新数据显示，202", "detail": "4年我国集装箱总\n产量超过810万标准箱，较2023年增长268.2%，再创历史新高。我国集装箱的产销量达全球的96%，产能\n主要分布在长三角和珠三角地区，以中集集团、上海寰宇、新华昌集团等为主要供应商。"}, {"title": "国务院总理李强日前签署国务院令，公布《国务院关于涉外知识产权纠纷处理的规定》，自", "detail": "2025年\n5月1日起施行。《规定》共18条。"}, {"title": "近日，国内首款碳—14核电池原型机“烛龙一号”发布，这标志着我国在核能技术领域与", "detail": "微型核电池\n领域取得重要突破。“烛龙一号”具有零下100摄氏度至200摄氏度的极端温度适应性，支持毫瓦级脉冲放电\n及能量智能管理，可适配不同场景需求，还将以绿色低碳属性推动新能源产业链迭代升级。"}, {"title": "世界知识产权组织近日公布2024年全球知识产权申报统计数据。", "detail": "数据显示，2024年，全球PCT（专\n利合作条约）国际专利申请总量达27.39万件，同比增长0.5%。中国申请量为70160件，同比增长0.9%，仍\n是申请量最大的来源国。美国以54087件申请量位居第二，日本、韩国和德国紧随其后。"}, {"title": "3月19日至20日，习近平在云南省委书记王宁和省长王予波陪同下，先后到丽江、昆明", "detail": "等地考察调\n研。习近平强调，云南区位条件独特，要积极推进高水平对外开放，建设面向南亚东南亚辐射中心。要高\n质量建设自由贸易试验区，加强交通物流、能源、数字信息等大通道建设，使各类开放平台成为经济发展\n的增长点。\n习近平指出，云南生态地位重要，要坚定不移走生态优先、绿色发展之路，筑牢我国西南生态安全屏\n障。要健全以国家公园为主体的自然保护地体系，加强生态系统保护和修复，持续开展石漠化、水土流失\n及小流域综合治理。"}, {"title": "3月19日至21日，以“融金聚智点亮南方”为主题的2025全球南方金融家论坛在北", "detail": "京举行。来自全\n球30多个国家和地区的政府部门、金融机构负责人及专家学者等展开交流研讨。"}, {"title": "农业农村部、国家卫生健康委、工业和信息化部近日联合印发的《中国食物与营养发展纲要", "detail": "（2025\n—2030年）》明确，到2030年，我国多元化食物供给体系更加完善，食物优质化、特色化、品牌化水平持\n续提升。食物消费结构向营养健康型转变，食物与营养摄入更加均衡合理，营养健康状况进一步改善。"}, {"title": "近期，中国科学技术大学潘建伟、彭承志、廖胜凯等人，联合济南量子技术研究院等单位组", "detail": "成的研\n究团队，在国际上首次实现微纳量子卫星与小型化、可移动地面站之间的实时星地量子密钥分发。他们与\n南非斯泰伦博斯大学科研团队合作，在中国和南非之间相隔12900多公里的距离上建立量子密钥，成功将一\n张中国长城图片和一张南非实验现场图片完成“一次一密”加密，实现跨越南北半球的远程安全传输。"}, {"title": "3月20日，我国自主研制的8600车大型汽车运输船正式交付。", "detail": "这艘船不仅性能优秀，还创造了我国\n大型汽车运输船船体搭载调试周期最快纪录。"}, {"title": "当地时间3月20日，正在希腊举行的国际奥委会第144次全会决定，将拳击纳入202", "detail": "8年洛杉矶奥运\n会正式比赛项目。"}, {"title": "神舟十九号航天员乘组圆满完成第三次出舱活动，航天员蔡旭哲已完成5次出舱活动，成为", "detail": "目前在\n舱外执行任务次数最多的中国航天员。"}, {"title": "2025年3月21日19时07分，我国在酒泉卫星发射中心使用谷神星一号运载火箭，", "detail": "成功将云遥一号\n43-48星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。此次任务是谷神星一号运载火箭的第\n9\n(cid:3)\n19次飞行。"}, {"title": "2025年3月21日是第13个“国际森林日”，主题是“森林与食物：森林对于维持粮", "detail": "食生产至关重要”。\n记者从国家林草局获悉，2024年，我国森林食物产量超2亿吨，成为继粮食、蔬菜之后的第三大重要农产\n品。"}, {"title": "3月20日，2025种子大会暨南繁硅谷论坛在海南三亚开幕。", "detail": "本届大会以“中国种业振兴南繁硅谷崛\n起”为主题，超2000位种业界同仁和国内外嘉宾参会，围绕种业发展和南繁硅谷建设等展开研讨，研判行业\n形势，助力种业高质量发展。"}, {"title": "3月20日，以“AI科技、AI生活”为主题的2025中国家电及消费电子博览会（A", "detail": "WE2025）在上海新\n国际博览中心开幕。本届展会吸引全球千余家企业参展，全景展示家电及消费电子领域的前沿成果，呈现\nAI赋能智慧生活的新产品、新方案、新场景。"}, {"title": "国务院总理李强3月21日主持召开国务院常务会议，研究建立健全涉企收费长效监管机制", "detail": "有关举措，\n审议通过《婚姻登记条例（修订草案）》。会议指出，加强涉企收费监管是降低企业经营成本、优化营商\n环境的重要举措。要坚持问题导向、防治并举、标本兼治，聚焦政府部门及下属单位、行政审批中介服务\n机构、行业协会商会、经营自然垄断环节业务企业等涉企收费主体，强化全过程监管，着力构建协同高效\n的长效监管机制。"}, {"title": "3月21日，面向空间天气研究的国家重大科技基础设施——子午工程二期通过国家验收，", "detail": "与子午工\n程一期组成了世界最大的空间环境地基综合监测网，这是我国建成的国际首个覆盖日地空间全圈层（太阳\n风-磁层-电离层-中高层大气）的综合性空间环境地基监测设施，标志着我国空间环境地基监测能力跃居世\n界领先地位。"}, {"title": "3月21日，金砖国家特殊经济区中国合作中心工作推进会在浙江杭州成功召开。", "detail": "会上，金砖国家特\n殊经济区中国合作中心正式揭牌。中国合作中心将打造金砖国家国际客厅和合作中心总部，打响“投资金砖”\n“买在金砖”公共品牌，推动一批示范性合作项目持续开展；结合全球数字贸易博览会等重大活动举办金砖国\n家合作对话，每年发布金砖国家特殊经济区合作报告和案例等，力争建设金砖国家特殊经济区合作示范区。"}, {"title": "3月21日，红河电厂扩建工程项目投产并网发电仪式在云南省红河州开远市举行，标志着", "detail": "全球首台\n700兆瓦超超临界循环流化床燃煤发电机组成功并网发电。红河电厂扩建工程项目是云南省“十四五”新增480\n万千瓦煤电和区域“重中之重”项目，是全球首个核准、首个开工、首个建成、首个并网发电的700兆瓦超超\n临界循环流化床机组。获取后续更新及更多考试资料，请加微信：YM188357"}, {"title": "2025年3月22日是第三十三届“世界水日”，从今天开始到28日，也是第三十八届", "detail": "“中国水周”。今年\n的主题是“推动水利高质量发展，保障我国水安全”。2024年度全国水土流失动态监测工作结果显示，全国\n水土流失面积下降到260.19万平方公里，较2023年减少2.57万平方公里，减幅0.98%。京津冀地区减幅最\n高，为2.48%，是全国平均减幅的2.53倍。"}, {"title": "3月22日，中共中央政治局委员、外交部长王毅在东京同日本外相岩屋毅、韩国外长赵兑", "detail": "烈共同出\n席第11次中日韩外长会。王毅强调，有风有雨是常态，风雨无阻是心态。三国合作要行稳致远，必须同双\n边关系相互促进、良性循环。尤其要尊重彼此的核心利益，管控好矛盾分歧，在维护良好稳定的双边关系\n基础上，不断积累共识、培育动能、深化合作、提升水平。中方愿同日韩一道，推动中日韩合作在新形势\n下提质升级，更加成熟、更加稳定、更富韧性。"}, {"title": "中国发展高层论坛2025年年会3月23日在北京钓鱼台国宾馆举行。", "detail": "这是两会后举办的首个国家级\n大型国际论坛，吸引了100多位外方代表参加，今年首次参会的跨国企业数量创下新高。本届论坛的主题为\n10\n(cid:3)\n“全面释放发展动能，共促全球经济稳定增长”。会议期间，中外嘉宾将围绕宏观政策、改革、提振消费、新\n质生产力、人工智能等议题举行12场专题研讨会。"}, {"title": "根据最新数据统计，2024年合肥市常住人口为1000.2万人。", "detail": "合肥成为长三角地区继上海、苏州、杭\n州之后的第4个千万人口大市，也是我国第18个常住人口破千万的城市。我国人口超过千万的18个城市分\n别是：重庆、上海、北京、成都、广州、深圳、武汉、天津、西安、苏州、郑州、杭州、石家庄、临沂、\n东莞、长沙、青岛和合肥。"}, {"title": "胜利济阳页岩油国家级示范区油气勘探取得重大突破，位于山东省淄博市高青县内的新兴油", "detail": "田樊页\n平1区块，页岩层系石油探明地质储量达1.4亿多吨，技术可采储量达1135.99万吨。这是首个通过自然资\n源部评审备案的探明地质储量达亿吨级的页岩油田。"}, {"title": "国务院总理李强日前签署国务院令，公布修订后的《保障中小企业款项支付条例》，自20", "detail": "25年6\n月1日起施行。《条例》共5章37条。明确机关、事业单位和大型企业支付中小企业款项的期限要求，增\n加规定大型企业应当自货物、工程、服务交付之日起60日内支付款项；按照行业规范、交易习惯合理约定\n付款期限的，不得约定以收到第三方付款作为向中小企业支付款项的条件或者按照第三方付款进度比例支\n付中小企业款项。"}, {"title": "日前，国家体育总局发布全国体育场地最新统计调查数据。", "detail": "目前，全国共有体育场地484.17万个，\n全国人均体育场地面积3.0平方米。"}, {"title": "2025年3月23日是第65个世界气象日，主题为“携手缩小早期预警差距”。", "detail": "3月23日发布的全球气\n象发展报告指出，2024年是有气象记录以来最热的一年，气象的早期预警系统是防灾减灾的重要手段，中\n国气象局发布的“风雷”“风清”“风顺”大模型均已在气象业务领域实现落地，风云气象卫星已服务130余个国\n家和地区，中国经验、技术和标准为全球气象治理和应对气候变化贡献大国力量。"}, {"title": "中国发展高层论坛2025年年会3月23日至24日在北京举行，中国民政部副部长唐承", "detail": "沛在出席年会\n时称，预计到2035年，银发经济占GDP比重将从6%上升到9%。"}, {"title": "3月24日，国家主席习近平夫人、世界卫生组织结核病和艾滋病防治亲善大使彭丽媛向世", "detail": "界卫生组\n织2025年世界防治结核病日视频会议发表书面致辞。彭丽媛表示，在世界卫生组织有力推动和国际社会长\n期努力下，全球结核病防治成效显著，自2000年以来已经成功挽救了7900万患者的生命，这是令人赞叹的\n成就！中国政府高度重视结核病防治，经过广大结核病防治工作者不懈努力，中国结核病患者治愈率保持\n在90%以上。"}, {"title": "3月24日，财政部公布的《2024年中国财政政策执行情况报告》显示，2024年，", "detail": "全国一般公共预\n算收入219702亿元。全年一般公共预算支出284612亿元，增长3.6%。"}, {"title": "2025年版《中华人民共和国药典》已由国家药监局、国家卫生健康委2025年第29", "detail": "号公告颁布，自\n2025年10月1日起实施。《中国药典》是国家药品标准的重要组成部分，是药品研制、生产（进口）、经\n营、使用和监督管理等相关单位均应当遵循的法定技术标准。"}, {"title": "3月25日，中国信息通信研究院发布《中国参与国际通信海缆建设和保护相关情况报告（", "detail": "2025年）》。\n报告显示，当前我国通信海缆技术已取得重大突破，我国企业在行业中率先推出了32纤对海缆解决方案及\n全系列产品。"}, {"title": "博鳌亚洲论坛2025年年会3月25日举行，本次年会的主题为“在世界变局中共创亚洲", "detail": "未来”，围绕“重\n建信任促合作、全球化再平衡与包容性发展、可持续发展、人工智能与创新发展”等方向设置议题。为期4\n天的年会将举办50多场论坛活动，来自60多个国家和地区的近2000名中外嘉宾参会。\n11\n(cid:3)"}, {"title": "中国网络视听节目服务协会3月26日在成都发布《中国网络视听发展研究报告（2025", "detail": "）》。报告显\n示，截至2024年12月，我国网络视听用户规模达10.91亿人，网民使用率为98.4%，继续保持增长态势，“第\n一大互联网应用”地位愈加巩固。"}, {"title": "生态环境部3月26日发布全国碳排放权交易市场工作方案，覆盖钢铁、水泥、铝冶炼行业", "detail": "，这是\n全国碳排放权交易市场首次扩大行业覆盖范围。目前，全国碳排放权交易市场仅覆盖了发电行业重点排放\n单位2200家，年覆盖二氧化碳排放量超过50亿吨。"}, {"title": "近日，人力资源社会保障部、财政部联合印发《关于实施“技能照亮前程”培训行动的通知", "detail": "》，《通\n知》明确，从2025年起到2027年底，实施“技能照亮前程”培训行动。主要目标是聚焦就业岗位挖潜扩容，\n面向有就业和培训意愿的农村转移就业劳动者、离校未就业高校毕业生、登记失业人员、就业困难人员等\n重点群体，积极开展职业技能培训。围绕康养托育、先进制造、现代服务、新职业等重点领域市场需求和\n职业技能要求，推行“岗位需求+技能培训+技能评价+就业服务”四位一体项目化培训模式，推动培训和就业\n协同联动，促进劳动者实现高质量充分就业。"}, {"title": "3月26日，湖北省十四届人大常委会第十六次会议表决通过《湖北省英雄烈士保护条例》。", "detail": "这是全\n国首部英雄烈士保护领域的地方性法规，将于2025年7月1日起施行。"}, {"title": "2025年3月26日23时55分，我国在西昌卫星发射中心使用长征三号乙运载火箭，", "detail": "成功将天链二\n号04星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。天链二号04星是我国第二代地球同步\n轨道数据中继卫星，主要用于为飞船、空间站等载人航天器提供数据中继和测控服务，为中、低轨道资源\n卫星提供数据中继和测控服务，为航天器发射提供测控支持。"}, {"title": "3月26日，《关于支持国际消费中心城市培育建设的若干措施》发布，政策支持上海、北", "detail": "京、广州、\n天津、重庆加快国际消费中心城市培育建设，打造具有全球吸引力的消费环境，五个国际消费中心城市突\n出地方特色，用丰富多元的供给，为消费市场不断注入新的活力。"}, {"title": "3月27日上午，第十二届中国网络视听大会在四川成都开幕。", "detail": "本届大会以“极视听·强赋能”为主题，\n突出“权威性、引领性、国际性、专业性”，持续打造中国著名、世界闻名的网络视听权威发布平台、成果展\n示平台、行业赋能平台、大众共享平台，进一步提升大会的影响力和产业带动效应，助力广播电视和网络\n视听行业的高质量发展。"}, {"title": "2025中关村论坛年会3月27日正式开幕，此次年会的主题是“新质生产力与全球科技", "detail": "合作”，来自\n34个国家的30多家专业技术转移机构、120多所高校院所、200多家创投机构、2000多家创新企业共同参\n与。"}, {"title": "国家自然科学基金委员会3月27日在2025中关村论坛年会开幕式上发布了2024年", "detail": "度“中国科学十\n大进展”。分别是：一嫦娥六号返回样品揭示月背28亿年前火山活动。实现大规模光计算芯片的智能推理与\n训练。三、阐明单胺类神经递质转运机制及相关精神疾病药物调控机理。四、实现原子级特征尺度与可重\n构光频相控阵的纳米激光器。五、发现自旋超固态巨磁卡效应与极低温制冷新机制。六、异体CAR-T细胞\n疗法治疗自身免疫病。七、额外X染色体多维度影响男性生殖细胞发育。八、凝聚态物质中引力子模的实\n验发现。九、高能量转化效率锕系辐射光伏微核电池的创制。十、发现超大质量黑洞影响宿主星系形成演\n化的重要证据。"}, {"title": "3月28日上午，国家主席习近平在北京人民大会堂会见国际工商界代表。", "detail": "习近平指出，多年来，中\n国一直是世界经济增长的主要贡献者和稳定锚，正在全面推进中国式现代化。对外开放是中国的基本国策，\n中国正在推进高水平对外开放，稳步扩大规则、规制、管理、标准等制度型开放，开放的大门只会越开越\n12\n(cid:3)\n大，利用外资的政策没有变也不会变。中国是全球第二大消费市场，拥有全球最大规模中等收入群体，蕴\n含着巨大投资和消费潜力。中国致力于高质量发展，绿色化、数字化、智能化转型加快推进，产业配套能\n力强，是新一轮科技革命和产业变革的最佳应用场景。"}, {"title": "国务院新闻办公室3月28日发布《新时代西藏人权事业的发展与进步》白皮书。", "detail": "白皮书说，西藏\n人民依法享有更加广泛充分、真实具体、有效管用的民主权利。适当生活水准权、受教育权、工作权、健\n康权、社会保障权得到更充分保障。西藏文化建设实现了前所未有的繁荣与发展，有效保障了各族人民的\n文化权利。获取后续更新及更多考试资料，请加微信：YM188357"}, {"title": "国家知识产权局3月28日召开新闻发布会介绍，截至2024年底，我国每万人口高价值", "detail": "发明专利拥\n有量达到14件，提前实现国家“十四五”规划预期目标。战略性新兴产业有效发明专利量达到134.9万件，同\n比增长15.7%。高校和科研机构新增专利申请中，发明专利比重提高到70.4%。"}, {"title": "中国电力企业联合会最新统计数据显示，截至2025年2月底，我国非化石能源发电装机", "detail": "规模首次\n达到20亿千瓦。我国非化石能源发电装机占全国总发电装机比重达到58.8%。"}, {"title": "3月28日，2025中国科幻大会开幕式在北京首钢国际会展中心举行。", "detail": "据了解，作为2025中关村论\n坛年会平行论坛之一，大会以“科学梦想创造未来”为主题，设置开幕式、专业性论坛、赛事类活动、产业\n促进活动和群众性活动等5个板块30余场活动，为观众带来“时尚+酷玩”的科幻体验。"}, {"title": "近日，中国酒业协会主办的第二十二届中国国际酒业博览会在四川泸州开幕。", "detail": "本届酒博会吸引了近\n50个国家和地区的800余家企业参展，设置白酒名酒展区、葡萄酒和果酒展区等十大展区，展览总面积超\n过8万平方米。"}, {"title": "近日，国务院办公厅印发《关于建立健全涉企收费长效监管机制的指导意见》。", "detail": "指导意见着力健全\n涉企收费监管制度，加大违规收费治理力度，强化防治、常治、惩治、根治，提出七方面重点任务。"}, {"title": "中国旅游研究院近日发布《中国入境旅游发展报告2024—2025》。", "detail": "《报告》指出，2024年中国共接\n待入境游客13190万人次，同比增长61%，恢复到2019年的九成以上，远高于2023年的恢复水平。《报告》\n显示，北京、上海、广州和深圳的入境旅游接待规模及恢复水平较高。"}, {"title": "2025年3月30日00时05分，我国在文昌航天发射场使用长征七号改运载火箭，成", "detail": "功将通信技术\n试验卫星十六号发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。该卫星主要用于开展多频段、\n高速率卫星通信技术验证。"}, {"title": "3月30日，以“系统性变革智能化传播：网络媒体的机遇与挑战”为主题的2025中国", "detail": "网络媒体论坛\n在广西南宁开幕。论坛期间，还举办了人机共创·2025AI赋能正能量创作大会、“坚持主流价值导向推动\n算法向上向善”主题分享会、“发挥多元主体力量共创繁荣内容生态”发布启动会等活动。"}, {"title": "近日，2025中国国际会展业创新发展大会（CCESF）在上海举办，此次创新发展大", "detail": "会以“赋能融合、\n创新开拓”为主题，汇聚全国会展城市代表、行业精英和知名会展企业代表，共谋会展业新增长、新路径、\n新机遇。"}, {"title": "近日，中共中央办公厅、国务院办公厅印发了《逐步把永久基本农田建成高标准农田实施方", "detail": "案》，\n明确到2030年，力争累计建成高标准农田13.5亿亩，累计改造提升2.8亿亩，统筹规划、同步实施高效节\n水灌溉，新增高效节水灌溉面积8000万亩；到2035年，力争将具备条件的永久基本农田全部建成高标准农\n田，累计改造提升4.55亿亩，新增高效节水灌溉面积1.3亿亩。\n在建设标准方面，提出以“一平”（田块平整）、“两通”（通水通路）、“三提升”（提升地力、产量、效\n益）为基本标准，合理确定不同区域、不同类型高标准农田建设标准和投入标准。\n13\n(cid:3)"}]}, {"month": "2025年4月", "year": 2025, "items": [{"title": "2024年，全国港口货物吞吐量达176亿吨，集装箱吞吐量达3.3亿标箱，继续稳居", "detail": "世界第一。截至2024\n年底，全球货物吞吐量和集装箱吞吐量排名前十的港口中，我国分别占八席和六席。"}, {"title": "中共中央政治局3月31日召开会议，审议《生态环境保护督察工作条例》《关于二十届中", "detail": "央第四轮\n巡视情况的综合报告》。会议强调，要坚持和加强党对生态环境保护督察工作的领导，继续发挥督察利剑\n作用，进一步压实各地区各部门抓好美丽中国建设的政治责任。要牢牢牵住责任制这个“牛鼻子”，强化大局\n意识，保持严的基调，敢于动真碰硬，持续发现问题，认真解决问题，提高对党中央生态文明建设决策部\n署的执行力。要强化督察队伍建设，加强规范管理，严明作风纪律。\n会议指出，中央巡视组对部分中央和国家机关单位开展巡视，发现一些问题，要严肃认真抓好整改。\n要加强领导班子建设，着力解决乱作为、不作为、不敢为、不善为问题，推进领导干部能上能下常态化。"}, {"title": "3月31日，中国海油发布消息，我国在南海东部海域勘探发现惠州19-6亿吨级油田。", "detail": "这是我国首次\n探获海上深层—超深层碎屑岩大型整装油田，展示出我国近海深层—超深层领域油气勘探潜力。"}, {"title": "4月1日出版的第7期《求是》杂志将发表习近平的重要文章《朝着建成科技强国的宏伟目", "detail": "标奋勇前\n进》。文章指出，在新时代科技事业发展实践中，我们不断深化规律性认识，积累了许多重要经验。主要\n是：坚持党的全面领导，坚持走中国特色自主创新道路，坚持创新引领发展，坚持“四个面向”的战略导向，\n坚持以深化改革激发创新活力，坚持推动教育科技人才良性循环，坚持培育创新文化，坚持科技开放合作\n造福人类。这些经验弥足珍贵，必须长期坚持并在实践中不断丰富发展。\n文章指出，我们要建成的科技强国，必须具备以下基本要素：一是拥有强大的基础研究和原始创新能\n力，持续产出重大原创性、颠覆性科技成果。二是拥有强大的关键核心技术攻关能力，有力支撑高质量发\n展和高水平安全。三是拥有强大的国际影响力和引领力，成为世界重要科学中心和创新高地。四是拥有强\n大的高水平科技人才培养和集聚能力，不断壮大国际顶尖科技人才队伍和国家战略科技力量。五是拥有强\n大的科技治理体系和治理能力，形成世界一流的创新生态和科研环境。"}, {"title": "2025年4月1日12时00分，我国在酒泉卫星发射中心使用长征二号丁运载火箭，成", "detail": "功将卫星互联网\n技术试验卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。该卫星主要用于开展手机宽带\n直连卫星、天地网络融合等技术试验验证。"}, {"title": "4月1日，国家主席习近平同印度总统穆尔穆互致贺电，庆祝两国建交75周年。", "detail": "习近平指出，中国和\n印度同为文明古国、发展中大国、“全球南方”重要成员，都处在各自现代化建设的关键时期。中印关系发展\n历程表明，做相互成就的伙伴、实现“龙象共舞”是双方的正确选择，完全符合两国和两国人民根本利益。双\n方应坚持从战略高度和长远角度看待和处理中印关系，共谋相邻大国和平共处、互信互利、共同发展的相\n处之道，共同推进世界多极化和国际关系民主化。"}, {"title": "近日，中国科学技术发展战略研究院发布《国家创新指数报告2024》。", "detail": "报告显示，全球创新格局保持\n亚美欧三足鼎立态势，领先国家科技创新优势突出。中国创新能力综合排名第10位，接近欧洲主要发达国\n家水平。"}, {"title": "近日，中共中央办公厅、国务院办公厅印发了《关于健全社会信用体系的意见》，《意见》", "detail": "提出坚持\n政府引导、市场驱动、社会共建，坚持弘扬诚信文化，坚持公共信用信息和市场信用信息相互融合，坚持\n信用奖惩合理合法，构建覆盖各类主体、制度规则统一、共建共享共用的社会信用体系，推动社会信用体\n系与经济社会发展各方面各环节深度融合，为加快建设全国统一大市场、维护公平有序竞争市场秩序、推\n动高质量发展提供有力支撑。\n1\n需要纸质原版打印加微信：YM188357"}, {"title": "3月31日晚，东江水供港60周年纪念典礼在香港举行。", "detail": "60年来，东深供水工程已不间断地向香港供\n水超过300亿立方米，满足香港约80%的用水需求。这项工程解决了香港缺水之忧，有力支撑香港从传统\n加工制造业向国际金融、航运、贸易中心的转型，成就了“东方明珠”的繁荣盛景。"}, {"title": "4月2日，中国人民解放军东部战区位台湾海峡中部、南部相关海域组织“海峡雷霆-20", "detail": "25A”演练。"}, {"title": "国家药监局今天向各省、自治区、直辖市和新疆生产建设兵团药品监督管理局以及中国食品", "detail": "药品检\n定研究院发出通知：决定将流感疫苗的批签发时限由60个工作日调整为45个工作日。"}, {"title": "中办、国办近日印发《关于完善价格治理机制的意见》。", "detail": "意见指出，加快构建市场有效、调控有度、\n监管科学的高水平价格治理机制，提高资源配置效率，提升宏观经济治理水平，更好服务中国式现代化建\n设。健全价格监测预警体系。优化价格监测报告制度，丰富监测品种、创新监测方式、拓展监测渠道、提\n升监测信息化水平，健全覆盖国内外、产供销、期现货的监测分析预警机制，增强时效性和针对性。完善\n价格信息发布，稳定市场预期。"}, {"title": "2025年4月3日10时12分，我国在太原卫星发射中心使用长征六号运载火箭，成功", "detail": "将天平三号A\n星02星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。天平三号A星02星主要用于地面雷\n达设备标校和RCS测量，为地面光学设备成像试验和低轨空间环境探测监视试验提供支持，为大气空间环\n境测量和轨道预报模型修正提供服务。"}, {"title": "习近平4月3日上午在参加首都义务植树活动时强调，植树造林是生态文明建设重要一环。", "detail": "习近平\n指出，绿化祖国必须坚持扩绿兴绿护绿“三绿”并举，推动森林水库、钱库、粮库、碳库“四库”联动。要更加\n注重“提质”，优化林分结构，搞好森林经营，同步提升草原生态质量。更加注重“兴业”，多用改革的办法用\n活林草资源，壮大林草产业。更加注重“利民”，为群众增添身边的绿、眼前的美，拓展林草就业增收空间。"}, {"title": "全国总工会、教育部、人力资源社会保障部、全国工商联日前联合印发《关于广泛实施求学", "detail": "圆梦行\n动推进产业工人学历与能力提升的意见》，明确到2030年，资助不少于300万名符合入学条件的产业工人，\n提供高等学历继续教育和非学历教育。"}, {"title": "当地时间4月2日，美国白宫发表声明称，美国总统特朗普签署了关于所谓“对等关税”的", "detail": "行政令，宣\n布美国对贸易伙伴设立10%的“最低基准关税”，并对某些贸易伙伴征收更高关税。"}, {"title": "4月4日，国务院关税税则委员会发布公告，经国务院批准，自2025年4月10日12", "detail": "时01分起，对\n原产于美国的所有进口商品，在现行适用关税税率基础上加征34%关税。"}, {"title": "近日从国家数据局获悉，据测算，2024年，全国数据市场交易规模超1600亿元，同", "detail": "比增长30%以上。\n其中，场内市场数据交易规模同比实现翻番。"}, {"title": "近日，国家知识产权局同意新疆维吾尔自治区开展国家级知识产权保护中心建设。", "detail": "至此，全国29个\n省（自治区、直辖市）已建设77家国家级知识产权保护中心，其中省域层面建设23家。"}, {"title": "4月4日，韩国宪法法院就尹锡悦弹劾案做出宣判，8名宪法法官一致认为，尹锡悦严重违", "detail": "反了宪法\n和法律，并于当地时间11时22分宣布尹锡悦被罢免。尹锡悦成为继2017年朴槿惠被弹劾下台之后，第二\n位被弹劾下台的韩国总统。"}, {"title": "4月5日，红旗渠将迎来主干渠通水60周年。", "detail": "记者4日从中国水利部获悉，60年来，红旗渠已累计\n引水超过130亿立方米，灌溉农田4700余万亩次，促进粮食增产80亿斤。"}, {"title": "4月5日，我国首台智能红外风机融冰设备在中国大唐江西蜈蚣山风电场成功试运，标志着", "detail": "我国在大\n容量风机智能除冰领域实现新的技术突破。"}, {"title": "日前发布的《“十五五”商业航天发展思路与路径》报告显示，中国商业航天正处于快速健", "detail": "康成长阶\n2\n需要纸质原版打印加微信：YM188357\n段，全产业链实现快速发展。报告将中国商业航天发展大致划分为4个阶段：起步期、成长期、成熟期和\n转型期。我国商业航天有望在“十五五”末或“十六五”时期迎来成熟期。"}, {"title": "国家发展改革委等六部门近日联合印发《推动热泵行业高质量发展行动方案》提出，经过各", "detail": "方共同\n努力，力争到2030年，热泵生产制造和技术研发能力不断增强，重点热泵产品能效水平提升20%以上。"}, {"title": "人力资源和社会保障部4月3日发布了全国各省、自治区、直辖市最低工资标准情况(截至", "detail": "2025年4\n月1日)。数据显示，目前有21个省份第一档月最低工资标准在2100元及以上，有8个省份第一档月最低\n工资标准超过2300元。"}, {"title": "近日教育部正式上线“中国教师”服务平台及移动端“中国教师”小程序，为全国各级各类", "detail": "学校教师提供\n教师政策资讯、教师培训查询、惠师服务、电子工作证照等多元化服务，标志着我国教师服务迈入数字化\n新阶段。"}, {"title": "目前全球奖金额最高的科学奖项“科学突破奖”2025年度获奖名单4月5日在美国洛杉", "detail": "矶揭晓。本年\n度“科学突破奖”设3个“生命科学突破奖”、2个“基础物理学突破奖”和1个“数学突破奖”共6个单项奖，每个\n奖项的奖金都是300万美元。美籍华裔科学家刘如谦因在基因编辑领域的贡献获得其中一个“生命科学突破\n奖”。"}, {"title": "近日，国家卫生健康委、市场监管总局联合发布《食品安全国家标准灭菌乳》1号修改单，", "detail": "将于今\n年9月16日起正式实施。此次修订明确，生产灭菌乳只能以生乳为原料，不再允许使用复原乳；使用复原\n乳生产的乳品不得标注“纯牛（羊）奶”或“纯牛（羊）乳”，将作为调制乳管理。"}, {"title": "4月7日，广东阳江三山岛500千伏海上风电柔直输电工程全面开工，这是我国首个海陆", "detail": "一体送出工\n程，将广东阳江三山岛的海上风电源源不断送往粤港澳大湾区。该工程起于广东阳江三山岛风电场，止于\n广东江门，线路总长293公里，其中，海底电缆长115公里、陆上输电线路为178公里。工程总投资约103\n亿元。"}, {"title": "今年是国家安全法颁布施行10周年，4月15日是第十个全民国家安全教育日。", "detail": "司法部、全国普法办\n日前印发通知，决定在全国开展2025年全民国家安全教育日普法宣传活动。今年全民国家安全教育日的活\n动主题为“全民国家安全教育走深走实十周年”。"}, {"title": "近日，中共中央、国务院印发了《加快建设农业强国规划（2024－2035年）》，《", "detail": "意见》提出到2027\n年，农业强国建设取得明显进展。乡村全面振兴取得实质性进展，农业农村现代化迈上新台阶。稳产保供\n能力巩固提升，粮食综合生产能力达到1.4万亿斤，重要农产品保持合理自给水平。到2035年，农业强国\n建设取得显著成效。到本世纪中叶，农业强国全面建成。\n健全耕地数量、质量、生态“三位一体”保护制度体系，改革完善耕地占补平衡制度，各类耕地占用纳入\n统一管理，完善补充耕地质量验收机制，确保达到平衡标准。守牢18.65亿亩耕地和15.46亿亩永久基本农\n田保护红线。分区分类开展盐碱耕地治理改良，因地制宜推动盐碱地等耕地后备资源开发。\n全面落实耕地保护和粮食安全党政同责，压实“米袋子”保供责任。健全保障耕地用于种植基本农作物管\n理体系，确保粮食播种面积稳定在17.5亿亩左右、谷物面积14.5亿亩左右。"}, {"title": "4月8日，“雪龙”号极地科考破冰船返回上海，这标志着自然资源部组织的中国第41次", "detail": "南极考察主\n要任务顺利完成。此次考察首次开展了秦岭站越冬考察任务，这也是我国南极考察首次实现长城站、中山\n站、秦岭站“三站越冬”，同时取得一批重要科研成果。"}, {"title": "4月8日，全球最大“华龙一号”核电基地，漳州核电2号机组热态性能试验顺利完成，为", "detail": "后续机组核\n燃料装载、并网发电等工作奠定了基础。漳州核电规划建设6台“华龙一号”核电机组，6台核电机组总装机\n3\n需要纸质原版打印加微信：YM188357\n容量约720万千瓦，全部投产后，每台核电机组每年发电超100亿度清洁电能。"}, {"title": "国务院总理李强4月8日下午同欧盟委员会主席冯德莱恩通电话。", "detail": "李强表示，中方愿同欧方携手努\n力，保持良好顺畅的高层交往，增进政治互信，拓展务实合作，坚持通过对话磋商解决各自关切，推动中\n欧关系不断向好、向前发展。双方要推动新一次中欧战略、经贸、绿色、数字领域高层对话尽早举行。"}, {"title": "近日，中共中央办公厅、国务院办公厅印发《关于加快构建普通高等学校毕业生高质量就业", "detail": "服务体\n系的意见》。《意见》实施就业优先战略，把高校毕业生就业作为重中之重，统筹抓好教育、培训和就业，\n以产业端人才需求和就业端评价反馈为指引，全链条优化培养供给、就业指导、求职招聘、帮扶援助、监\n测评价等服务，开发更多有利于发挥所学所长的就业岗位，完善供需对接机制，力求做到人岗相适、用人\n所长、人尽其才，提升就业质量和稳定性。\n《意见》要求，巩固支持保障体系。建强高校毕业生就业服务机构，按规定落实高校毕业生就业服务\n机构、人员、场地、经费“四到位”要求，打造专业化就业指导教师队伍。"}, {"title": "4月8日，第七届世界大健康博览会在湖北武汉开幕。", "detail": "大会以“AI赋能健康生活”为主题。来自18\n个国家和地区的近700家参展商及一批大健康领域专家学者等参会，展示大健康领域新产品、新技术，探寻\n产业发展新趋势。"}, {"title": "中央周边工作会议4月8日至9日在北京举行。", "detail": "会议指出，我国幅员辽阔、边界线长，周边是实现\n发展繁荣的重要基础、维护国家安全的重点、运筹外交全局的首要、推动构建人类命运共同体的关键。\n会议指出，要统筹国内国际两个大局、发展安全两件大事，高举人类命运共同体旗帜，以建设和平、\n安宁、繁荣、美丽、友好“五大家园”为共同愿景，以睦邻、安邻、富邻、亲诚惠容、命运与共为理念方针，\n以和平、合作、开放、包容的亚洲价值观为基本遵循，以高质量共建“一带一路”为主要平台，以安危与共、\n求同存异、对话协商的亚洲安全模式为战略支撑，携手周边国家共创美好未来。"}, {"title": "国务院关税税则委员会4月9日发布公告称，经国务院批准，自2025年4月10日12", "detail": "时01分起，调\n整《国务院关税税则委员会关于对原产于美国的进口商品加征关税的公告》（税委会公告2025年第4号）\n规定的加征关税税率，由34%提高至84%。"}, {"title": "中共中央党史和文献研究院编辑的《习近平经济文选》第一卷，近日由中央文献出版社出版", "detail": "，在全\n国发行。习近平经济思想是习近平新时代中国特色社会主义思想的重要组成部分，是对新时代经济发展实\n践经验的系统理论概括，是中国共产党不懈探索社会主义经济发展道路形成的宝贵思想结晶，开拓了中国\n特色社会主义政治经济学新境界，为丰富发展马克思主义政治经济学作出了重要原创性贡献，为推动我国\n经济高质量发展、科学应对重大风险挑战、全面建设社会主义现代化国家提供了锐利思想武器。《习近平\n经济文选》第一卷，收入习近平同志2012年11月至2024年12月期间关于经济建设最重要、最基本的著作，\n按时间顺序编排，共有报告、讲话、演讲、指示、批示等74篇。"}, {"title": "4月9日，拉美和加勒比国家共同体第九届峰会在轮值主席国洪都拉斯举行，国家主席习近", "detail": "平向峰会\n致贺信。习近平强调，中拉关系历经国际风云变幻考验，已经进入平等、互利、创新、开放、惠民的新阶\n段。双方政治互信不断深化，务实合作持续拓展，人文交往日益密切，惠及中拉双方人民，树立起南南合\n作的典范。中方愿同地区国家一道，推动中拉命运共同体建设不断得到新发展。"}, {"title": "4月10日，2025年“数据要素×”大赛启动仪式在河北雄安新区成功举办。", "detail": "本次大赛以“数据赋能乘\n数而上”为主题，聚焦数据要素在经济社会各领域的创新应用，现在正式面向全国企事业单位、高校、科研\n院所等开放报名。"}, {"title": "国务院总理李强日前签署国务院令，公布修订后的《婚姻登记条例》。", "detail": "《条例》自2025年5月10\n4\n需要纸质原版打印加微信：YM188357\n日起施行，全文共6章28条。一是增加婚姻家庭服务工作内容。二是实行婚姻登记“全国通办”。三是优化\n婚姻登记服务。"}, {"title": "中国政府网消息，国务院批复，原则同意自然资源部组织起草的《黄河流域国土空间规划（", "detail": "2021—\n2035年）》。到2035年，黄河流域耕地保有量不低于25921.71万亩，其中永久基本农田保护面积不低于21544.88\n万亩；生态保护红线面积不低于39.60万平方千米；城镇开发边界扩展倍数控制在基于2020年城镇建设用\n地规模的1.3倍以内；单位国内生产总值建设用地使用面积下降不少于40%；用水总量不超过国家下达指标。"}, {"title": "4月10日，2025中国移动云智算大会在江苏苏州开幕，大会以“由云向智，共绘算网", "detail": "新生态”为主题。\n本次大会为期两天，聚焦AI时代算力网络革新与产业发展需求，全面展示了中国移动以技术创新推动“由\n云向智”发展，构建“云智算”一体化服务生态，以及AI＋行业服务模式的创新实践。"}, {"title": "当地时间4月10日23时（北京时间4月11日5时），在法国巴黎召开的联合国教科文", "detail": "组织执行局\n第221届会议上，我国推荐的青海坎布拉和重庆云阳两处候选地正式获批联合国教科文组织世界地质公园称\n号。至此，我国世界地质公园增至49处，数量继续稳居世界首位。"}, {"title": "2024年4月11日0时47分，我国在西昌卫星发射中心使用长征三号乙运载火箭，成", "detail": "功将通信技术\n试验卫星十七号发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。通信技术试验卫星十七号主\n要用于开展多频段、高速率卫星通信技术验证。"}, {"title": "4月11日上午，国家主席习近平在北京钓鱼台国宾馆会见来华访问的西班牙首相桑切斯。", "detail": "习近平指\n出，今年是中国和西班牙建立全面战略伙伴关系20周年，中方愿同西班牙打造更有战略定力、更富发展活\n力的全面战略伙伴关系，为两国人民增进福祉，为中欧关系增添动力，也为促进世界和平、稳定、发展作\n出更大贡献。\n习近平指出，中国一直视欧盟为多极世界重要一极，是明确支持欧盟团结发展壮大的主要大国。当前\n形势下，共同打造中欧和平、增长、改革、文明四大伙伴关系具有重要现实意义。"}, {"title": "国务院关税税则委员会4月11日发布公告称，经国务院批准，自2025年4月12日起", "detail": "，对原产于美\n国的进口商品加征关税税率由84%提高至125%。鉴于在目前关税水平下，美国输华商品已无市场接受可能\n性，如果美方后续对中国输美商品继续加征关税，中方将不予理会。"}, {"title": "国务院关于《加快推进服务业扩大开放综合试点工作方案》的批复4月11日发布。", "detail": "根据方案，在已\n有试点地区基础上，将大连市、宁波市、厦门市、青岛市、深圳市、合肥市、福州市、西安市、苏州市等9\n个城市纳入试点范围。"}, {"title": "4月12日，随着宁夏至湖南±800千伏特高压直流输电线路工程重庆段跨长江段导地线", "detail": "全部牵引到\n位，该工程重庆段全线贯通。宁夏至湖南±800千伏特高压直流输电线路工程全长1634.3公里，额定电压±\n800千伏、额定容量800万千瓦，动态投资280.95亿元，是我国首条以输送“沙漠、戈壁、荒漠”新能源大基\n地电量为主的特高压外送通道。"}, {"title": "国务院、中央军委日前公布修订后的《中国人民解放军实施〈中华人民共和国药品管理法〉", "detail": "办法》。\n《办法》自2025年6月1日起施行，共7章60条，军队药品管理工作坚持中国共产党的领导，贯彻习近平\n强军思想，坚持风险管理、全程管控、军地协同的原则，科学严格监管，保障药品的安全、有效、可及。"}, {"title": "国家发展改革委、国家能源局日前印发《关于加快推进虚拟电厂发展的指导意见》，提出到", "detail": "2027年，\n虚拟电厂建设运行管理机制成熟规范，参与电力市场的机制健全完善，全国虚拟电厂调节能力达到2000万\n千瓦以上；到2030年，全国虚拟电厂调节能力达到5000万千瓦以上。"}, {"title": "4月10日至12日，2025全球6G技术与产业生态大会在江苏省南京市举行。", "detail": "本届大会将关注焦点投\n5\n需要纸质原版打印加微信：YM188357\n向未来产业生态，以“共筑创新同享未来”为主题，聚焦6G愿景与关键技术、安全可信、AI与通信等前沿\n主题。"}, {"title": "4月13日，国家主席习近平同印度尼西亚总统普拉博沃互致贺电，庆祝中印尼建交75周", "detail": "年。习近平\n强调，中印尼同为发展中大国和“全球南方”重要力量，双方合作具有战略意义和全球影响。我高度重视中印\n尼关系发展，愿同总统先生一道努力，以庆祝两国建交75周年为契机，进一步深化两国全面战略合作，加\n强多边战略协调，不断丰富中印尼命运共同体的时代内涵，打造发展中大国精诚团结的典范、共同发展的\n样板、南南合作的先锋，共同促进人类进步事业。"}, {"title": "4月13日，第五届中国国际消费品博览会在海南海口正式开馆。", "detail": "本届消博会主题为“共享开放机遇，\n共创美好生活”，展区总面积超过16万平方米，吸引了来自71个国家和地区超过4100个品牌参展，涵盖了\n数字消费、健康消费、绿色消费等新兴消费领域。本次消博会首次设置了人工智能展示活动专区，展区面\n积有约300平方米。"}, {"title": "2025年大阪·关西世博会（大阪世博会）4月13日正式开园，以“共同构建人与自然", "detail": "生命共同体——\n绿色发展的未来社会”为主题的中国馆当天举行了开馆仪式。大阪世博会将持续至10月13日。中国馆是本\n届世博会面积最大的外国自建馆之一，占地面积约3500平方米。"}, {"title": "2025年海南自由贸易港全球产业招商大会4月14日在海南海口举行。", "detail": "大会以“投资海南链接世界”\n为主题，向全球投资者展示海南自由贸易港的建设成果、营商环境和投资机遇，政府部门、内外资企业和\n境内外商协会代表等约3000人参加。"}, {"title": "4月14日，在习近平在越南《人民报》发表题为《志同道合携手前行继往开来续写新篇》", "detail": "的署名文\n章。中国和越南是社会主义友好邻邦，拥有共同理想信念和广泛战略利益。中越命运共同体传承于鲜明的\n红色基因。中越命运共同体发轫于深厚的政治互信。中越命运共同体植根于丰厚的合作沃土。中越命运共\n同体推进于密切的人文交流。\n我们要全面深化中越命运共同体建设，为亚洲乃至世界和平稳定和发展繁荣作出积极贡献。深化战略\n互信，推动社会主义事业发展壮大。坚持合作共赢，增进两国人民福祉。加强人文交流，拉紧民心相通纽\n带。密切多边协作，促进亚洲繁荣振兴。妥善管控分歧，维护地区和平稳定。"}, {"title": "我国最大超深油田——富满油田传来喜讯：累计生产油气产量当量突破2000万吨，成为", "detail": "我国在8000\n米以深复杂领域高质量勘探开发的“深地标杆”。"}, {"title": "日前，《中国环境保护产业发展报告（2024）》发布。", "detail": "《报告》显示，到2024年，我国环保产业年\n营收已经连续三年超过2.2万亿元，覆盖了大气、水、固废、土壤、环境监测、生态修复、减污降碳等重点\n领域。在产业中，民营企业数量占从业单位总数的90%以上，技术水平显著提升。"}, {"title": "4月14日下午，习近平在越共中央驻地同越共中央总书记苏林举行会谈。", "detail": "习近平强调，今年是中越\n建交75周年暨“中越人文交流年”。站在新的历史起点上，双方要继往开来、携手前行，赓续“越中情谊深、\n同志加兄弟”的传统友谊，按照政治互信更高、安全合作更实、务实合作更深、民意基础更牢、多边协调配\n合更紧、分歧管控解决更好的“六个更”总体目标，高质量推动全面战略合作，确保中越命运共同体建设行稳\n致远，为构建人类命运共同体作出新的更大贡献。\n习近平就深化中越命运共同体建设提出六点举措。一是增进更高水平的战略互信。二是建设更加牢固\n的安全屏障。三是拓展更高质量的互利合作。四是系牢更加广泛的民意纽带。五是开展更加紧密的多边协\n作。六是实现更加良性的海上互动。"}, {"title": "为期两天的2025年世界互联网大会亚太峰会4月14日在香港会议展览中心开幕。", "detail": "本次峰会主题是“数\n6\n需要纸质原版打印加微信：YM188357\n智融合引领未来——携手构建网络空间命运共同体”，来自全球50余个国家和地区的政府部门、国际组织、\n企业、民间团体高级别代表以及专家学者等近千名嘉宾参会。"}, {"title": "4月15日是第十个全民国家安全教育日，各地区各部门组织了多种形式的宣传教育活动，", "detail": "提升全民\n国家安全意识。今年全民国家安全教育日宣传教育活动主题为“全民国家安全教育走深走实十周年”。"}, {"title": "4月15日，全球最大的24000箱级双燃料动力集装箱船正式交付，再次刷新我国双燃", "detail": "料集装箱船建\n造纪录。交付后这艘船将用于远东至欧洲航线的货物运输。今天交付的全球最大双燃料动力集装箱船一次\n可承载22万吨货物，24000个左右的集装箱堆叠高度相当于25层楼，被称为海上“超级带货王”。"}, {"title": "4月16日出版的第8期《求是》杂志发表中共中央总书记、国家主席、中央军委主席习近", "detail": "平的重要\n文章《加快建设文化强国》。文章指出，建设文化强国，事关中国式现代化建设全局，事关中华民族复兴\n大业，事关提升国际竞争力。我们要锚定2035年建成文化强国的战略目标，坚持马克思主义这一根本指导\n思想，植根博大精深的中华文明，顺应信息技术发展潮流，不断发展具有强大思想引领力、精神凝聚力、\n价值感召力、国际影响力的新时代中国特色社会主义文化，不断增强人民精神力量，筑牢强国建设、民族\n复兴的文化根基。\n文章指出，我们党是具有高度文化自觉的马克思主义政党，始终站在时代前列，引领文化发展进步，\n带领人民走出了中国特色社会主义文化发展道路。这条道路最本质的特征，就是坚持党的领导。我多次讲\n过，过不了互联网这一关，就过不了长期执政这一关。这里最关键的，就是必须把党管宣传、党管意识形\n态、党管媒体、党管互联网原则落实到位，提升信息化条件下文化领域治理能力，在思想上、精神上、文\n化上筑牢党的执政基础和群众基础。"}, {"title": "国家统计局4月16日发布的最新数据显示，初步核算，2025年一季度国内生产总值3", "detail": "18758亿元，\n按不变价格计算，同比增长5.4%，比上年四季度环比增长1.2%。"}, {"title": "4月16日下午，国家主席习近平同马来西亚总理安瓦尔在布特拉加亚总理官邸举行会谈。", "detail": "习近平指\n出，中马传统友谊跨越千年。两国友好在悠久历史中孕育，在文化交融中生长，在互惠互利中巩固，在风\n雨同舟中升华，展现了以心相交、以诚相待、以义为持、以和为贵的共同价值追求，体现出两国人民的历\n史智慧和勇气，是两国共同的宝贵财富。\n习近平就建设高水平战略性中马命运共同体提出三点意见。一是坚持战略自主，开展高水平战略协作。\n二是凝聚发展合力，打造高质量发展合作标杆。三是传承世代友好，深化文明交流互鉴。"}, {"title": "工业和信息化部组织制定的强制性国家标准《电动汽车用动力蓄电池安全要求》（GB38", "detail": "031-2025）\n日前发布，将于2026年7月1日起开始实施。本次修订内容主要有修订热扩散测试，进一步明确待测电池\n温度要求、上下电状态、观察时间、整车测试条件，技术要求从此前的着火、爆炸前5分钟提供热事件报\n警信号等，调整为不起火、不爆炸(仍需报警)，烟气不对乘员造成伤害等；新增底部撞击测试，考查电池底\n部受到撞击后的防护能力；新增快充循环后安全测试，300次快充循环后进行外部短路测试，要求不起火、\n不爆炸等。"}, {"title": "联合国教科文组织4月17日发布新闻公报，宣布将74项文献遗产新列入其《世界记忆名", "detail": "录》，其\n中包括中国组织申报的《随州曾侯乙编钟》《少林寺碑碣（566—1990）》以及中国与斯里兰卡联合申报的\n郑和遗存《布施锡兰山佛寺碑（1409年2月15日）》。至此，中国共有18项文献遗产入选《世界记忆名\n录》。"}, {"title": "4月17日，全球首艘15万吨级智慧渔业大型养殖工船“国信1号2-1”在中国船舶集", "detail": "团北海造船厂交\n付运营，被正式命名为“鲁即渔养60617”。“国信1号2-1”是全球首艘10万吨级养殖工船“国信1号”的升级版，\n7\n需要纸质原版打印加微信：YM188357\n将以“船载舱养”模式开展大黄鱼、鲑鳟鱼、黄条鰤等名优鱼种养殖，设计年产高品质鱼类约3600吨。"}, {"title": "4月17日，国务院以“加强预期管理，协同推进政策实施和预期引导”为主题，进行第十", "detail": "三次专题学\n习。李强强调，重大战略和改革、发展环境对稳预期都有着重要作用。要加快重大战略和改革举措落实落\n地，说一件、干一件、成一件，引导形成明确稳定的市场预期，实现改革深化和预期强化的正向互动。要\n营造包容的氛围和公平、稳定、可预期的发展环境，主动帮助群众和企业解决困难，进一步改进和完善行\n政执法、规范权力运行，有力保护各类经营主体合法权益。"}, {"title": "近日，工业和信息化部向中国国家铁路集团有限公司批复铁路新一代移动通信（5G-R）", "detail": "系统试验频\n率，支持其在部分线路开展5G-R系统现场技术试验，进一步加速铁路数字化、智能化步伐。"}, {"title": "4月17日晚，国家主席习近平同柬埔寨首相洪玛奈在金边和平大厦举行会谈。", "detail": "两国领导人一致同意\n携手构建新时代全天候中柬命运共同体，宣布2025年为“中柬旅游年”。习近平指出，中柬铁杆友谊拥有深\n厚历史积淀、牢固政治基础、强大内生动力。无论国际风云如何变化，两国始终走在构建人类命运共同体\n前列。双方要以构建新时代全天候中柬命运共同体为新起点，乘势而上，继续落实好新版中柬命运共同体\n行动计划，加强团结合作，加快落实全球发展倡议、全球安全倡议、全球文明倡议，深化更高水平政治互\n信，拓展更高质量互利合作，筑牢更高层次安全保障，开展更高频率人文交流，强化更高标准战略协作，\n更好造福两国人民。"}, {"title": "4月17日14时18分，云能红河电厂700兆瓦高效超超临界循环流化床发电机组顺利", "detail": "完成168小时\n试运行，标志着由东方锅炉研制的世界首台700兆瓦超超临界循环流化床锅炉正式投运。"}, {"title": "在即将到来的第十个“中国航天日”，我国轻舟货运飞船将首次向公众亮相，1：1模型将", "detail": "在上海世博\n展览馆举行的航天科普展上展示。"}, {"title": "近日，教育部等九部门联合印发《关于加快推进教育数字化的意见》。", "detail": "《意见》深入实施国家教育\n数字化战略，坚持应用导向、治理为基，秉承联结为先、内容为本、合作为要，聚焦集成化、智能化、国\n际化，扩大优质教育资源受益面，促进人工智能助力教育变革，加快形成泛在可及的终身教育体系，助力\n建设人人皆学、处处能学、时时可学的学习型社会，为有效应对新一轮科技革命和产业变革、加快建设教\n育强国提供有力支撑。"}, {"title": "4月19日6时51分，我国在太原卫星发射中心使用长征六号改运载火箭，成功将试验二", "detail": "十七号卫星\n01星-06星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。试验二十七号卫星01星-06星主要\n用于空间环境探测及相关技术试验。"}, {"title": "4月19日7时30分，2025北京亦庄半程马拉松暨人形机器人半程马拉松在北京亦庄", "detail": "鸣枪起跑，这也\n是全球首个人类和人形机器人共跑的半程马拉松赛。9000余名大众跑者和近20家机器人企业共同参赛，“人\n机共跑”21.0975公里。"}, {"title": "第二届全国大学生职业规划大赛总决赛颁奖活动4月19日在湖南长沙举行。", "detail": "经过激烈角逐，大赛共\n决出金奖150名、银奖225名、铜奖375名，评出省级优秀组织奖10个、高校优秀组织奖100个、特别贡\n献奖9个。"}, {"title": "2025年4月19日，由成都航空湿租给越捷航空的两架C909飞机正式开通“河内-", "detail": "昆岛-胡志明”航线，\n标志着中国商用飞机在越南开启商业运营。截至目前，印尼翎亚航空、老挝航空、越南越捷航空三家海外\n航空公司已累计使用C909飞机在东南亚开通15条航线，运送旅客超25万人次。"}, {"title": "我国自主研制的大型水陆两栖灭火飞机AG600于4月20日在北京获得中国民航局颁发", "detail": "的型号合格\n证，标志着全球起飞重量最大的民用水陆两栖飞机研制成功并获准进入市场，成为中国特种用途飞机研制\n8\n需要纸质原版打印加微信：YM188357\n和民用航空工业发展的重要里程碑。"}, {"title": "4月19日至20日，以“人工智能赋能医学发展”为主题的2025年中国医学发展大会", "detail": "在北京召开。大\n会汇聚来自数学、人工智能、医学、公共卫生、药学等多学科的顶尖专家，共同探讨人工智能与医学深度\n融合的创新路径与发展方向。"}, {"title": "2025年全国知识产权宣传周活动4月20日启动，今年的主题是“知识产权与人工智能", "detail": "”。宣传周期间\n将举行中国知识产权保护高层论坛。国家知识产权局将举办开放日活动，发布2025专利转化运用优秀案例\n等。"}, {"title": "近日，2025年联合国中文日活动在美国纽约联合国总部拉开帷幕。", "detail": "今年“国际中文日”的主题是“中文：\n穿越时空的礼物”。2010年，联合国将中国传统二十四节气之一的“谷雨”日定为联合国中文日。"}, {"title": "市场监管总局4月21日发布数据显示，截至3月底，全国登记在册民营企业超过5700", "detail": "万户，占企业\n总量的92.3%。"}, {"title": "4月22日是第56个世界地球日。", "detail": "今年的主题是“珍爱地球人与自然和谐共生”，引导全社会支持参\n与自然保护和生态修复。"}, {"title": "近日，中共中央办公厅、国务院办公厅印发《农村基层干部廉洁履行职责规定》，《规定》", "detail": "提出，\n农村基层干部廉洁履行职责应当做到：（一）坚定理想信念，坚持以人民为中心，实现好、维护好、发展\n好群众根本利益；（二）弘扬党的光荣传统和优良作风，求真务实、勇于担当，提高为民服务本领；（三）\n严格遵守党章党规党纪和法律法规，清正廉洁、规范履职，自觉接受监督；（四）带头实践社会主义核心\n价值观，促进新时代农村精神文明建设，推进移风易俗、建设文明乡风。"}, {"title": "近日，中央宣传部等十部门联合印发《新时代职业道德建设实施纲要》，《纲要》强调，要", "detail": "适应推\n进中国式现代化的要求，着眼增强人民精神力量，加强职业道德规范建设，深化职业道德教育引导，强化\n职业道德实践养成，优化职业道德建设环境，推动职业道德建设展现新气象新作为。"}, {"title": "4月22日是世界地球日。", "detail": "草原被誉为地球的“皮肤”，国家林草局草原管理司司长李拥军介绍，近年\n来国家林草局以组织实施“双重”“三北”等工程为抓手，持续推进草原修复治理，年均修复草原超过4600万\n亩。"}, {"title": "4月22日，全球装载量最大的汽车运输船“深圳号”在江苏正式交付启航，计划本周在太", "detail": "仓港完成装\n车作业后开启驶往巴西的航程。“深圳号”总长219.9米、型宽37.7米，拥有16层甲板，配置9200个标准装\n载车位，是目前已投入运营的全球最大装载量汽车运输船。\n914月22日，教育部公布2024年度普通高等学校本科专业备案和审批结果及《普通高等学校本科专业\n目录（2025年）》。最新发布的《普通高等学校本科专业目录（2025年）》有845种专业，包括本次增设\n的29种新专业。在专业设置过程中，以“新工科、新医科、新农科、新文科”建设为引领，推动专业交叉融\n合再出新。"}, {"title": "近日，中共中央、国务院印发《关于实施自由贸易试验区提升战略的意见》，《意见》强调", "detail": "，经过5\n年左右的首创性、集成式探索，实现自由贸易试验区制度型开放水平、系统性改革成效、开放型经济质量\n全面提升，以贸易、投资、资金流动、交通运输、人员往来自由便利和数据安全有序流动为重点的政策体\n系更加完善，科技创新和产业创新深度融合，现代产业集群能级跃升，新质生产力加快发展，打造开放层\n次更高、营商环境更优、辐射作用更强的改革开放新高地。"}, {"title": "4月23日，神舟二十号载人飞行任务新闻发布会在酒泉卫星发射中心举行。", "detail": "神舟二十号载人飞行任\n务乘组由航天员陈冬、陈中瑞、王杰组成，包括2名航天驾驶员和1名飞行工程师。指令长陈冬执行过神\n9\n需要纸质原版打印加微信：YM188357\n舟十一号、神舟十四号载人飞行任务，陈中瑞和王杰均为我国第三批航天员，都是首次执行飞行任务。"}, {"title": "4月23日在山西太原举办的第四届全民阅读大会发布2024年度中国数字阅读报告，报", "detail": "告显示，2024\n年我国数字阅读用户规模为6.7亿，同比增长17.52%。我国数字阅读市场总体营收规模为661.41亿元，同比\n增长16.65%，我国数字阅读作品总量约为6307.26万部，同比增长6.31%。"}, {"title": "4月23日上午，国家主席习近平在北京人民大会堂同来华进行国事访问的阿塞拜疆总统阿", "detail": "利耶夫举\n行会谈。两国元首宣布，建立中阿全面战略伙伴关系。习近平指出，志合者，不以山海为远。尽管国际形\n势风云变幻，但中阿关系万里同契、历久弥坚。两国始终牢记建交初心，坚持相互尊重、公平正义、合作\n共赢，从战略高度和长远角度看待和发展中阿关系。双方要持续增进政治互信，深化务实合作，密切国际\n协作，开启中阿全方位合作新篇章，助力两国发展振兴，更好造福两国人民。"}, {"title": "习近平近日对双拥工作作出重要指示指出，拥军优属、拥政爱民，是我党我军我国人民优良", "detail": "传统和\n特有政治优势。习近平强调，各级党委和政府要关心支持部队建设和改革，主动为广大官兵排忧解难，进\n一步营造关心国防、热爱军队、尊崇军人的良好社会氛围。军队要树牢宗旨意识，积极支援地方建设发展，\n以实际行动为人民造福兴利。"}, {"title": "4月23日，国家主席习近平向气候和公正转型领导人视频峰会发表致辞。", "detail": "习近平强调，人与自然和\n谐共生是中国式现代化的鲜明特点。中国是世界绿色发展的坚定行动派、重要贡献者，自5年前我宣布碳\n达峰碳中和目标以来，中国构建了全球最大、发展最快的可再生能源体系，建成了全球最大、最完整的新\n能源产业链，贡献了全球四分之一的新增绿色面积。无论国际形势如何变化，中国积极应对气候变化的行\n动不会放缓，促进国际合作的努力不会减弱，推动构建人类命运共同体的实践不会停歇。中国愿同各方一\n道，切实履行共同但有区别的责任，各尽所能，团结协作，推动共建清洁、美丽、可持续的世界。"}, {"title": "4月24日上午，国家主席习近平在北京人民大会堂同来华进行国事访问的肯尼亚总统鲁托", "detail": "举行会谈。\n两国元首一致同意将双边关系定位提升至新时代中肯命运共同体。习近平强调，构建命运共同体是相互尊\n重、平等相待、互利共赢、“同球共济”的大道正途。中肯双方要继续坚定支持彼此维护国家主权、安全、发\n展利益，坚定支持彼此探索符合本国国情的发展道路，深化治国理政经验交流，做现代化道路上的同行者\n和真朋友。"}, {"title": "据中国载人航天工程办公室消息，北京时间2025年4月24日17时17分，搭载神舟", "detail": "二十号载人飞船\n的长征二号F遥二十运载火箭在酒泉卫星发射中心点火发射，约10分钟后，神舟二十号载人飞船与火箭成\n功分离，进入预定轨道。目前，航天员乘组状态良好，发射取得圆满成功。神舟二十号的成功发射意味着\n我国已成功将26名航天员共41人次送入太空。"}, {"title": "在第30个世界读书日到来之际，4月23日至25日，第四届全民阅读大会在山西太原举", "detail": "办，主题为\n“培育读书风尚建设文化强国”。大会聚焦推动新时代全民阅读，将举办主论坛等交流活动，发布全国国民\n阅读调查结果，聚焦不同群体阅读需求，开展主题阅读、数字阅读、乡村阅读及阅读权益保障等不同主题\n分论坛。"}, {"title": "由国家文物局主管2024年度全国十大考古新发现4月24日在北京揭晓，四川资阳濛溪", "detail": "河遗址群、\n浙江仙居下汤遗址、甘肃临洮寺洼遗址、西藏康马玛不错遗址、湖北黄陂盘龙城遗址、陕西宝鸡周原遗址、\n北京房山琉璃河遗址、安徽淮南武王墩一号墓、云南晋宁河泊所遗址、新疆喀什莫尔寺遗址入选。"}, {"title": "4月24日，主题为“海上生明月，九天揽星河”的第十个中国航天日主场活动在上海举办。", "detail": "今年是钱\n学森归国70周年，也是我国第一颗人造卫星成功发射55周年。"}, {"title": "据中国载人航天工程办公室消息，神舟二十号载人飞船入轨后，于北京时间2025年4月", "detail": "24日23\n10\n需要纸质原版打印加微信：YM188357\n时49分，成功对接于空间站天和核心舱径向端口，整个对接过程历时约6.5小时。北京时间2025年4月25\n日1时17分，在轨执行任务的神舟十九号航天员乘组顺利打开“家门”，欢迎远道而来的神舟二十号航天员\n乘组入驻中国空间站，这是中国航天史上第6次“太空会师”，也是两名指令长时隔3年后再次相聚“天宫”。"}, {"title": "中共中央政治局4月25日召开会议，分析研究当前经济形势和经济工作。", "detail": "会议指出，要坚持稳中\n求进工作总基调，完整准确全面贯彻新发展理念，加快构建新发展格局，统筹国内经济工作和国际经贸斗\n争，坚定不移办好自己的事，坚定不移扩大高水平对外开放，着力稳就业、稳企业、稳市场、稳预期，以\n高质量发展的确定性应对外部环境急剧变化的不确定性。"}, {"title": "中共中央政治局4月25日下午就加强人工智能发展和监管进行第二十次集体学习。", "detail": "习近平强调，\n人工智能领域要占领先机、赢得优势，必须在基础理论、方法、工具等方面取得突破。\n习近平强调，人工智能作为新技术新领域，政策支持很重要。要综合运用知识产权、财政税收、政府\n采购、设施开放等政策，做好科技金融文章。"}, {"title": "4月25日，第四届全球媒体创新论坛在山东曲阜举行，论坛以“交流互鉴科技赋能——变", "detail": "革发展中\n的文明力量”为主题。来自95个国家和地区的政界人士、国际组织和中外主流媒体机构负责人、驻华使节、\n专家学者、跨国企业代表等约300位嘉宾，以线上线下结合的方式参会。"}, {"title": "国务院4月25日发布批复，同意在海南全岛和秦皇岛等15个城市（地区）设立跨境电子", "detail": "商务综合\n试验区，同时撤销在海口市、三亚市、阿拉山口市设立的跨境电子商务综合试验区。15个城市（地区）包\n括：秦皇岛市、保定市、二连浩特市、丹东市、滁州市、三明市、开封市、新乡市、鄂州市、邵阳市、梧\n州市、北海市、防城港市、广安市、博尔塔拉蒙古自治州。"}, {"title": "近日，中国科学院“地月空间DRO探索研究”A类先导专项通过DRO-A卫星单角锥反", "detail": "射器与1.2m\n口径望远镜地面激光测距系统，成功开展了距离约35万公里的卫星激光测距新技术试验，这是我国首次实\n现地月距离尺度的卫星激光测距。"}, {"title": "当地时间4月26日，中国－中亚外长第六次会晤在阿拉木图举行。", "detail": "王毅就深化中国—中亚合作提\n出中方5点建议。一是坚持讲信修睦。二是坚持互利合作。三是坚持机制建设。四是坚持公平正义。五是\n坚持世代友好。"}, {"title": "4月27日下午，国务院新闻办公室召开新闻发布会，商务部、财政部、文化和旅游部等六", "detail": "部门介绍\n优化离境退税政策、扩大入境消费的有关情况。将离境退税起退点从500元下调至200元，现金退税限额由\n1万元上调至2万元，鼓励各地在大型商圈、步行街等境外旅客聚集地增设退税商店，增加老字号产品、国\n货潮品等中国特色优质产品供应，将“即买即退”服务措施推广至全国，让旅客在购物现场就可以领取退税款。"}, {"title": "4月27日，中国核能行业协会发布《中国核能发展报告2025》蓝皮书。", "detail": "蓝皮书显示，截至目前，我\n国在运、在建和核准建设的核电机组共102台、装机容量达到1.13亿千瓦，核电总体规模首次跃居世界第\n一。"}, {"title": "第二十届中国电影华表奖4月27日在山东青岛揭晓，《第二十条》等10部影片获优秀故", "detail": "事片奖。\n单项奖方面，郭帆凭借《流浪地球2》获优秀导演奖，董润年、应萝佳凭借《年会不能停！》获优秀编剧奖，\n张译凭借《三大队》获优秀男演员奖，惠英红凭借《我爱你！》获优秀女演员奖。"}, {"title": "国务院关于2024年度环境状况和环境保护目标完成情况的报告4月27日提请十四届全", "detail": "国人大常委\n会第十五次会议审议。报告显示，2024年，全国空气质量稳中向好，重污染天气明显减少。地级及以上城\n市细颗粒物（PM2.5）平均浓度为29.3微克/立方米，同比下降2.7%；空气质量优良天数比率为87.2%，同\n比上升1.7个百分点；重污染天数比率为0.9%，同比下降0.7个百分点。\n11\n需要纸质原版打印加微信：YM188357"}, {"title": "2025年4月27日23时54分，我国在西昌卫星发射中心使用长征三号乙运载火箭，", "detail": "成功将天链二\n号05星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。该卫星是我国第二代地球同步轨道数\n据中继卫星，主要用于为飞船、空间站等载人航天器提供数据中继和测控服务，为中、低轨道资源卫星提\n供数据中继和测控服务，为航天器发射提供测控支持。"}, {"title": "庆祝中华全国总工会成立100周年暨全国劳动模范和先进工作者表彰大会4月28日上午", "detail": "在人民大\n会堂隆重举行。习近平指出，100年来的实践充分证明，我国工人阶级不愧是中国共产党最坚实最可靠的阶\n级基础，不愧是我们社会主义国家的领导阶级，不愧是先进生产力和生产关系的代表，不愧是坚持和发展\n中国特色社会主义的主力军。我国工会不愧是党联系职工群众的桥梁和纽带，不愧是社会主义国家政权的\n重要社会支柱，不愧是职工利益的代表者和维护者。"}, {"title": "国家能源局4月28日举行新闻发布会，公开发布了我国首份氢能发展报告。", "detail": "《报告》显示，2024\n年，我国氢能全年生产消费规模超过3650万吨，位列世界第一位。截至2024年底，全球可再生能源制氢项\n目累计建成产能年均超过25万吨，中国占比超过一半，已逐步成为全球可再生能源制氢及相关产业发展的\n引领国家。"}, {"title": "中国贸促会新闻发言人赵萍4月28日表示，本月初，泰国商业部正式函复中国贸促会，确", "detail": "认泰国\n将担任第三届中国国际供应链促进博览会（链博会）主宾国。第三届链博会将于今年7月16日至20日在北\n京举办，展览总面积12万平方米。"}, {"title": "4月29日4时10分，我国在文昌航天发射场使用长征五号乙运载火箭/远征二号上面级", "detail": "，成功将卫\n星互联网低轨03组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "4月29日上午，第八届数字中国建设峰会在福建省福州市开幕。", "detail": "此次峰会主题是“二十五载奋进路数\n字中国谱新篇——数智引领高质量发展”。会议主要包括开幕式、主论坛、分论坛，以及数字中国创新大赛、\n“闽江夜话”、“有福之州·对话未来”等特色活动，并设现场体验区，邀请浙江省、重庆市作为主宾省（市）。"}, {"title": "习近平4月29日在上海考察时强调，上海承担着建设国际科技创新中心的历史使命，要抢", "detail": "抓机遇，\n以服务国家战略为牵引，不断增强科技创新策源功能和高端产业引领功能，加快建成具有全球影响力的科\n技创新高地。"}, {"title": "4月29日上午，国家主席习近平在上海访问金砖国家新开发银行，并会见新开发银行行长", "detail": "罗塞芙。\n习近平强调，“大金砖合作”已经迈入高质量发展阶段，新开发银行也要开启高质量发展的第二个“金色十年”。\n要践行初心，紧贴全球南方发展需求，提供更多高质量、低成本、可持续的基础设施融资。\n12\n需要纸质原版打印加微信：YM188357"}]}, {"month": "2025年5月", "year": 2025, "items": [{"title": "习近平4月30日上午在上海主持召开部分省区市“十五五”时期经济社会发展座谈会并发", "detail": "表重要讲话。\n他强调，科学制定和接续实施五年规划，是我们党治国理政一条重要经验，也是中国特色社会主义一个重\n要政治优势。要统筹谋划，抓住关键性、决定性因素，把握好节奏和进度，注重巩固拓展优势、突破瓶颈\n堵点、补强短板弱项、提高质量效益，与整体目标保持取向一致性。\n习近平强调，“十五五”时期，必须把因地制宜发展新质生产力摆在更加突出的战略位置，以科技创新为\n引领、以实体经济为根基，坚持全面推进传统产业转型升级、积极发展新兴产业、超前布局未来产业并举，\n加快建设现代化产业体系。"}, {"title": "4月30日13时08分，神舟十九号载人飞船返回舱在东风着陆场成功着陆，现场医监医", "detail": "保人员确认航\n天员蔡旭哲、宋令东、王浩泽身体状态良好，神舟十九号载人飞行任务取得圆满成功。"}, {"title": "《中华人民共和国民营经济促进法》已由中华人民共和国第十四届全国人民代表大会常务委", "detail": "员会第十\n五次会议于2025年4月30日通过，自2025年5月20日起施行。\n民营经济是社会主义市场经济的重要组成部分，是推进中国式现代化的生力军，是高质量发展的重要\n基础，是推动我国全面建成社会主义现代化强国、实现中华民族伟大复兴的重要力量。促进民营经济持续、\n健康、高质量发展，是国家长期坚持的重大方针政策。\n国家坚持依法鼓励、支持、引导民营经济发展，更好发挥法治固根本、稳预期、利长远的保障作用。\n国家坚持平等对待、公平竞争、同等保护、共同发展的原则，促进民营经济发展壮大。民营经济组织\n与其他各类经济组织享有平等的法律地位、市场机会和发展权利。"}, {"title": "中国空间站第八批空间科学实验样品4月30日随神舟十九号载人飞船返回舱顺利返回地球。", "detail": "本次返\n回的科学实验样品涉及空间生命科学、空间材料科学等领域的25项实验项目，总重量约37.25公斤。"}, {"title": "5月1日出版的第9期《求是》杂志将发表习近平的重要文章《激励新时代青年在中国式现", "detail": "代化建设\n中挺膺担当》。文章指出，要着力加强对广大青年的政治引领。青年人有理想、敢担当、能吃苦、肯奋斗，\n中国青年才会有力量，党和国家事业发展才能充满希望。\n文章指出，要充分激发新时代青年在中国式现代化建设中挺膺担当。中国式现代化是强国建设、民族\n复兴的唯一正确道路，是一项前无古人的开创性事业。共青团要坚持围绕中心、服务大局，主动对接国家\n重大战略和重大任务，组织动员广大青年立足本职岗位，积极投身中国式现代化建设，在科技创新、乡村\n振兴、绿色发展、社会服务、卫国戍边等各领域各方面工作中争当排头兵和生力军。"}, {"title": "国务院总理李强日前签署国务院令，公布修订后的《中华人民共和国植物新品种保护条例》。", "detail": "《条例》\n自2025年6月1日起施行，全文共8章49条，将保护范围由授权品种的繁殖材料延伸到收获材料，将保护\n环节由生产、繁殖、销售扩展到为繁殖而进行处理、许诺销售、进口、出口、储存，将品种权效力延及授\n权品种的实质性派生品种、与授权品种相比不具备明显区别的品种、为商业目的重复使用授权品种进行生\n产或者繁殖的另一品种。"}, {"title": "5月1日，南宁海关技术中心主持制定的壮锦国家标准正式实施。", "detail": "这也是我国第一个少数民族非遗纺\n织类国家标准。壮族是我国人口最多的少数民族。壮锦，作为首批国家级非物质文化遗产，与宋锦、云锦、\n蜀锦并称“中国四大名锦”，是壮族文化的瑰宝。"}, {"title": "5月1日，位于四川省大渡河流域的世界最高坝——双江口水电站库区完成首次蓄水，标志", "detail": "着电站向\n投产发电迈出重要一步。双江口水电站位于四川省大渡河流域，总装机容量200万千瓦，是国家“十四五”\n能源发展重点项目。\n1\n(cid:3)"}, {"title": "共青团中央5月3日发布数据显示，截至2024年12月底，全国共有共青团员7531", "detail": ".8万名，共青团组\n织439.7万个。2024年共发展团员641.7万名。"}, {"title": "在五四青年节到来之际，习近平给新疆克孜勒苏柯尔克孜自治州阿图什市哈拉峻乡谢依特小", "detail": "学戍边\n支教西部计划志愿者服务队全体队员回信，向全国广大青年致以节日祝贺并提出殷切期望。习近平在回信\n中说，你们响应党的号召到西部边疆地区教书育人，在促进当地教育事业发展、促进民族团结进步、促进\n兴边富民和稳边固边中发挥了积极作用，自身也得到历练和成长。\n希望广大青年坚定理想信念，厚植家国情怀，练就过硬本领，发扬奋斗精神，到祖国和人民最需要的\n地方发光发热，为中国式现代化建设贡献青春力量。"}, {"title": "由深空探测实验室牵头研制的天都一号通导技术试验星成功完成白天强光干扰条件下的地月", "detail": "空间激\n光测距技术试验，在国际上首次打破地月空间卫星激光测距仅能在夜晚作业的时间限制，标志着我国在深\n空轨道精密测量领域取得技术新突破。"}, {"title": "今年是国家湿地公园创建20周年。", "detail": "国家林草局近日发布，20年来，我国高质量推进国家湿地公园建\n设，共设立国家湿地公园903处，有效保护了全国240万公顷湿地，为国家重点野生动植物栖息繁衍提供了\n充足空间。"}, {"title": "我国在安徽合肥设计建造了大科学装置聚变堆主机关键系统综合研究设施——“夸父”项目。", "detail": "这一设\n施可以为未来我国的聚变堆建设提供技术支撑和大型研发测试平台。目前“夸父”项目建设已经进入关键阶段，\n预计将于今年年底全面建成。"}, {"title": "近日，从自然资源部了解到，“十四五”以来，我国持续完善矿山生态修复政策、加强技术", "detail": "和资金保\n障，已在长江、黄河、青藏高原、三北地区等重点区域部署历史遗留矿山生态修复，修复治理面积达120\n万亩，有效促进了资源开发与生态保护相协调，并推动了资源型城市转型发展。"}, {"title": "近日，从人力资源社会保障部了解到，2025年1—3月，全国城镇新增就业308万人", "detail": "，同比增加5万\n人。3月份全国城镇调查失业率为5.2%，比上月下降0.2个百分点。就业形势保持总体稳定。"}, {"title": "国家发展改革委近日发布《中国营商环境发展报告（2025）》，值得一提的是，报告展", "detail": "示我国以“高\n效办成一件事”为牵引提升行政效能和水平的创新实践，具体介绍企业开办、企业信息变更、破产信息核查、\n企业注销等领域“一件事”实施效果。"}, {"title": "5月6日，国家主席习近平同欧洲理事会主席科斯塔、欧盟委员会主席冯德莱恩互致贺电，", "detail": "热烈庆祝\n中国和欧盟建交50周年。习近平指出，中国和欧盟是全面战略伙伴，也是推动多极化的两大力量、支持全\n球化的两大市场、倡导多样性的两大文明。建交50年来，双方各层级、各领域交往密切，对话合作成果丰\n硕，人文交流有声有色，多边协调卓有成效。\n习近平强调，我高度重视中欧关系发展，愿同科斯塔主席和冯德莱恩主席一道努力，以建交50周年为\n契机，总结中欧关系发展经验，深化战略沟通，增进理解互信，巩固伙伴定位，扩大相互开放，妥处摩擦\n分歧，开辟中欧关系更加美好的未来。"}, {"title": "5月6日从安徽省量子计算工程研究中心获悉，本源量子计算科技（合肥）股份有限公司推", "detail": "出支持\n500+量子比特的中国第四代自主量子计算测控系统“本源天机4.0”，标志着我国量子计算产业已具备可复制、\n可迭代的工程化生产能力，为百比特级量子计算机量产奠定产业化基础。"}, {"title": "北京时间5月6日，斯诺克世锦赛决赛第四阶段比赛结束，中国选手赵心童总比分18比1", "detail": "2战胜马\n克威廉姆斯夺得冠军，成为中国首位，也是亚洲首位斯诺克世锦赛冠军，创造了斯诺克运动的历史。"}, {"title": "第137届中国进出口商品交易会（广交会）线下展于5月5日在广州闭幕，到会境外采购", "detail": "商人数和\n2\n(cid:3)\n时政/公基/笔试/面试/真题资料，请加微信：yumi9938\n现场意向出口成交等多项指标刷新历史纪录。截至5月4日，共有来自219个国家和地区的28.89万名境外\n采购商到会，较去年春季同期举行的第135届广交会同比增长17.3%；现场意向出口成交254.4亿美元，同\n比增长3%。"}, {"title": "5月7日，在赴莫斯科对俄罗斯进行国事访问并出席纪念苏联伟大卫国战争胜利80周年庆", "detail": "典之际，\n国家主席习近平在《俄罗斯报》发表题为《以史为鉴共创未来》的署名文章。文章指出，我们要以史为\n鉴，从第二次世界大战的深刻教训和反法西斯战争的伟大胜利中汲取智慧和力量，坚决反对一切形式的霸\n权主义和强权政治，共同创造人类更加美好的未来。国际形势越是变乱交织，我们越要坚持和维护联合国\n权威，坚定维护以联合国为核心的国际体系、以国际法为基础的国际秩序、以联合国宪章宗旨和原则为基\n础的国际关系基本准则，持续推进平等有序的世界多极化、普惠包容的经济全球化。\n当今世界，和平赤字、发展赤字、安全赤字、治理赤字有增无减。我提出推动构建人类命运共同体，\n提出全球发展倡议、全球安全倡议、全球文明倡议，就是为了破解上述赤字，以公平正义为理念积极引领\n全球治理体系变革。"}, {"title": "近日，我国首批5座9000吨级气膜粮仓在中央储备粮长沙直属库充气成型后拔地而起，", "detail": "标志着我国\n第四代新型粮仓正式进入实践应用阶段，我国守护粮食安全又多了一重保障。"}, {"title": "中国气象局日前发布《极地气候变化年报（2024）》，《年报》指出，极地气温延续较", "detail": "常年略偏高\n趋势，2024年，南极大陆年均气温为零下31.79摄氏度，较1991—2020年气候均值略高0.05摄氏度；北极\n地区持续增温，2024年北极地区年均气温为零下6.89摄氏度，较1991年—2020年气候均值高0.65摄氏度。"}, {"title": "当地时间5月6日下午，德国联邦议院进行第二轮投票，选举新任总理。", "detail": "德国联盟党总理候选人弗\n里德里希·默茨获得联邦议院全体议员多数票的支持，正式当选德国新任总理。"}, {"title": "当地时间5月8日上午，俄罗斯总统普京同中国国家主席习近平在莫斯科克里姆林宫举行会", "detail": "谈。习\n近平指出，历史和现实充分证明，持续发展和深化中俄关系，是传承两国人民世代友好的应有之义，是双\n方彼此成就、促进各自发展振兴的必然选择，也是捍卫国际公平正义、推进全球治理体系改革的时代呼唤。\n习近平指出，中俄双方要坚持合作大方向，排除外部干扰，让合作“稳”的基础更坚实、“进”的动能更充\n足。要发挥两国资源禀赋和产业体系互补优势，拓展经贸、能源、农业、航空航天、人工智能等领域高质\n量互利合作。"}, {"title": "国家电网5月8日在济南、兰州同时宣布，陇东—山东±800千伏特高压直流工程竣工投", "detail": "产，标志着\n我国首个“风光火储一体化”大型综合能源基地外送工程建成投运。这条特高压输送的电能超一半是风能、光\n伏、储能等纯绿色电能。"}, {"title": "5月8日，海洋石油工程股份有限公司发布消息，我国首艘深水铺管起重船“海洋石油20", "detail": "1”从广东珠\n海高栏国际码头启航，驶向中东区域海管作业现场。这是该船首次进入国际市场作业，对提升我国大型海\n洋工程船舶国际化运营能力具有重要意义。"}, {"title": "日前从中国企业国有产权交易机构协会了解到，2024年全国产权市场累计完成各类交易", "detail": "项目逾1.13\n亿宗，成交总额达到25.42万亿元，同比增长0.16%。"}, {"title": "5月9日，国家主席习近平同瑞典国王卡尔十六世·古斯塔夫互致贺电，庆祝两国建交75", "detail": "周年。习\n近平指出，瑞典是第一批同新中国建交的欧洲国家之一。建交75年来，中瑞关系总体保持平稳，两国经贸、\n科技、教育、人文等合作不断拓展，取得积极成果。"}, {"title": "当地时间5月9日，俄罗斯举行盛大庆典，纪念苏联伟大卫国战争胜利80周年。", "detail": "国家主席习近平和\n来自世界20多个国家及国际组织领导人应邀出席庆典。\n3\n(cid:3)"}, {"title": "5月9日从教育部获悉，自2024年1月世界数字教育联盟正式成立以来，得到国际各方", "detail": "热烈响应。\n截至2025年4月底，联盟成员总数达115个，包含来自43个国家和地区的国际组织、高校、科研机构及领\n军企业。"}, {"title": "梵蒂冈城消息：来自美国的枢机主教罗伯特·普雷沃斯特5月8日在罗马教皇选举中当选第", "detail": "267任\n天主教罗马教皇，称为利奥十四世。"}, {"title": "中国残疾人联合会5月8日发布《2024年残疾人事业发展统计公报》显示，2024年", "detail": "全国城乡持证残\n疾人就业人数为914.4万人，新增51.2万人。"}, {"title": "5月9日在京发布的《2024中国网络文学发展研究报告》显示，截至2024年底，中", "detail": "国网络文学阅读\n市场规模达430.6亿元，同比增长6.8%；网络文学用户数量达5.75亿，同比增长10.58%。"}, {"title": "2025世界品牌莫干山大会5月10日在浙江德清开幕。", "detail": "本次大会以“品牌，让世界更美好”为主题，搭\n建品牌交流对话平台，汇聚相关政府部门、中外企业、高等院校、行业协会等深入探讨品牌建设，发出全\n球品牌声音。获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "日前，国务院办公厅印发《关于进一步加强困境儿童福利保障工作的意见》，《意见》坚持", "detail": "儿童优\n先发展和最有利于儿童的原则，按照保障基本、优化服务、维护权益、促进发展的工作思路，加强科学分\n类，强化精准识别，有效提升困境儿童福利保障水平。"}, {"title": "教育部等九部门近日联合印发《关于办好2025年职业教育活动周的通知》，部署启动2", "detail": "025年职业教\n育活动周。今年职业教育活动周时间为5月11日至17日，主题为“一技在手，一生无忧”。"}, {"title": "5月11日，金沙江上游川藏段装机规模最大的水电站——叶巴滩水电站大坝成功取出一根", "detail": "长度38.10\n米的混凝土芯样，相当于12层楼高，打破国内同类坝型大坝取芯纪录。叶巴滩水电站地处四川甘孜州白玉\n县与西藏昌都市贡觉县交界处的金沙江上游，总装机容量224万千瓦，水电站最大坝高217米，是我国在建\n海拔最高双曲拱坝。"}, {"title": "由中国能源建设集团设计建造的世界首台（套）660兆瓦人工硐室型压缩空气储能电站示", "detail": "范项目通过\n可研评审，5月8日正式落地甘肃酒泉敦煌，标志着我国压气储能行业正迈向单机功率600兆瓦级新时代。"}, {"title": "5月8日至11日，以“科技引领创享未来”为主题的第二十七届中国北京国际科技产业博", "detail": "览会（简称\n北京科博会）在国家会议中心举办。据了解，本届北京科博会设有信息科技、智能制造、医药健康、绿色\n双碳、数字经济和区域创新6个专题展区，展览总面积约5万平方米，吸引800余家中外企业和机构参展。"}, {"title": "2025年5月11日21时27分，我国在太原卫星发射中心使用长征六号改运载火箭，", "detail": "成功将遥感四十\n号02组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。该卫星主要用于开展电磁环境探\n测及相关技术试验。"}, {"title": "2025年5月12日是第17个全国防灾减灾日，主题是“人人讲安全、个个会应急——", "detail": "排查身边灾害隐\n患”。"}, {"title": "国务院新闻办公室5月12日发布《新时代的中国国家安全》白皮书，白皮书介绍，总体国", "detail": "家安全观\n是新中国成立以来第一个被确立为国家安全工作指导思想的重大战略思想，是习近平新时代中国特色社会\n主义思想的重要组成部分，是当代中国对世界的重要思想理论贡献。新时代的中国国家安全，坚持中国特\n色国家安全道路，是总体的、系统的、相对的大安全，是以人民安全为宗旨、以政治安全为根本、以国家\n利益为准则的安全，是服务和促进高质量发展的安全，是根据经济社会发展动态调整的安全，是支撑进一\n步扩大高水平开放的安全，是在法治轨道上规范运行的安全。"}, {"title": "国家粮食和物资储备局最新发布，目前，2024年度秋粮旺季收购完成，累计收购秋粮3", "detail": ".45亿吨，为\n4\n(cid:3)\n时政/公基/笔试/面试/真题资料，请加微信：yumi9938\n近年来较高水平。秋粮收购占全年粮食收购量的四分之三左右。"}, {"title": "5月12日是国际护士节，红十字国际委员会公布了第五十届南丁格尔奖获奖者名单，共有", "detail": "来自17个\n国家的35名护理人员获得南丁格尔奖。经中国红十字会评选推荐，我国有7名护理工作者获此殊荣，人数\n最多。今年我国护士节主题为“关爱护士队伍，守护人民健康”。目前，我国注册护士总数近600万。"}, {"title": "2025年5月13日02时09分，我国在西昌卫星发射中心使用长征三号丙运载火箭，", "detail": "成功将通信技术\n试验卫星十九号发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。该卫星主要用于开展多频段、\n高速率卫星通信技术验证。"}, {"title": "5月13日上午，国家主席习近平在国家会议中心出席中国－拉美和加勒比国家共同体论坛", "detail": "第四届部\n长级会议开幕式并发表题为《谱写构建中拉命运共同体新篇章》的主旨讲话。习近平指出，2015年，我同\n拉美和加勒比国家代表一道，在北京出席中拉论坛首届部长级会议开幕式，宣告中拉论坛成立。10年来，\n在双方精心培育下，中拉论坛已经从一棵稚嫩幼苗长成挺拔大树。我们携手并肩、相互支持；我们勇立潮\n头、合作共赢；我们守望相助、共克时艰；我们团结协作、勇于担当。\n事实证明，中拉已经成为携手共进的命运共同体，其鲜明底色是平等相待，强大动力是互利共赢，胸\n怀品格是开放包容，根本追求是造福人民，具有蓬勃生命力和广阔发展前景。\n习近平强调，当前，世界百年变局加速演进，多重风险交织叠加，各国唯有团结协作，才能维护世界\n和平稳定，促进全球发展繁荣。中方愿同拉方携手启动五大工程，共谋发展振兴，共建中拉命运共同体。\n一是团结工程。二是发展工程。三是文明工程。四是和平工程。五是民心工程。"}, {"title": "5月13日下午，国家主席习近平在北京人民大会堂同来华进行国事访问的巴西总统卢拉举", "detail": "行会谈。\n习近平强调，站在新的历史起点，中巴双方一要坚持战略互信；二要坚持扩大合作；三要坚持人文交流；\n四要坚持多边协作。"}, {"title": "中国石化5月13日宣布，旗下中原油田部署在四川盆地普光地区的铁北1侧HF井垂深超", "detail": "过5300米，\n试产获高产工业气流，该井刷新了我国页岩气井垂深纪录，助力四川盆地超深层页岩气开发。"}, {"title": "5月14日12时12分，我国在酒泉卫星发射中心使用长征二号丁运载火箭，成功将太空", "detail": "计算卫星星\n座发射升空，卫星顺利进入预定轨道，标志着全球首个太空计算卫星星座成功发射。"}, {"title": "5月14日，第十二届中国国际警用装备博览会在北京首钢国际会展中心开幕。", "detail": "本届警博会以“新技术、\n新装备、新质战斗力”为主题，以“简约、专业、精彩”为办展理念，广泛邀请国内外警用装备企业和科研机\n构参展，展示新技术在警用装备上的最新应用，展现警用技术装备发展成就。"}, {"title": "5月14日下午，2025世界数字教育大会在湖北武汉开幕，大会以“教育发展与变革：", "detail": "智能时代”主题，\n吸引了来自全球数十个国家和地区的教育部门负责人、国内外大中小学校校长和师生代表、数字技术企业\n代表等齐聚在一起，来共商全球数字教育的未来。"}, {"title": "中央网信办、农业农村部、国家发展改革委、工业和信息化部近日联合印发《2025年数", "detail": "字乡村发展\n工作要点》，工作要点明确，到2025年底，数字技术在确保国家粮食安全、确保不发生规模性返贫致贫中\n的作用更加彰显。全国行政村5G通达率超过90%，农村地区互联网普及率稳步提升，农业生产信息化率进\n一步提升，农产品网络零售额持续稳定增长，乡村数字治理效能、信息服务水平不断增强，数字技术加速\n推动城乡差距缩小、促进城乡融合发展。"}, {"title": "国务院办公厅日前印发《国务院2025年度立法工作计划》，《国务院立法计划》提出，", "detail": "国务院2025\n年度立法工作的总体要求是，坚持党的领导、人民当家作主、依法治国有机统一，统筹推进国内法治和涉\n外法治，深化立法领域改革，加强政府立法审查，坚持立改废释并举，加强重点领域、新兴领域、涉外领\n5\n(cid:3)\n时政/公基/笔试/面试/真题资料，请加微信：yumi9938\n域立法，提高立法质量，完善以宪法为核心的中国特色社会主义法律体系，发挥好法治的引导、推动、规\n范和保障作用，为以中国式现代化全面推进强国建设、民族复兴伟业提供坚实法治保障。"}, {"title": "中共中央办公厅、国务院办公厅近日印发《关于持续推进城市更新行动的意见》，要求坚持", "detail": "稳中求\n进工作总基调，转变城市开发建设方式，建立可持续的城市更新模式和政策法规，大力实施城市更新，促\n进城市结构优化、功能完善、文脉赓续、品质提升，打造宜居、韧性、智慧城市。"}, {"title": "近日，中央军委决定，调整组建中国人民解放军陆军兵种大学、中国人民解放军信息支援部", "detail": "队工程\n大学、中国人民解放军联勤保障部队工程大学等3所院校，均为高等教育院校，面向社会招收普通高中毕\n业生。其中，陆军兵种大学以陆军装甲兵学院、陆军炮兵防空兵学院为基础组建，校本部位于安徽合肥；\n信息支援部队工程大学以国防科技大学信息通信学院、陆军工程大学通信士官学校为基础组建，校本部位\n于湖北武汉；联勤保障部队工程大学以陆军勤务学院、陆军军事交通学院本部及所属汽车士官学校为基础\n组建，校本部位于重庆。"}, {"title": "5月16日出版的第10期《求是》杂志将发表习近平的重要文章《锲而不舍落实中央八项", "detail": "规定精神，\n以优良党风引领社风民风》。这是习近平总书记2012年12月至2025年3月期间有关重要论述的节录。文\n章强调，党风问题关系执政党的生死存亡。经过新时代全面从严治党的革命性锻造，纪律松弛、作风飘浮\n状况显著改变，真管真严、敢管敢严、长管长严氛围基本形成，党风政风焕然一新，社风民风持续向好，\n重塑了党在人民心中的形象。获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "5月15日上午，以“共享数字发展新机遇共建中拉网络空间命运共同体”为主题的中拉互", "detail": "联网发展与\n合作论坛在陕西西安开幕。论坛上，拉美和加勒比国家政府部门代表致辞，一起聆听他们的观点。"}, {"title": "第七次全国自强模范暨助残先进表彰大会5月16日在京召开。", "detail": "习近平作出重要指示，习近平强调，\n各级党委和政府要高度重视残疾人工作，持续提升残疾人公共服务质量，积极营造全社会理解、尊重、关\n心、帮助残疾人的良好氛围和环境。各级残联组织和广大残疾人工作者要不断提高服务能力和水平，努力\n做残疾人信得过、靠得住的知心人、贴心人。"}, {"title": "5月16日上午，在2025世界数字教育大会上，教育部发布《中国智慧教育白皮书》，", "detail": "数据显示，国\n家智慧教育平台注册用户已突破1.64亿，覆盖220余个国家和地区，成为全球最大的教育资源数字化中心。"}, {"title": "国家数据局综合司于近日印发《数字中国建设2025年行动方案》，方案提出，以数据要", "detail": "素市场化配\n置改革为主线，加快培育全国一体化数据市场，因地制宜发展以数据为关键要素的数字经济，全面提升数\n字中国建设水平。到2025年底，数字中国建设取得重要进展，数字领域新质生产力不断壮大，数字经济发\n展质量和效益大幅提升，数字经济核心产业增加值占国内生产总值比重超过10%，数据要素市场建设稳步\n推进。"}, {"title": "5月15日，国务院召开做强国内大循环工作推进会，李强指出，内需为主导、内部可循环", "detail": "是大国经\n济的独有优势。结合现阶段我国发展实际，做强国内大循环重点要体现在四个方面。一是资源要素的高效\n配置；二是科技创新和产业创新的深度融合；三是产业链供应链的自主完备；四是供给和需求的动态平衡。"}, {"title": "5月17日12时12分，朱雀二号改进型遥二运载火箭在东风商业航天创新试验区发射升", "detail": "空，将搭载\n的天仪29星、天仪34星、天仪35星、天仪42星、天仪45星、天仪46星共6颗卫星顺利送入预定轨道，\n飞行试验任务获得圆满成功。"}, {"title": "5月17日，国家主席习近平向阿拉伯国家联盟首脑理事会会议轮值主席伊拉克总统拉希德", "detail": "致贺信，\n祝贺第三十四届阿拉伯国家联盟首脑理事会会议在巴格达召开。习近平强调，展望未来，中国将始终做阿\n拉伯国家值得信赖的朋友和伙伴，坚定站在阿拉伯国家正义事业一边。中国愿同阿拉伯国家一道努力，深\n6\n(cid:3)\n时政/公基/笔试/面试/真题资料，请加微信：yumi9938\n化政治互信，促进互利合作，增进人文交流，在各自现代化道路上携手前行，构建更高水平中阿命运共同\n体。"}, {"title": "国家统计局公布2024年城镇单位就业人员年平均工资情况。", "detail": "2024年，全国城镇非私营单位就业人员\n年平均工资124110元，比上年增加3412元，名义增长2.8%，按可比口径增长2.6%。2024年，全国城镇私\n营单位就业人员年平均工资69476元，比上年增加1136元，名义增长1.7%，按可比口径增长4.0%。"}, {"title": "5月17日，第十一届世界雷达博览会在安徽合肥开幕，本届雷达博览会以“共享创新成果", "detail": "，为新质生\n产力发展注入活力”为主题，设有“智能电子装备及产业链”“行业应用”“新一代信息技术”和“户外实装”等多个\n展区，吸引了全球600多家企业参展。"}, {"title": "5月17日至18日，中国科学院第二十一届公众科学日正式启动。", "detail": "本届公众科学日以“以科学之问启\n未来新程”为主题，135个中国科学院院属单位将组织近400场科普活动，20余位中国科学院院士围绕公众\n感兴趣的热门话题开展科普讲座、在线问答和互动交流，讲解最新、最前沿的科研成果，激励年轻人投身\n科学事业。"}, {"title": "2025年国际博物馆日中国主会场活动5月18日在北京大运河博物馆举行。", "detail": "国家文物局发布最新数据\n显示，2024年全国博物馆举办陈列展览4.3万个、教育活动51.1万场，接待观众14.9亿人次。截至2024年\n底，全国备案博物馆总数达7046家，较上一年增加213家。"}, {"title": "中国载人航天工程办公室最新发布消息，近日，科研人员首次公布在我国空间站发现的一个", "detail": "微生物\n新物种，并将其命名为“天宫尼尔菌”。此次微生物新物种发现是在空间站工程航天技术试验项目支持下实现\n的。"}, {"title": "5月18日，《2025中国卫星导航与位置服务产业发展白皮书》发布。", "detail": "2024年，我国卫星导航与位置\n服务产业总产值达5758亿元人民币，同比增长7.39%。卫星导航专利申请总量累计突破12.9万件，继续保\n持全球领先。"}, {"title": "5月18日，第二十七届海峡两岸经贸交易会在福建福州开幕。", "detail": "本届海峡两岸经贸交易会以“深化两岸\n融合、建设第一家园”为主题，将全面展现福建建设两岸融合发展示范区标志性成果，不断强化经贸合作功\n能，持续彰显招商引资平台实效。"}, {"title": "5月18日，AG600“鲲龙”批产首架机（1101）在广东珠海成功完成生产试飞，", "detail": "表明该架机生产符合型\n号设计要求，达到安全可用状态，具备出厂条件，标志着AG600飞机通过取得生产许可证（PC）的关键环\n节，实物状态满足PC构型要求。"}, {"title": "2025年5月19日15时38分，我国太原卫星发射中心在山东附近海域成功发射谷神", "detail": "星一号海射型遥\n五运载火箭，搭载发射的天启星座05组卫星顺利进入预定轨道，飞行试验任务获得圆满成功。"}, {"title": "5月19日，2025年“5·19中国旅游日”主会场活动在浙江省宁波市宁海县举行。", "detail": "今年“5·19中国旅\n游日”活动主题为“锦绣山河，美好旅程”，活动时间为4月21日至5月31日。截至目前，国家5A级旅游景\n区共有358家。"}, {"title": "5月20日，2025年上海合作组织减贫和可持续发展论坛在陕西西安开幕，本届论坛主", "detail": "题为“持续减贫\n合作发展——推动上合组织国家减贫和可持续发展”。国家主席习近平向2025年上海合作组织减贫和可持续\n发展论坛致贺信。"}, {"title": "2025年5月20日19时50分，我国在文昌航天发射场使用长征七号改运载火箭，成", "detail": "功将中星3B卫\n星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。该卫星主要用于为用户提供话音、数据、\n广播电视传输业务。\n7\n(cid:3)"}, {"title": "习近平近日对“十五五”规划编制工作作出重要指示强调，科学制定和接续实施五年规划，", "detail": "是我们党\n治国理政一条重要经验，也是中国特色社会主义一个重要政治优势。编制和实施“十五五”规划，对于全面落\n实党的二十大战略部署、推进中国式现代化意义重大。要坚持科学决策、民主决策、依法决策，把顶层设\n计和问计于民统一起来，加强调研论证，广泛凝聚共识，以多种方式听取人民群众和社会各界的意见建议，\n充分吸收干部群众在实践中创造的新鲜经验，注重目标任务和政策举措的系统性整体性协同性，高质量完\n成规划编制工作。获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "第78届世界卫生大会5月19日在瑞士日内瓦开幕，本届大会的主题是“共创健康世界”。", "detail": "本届大会备\n受期待的一项内容是审议“大流行协定”。世卫组织4月16日宣布，经过三年多的密集谈判，世卫组织成员\n国就“大流行协定”草案达成一致。"}, {"title": "习近平近日在河南考察时强调，新时代新征程，河南要认真落实党中央关于中部地区加快崛", "detail": "起、黄\n河流域生态保护和高质量发展等战略部署，坚持稳中求进工作总基调，全面深化改革开放，着力建设现代\n化产业体系和农业强省，着力改善民生、加强社会治理，着力加强生态环境保护，着力推动文化繁荣兴盛，\n以高质量发展和高效能治理奋力谱写中原大地推进中国式现代化新篇章。\n习近平指出，高质量发展是中国式现代化的必然要求。面对复杂的外部环境，要坚定信心，坚定不移\n办好自己的事，坚定不移扩大高水平对外开放，着力稳就业、稳企业、稳市场、稳预期，以高质量发展的\n确定性应对各种不确定性。河南作为经济大省，要进一步夯实实体经济这个根基，以科技创新为引领，因\n地制宜发展新质生产力，提升现代化产业体系对高质量发展的支撑能力。"}, {"title": "5月20日，第三届国际农业生物多样性大会在云南昆明开幕。", "detail": "大会以“农业生物多样性繁荣人类和地\n球”为主题，将提供一个分享和管理农业生物多样性知识、技术和经验的平台，共同探讨农业生物多样性的\n研究、保护与可持续发展，开展全球农业生物多样性保护和利用的现状、挑战和趋势的交流与评估，共商\n农业生物多样性保护与可持续利用大计，推动构建更具韧性的全球粮食系统。"}, {"title": "2025年5月21日12时05分，力箭一号遥七运载火箭在东风商业航天创新试验区发", "detail": "射升空，将搭载\n的泰景三号04星、泰景四号02A星、星睿十一号卫星、星迹源一号卫星、立方108001星、西光壹号02星\n共6颗卫星顺利送入预定轨道，飞行试验任务获得圆满成功。"}, {"title": "5月21日，我国首套具有自主知识产权的智能钻井系统——“长龙号”智能钻井系统正式", "detail": "投入使用，\n对推动我国能源行业数智化转型具有重要意义。“长龙号”智能钻井系统集智能钻机、智能井场、智能决策平\n台于一体，可为地下近万米油气勘探开发提供智能工程技术。"}, {"title": "商务部5月21日对外发布，5月20日，中国—东盟经贸部长特别会议以线上方式举行，", "detail": "双方经贸部\n长共同宣布全面完成中国—东盟自贸区3.0版谈判。"}, {"title": "近日，海军“吉祥方舟”号医院船在黄海某海域开展多要素、全流程医疗救护演练。", "detail": "海军“吉祥方舟”\n号医院船，舷号为868，是我国自主设计建造的第三艘万吨级远洋医院船。也是目前我国最新、最先进的医\n院船。"}, {"title": "5月21日，国际大坝委员会第28届大会在四川成都开幕。", "detail": "本届大会以“共同的挑战、共享的未来、\n更好的大坝”为主题，围绕适应气候变化的大坝和水库、适应未来需要的堤坝、面向极端水文事件的堤坝安\n全、大坝抗震性能与安全等4大议题研讨交流。会上，国际大坝委员会签署发布了《世界成都宣言》。国\n际大坝委员会每年召开一次年会、每三年召开一次大会，是世界坝工领域专业水平最高、参加范围最广、\n影响力最大的学术会议。"}, {"title": "5月21日是联合国确定的“国际茶日”。", "detail": "当天上午，2025年“国际茶日”中国主场活动在杭州国际博览\n8\n(cid:3)\n时政/公基/笔试/面试/真题资料，请加微信：yumi9938\n中心启动。主场活动围绕“茶和世界、共品共享”主题，通过“茶文化、茶产业、茶科技”三大篇章，以文化讲\n述、艺术表演、特色产品体验等方式，聚焦中国茶文化的深厚底蕴与创新活力，并进行交流。"}, {"title": "5月21日，第九届丝绸之路国际博览会暨中国东西部合作与投资贸易洽谈会在陕西西安开", "detail": "幕。本届\n丝博会以“丝路融通·开放合作”为主题，会期为5月21日至25日。本届丝博会围绕国际省际交流合作、陕\n西比较优势、重点产业和消费促进等主题，在西安国际会展中心设置丝路优品展、省际合作展、科技创新\n展、低空经济展、交通物流展、文旅消费展等6个展区，总展示面积7.2万平方米。"}, {"title": "5月22日上午，第四届中国—中东欧国家博览会暨国际消费品博览会在浙江宁波开幕。", "detail": "作为我国唯\n一面向中东欧国家的国家级机制性展会，本届博览会以“向新向实向未来”为主题。由斯洛文尼亚和斯洛伐\n克担任主宾国，黑龙江省担任主题省。"}, {"title": "5月22日，第二十一届中国（深圳）国际文化产业博览交易会在深圳国际会展中心开幕，", "detail": "本届文博\n会以“创新引领潮流，创意点亮生活”为主题，展会时间定于5月22日至26日。"}, {"title": "5月22日，第七届中国西部国际投资贸易洽谈会（简称“西洽会”）在重庆开幕。", "detail": "本届西洽会以“新西\n部、新制造、新服务”为主题，来自39个国家（地区）的1300余家企业（机构）参展参会，会期将持续到\n5月25日。"}, {"title": "总部位于上海的金砖国家新开发银行5月22日宣布，阿尔及利亚正式成为新成员国。", "detail": "2021年，新开\n发银行启动扩员。截至目前，孟加拉国、埃及、阿拉伯联合酋长国和阿尔及利亚成为银行的新正式成员国。\n新开发银行是巴西、俄罗斯、印度、中国、南非于2015年共同成立的多边开发银行，旨在为金砖国家及其\n他新兴市场国家和发展中国家的基础设施和可持续发展项目调动资源。"}, {"title": "5月22日下午，2025年全球贸易投资促进峰会在北京钓鱼台国宾馆举行，峰会主题为", "detail": "“拥抱数智时代，\n携手共同发展”，来自48个国家和地区的工商界人士围绕数字智能时代全球贸易投资合作等话题展开讨论。"}, {"title": "5月23日，以“共建美好家园共创繁荣未来”为主题的2025上合组织国家媒体合作论", "detail": "坛在新疆维吾\n尔自治区乌鲁木齐市举行。来自上海合作组织成员国、观察员国和对话伙伴共26个国家的300余位主流媒\n体代表、有关部门负责同志、专家学者和企业代表等齐聚一堂、共商合作。"}, {"title": "近日，生态环境部等部门印发的《美丽河湖保护与建设行动方案（2025—2027年）", "detail": "》对外发布。这\n份行动方案提出，大力推进美丽河湖保护与建设，到2027年，美丽河湖建成率达到40%左右；到2030年，\n美丽河湖建设取得明显成效；到2035年，美丽河湖基本建成。"}, {"title": "国务院总理李强5月23日主持召开国务院常务会议，审议通过《制造业绿色低碳发展行动", "detail": "方案（2025\n－2027年）》，研究进一步健全横向生态保护补偿机制有关举措，讨论《中华人民共和国食品安全法（修\n正草案）》。会议指出，建立成本共担、效益共享、合作共治的横向生态保护补偿机制，对于加强生态环\n境保护、促进区域间协同发展具有重要意义。要推动建立覆盖更加全面、权责更加清晰、方式更加多元、\n治理更加高效的横向生态保护补偿机制，进一步细化重点任务和落实举措，实现生态产品供给地与受益地\n良性互动。获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "5月23日，主题为“步入低空经济新时代”的“2025第九届世界无人机大会暨国际低", "detail": "空经济与无人系统\n博览会/第十届深圳国际无人机展览会”在深圳会展中心开幕，会期三天。来自全国各地相关部门和机构，\n以及100多个国家和地区的企业人士、专家、学者共1200余人出席开幕式。"}, {"title": "第十一届中国国际养老服务业博览会于5月21日—23日在北京举办，本届博览会聚焦“", "detail": "携手共促新\n质生产力，探索银发经济新未来”的主题，设立国际和国内品牌展区、智慧养老信息技术展区、适老环境与\n设备用品展区、涉老服务人才培养展区、养老金融与法律服务展区、老年健康食品展区等10个展区，并聚\n9\n(cid:3)\n时政/公基/笔试/面试/真题资料，请加微信：yumi9938\n合国际优质资源举办论坛和相关活动，引领养老服务行业高质量发展。"}, {"title": "近日，甘肃皋兰什川古梨园系统、浙江德清淡水珍珠复合养殖系统和福建福鼎白茶文化系统", "detail": "三项遗\n产系统顺利通过专家评审，正式被联合国粮农组织认定为全球重要农业文化遗产。截至2025年5月，我国\n全球重要农业文化遗产增至25项，数量继续保持世界首位。"}, {"title": "5月23日上午，第63届高等教育博览会在吉林长春开幕。", "detail": "本届高博会以“融合·创新·引领：服务\n高等教育强国建设”为主题，聚焦新时代高等教育改革与产教融合发展，吸引了全国千余所高校及科研机构、\n800余家科技企业参与，展览面积超12万平方米，通过展览展示、高端论坛、政企签约等系列活动，搭建\n起教育、科技、人才深度融合的国家级平台。"}, {"title": "5月25日，第二十届中国西部国际博览会在四川省成都市开幕，主题为“深化改革增动能", "detail": "扩大开\n放促发展”，锚定全球产业链供应链融合新坐标，以更锐意进取的开放格局与创新实践，为构建双循环新发\n展格局注入磅礴动能。"}, {"title": "5月25日，2025国家新质生产力与智能产业发展会议在北京举办。", "detail": "本次会议以“向新而行·以质致\n远”为主题，邀请了8位院士及500余名来自学术界和产业界的专家学者参会。"}, {"title": "5月25日，我国首个大型锂钠混合储能站——南方电网宝池储能站在云南投产。", "detail": "宝池储能站占地面\n积有5个足球场大小，装机容量达到400兆瓦时，每年可调节电量5.8亿度，相当于27万户居民一年的用\n电量，其中绿电占比高达98%。"}, {"title": "近日，从正在四川成都召开的国际大坝委员会第28届大会上了解到，截至2024年12", "detail": "月，我国已建\n成大坝9.4万多座，全国水电累计装机容量达4.36亿千瓦，数量及装机规模居世界第一。"}, {"title": "5月26日，2025文化强国建设高峰论坛在广东深圳开幕。", "detail": "本届论坛主题为“深化文化体制机制改革\n激发文化创新创造活力”。"}, {"title": "习近平5月26日致信祝贺复旦大学建校120周年，向全体师生员工和广大校友致以热烈", "detail": "的祝贺。\n习近平强调，新起点上，希望复旦大学坚持不懈用新时代中国特色社会主义思想铸魂育人，深化教育科研\n改革，推动科技自主创新和人才自主培养良性互动，推动哲学社会科学知识创新、理论创新、方法创新，\n不断提升服务国家重大战略和区域经济社会发展能力，为以中国式现代化全面推进强国建设、民族复兴伟\n业不断作出新贡献。"}, {"title": "国务院、中央军委日前公布《重要军工设施保护条例》，自2025年9月15日起施行。", "detail": "《条例》旨\n在保护重要军工设施的安全，保障重要军工设施的使用效能和军工科研、生产等活动的正常进行，加强国\n防现代化建设。《条例》共7章51条。"}, {"title": "近日，《中共中央办公厅国务院办公厅关于完善中国特色现代企业制度的意见》印发，《意", "detail": "见》\n要求，坚持稳中求进工作总基调，坚持和完善社会主义基本经济制度，坚持社会主义市场经济改革方向，\n统筹高质量发展和高水平安全，以坚持和加强党的领导为根本，以产权清晰、权责明确、政企分开、管理\n科学为基础，以完善公司治理为重点，以改革创新为动力，弘扬企业家精神，加快建设更多世界一流企业，\n为以中国式现代化全面推进强国建设、民族复兴伟业提供有力支撑。\n经过5年左右，推动具备条件的企业普遍建立适合国情、符合实际、满足发展需要的中国特色现代企\n业制度，企业党的建设全面加强，治理结构更加健全，市场化运营机制更加完善，科学管理水平进一步提\n高，推动自主创新、支撑产业升级、履行社会责任等作用充分发挥。到2035年，中国特色现代企业制度更\n加完善，企业国际竞争力全面提升，为加快建设世界一流企业奠定坚实基础。"}, {"title": "5月26日，第三届民航科教创新成果展在北京国家会议中心开幕。", "detail": "成果展以“创新领航智连世界”\n10\n(cid:3)\n时政/公基/笔试/面试/真题资料，请加微信：yumi9938\n为主题，集中展示我国民航自主创新技术和国产民机、无人机等先进制造技术成果。多项国产化的装备系\n统为航空安全提供了更新的解决方案。"}, {"title": "中国少年先锋队第九次全国代表大会5月27日上午在北京开幕。", "detail": "习近平发来贺信，习近平在贺信\n中强调，少年儿童是推进强国建设、民族复兴伟业的未来生力军，少先队是少年儿童健康成长的大学校。\n新征程上，少先队要高举队旗跟党走，聚焦培育共产主义接班人的根本任务，着眼于培养中国特色社会主\n义事业合格建设者，教育引领广大少先队员争当爱党爱国、勤奋好学、全面发展的新时代好少年。"}, {"title": "国家电投集团5月27日发布消息，位于江西彭泽的棉船岛风电项目全容量并网发电，标志", "detail": "着长江\n流域首个实现规模化可再生能源供电的“零碳岛”正式投运。"}, {"title": "《中国氢能发展报告（2025）》日前正式发布。", "detail": "《报告》显示，2024年我国氢能全年生产消费规模\n超3650万吨，位列世界第一位。"}, {"title": "当地时间5月27日下午，国务院总理李强在吉隆坡出席东盟－中国－海合会峰会。", "detail": "会议以“共创机\n遇共享繁荣”为主题。李强强调，各方应当牢牢把握这一历史性机遇，不断丰富三方合作内涵，努力打造当\n今时代全球合作发展的典范。一是打造跨区域开放的典范。二是打造跨发展阶段合作的典范。三是打造跨\n文明融合的典范。\n李强指出，中方愿同东盟、海合会加强三方伙伴关系，商讨制定高质量共建“一带一路”行动计划，加强\n基础设施、市场规则等对接联通，拓展能源、农业、人工智能、数字经济、绿色低碳等领域合作，促进人\n员往来和民心相通。"}, {"title": "5月28日上午，第二届海峡两岸中华文化峰会在北京开幕，本届大会以“传承·弘扬·发", "detail": "展”为主题。\n两岸文化各领域代表人士800余人出席活动。"}, {"title": "黄河水利委员会近日正式发布《黄河流域水土保持公报（2024年）》，5年来，黄河流", "detail": "域水土流失\n面积减少1.84万平方千米，减幅6.96%。《公报》显示，截至2024年年底，黄河流域水土流失面积24.58\n万平方千米，植被面积54.13万平方千米，水土保持率69.07%，淤地坝5.83万座。"}, {"title": "在第九个全国科技工作者日到来之际，中国科协公布一项最新调查数据显示，2024年中", "detail": "国具备科学\n素质的公民比例提升至15.37%。同时调查发现，中国基本具备科学素质的公民比例已达44.07%，人口规模\n达4.4亿。获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "2025年5月29日凌晨1时31分，我国在西昌卫星发射中心用长征三号乙Y110运", "detail": "载火箭，成功将\n行星探测工程天问二号探测器发射升空。天问二号主要任务目标是对小行星2016HO3进行探测、取样并返\n回地球，此后再对主带彗星311P开展科学探测。小行星2016HO3是人类目前发现的地球准卫星之一。"}, {"title": "2025年5月29日12时12分，我国在酒泉卫星发射中心使用长征四号乙运载火箭，", "detail": "成功将实践二\n十六号卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。实践二十六号卫星主要用于国土\n普查、环境治理等领域，为国民经济建设提供信息服务。"}, {"title": "中央军委主席习近平日前签署命令，发布《军事科研奖励条例》，自2025年7月1日起", "detail": "施行。《条\n例》共8章42条，适应军事科研工作创新发展、向战为战的形势任务需要，鲜明立起战斗力这个唯一的根\n本的标准，设置了军事特色鲜明、结构层级合理、评价标准科学、与国家和军队重大战略需求紧密结合的\n军事科研奖励体系。"}, {"title": "近日，中办、国办印发《关于健全资源环境要素市场化配置体系的意见》，意见提出，到2", "detail": "027年，\n碳排放权、用水权交易制度基本完善，排污权交易制度建立健全，节能市场化机制更加健全，资源环境要\n素交易市场更加活跃、价格形成机制更加健全，推动资源环境要素畅通流动、高效配置，充分释放市场潜\n11\n(cid:3)\n时政/公基/笔试/面试/真题资料，请加微信：yumi9938\n力，对实现相关资源环境目标的支撑作用有效增强。"}, {"title": "今年6月是第24个全国“安全生产月”。", "detail": "5月29日，国务院安委会办公室、应急管理部在京举行全\n国“安全生产月”活动启动仪式。今年的“安全生产月”活动主题为“人人讲安全、个个会应急——查找身边安\n全隐患”。"}, {"title": "2025年5月29日至31日，第四届文明交流互鉴对话会在甘肃敦煌举办。", "detail": "来自多国的政党政要、专\n家学者、国际组织和非政府组织负责人以及中方相关部门代表约400人与会。"}, {"title": "5月29日，以“智汇中国智惠上合”为主题的“中国—上海合作组织人工智能合作论坛”", "detail": "在天津举行。\n论坛推动中国与上海合作组织成员国在技术研发、人才培养、产业应用等方面加强协作，共同攻克技术难\n题，加速人工智能技术产业化进程，共享人工智能发展带来的红利，为促进地区繁荣发展注入新的强大动\n力。"}, {"title": "5月29日，中国—中亚国际人文旅游专列（西安—阿拉木图段）首发开行活动在西安火车", "detail": "站举行。\n本次Y29次人文旅游专列从西安出发，经新疆霍尔果斯口岸出境，于哈萨克斯坦时间5月31日晚抵达阿拉\n木图。"}, {"title": "5月30日上午，国际调解院公约签署仪式在中国香港举行。", "detail": "来自亚洲、非洲、拉美和欧洲85个国\n家和近20个国际组织的高级别代表约400人出席。33个国家现场签署公约，成为创始成员国。\n12\n(cid:3)"}]}, {"month": "2025年6月", "year": 2025, "items": [{"title": "5月30日，2025年全国科技工作者日主场活动在北京举行。", "detail": "今年全国科技工作者日系列活动以“矢志\n创新发展建设科技强国”为主题。"}, {"title": "5月31日，全国少工委发布中国少年先锋队统计主要数据，截至2024年12月31日", "detail": "，全国共有少先\n队员1.13亿名，中小学校少先队大、中队辅导员305.4万名。中小学校少工委17.6万个、少先队大队17.9\n万个、中队287.4万个。"}, {"title": "6月1日出版的第11期《求是》杂志将发表习近平的重要文章《加快建设教育强国》。", "detail": "文章强调，教\n育是强国建设、民族复兴之基。党的十八大以来，我们坚持把教育作为国之大计、党之大计，全面贯彻党\n的教育方针，作出深入实施科教兴国战略、加快教育现代化的重大决策，确立到2035年建成教育强国的奋\n斗目标，推动新时代教育事业取得历史性成就、发生格局性变化。\n文章指出，我们要建成的教育强国，是中国特色社会主义教育强国，应当具有强大的思政引领力、人\n才竞争力、科技支撑力、民生保障力、社会协同力、国际影响力。建设这样的教育强国，必须全面构建固\n本铸魂的思想政治教育体系、公平优质的基础教育体系、自强卓越的高等教育体系、产教融合的职业教育\n体系、泛在可及的终身教育体系、创新牵引的科技支撑体系、素质精良的教师队伍体系、开放互鉴的国际\n合作体系。"}, {"title": "6月1日，中国—蒙古国海关AEO互认安排正式实施。", "detail": "AEO是即“经认证经营者”，是由世界海关组\n织倡导，通过海关对信用状况、守法程度和水平较高企业进行认证，对通过认证企业给予优惠通关便利的\n一项国际经贸规则。"}, {"title": "6月1日起，中方对巴西、阿根廷、智利、秘鲁、乌拉圭5国持普通护照人员试行免签政策", "detail": "，中国单\n方面免签“朋友圈”又添新成员。这是中方免签政策首次拓展到拉美和加勒比地区国家。至此，适用单方面免\n签政策来华国家已扩展至43个。"}, {"title": "中华人民共和国国家监察委员会发布公告（第2号），《中华人民共和国监察法实施条例》", "detail": "已经2025\n年4月27日国家监察委员会全体会议修订通过，现予公布，自2025年6月1日起施行。"}, {"title": "近日，中国科学院国家天文台领导的国际合作团队利用我国的郭守敬望远镜首次在银河系发", "detail": "现一颗锕\n系元素增丰极贫金属星（一颗金属元素含量远低于太阳，而锕系元素含量显著高于同类恒星的古老恒星）。"}, {"title": "6月1日，2025年人口固定样本跟访调查正式启动。", "detail": "此次调查可以为加强人口统计和动态监测预警、\n更好地服务人口高质量发展提供数据支持。今年的人口固定样本跟访调查主要内容包括：调查对象的姓名、\n性别、受教育程度、迁移流动情况、婚姻状况、生育情况等。调查将以调查员入户开展调查的方式进行。"}, {"title": "6月1日起，《国务院关于修改〈快递暂行条例〉的决定》正式施行。", "detail": "此次修改，专门增加了“快递包\n装”章节，推进快递包装绿色化、减量化、可循环，鼓励经营快递业务的企业和寄件人使用可降解、可重复\n利用的环保包装材料。国家邮政局数据显示，2024年我国快递业务量达1750亿件，已连续11年位居世界\n第一，同时也带来包装物大量消耗资源和污染环境等问题。"}, {"title": "近日，上海交通大学陈险峰教授团队联合上海电力大学李渊华教授团队，在量子直接通信领", "detail": "域取得\n重要进展，成功构建了一个四个节点间300公里级的全连接量子直接通信网络。"}, {"title": "日前，人力资源社会保障部、财政部、国务院国资委联合印发《关于加大国有企业技能人才", "detail": "薪酬分\n配激励的通知》，《通知》指出，建立创新创造奖励制度，坚持创新者多得，对技能人才小发明、小创造、\n小革新等日常创新设置单项奖励，对在解决重大工艺技术难题、重大质量问题等技术革新或技术攻关中作\n出突出贡献的技能人才给予专项奖励。鼓励企业创新多元化激励方式，完善以创新能力、质量、实效、贡\n1\n(cid:3)\n(cid:3)\n献为导向的技能人才激励和人才评价体系，开展形式多样的劳动技能竞赛，完善技能岗位与相应层级专业\n技术、管理岗位的互转机制。"}, {"title": "水电水利规划设计总院近日发布的《中国可再生能源发展报告2024年度》显示，截至2", "detail": "024年底，我\n国抽水蓄能累计投产规模超5800万千瓦，2024年抽水蓄能新增投产规模775万千瓦，全年新增核准抽水蓄\n能电站23座。我国抽水蓄能装机容量连续9年居世界首位，日本、美国抽水蓄能装机容量分列第二、三位。"}, {"title": "国务院总理李强日前签署国务院令，公布《政务数据共享条例》，自2025年8月1日起", "detail": "施行。《条\n例》规定政务数据共享工作坚持中国共产党的领导，遵循统筹协调、标准统一、依法共享、合理使用、安\n全可控的原则。细化各级人民政府、政务数据共享主管部门、政府部门及其政务数据共享工作机构的职责。"}, {"title": "近日，《中国教师发展报告2024》成果发布会在东北师范大学召开。", "detail": "从会上获悉，我国班主任队伍\n规模稳步扩充，队伍结构趋向合理，专业发展水平总体较高，学历层次提升明显，本科及以上学历占比高\n达95.14%。"}, {"title": "近日，生态环境部、文化和旅游部、中国文联、中国作协四部门联合印发《关于进一步加强", "detail": "生态文\n化建设的指导意见》，《意见》提出到2030年，形成一批标志性生态文化理论研究成果，打造一批多样化\n生态文化阵地，产出一批高质量生态文艺作品，推出一批生态文化特色旅游精品线路，生态文化产品和服\n务更加丰富，以生态价值观念为准则的生态文化体系基本建立。到2035年，生态文化建设、管理和传播体\n制机制持续完善，以生态价值观念为准则的生态文化体系逐步健全，生态文化对经济社会发展支持更加有\n力，绿色生产生活方式广泛形成，生态文明国际传播力和影响力显著提升。"}, {"title": "6月4日上午，国家主席习近平在中南海会见白俄罗斯总统卢卡申科。", "detail": "习近平指出，中国和白俄罗斯\n是真朋友、好伙伴。双方一直以诚相待、以信相交。两国传统友好历久弥坚，政治互信牢不可破，各领域\n合作全面推进。"}, {"title": "韩国中央选举管理委员会6月4日通过大选计票结果，正式确认共同民主党候选人李在明当", "detail": "选第21\n届韩国总统，李在明的总统任期自当地时间4日6时21分正式开启。"}, {"title": "财政部、生态环境部、国家发展改革委、水利部、国家林草局日前联合出台意见，进一步健", "detail": "全横向\n生态保护补偿机制。意见提出，推动建立覆盖更加全面、权责更加清晰、方式更加多元、治理更加高效的\n横向生态保护补偿机制，实现生态产品供给地与受益地良性互动，真正让保护者、贡献者得到实惠。健全\n奖罚分明的制度机制，坚持“谁污染、谁治理，谁保护、谁受益”，强化激励约束，吸引更多社会资本参与生\n态文明建设。"}, {"title": "国家发展改革委和国家能源局日前联合印发《关于深化提升“获得电力”服务水平全面打造", "detail": "现代化用\n电营商环境的意见》，明确到2029年，我国基本建成办电便捷化、供电高质化、用电绿色化、服务普惠化、\n监管协同化的现代化用电营商环境，我国“获得电力”国际竞争优势进一步巩固，人民群众办电用电获得感满\n意度持续增强。"}, {"title": "2025年六五环境日国家主场活动6月5日在重庆市举办。", "detail": "今年的六五环境日以“美丽中国我先行”为\n主题，旨在推动全社会进一步树牢和践行生态文明理念，汇聚起呵护美丽中国、共同守护地球家园的磅礴\n力量。"}, {"title": "6月5日，我国自主研制的AES100发动机在湖南获颁生产许可证并签订销售合同。", "detail": "AES100发动机\n是我国自主研制的1000千瓦级先进民用涡轴发动机，具有安全性高、经济性好、维护便捷、环境适应性广\n等特点，可配装5～6吨级双发直升机和3～4吨级单发直升机，也可用于倾转旋翼机等飞行器，执行运输、\n观光、救援等任务。\n2\n(cid:3)"}, {"title": "6月5日，生态环境部正式发布《2024中国生态环境状况公报》。", "detail": "《公报》显示，2024年全国地级\n及以上城市细颗粒物（PM2.5）平均浓度达到29.3微克/立方米，比2023年下降2.7；空气质量优良天数比\n例为87.2%，比2023年上升1.7个百分点。"}, {"title": "日前，由中国科学院云南天文台顾盛宏研究员领衔的国际联合研究团队，在世界上首次利用", "detail": "凌星中\n间时刻变化（TTV）反演技术，在类太阳恒星的宜居带发现一颗质量大约是地球10倍的超级地球——开普\n勒-725c。"}, {"title": "当地时间6月4日，欧洲央行正式批准保加利亚使用欧元的申请，使其成为欧元区第21个", "detail": "成员国。"}, {"title": "2025年6月6日04时45分，我国在太原卫星发射中心使用长征六号改运载火箭，成", "detail": "功将卫星互联\n网低轨04组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "习近平6月6日在中南海接受班禅额尔德尼·确吉杰布拜见。", "detail": "习近平希望班禅继承藏传佛教爱国爱\n教光荣传统，坚决维护祖国统一和民族团结。在学业上潜心精进，不断深化宗教学修、提高宗教造诣，加\n强各方面知识的学习和掌握。在工作上积极有为，为推动铸牢中华民族共同体意识、系统推进我国宗教中\n国化、促进西藏现代化建设更好发挥作用。在修养上持重善律，带头守法持戒，涵养优良品德和高尚情操。"}, {"title": "中央军委主席习近平日前签署命令，发布《军事设施建设条例》，自2025年8月1日起", "detail": "施行。条例\n共11章63条，按照军委管总、战区主战、军种主建的总原则，围绕理顺建设链、管理链、监督链，重点从\n军事设施建设计划管理、项目审批、工程发包、勘察设计、施工管理、应急建设、安全保密、监督问责等\n方面，厘清管理权限，优化流程机制，固化实践成果，为提高军事设施建设质量效益和保障能力提供有力\n法治保障。"}, {"title": "近期，该研究所甘再国研究员团队与合作者利用兰州重离子加速器国家实验室加速器装置，", "detail": "首次合\n成了新核素：镤-210，该核素是目前已知的最缺中子的镤同位素。"}, {"title": "2025年全国统一高考于6月7日开考。", "detail": "据教育部数据，2025年全国高考报名人数达1335万人。"}, {"title": "近日，我国科学家凭分子遗传学证据确认，山东广饶傅家遗址存在距今4750年以前由两", "detail": "个母系氏族\n构成的社会形态。这项成果在世界范围内首次确证存在史前母系社会组织，首次以分子遗传学证据实证了\n我国新石器时代母系社会的具体结构，刷新了母系社会最早仅可追溯至欧洲铁器时代的遗传学线索溯源。"}, {"title": "近日，国家铁路局发布《2024年铁道统计公报》。", "detail": "公报显示，2024年，全国铁路旅客发送量完成43.12\n亿人，比上年增长11.9%；全国铁路货运总发送量完成51.75亿吨，比上年增长2.8%。截止到2024年底，全\n国铁路营业里程达到16.2万公里，其中高速铁路4.8万公里。\n获取后续更新及更多考试资料，请加微信：(cid:3)"}, {"title": "国务院国资委近日印发《中央企业发展规划管理办法》，通过加强顶层设计、规范程序、强", "detail": "化执行、\n统筹联动，着力构建全流程、能监测、可评估的规划管理体系。"}, {"title": "2025年6月8日，是第17个世界海洋日和第18个全国海洋宣传日。", "detail": "当日，2025年世界海洋日暨全\n国海洋宣传日主场活动在海南海口举办，活动主题是“保护海洋生态系统，人与自然和谐共生”。"}, {"title": "6月8日，自然资源部海洋战略规划与经济司发布《2025中国海洋经济发展指数》。", "detail": "2024年我国海\n洋生产总值首次突破10万亿元，比上年增长5.9%。指数显示，2024年指数为125.2，比上年增长2.3%。"}, {"title": "新华社国家高端智库6月8日面向全球发布中英文智库报告《中国将南海打造成和平、友谊", "detail": "、合作\n之海的实践》。报告强调，南海稳，则地区国家受益；南海乱，则地区国家遭殃。南海地区和平稳定是包\n括中国在内地区国家的共同愿望，符合各国利益。中国提出将南海打造成和平之海、友谊之海、合作之海\n的重要倡议，坚持通过谈判协商解决争议，坚持通过规则机制管控分歧，坚持通过互利合作实现共赢，坚\n3\n(cid:3)\n(cid:3)\n持反对域外势力插手干涉，并不断积极推动付诸实践，为南海地区和平稳定与繁荣发展提供强大支撑。"}, {"title": "中华环保世纪行2025年宣传活动6月8日在四川省成都市启动。", "detail": "今年宣传活动的主题是“贯彻习近平\n生态文明思想，筑牢长江上游生态屏障”。"}, {"title": "2025年6月9日是第18个国际档案日，国家档案局6月9日举办新闻发布会，发布了", "detail": "第六批《中国\n档案文献遗产名录》，52项档案文献入选。至此，经过六批评选，《中国档案文献遗产名录》入选项目达\n250项。"}, {"title": "6月9日，国务院以“深化科技成果转化机制改革，推动科技创新和产业创新融合发展”为", "detail": "主题，进行\n第十四次专题学习。李强指出，科技成果转化经历技术研发、工程验证和产业化商业化等众多环节，任何\n一个环节不畅通都会影响落地效果，要聚焦关键着力打通科技成果转化的堵点断点。在转化源头方面，要\n进一步优化对科技研发及产业发展的相关评价体系和机制；在转化对接方面，要进一步强化企业创新主体\n地位；在转化应用方面，要用好首台套等政策。"}, {"title": "6月9日起，中方对沙特、阿曼、科威特、巴林持普通护照人员试行免签政策。", "detail": "至此，适用单方面免\n签政策来华国家已扩展至47个。加上2018年全面互免签证的海合会成员国阿联酋和卡塔尔，中方已实现对\n海合会国家免签“全覆盖”。"}, {"title": "日前，中共中央办公厅、国务院办公厅印发《关于进一步保障和改善民生着力解决群众急难", "detail": "愁盼的\n意见》，推动民生建设更加公平、均衡、普惠、可及。意见明确，要提高基本公共服务均衡性。适时将涉\n及群众切身利益的增量服务事项纳入国家基本公共服务标准。以县域为基本单元，全面推进公共服务规划\n布局、设施建设、资源配置、人才调配城乡一体化。逐步将基本公共服务调整为常住地提供。"}, {"title": "6月10日，2025年中国网络文明大会在安徽合肥举行，也是首次在中部地区、首次在", "detail": "长三角地区举\n办。本次大会以“汇聚网络正能量引领时代新风尚”为主题。"}, {"title": "第五届中国印刷业创新发展大会于6月10日上午在辽宁沈阳开幕。", "detail": "大会以“数据驱动新质印力”为主\n题，旨在贯彻落实党的二十届三中全会精神，加快发展数智绿色融合印刷新质生产力。"}, {"title": "6月10日，国家电网有限公司哈密-重庆±800千伏特高压直流输电工程（以下简称哈", "detail": "密-重庆工程）\n投产送电。这是我国首个投产送电的沙戈荒新能源基地外送特高压直流输电工程，是西南地区首个特高压\n直流受入工程，对于推动哈密能源资源的开发与外送，促进清洁能源大范围优化配置，提高重庆电力供应\n保障能力，助力实现“双碳”目标具有重要意义。\n获取后续更新及更多考试资料，请加微信：(cid:3)"}, {"title": "6月10日，第十五届全国运动会奖牌发布仪式在广东省广州市举行，本届全运会奖牌名为", "detail": "“同心跃”，\n代表粤港澳大湾区三地同心协力，共跃未来。"}, {"title": "2025年中国网络文明大会6月10日在安徽合肥开幕，大会上举行了2025年全民数", "detail": "字素养与技能提\n升月启动仪式。本次提升月主题为“数智赋能全民共享”，以助力提高我国人口整体素质、促进人的全面发\n展为目标，以推进人工智能全学段教育和全社会通识教育、源源不断培养高素质人才为主攻方向，举办提\n升全民数字素养与技能系列主题活动，进一步推动数字技术普及应用，促进数字成果普惠共享，不断夯实\n新质生产力发展的人力资源基础，助力网络强国建设。"}, {"title": "6月10日至12日，第二届“一带一路”科技交流大会在四川成都举行。", "detail": "本届大会以“共建创新之路，\n同促合作发展——携手构建‘一带一路’科技创新共同体”为主题，在首届大会取得成效的基础上，机制化推\n动“一带一路”科技交流合作，将签署系列双边政府间科技合作文件，启动多个重要领域的“一带一路”科技创\n新专项合作计划，搭建一批“产学研用”交流合作平台。\n4\n(cid:3)"}, {"title": "6月10日是首个文明对话国际日。", "detail": "中方同联合国等国际组织以及多国一道，在全球多地开展丰富多\n彩的主题活动。2024年6月，联合国大会一致通过中国提出的决议，把每年6月10日定为文明对话国际日。"}, {"title": "6月11日，中非合作论坛成果落实协调人部长级会议在湖南长沙举行。", "detail": "王毅在出席开幕式时表示，\n中国和非洲作为世界上最大的发展中国家和发展中国家最集中的大陆，是全球南方的中坚力量。王毅代表\n中方就推动中非合作高质量发展提出五点倡议。一是坚持守望相助，做全球南方团结的维护者。二是坚持\n对外开放，做国际自由贸易的倡导者。三是坚持互利共赢，做全球发展合作的同行者。四是坚持公道正义，\n做国际公正秩序的捍卫者。五是坚持交流互鉴，做世界文明多样性的促进者。"}, {"title": "6月12日，交通运输部发布《2024年交通运输行业发展统计公报》。", "detail": "《统计公报》显示，截至2024\n年年底，全国铁路营业里程16.2万公里，其中高铁营业里程4.8万公里；全国公路里程549.04万公里，其中\n高速公路里程19.07万公里、比上年末增加0.7万公里。"}, {"title": "国家移民管理局6月12日发布公告，自2025年6月12日起，印度尼西亚公民可适用", "detail": "240小时过境\n免签政策便捷来华，中国240小时过境免签政策适用国家增至55国。"}, {"title": "6月12日，第四届中国－非洲经贸博览会在湖南长沙举行。", "detail": "本届博览会以“中非共行动逐梦现代化”\n为主题，会期4天。本届博览会吸引了近4700家中非企业、3万余名中外朋友参加，初步达成的合作项目\n总金额超过110亿美元。"}, {"title": "近日，文化和旅游部确定七地为国家级文化生态保护区，分别是：客家文化（闽西）生态保", "detail": "护区（龙\n岩市、三明市）、说唱文化（宝丰）生态保护区、武陵山区（鄂西南）土家族苗族文化生态保护区（宜昌\n市、恩施土家族苗族自治州）、武陵山区（渝东南）土家族苗族文化生态保护区、藏族文化（玉树）生态\n保护区、晋中文化生态保护区（太原市、吕梁市）、陕北文化生态保护区（延安市）。"}, {"title": "6月12日，第十七届海峡论坛·海峡阅读大会开幕式在福建福州举行，本届海峡阅读大会", "detail": "以“融通两\n岸向海而兴”为主题，持续至7月底，将通过专家研讨、阅读推广、读者交流、图书展览等，进一步深化两\n岸文化交流。"}, {"title": "中共中央6月13日上午在人民大会堂举行座谈会，纪念陈云同志诞辰120周年。", "detail": "习近平在讲话中回\n顾了陈云同志光辉的一生，总结了他为我国革命、建设、改革建立的不朽功勋，强调陈云同志是伟大的无\n产阶级革命家、政治家，杰出的马克思主义者，是中国社会主义经济建设的开创者和奠基人之一，党和国\n家久经考验的卓越领导人，是以毛泽东同志为核心的党的第一代中央领导集体和以邓小平同志为核心的党\n的第二代中央领导集体的重要成员，为党和人民事业发展作出了重大贡献。\n习近平指出，陈云同志在长期革命生涯中树立和坚持的坚定理想信念、坚强党性原则、求真务实作风、\n朴素公仆情怀、勤奋学习精神，体现着共产党人的高尚品质。"}, {"title": "近日，2025年度世界灌溉工程遗产中国候选工程名单正式公布，北京门头沟永定河古渠", "detail": "灌溉工程、\n云南元阳哈尼梯田、江苏赤山湖灌溉工程、四川湔江堰4项灌溉工程遗产入选。"}, {"title": "近日，中办、国办印发的《关于深入推进深圳综合改革试点深化改革创新扩大开放的意见》", "detail": "正式公\n开。意见明确，按照分批次研究制定授权事项清单的工作机制，再推出一批改革措施、落地一批创新试验、\n深化一批开放举措，在破解教育科技人才领域体制机制障碍、强化创新链产业链资金链人才链深度融合、\n拓展粤港澳合作新途径新场景新载体、建设现代化国际化创新型城市等方面先行先试、开拓创新、真抓实\n干，在更高起点、更高层次、更高目标上深化改革、扩大开放，创造更多可复制、可推广的新鲜经验。"}, {"title": "2025年6月14日是全国第20个“文化和自然遗产日”。", "detail": "6月14日，2025年文化和自然遗产日主场城\n市活动在湖南长沙举行。活动主题为“让文物焕发新活力绽放新光彩”。\n5\n(cid:3)"}, {"title": "2025年6月14日15时56分，我国在酒泉卫星发射中心用长征二号丁运载火箭，成", "detail": "功将电磁监测卫\n星“张衡一号”02星发射升空。“张衡一号”02星的成功发射是我国在地球物理场空间观测领域探测能力建设\n的又一重大成果，进一步提升我国对重大自然灾害的“天-空-地”立体监测能力。"}, {"title": "国家文物局近日完成新一批国家考古遗址公园评定工作，10家单位列入国家考古遗址公园", "detail": "名单。至\n此，国家考古遗址公园已评定65家，分布在全国21个省（区、市）。这10家单位是：山西省陶寺国家考\n古遗址公园、内蒙古自治区萨拉乌苏国家考古遗址公园、内蒙古自治区和林格尔土城子国家考古遗址公园、\n浙江省上山国家考古遗址公园、安徽省双墩国家考古遗址公园、山东省大汶口国家考古遗址公园、河南省\n大河村国家考古遗址公园、湖北省铜绿山国家考古遗址公园、四川省宝墩国家考古遗址公园、陕西省秦咸\n阳城咸阳宫国家考古遗址公园。"}, {"title": "当地时间6月13日，巴西政府以轮值主席国身份宣布，越南正式加入金砖国家合作机制成", "detail": "为伙伴国。\n金砖伙伴国还包括尼日利亚、白俄罗斯、玻利维亚、哈萨克斯坦、古巴、马来西亚、泰国、乌干达和乌兹\n别克斯坦。"}, {"title": "6月15日，第十七届海峡论坛大会在福建厦门举行。", "detail": "本届海峡论坛延续“扩大民间交流、深化融合发\n展”主题，设置基层交流、青年交流、文化交流、经济交流四大板块，安排系列活动56场。"}, {"title": "中核集团6月15日宣布，经秦山核电“和福一号”辐照后的钇-90玻璃微球已顺利出堆", "detail": "并通过相关检测，\n标志着我国成功掌握商用堆生产钇-90的技术，可实现批量化生产。钇-90微球被誉为肝癌介入治疗领域的“精\n准核武器”，其通过释放β射线精准摧毁肿瘤细胞的特性，正成为国际常用的中晚期肝癌治疗的重要手段。"}, {"title": "近日，中国科学院脑科学与智能技术卓越创新中心联合复旦大学附属华山医院，与相关企业", "detail": "合作，\n成功开展了我国首例侵入式脑机接口的前瞻性临床试验。该成果标志着我国在侵入式脑机接口技术上成为\n全球第二个进入临床试验阶段的国家。"}, {"title": "6月16日出版的第12期《求是》杂志将发表习近平的重要文章《用中长期规划指导经济", "detail": "社会发展是\n我们党治国理政的一种重要方式》。文章指出，人民对美好生活的向往就是我们的奋斗目标，人民的信心\n和支持就是我们国家奋进的力量。好的方针政策和发展规划都应该顺应人民意愿、符合人民所思所盼，从\n群众中来、到群众中去。五年规划编制涉及经济社会发展方方面面，同人民群众生产生活息息相关，需要\n把加强顶层设计和坚持问计于民统一起来，把社会期盼、群众智慧、专家意见、基层经验充分吸收到规划\n编制中来。\n文章强调，谋划“十五五”时期经济社会发展，必须准确把握“十五五”时期的阶段性要求，着眼强国建设、\n民族复兴伟业，紧紧围绕基本实现社会主义现代化目标，一个领域一个领域合理确定目标任务、提出思路\n举措。对各方面的目标任务，要深入分析论证，确保科学精准、能够如期实现。要统筹谋划，抓住关键性、\n决定性因素，把握好节奏和进度，注重巩固拓展优势、突破瓶颈堵点、补强短板弱项、提高质量效益，与\n整体目标保持取向一致性。各地区编制本地区规划要结合实际，实事求是，提高规划执行力和落实力。\n获取后续更新及更多考试资料，请加微信：(cid:3)"}, {"title": "6月15日，两岸融合发展示范区建设专题推进会在福建厦门召开。", "detail": "王沪宁表示，深化两岸融合发展\n意义重大、责任重大。要围绕建设两岸融合发展示范区目标任务，强化责任担当，加强谋划推进，推出更\n多创新性举措和融合发展成果。要发挥福建对台独特优势和先行示范作用，加强政策和制度创新，致力于\n促进两岸经济文化交流合作。"}, {"title": "6月16日，最高人民检察院发布《未成年人检察工作白皮书（2024）》，白皮书显示", "detail": "，2024年，全\n国检察机关受理审查逮捕未成年犯罪嫌疑人65198人，同比下降1.1%，批准逮捕34329人，同比上升27.8%。\n6\n(cid:3)"}, {"title": "6月16日，安徽省量子信息工程技术研究中心发布消息，我国首款面向千比特规模设计的", "detail": "超导量子\n计算测控系统ez-Q®Engine2.0正式交付使用。测控系统是量子计算机的关键核心设备之一，可类比经典计\n算机的主板，主要负责对量子芯片上的量子比特进行操作，执行量子算法运算等工作。"}, {"title": "今年6月是第24个全国“安全生产月”，主题为“人人讲安全、个个会应急——查找身边", "detail": "安全隐患”。6\n月16日上午，2025年全国“安全宣传咨询日”主场活动在河南郑州举行。"}, {"title": "当地时间6月16日下午，哈萨克斯坦总统托卡耶夫同中国国家主席习近平在阿斯塔纳总统", "detail": "府举行会\n谈。习近平强调，中哈都处在各自发展振兴的关键阶段，两国要齐心协力推进全方位合作。一要以高水平\n战略互信引领双边关系发展；二要以高质量共建“一带一路”促进两国合作提质升级；三要以全方位安全合作\n维护两国和平安宁；要以多元化人文交流夯实中哈友好根基。"}, {"title": "今年6月17日是第31个世界防治荒漠化与干旱日，今年的国际主题是“恢复土地释放机", "detail": "遇”，我国\n的主题为“科学治沙兴业利民”。党的十八大以来，我国持续加大荒漠化综合防治力度，加快推进“三北”等\n重点生态工程建设，完成沙化土地治理任务3.65亿亩，封禁保护面积2794万亩。"}, {"title": "6月17日，我国在酒泉卫星发射中心成功组织实施梦舟载人飞船零高度逃逸飞行试验，标", "detail": "志着我国\n载人月球探测工程研制工作取得新的重要突破。梦舟载人飞船未来将成为支撑空间站应用与发展、载人月\n球探测等任务的核心载人飞行器，这次试验成功为后续载人月球探测任务奠定了重要技术基础。"}, {"title": "当地时间6月17日下午，第二届中国—中亚峰会在阿斯塔纳独立宫举行。", "detail": "中国国家主席习近平在发\n表主旨发言时表示，在长期实践中，我们探索形成了“互尊、互信、互利、互助，以高质量发展推进共同现\n代化”的“中国－中亚精神”。\n习近平指出，我们要以“中国—中亚精神”为引领，以更加进取的姿态和更加务实的举措加强合作，推动\n共建“一带一路”高质量发展，朝着命运共同体目标砥砺前行。一要坚守彼此信赖、相互支持的团结初心。二\n要优化务实高效、深度融合的合作布局。三要打造和平安宁、休戚与共的安全格局。四要拉紧同心同德、\n相知相亲的人文纽带。五要维护公正合理、平等有序的国际秩序。"}, {"title": "当地时间6月16日，第79届联合国大会投票通过一项决议草案，将12月4日设立为“", "detail": "反对单边强制\n措施国际日”，自2025年起每年举行纪念活动，促进消除以单方面强制性经济措施作为政治和经济胁迫的手\n段。"}, {"title": "6月18日，第三十一届北京国际图书博览会在北京国家会议中心开幕，本届图博会以“促", "detail": "进文明传承\n发展，推动交流互鉴共赢”为主题，坚持开放包容，坚持守正创新，扎实推进高水平对外开放平台建设，推\n动文化贸易务实合作，以书为媒全面展示中华文明和世界各国优秀文明成果。"}, {"title": "6月18日，2025陆家嘴论坛在上海开幕，本次论坛主题为“全球经济变局中的金融开", "detail": "放合作与高质量\n发展”。"}, {"title": "近日，中国科学院紫金山天文台牵头的联合实验团队在太赫兹通信领域取得重大突破，标志", "detail": "着太赫\n兹通信技术成功得到验证，为我国高容量通信技术发展提供了新的思路和实践范例，相关成果在《国家科\n学评论》在线发表。"}, {"title": "6月19日上午，第六届跨国公司领导人青岛峰会在青岛国际会议中心开幕，来自465家", "detail": "跨国公司的\n570位企业负责人参加。本届峰会的主题是“跨国公司与中国——链接世界合作共赢”，举办1场开幕式暨\n跨国公司高质量发展论坛，3场主题活动和涵盖4大板块的多场平行活动，发布《跨国公司在中国》系列研\n究报告等。"}, {"title": "第9届中国—南亚博览会6月19日在云南昆明开幕。", "detail": "本届南博会有73个国家、地区和国际组织参\n7\n(cid:3)\n(cid:3)\n会，2500多家企业参展，覆盖了南亚、东南亚所有国家。本届南博会沿用“团结协作、共谋发展”的主题，\n由斯里兰卡担任主题国，泰国担任特邀伙伴国。"}, {"title": "中国物流与采购联合会6月19日公布《中国公共采购发展报告（2024）》。", "detail": "根据报告，2024年全国\n公共采购总额为45万亿元，同比下降2.18%。"}, {"title": "近日，湖北东湖实验室高速磁悬浮电磁推进技术创新中心开展的一次磁悬浮实验中，科研人", "detail": "员用时7\n秒，成功在1000米距离内将1.1吨重的试验车加速至650公里/小时，测试速度打破了同类型平台全球纪录，\n成为全球最快的磁悬浮试验速度。"}, {"title": "6月19日，2025年第12届世界运动会奖牌“竹光”正式亮相。", "detail": "该奖牌名取自谐音“逐光”，不仅包含太\n阳神鸟纹饰、大熊猫等成都元素，还贴心地设计成“开口”的样式，运动员可将奖牌中的徽章赠予他人，承载\n着独特的“分享”理念。"}, {"title": "6月20日上午，国家主席习近平在北京人民大会堂会见来华进行正式访问的新西兰总理拉", "detail": "克森。习\n近平强调，中新双方要把合作放在双边关系中更加突出的位置，发挥互补优势，深化贸易和投资合作，挖\n掘科技创新、应对气候变化、基础设施等领域合作潜力，加强教育、文化、青年、民间、地方交流，丰富\n双边关系内涵。"}, {"title": "2025年6月20日20时37分，我国在西昌卫星发射中心使用长征三号乙运载火箭，", "detail": "成功将中星9C\n卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "中国消费者协会6月20日发布《中国消费者权益保护状况年度报告（2024）》，其中", "detail": "指出，2024年\n全国消协组织共受理消费者投诉1761886件，比上年增长32.62%，解决1211284件，投诉解决率68.75%，为\n消费者挽回经济损失12.8亿元。"}, {"title": "6月19日，第六届西部数字经济博览会在西安国际会展中心开幕。", "detail": "本届西部数博会以“数聚西安智\n造未来”为主题，展览面积1万平方米，共吸引国内外309家企业参会。"}, {"title": "6月20日，第十届全球海上风电大会在辽宁省大连市开幕，本届大会以“跨海合作，共赢", "detail": "未来：共建\n全球海上风电新生态”为主题，会期3天。会上发布了《全球海上风电市场展望》及《全球风能报告》。报\n告显示，今年以来，我国风电装机快速增长，风电发电量占比超12%。到2030年，全球海上风电装机容量\n有望突破230吉瓦，其中，我国深远海项目将成为国际合作的核心增长点。"}, {"title": "6月21日，中国奥委会举行2025年第39届奥林匹克日活动，迎接6月23日国际奥", "detail": "林匹克日。本届\n活动延续“动就一起”的主题，覆盖北京、深圳、南京等地，开展了奥林匹克日健康跑、奥林匹克文化营等活\n动。"}, {"title": "6月21日，2025（乙巳）年公祭中华人文始祖伏羲大典在甘肃省天水市举行。", "detail": "今年的公祭伏羲大典，\n以“赓续文脉凝聚力量、传承智慧永励后人”为主题，追思始祖伏羲创世功绩，激励中华儿女进取之志，为实\n现中华民族伟大复兴凝聚强大精神力量。伏羲被称为中华民族人文始祖，位居“三皇之首”“百王之先”。相传\n天水是伏羲的诞生地和伏羲文化的发祥地，祭祀伏羲由来已久、世代传承。"}, {"title": "6月20日，由扬州中远海运重工建造的中国首制16000TEU(标箱)甲醇双燃料集", "detail": "装箱船“中远海运洋浦”\n轮，在上海长兴岛交付。该船的交付实现了大型甲醇双燃料箱船建造领域“国内船东第一单、国内船厂交付\n第一艘、国产甲醇主机第一次实船应用”三个历史性突破。"}, {"title": "6月18日—20日，2025世界移动通信大会在上海举办。", "detail": "作为亚洲最具规模与影响力的通信信息产业\n盛会，本届大会以“连接之妙逐梦无限”为主题，汇聚全球领先的科技企业，紧扣AI+等内容，为公众呈现\n了一场AI创新盛宴。\n8\n(cid:3)"}, {"title": "华中科技大学6月22日发布消息，该校国家脉冲强磁场科学中心李亮教授团队于近日成功", "detail": "实现71.36\n特斯拉平顶脉冲磁场，刷新其团队于2018年创下的64特斯拉世界纪录，进一步巩固中国在该领域的国际领\n先地位。强磁场是现代科学实验最重要的极端条件之一，能够为基础科学研究发现新现象、揭示新规律提\n供更多机遇。"}, {"title": "近日，中国农业科学院农业经济与发展研究所发布的《中国农业产业发展报告2025》显", "detail": "示，2024年，\n我国农业持续发力，粮食产量首次跃上1.4万亿斤新台阶、亩产提升5.1公斤。《报告》预测，2025年我国\n农业生产将继续向好，粮食总产量预计将达到1.426万亿斤，大豆油料扩种持续增效，棉糖果生产稳中向好，\n生猪产能调控成效显现，猪肉进口下降，畜产品和水产品供应稳定。"}, {"title": "6月20日-22日，2025杭州国际人形机器人与机器人技术展览会在杭州大会展中心", "detail": "顺利举行，这是\n国内首个专注人形机器人全产业链的专业展会。本届杭州人形机器人展以“人形机器人赋能新型工业化”为主\n题，汇聚近300家国内外领军企业及科研机构参展。"}, {"title": "6月22日，随着直径达17.5米的“山河号”盾构机平稳穿越黄河南岸大堤，济南市黄", "detail": "岗路穿黄隧道顺\n利完成黄河段掘进任务，标志着世界最大直径水下盾构隧道工程建设完成又一重要节点。"}, {"title": "2025年全国节能宣传周启动仪式6月23日在山东青岛举行。", "detail": "今年的宣传周是我国第35个全国节能\n宣传周，时间为6月23日至29日，主题是“节能增效，焕‘新’引领”。"}, {"title": "当地时间6月23日，国际奥委会在瑞士洛桑举行主席交接仪式，国际奥委会主席巴赫将正", "detail": "式把主席\n职位移交给候任主席柯丝蒂·考文垂。在今年3月于希腊举行的第144届国际奥委会全会上，柯丝蒂·考文\n垂被选为国际奥委会第十任主席，巴赫被选为国际奥委会终身名誉主席。"}, {"title": "6月23日，黄河2025年调水调沙正式启动。", "detail": "作为黄河中下游防洪、水沙调控体系中的关键控制性工\n程，小浪底水利枢纽控制着黄河91.2％的径流量和近100%的输沙量。"}, {"title": "6月24日上午，国家主席习近平在北京人民大会堂会见来华进行正式访问的新加坡总理黄", "detail": "循财。习\n近平强调，中新要牢牢把握两国友好大方向，始终从战略高度和长远角度看待和发展中新关系，确保航向\n不偏、动力不减。要筑牢中新友好政治基础，支持彼此核心利益和重大关切，以更高水平政治互信服务两\n国关系发展。中方欢迎新方继续深度融入中国发展，双方要深入推进共建“一带一路”合作，打造数字经济、\n绿色发展、人工智能等领域标志性成果，推动重大项目提质升级，续写高质量合作新篇章。"}, {"title": "亚洲基础设施投资银行（亚投行）理事会6月24日选举邹加怡担任亚投行下一任行长。", "detail": "邹加怡的五\n年任期将于2026年1月16日开始。亚投行首任行长金立群的第二个五年任期将于2026年1月15日结束。"}, {"title": "近日发布的《世界独角兽企业发展报告2025》显示，截至2024年，全球独角兽企业", "detail": "数量1212家，\n其中，中国以370余家的数量，在全球独角兽领域占据近三成的份额。其中，2024年新晋独角兽企业135\n家，分布在全球17个国家和地区，中国新晋独角兽企业有53家，全球4家估值超百亿美元的超级独角兽中，\n3家为中国企业。"}, {"title": "6月25日，第35个全国“土地日”主场活动在湖北武汉举行。", "detail": "本次活动以“节约集约用地严守耕地\n红线”为主题。活动围绕这一主题，发布成果案例、交流典型经验等，共同夯实高质量发展和粮食安全根基。\n获取后续更新及更多考试资料，请加微信：(cid:3)"}, {"title": "6月25日，2025年夏季达沃斯论坛开幕式在天津举行。", "detail": "本届论坛主题为“新时代企业家精神”，在为\n期三天的会议中，与会者将围绕五大核心议题展开近200场分论坛讨论。"}, {"title": "6月25日上午，国务院总理李强在天津出席2025年夏季达沃斯论坛开幕式并致辞。", "detail": "李强表示，当\n前国际经贸格局正在发生深刻变化。经贸体系更趋多元，全球南方力量快速崛起；传统贸易增速放缓，新\n9\n(cid:3)\n(cid:3)\n兴贸易逆势增长；全球性机制受到冲击，区域协作日渐增多；跨境投资波动下行，产供链碎片化风险上升。\n我们应当顺应正道和大势，拿出智慧和担当，采取积极的态度和建设性的行动，坚定不移拥抱普惠包容的\n经济全球化，维护自由贸易和多边主义，促进世界经济稳定发展。"}, {"title": "6月25日从第十五届全运会组委会和全国第十二届残运会暨第九届特奥会组委会举办的新", "detail": "闻发布会\n上了解到，十五运会开幕式将以“圆梦未来”为主题，残特奥会开幕式将以“手牵手”为主题。"}, {"title": "6月25日从中国海油获悉，我国首个深水高压气田——“深海一号”二期项目全面投产。", "detail": "全面投产后，\n“深海一号”年产气量有望超过45亿立方米，成为我国产量最大、智能化程度最高的海上气田。"}, {"title": "6月25日，2025年“全国低碳日”主场活动在浙江杭州举办。", "detail": "今年的活动主题为“碳路先锋、绿动未\n来”，活动主办方倡议，各方积极参与到应对气候变化工作中来，从日常生产生活做起，节约资源、减少能\n源消耗，践行简约适度、绿色低碳、文明健康的生活理念和消费模式，携手推动高质量发展，共建清洁、\n美丽、可持续的未来。"}, {"title": "国务院总理李强6月26日上午在北京出席亚洲基础设施投资银行第十届理事会年会开幕式", "detail": "并致辞。\n李强表示，习近平主席在亚投行组建之初提出将亚投行打造成专业、高效、廉洁的新型多边开发银行。10\n年来，在全体成员共同支持和努力下，亚投行坚守初心、创新进取，成员从57个扩大到110个，事业不断\n发展壮大，树立了专业务实的良好形象，为各成员共同发展注入了新动能，为全球金融治理拓展了新模式，\n为国际多边合作树立了新典范。\n李强对亚投行未来发展提出三点希望。一是面对世界经济增长困境，更大力度支持成员提升发展能力。\n二是面对经贸格局重塑，更大范围增进国际对话交流协作。三是面对全球治理挑战，更好发挥自身新型多\n边平台功能。"}, {"title": "6月26日，我国自主研发的新一代国产通用处理器——龙芯3C6000在北京发布。", "detail": "最新发布的龙芯\n3C6000采用我国自主设计的指令系统龙架构，无需依赖任何国外授权技术，是我国自主研发、自主可控的\n新一代通用处理器，可满足通算、智算、存储、工控、工作站等多场景的计算需求。"}, {"title": "6月26日，全国首艘氢电拖轮“氢电拖1”轮在山东港口青岛港正式入列。", "detail": "该拖轮搭载“氢燃料电池+\n液冷锂电池”混动系统，可实现零碳排放，9节航速下续航超12小时，拖力达82吨。其创新应用北斗集成\n系统、全自动智能岸基充电等技术，填补多项国内空白，成为全国马力最大、锂电池容量最大的港作拖轮。"}, {"title": "6月26日，2025（中国）亚欧商品贸易博览会在新疆乌鲁木齐启幕。", "detail": "本届商博会以“共商亚欧合作共\n享丝路繁荣”为主题，设置14万平方米室内外展区，创新采用“1+10+N”展区布局。"}, {"title": "6月27日，十四届全国人大常委会第十六次会议表决通过新修订的治安管理处罚法，自2", "detail": "026年1\n月1日起施行。新修订的治安管理处罚法共6章144条，包括总则、处罚的种类和适用、违反治安管理的行\n为和处罚、处罚程序、执法监督、附则。"}, {"title": "近日，《中共中央办公厅国务院办公厅关于全面推进江河保护治理的意见》发布，主要目标", "detail": "是：\n到2035年，现代化流域防洪减灾体系基本完善，防洪安全保障能力显著提高；水资源节约集约利用水平进\n一步提高，城乡供水安全保障水平明显提升；江河生态环境质量全面改善，水生态系统健康稳定；水文化\n繁荣发展，影响力显著增强；江河保护治理体制机制更加完善，人水关系更加和谐。"}, {"title": "十四届全国人大常委会第十六次会议6月27日表决通过新修订的反不正当竞争法，自20", "detail": "25年10\n月15日起施行。新修订的反不正当竞争法包括总则、不正当竞争行为、对涉嫌不正当竞争行为的调查、法\n律责任、附则五章。"}, {"title": "市场监管总局6月27日发布的数据显示，截至2025年5月底，全国实有民营经济组织", "detail": "1.85亿户，\n10\n(cid:3)\n占经营主体总量的96.76%，同比增长2.3%。"}, {"title": "6月28日，2025能源产业生态论坛在北京举办。", "detail": "论坛以“面向‘十五五’，加速构建新型能源体系”为\n主题，由主论坛暨全体大会、三场分论坛、参观未来科学城活动等环节组成。"}, {"title": "2025年6月28日，全球首艘纯氨燃料内燃机动力示范船“氨晖号”在安徽合肥巢湖水", "detail": "域首航取得成\n功，标志着氨燃料在船舶领域的工业化应用取得重大突破，为航运业节能减排、绿色发展开辟了一条切实\n可行的全新路径，对加快构建清洁低碳、安全高效的水上交通能源体系具有重大里程碑意义。"}, {"title": "6月28日发布的《中国能源生态报告》显示，2024年，我国清洁能源投资规模达到6", "detail": "250亿美元，\n占全球比重的1/3。光伏、风电装机容量连续10年位居全球首位，十年间，中国对全球非化石能源消费增\n量贡献率超过45%。"}, {"title": "近日，从中国能建获悉，新疆大石峡水利枢纽工程首台机组转子顺利完成吊装，标志着世界", "detail": "最高混\n凝土面板堆石坝发电机组进入总装阶段。大石峡水利枢纽工程位于天山西部的新疆阿克苏地区库玛拉克河\n中下游的大石峡峡谷处，最大坝高247米，相当于80多层楼的高度，是世界在建最高混凝土面板堆石坝。"}, {"title": "近日，习近平给西藏林芝市巴宜区林芝镇嘎拉村全体村民回信，对他们提出殷切期望。", "detail": "习近平强调，\n大家在信里说得好，看着北斗星走不迷路，跟着共产党走会幸福。希望你们在党的兴边富民好政策引领下，\n切实维护好民族团结，创造更加幸福美好的生活，把雪域高原的自然美景保护好，把“桃花村”品牌擦得更亮，\n为建设繁荣稳固的祖国边疆贡献力量。"}, {"title": "从国家知识产权局获悉：截至2025年5月，我国国内有效发明专利拥有量达到497万", "detail": "件。目前，我\n国已建设77个国家级知识产权保护中心，为各类主体提供“一站式”知识产权保护服务。\n11\n(cid:3)"}]}, {"month": "2025年7月", "year": 2025, "items": [{"title": "中共中央政治局6月30日下午就健全落实中央八项规定精神、纠治“四风”长效机制进行", "detail": "第二十一次集\n体学习。习近平在主持学习时强调，自我革命是我们党跳出治乱兴衰历史周期率的第二个答案，从抓作风\n入手推进全面从严治党是新时代党的自我革命一条重要经验。推进党的自我革命，要在提高认识、增强党\n性、规范权力运行、从严监督执纪、履行管党治党责任等方面进一步落实到位。\n习近平指出，推进自我革命，必须固本培元、增强党性。增强党性，重在坚定理想信念，铸牢对党忠\n诚，厚植为民情怀，纯正道德品质，保持清正廉洁。"}, {"title": "中共中央政治局6月30日召开会议，审议《党中央决策议事协调机构工作条例》。", "detail": "会议指出，设立\n党中央决策议事协调机构，是健全党中央对重大工作集中统一领导、推动重大任务落实的重要制度安排。\n制定出台《党中央决策议事协调机构工作条例》，进一步规范党中央决策议事协调机构的设立、职责和运\n行，对于发挥好对重大工作的顶层设计、统筹协调、整体推进、督促落实职能作用，具有重要意义。"}, {"title": "中央组织部最新党内统计数据显示，截至2024年底，中国共产党党员总数为10027", "detail": ".1万名，比上年净\n增108.6万名。党的基层组织525.0万个，比上年净增7.4万个。"}, {"title": "日前，国务院办公厅印发《促进残疾人就业三年行动方案（2025－2027年）》，《", "detail": "行动方案》强调，\n要按照政府扶持、部门协同、市场推动、社会参与的工作思路，进一步拓宽残疾人就业创业渠道，优化就\n业结构，促进残疾人就业质量稳中有升，更好保障残疾人就业权益，推动残疾人就业创业服务提质增效，\n积极营造全社会关心支持残疾人就业创业的良好社会氛围和环境。"}, {"title": "7月1日出版的第13期《求是》杂志将发表习近平的重要文章《团结奋斗是中国人民创造", "detail": "历史伟业的\n必由之路》。文章指出，围绕明确奋斗目标形成的团结才是最牢固的团结，依靠紧密团结进行的奋斗才是\n最有力的奋斗。新征程上我们就要靠中国式现代化进一步凝心聚力、团结奋斗。\n文章指出，幸福都是奋斗出来的，奋斗本身就是一种幸福。民族复兴的使命要靠奋斗来实现，人生理\n想的风帆要靠奋斗来扬起。奋斗是艰辛的、长期的、曲折的，必须准备付出更为艰巨、更为艰苦的努力。\n我国正处于实现中华民族伟大复兴关键时期，改革发展正处在攻坚克难的重要阶段，在前进道路上，我们\n面临的重大斗争不会少。面对围堵、遏制、打压，我们应理直气壮地进行斗争。必须发扬斗争精神，把握\n斗争方向，掌握斗争规律，增强斗争本领，有效应对重大挑战、抵御重大风险、克服重大阻力、解决重大\n矛盾，不断夺取新时代伟大斗争的新胜利。"}, {"title": "习近平7月1日上午主持召开中央财经委员会第六次会议，研究纵深推进全国统一大市场建", "detail": "设、海洋\n经济高质量发展等问题。会议指出，纵深推进全国统一大市场建设，基本要求是“五统一、一开放”，即统一\n市场基础制度、统一市场基础设施、统一政府行为尺度、统一市场监管执法、统一要素资源市场，持续扩\n大对内对外开放。"}, {"title": "中央宣传部、国家发展改革委近日发布了2024年“诚信之星”。", "detail": "此次发布的“诚信之星”分别是：山西省\n晋城市城区北石店镇南石店村村民刘平贵、李继林夫妇，内蒙古自治区包头市达茂旗满都拉镇巴音哈拉嘎\n查牧民、护边员阿迪雅，中国邮政集团有限公司黑龙江省漠河市分公司北极村支局投递员王秀珑，上海市\n公安局浦东分局梅园新村派出所副所长姜经纬，江苏省淮安市金湖县金南镇退役军人服务队队长於如桂，\n江西省抚州市广昌县远泰食药用菌研究所所长谢远泰，广西壮宏文化发展有限公司董事长兰培文，重庆市\n铜梁区巴川街道袁家社区居民陈淑梅，宁夏回族自治区中卫市沙坡头区永康镇艾湾村村民刘金录，新疆维\n吾尔自治区巴音郭楞蒙古自治州和静县哈尔莫敦镇哈尔莫敦村村民付志周。"}, {"title": "近日，随着新疆吉木萨尔北庭100万千瓦+20万千瓦/100万千瓦时全钒液流储能一", "detail": "体化项目主体工程\n1\n(cid:3)\n顺利完工，项目建设进入收尾阶段。该项目装机容量1000兆瓦，年平均发电量约17.2亿千瓦时，与传统火\n电站相比，每年可减少二氧化碳排放量超160万吨，其作为全国最大全钒液流储能项目，“全国之最”体现在\n装机容量1000兆瓦、储能规模100万千瓦时且时长5小时，能源转化和供应能力强。"}, {"title": "中华全国青年联合会第十四届委员会全体会议、中华全国学生联合会第二十八次代表大会7", "detail": "月2日上\n午在北京开幕。习近平发来贺信，习近平指出，以中国式现代化全面推进强国建设、民族复兴伟业，青年\n大有可为。广大青年要自觉听从党和人民召唤，坚定理想信念，厚植家国情怀，勇担历史使命，奋力书写\n挺膺担当的青春篇章。"}, {"title": "7月2日，我国海事系统规模最大、装备最先进的专业溢油回收船——“海巡041”轮在", "detail": "河北正式列编，\n这标志着我国环渤海区域溢油应急处置能力迈上新台阶，为守护区域海洋生态环境和海上安全提供了强有\n力的装备支撑。"}, {"title": "7月2日，全球首台单机容量最大500兆瓦、转轮尺寸最大6.23米的冲击式水轮机转", "detail": "轮在哈电集团哈\n尔滨电机厂有限责任公司自主研制成功并发运，标志着我国在高水头、大容量冲击式水轮机组核心装备领\n域实现历史性突破。该转轮将应用于西藏扎拉水电站。"}, {"title": "7月2日，2025全球数字经济大会在北京国家会议中心开幕。", "detail": "本届大会以“建设数字友好城市”为主题，\n呈现开放共享、聚焦前沿、产业融合、增强体验四大亮点。"}, {"title": "7月3日，第十三届世界和平论坛在位于北京的清华大学开幕。", "detail": "本届论坛以“共促世界和平与繁荣：\n共担、共享、共赢”为主题。嘉宾将探讨如何通过加强国际合作、共同承担维护和平、促进发展的责任，共\n享全球化带来的机遇，最终实现世界各国的共同繁荣和持久和平。"}, {"title": "2025年7月3日17时35分，我国在西昌卫星发射中心使用长征四号丙运载火箭，成", "detail": "功将试验二十\n八号B星01星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。试验二十八号B星01星主要\n用于空间环境探测及相关技术试验。"}, {"title": "工业和信息化部日前印发通知，部署开展号码保护服务业务试点工作，其中为满足开展号码", "detail": "保护服\n务业务的码号资源需求，并与固定、移动用户号码明显区分，便于用户识别，规划700号段作为号码保护服\n务业务的专用码号资源。"}, {"title": "当地时间7月2日，中共中央政治局委员、外交部长王毅在布鲁塞尔同欧盟外交与安全政策", "detail": "高级代\n表卡拉斯举行第十三轮中欧高级别战略对话。王毅说，中欧不存在根本利害冲突，有着广泛共同利益。双\n方都支持多边主义和开放合作，都支持联合国核心地位和国际关系民主化，都坚持通过对话和平解决争端。\n面对国际局势不确定、不稳定性上升，中欧作为两大力量和两大经济体，应加强交往、深化了解、增进互\n信、推进合作，共同维护战后国际秩序，为世界提供稀缺的确定性。"}, {"title": "2025两岸青年峰会7月3日在北京开幕，海峡两岸各界人士和青年代表700余人出席", "detail": "开幕式。此次\n峰会以“携手绘青春奋进新时代”为主题，将举办主论坛、分论坛、科技文化融合成果展等交流活动。"}, {"title": "7月3日，2025上合组织国家电影节在重庆市永川区开幕。", "detail": "电影节期间将集中展映来自上合组织国\n家的28部优秀影片。本届电影节以“科技光影·上合风采”为主题。"}, {"title": "7月4日，随着三峡江苏大丰海上风电项目9号机组叶片缓缓转动，我国当前离岸距离最远", "detail": "的海上风\n电项目实现首批机组并网，为我国海上风电向深远海发展再进一步。江苏大丰海上风电项目位于江苏省盐\n城市大丰区东北方向海域，最远点离岸距离85.5千米，是我国目前已并网发电离岸距离最远的海上风电项\n目。项目共安装98台风电机组，总装机容量800兆瓦。"}, {"title": "近日，中共中央办公厅、国务院办公厅印发《关于全面推进江河保护治理的意见》。", "detail": "《意见》提出，\n2\n(cid:3)\n坚持节水优先、空间均衡、系统治理、两手发力的治水思路，坚持重在保护、要在治理，以流域为单元，\n统筹推进水灾害、水资源、水生态、水环境治理，传承弘扬水文化，健全江河保护治理制度，形成江河哺\n育人民、人民守护江河、人水和谐共生的江河保护治理格局。"}, {"title": "7月5日从华北油田山西煤层气分公司获悉，作为我国最大中浅层煤层气田——华北油田山", "detail": "西沁水煤\n层气田，截至7月4日的累计产气量超过200亿立方米，成为国内首个累计产量突破200亿立方米的煤层气\n田。"}, {"title": "7月5日上午，2025年生态文明贵阳国际论坛在贵州省贵阳市开幕，国内外政要及前政", "detail": "要、相关国\n际组织负责人等约800名嘉宾出席。本届论坛主题为“人与自然和谐共生——共商全球发展绿色转型”，举办\n开幕式、场外参观、绿色招商等活动和主宾省系列活动，围绕“共谋全球生态文明与可持续发展”“应对气候\n变化”“生物多样性保护”“多元协同治理”4个板块，共设置20个主题论坛。"}, {"title": "近日，海南大学新能源光电材料与器件团队自主研发的钙钛矿太阳能电池，经中国国家光伏", "detail": "产业计量\n测试中心认证，稳态光电转换效率达27.32%，这一数值超越了美国国家可再生能源实验室今年2月公布的"}, {"title": "95%效率纪录，以及马丁·格林太阳能电池效率统计表5月收录的27.3%行业标杆值", "detail": "，标志着海南大学在\n第三代光伏技术领域跻身全球领先行列。"}, {"title": "日前，国务院印发《关于做好自由贸易试验区全面对接国际高标准经贸规则推进高水平制度", "detail": "型开放\n试点措施复制推广工作的通知》。其中提出，各地区、各部门要统筹开放和安全，完善风险防控制度，加\n强风险评估预警，强化风险防范化解，在推动措施落地见效的同时，实施与之相适应的风险防控措施，健\n全权责明确、公平公正、公开透明、简约高效的监管体系。对出现的新情况、新问题，要及时研究解决，\n不断调整优化实施举措。"}, {"title": "近日，习近平委托中央组织部负责同志向国家话剧院一级演员游本昌转达勉励和问候。", "detail": "6月30日上\n午，92岁的游本昌宣誓加入中国共产党。"}, {"title": "当地时间7月5日，国务院总理李强在里约热内卢会见巴西总统卢拉。", "detail": "李强指出，中方愿同巴方发\n挥互补优势，在高质量共建“一带一路”框架下，巩固深化双边贸易、金融、基础设施建设等合作，拓展数字\n经济、绿色经济、科技创新、航天等领域合作，增强两国发展动能。"}, {"title": "当地时间7月6日上午，为期两天的金砖国家领导人第十七次会晤在巴西里约热内卢正式开", "detail": "幕。本\n次会晤以“加强全球南方合作，推动更加包容和可持续的全球治理”为主题，围绕六大议题展开，涵盖全球卫\n生健康、贸易投资与发展融资、应对气候变化、人工智能治理、全球安全架构改革以及金砖机制自身建设\n等关键领域。"}, {"title": "7月6日，第十二届世界高铁大会的吉祥物命名正式公布。", "detail": "大会吉祥物以“国宝”大熊猫为原型，身着\n高铁司机和客运员制服，形象生动活泼。吉祥物命名为“福福”和“馨馨”，与“复兴”发音相契合，向世界传递\n高铁创新发展、为人类创造美好生活的愿景。"}, {"title": "当地时间7月6日，国务院总理李强在里约热内卢出席金砖国家领导人第十七次会晤第一阶", "detail": "段会议，\n就“和平与安全、全球治理改革”议题发表讲话。李强表示，当前，世界百年变局加速演进，国际规则和秩序\n遭受严重冲击，多边机制权威和效能减弱。习近平主席提出的共商共建共享的全球治理观更加彰显出其时\n代价值和现实意义。在激化加剧的矛盾分歧面前，我们需要以平等尊重的态度更好共商。在深度交融的共\n同利益面前，我们需要以团结协作的行动更好共建。在合则互惠的发展机遇面前，我们需要以相互成就的\n胸怀更好共享。"}, {"title": "7月7日上午，纪念全民族抗战爆发88周年仪式暨《为了民族解放与世界和平》主题展览", "detail": "开幕式在\n3\n(cid:3)\n中国人民抗日战争纪念馆举行。蔡奇在讲话中指出，88年前的今天，日本军国主义蓄意制造震惊中外的卢\n沟桥事变，悍然发动全面侵华战争。中国军民奋起抵抗，全民族抗战爆发，并开辟了世界反法西斯战争的\n东方主战场。中国共产党勇敢战斗在抗日战争最前线，引领中国抗战的前进方向，成为全民族抗战的中流\n砥柱，全体中华儿女前赴后继、勠力同心，为国家生存而战、为民族复兴而战、为人类正义而战，赢得了\n中国人民抗日战争的伟大胜利，为世界反法西斯战争胜利作出了重大贡献。"}, {"title": "国际深空探测学会成立大会7月7日在安徽合肥举行。", "detail": "这是我国首个深空探测领域国际科技组织。\n国际深空探测学会由深空探测实验室、中国国家航天局探月与航天工程中心、中国宇航学会、中国空间科\n学学会及法国行星探测地平线2061五家单位联合倡议，汇聚20位国内院士与31名国外科学家共同发起申\n请，历经两年多筹备，于今年4月经国务院批准，成为在民政部注册具有独立法人资格的非营利性国际科\n技组织。"}, {"title": "近日，国内首座工厂化全海水漂浮式光伏项目在中国石化青岛炼化公司并网发电。", "detail": "该项目位于山东\n青岛西海岸新区，装机容量7.5兆瓦，创新采用漂浮式结构，光伏板随潮汐升降贴近水面，利用海水高效散\n热提升发电效率。预计年发绿电近1000万千瓦时，减排二氧化碳0.83万吨，为沿海地区推广提供了重要示\n范。"}, {"title": "习近平近日在山西考察时强调，山西要认真落实党中央关于促进中部地区加快崛起、推动黄", "detail": "河流域\n生态保护和高质量发展等战略部署，坚持稳中求进工作总基调，完整准确全面贯彻新发展理念，统筹好发\n展和安全，努力在推动资源型经济转型发展上迈出新步伐，奋力谱写三晋大地推进中国式现代化新篇章。\n习近平强调，转型发展必须牢牢守住安全稳定底线。要着力稳就业、稳企业、稳市场、稳预期，强化“一\n老一小”等重点民生保障服务，兜牢困难群众基本生活。"}, {"title": "当地时间7月6日和7日，国务院总理李强在里约热内卢出席金砖国家领导人第十七次会晤", "detail": "第二及\n第三阶段会议，围绕加强多边主义、人工智能、环境和气候变化、全球卫生等议题发表讲话。李强表示，\n当前国际经贸秩序、多边贸易体制受到严重冲击，世界经济复苏艰难。“大金砖合作”要秉持成立初衷，契合\n时代之需，维护和践行多边主义，推动建设公平开放的国际经贸秩序，凝聚全球南方力量，为世界稳定发\n展作出更大贡献。一是致力于构建开放型世界经济。二是致力于提升国际金融合作水平。三是致力于开辟\n经济增长新蓝海。中方将在全球发展倡议框架下打造“数字南方”品牌，未来5年为南方国家举办200期数字\n经济、人工智能培训项目。"}, {"title": "7月8日上午，第十二届世界高速铁路大会在北京国家会议中心开幕，本届大会以“高速铁", "detail": "路：创新\n发展让生活更美好”为主题，国内外铁路技术人员、企业负责人、政府官员和国际组织代表等2000余人参加\n开幕式。"}, {"title": "天舟八号货运飞船7月8日顺利撤离空间站组合体，将于近期择机受控再入大气层。", "detail": "2024年11月15\n日，天舟八号货运飞船在我国文昌航天发射场发射升空，11月16日成功对接于空间站天和核心舱后向端口。"}, {"title": "首届上海合作组织标准化合作会议7月8日在山东省青岛市举行。", "detail": "此次会议标志着首次在上海合作\n组织框架下成立标准化合作机制，为成员国标准化合作提供制度保障。"}, {"title": "7月8日，我国规模最大的绿色氢氨一体化项目在内蒙古赤峰正式投产，项目一期年产32", "detail": "万吨绿色\n合成氨，标志着我国绿色氢氨产业从示范探索迈入规模化商业运营的新阶段。"}, {"title": "第十次全国对口支援新疆工作会议7日至9日在新疆和田召开。", "detail": "沪宁表示，对口援疆是国家战略，\n必须长期坚持。要更加注重在解决南疆突出问题上聚焦发力，巩固拓展南疆脱贫攻坚成果，推动南疆经济\n社会发展和长治久安。要更加注重在推进新疆新型工业化城镇化上聚焦发力，紧贴民生推动新疆高质量发\n4\n(cid:3)\n展。要更加注重在促进各民族交往交流交融上聚焦发力，让各民族像石榴籽一样紧紧抱在一起。要更加注\n重在有形有感有效开展文化润疆上聚焦发力，不断增进各族群众“五个认同”。要更加注重在提升教育援疆效\n果上聚焦发力，推动新疆加快建设高质量教育体系。"}, {"title": "7月9日，第十一届尼山世界文明论坛在山东曲阜开幕。", "detail": "本届论坛以“各美其美·美美与共——文明\n间关系与全球现代化”为主题，下设“文明的起源与未来发展”“儒家文化的世界意义和时代价值”等6个分议\n题，共有来自70多个国家的560余名嘉宾齐聚尼山脚下，开展文明交流和对话，共同探讨不同文明和谐共\n处、和合共生之道。"}, {"title": "国家发展改革委办公厅等四部门发布《关于促进大功率充电设施科学规划建设的通知》。", "detail": "明确到2027\n年底，力争全国范围内大功率充电设施超过10万台，服务品质和技术应用实现迭代升级。"}, {"title": "国家统计局7月10日发布数据显示，2025年全国夏粮总产量14973.8万吨（2", "detail": "994.8亿斤），比上年\n减少3.1亿斤，下降0.1%；全国夏粮播种面积3.99亿亩，比上年减少52.0万亩，下降0.1%，保持基本稳定；\n全国夏粮单产375.6公斤/亩，比上年增加0.1公斤/亩，基本持平。"}, {"title": "中国汽车工业协会7月10日发布的数据显示，2025年上半年我国汽车产销量首次双超", "detail": "1500万辆，\n均同比实现两位数增长，汽车产业活力持续释放。"}, {"title": "7月10日，全球文明对话部长级会议在北京开幕，本次会议主题为“维护人类文明多样性", "detail": "共促世界\n和平发展”。来自约140个国家和地区的政界、文化界、教育界人士等600余人出席开幕式。"}, {"title": "7月10日，习近平向全球文明对话部长级会议致贺信。", "detail": "习近平强调，中国愿同各国一道，秉持平等、\n互鉴、对话、包容的文明观，践行全球文明倡议，推动构建全球文明对话合作网络，为人类文明进步、世\n界和平发展注入新的动力。希望各位代表深入交流、凝聚共识，为促进各国人民相知相亲、不同文明和合\n共生贡献智慧和力量。"}, {"title": "7月10日，据国家管网集团消息，我国“北气南下”能源大通道累计输气量突破1000", "detail": "亿立方米。作为\n我国“十四五”期间建成的重要能源基础设施，“北气南下”能源大通道北起黑龙江黑河，南至上海，途经9个\n省区市。"}, {"title": "7月11日，2025上合组织数字经济论坛在天津开幕。", "detail": "本次论坛主题为“数字经济新纽带共拓合作新\n空间”，旨在加强与上合组织各国交流互鉴、深化合作，构建更加紧密的合作伙伴关系，共拓数字经济合作\n发展新空间。"}, {"title": "2025年日本大阪世博会中国国家馆日7月11日在日本大阪举行。", "detail": "大阪世博会于4月13日至10月13\n日举办，主题为“构想焕发生机的未来社会”。中国贸促会代表中国政府组织参展的中国馆以“共同构建人与\n自然生命共同体——绿色发展的未来社会”为主题，全面展示中国传统生态智慧，展现中国绿色发展理念，\n推动中外文明交流互鉴和民心相通。"}, {"title": "中共中央党史和文献研究院编辑的《习近平生态文明文选》第一卷，近日由中央文献出版社", "detail": "出版，\n在全国发行。习近平生态文明思想是习近平新时代中国特色社会主义思想的重要组成部分，是马克思主义\n基本原理同中国具体实际相结合、同中华优秀传统文化相结合的重大成果，把我们党对生态文明建设规律\n的认识提升到新高度，为以美丽中国建设全面推进人与自然和谐共生的现代化提供了根本遵循。"}, {"title": "近日，国家卫生健康委等七部门联合发布了《关于加快推进普惠托育服务体系建设的意见》", "detail": "，《意\n见》明确提出，要发展“1+N”的托育服务体系，就是以托育综合服务中心为枢纽，发挥示范引领、辐射带动\n作用，建设社区嵌入式托育、幼儿园托班、用人单位办托、家庭托育点等多种形式的托育服务机构。最新\n数据显示，截至2024年底，全国每千人口托位数达到4.08个，国家“十四五”规划《纲要》提出“到2025年\n5\n(cid:3)\n千人口托位数达到4.5个”。"}, {"title": "当地时间2025年7月11日，在法国巴黎召开的联合国教科文组织第47届世界遗产大", "detail": "会通过决议，\n将我国申报的位于宁夏银川的“西夏陵”列入《世界遗产名录》。至此，我国世界遗产总数达到60项，其中\n包括世界文化遗产41项、自然遗产15项、文化与自然双遗产4项。西夏陵是中国西北地区11至13世纪由\n党项族建立的西夏王朝（1038—1227年）的陵墓遗址群。西夏陵是西夏留存至今规模最大、等级最高、保\n存完整的考古遗存，直接为中国历史上延续近200年的西夏王朝及其君主世系提供不可替代的见证作用，实\n证了西夏王朝在丝绸之路上的中继枢纽地位。"}, {"title": "7月11日，中非合作论坛－法治论坛（2025）在湖南长沙开幕，论坛主题是“深化经", "detail": "贸法治合作，共\n筑高水平中非命运共同体”。"}, {"title": "以“两岸薪火，青春力量”为主题的第八届海峡两岸青年发展论坛7月11日上午在浙江杭", "detail": "州开幕，来\n自两岸的嘉宾和青年1000余人参加论坛相关活动，加深彼此了解、促进交流合作。"}, {"title": "7月12日是国际防治沙尘暴日。", "detail": "2025年我国的宣传主题为“防治沙尘灾害共同守护蓝天”。近十多年\n来，累计完成沙化土地治理任务3.65亿亩，封禁保护面积2794万亩，在全球率先实现土地退化零增长目标。"}, {"title": "7月12日上午，第七届中国粮食交易大会在辽宁沈阳开幕。", "detail": "本届大会以“粮安天下聚合力、产销融通\n促发展”为主题，来自全国的4000多家企业，2万余名行业人员参会。"}, {"title": "7月12日，2025绿色算力（人工智能）大会在内蒙古呼和浩特市开幕。", "detail": "本次大会以“共筑绿色算力大\n生态共创人工智能新未来”为主题，汇聚全国前沿智慧，共绘产业发展蓝图。"}, {"title": "2025国际基础科学大会7月13日在北京开幕，主题为“聚焦基础科学引领人类未来”", "detail": "，共有80多位\n中外院士、近千名国内外专家学者参会，大会将持续到25日。"}, {"title": "7月13日，历时15年建设，总长4197公里的环塔里木盆地750千伏输变电工程全", "detail": "线贯通，这意味\n着我国最大的盆地——塔里木盆地装上了电力“能量环”。"}, {"title": "7月13日从中国海油获悉，由我国自主建造的24套2000米级超深水吸力锚在珠海启", "detail": "运至巴西，这\n是目前我国对外交付的应用水深最大的深海油气装备之一。"}, {"title": "7月13日，由黄埔文冲建造的我国首艘海洋级智能综合科考船“同济”号在上海正式交付。", "detail": "“同济”号\n是我国自主设计、建造的2000吨级新一代绿色、静音、智能型综合科考船，集海洋地质、海洋化学、海洋\n生物等科考调查，以及科学研究、人才培养、科普教育和文化传承等多功能于一体，是同济大学着力打造\n的“海上校区”。与以往的科考船相比，“同济”号更加智能。"}, {"title": "国家医保局7月14日发布《2024年全国医疗保障事业发展统计公报》。", "detail": "截至2024年底，全国基本\n医保参保132662.08万人，参保率巩固在95%。"}, {"title": "近日，位于内蒙古自治区鄂尔多斯市的“国铀一号”示范工程生产出第一桶铀产品。", "detail": "这标志着我国铀\n资源开发迈入绿色安全、智能高效的新阶段，将为国家能源安全与核工业发展提供坚实的资源保障，同时\n也将大幅度提升我国天然铀产业的国际竞争力。"}, {"title": "人力资源社会保障部、财政部日前印发《关于2025年调整退休人员基本养老金的通知》", "detail": "，《通知》\n明确，从2025年1月1日起，为2024年底前已按规定办理退休手续并按月领取基本养老金的退休人员提高\n基本养老金水平，总体调整水平为2024年退休人员月人均基本养老金的2%。"}, {"title": "“十四五”期间，我国把创新提到前所未有的重要位置，创新成为推动高质量发展的主要驱", "detail": "动力。2024\n年，全社会研发经费投入规模比“十三五”末增长近50%，达到3.6万亿元，稳居全球第二。"}, {"title": "7月14日，第十二届世界化学工程大会暨第二十一届亚太化工联盟大会在北京开幕。", "detail": "这是世界化学\n6\n(cid:3)\n工程大会与亚太化工联盟大会50年来首次联袂在中国召开。本届大会以“迎接全球挑战的化学工程范式变革”\n为主题，旨在构建一个国际化学术交流、产学研融合的重要舞台，共议化学工程的范式变革，共享前沿技\n术与创新成果，共促全球化工领域的繁荣与发展。"}, {"title": "7月15日5时34分，搭载天舟九号货运飞船的长征七号遥十运载火箭，在我国文昌航天", "detail": "发射场点火\n发射，约10分钟后，天舟九号货运飞船与火箭成功分离并进入预定轨道，之后飞船太阳能帆板顺利展开，\n发射取得圆满成功。"}, {"title": "中央城市工作会议7月14日至15日在北京举行。", "detail": "会议指出，党的十八大以来，党中央深刻把握新\n形势下我国城市发展规律，坚持党对城市工作的全面领导，坚持人民城市人民建、人民城市为人民，坚持\n把城市作为有机生命体系统谋划，推动城市发展取得历史性成就，我国新型城镇化水平和城市发展能级、\n规划建设治理水平、宜业宜居水平、历史文化保护传承水平、生态环境质量大幅提升。\n会议指出，我国城镇化正从快速增长期转向稳定发展期，城市发展正从大规模增量扩张阶段转向存量\n提质增效为主的阶段。城市工作要深刻把握、主动适应形势变化，转变城市发展理念，更加注重以人为本；\n转变城市发展方式，更加注重集约高效；转变城市发展动力，更加注重特色发展；转变城市工作重心，更\n加注重治理投入；转变城市工作方法，更加注重统筹协调。"}, {"title": "国家统计局7月15日发布数据，初步核算，2025上半年我国国内生产总值（GDP）", "detail": "660536亿元，按\n不变价格计算，同比增长5.3%。国民经济顶住压力、迎难而上，经济运行总体平稳、稳中向好。"}, {"title": "国家统计局7月15日发布数据，2025上半年，全国居民人均可支配收入21840元", "detail": "，比上年同期名义\n增长5.3%，2025上半年，全国居民人均消费支出14309元，比上年同期名义增长5.2%，扣除价格因素影响，\n实际增长5.3%。"}, {"title": "7月15日，2025年世界青年发展论坛在江苏苏州开幕。", "detail": "本届论坛以“拓展青年潜能助力全球发展”\n为主题，分设绿色消费与可持续发展、人工智能与科技创新、文化遗产保护与传承三场主题论坛。"}, {"title": "7月15日上午，国家主席习近平在北京人民大会堂会见来华进行正式访问的澳大利亚总理", "detail": "阿尔巴尼\n斯。习近平指出，在双方共同努力下，中澳关系近年来走出低谷、实现转圜，给两国人民带来了实实在在\n福祉。这给我们最大的启示就是，坚持平等相待、求同存异、互利合作符合中澳两国和两国人民根本利益，\n无论国际风云如何变化，都应该坚持这个大方向不动摇。中澳全面战略伙伴关系已经开启第二个10年，中\n方愿同澳方一道，推动中澳关系进一步向前、向好发展，更好造福两国人民。"}, {"title": "7月16日出版的第14期《求是》杂志将发表习近平的重要文章《坚定不移推进高水平对", "detail": "外开放》。\n这是习近平总书记2012年12月至2025年4月期间有关重要论述的节录。文章强调，开放带来进步，封闭\n必然落后。中国的发展离不开世界，世界的繁荣也需要中国。不断扩大对外开放、提高对外开放水平，以\n开放促改革、促发展，是我国发展不断取得新成就的重要法宝。中国开放的大门不会关闭，只会越开越大。\n文章指出，要不断扩大高水平对外开放。过去中国经济发展是在开放条件下取得的，未来中国经济实\n现高质量发展也必须在更加开放条件下进行。要以国内大循环吸引全球资源要素，增强国内国际两个市场\n两种资源联动效应。稳步扩大规则、规制、管理、标准等制度型开放，主动对接国际高标准经贸规则，深\n化外贸、外商投资和对外投资管理体制改革，营造市场化、法治化、国际化一流营商环境。"}, {"title": "7月16日，第三届中国国际供应链促进博览会开幕式在北京举办。", "detail": "本届链博会主题为“链接世界、共\n创未来”。泰国担任主宾国，山东、广东担任主宾省。本届链博会设置先进制造链、智能汽车链、绿色农业\n链、清洁能源链、数字科技链、健康生活链等6大链条和供应链服务展区。75个国家和地区651家企业和\n机构参展，集中展示各链条上中下游关键环节的新技术、新产品、新服务，其中境外参展商占比达35%。\n7\n(cid:3)"}, {"title": "7月17日，国务院新闻办公室举行“高质量完成‘十四五’规划”系列主题新闻发布会，", "detail": "国家知识产权局\n相关负责人介绍“十四五”时期知识产权强国建设新进展新成效。据介绍，截至2025年6月，国内发明专利\n有效量达501万件。我国每万人口高价值发明专利拥有量已经达到15.3件，提前实现“十四五”规划预期的\n12件目标。"}, {"title": "近日，由中国科学院高能物理研究所牵头在西藏阿里地区海拔5250米的山脊上建设的阿", "detail": "里原初引力\n波探测实验一期（AliCPT-1）建成，并实现了首光观测。这是我国首次开展原初引力波探测实验。实验成功\n获取了月球和木星辐射的150GHz频段清晰图像，标志着我国在原初引力波探测实验领域迈出了关键一步。"}, {"title": "我国最大的地下储气库群——中原储气库群再度扩容，规模增加到7座，新增库容7.08", "detail": "亿立方米，\n为京津冀在内的大华北地区及黄河流域季节调峰、应急供气提供保障。"}, {"title": "近日，以“推进系统性变革实现数智化发展”为主题的第四届中国报业创新发展大会在浙江", "detail": "杭州拉开\n序幕。来自各省级党委宣传部、中央和地方报纸出版单位、网站平台、行业协会等的700多位嘉宾齐聚盛夏\n的杭州，共商合作、共谋发展、共话未来。"}, {"title": "近日，第二届上海合作组织国家电视节在陕西西安开幕，本届电视节以“汇文明·创视听·", "detail": "共未来”\n为主题。举行3场平行主题交流活动和上合组织国家视听节目展播等系列配套活动。"}, {"title": "7月18日上午，中国—上海合作组织地方经贸合作大会在山东青岛开幕。", "detail": "此次大会以“共谋区域合作\n携手创新发展”为主题，邀请近300位中外嘉宾参会，共话上合机遇，共商合作大计，进一步搭建起山东与\n上合组织国家地方经贸合作交流的重要平台，为促进经济全球化、构建开放型的世界经济注入更加强劲的“上\n合力量”。"}, {"title": "据海关统计，2025年上半年，我国货物贸易进出口总值21.79万亿元，同比增长2", "detail": ".9%，比前5个月\n加快0.4个百分点。其中，出口13万亿元，历史同期首次突破13万亿元，同比实现7.2%的较快增长；进口"}, {"title": "79万亿元，同比下降2.7%，降幅相比前5个月收窄1.1个百分点。", "detail": ""}, {"title": "7月18日，国内首个以“气象经济”为核心的国家级博览会——首届气象经济博览会在安", "detail": "徽合肥启幕。\n本届博览会以“气象融入新经济，携手共创好未来”为主题，汇聚来自气象、新能源、人工智能、低空经济、\n交通旅游、健康农业等20多个领域百余家企业，旨在打造国家级、综合性气象经济交流合作平台。"}, {"title": "第47届世界遗产大会日前在法国巴黎落下帷幕。", "detail": "联合国教科文组织7月17日发布新闻公告说，本\n届大会决议将26处文化和自然遗产列入《世界遗产名录》，使列入名录的世界遗产总数达到1248处。"}, {"title": "雅鲁藏布江下游水电工程开工仪式7月19日上午在西藏自治区林芝市举行。", "detail": "雅鲁藏布江下游水电工\n程位于西藏自治区林芝市。工程主要采取截弯取直、隧洞引水的开发方式，建设5座梯级电站，总投资约"}, {"title": "2万亿元。", "detail": "工程电力以外送消纳为主，兼顾西藏本地自用需求。"}, {"title": "近日，自然资源部发布《2024年全国海水利用报告》。", "detail": "《报告》显示，2024年全国现有海水淡化工\n程158个，工程规模285.6万吨/日，比2023年增加了33.3万吨/日。"}, {"title": "近日，中央宣传部、中央军委政治工作部联合发布12名“最美新时代革命军人”。", "detail": "张灿灿、马少利、\n陈思麒、崔道虎、何元智、李慧灵、谢亮、王超、傅达林、傅婉娟、雷耀明、布和图木尔等12名官兵，是\n全军部队坚决听党指挥、强化使命担当、埋头苦干实干、狠抓工作落实，奋力推进新时代强军事业中涌现\n出的先进典型。"}, {"title": "近日，中国地质大学(武汉)联合内蒙古自治区地质调查研究院，在内蒙古白云鄂博矿床主", "detail": "矿矿段的矿\n体中部，发现一种新稀土矿物，命名为“钕黄河矿”。钕黄河矿隶属于稀土碳酸盐矿物家族，其化学成分具有\n独特的钕元素富集特征。钕作为高性能永磁材料的核心成分，在新能源汽车、风力发电、电子信息等领域\n8\n(cid:3)\n需求旺盛。"}, {"title": "近日，中国科学院近代物理研究所科研人员与德国亥姆霍兹重离子研究中心、复旦大学等国", "detail": "内外合\n作者在原子核的奇特衰变研究领域取得新进展，首次在实验上观测到新核素铝-20，并发现其通过稀有的三\n质子发射模式进行衰变。铝-20位于质子滴线外，比自然界稳定存在的铝同位素少7个中子，是迄今实验上\n发现的最轻的铝同位素。"}, {"title": "近日，国务院国资委发布2025年1号公告，经国务院批准，组建中国雅江集团有限公司", "detail": "，由国务院\n国有资产监督管理委员会代表国务院履行出资人职责，列入国务院国有资产监督管理委员会履行出资人职\n责的企业名单。根据最新央企名录，中国雅江集团有限公司“序号”为22，位列中国长江三峡集团有限公司\n和国家能源投资集团有限责任公司之间。"}, {"title": "7月21日，中国互联网络信息中心（CNNIC）在京发布第56次《中国互联网络发展", "detail": "状况统计报告》。\n《报告》显示，截至2025年6月，我国网民规模达11.23亿人，互联网普及率达79.7%，越来越多的群体共\n享数字发展成果。"}, {"title": "第十五届全国见义勇为英雄模范表彰大会7月21日在京召开，隆重表彰60个见义勇为英", "detail": "雄模范个\n人和群体。陈文清强调，要大力弘扬见义勇为精神，坚持正确义利观，以英雄模范英勇无畏、惩恶扬善、\n扶危济困、匡扶正义、舍己为人、乐于奉献的崇高品格影响人、感染人、带动人，充分激发社会正气正义。"}, {"title": "国务院总理李强日前签署国务院令，公布《住房租赁条例》，自2025年9月15日起施", "detail": "行。《条例》\n共7章50条。"}, {"title": "水利部近日发布《中国节约用水报告2024》。", "detail": "报告显示，2024年全国用水总量较2023年增加21.5\n亿立方米，万元国内生产总值用水量、万元工业增加值用水量按可比价计算分别较2023年下降4.4%和5.3%；\n农田灌溉水有效利用系数提升至0.580。"}, {"title": "7月22日上午，人力资源社会保障部召开二季度新闻发布会，相关负责人介绍，2025", "detail": "年上半年，全\n国城镇新增就业695万人，完成全年目标任务的58%。6月份全国城镇调查失业率为5.0%，与去年同期持平。"}, {"title": "国务院总理李强日前签署国务院令，公布《农村公路条例》，自2025年9月15日起施", "detail": "行。《条例》\n规定农村公路发展应当贯彻党和国家路线方针政策、决策部署，与统筹新型城镇化和乡村全面振兴的有关\n要求相适应，坚持政府主导、统筹规划、因地制宜，坚持建设、管理、养护、运营并重，逐步完善全域覆\n盖、普惠共享、安全适用、便捷高效的农村交通基础设施网络。"}, {"title": "日前，国家移民管理局发布的数据显示，2025年上半年，全国口岸出入境外国人380", "detail": "5.3万人次，同\n比上升了30.2%。数据大幅提升的背后是全国各口岸持续打造的入境第一站的系列便利措施。"}, {"title": "美国国务院发言人塔米·布鲁斯7月22日发表声明，宣布美国退出联合国教科文组织。", "detail": "这将是美国\n第三次退出联合国教科文组织，也是特朗普执政时期的第二次。"}, {"title": "7月23日，国新办举行新闻发布会介绍海南自由贸易港建设有关情况。", "detail": "会上宣布，经党中央批准，\n海南自贸港封关定于2025年12月18日正式启动。全岛封关运作将实施以“一线”放开、“二线”管住、岛内自\n由为基本特征的自由化、便利化政策制度。"}, {"title": "7月23日至26日，2025国际低空经济博览会在上海举办，以“启航低空经济，赋能", "detail": "千行百业”为主题，\n参展商数量近300家，展示低空基础设施、制造与配套服务等。"}, {"title": "7月23日，“未来”号深远海绿色智能技术试验船历时六年的科研攻关和设计建造，顺利", "detail": "完成命名交\n付。“未来”号是国内首艘深远海绿色智能技术试验船，总长110.8米，满载排水量7000吨，续航力大于10000\n海里，将成为我国“陆—池—湖—海—船”试验研究体系中的核心装备，有力填补我国船舶与海洋装备实海验\n9\n(cid:3)\n证中试平台的空白，对解决国产装备实船海上测试与应用的“最后一公里”、推动船舶工业高质量发展具有重\n要意义。"}, {"title": "中共中央、国务院、中央军委决定，给蔡旭哲同志颁发“二级航天功勋奖章”，授予宋令东", "detail": "、王浩泽\n同志“英雄航天员”荣誉称号并颁发“三级航天功勋奖章”。2024年10月30日，神舟十九号载人飞船成功发射，\n航天员蔡旭哲、宋令东、王浩泽驾乘飞船顺利进驻天和核心舱，在轨驻留6个月，先后进行3次出舱活动，\n实施6次载荷货物气闸舱进出舱任务，完成90余项空间站建设升级维护维修任务，开展80余项空间科学实\n验与技术试验，于2025年4月30日安全返回。"}, {"title": "7月23日，国家能源局发布1-6月份全国电力工业统计数据。", "detail": "截至2025年6月底，全国累计发电装\n机容量36.5亿千瓦，同比增长18.7%。其中，太阳能发电装机容量11.0亿千瓦，同比增长54.2%；风电装机\n容量5.7亿千瓦，同比增长22.7%。"}, {"title": "2025（第二十四届）中国互联网大会于7月23日至25日在北京举行。", "detail": "本届大会以“数驱新质・智创\n未来”为主题，聚焦人工智能（AI）、5G-A/6G、低空经济等前沿技术领域，汇聚全球政产学研各界力量，\n共同探索AI驱动下的产业升级路径以及数字生态重构方案。"}, {"title": "7月24日，2025年世界互联网大会数字丝路发展论坛在福建泉州开幕。", "detail": "本次论坛主题为“数智海丝共\n迎未来——携手构建网络空间命运共同体”。来自全球49个国家和地区，及13个国际组织的600余名嘉宾\n参会。"}, {"title": "7月24日上午，国家主席习近平在北京人民大会堂会见来华举行第二十五次中国－欧盟领", "detail": "导人会晤\n的欧洲理事会主席科斯塔和欧盟委员会主席冯德莱恩。习近平指出，中欧建交50年来，交流合作成果丰硕，\n既成就彼此又惠及世界，其中的重要经验和启示就是相互尊重、求同存异、开放合作、互利共赢。这也是\n中欧关系未来发展应该坚持的重要原则和努力方向。\n习近平就中欧关系未来发展提出三点主张。一是坚持相互尊重，巩固伙伴关系定位。二是坚持开放合\n作，妥善处理分歧摩擦。三是践行多边主义，维护国际规则秩序。"}, {"title": "7月24日，在津巴布韦维多利亚瀑布城开幕的《湿地公约》第十五届缔约方大会上，中国", "detail": "9地获“国\n际湿地城市”认证。至此，中国“国际湿地城市”总数达22个，继续居全球第一。此次获得认证的9地分别为\n上海崇明、云南大理、福建福州、浙江杭州、江西九江、西藏拉萨、江苏苏州、浙江温州和湖南岳阳。"}, {"title": "7月25日上午，2025年国际粮食减损大会在山东济南开幕。", "detail": "大会以“科技创新赋能节粮减损全球携\n手共促粮食安全”为主题，会议设置主题论坛及三个分论坛，聚焦科技减损、机械化生产及青年行动，并发\n布《国际粮食减损大会济南倡议回顾》等成果文件。"}, {"title": "7月25日，第33届全国图书交易博览会（简称“书博会”）在重庆启幕。", "detail": "本届书博会主题为“书香中\n国·阅读之美”，举行时间为7月25日至28日。本届书博会线上线下参展图书总数超过100万种，主会场\n展区分为5个展馆，设有国际标准展位4500余个。"}, {"title": "日前，全球首艘8万吨级通海养殖工船“森海先锋”号在河北秦皇岛完成交付，这是全球首", "detail": "个获得中\n国船级社完全入级认证的通海型养殖工船，标志着我国在深远海智能化、规模化养殖装备领域实现突破。"}, {"title": "上海合作组织媒体智库峰会全体会议7月25日在河南郑州举行，主题为“弘扬‘上海精神", "detail": "’共建美好\n家园”。来自上合组织成员国、观察员国、对话伙伴的近200家媒体、智库、政府机构及国际和地区组织的\n400余位中外嘉宾齐聚一堂，共商媒体合作，共话区域发展。"}, {"title": "7月26日上午，以“智能时代同球共济”为主题的2025世界人工智能大会暨人工智能", "detail": "全球治理高级\n别会议在上海世博中心开幕，大会会期为7月26至28日。\n10\n(cid:3)"}, {"title": "国务院总理李强7月26日在上海出席2025世界人工智能大会暨人工智能全球治理高级", "detail": "别会议开幕\n式并致辞。李强围绕如何把握人工智能公共产品属性、推进人工智能发展和治理，提出三点建议。一是更\n加注重普及普惠，充分用好人工智能发展的已有成果。二是更加注重创新合作，力求更多突破性的人工智\n能科技硕果。三是更加注重共同治理，确保人工智能在造福人类上最终修成正果。"}, {"title": "7月26日，以“牵手世运点燃梦想”为主题的2025年第12届世界运动会火炬传递活", "detail": "动在四川成都、\n德阳、眉山三地举行。这场世运会历史上的首次火炬传递活动成为展示文化、友谊、团结的重要窗口。"}, {"title": "中国政府7月26日倡议成立世界人工智能合作组织，初步考虑总部设在上海。", "detail": "中方倡议成立世界\n人工智能合作组织旨在加强人工智能领域的国际合作。中方初步考虑该组织总部设在上海，希望利用中国\n特别是上海人工智能先发优势，凝聚国际共识，促进务实合作，让人工智能真正造福全人类。"}, {"title": "2025年7月27日18时03分，我国在太原卫星发射中心使用长征六号改运载火箭，", "detail": "成功将卫星互\n联网低轨05组卫星发射升空。卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "7月27日从国家发展改革委获悉，物流运行情况显示，2025年上半年，社会物流总费", "detail": "用与国内生产\n总值（GDP）的比率降至14%，较一季度和上年同期分别下降0.1个和0.2个百分点，降低全社会物流成本\n工作取得阶段性成效。"}, {"title": "7月27日17时22分，由德国神鹰航空运营的“法兰克福⇌曼谷⇌三亚”第五航权定期", "detail": "客运航线首航航\n班成功抵达三亚机场，这条航线是海南自贸港首条直通欧洲的第五航权定期客运航线。第五航权，即第三\n国运输权，是指一个国家的航空公司在经营某条国际航线的同时，获得在第三国经停并载运客货的权利。\n该航权是航空公司扩展国际航线网络和发展全球市场的重要途径之一。"}, {"title": "7月26日，2025中国—东盟教育交流周在贵州贵阳开幕，本届交流周以“智汇人文，", "detail": "教育共融，协\n同发展”为主题。开幕式上，发布了“贵匠工坊”贵州职教出海、教随产出国际化项目品牌，中国—东盟校企\n合作职教出海项目单位签订了协议。"}, {"title": "7月28日，国家育儿补贴制度实施方案公布，从2025年1月1日起，无论一孩、二孩", "detail": "、三孩，每\n年均可领取3600元补贴，直至年满3周岁。"}, {"title": "生态环境部7月28日发布2025年上半年全国空气和地表水环境质量。", "detail": "空气质量方面，全国339个\n地级及以上城市平均空气质量优良天数比例为83.8%，同比上升1个百分点；全国PM2.5平均浓度为32.1\n微克/立方米，同比下降2.4%。"}, {"title": "民政部和全国老龄办日前发布《2024年度国家老龄事业发展公报》，截至2024年末", "detail": "，全国60周岁\n及以上老年人口31031万人，占总人口的22.0%；全国65周岁及以上老年人口22023万人，占总人口的15.6%。\n全国65周岁及以上老年人口抚养比22.8%。2024年，全国人均预期寿命达79.0岁，比2023年提高了0.4岁，\n已位于世界中高收入国家前列。"}, {"title": "7月29日，世界青年和平大会在北京举行，本次大会以“一起为和平”为主题，采取“一", "detail": "场主会场+多\n场主题活动”的形式。"}, {"title": "7月29日，国家主席习近平向世界青年和平大会致信。", "detail": "习近平强调，和平的未来寄托在青年身上。\n希望各国青年朋友们以这次大会为契机，交流思想、增进了解、收获友谊，一起做和平理念的倡导者、和\n平发展的行动者，为推动构建人类命运共同体贡献智慧和力量。"}, {"title": "2025年7月29日12时11分，双曲线一号遥十运载火箭在我国酒泉卫星发射中心发", "detail": "射升空，将搭\n载的恩施硒都山泉号卫星顺利送入预定轨道，飞行试验任务获得圆满成功。"}, {"title": "财政部最新数据显示，2025上半年，全国财政收入11.56万亿元。", "detail": "其中，税收收入逐步回升，从4\n11\n(cid:3)\n月份起，连续(cid:1)3(cid:1)个月实现同比增长。全国财政支出(cid:1)14.13(cid:1)万亿元，同比增长"}, {"title": "7月23日，中共中央在中南海召开党外人士座谈会，就当前经济形势和下半年经济工作听", "detail": "取各民主\n党派中央、全国工商联负责人和无党派人士代表的意见建议。习近平强调，当前我国经济运行依然面临不3.4%。\n少风险挑战，要正确把握形势，增强忧患意识，坚持底线思维，用好发展机遇、潜力和优势，巩固拓展经\n济回升向好势头。下半年，要在宏观政策上持续发力、适时加力，重点做好全方位扩大内需、坚定不移深\n化改革扩大开放、推动科技创新和产业创新深度融合发展、持续防范化解重点领域风险、多措并举保障改\n善民生等工作。"}, {"title": "中国物流与采购联合会7月29日公布今年上半年物流运行数据。", "detail": "2025年上半年，全国社会物流总\n额，即物流运行中的实物商品价值总和为171.3万亿元，同比增长5.6%。上半年社会物流总额增速高于同期\nGDP增速0.3个百分点，反映出物流需求对经济发展的支撑作用依然较强。"}, {"title": "2025年7月30日15时49分，我国在海南商业航天发射场使用长征八号甲运载火箭", "detail": "，成功将卫星\n互联网低轨06组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "中共中央政治局7月30日召开会议，决定今年10月在北京召开中国共产党第二十届中央", "detail": "委员会第\n四次全体会议，主要议程是，中共中央政治局向中央委员会报告工作，研究关于制定国民经济和社会发展\n第十五个五年规划的建议。会议指出，“十五五”时期是基本实现社会主义现代化夯实基础、全面发力的关键\n时期，我国发展环境面临深刻复杂变化，战略机遇和风险挑战并存、不确定难预料因素增多，同时我国经\n济基础稳、优势多、韧性强、潜能大，长期向好的支撑条件和基本趋势没有变，中国特色社会主义制度优\n势、超大规模市场优势、完整产业体系优势、丰富人才资源优势更加彰显，要保持战略定力，增强必胜信\n心，积极识变应变求变，集中力量办好自己的事，在激烈国际竞争中赢得战略主动，推动事关中国式现代\n化全局的战略任务取得重大突破。\n会议指出，宏观政策要持续发力、适时加力。要落实落细更加积极的财政政策和适度宽松的货币政策，\n充分释放政策效应。用好各项结构性货币政策工具，加力支持科技创新、提振消费、小微企业、稳定外贸\n等。\n12\n(cid:3)"}]}, {"month": "2025年8月", "year": 2025, "items": [{"title": "第十届上海合作组织成员国农业部长会议7月30日在云南昆明召开。", "detail": "会议以“强化农业政策交流构\n建更加密切美好的上合农业合作大家庭”为主题，围绕农村发展、减贫合作、科技交流等展开研讨。"}, {"title": "2025年7月31日10时00分，我国在西昌卫星发射中心使用快舟一号甲运载火箭，", "detail": "成功将巴基斯坦\n遥感卫星01星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。巴基斯坦遥感卫星01星主要用\n于国土普查和防灾减灾领域。"}, {"title": "国务院总理李强7月31日主持召开国务院常务会议，学习贯彻习近平总书记关于上半年经", "detail": "济形势和\n做好下半年经济工作的重要讲话精神。会议强调，要深刻领会党中央关于经济形势的科学判断，进一步增\n强做好下半年经济工作的责任感使命感，正确把握形势，强化忧患意识，坚持底线思维，勇于担当、攻坚\n克难，巩固拓展经济回升向好势头。"}, {"title": "中央军委主席习近平近日签署命令，发布军事航天部队、网络空间部队、信息支援部队、联", "detail": "勤保障部\n队军旗旗面式样。\n八一军旗陆军军旗海军军旗\n空军军旗火箭军军旗军事航天部队军旗\n网络空间部队军旗信息支援部队军旗联勤保障部队军旗"}, {"title": "第六次世界议长大会7月29日至31日在日内瓦万国宫举行。", "detail": "全国人大常委会委员长赵乐际出席大会，\n并作了题为《坚持多边主义，共建美好家园》的发言。赵乐际在发言中说，当前，人类和平与发展事业面\n临严峻挑战，立法机构有责任为推动构建新型国际关系发挥积极作用。要做世界和平安宁的共同守护者；\n1\n(cid:3)\n做全球发展繁荣的共同促进者；做文明交流互鉴的共同倡导者；做国际公平正义的共同推动者。"}, {"title": "8月1日建军节，我国第4艘075型两栖攻击舰湖北舰首次公开亮相，舷号为“34”，", "detail": "另外三艘：“31”\n海南舰、“32”广西舰、“33”安徽舰。075型两栖攻击舰系我国自主研制的首型两栖攻击舰。"}, {"title": "8月1日出版的第15期《求是》杂志发表习近平2023年7月17日《在全国生态环境", "detail": "保护大会上的讲\n话》。文章强调，党的十八大以来，我们把生态文明建设作为关系中华民族永续发展的根本大计，开展了\n一系列开创性工作，决心之大、力度之大、成效之大前所未有，生态文明建设从理论到实践都发生了历史\n性、转折性、全局性变化，实现由重点整治到系统治理、由被动应对到主动作为、由全球环境治理参与者\n到引领者、由实践探索到科学理论指导的重大转变。\n文章指出，我国经济社会发展已进入加快绿色化、低碳化的高质量发展阶段，生态文明建设仍然处于\n压力叠加、负重前行的关键期。新征程继续推进生态文明建设需要处理好几个重大关系。一是高质量发展\n和高水平保护的关系。二是重点攻坚和协同治理的关系。三是自然恢复和人工修复的关系。四是外部约束\n和内生动力的关系。五是“双碳”承诺和自主行动的关系。\n文章指出，要以美丽中国建设全面推进人与自然和谐共生的现代化。第一，持续深入打好污染防治攻\n坚战。第二，加快推动发展方式绿色低碳转型。第三，着力提升生态系统多样性、稳定性、持续性。第四，\n积极稳妥推进碳达峰碳中和。第五，守牢美丽中国建设安全底线。"}, {"title": "8月1日，国家主席习近平同尼泊尔总统鲍德尔互致贺电，庆祝中尼两国建交70周年。", "detail": "习近平指出，\n中国和尼泊尔山水相连，友好交往源远流长。中尼建交70年来，无论国际和地区形势如何变化，两国始终\n相互尊重、平等相待、互利合作，树立了不同社会制度和大小国家间友好相处的典范。"}, {"title": "8月1日从中央网信办获悉，据国家IPv6发展监测平台数据显示，截至2025年6月", "detail": "，我国IPv6活跃\n用户数达8.34亿，占我国全部网民数的75.29%。全国IPv6网络流量占比达31.12%，其中移动网络IPv6流\n量占比为66.00%，固定网络IPv6流量占比为28.32%。"}, {"title": "从自然资源部获悉，2025年上半年，我国海洋经济发展态势稳中向好。", "detail": "经初步核算，上半年海洋生\n产总值5.1万亿元，同比增长5.8%。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "文化和旅游部最新数据显示，2025年上半年，国内居民出游人次32.85亿，同比增", "detail": "长20.6%；国内居\n民出游花费3.15万亿元，同比增长15.2%。"}, {"title": "8月1日，全国最大的沙漠油田——塔里木油田哈得—富满油田传来捷报：油气产量当量累", "detail": "计突破\n5000万吨，标志着在沙漠腹地高质量建成一座绿色低碳智能的现代化超深油田。"}, {"title": "8月1日，以“同心携手向新而行”为主题的2025京港澳青年科学家大会在北京经济技", "detail": "术开发区召开。\n大会汇聚京港澳三地青年科学家、企业家、投资机构，搭建多元交流平台，聚焦人工智能、生物医药、量\n子通信、未来航天、新能源等前沿领域，推动科技创新与产业创新深度融合，助力北京新质生产力发展。"}, {"title": "8月2日晚上，第十五届全国运动会和残特奥会火炬“绽放”在深圳亮相。", "detail": "颁奖礼服、颁奖音乐、残特\n奥会奖牌“同心暖”等集中发布。“绽放”的核心设计理念为“融”与“荣”，一方面是“交流融合”，体现粤港澳“三\n地一家”“同根同源”的岭南特色文化；另一方面是“共同繁荣”，彰显“一国两制”制度优势下，粤港澳团结协作\n的发展路径。"}, {"title": "8月3日上午，以“新质生产力：新智造新消费新生态”为主题的2025企业家太阳岛年", "detail": "会主论坛在\n黑龙江哈尔滨举行，来自政商学研企等领域的嘉宾共赴“冰城”，为经济社会高质量发展提供新思路、激荡新\n智慧、注入新动能。\n2\n(cid:3)"}, {"title": "8月2日，浙江大学脑机智能全国重点实验室发布最新成果，新一代神经拟态类脑计算机—", "detail": "—“悟空”\n问世。这是国际首台神经元规模超20亿的基于专用神经拟态芯片的类脑计算机，接近猕猴大脑规模，标志\n着我国在神经拟态类脑计算机领域已达到国际先进水平。"}, {"title": "8月3日，成都第12届世界运动会运动员村开村。", "detail": "作为各类客群赛时期间的“成都家园”，预计开村\n首日将迎来约500人入住。世运会期间，这里将为约7000名参赛者提供服务。"}, {"title": "2025年8月4日18时21分，我国在海南商业航天发射场使用长征十二号运载火箭，", "detail": "成功将卫星互\n联网低轨07组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "习近平近日就研究吸收网民对“十五五”规划编制工作意见建议作出重要指示强调，“十五", "detail": "五”规划编制\n工作网络征求意见活动参与度高、覆盖面广，是全过程人民民主的一次生动实践。广大人民群众积极建言\n献策，提出了许多有价值的意见建议，有关部门要认真研究吸纳。各级党委和政府要始终坚持以人民为中\n心，广泛深入地察民情、听民声、汇民智，凝聚起推进中国式现代化的强大合力，不断实现人民对美好生\n活的向往。"}, {"title": "8月5日，国家疾控局联合多部门发布《健康中国行动—健康环境促进行动实施方案（20", "detail": "25—2030\n年）》，方案提出，到2030年，达到《健康中国行动（2019—2030年）》提出的关于健康环境2个结果性\n指标和4个倡导性指标要求：实现居民饮用水水质达标情况持续改善，居民环境与健康素养水平达到25%\n及以上；倡导生活垃圾分类，倡导防治室内空气污染，倡导学校、医院等人员密集场所定期开展应急演练，\n倡导提高自身健康防护意识和能力。"}, {"title": "8月5日上午，国务院新闻办公室举行新闻发布会，介绍西藏自治区成立60周年经济社会", "detail": "发展成就。\n会上介绍，2024年，西藏全区生产总值达到2765亿元，按不变价格计算，是1965年的155倍，年均增长"}, {"title": "9%；地方财政收入达到277亿元，是1965年的1258倍，年均增长12.9%。", "detail": "在60年的发展历程中，西藏全\n区生产总值达到第一个千亿用了50年，而第二个千亿仅用了6年。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "国家能源局发布的全国电力工业统计数据显示：截至2025年6月底，全国累计发电装机", "detail": "容量36.5亿\n千瓦，同比增长18.7%。其中，太阳能发电装机容量11.0亿千瓦，同比增长54.2%；风电装机容量5.7亿千\n瓦，同比增长22.7%。"}, {"title": "日前，国务院办公厅印发《关于逐步推行免费学前教育的意见》，推进学前教育普及普惠安", "detail": "全优质\n发展。《意见》强调，坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届\n二中、三中全会精神，全面贯彻党的教育方针，聚焦人民群众所急所需所盼，按照强化普及普惠、稳妥有\n序推进、加大政府投入、经费合理分担的原则，逐步免除学前教育保育教育费，有效降低教育成本，提高\n基本公共教育服务水平，办好人民满意的教育。"}, {"title": "成都世运会中国体育代表团8月6日宣布，在8月7日举行的世运会开幕式上，中国代表团", "detail": "旗手将\n由技巧项目男子运动员史经纬和轮滑项目女子运动员郭丹担任。"}, {"title": "交通运输部、财政部、自然资源部近日发布关于印发《新一轮农村公路提升行动方案》的通", "detail": "知，总\n体要求中提到，到2027年，全国完成新改建农村公路30万公里，便捷高效、普惠公平的农村公路网络基本\n建成。"}, {"title": "日前，农业农村部、生态环境部联合发布《中国渔业生态环境状况公报（2024）》，《", "detail": "公报》显示，\n2024年，农业农村部组织全国渔业生态环境监测网络所属42个监测站，对159个、总面积1016万公顷的重\n要渔业水域环境状况进行常规监测。所有监测水域铅、镉和砷指标监测浓度均优于评价标准；海洋重要渔\n3\n(cid:3)\n业水域中化学需氧量指标的超标面积比例下降幅度为25%；内陆重要渔业水域中非离子氨、高锰酸盐指数\n指标的超标面积比例下降幅度分别为25%和32%。"}, {"title": "中共中央办公厅、国务院办公厅印发了《整治形式主义为基层减负若干规定》，《规定》明", "detail": "确，严\n控文件数量。地方和部门发文严格实行计划管理、总量管控和发文立项制度，严格控制临时性、配套类、\n分工类发文。提升文件质量。坚持“短实新”文风，除部署综合性工作外，地方和部门文件一般不超过5000\n字，部署专项工作或者具体任务的文件一般不超过4000字。"}, {"title": "8月6日，第十三届海峡青年荟主场活动海峡青年连心汇在福建福州举办。", "detail": "第十三届海峡青年荟以“传\n承中华文化,赓续血脉亲情”为主题,8月1日至7日集中举办海峡青年连心汇、两岸大学生领袖营、“走进政协·台\n湾青年说”等活动,全年将开展52项活动,预计邀请台青超3000人次。"}, {"title": "8月6日，2025未来科学大奖获奖名单揭晓。", "detail": "季强、徐星、周忠和获得“生命科学奖”，以表彰他们发\n现了鸟类起源于恐龙的化石证据；方忠、戴希、丁洪获得“物质科学奖”，以表彰他们在拓扑电子材料的计算\n预测以及实验实现方面做出的贡献；卢志远获得“数学与计算机科学奖”，以表彰他在非易失性半导体存储单\n元密度、器件集成度和数据可靠性领域的发明和引领的贡献。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "据中国载人航天工程办公室消息，北京时间2025年8月6日，揽月月面着陆器着陆起飞", "detail": "综合验证试\n验在位于河北省怀来县的地外天体着陆试验场圆满完成。此次试验是我国首次进行载人航天器地外天体着\n陆起飞试验，试验工况多、试验周期长、技术难度高，是我国载人月球探测工程研制工作的一个关键节点。\n揽月月面着陆器是我国面向首次载人月球探测任务全新研制的地外天体载人下降与上升飞行器，由登月舱\n和推进舱组成，主要用于环月轨道和月球表面间的航天员运输，可搭载2名航天员往返，并可携带月球车\n和科学载荷，是航天员登陆月球后的月面生活中心、能源中心及数据中心，能支持开展月面驻留和月面活\n动。"}, {"title": "国务院办公厅日前印发《自然灾害调查评估暂行办法》，《办法》明确，对性质严重、造成", "detail": "重大社\n会影响、公众质疑灾害原因或者伤亡人数、相关工程或者基础设施可能存在重大质量问题、相关人员在灾\n害防治和应急处置等工作中涉嫌失职渎职等的重大自然灾害，经国务院批准后，由国务院应急管理部门或\n者其他有关部门牵头提级调查评估。"}, {"title": "8月7日，2025年第12届世界运动会在四川省成都市开幕。", "detail": "这是继2023年成都大运会之后中国西部\n地区再次举办的又一项大型综合性国际赛事。世运会由国际世运会协会主办，是非奥项目规模最大、水平\n最高的国际综合性运动会，每4年举办一届。本届世运会共设34个大项60个分项256个小项，报名参赛运\n动员近4000人。中国体育代表团将有321名运动员参加28个大项50个分项152个小项的比赛。"}, {"title": "8月8日，2025世界机器人大会在北京开幕，本届大会以“让机器人更智慧，让具身体", "detail": "更智能”为主题，\n得到28家国际机构支持，来自全球近20个国家的1万余名选手参赛，共有200余家企业的1500余件产品\n参展，其中首发新品100余款。"}, {"title": "8月8日，位于新疆塔克拉玛干沙漠中心的最大光伏电站——塔油且末光伏电站累计发出绿", "detail": "电突破3\n亿度。塔油且末光伏电站位于新疆巴音郭楞蒙古自治州且末县境内，地处塔克拉玛干沙漠腹地，是我国在\n流动性沙漠中心建成的首个大型集中式光伏电站。项目于2023年5月31日并网发电，总占地面积超过3300\n亩，由近26万块光伏板组成，配套10兆瓦储能装置。"}, {"title": "2025年8月8日，是第17个全民健身日。", "detail": "自2009年全民健身日确立以来，“运动是良医”的理念已深\n入人心。目前，我国人均预期寿命已提高到79岁，居民主要健康指标居于中高收入国家前列。\n4\n(cid:3)"}, {"title": "8月8日，2025算力之都开发者大会在宁夏银川正式拉开帷幕。", "detail": "本次大会主题为“开源·开放融合·服\n务”，会议现场启动三万卡并网仪式及十万卡生态共建行动，正式点亮覆盖全区的“1+5+22”分布式智算节点\n及AI创新港建设工程，宣告信息技术与自主创新产教融合共同体宁夏分中心成立。"}, {"title": "2025年8月9日0时31分，我国太原卫星发射中心在山东日照附近海域使用捷龙三号", "detail": "运载火箭，成\n功将吉利星座04组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "国家能源局最新数据显示，截至2025年6月底，我国电动汽车充电设施总数已达到16", "detail": "10万个，其中\n公共充电设施409.6万个，私人充电设施1200.4万个。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "工业和信息化部、国家发展改革委、教育部等七部门日前联合印发《关于推动脑机接口产业", "detail": "创新发\n展的实施意见》。意见提出，到2027年，脑机接口关键技术取得突破，初步建立先进的技术体系、产业体\n系和标准体系。脑机接口产品在工业制造、医疗健康、生活消费等加快应用。产业规模不断壮大，打造2\n至3个产业发展集聚区，开拓一批新场景、新模式、新业态。"}, {"title": "8月9日夜间至8月10日凌晨，北京天安门地区举行了纪念中国人民抗日战争暨世界反法", "detail": "西斯战争\n胜利80周年大会第一次综合演练，约2.2万人参加演练及现场保障工作。"}, {"title": "第一届全国青少年田径运动会8月10日在辽宁省沈阳市开幕。", "detail": "本届赛事设置56个比赛项目，来自\n全国29个省（区、市）、新疆生产建设兵团和香港、澳门特别行政区的1100多名青少年运动员参赛。"}, {"title": "8月10日，位于浙江宁波的金七门核电1号机组核岛混凝土开始浇筑，核岛建设全面启动", "detail": "，“华龙一\n号”核电机组再添新成员。浙江金七门核电1号机组设计运行寿命60年，规划建设6台百万千瓦级核电机组。"}, {"title": "我国首个隧道与地下空间领域垂直大模型8月10日发布。", "detail": "目前，该模型已在高原铁路隧道、崇太长\n江隧道、深江铁路珠江口隧道等工程完成验证，实现隧道建造安全、优质、高效、绿色，推动行业数智化\n转型升级。"}, {"title": "自然资源部8月11日宣布我国首批设立的5个国家公园全部完成确权登记。", "detail": "大熊猫、东北虎豹、海\n南热带雨林、武夷山和三江源5个国家公园都有了“户口本”。国家公园是具有国家代表性的自然生态系统，\n保护范围大，生态过程完整，是我国自然生态系统中最重要、自然景观最独特、自然遗产最精华、生物多\n样性最富集的部分。"}, {"title": "近日，中共中央印发了修订后的《中国共产党党校（行政学院）工作条例》，《条例》指出", "detail": "，党校\n（行政学院）是党领导的培养党的领导干部的学校，是党委的重要部门，是教育培训干部和党员的主渠道，\n是党的思想理论建设的重要阵地，是党和国家的哲学社会科学研究机构和重要智库。"}, {"title": "近日，本源量子联合中国科学技术大学、合肥综合性国家科学中心人工智能研究院成功实现", "detail": "基于量\n子边编码技术的药物分子性质预测应用，并在中国第三代自主超导量子计算机“本源悟空”上完成真机验证，\n这项技术为分子性质预测及药物研发开辟全新路径。"}, {"title": "近日，财政部、教育部修订印发了《支持学前教育发展资金管理办法》。", "detail": "办法明确，支持学前教育\n发展资金管理遵循“统筹安排、突出重点，客观公正、规范透明，注重绩效、强化监督”的原则。"}, {"title": "8月11日，我国自主研制的直径最大泥水平衡盾构机“沧渊号”，在海太长江隧道A4标", "detail": "段项目左线正\n式始发，标志着项目正式进入掘进施工阶段。“沧渊号”盾构机开挖直径达16.66米，整机总长176米，总重\n量超过5650吨，是由中交天和自主研制的目前我国直径最大的泥水平衡盾构机，标志着我国在高端隧道施\n工装备领域取得新的突破。"}, {"title": "第四届中日韩农业部长会议8月11日在韩国仁川召开。", "detail": "中日韩农业部长会议时隔7年重启，上届会\n5\n(cid:3)\n议于2018年11月在北京召开。本届会议上，三国农业部长围绕粮食安全、动物疫病防控、可持续农业、乡\n村振兴、全球重要农业文化遗产合作、全球合作等六大核心议题进行了讨论，并就今后合作方向交换了意\n见。"}, {"title": "市场监管总局8月12日发布数据，2025年上半年，全国新设经营主体1327.8万", "detail": "户。其中，新设企业\n462万户，新设个体工商户862.9万户，新设农民专业合作社2.9万户，多种经营主体均呈现稳定增长势头。"}, {"title": "8月12日是世界大象日。", "detail": "目前，我国野生亚洲象种群数量稳定增长，云南省野生亚洲象种群数量已\n经增长到300多头，数量还在不断扩大。"}, {"title": "据水利部消息，8月12日8时，位于黄河最下游的国家水文站——利津水文站测得实时流", "detail": "量588立\n方米每秒。至此，通过实施黄河水量统一调度，黄河已实现自1999年以来连续26年不断流，持续为流域经\n济社会发展注入澎湃动力。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "为期5天的2025世界机器人大会8月12日在北京落下帷幕。", "detail": "从大会组委会获悉，此次大会在机器人\n产业促进、应用推广等方面作用显著，会期累计售出机器人及相关产品1.9万台，销售额超2亿元。"}, {"title": "8月13日14时43分，我国在文昌航天发射场使用长征五号乙运载火箭/远征二号上面", "detail": "级，成功将卫\n星互联网低轨08组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "财政部、中国人民银行、金融监管总局近日联合印发《个人消费贷款财政贴息政策实施方案", "detail": "》，明\n确对个人消费贷款进行财政贴息。方案明确，年贴息比例为1个百分点，且最高不超过贷款合同利率的50%，\n中央财政、省级财政分别承担贴息资金的90%、10%。"}, {"title": "8月13日9时50分，满载55个集装箱光伏组件的X9043次中欧班列（西安）从西", "detail": "安国际港站缓缓\n驶出，这标志着中欧班列（西安）自2013年开行首列以来，累计开行突破30000列。西安也成为全国首个\n中欧班列累计开行突破30000列的城市。"}, {"title": "国家发展改革委党组成员、国家数据局局长刘烈宏8月14日在国新办举行的“高质量完成", "detail": "‘十四五’规\n划”系列主题新闻发布会上介绍，“十四五”时期我国数字基础设施实现长足发展。我国数字基础设施在规模、\n技术等方面处于世界领先地位，截至2025年6月底，5G基站总数达到455万个，千兆宽带用户达2.26亿户，\n算力总规模位居全球第二，有力带动经济社会发展。"}, {"title": "2025澳中博览会8月14日在墨尔本开幕，100多家中澳企业和机构参展。", "detail": "本届博览会以“新质生产力\n造福澳中美好未来”为主题，旨在展示高科技和人工智能、绿色能源及新能源汽车等新兴产业机遇，同时推\n动农牧产品和红酒、旅游和留学、传统贸易和电商等中澳经贸合作热门行业合作。"}, {"title": "市场监管总局日前发布数据显示：截至目前，我国累计批准发布国家标准物质19007项", "detail": "，其中1—7\n月新批准发布国家标准物质549项，同比增长56%。"}, {"title": "我国8月15日在文昌航天发射场成功组织实施长征十号系列运载火箭系留点火试验。", "detail": "这是继圆满完\n成梦舟载人飞船零高度逃逸飞行试验和揽月着陆器着陆起飞综合验证试验之后，我国载人月球探测工程研\n制工作取得的又一项重要阶段性突破。长征十号系列运载火箭是我国面向载人月球探测任务研制的新一代\n载人运载火箭，包括长征十号和长征十号甲两种构型。"}, {"title": "8月15日，李强在京出席2025年全国生态日主场活动开幕式暨践行绿水青山就是金山", "detail": "银山理念座谈\n会，李强表示，绿水青山就是金山银山理念提出20年来，理论内涵和实践应用不断深化拓展，已成为全党\n全社会的共识和行动。这一重要理念，丰富了马克思主义人与自然关系的思想和生产力理论；这一重要理\n念，引领我国生态文明建设发生了历史性、转折性、全局性变化；这一重要理念，为全球可持续发展和生\n6\n(cid:3)\n时政/公基/笔试/面试/真题资料，请加微信：\nyumi9938态文明建设提供了中国思路、中国方案，作出了中国贡献。\n李强指出，我国经济社会发展已进入加快绿色化、低碳化的高质量发展阶段，必须坚定不移走生态优\n先、绿色发展之路。要以更大力度把绿水青山建得更美；要以绿色发展方式把金山银山做得更大；要以健\n全的制度为守护绿水青山提供可靠保障；要以坚定务实举措积极推动全球生态文明建设。"}, {"title": "8月15日，我国自主研发的世界首套生态清淤绿色智能一体化水上平台——“太湖之光”", "detail": "，在江苏无\n锡宜兴太湖水域全面投入使用。“太湖之光”由五艘作业船通过管道连接，包括新型智能环保清淤船“太湖浚\n清2号”、筛分调节船“太湖之光1号”、脱水减容模块船“太湖之光2号、3号”及世界首制的余水处理船，船\n体面积超过五千平方米。"}, {"title": "澜沧江－湄公河合作第十次外长会8月15日在云南安宁举行。", "detail": "会议发布《澜湄合作五年行动计划\n（2023－2027）2024年度落实进展报告》《2025年度澜湄合作专项基金支持项目清单》《澜湄合作机制下\n加强非传统安全合作的进展、挑战与路径》3份成果文件。"}, {"title": "2025年8月15日，全球首个以人形机器人为参赛主体的综合性体育盛会“2025世", "detail": "界人形机器人运动\n会”在位于北京的国家速滑馆“冰丝带”正式开赛。比赛涵盖了竞技赛、表演赛、场景赛等多个类别，吸引了\n来自全球16个国家的280支参赛队伍。"}, {"title": "8月15日，全球首台500千伏植物油变压器在广州500千伏增城变电站成功投运。", "detail": "这一突破标志着\n我国在高电压等级环保变压器领域实现从跟跑到领跑的跨越。作为目前全球运行电压等级最高的植物油变\n压器，它的诞生填补了500千伏天然酯绝缘油变压器实用化领域的国际空白。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "神舟二十号航天员乘组8月15日晚圆满完成第三次出舱活动。", "detail": "在出舱活动准备工作中，一个名叫“悟\n空AI”的大模型发挥了辅助支撑作用，为航天员在轨工作提供了智能化、专业化支持。“悟空AI”大模型结合\n载人航天飞行任务需求，采用预训练与指令微调技术，构建了专业领域大语言模型和以航天飞行知识规范\n为核心的RAG知识库。"}, {"title": "8月16日出版的第16期《求是》杂志将发表习近平的重要文章《促进民营经济健康发展", "detail": "、高质量发\n展》。文章指出，新时代新征程，我国社会生产力将不断跃升，人民生活水平将稳步提高，改革开放将进\n一步全面深化，特别是教育科技事业快速发展，人才队伍和劳动力资源数量庞大、素质优良，产业体系和\n基础设施体系配套完善，新产业、新业态、新模式不断涌现，14亿多人口的超大规模市场潜力巨大，给民\n营经济发展带来很多新的机遇、提供更大发展空间。\n文章指出，要扎扎实实落实促进民营经济发展的政策措施。凡是党中央定了的就要坚决执行，不能含\n含糊糊、拖拖拉拉，不能打折扣。一是坚决破除依法平等使用生产要素、公平参与市场竞争的各种障碍。\n二是着力解决拖欠民营企业账款问题。三是切实依法保护民营企业和民营企业家合法权益。四是认真落实\n各项纾困政策。五是进一步构建亲清政商关系。"}, {"title": "第一届全国青少年田径运动会8月15日在辽宁省沈阳市闭幕。", "detail": "来自全国29个省（区、市）、新疆\n生产建设兵团和香港、澳门特别行政区的1100多名青少年运动员在为期6天的比赛中连创佳绩。第二届全\n国青少年田径运动会将于明年在山东省日照市举行。"}, {"title": "8月16日，我国首个搭载气象雷达的海上升压站，在三峡江苏大丰800兆瓦海上风电项", "detail": "目现场完成\n安装，该设施将实现海洋气象精细化监测与海上风电场高效运行的协同应用，为海上清洁能源开发提供新\n模式。"}, {"title": "8月16日上午，2025中国自动化与人工智能教育大会暨全国青少年劳动技能与智能设", "detail": "计大赛全国决\n7\n(cid:3)\n赛在浙江省桐乡市启幕。本次大会以“数字化赋能教育发展，新质力夯实人才根基”为主题，旨在开辟智能教\n育新路径，打造教育新生态，为建设高质量教育体系汇聚磅礴智慧。"}, {"title": "8月16日晚感动中国2024年度人物揭晓，全国有9名个人、1个集体入选，他们是航", "detail": "天专家栾恩杰、\n“拼命书记”范振喜、“火箭少女”郑钦文、一人撑起一大家的“好人”曲亚波、最美志愿者吕明玉、保定学院西\n部支教群体、英勇船长沈华忠、人民的好干部李东、励志学子庞众望、百岁老兵李登月。特别致敬：刘老\n庄连。"}, {"title": "2025年8月17日16时55分，我国在西昌卫星发射中心使用长征四号丙运载火箭，", "detail": "成功将试验二十\n八号B星02星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。试验二十八号B星02星主要\n用于空间环境探测及相关技术试验。"}, {"title": "2025年8月17日22时15分，我国在太原卫星发射中心使用长征六号改运载火箭，", "detail": "成功将卫星互联\n网低轨09组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "8月17日，随着开挖直径17.5米的“山河号”盾构机刀盘破土而出，由济南城市建设", "detail": "集团投资建设、\n中铁十四局集团承建的济南市黄岗路黄河隧道盾构段掘进完成，这一世界最大直径水下盾构隧道顺利贯通。\n济南市黄岗路黄河隧道全长约5.75公里，其中盾构段长约3.3公里，设计时速60公里，是国内首条穿黄“单\n洞双层”盾构隧道。"}, {"title": "第12届世界运动会于8月17日晚在四川成都落下帷幕，这是我国大陆地区首次举办世界", "detail": "运动会。\n中国体育代表团在本届世运会上共夺得36金、17银、11铜共64枚奖牌，金牌、奖牌总数均创历史新高，\n首次位居金牌榜和奖牌榜第一，创我国参加世运会历史最好成绩。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "国务院总理李强8月18日主持召开国务院第九次全体会议，李强指出，今年以来，在以习", "detail": "近平同志\n为核心的党中央坚强领导下，各方面共同奋斗、克服困难，我国经济运行稳中有进，高质量发展取得新成\n效。要坚持全面、辩证地把握经济形势，既看到来之不易的发展成绩，看到我国经济所具有的强大韧性和\n活力，进一步坚定信心，又看到经济运行中面临的风险挑战，看到外部环境的严峻复杂，始终保持冷静清\n醒，积极应对各种不确定性，下大力气抓好确定的事，把党中央决策部署落实到位，用实实在在的行动争\n取最好的结果。"}, {"title": "8月15日至17日，第七届大运河文化旅游博览会在苏州国际博览中心举办，本届运博会", "detail": "延续“融合·创\n新·共享”主题，坚持专业化、市场化和品牌化理念，努力为运河沿线省市及全国文旅行业搭建一个文旅融\n合发展、文旅精品推广、美好生活共享的综合平台。"}, {"title": "在“中国医师节”到来之际，中央宣传部、国家卫生健康委向全社会公开发布2025年“", "detail": "最美医生”。玉\n凤、申小惠、尼玛拉毛、邢少云、刘志宏、农康、何建行、张军桥、周坚红和梁春荣等10名同志光荣入选。"}, {"title": "2025年8月19日15时33分，力箭一号遥十运载火箭在东风商业航天创新试验区发", "detail": "射升空，将搭载\n的中科卫星05星，多功能试验二号卫星01星、02星、03星（天拓六号卫星），天雁26星，ThumbSat-1\n卫星、ThumbSat-2卫星等7颗卫星顺利送入预定轨道，飞行试验任务获得圆满成功。"}, {"title": "国务院新闻办公室8月19日上午举行“高质量完成‘十四五’规划”系列主题新闻发布会。", "detail": "国家体育总局\n局长高志丹介绍“十四五”时期体育强国建设成就。截至2024年，全国体育场地面积达到42.3亿平方米，较“十\n三五”末增加11.31亿平方米，经常参加体育锻炼人数比例超过38.5%。同时，竞技体育彰显强国新形象。截\n至2024年底，“十四五”时期我国体育健儿共取得世界冠军519个，创世界记录68次。"}, {"title": "8月19日，第三届国家公园论坛在四川成都举办，主题为“守护自然瑰宝共绘和合之美”。", "detail": "论坛设1\n8\n(cid:3)\n个主论坛和3个分论坛，围绕国家公园立法、时空智能助力国家公园可持续发展以及国家公园政策创新与\n实践探索、全民共享与社区治理、旗舰物种保护与监测技术创新等主题，交流经验、共话发展。国家公园\n建设主题成果展同期举办，首批5个国家公园、相关科研机构、知名企业等以图片、实物产品、视频展示\n等形式，全面展现国家公园建设的重大成果、创新产品、显著成效等。"}, {"title": "8月20日，习近平听取西藏自治区党委和政府工作汇报，他强调，西藏要全面贯彻新时代", "detail": "党的治藏\n方略，坚持稳中求进工作总基调，完整准确全面贯彻新发展理念，扎实推动高质量发展，持续深入抓好稳\n定、发展、生态、强边四件大事，努力建设团结富裕文明和谐美丽的社会主义现代化新西藏。\n习近平强调，治藏稳藏兴藏，首先是要保持西藏的政治安定、社会稳定、民族团结、宗教和顺。要进\n一步铸牢中华民族共同体意识、推进中华民族共同体建设，加强党史、新中国史、改革开放史、社会主义\n发展史、中华民族发展史宣传教育，广泛宣传西藏自治区60年来的辉煌成就，讲好新时代西藏故事，引导\n各族干部群众不断增进“五个认同”。"}, {"title": "8月20日，我国首个获得核准的沙戈荒新能源外送工程——宁夏至湖南正负800千伏特", "detail": "高压直流工\n程投产送电，每年可从宁夏向湖南输送电量超360亿千瓦时，可满足超1000万户家庭一年的用电量。"}, {"title": "8月20日从交通运输部了解到，“十四五”前四年，全国农村公路新改建71.6万公里", "detail": "，乡镇通三级及\n以上公路比例达89.5%，较大人口规模自然村（组）通硬化路比例达94.6%，提前完成了“十四五”规划主要\n指标。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "8月20日，第九届未来网络发展大会在江苏南京开幕。", "detail": "本届大会以“网络全球决胜未来”为主题，立\n足全球视野打造高端对话交流平台，加强网络通信领域的技术交流与产业合作。"}, {"title": "8月20日，我国内河首艘纯电动清漂转运船——“三峡护坝1号”在湖北省秭归县成功试", "detail": "航并交付，\n进一步推动三峡库区船舶电动化、绿色化转型。“三峡护坝1号”船总长82米、型宽13.76米、设计最大吃水"}, {"title": "25米，采用双机双桨的推进方式，续航里程可达150公里，每年可替代燃油253.4", "detail": "吨，减少二氧化碳排放\n842.4吨。"}, {"title": "8月21日上午，西藏各族各界干部群众约2万人欢聚拉萨市布达拉宫广场，热烈庆祝西藏", "detail": "自治区成\n立60周年。王沪宁向西藏自治区赠送习近平题词的“共建中华民族共同体书写美丽西藏新篇章”贺匾。"}, {"title": "8月21日从中国石化获悉，江汉油田红星页岩气田在湖北和重庆两省探明1650.25", "detail": "亿立方米页岩气储\n量，标志着我国首个二叠系大型页岩气田正式诞生，对保障国家能源安全具有积极意义。"}, {"title": "日前，我国科学家通过对“嫦娥六号”月壤样品的高精度年代学研究，首次精确测定月球阿", "detail": "波罗（Apollo）\n盆地形成于41.6亿年前。据研究人员介绍，月球形成初期曾经历剧烈的小天体撞击事件，其表面广泛分布\n的直径超过300公里的巨型撞击盆地是最直观的地质记录。这些撞击盆地集中形成的时期被学界称为月球“后\n期重轰炸期”。"}, {"title": "据国家统计局网站8月22日消息，根据早稻抽样调查结果推算，国家统计局公布2025", "detail": "年全国早稻\n播种面积、单位面积产量、总产量。其中，全国早稻播种面积4742.9千公顷（7114.3万亩），比2024年减\n少12.0千公顷（17.9万亩），下降0.3%；全国早稻单位面积产量6011.9公斤/公顷（400.8公斤/亩），比2024\n年增加86.5公斤/公顷（5.8公斤/亩），增长1.5%；全国早稻总产量2851.3万吨（570.3亿斤），比2024年\n增加33.9万吨（6.8亿斤），增长1.2%。"}, {"title": "国务院总理李强8月22日主持召开国务院常务会议，会议指出，大规模设备更新和消费品", "detail": "以旧换新\n政策，在稳投资、扩消费、促转型、惠民生等方面取得明显成效。\n9\n(cid:3)"}, {"title": "近日，中央宣传部、中国国家铁路集团有限公司向全社会公开发布“最美铁路人”。", "detail": "丁巧仁、王婷婷、\n孔祥配、车菲菲、李元、王超、陈永红、马万里、王中美和高明伟等10名同志光荣入选。"}, {"title": "8月21日，在建世界第一高桥——贵州花江峡谷大桥正式启动荷载试验。", "detail": "2022年开工建设的花江峡\n谷大桥，跨越被誉为“地球裂缝”的花江大峡谷，是贵州省六枝至安龙高速公路的控制性工程。大桥为钢桁梁\n悬索桥，全长2890米，其中主桥跨径1420米，桥面至水面高度625米。"}, {"title": "8月22日，国务院新闻办公室举行“高质量完成‘十四五’规划”系列主题新闻发布会。", "detail": "国家市场监督管\n理总局介绍了我国“十四五”时期市场监管高质量发展成就。“十四五”以来，我国营商环境持续优化，充分激\n发了全社会的创业活力，我国企业净增1999.9万户，个体工商户净增3394.6万户。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "8月23日，以“算网筑基智引未来”为主题的2025中国算力大会在山西大同开幕。", "detail": "开幕式上，中国\n算力平台正式完成山西、辽宁、上海、江苏、浙江、山东、河南、青海、宁夏、新疆10个省区市分平台接\n入工作，实现“平台、主体、资源、生态、场景”全面贯通。"}, {"title": "中国人民银行、工业和信息化部等7部门近日联合印发《关于金融支持新型工业化的指导意", "detail": "见》，\n《意见》提出，到2027年，支持制造业高端化智能化绿色化发展的金融体系基本成熟，服务适配性有效增\n强。"}, {"title": "8月23日清晨，在南海飘着小雨的蓝色晨曦中，我国自主研制的6000米级深海无人遥", "detail": "控潜水器（ROV）\n“海琴”号，经过8个小时作业，从4140米深海凯旋，成功进行海试，我国深海研究又多了一个“科考利器”。"}, {"title": "第六届中国（甘肃）中医药产业博览会8月24日在甘肃省定西市陇西县开幕。", "detail": "本届药博会以“传承\n创新、开放共享，推动中医药高质量发展”为主题，展出道地中药材、精制饮片、中药材种植加工机械、中\n医AI前沿科技等全产业链产品。"}, {"title": "8月24日，全球首个超阶零碳大楼在山东青岛正式启用。", "detail": "说它是“超阶”，是因为除了光伏发电外，\n这个大楼还通过梯次储能电池以及新能源汽车放电，实现100%绿能替代。该大楼的正式启用标志着我国在\n零碳建筑方面取得新进展。"}, {"title": "2025年8月25日是全国第九个残疾预防日。", "detail": "今年残疾预防日宣传教育活动主题为“预防伤害致残，\n共创健康生活”。"}, {"title": "8月22日至24日，2025中国算力大会在山西大同举行。", "detail": "会上发布了“1+4”个算力行业发展报告，即\n《2025综合算力指数》和《2025算力发展报告》《2025存力发展报告》《2025运力发展报告》《2025智算\n服务发展报告》。报告显示，河北省综合算力指数连续2年排名全国第一。"}, {"title": "海关总署署长孙梅君8月25日在国新办举行的“高质量完成‘十四五’规划”系列主题新", "detail": "闻发布会上介\n绍，“十四五”以来，海关对外签署合作文件519份。2024年，我国与共建“一带一路”国家进出口22万亿元，\n占我国进出口比重超过一半，与东盟、拉美、非洲、中亚等新兴市场进出口年均增长10%以上。我国已成\n为全球157个国家和地区前三大贸易伙伴。国际合作共赢新优势更加凸显。"}, {"title": "8月25日，中共中央办公厅、国务院办公厅《关于推进绿色低碳转型加强全国碳市场建设", "detail": "的意见》\n对外公布。意见提出，到2027年，全国碳排放权交易市场基本覆盖工业领域主要排放行业，全国温室气体\n自愿减排交易市场实现重点领域全覆盖。到2030年，基本建成以配额总量控制为基础、免费和有偿分配相\n结合的全国碳排放权交易市场，建成诚信透明、方法统一、参与广泛、与国际接轨的全国温室气体自愿减\n排交易市场，形成减排效果明显、规则体系健全、价格水平合理的碳定价机制。"}, {"title": "市场监管总局（国家标准委）近日批准发布《适老家具设计指南》国家标准，将于2026", "detail": "年2月1\n10\n(cid:3)\n日正式实施。这一标准立足老年人的实际需求与生理心理特点，从适老家具的外观材料、智能化、功能配\n置等方面提出细化设计要求，旨在提升家具产品与老年人需求的适配度。"}, {"title": "2025年8月26日3时8分，我国在海南商业航天发射场使用长征八号甲运载火箭，成", "detail": "功将卫星互\n联网低轨10组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。此次发射所使用的长征八\n号甲火箭是我国针对中低轨道巨型星座组网发射需求而研制的新一代中型液体运载火箭。自今年2月首飞\n以来，这是它今年执行的第三发任务，表明长征八号甲火箭已经具备执行多任务并行的高密度发射能力。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "国务院新闻办公室于8月26日举行“高质量完成‘十四五’规划”系列主题新闻发布会，", "detail": "介绍“十四五”\n时期能源高质量发展成就。发布会上介绍，我国构建起全球最大、发展最快的可再生能源体系，可再生能\n源发电装机占比由40%提升至60%左右，风电光伏每年新增装机先后突破1亿、2亿、3亿千瓦关口，实现\n台阶式跃升发展，发展速度和力度前所未有。"}, {"title": "8月26日，江门中微子实验（JUNO）正式运行取数。", "detail": "经过十余年的准备和建设，江门中微子实验\n成为国际上首个运行的超大规模和超高精度中微子专用大科学装置。"}, {"title": "国务院日前印发《关于深入实施“人工智能+”行动的意见》，《意见》坚持以习近平新时", "detail": "代中国特\n色社会主义思想为指导，完整准确全面贯彻新发展理念，坚持以人民为中心的发展思想，充分发挥我国数\n据资源丰富、产业体系完备、应用场景广阔等优势，强化前瞻谋划、系统布局、分业施策、开放共享、安\n全可控，以科技、产业、消费、民生、治理、全球合作等领域为重点，深入实施“人工智能+”行动，涌现一\n批新基础设施、新技术体系、新产业生态、新就业岗位等，加快培育发展新质生产力，使全体人民共享人\n工智能发展成果，更好服务中国式现代化建设。"}, {"title": "8月26日，《厦门经济特区个人破产保护条例》经厦门市十六届人大常委会第三十一次会", "detail": "议三审表\n决通过，将于2025年11月1日起正式施行。这意味着，继深圳之后，厦门成为国内第二个探索建立个人破\n产制度的城市。"}, {"title": "《2024-2025年中国数字出版产业年度报告》8月27日在河南郑州发布。", "detail": "报告显示，2024年我国数\n字出版产业收入持续增长，整体收入规模全年达到17485.36亿元再创新高，比上年增加8.07%。"}, {"title": "8月27日，第十五届中国-东北亚博览会在吉林长春开幕，本届东北亚博览会以“携手东", "detail": "北亚开放\n赢未来”为主题，吸引全球40余个国家和地区的万余名客商参展参会。"}, {"title": "国家统计局统计科学研究所基于《新产业新业态新商业模式统计监测制度》，采用定基指数", "detail": "方法测\n算了2024年经济发展新动能情况指数。结果显示，2024年我国经济发展新动能指数（以2022年为100）为"}, {"title": "0，比上年增长14.2%。", "detail": "2024年，各项分类指数与上年相比均有提升，其中，网络经济和创新驱动对总\n指数增长的贡献较大。"}, {"title": "8月27日是首个世界湖泊日。", "detail": "从水利部了解到，通过充分应用高分辨率卫星遥感、人工智能、北斗\n定位、高点视频等技术，我国基本实现对14万条河流、3000多个湖泊、3000多个采砂重点河段、3万个岸\n线功能区、300万条河湖基础数据的动态管理，全国河道砂石采运实现“一码通用、一码溯源”，违建等重点\n地物AI识别精度超过85%。截至目前，我国大江大河大湖岸线保护利用规划全部印发实施，划定岸线保护\n区、保留区3.31万公里，占规划岸线总长的近70%。"}, {"title": "8月28日，2025中国国际大数据产业博览会在贵州省贵阳市隆重开幕。", "detail": "本届数博会以“数聚产业动\n能智启发展新篇”为主题，展现数据要素与人工智能技术融合创新的最新成果，将推动数据资源的高效汇聚\n和开发利用，有力促进数字经济国际合作和高质量发展。\n11\n(cid:3)"}, {"title": "8月28日，第十五届中国国际数字出版博览会在河南郑州召开。", "detail": "作为我国唯一以促进数字出版产业\n发展为主题举办的全国性、国际化博览会，本届数博会以“数实相融智赢未来”为主题，将举行主题论坛、\n洽谈签约、新品发布、项目路演等活动。来自国内外的出版企业负责人、专家学者齐聚一堂，深入交流合\n作，共享数字发展新机遇，共创数字出版新未来。"}, {"title": "工业和信息化部近日印发《关于优化业务准入促进卫星通信产业发展的指导意见》，提出到", "detail": "2030\n年，卫星通信管理制度及政策法规进一步完善，产业发展环境持续优化，各类经营主体创新活力充分迸发，\n基础设施、产业供给、技术标准、国际合作等综合发展水平显著提升，手机直连卫星等新模式新业态规模\n应用，发展卫星通信用户超千万，推动卫星通信充分融入新发展格局，有力服务经济社会高质量发展。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "8月28日上午，第七届中国—阿拉伯国家博览会在宁夏银川开幕。", "detail": "本届博览会以“创新、绿色、繁\n荣”为主题，聚焦中阿经贸务实合作，举办开幕式暨“一带一路”贸易投资促进活动，主宾国(阿拉伯联合酋长\n国)和主题省(新疆维吾尔自治区)2项机制性活动；设置共建“一带一路”国家、区域经济合作、中央企业、清\n洁能源、数字经济、特色商品6大展区；组织开展中阿工商界经贸交流、技术转移与创新合作、现代农业、\n水资源、卫生健康、中阿旅行商、气象高质量发展、标准化及知识产权等8个板块40余项经贸交流活动。"}, {"title": "中共中央政治局8月29日召开会议，审议《中国共产党思想政治工作条例》，研究《中华", "detail": "人民共\n和国民族团结进步促进法（草案）》。会议强调，要充分发挥思想政治工作的引领作用，坚持把用习近平\n新时代中国特色社会主义思想凝心铸魂放在首位，以理想信念教育为核心，紧密结合实际加强学习宣传教\n育，更好统一思想、凝聚共识、坚定信心、鼓舞斗志。"}, {"title": "习近平近日作出重要指示强调，党的作风就是党的形象，关系人心向背，关系党的生死存亡。", "detail": "习近\n平指出，这次深入贯彻中央八项规定精神学习教育，坚持学查改一体推进，坚持从上到下一贯到底，坚持\n严的基调不动摇，坚持务实精准组织实施，工作开展扎实，取得明显成效。"}, {"title": "中央党的建设工作领导小组8月29日召开会议，传达习近平重要指示，总结深入贯彻中央", "detail": "八项规\n定精神学习教育，研究部署巩固拓展学习教育成果、锲而不舍落实中央八项规定精神、推进作风建设常态\n化长效化工作。会议强调，要深入学习贯彻习近平总书记重要讲话和重要指示精神，以更高政治站位深化\n对作风建设的认识，牢固树立经常抓、深入抓、持久抓的思想观念。要以多种方式强化作风教育，引导党\n员干部加强理论武装，筑牢思想堤坝，自觉养成严格遵守中央八项规定及其实施细则精神的好习惯。"}, {"title": "国务院总理李强8月29日主持召开国务院常务会议，研究在全国部分地区实施要素市场化", "detail": "配置综\n合改革试点工作，部署开展县域普通高中振兴行动，审议通过《医疗卫生强基工程实施方案》。会议指出，\n深化要素市场化改革是构建高水平社会主义市场经济体制的重要举措，是推进全国统一大市场建设的重要\n内容。要持续用力推进改革，发挥市场在资源配置中的决定性作用，促进要素价格市场决定、流动自主有\n序、配置高效公平。"}, {"title": "8月29日，《新型能源体系发展研究蓝皮书》《能源科技创新蓝皮书》《中国能源发展报", "detail": "告2025》\n等6本智库报告在京发布。报告显示，目前我国电能占终端能源消费比重已达30%，显著高于世界平均水\n平。预计到2035年，这一比例将提升至40%以上。"}, {"title": "8月30日，第七届中国国际新材料产业博览会（简称新博会）在黑龙江哈尔滨开幕。", "detail": "本届新博会会\n期3天，主题为“数智驱动、向新笃行”，旨在聚焦推动人工智能与新材料产业深度融合，着力打造创新展示、\n产业协作、技术交流、营销服务国际化平台，吸引来自全球10多个国家和地区的1000多家企业和机构参展\n参会，共享“数智驱动”新机遇、共绘“向新笃行”新图景、共话“合作共赢”新未来。\n12\n(cid:3)"}, {"title": "8月30日，我国拥有完全自主知识产权，全球最大26兆瓦级海上风力发电机组在山东东", "detail": "营完成吊\n装。600吨级机舱在百米高空实现了毫米级精准对接。此次吊装的26兆瓦级海上风电机组由超过3万个零\n部件构成，轮毂中心高度相当于50多层居民楼高，其风轮扫风面积达7.7万平方米，是目前全球单机容量\n最大、叶轮直径最长的海上风电机组，并且实现全国产化设计制造。"}, {"title": "8月30日，从中国海油获悉，我国海上稠油热采累计产量已超500万吨，成为全球首个", "detail": "实现海上稠\n油规模化热采开发的国家。\n13\n(cid:3)"}]}, {"month": "2025年9月", "year": 2025, "items": [{"title": "8月30日，第十届中国国际纳米科学技术会议在北京举行。", "detail": "自2000年至2025年，全球授权纳米专利\n总数超过107.8万件，其中中国专利达46.4万件，占比高达43%，稳居世界第一。中国科学院以2.34万件专\n利位列全球专利权人榜首。预计至2025年底，全球纳米市场规模将攀升至1.5万亿美元，2018年至2025年\n复合增长率超过17%。"}, {"title": "近日，《中共中央国务院关于推动城市高质量发展的意见》对外公布。", "detail": "意见提出，到2030年，现代\n化人民城市建设取得重要进展，适应城市高质量发展的政策制度不断完善，新旧动能加快转换，人居品质\n明显提升，绿色转型深入推进，安全基础有力夯实，文化魅力充分彰显，治理水平大幅提高；到2035年，\n现代化人民城市基本建成。"}, {"title": "近日，从水利部获悉：“十四五”以来，我国人为新增水土流失得到有效管控，重点区域治", "detail": "理加快推进，\n水土保持工作取得明显成效，到2024年底，新增水土流失治理面积28.17万平方公里，水土保持率提高到\n72.83%。"}, {"title": "中央教育工作领导小组近日印发《高等教育学科专业设置调整优化行动方案（2025—2", "detail": "027年）》，方\n案明确，健全供需对接机制，建设国家人才供需对接大数据平台。平台整合共享各部门和人力资源服务机\n构的数据资源，重点构建动态供需大数据查询分析、支撑毕业生就业创业、服务人才培养质量评价、提供\n学科专业诊断预警、开展结构布局诊断分析、探索重点产业人才需求预测等6个功能版块。"}, {"title": "9月1日出版的第17期《求是》杂志发表习近平的重要文章《弘扬伟大抗战精神，向着中", "detail": "华民族伟大\n复兴的光辉彼岸奋勇前进》。文章强调，中国人民抗日战争是近代以来中国人民反抗外敌入侵持续时间最\n长、规模最大、牺牲最多的民族解放斗争，也是第一次取得完全胜利的民族解放斗争。中国人民抗日战争\n的伟大胜利，彻底粉碎了日本军国主义殖民奴役中国的图谋，有力捍卫了国家主权和领土完整，彻底洗刷\n了近代以来抗击外来侵略屡战屡败的民族耻辱。中国人民抗日战争的伟大胜利，重新确立了中国在世界上\n的大国地位，中国人民赢得了世界爱好和平人民的尊敬，中华民族赢得了崇高的民族声誉。这个伟大胜利，\n是中华民族从近代以来陷入深重危机走向伟大复兴的历史转折点、也是世界反法西斯战争胜利的重要组成\n部分，是中国人民的胜利、也是世界人民的胜利。\n文章强调，在中国人民抗日战争的壮阔进程中，形成了伟大的抗战精神，中国人民向世界展示了天下\n兴亡、匹夫有责的爱国情怀，视死如归、宁死不屈的民族气节，不畏强暴、血战到底的英雄气概，百折不\n挠、坚忍不拔的必胜信念。伟大的抗战精神，是中国人民弥足珍贵的精神财富，永远是激励中国人民克服\n一切艰难险阻、为实现中华民族伟大复兴而奋斗的强大精神动力。"}, {"title": "9月1日上午，上海合作组织成员国元首理事会第二十五次会议在天津梅江会展中心举行。", "detail": "中国国家\n主席习近平主持会议并发表题为《牢记初心使命开创美好未来》的重要讲话。习近平指出，从黄浦江畔到\n海河之滨，上海合作组织走过不平凡发展历程。上海合作组织成立24年来，成员国秉持互信、互利、平等、\n协商、尊重多样文明、谋求共同发展的“上海精神”，共享机遇、共谋发展，取得一系列开创性成果、历史性\n成就，树立了新型国际关系的典范。上海合作组织率先建立边境地区军事领域信任机制，最早采取打击“三\n股势力”多边行动，维护了地区和平安宁；率先启动共建“一带一路”合作，使地区发展繁荣动力更加充足，\n立体互联互通网络更加完善；率先缔结长期睦邻友好合作条约，宣告世代友好、永不为敌，促进了各成员\n国人民相亲、民心相通；率先提出共商共建共享的全球治理观，践行真正的多边主义，为促进世界和平与\n发展发挥了积极作用。"}, {"title": "9月1日下午，“上海合作组织+”会议在天津梅江会展中心举行。", "detail": "国家主席习近平主持会议并发表题为\n1\n(cid:3)\n《凝聚上合力量完善全球治理》的重要讲话。习近平指出，今年是世界反法西斯战争胜利和联合国成立\n80周年，是铭记历史、共创未来的重要时刻。中方愿同各国一道，推动构建更加公正合理的全球治理体系，\n携手迈向人类命运共同体。为此，习近平提出全球治理倡议：第一，奉行主权平等。第二，遵守国际法治。\n第三，践行多边主义。第四，倡导以人为本。第五，注重行动导向。\n习近平强调，上海合作组织在成立宣言和组织宪章中开宗明义指出，要推动国际政治经济秩序朝着更\n加民主、公正、合理的方向发展。面对加速演进的世界百年未有之大变局，上海合作组织要发挥引领作用，\n为维护世界和平稳定贡献“上合力量”，为推动全球开放合作展现“上合担当”，为弘扬全人类共同价值作出“上\n合示范”，为捍卫国际公平正义采取“上合行动”，当好践行全球治理倡议的表率。"}, {"title": "以“科技改变生活创新赢得未来”为主题的首个全国科普月活动9月1日全面启动，各类活", "detail": "动将持续1\n个月，打造全领域行动、全地域覆盖、全民参与共享的“科普盛宴”。"}, {"title": "国家药监局9月1日在京启动2025年“全国药品安全宣传周”活动。", "detail": "本次宣传周的主题为“药品安全监\n管为民”。各级药监部门将组织丰富多彩的宣传活动，进一步增强全民药品安全意识。"}, {"title": "9月2日上午，国家主席习近平同俄罗斯总统普京、蒙古国总统呼日勒苏赫在北京人民大会", "detail": "堂举行中\n俄蒙三国元首第七次会晤。习近平指出，近年来，中俄蒙三方合作稳步发展，取得实实在在的成果。三方\n合作中期路线图顺利实施，三国贸易额节节攀升，经贸、科技、生态保护、人文合作不断深化。"}, {"title": "日前从国家市场监督管理总局获悉，目前我国已部署质量攻关标志性项目289项，实施质", "detail": "量强链项\n目1724个，组建质量技术创新联合体1331个，超过4200家链主企业、25万家链员企业、4800家赋能机构\n参与。质量强链工作是加快发展新质生产力的必然要求，是畅通国内市场大循环的创新举措，是满足人民\n群众高品质生活的重要路径。"}, {"title": "自然资源部、农业农村部制定的《永久基本农田保护红线管理办法》将自2025年10月", "detail": "1日起施行。\n永久基本农田保护红线在坚持整体稳定，确保国土空间规划确定的永久基本农田保护任务不突破的前提下，\n可以对布局进行正向优化。依照本办法规定确需对永久基本农田布局进行正向优化调整的，应当按照“数量\n不减、质量不降、布局优化、生态改善”的原则优化调整并落实补划，逐步提高永久基本农田中优质耕地的\n比例。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "9月2日，中国-上海合作组织绿色产业合作平台、数字经济合作平台、职业技术教育合作", "detail": "中心在天\n津揭牌成立，开启这座城市国际合作新篇章。"}, {"title": "9月3日上午，纪念中国人民抗日战争暨世界反法西斯战争胜利80周年大会在北京天安门", "detail": "广场隆重\n举行，以盛大阅兵仪式，同世界人民一道纪念这个伟大的日子，共同开创更加光明的未来。习近平发表重\n要讲话并检阅受阅部队。习近平指出，中国人民抗日战争是艰苦卓绝的伟大战争。历史警示我们，人类命\n运休戚与共，各个国家、各个民族只有平等相待、和睦相处、守望相助，才能维护共同安全，消弭战争根\n源，不让历史悲剧重演。\n习近平强调，中华民族是不畏强暴、自立自强的伟大民族。当年，面对正义与邪恶、光明与黑暗、进\n步与反动的生死较量，中国人民同仇敌忾、奋起反抗，为国家生存而战，为民族复兴而战，为人类正义而\n战。今天，人类又面临和平还是战争、对话还是对抗、共赢还是零和的抉择。中国人民坚定站在历史正确\n一边、站在人类文明进步一边，坚持走和平发展道路，与各国人民携手构建人类命运共同体。"}, {"title": "9月3日，纪念中国人民抗日战争暨世界反法西斯战争胜利80周年招待会在北京人民大会", "detail": "堂隆重举\n行。习近平出席招待会并发表重要讲话强调，正义的信念不可动摇，和平的期盼不可阻遏，人民的力量不\n2\n(cid:3)\n可战胜。任何时候，我们都要弘扬全人类共同价值，坚定捍卫国际公平正义，让世界正气充盈、乾坤朗朗；\n都要坚持走和平发展道路，坚定守护世界和平安宁，携手构建人类命运共同体；都要以人民之心为心、以\n天下之利为利，为增进人民福祉而不懈努力。"}, {"title": "截至今年6月底，我国在用算力中心机架总规模达1085万标准机架，智能算力规模达7", "detail": "88百亿亿次/\n秒（EFLOPS）；存力规模超过1680艾字节（EB），相比2023年增长约40%；已发布1509个大模型，在\n全球位居前列。"}, {"title": "9月4日，中国—上海合作组织科技创新合作中心在山东青岛挂牌成立。", "detail": "10个面向上合组织国家的\n重点国际合作项目同步启动，涉及生物医药、高端装备、现代高效农业等多个领域。中国—上海合作组织\n科技创新合作中心坚持“立足山东、辐射全国、面向上合”理念，将有力促进区域协同创新，构建开放包容、\n互利共赢的国际创新合作生态，为各成员国经济社会发展注入新的动力。"}, {"title": "国家能源局近日发布的《中国新型储能发展报告（2025）》显示，截至2024年底，", "detail": "全国已建成投运\n新型储能7376万千瓦/1.68亿千瓦时，装机规模占全球总装机比例超过40%。中国新型储能规模已跃居世界\n第一。"}, {"title": "国家标准委、工业和信息化部印发《工业母机高质量标准体系建设方案》。", "detail": "《方案》提出，到2026\n年，工业母机高质量标准体系基本建立，以高质量标准体系建设促进工业母机产品质量提升和设备升级换\n代，以高水平标准引领产业高质量发展。制修订标准不少于300项，牵头制修订不少于5项相关国际标准，\n国际标准转化率达90%，标准供给结构更加优化。到2030年，适应工业母机产业高质量发展的标准体系全\n面形成，标准的技术水平和国际化程度持续跃升，以标准引领产业高质量发展的效能全面显现，减材、等\n材制造标准整体达到世界先进水平，部分增材制造标准水平达到世界领先。"}, {"title": "日前，国务院办公厅印发《关于释放体育消费潜力进一步推进体育产业高质量发展的意见》。", "detail": "其中\n提出，到2030年，培育一批具有世界影响力的体育企业和体育赛事，体育产业发展水平大幅跃升，总规模\n超过7万亿元，在构建新发展格局中发挥重要作用。"}, {"title": "9月5日10时34分，我国在西昌卫星发射中心使用长征三号丙运载火箭/远征一号上面", "detail": "级，成功将\n试验二十九号卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。试验二十九号卫星主要用\n于空间环境探测及相关技术试验。"}, {"title": "9月4日，第十七届中国生物产业大会在武汉开幕。", "detail": "本届大会以“生物科技赋能未来·生物制造重塑\n世界”为主题，举办生物制造高层论坛等26场活动，17位中外院士和700余家生物产业领域重点企业参加。"}, {"title": "9月5日，2025世界智能产业博览会在重庆市开幕，本届智博会以“人工智能+”和“", "detail": "智能网联新能源汽\n车”为年度主题，吸引全球600余家中外企业参展，室内展示面积13万平方米，室外体验区面积4万平方米，\n集中展示3000余项智能产业创新成果。新加坡担任主宾国，四川省担任主宾省。"}, {"title": "9月5日，国家主席习近平向2025世界智能产业博览会致贺信。", "detail": "习近平强调，人工智能应该是造福\n全人类的国际公共产品。中国愿同世界各国广泛开展人工智能领域国际合作，加强发展战略、治理规则、\n技术标准等方面的对接协调，促进智能产业健康蓬勃发展，让智能成果更好惠及各国人民。"}, {"title": "9月5日19时39分，我国在酒泉卫星发射中心使用谷神星一号运载火箭，成功将开运一", "detail": "号卫星发射\n升空，卫星顺利进入预定轨道，发射任务获得圆满成功。这次任务还搭载发射了驭星三号08星、云遥一号\n27星。"}, {"title": "9月4日至5日，第三届深空探测（天都）国际会议在安徽合肥召开，来自全球40多个国", "detail": "家和地区\n的驻华大使、国际组织负责人、航天机构代表、科研院所专家等共计400余人参加。会议以“小行星探测、\n3\n(cid:3)\n防御和资源利用”为主题，旨在汇聚全球深空探测领域专家学者，共同研讨小行星探测、防御及地外资源开\n发利用国际前沿问题，寻求共识，为全人类的小行星探索事业作出更多贡献。"}, {"title": "9月5日，第三届中国工业高质量发展论坛在辽宁省沈阳市举办。", "detail": "本届论坛以“创新引领、绿数协同、\n智创新质”为主题，旨在汇聚工业领域数字化、绿色化和国际化的优秀企业，共商工业高质量发展大计。"}, {"title": "2025年中国农民丰收节金秋消费季活动9月5日在浙江省杭州市启动。", "detail": "今年金秋消费季以“庆农业丰\n收享美好生活”为主题，从9月初持续到11月底，其间各地各部门将组织开展多领域、多层次、多元化的\n庆丰收促消费活动。"}, {"title": "9月5日至9日，2025“全球南方”媒体智库高端论坛在云南昆明举行，本届论坛以“", "detail": "聚南方力量应世\n界变局”为主题，来自全球110个国家和地区的260余家媒体、智库、政府机构及国际和地区组织的约500\n名代表出席。"}, {"title": "9月5日下午，2025低空经济发展大会在安徽芜湖如期开幕。", "detail": "本次大会为期3天，以“场景创新引领安\n全有序发展”为主题，专设“会”“展”“演”“引”“行”五个板块。"}, {"title": "9月6日，2025全球工业互联网大会在辽宁沈阳开幕。", "detail": "大会以“数启新章智造新质”为主题，来自政\n商学研企等领域的嘉宾共话工业互联网创新发展。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "9月6日，在2025全球南方媒体智库高端论坛开幕式上，发布了《全球南方媒体智库高", "detail": "端论坛云南\n共识》。共识强调，捍卫真正的多边主义、完善全球治理符合全球南方国家共同利益。全球南方媒体智库\n应当弘扬全人类共同价值，倡导共商共建共享的全球治理观，响亮发出要团结不要分裂、要合作不要对抗、\n要公正不要霸权的时代强音，携手推动国际秩序朝着更加公正合理的方向发展。"}, {"title": "9月7日0时34分，我国在太原卫星发射中心使用长征六号改运载火箭，成功将遥感四十", "detail": "号03组卫\n星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。遥感四十号03组卫星主要用于开展电磁环\n境探测及相关技术试验。"}, {"title": "9月8日，第二十五届中国国际投资贸易洽谈会在福建厦门举办。", "detail": "大会以“携手中国投资未来”为主\n题，展览总面积12万平方米，将举办投资促进活动超过百场，努力打造“投资中国”的标志性展会和双向投\n资促进的重要服务平台。"}, {"title": "9月8日，国家主席习近平向第二十五届中国国际投资贸易洽谈会致贺信。", "detail": "习近平强调，作为世界经\n济增长的主要贡献者和稳定锚，中国将坚定不移扩大高水平对外开放，促进贸易和投资自由化便利化，继\n续和世界分享自身的发展机遇，为全球发展注入更多正能量和确定性。中国愿同各方一道，携手推动普惠\n包容的经济全球化，共创繁荣发展的美好未来。"}, {"title": "9月8日，国内功率最大的国产商业投运重型燃气轮机“太行110”首台套商业机组在中", "detail": "国航发燃机制\n造装试基地出厂，即将交付。这标志着我国自主研制的110兆瓦级重型燃气轮机正式迈入商业化应用新阶段。"}, {"title": "9月8日，国家海洋信息中心和中国海洋发展研究会发布了2025中国海洋发展指数报告。", "detail": "指数报告\n显示，2024年，中国海洋发展指数为129.7，比上年增长2.9%。"}, {"title": "9月8日，2025海洋合作发展论坛在山东青岛举行。", "detail": "本次论坛以“从蔚蓝到未来——发展可持续海洋\n经济，共建美丽丰盈的海洋”为主题，来自68个国家和地区的约700位嘉宾将齐聚青岛。"}, {"title": "9月8日晚，国家主席习近平出席金砖国家领导人线上峰会，并发表题为《团结合作砥砺前", "detail": "行》的\n重要讲话。习近平提出三点建议：第一，坚持多边主义，捍卫国际公平正义。第二，坚持开放共赢，维护\n国际经贸秩序。第三，坚持团结合作，凝聚共同发展合力。\n4\n(cid:3)"}, {"title": "2025年9月9日3时48分，我国太原卫星发射中心在山东日照附近海域使用捷龙三号", "detail": "运载火箭，成\n功将吉利星座05组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。此次任务是捷龙三号\n运载火箭的第7次飞行。"}, {"title": "世界知识产权组织近日在香港发布《2025年全球创新指数》百强创新集群，我国以24", "detail": "个集群数量继\n续位列全球第一，数量连续第三年位居全球第一。"}, {"title": "9月9日10时00分，我国在文昌航天发射场使用长征七号改运载火箭，成功将遥感四十", "detail": "五号卫星发\n射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。遥感四十五号卫星主要用于科学试验、国土资\n源普查、农产品估产和防灾减灾等领域。"}, {"title": "9月9日，世界最大跨度斜拉桥常泰长江大桥通车。", "detail": "常泰长江大桥分为上下两层，连接江苏省常州市、\n泰州市，据了解，该大桥跨江段全长10.03公里，由一座跨主航道的跨径1208米钢桁梁斜拉桥、两座跨专\n用航道的跨径388米钢桁梁拱桥和一座3×124米的非通航孔钢桁梁桥组成，创下了最大跨度斜拉桥、最大\n跨度公铁两用钢桁拱桥的世界纪录。"}, {"title": "9月10日，2025年中国国际服务贸易交易会在北京首钢园区开幕。", "detail": "本届服贸会以“数智领航，服贸焕\n新”为年度主题，秉承“全球服务，互惠共享”的理念，首次实现全部展区集中于首钢园“一址举办”，打破以\n往“一会两址”的布局，预计吸引800余家企业线下参展。"}, {"title": "9月10日上午，在第76届国际执行理事会会议上，2025年世界灌溉工程遗产名录正", "detail": "式公布；我国申\n报的云南元阳哈尼梯田、江苏句容赤山湖灌溉工程、四川彭州湔江堰、北京门头沟永定河古渠灌溉工程全\n部成功入选。世界灌溉工程遗产名录自2014年设立，目前世界灌溉工程遗产总数量已达到200项。至此，\n我国的世界灌溉工程遗产总数已达42项。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "近日，中央宣传部、教育部向全社会公开发布2025年全国“最美教师”。", "detail": "丁美珍、马琼、水柏年、邓\n宗全、古桑曲珍、任明杰、刘玉忠、刘益春、杨洋、肖惠文、邵瑜、欧阳陵江、郑万众、孟庆阳、胡嵘苹、\n钟义信、侯纯广、姜德生、秦春娟、秦宣、黄俊琼、廖红、翟婉明、薄宜勇等24名同志和保定学院毕业生\n赴疆任教群体代表光荣入选。"}, {"title": "9月10日上午，2025世界顶尖科学家协会奖（中文简称“顶科协奖”）获奖者名单在", "detail": "上海正式公布。\n2025顶科协奖“智能科学或数学奖”授予斯坦福大学人文与科学学院名誉讲席教授孙理察，表彰他在几何分\n析与微分几何领域作出开创性工作，包括在共形偏微分方程、极小曲面、广义相对论、调和映射及山边问\n题等方面取得的奠基性成果。2025顶科协奖“生命科学或医学奖”授予康奈尔大学分子生物学与遗传学系细\n胞与分子生物学名誉教授斯科特·D·埃默尔和犹他大学生物化学系特聘教授兼系主任韦斯·I·桑德奎斯\n特，表彰他们在受体膜蛋白转运与降解细胞机制研究中的突破性发现，该机制与病毒出芽、感染进程及人\n类免疫缺陷病毒药物干预密切相关。"}, {"title": "9月10日，国新办举行“高质量完成‘十四五’规划”系列主题新闻发布会，介绍“十四", "detail": "五”时期自然资源\n工作高质量发展成就。据介绍，我国持续开展调查监测，自然资源家底更加厚实。截至2024年底：全国耕\n地面积达19.4亿亩，比2020年增加2800万亩，牢牢守住了耕地保护红线。林地、草地、湿地、沙化土地面\n积分别为42.53亿亩、39.12亿亩、8.34亿亩、25.09亿亩。森林覆盖率达25.09%，比2020年提高约2个百分\n点，我国成为全球增绿最多最快的国家；森林蓄积量达209.88亿立方米，提前实现应对气候变化国家自主\n贡献2030年目标。"}, {"title": "第十四届中国知识产权年会9月11日—12日在北京举行，主题为“数字时代的知识产权", "detail": "”。国家知识\n5\n(cid:3)\n产权局负责人介绍，2024年，我国数字经济核心产业发明专利授权量已经达到50万件，位居全球第一，同\n比增速达23.1%。"}, {"title": "9月11日上午，国新办举行“高质量完成‘十四五’规划”系列主题新闻发布会，介绍“", "detail": "十四五”时期卫生\n健康工作发展成就。据介绍，2024年我国人均预期寿命达到79岁，比2020年提高1.1岁，孕产妇死亡率、\n婴儿死亡率持续改善。"}, {"title": "9月11日，2025年全国食品安全宣传周活动将正式启动。", "detail": "活动主题为“尚德守法共享食安”。宣传周\n期间将在北京举办“全国食品安全宣传周”主场活动，以及第十六届中国食品安全论坛、第四届中国食育大会\n等活动。"}, {"title": "第50届南丁格尔奖颁奖大会9月12日上午在北京人民大会堂举行。", "detail": "南丁格尔奖是红十字国际委员\n会设立的国际护理界最高荣誉。今年共有来自17个国家的35名护理人员获得南丁格尔奖。我国有7名优秀\n护理工作者获此殊荣，是本届获奖人数最多的国家。他们分别是：武汉大学中南医院副主任护师冯玲，甘\n肃省人民医院主任护师韩琳，香港特别行政区红十字会资深医护义工梁伟贤，解放军总医院第五医学中心\n副主任护师秦玉玲，天津市第三中心医院主任护师田丽，上海市第一人民医院主任护师邢红，陕西省人民\n医院主任护师张玉莲。"}, {"title": "十四届全国人大常委会第十七次会议9月12日表决通过新修订的仲裁法，自2026年3", "detail": "月1日起施行。\n新修订的仲裁法规定，仲裁活动可以通过信息网络在线进行，但当事人明确表示不同意的除外。仲裁活动\n通过信息网络在线进行的，与线下仲裁活动具有同等法律效力。"}, {"title": "9月12日，2025中国国际福祉博览会暨中国国际康复博览会在北京国家会议中心举办", "detail": "，400余家国\n内外企业、机构参展。本届博览会以“科技赋能·共享福祉”为主题，集中展示万余种科技助残创新产品，并\n同期举办30余场学术交流与产业对接活动，打造康复辅具产业创新成果的展示窗口与合作平台。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "9月12日，十四届全国人大常委会第十七次会议表决通过了《中华人民共和国法治宣传教", "detail": "育法》，\n自2025年11月1日起施行。法律明确，国家实行公民终身法治教育制度，将法治教育纳入国民教育、干部\n教育、社会教育体系。"}, {"title": "十四届全国人大常委会第十七次会议9月12日表决通过《中华人民共和国国家公园法》，", "detail": "自2026\n年1月1日起施行。这部法律规定，国家建立统一规范高效的国家公园管理体制。坚持山水林田湖草沙一\n体化保护，按照自然生态系统特性和内在规律，对国家公园实行整体保护、系统修复、综合治理。"}, {"title": "9月12日晚，2025长江文化艺术季在湖北武汉启幕。", "detail": "本届艺术季以“勇担支点建设使命打造长江文\n化高地”为主题，通过丰富多彩的文艺演出和文化交流活动，展现长江文化的深厚底蕴与开放包容。"}, {"title": "9月13日，2025金熊猫国际文化论坛在四川成都举行。", "detail": "2025金熊猫国际文化论坛是第二届金熊猫奖\n的主体活动之一，今年的主题为“文明共聚开创未来”，来自海内外的780余位嘉宾出席论坛，围绕“数智赋\n能”等主题深入开展交流。"}, {"title": "目前，我国已成为全球人工智能专利最大拥有国，企业数量超5000家，2025年人工", "detail": "智能市场规模有\n望超7000亿元。预计到2030年，我国人工智能核心产业规模或超过1万亿元，并带动相关产业规模超过\n10万亿元。"}, {"title": "9月12日至14日，2025中国文化旅游产业博览会在湖北武汉举行，本次博览会以“", "detail": "深化文旅融合畅\n享美好生活”为主题，融合“展、演、销、游”四大功能。4万平方米的室外展区展示以“河山添锦绣”为主题的\n文旅IP花车矩阵，6万平方米的室内展馆集中展现文旅新业态、新场景、新产品，涵盖数字集群、智能导\n6\n(cid:3)\n览、低空文旅、非遗文创等方面，吸引了国内2000余家展商以及50家海外旅行商参展。"}, {"title": "9月14日，我国首批规模性采用10兆瓦发电机组的单体最大陆上风电项目——内蒙古能", "detail": "源乌拉特中\n旗150万千瓦风储基地项目，正式投入商业运行。"}, {"title": "国务院日前印发《关于全国部分地区要素市场化配置综合改革试点实施方案的批复》，同意", "detail": "自即日\n起2年内开展北京城市副中心、苏南重点城市、杭甬温、合肥都市圈、福厦泉、郑州市、长株潭、粤港澳\n大湾区内地九市、重庆市、成都市等10个要素市场化配置综合改革试点。"}, {"title": "日前，国务院办公厅印发修编后的《“三北”工程总体规划》，《规划》坚持以习近平新时", "detail": "代中国特\n色社会主义思想为指导，认真贯彻习近平生态文明思想，完整准确全面贯彻新发展理念，以防沙治沙为主\n攻方向，以筑牢北方生态安全屏障为根本目标，坚持扩绿兴绿护绿“三绿”并举，推动森林水库、钱库、粮库、\n碳库“四库”联动，更加注重“提质”、“兴业”、“利民”，着力优化治理格局，完善政策措施，巩固拓展建设成\n果，不断提高生态产品供给能力，稳步提升生态系统多样性、稳定性和持续性。"}, {"title": "9月15日上午，2025年国家网络安全宣传周开幕式在云南昆明举行，今年网安周的主", "detail": "题是“网络安全\n为人民，网络安全靠人民——以高水平安全守护高质量发展”。开幕式上举行了12387网络安全事件报告平\n台启动仪式。"}, {"title": "金融监管总局、中国人民银行、中国证监会9月15日联合启动金融教育宣传周活动。", "detail": "本次活动以“保\n障金融权益助力美好生活”为主题，围绕“为民办实事，提升服务水平；规范营销行为，强化适当性管理；\n抵制非法中介，维护金融秩序；防范电信诈骗，保护财产安全”等四方面，汇聚政府部门、行业协会、金融\n机构、社会媒体等多方力量，开展多渠道、多形式、分人群、有侧重的金融教育宣传。"}, {"title": "由国际采购与供应管理联盟成员共同发起的《全球供应链发展与稳定厦门倡议》9月15日", "detail": "正式发布。\n倡议提出，要坚定维护多边贸易体制，共同建设开放、包容、韧性、可持续的全球供应链。"}, {"title": "据工信部网站消息，工业和信息化部等八部门印发《汽车行业稳增长工作方案（2025—", "detail": "2026年）》，\n主要目标为：2025年，力争实现全年汽车销量3230万辆左右，同比增长约3%，其中新能源汽车销量1550\n万辆左右，同比增长约20%；汽车出口保持稳定增长；汽车制造业增加值同比增长6%左右。2026年，行业\n运行保持稳中向好发展态势，产业规模和质量效益进一步提升。"}, {"title": "9月16日9时6分，我国在酒泉卫星发射中心使用长征二号丙运载火箭/远征一号S上面", "detail": "级，成功将\n卫星互联网技术试验卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "9月16日出版的第18期《求是》杂志发表习近平的重要文章《纵深推进全国统一大市场", "detail": "建设》。文\n章指出，纵深推进全国统一大市场建设，基本要求是“五统一、一开放”。“五统一”，就是统一市场基础制度，\n特别是实现产权保护、公平竞争、质量标准等制度的统一；统一市场基础设施，打通物流、资金流、信息\n流，健全现代商贸流通体系；统一政府行为尺度，地方在推动经济发展特别是招商引资时，哪些能干哪些\n不能干有明确规矩，不能各行其是；统一市场监管执法，明确市场监管行政处罚裁量基准，一把尺子量到\n底；统一要素资源市场，促进自由流动、高效配置，减少资源错配和闲置浪费。“一开放”，就是持续扩大开\n放，实行对内对外开放联通，不搞封闭运行。\n文章指出，要聚焦重点难点，下决心清除顽瘴痼疾。第一，着力整治企业低价无序竞争乱象。第二，\n着力整治政府采购招标乱象。第三，着力整治地方招商引资乱象。第四，着力推动内外贸一体化发展。第\n五，着力补齐法规制度短板。第六，着力纠治政绩观偏差。"}, {"title": "当地时间9月16日，世界知识产权组织公布了《2025年全球创新指数报告》。", "detail": "在对全球近140个经\n济体的排名中，中国较去年排名上升1位至第十位。\n7\n(cid:3)"}, {"title": "9月16日，2025金砖国家新工业革命伙伴关系论坛在福建厦门开幕，本次论坛以“释", "detail": "放大金砖合作潜\n力实现包容可持续工业化”为主题。"}, {"title": "9月16日，第六届中国质量大会在江苏南京举办，本届大会以“质量：赋能新质生产力”", "detail": "为主题。中\n国质量大会作为质量领域规格最高、规模最大、影响最广的国际性质量会议之一，已成为面向世界的质量\n交流合作平台。"}, {"title": "从国务院新闻办公室9月16日举行的新闻发布会获悉，第五届世界生物圈保护区大会将于", "detail": "2025年9\n月22日至25日在浙江杭州举办。这是该大会首次在亚洲举办，将有全球150多个国家和地区的约4000名\n代表参会，规模达历届之最。大会将发布《杭州宣言》。目前，我国已有34个自然保护地被联合国教科文\n组织批准为世界生物圈保护区，总数位居亚洲第一。"}, {"title": "9月16日，国务院新闻办举行“高质量完成‘十四五’规划”系列主题新闻发布会，介绍", "detail": "“十四五”时期农\n业农村发展成就。2024年，我国粮食产量首次突破1.4万亿斤，人均粮食占有量达到500公斤，做到谷物基\n本自给、口粮绝对安全。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "中国人民抗日战争暨世界反法西斯战争胜利80周年纪念活动总结会议9月17日上午在京", "detail": "举行。日\n前，习近平主持召开中央政治局常委会会议，专门听取纪念活动总结报告并发表重要讲话。习近平强调，\n纪念中国人民抗日战争暨世界反法西斯战争胜利80周年活动，是一次庄严隆重、大气磅礴、震撼人心、激\n励奋进的抗战纪念盛典，进一步弘扬了伟大抗战精神，进一步坚定了全面推进强国建设、民族复兴伟业的\n信念信心，进一步展示了推动构建人类命运共同体的责任担当。"}, {"title": "9月17日，第22届中国—东盟博览会暨中国—东盟商务与投资峰会在广西南宁开幕，主", "detail": "题为“数智\n赋能发展，创新引领未来——以中国—东盟自贸区3.0版新机遇助建命运共同体”。"}, {"title": "9月17日，2025年世界互联网大会文化遗产数字化论坛在陕西西安开幕，论坛以“数", "detail": "联古今智绘文\n明——携手构建网络空间命运共同体”为主题，这是世界互联网大会首次围绕文化遗产数字化举办论坛活动。"}, {"title": "9月17日，2025世界储能大会在福建宁德开幕。", "detail": "本届大会以“储能新纪元零碳启未来”为年度主题，\n旨在打造具有全球影响力的储能领域交流合作平台，推动储能产业迈向可持续、高质量发展新阶段。"}, {"title": "第十二届北京香山论坛9月18日在北京国际会议中心开幕。", "detail": "本届论坛主题为“共护国际秩序、共促\n和平发展”，100余个国家、地区和国际组织官方代表及专家学者和各国观察员等1800余名嘉宾出席。"}, {"title": "国务院总理李强日前签署国务院令，公布《外国驻华外交领事机构中国籍雇员管理条例》，", "detail": "自2026\n年1月1日起施行。《条例》旨在便利外国驻华外交领事机构执行职务，维护中国籍雇员的合法权益。《条\n例》共12条。"}, {"title": "9月17日，2025世界清洁能源装备大会在四川德阳开幕，此次大会以“绿色新能源·", "detail": "智造新未来”为\n主题。"}, {"title": "国务院新闻办公室于9月18日举行“高质量完成‘十四五’规划”系列主题新闻发布会，", "detail": "介绍“十四五”\n时期科技创新发展成就。2024年，我国高被引科学家达到1405人次，比2021年增长了50%，占全世界的\n1/5。"}, {"title": "在中国致公党成立100周年之际，习近平发来贺信，代表中共中央表示热烈祝贺，向致公", "detail": "党全体同\n志致以诚挚问候。习近平强调，新征程上，希望致公党始终坚持中国共产党的领导，深入学习贯彻新时代\n中国特色社会主义思想，坚守合作初心，发扬优良传统，加强自身建设，认真履职尽责，广泛团结海外侨\n胞、归侨侨眷和留学人员，积极服务祖国统一大业，为以中国式现代化全面推进强国建设、民族复兴伟业\n8\n(cid:3)\n作出新的更大贡献。"}, {"title": "国务院新闻办公室于9月19日举行“高质量完成‘十四五’规划”系列主题新闻发布会，", "detail": "介绍以生态环境\n高水平保护推动高质量发展情况。我国陆域生态保护红线面积占比超过了30%。持续开展“绿盾”自然保护地\n强化监督，共发现查处4545个涉及国家级自然保护区的重点问题，已基本完成整改。"}, {"title": "9月19日晚，第三届全国技能大赛在河南郑州开赛。", "detail": "本届大赛以“技能照亮前程”为主题，35个代表\n团的3420名选手围绕106个竞赛项目参赛。这是我国赛事规格最高、竞赛项目最多、参赛规模最大、影响\n范围最广的综合性国家职业技能赛事。"}, {"title": "联合国教科文组织9月19日在巴黎总部举行联合国教科文组织-阿勒福赞科学、技术、工", "detail": "程、数学领\n域杰出青年科学家国际奖（简称“阿勒福赞奖”）颁奖典礼，中国科学院大气物理研究所研究员成里京获奖，\n以表彰其为海洋气候变化提供的科学证据，这些证据是评估风险、适应和减缓气候变化的关键基础。"}, {"title": "9月20日，2025世界制造业大会在安徽省合肥市开幕。", "detail": "大会为期四天，以“智造世界·创造美好”为\n主题，举办开幕式暨主旨演讲、重大项目对接、“十四五”制造业发展成就展示、重点产业链供应链供需对接、\n大会发布等活动。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "2026国际篮联女篮世界杯预选赛将于2026年3月11日至17日举行。", "detail": "国际篮联日前宣布，比赛将由\n土耳其伊斯坦布尔、法国维勒班、波多黎各圣胡安以及中国武汉四座城市共同承办。"}, {"title": "2025年9月20日是第25个全民国防教育日，9月也是“全民国防教育月”，中国各", "detail": "地采取多种形式开\n展国防教育活动。今年“全民国防教育月”主题为“弘扬抗战精神共筑国防长城”。"}, {"title": "9月20日从昆明海关获悉，自2021年12月中老铁路通车运营以来，截至2025年", "detail": "9月19日，经中老\n铁路进出口货物突破1500万吨，货值超653亿元。"}, {"title": "9月20日，全国首座500千伏全自主可控新一代变电站——西泉变电站在辽宁投运。", "detail": "西泉变电站首\n次实现了电气、保护设备的核心材料、关键芯片、操作系统、数据库乃至技术标准体系的全链条国产化，\n提高了电网安全和辽北地区新能源电力送出能力。"}, {"title": "近日，第十九届中华老字号博览会在上海展览中心举行。", "detail": "本届博览会以“传承焕新篇·国潮正当时”\n为主题，近1万平方米展区汇集了全国超过200家老字号品牌及产业链机构，覆盖食品、医药、服装、鞋帽、\n文创、工艺品等多元领域，更有非遗展演、跨界新品和沉浸式体验等亮点，打造一场“可逛、可品、可购、\n可娱”的老字号文化盛宴。"}, {"title": "9月21日，第八届丝绸之路（敦煌）国际文化博览会开幕式在甘肃敦煌举行，本届敦煌文", "detail": "博会主题\n是“加强文化交流，促进文明互鉴”，邀请1000余名中外嘉宾参会，泰国担任主宾国。"}, {"title": "在第八个“中国农民丰收节”到来之际，习近平代表党中央，向全国广大农民和工作在“三", "detail": "农”战线上的\n同志们致以节日祝贺和诚挚问候。习近平强调，中国式现代化离不开农业农村现代化。各级党委和政府要\n深入贯彻党中央决策部署，坚持农业农村优先发展，完善强农惠农富农政策，强化农业科技装备支撑，着\n力提升农业综合生产能力，多措并举促进农民就业和增收，扎扎实实推进乡村全面振兴。希望广大农民群\n众充分发挥主动性创造性，社会各界积极支持参与，努力建设宜居宜业和美乡村，共同奔向中国式现代化\n的美好未来。"}, {"title": "9月22日，工业和信息化部等部门联合印发《钢铁行业稳增长工作方案（2025—20", "detail": "26年）》，明确\n未来两年钢铁行业增加值年均增长目标设定在4%左右。该方案以“稳增长、防内卷”为核心，为中国钢铁行\n业的结构性调整与高质量发展指明实施路径。\n9\n(cid:3)"}, {"title": "9月22日，第五届世界生物圈保护区大会在浙江杭州开幕，本届大会是首次在亚洲举办的", "detail": "世界生物\n圈保护区大会，也是联合国教科文组织成员国参与范围最广的一届大会，将有全球150多个国家和地区约\n4000名代表参会。"}, {"title": "9月22日举行的“高质量完成‘十四五’规划”发布会上，中国人民银行行长潘功胜说，", "detail": "我国金融事业取\n得新的重大成就，截至2025年6月末，银行业总资产近470万亿元，位居世界第一；股票、债券市场规模\n位居世界第二；外汇储备规模连续20年位居世界第一。"}, {"title": "2025年全国“诚信兴商宣传月”活动9月22日在湖北省咸宁市正式启动。", "detail": "活动以“诚实守信，利企惠民”\n为主题，旨在弘扬诚信文化，优化消费环境，推动社会信用体系建设高质量发展。"}, {"title": "9月22日，我国首个“新能源+重载铁路”融合项目——包神铁路正式投入运行，标志着", "detail": "我国铁路供能\n迈入绿色新阶段。"}, {"title": "第十二届丝绸之路国际电影节9月22日晚在福建福州开幕。", "detail": "本届电影节以“丝路通天下光影耀闽\n都”为主题，共征集到来自135个国家和地区的3500余部参展、参赛影片，其中境外影片占比超92%。"}, {"title": "9月23日，2025北京文化论坛在北京开幕。", "detail": "论坛以“文化和科技融合发展”为主题，来自58个国家\n和地区的800多位嘉宾出席论坛。"}, {"title": "9月23日，2025年中国农民丰收节主场活动在山东招远举办。", "detail": "今年是第八个中国农民丰收节，各地\n以“庆农业丰收享美好生活”为主题，秉承“庆祝丰收、弘扬文化、振兴乡村”的宗旨，突出农民主体，组织\n开展丰富多彩的庆祝丰收活动，充分展现“三农”发展辉煌成就，传承弘扬中华优秀传统文化，展现新时代农\n民精神风貌。"}, {"title": "9月23日，2025欧亚经济论坛在陕西西安开幕，本届论坛举办时间为9月23日至2", "detail": "5日，主题为“聚\n合欧亚新动能共筑可持续发展新格局”。3天会期内将举办上合组织国家地学合作与矿业投资研讨会、欧亚\n青年精英对话会、中医药交流合作会议等13场分会，举行经贸交流、文化交流等活动。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "9月23日，第三届大国工匠创新交流大会暨大国工匠论坛在重庆开幕。", "detail": "本届大会以“匠心铸梦向新\n而行”为主题，旨在大力弘扬劳模精神、劳动精神、工匠精神，集中展示大国工匠和广大职工在推动高质量\n发展、发展新质生产力中的卓越贡献与创新成果，激励亿万职工在中国式现代化建设的伟大征程中再创佳\n绩。"}, {"title": "9月23日上午，国务院新闻办公室举行高质量完成“十四五”规划系列主题新闻发布会。", "detail": "教育部介绍，\n我国基础教育已达世界高收入国家平均水平。据介绍，我国已经建成规模最大且高质量的教育体系。基础\n教育已经达到世界高收入国家平均水平，今年学前一年免费惠及1200多万儿童，义务教育全国2895个县域\n全部实现基本均衡。高等教育毛入学率从2012年30%到现在的60.8%，提高了一倍多，进入世界公认的普\n及化阶段。"}, {"title": "习近平9月24日听取新疆维吾尔自治区党委和政府工作汇报。", "detail": "他强调，新疆要完整准确全面贯彻\n新时代党的治疆方略，坚持稳中求进工作总基调，统筹发展和安全，牢牢扭住社会稳定和长治久安工作总\n目标，紧紧围绕铸牢中华民族共同体意识、推进中华民族共同体建设，锚定中央赋予的“五大战略定位”，凝\n心聚力、久久为功，努力建设团结和谐、繁荣富裕、文明进步、安居乐业、生态良好的社会主义现代化新\n疆。\n习近平指出，要全力维护新疆社会大局稳定。坚持抓基层、强基础、固根本，筑牢反恐维稳的人民防\n线。铸牢中华民族共同体意识、推进中华民族共同体建设，推进我国宗教中国化，加强文化润疆、注重以\n10\n(cid:3)\n文化人，引导各族干部群众树立正确的国家观、历史观、民族观、文化观、宗教观。"}, {"title": "2025年9月24日15时56分，我国太原卫星发射中心在山东日照附近海域使用捷龙", "detail": "三号运载火箭，\n成功将吉利星座06组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。此次任务还搭载发\n射了北大时空星01试验星。此次任务是捷龙三号运载火箭的第8次飞行。"}, {"title": "9月24日，第四届北斗规模应用国际峰会在湖南株洲开幕，本届峰会以“同世界·共北斗", "detail": "——智联\n时空”为主题，国内外政府官员、企业负责人、科技人员和国际组织代表等约800人参加了开幕式。"}, {"title": "9月24日，2025年中国碳市场大会在上海举行，本次大会以“完善碳定价机制，激发", "detail": "绿色低碳发展\n新动能”为主题。大会围绕全国碳市场运行经验总结、健全碳市场交易体系、碳金融创新等关键议题展开深\n入交流，旨在进一步提升中国在国际碳交易体系中的影响力，推动碳市场健康有序发展，为实现《巴黎协\n定》气候目标贡献中国智慧与方案。"}, {"title": "以“加大国家通用语言文字推广力度，促进铸牢中华民族共同体意识”为主题的第28届全", "detail": "国推广普通\n话宣传周主题活动9月24日在四川省凉山彝族自治州西昌市举行。"}, {"title": "9月24日，国家主席习近平在联合国气候变化峰会发表视频致辞。", "detail": "习近平宣布中国新一轮国家自主\n贡献：到2035年，中国全经济范围温室气体净排放量比峰值下降7%—10%，力争做得更好。非化石能源消\n费占能源消费总量的比重达到30%以上，风电和太阳能发电总装机容量达到2020年的6倍以上、力争达到\n36亿千瓦，森林蓄积量达到240亿立方米以上，新能源汽车成为新销售车辆的主流，全国碳排放权交易市\n场覆盖主要高排放行业，气候适应型社会基本建成。"}, {"title": "9月25日，我国首个国家级陆相页岩油示范区——中国石油新疆吉木萨尔页岩油累计产量", "detail": "突破500\n万吨，标志着我国对页岩油的开发从技术探索迈向稳定产出阶段。"}, {"title": "9月25日上午，新疆维吾尔自治区成立70周年庆祝大会在新疆人民会堂隆重举行。", "detail": "习近平出席庆\n祝大会。王沪宁表示，新疆维吾尔自治区70年来取得的辉煌成就，充分彰显了党的领导和社会主义制度的\n显著优势，充分展现了中国特色解决民族问题正确道路的强大生命力，充分证明了新时代党的治疆方略是\n完全正确的。"}, {"title": "9月25日，2025年全国国庆文化和旅游消费月主场活动在四川省成都市举办，正式启", "detail": "动国庆文旅消\n费月，于9月下旬至10月下旬开展系列文旅消费活动，激发假日消费活力，满足人民美好生活需要。"}, {"title": "9月25日，第四届全球数字贸易博览会在浙江杭州举办，本次大会以“在数贸会看见创新", "detail": "未来”为年\n度主题，突出“数字贸易与AI深度融合”，吸引来自154个国家（地区）、33个国际组织以及超过1800家中\n外企业设展参会，4.2万余名专业客商到会采购，规模、影响和热度均创历史之最，有力推动各方共享全球\n数字贸易发展新机遇。"}, {"title": "9月26日，我国第15次北冰洋科学考察“雪龙2”号船返回上海，标志着此次考察圆满", "detail": "完成任务。在\n“雪龙2”号船保障支持下，“深海一号”船搭载“蛟龙”号成功实现了首次我国载人深潜北极冰区下潜，标志着\n我国深海进入和深海探测能力持续增强。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "2025年9月26日1时35分，经过约6小时的出舱活动，神舟二十号航天员乘组圆满", "detail": "完成第四次出\n舱活动。出舱活动期间，航天员陈中瑞、王杰完成了空间站空间碎片防护装置安装、舱外设备设施巡检等\n任务，这是我国首次由两名第三批航天员共同完成舱外作业任务。至此，神舟二十号航天员乘组已完成四\n次出舱活动，成为我国执行出舱任务次数最多的两个乘组之一。"}, {"title": "9月26日，2025“大河对话”在湖北武汉开幕，活动以“大河文明——全球水安全与", "detail": "高质量发展”为主\n11\n(cid:3)\n题，吸引了国际组织官员、世界流域机构专家、水博物馆联盟代表等来自全球20多个国家和地区的40多位\n国际专家，以及国内知名高校和研究机构学者约200位代表出席。"}, {"title": "当地时间9月26日，国务院总理李强在纽约联合国总部出席第80届联合国大会一般性辩", "detail": "论并发表\n讲话。李强表示，今年是世界反法西斯战争胜利80周年，也是联合国成立80周年。回首既往，我们可以得\n出一些宝贵启示：和平与发展是各国人民最热切的共同期盼，团结合作是人类进步最强大的力量源泉，公\n平正义是国际社会最重要的价值追求。\n李强指出，中国人常讲，不忘初心，方得始终。追求和平、进步、发展，就是我们纪念胜利的初心所\n在，就是我们携手奋斗的使命所在。我们或许不能回到过去，但完全可以创造更好的未来。在世界变乱交\n织之际，我们要共筑和平、共享安全。在全球增长乏力之际，我们要重振合作、谋求共赢。在多元文明激\n荡之际，我们要倡导对话、美美与共。在新型挑战频出之际，我们要携手应对、共护家园。"}, {"title": "2025年9月27日3时28分，我国在酒泉卫星发射中心使用长征四号丙运载火箭，成", "detail": "功将风云三号\n08星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "联合国教科文组织9月27日发布公报说，该组织新认定了26个生物圈保护区，其中包括", "detail": "我国的大\n青山生物圈保护区和周至生物圈保护区。至此，世界生物圈保护区网络中的保护区总数达到785个。"}, {"title": "中国科学院合肥物质科学研究院联合多家机构成功研制全超导磁体系统，于9月27日凌晨", "detail": "实现"}, {"title": "1T稳态强磁场，并持续稳定运行30分钟。", "detail": "这一强度相当于地球磁场的70万倍，刷新了我国稳态强磁\n场技术纪录。"}, {"title": "中国海油9月28日宣布，我国海底油气管道总长度突破10000公里，跃居世界前列，", "detail": "标志着我国海\n洋油气管道工程技术与装备能力实现全方位跨越，对加快海洋油气资源开发、提升国家海洋能源自主保障\n能力具有里程碑意义。\n获取后续更新及更多考试资料，请加客服微信：yumi9938"}, {"title": "9月28日，横跨贵州省贞丰县与关岭县的世界第一高桥——六安高速花江峡谷大桥正式建", "detail": "成通车。\n这座“横竖”都是世界第一的超级大桥，主桥跨径1420米，居山区桥梁世界第一；桥面至水面高差625米，\n同样登顶世界第一，将成为连通贵州六枝至安龙高速公路的关键枢纽。"}, {"title": "9月27日20时40分，我国在太原卫星发射中心使用长征六号改运载火箭，成功将卫星", "detail": "互联网低轨\n11组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。此次任务是长征系列运载火箭的第\n597次飞行。"}, {"title": "9月28日，国家统计局发布《十四五”以来社会民生统计报告》。", "detail": "总人口和劳动年龄人口规模优势\n依然明显。2024年末，全国人口总量为140828万人，人口总量位居世界前列。2024年，我国16—59岁劳\n动年龄人口为85798万人，占总人口的60.9%，规模优势和人口红利依然存在。2024年末，我国城镇人口94350\n万人，城镇化率为67.00%，比2020年末提高3.11个百分点，城镇化率持续提高。2024年，我国人口平均预\n期寿命达到79.0岁，比2020年提高1.07岁，比世界平均水平高5岁。"}, {"title": "9月28日，2025年第三届“全国一刻钟便民生活服务月”启动仪式在山西太原举行。", "detail": "今年10月1日\n至31日，商务部组织开展第三届“全国一刻钟便民生活服务月”，活动口号是“便民乐享服务万家”。"}, {"title": "9月29日，国家统计局、科学技术部、财政部公布2024年全国科技经费投入统计公报", "detail": "，2024年，\n全国共投入研究与试验发展（R&D）经费36326.8亿元，比上年增加2969.7亿元，增长8.9%；研究与试验\n发展（R&D）经费投入强度（与国内生产总值之比）为2.69%，比上年提高0.11个百分点。"}, {"title": "9月29日，国家重大科技基础设施——超重力离心模拟与实验装置在浙江杭州启动首台离", "detail": "心机主机。\n12\n(cid:3)\n该设施将营造超过地球重力千百倍的“超重力场”，实现“时空压缩”效应，为一系列研究提供关键支撑。本次\n启动的首台离心机“CHIEF1300”容量为1300g·t（重力加速度·吨），是目前世界上容量最大的离心机。\n13\n(cid:3)"}]}, {"month": "2025年10月", "year": 2025, "items": [{"title": "2025年9月29日11时00分，我国在西昌卫星发射中心使用长征二号丁运载火箭，", "detail": "成功将试验三十\n号卫星01、02星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。该卫星主要用于对地观测技\n术试验验证。试验三十号卫星01、02星主要用于对地观测技术试验验证。执行此次发射任务的是我国的“金\n牌火箭”长征二号丁运载火箭，这是它的第100次发射，长二丁也成为我国第二型突破百发的单一型号运\n载火箭，并且保持全胜战绩，创造了我国运载火箭历程中又一个新纪录。"}, {"title": "中共中央政治局9月29日召开会议，研究制定国民经济和社会发展第十五个五年规划重大", "detail": "问题。会\n议强调，“十五五”时期经济社会发展必须坚持党的全面领导，坚决维护党中央权威和集中统一领导，把\n党的领导贯穿经济社会发展各方面全过程；坚持人民至上，尊重人民主体地位，让现代化建设成果更多更\n公平惠及全体人民；坚持高质量发展，以新发展理念引领发展，因地制宜发展新质生产力，推动经济持续\n健康发展和社会全面进步；坚持全面深化改革，扩大高水平开放，持续增强发展动力和社会活力；坚持有\n效市场和有为政府相结合，充分发挥市场在资源配置中的决定性作用，更好发挥政府作用；坚持统筹发展\n和安全，强化底线思维，有效防范化解各类风险，以新安全格局保障新发展格局。\n会议强调，坚持和加强党的全面领导是推进中国式现代化的根本保证。必须坚持以党的自我革命引领\n社会革命，持之以恒推进全面从严治党，增强党的政治领导力、思想引领力、群众组织力、社会号召力，\n提高党领导经济社会发展能力和水平，为推进中国式现代化凝聚磅礴力量。"}, {"title": "庆祝中华人民共和国成立76周年招待会9月30日晚在人民大会堂举行。", "detail": "习近平强调，面对百年变局\n加速演进的国际形势，我们要大力弘扬全人类共同价值，践行真正的多边主义，推动落实全球发展倡议、\n全球安全倡议、全球文明倡议、全球治理倡议，同各国携手构建人类命运共同体。"}, {"title": "10月1日出版的第19期《求是》杂志将发表习近平的重要文章《中华民族共同体的形成", "detail": "和发展是人\n心所向、大势所趋、历史必然》。这是习近平总书记2024年9月27日在全国民族团结进步表彰大会上讲\n话的一部分。文章指出，中华民族共同体的形成和发展是人心所向、大势所趋、历史必然。各民族血脉相\n融，是中华民族共同体形成和发展的历史根基。各民族信念相同，是中华民族缔造统一的多民族国家的内\n生动力。各民族文化相通，是中华民族铸就多元一体文明格局的文化基因。各民族经济相依，是中华民族\n构建统一经济体的强大力量。各民族情感相亲，是中华民族一家亲的坚强纽带。\n文章强调，五千多年中华文明所孕育的伟大祖国、伟大民族，永远是全体中华儿女最深沉、最持久的\n情感所系。在这片辽阔、美丽、富饶的土地上，各族人民都有一个共同家园，就是中国；都有一个共同身\n份，就是中华民族；都有一个共同名字，就是中国人；都有一个共同梦想，就是实现中华民族伟大复兴。"}, {"title": "近日，我国自主研制的载人飞艇“祥云”AS700在西南地区完成了首次飞行，全面检验", "detail": "了飞艇在高原\n地区低空环境飞行的稳定性和安全性。"}, {"title": "10月5日，世界最高双联主塔——石沱长江大桥高度为253米的6号主塔顺利封顶。", "detail": "石沱长江大桥\n位于重庆市涪陵区，是渝万高铁全线控制性工程，由中铁大桥局承建。该桥主桥全长1056米，主跨608米，\n是首次采用公铁合建双联塔、公铁同层分幅主梁的桥梁。其6号主塔高253米，是世界最高双联主塔。"}, {"title": "当地时间10月6日，瑞典卡罗琳医学院宣布，将2025年诺贝尔生理学或医学奖授予科", "detail": "学家玛丽·E·布\n伦科（MaryE.Brunkow）、弗雷德·拉姆斯德尔（FredRamsdell）和坂口志文（ShimonSakaguchi），表\n彰他们在外周免疫耐受方面的研究贡献。"}, {"title": "当地时间10月7日，瑞典皇家科学院决定将2025年诺贝尔物理学奖授予科学家约翰·", "detail": "克拉克、麦\n克·H·德沃雷特、约翰·M·马蒂尼，以表彰他们在量子力学领域的贡献。\n1\n(cid:3)"}, {"title": "近日，工业和信息化部等六部门联合印发《机械行业稳增长工作方案（2025—2026", "detail": "年）》，提出2025\n—2026年力争机械行业营业收入平均增速达到3.5%左右，到2026年营业收入突破10万亿元，培育一批具\n有竞争力的中小企业特色产业集群和具有国际竞争力的产业集群等目标。"}, {"title": "国家海洋信息中心、中国海洋发展研究会今年9月联合发布的《2025中国海洋发展指数", "detail": "报告》显示，\n我国海洋水产品产量连续多年居全球首位，2024年产量超3700万吨，人均海洋水产品占有量26.7公斤，\n比上年增加0.5公斤，更好满足居民优质蛋白营养需求。"}, {"title": "当地时间10月8日，瑞典皇家科学院决定将2025年诺贝尔化学奖授予北川进（Sus", "detail": "umuKitagawa）、\n理查德·罗布森（RichardRobson）以及奥马尔·M·亚吉（OmarM.Yaghi）三位科学家，以表彰其在金属\n有机骨架化合物开发领域的贡献。"}, {"title": "10月8日，位于广西南宁市武鸣区的伏林钠离子电池储能电站二期扩容升级工程正式投运。", "detail": "作为全\n国首个大容量钠离子电池储能电站，该工程依托国家重点研发计划“百兆瓦时级钠离子电池储能技术”项\n目，为绿电高效消纳注入“钠电动能”。"}, {"title": "10月9日，第十五届全国运动会和全国第十二届残疾人运动会暨第九届特殊奥林匹克运动", "detail": "会（简称\n“十五运会和残特奥会”）火种采集仪式在广州举行。此次火种采集活动包含“源火”采集与“圣火”点\n燃两大环节。活动现场，采集自深海的“源火”首度揭晓其神秘面纱。采火技术团队代表手捧“源火”盒\n走上舞台，这一簇来自南海1522米深处的可燃冰“源火”正式对外亮相。"}, {"title": "日前，国务院办公厅印发《电子印章管理办法》，对电子印章管理和应用活动进行规范。", "detail": "《办法》\n要求，电子印章管理工作遵循统筹推进、分级管理、规范标准、安全可控的原则。国家密码管理局会同有\n关部门统筹协调和推进全国电子印章的规范管理和推广应用，各地区各部门应当统筹加强本地区本部门（本\n系统）电子印章的规范管理和推广应用，促进电子印章互信互认。"}, {"title": "北京时间10月9日，2025年诺贝尔文学奖公布，授予匈牙利作家拉斯洛·克拉斯纳霍", "detail": "尔凯，“以\n表彰他引人入胜且富有远见的作品，在世界末日的恐怖中，再次证明了艺术的力量。”"}, {"title": "10月10日，中共中央总书记习近平致电朝鲜劳动党总书记金正恩，祝贺朝鲜劳动党成立", "detail": "80周年。\n习近平强调，中朝两国同为共产党领导的社会主义国家。近年来，我同总书记同志多次会晤，为两党两国\n关系发展领航把舵，开启中朝友谊崭新篇章。中方愿同朝方一道，加强战略沟通，深化务实合作，密切协\n调配合，推动中朝关系不断向前发展，服务两国社会主义建设事业，为地区乃至世界和平稳定和发展繁荣\n作出积极贡献。"}, {"title": "近日，水利部办公厅印发《关于公布水预算管理第二批试点地区的通知》，在河北省、上海", "detail": "市、浙\n江省、山东省开展省域试点，在北京市通州区、黑龙江省大兴安岭地区、江西省景德镇市、重庆市大足区、\n新疆维吾尔自治区乌鲁木齐市开展市域试点，在辽宁省大连市长海县、福建省漳州市东山县、湖南省长沙\n市长沙县开展县域试点，进一步夯实水预算管理制度建设实践基础。"}, {"title": "故宫博物院建院100周年座谈会10月10日在北京举行。", "detail": "与会嘉宾认为，故宫是历史中国的独特象\n征，也是中华文明的重要标识。悠久的中华文化，让故宫积淀深厚、文脉绵长。"}, {"title": "截至10月9日，浙江11个地级市全部发布推行中小学春秋假制度的相关文件，标志着浙", "detail": "江成为全\n国首个在全省推行中小学春秋假制度的省份。"}, {"title": "当地时间10月10日，挪威诺贝尔委员会宣布，将2025年诺贝尔和平奖授予委内瑞拉", "detail": "反对派领袖马\n查多，以表彰她为促进委内瑞拉人民的民主权利所做的不懈努力。"}, {"title": "2025年10月11日10时20分，我国太原卫星发射中心在山东海阳附近海域使用引", "detail": "力一号遥二运载\n2\n(cid:3)\n火箭，将搭载的吉林一号宽幅02B07星、数天宇星01-02试验星顺利送入预定轨道，飞行试验任务获得圆\n满成功。引力一号是我国研制的全球最大固体运载火箭，此次任务是引力一号运载火箭的第2次飞行。"}, {"title": "国务院总理李强日前签署国务院令，公布《密云水库水源保护条例》，自2025年12月", "detail": "1日起施行。\n密云水库水源保护应当贯彻党和国家路线方针政策、决策部署，坚持保护优先、统筹保护与发展，坚持源\n头控制、系统治理，强化区域协同联动，实现水源保护、绿色发展、民生改善相统一，并与全面提升密云\n水库流域防洪等防灾减灾救灾能力相结合。"}, {"title": "10月10日-12日，第十一届世界自由区组织大会在海南海口举办，这是全球自由区领", "detail": "域的权威机\n构首次在中国办会，超过900名全球及地区商业领袖、自由区官员以及来自众多国际组织的代表出席。本\n届大会主题为“自由区：通向全球繁荣、贸易和可持续创新的大门”。"}, {"title": "民政部近日公布了新修订的《慈善组织信息公开办法》，将自2026年1月1日起施行。", "detail": "办法增加了\n慈善组织信息公开内容，明确具有公开募捐资格的慈善组织，应当在公开募捐活动结束后3个月内，对外\n公开对公开募捐合作方的评估和指导监督情况等信息。"}, {"title": "工业和信息化部、人力资源社会保障部、商务部等七部门日前印发《深入推动服务型制造创", "detail": "新发展\n实施方案（2025—2028年）》，提出到2028年，服务型制造在制造业高质量发展中的作用进一步增强，完\n成20项标准制定，打造50个领军品牌，建设100个创新发展高地。"}, {"title": "今年10月是第16个全国“敬老月”，近日，2025年全国“敬老月”活动启动，本次", "detail": "全国“敬老月”\n以“弘扬孝亲敬老美德、共建老年友好社会”为主题，部署开展了系列敬老爱老助老活动。"}, {"title": "10月12日晚，大阪世博会中国馆在世博会颁奖典礼上荣获国际展览局颁发的世博会大型", "detail": "自建馆展\n示类金奖。这是中国在海外参加综合类世博会首次获得金奖，也是中国贸促会自1982年代表中国政府组织\n中国馆参加海外世博会以来，连续五次获得世博会重要奖项。"}, {"title": "10月13日上午，全球妇女峰会开幕式在北京举行。", "detail": "峰会的主题是“命运与共：加速妇女全面发展\n新进程”。"}, {"title": "10月13日上午，国家主席习近平在北京出席全球妇女峰会开幕式并发表主旨讲话。", "detail": "习近平指出，\n妇女是人类文明的重要创造者、推动者、传承者，推进妇女事业发展是国际社会的共同责任。30年前，北\n京世妇会确立“以行动谋求平等、发展与和平”的崇高目标，通过了具有里程碑意义的《北京宣言》和《行\n动纲领》，将性别平等刻入时代议程，激励全世界的人们为之接续奋斗。\n习近平强调，展望未来，各方要重温北京世妇会初心，为加速妇女全面发展新进程凝聚更广泛共识、\n开辟更广阔道路、采取更务实行动。习近平提出4点建议：第一，共同营造有利于妇女成长发展的良好环\n境。第二，共同培育推动妇女事业高质量发展的强劲动能。第三，共同构建保障妇女权益的治理格局。第\n四，共同书写促进全球妇女合作的崭新篇章。"}, {"title": "当地时间10月13日，瑞典皇家科学院宣布，将2025年诺贝尔经济学奖授予乔尔·莫", "detail": "基尔、菲利普·阿\n吉翁和彼得·豪伊特，以表彰他们对创新驱动经济增长理论的阐释。"}, {"title": "2025年10月13日18时00分，我国在酒泉卫星发射中心使用长征二号丁运载火箭", "detail": "，成功将试验三\n十一号卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。试验三十一号卫星主要用于开展\n新型光学成像技术验证。"}, {"title": "10月13日，2025年世界工程组织联合会全体大会在上海开幕。", "detail": "本次大会以“工程塑造绿色未来”\n为主题，由中外政府官员、工程组织代表、科技人员和企业负责人等约760人参加了开幕式。"}, {"title": "10月13日上午，2025中国（河南）—东盟粮农合作发展大会暨第四届“一带一路”", "detail": "（河南）国际\n3\n(cid:3)\n农业合作博览会在郑州开幕。本次大会以“数智赋能粮农合作，创新驱动区域发展”为主题，聚焦粮食安\n全、智慧农业和农产品贸易三大核心领域，旨在推动河南与东盟国家在农业科技、产业投资和可持续发展\n方面的深度合作。河南生产了全国1/10的粮食、超过1/4的小麦，粮食总产量连续8年稳定在1300亿斤以\n上，被誉为“中原粮仓”“国人厨房”。"}, {"title": "10月13日，2025世界农业科技创新大会在北京市平谷区开幕。", "detail": "大会以“践行大食物观，共建韧性\n食物供应体系”为主题，来自90余个国家和地区的近800位涉农领域科学家、高校校长、教育家、企业家、\n优秀青年代表参会，共话农业科技发展趋势，共探农食行业挑战与发展路径，助力汇聚全球智慧，共筑韧\n性农食未来。"}, {"title": "“世界聚变能源集团”第2次部长级会议暨第30届聚变能国际大会10月14日在四川成", "detail": "都开幕，世\n界聚变能源集团第2次部长级会议主题为“聚变能：清洁能源未来”，来自27个国家、6个国际组织的约\n150人参加会议。"}, {"title": "10月14日，第二届世界中国学大会在上海开幕。", "detail": "本届大会以“世界视野下的历史中国与当代中国”\n为主题，会上发布了《文明互鉴与世界中国学繁荣发展：上海倡议》。来自50多个国家和地区的约500位\n嘉宾与会。"}, {"title": "10月15日，全球首座吊装能力突破三千吨级的全直流供电风电安装船——“北欧之风”", "detail": "号在山东\n烟台交付，填补了全球超大型全直流风电安装船的技术空白。"}, {"title": "10月15日，国务院以“强化标准引领保障作用，以标准升级促进经济高质量发展”为主", "detail": "题，进行\n第十六次专题学习。李强强调，要强化标准实施，坚持严格监督和优化服务并举，用好检验检测、认证认\n可等手段推动标准实施，建立强制性标准实施责任清单，注重在产业政策、政府采购、招投标中引用推荐\n性标准，引导企业执行高水平标准。更多公考资料，请加客服微信：jdgk101"}, {"title": "10月16日出版的第20期《求是》杂志将发表习近平的重要文章《推动落实全球发展倡", "detail": "议、全球安\n全倡议、全球文明倡议、全球治理倡议》。文章强调，当今世界，和平赤字、发展赤字、安全赤字、治理\n赤字有增无减。提出构建人类命运共同体和全球发展倡议、全球安全倡议、全球文明倡议等，就是为了破\n解上述赤字，推动建设一个更加美好的世界，为各国人民创造更加美好的生活。\n文章指出，今年是世界反法西斯战争胜利和联合国成立80周年，是铭记历史、共创未来的重要时刻。\n历史告诉我们，越是困难时刻，越要秉持和平共处的初心，坚定合作共赢的信心，坚持在历史前进的逻辑\n中前进、在时代发展的潮流中发展。为此，中方提出全球治理倡议，同各国一道，推动构建更加公正合理\n的全球治理体系，携手迈向人类命运共同体。第一，奉行主权平等。第二，遵守国际法治。第三，践行多\n边主义。第四，倡导以人为本。第五，注重行动导向。"}, {"title": "10月15日上午，2025中国—北欧经贸合作论坛在湖北武汉开幕。", "detail": "本届论坛以“支点湖北智链全球”\n为主题，汇聚30多个国家、200多家世界500强企业的代表和嘉宾，必将为深化中欧全面战略伙伴关系、\n建设开放型世界经济注入强劲动力。"}, {"title": "10月16日，第十四届中国艺术节开幕式在四川成都举行。", "detail": "本届中国艺术节以“艺动巴山蜀水共绘\n时代新篇”为主题，将于11月5日在重庆闭幕，整体活动持续至2025年底。"}, {"title": "10月16日，国家主席习近平向联合国粮食及农业组织成立80周年致贺信。", "detail": "习近平指出，联合国粮\n食及农业组织为保障世界粮食安全、推动乡村发展和粮食体系转型、提高各国人民生活水平发挥了重要作\n用。中国将一如既往支持联合国粮食及农业组织在国际粮农领域发挥重要作用，愿同国际社会携手落实全\n球发展倡议，推进联合国2030年可持续发展议程，推动构建人类命运共同体，为增进各国人民福祉作出新\n4\n(cid:3)\n的更大贡献。"}, {"title": "2025年10月16日9时33分，我国在海南商业航天发射场使用长征八号甲运载火箭", "detail": "，成功将卫星\n互联网低轨12组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。本次发射是长八甲火箭\n自今年首飞以来的第四次发射，也是长征系列火箭的第600次发射。"}, {"title": "10月16日上午，2025世界航海装备大会在福建省福州市开幕。", "detail": "本次大会延续“承载人类梦想驶向\n星辰大海”永久主题，设置“福海扬帆绿动领航”年度主题，主要活动包括开幕式、福建省海洋经济产业\n合作创新发展大会、福建省加快建设全国海洋经济发展示范区回顾与展望、航海装备大会论坛（主论坛）、\n海洋科创“五链融合”推进活动及13场分论坛，重点聚焦自然科学、海洋经济、产业创新、成果转化等领\n域方向。活动将持续至10月19日。"}, {"title": "10月16日，第十届中国国际版权博览会暨2025国际版权论坛在山东青岛开幕。", "detail": "本届版博会以“数\n智引领未来，版权创新发展”为主题，设置五大板块，规划场馆面积近5万平方米，共吸引57个展团、超\n1100家企业参展，集中展示全球版权领域数字化、智能化创新成果，搭建版权产品和服务展览交易国际化\n平台。"}, {"title": "10月15日，中国环境与发展国际合作委员会（简称国合会）2025年年会在北京开幕。", "detail": "本次年会的\n主题为“坚定全面绿色转型，促进人与自然和谐共生”。"}, {"title": "10月16日，我们迎来第45个世界粮食日。", "detail": "今年的主题是“手拉手共倡多样美食，聚合力同创美好\n未来”。目前我国人均粮食占有量达到500公斤，高于国际公认的人均400公斤粮食安全线，做到了谷物\n基本自给、口粮绝对安全。端牢饭碗，中国底气十足。"}, {"title": "全国首列氢能文旅列车“氢春号”10月16日在长春发布，这标志着我国氢能轨道交通技", "detail": "术取得重\n要突破。列车由中车长春轨道客车股份有限公司研制，属新能源轨道交通装备，内置氢能动力系统，实现\n零碳排放，运行时无需接触网，同时结合城市文旅特色，为现代城市交通出行提供绿色经济的定制化方案。"}, {"title": "国家铁路局于2025年10月16日正式开通运行12327全国铁路监督热线（简称1", "detail": "2327热线）。12327\n热线作为铁路服务监督专用电话号码，是政府监督热线，主要受理铁路行业安全、质量、市场秩序等方面\n的投诉举报、意见建议、政策咨询等事项。更多公考资料，请加客服微信：jdgk101"}, {"title": "10月16日上午，2025世界智能网联汽车大会在北京开幕。", "detail": "2025世界智能网联汽车大会以“汇智聚\n能网联无限”为主题，设有3场全体会议和3场特色会议，大会将围绕智能网联汽车产业的政策、技术、\n安全、人工智能、应用、数据等方向进行深度探讨。工业和信息化部有关负责人表示，大会还将组织一系\n列深化国际合作的活动。"}, {"title": "全球首个陆上商用模块式小型堆——中核集团海南昌江多用途模块式小型堆科技示范工程“", "detail": "玲龙一\n号”一回路冷态功能试验10月16日取得圆满成功。“玲龙一号”是全球首个通过国际原子能机构安全审\n查的陆上商用模块化小堆，是我国在核电自主创新上的重大突破。"}, {"title": "10月16日，青海350兆瓦塔式光热发电项目正式开工建设，这也是目前全球单机规模", "detail": "最大的光热\n发电项目。项目采用我国自主研发的塔式熔盐储能光热发电核心技术，由三座吸热塔和一台汽轮机组成，\n场区定日镜镜场总面积为330万平方米，是目前国内镜场反射面积最大的光热发电项目，计划于2027年9\n月底前全容量并网发电。"}, {"title": "第二十二届中国国际农产品交易会10月17日在天津开幕。", "detail": "本届农交会主题为“塑强品牌助振兴提\n振消费增活力”，吸引参展商近4000家，参展产品约2.5万种，新技术、新装备成为本届农交会的一大亮\n点。\n5\n(cid:3)"}, {"title": "10月17日，联合国旅游组织在浙江省湖州市举行“最佳旅游乡村”颁奖仪式。", "detail": "会上公布了2025年\n“最佳旅游乡村”名单，我国申报的贵州省黔东南苗族侗族自治州黎平县双江镇黄岗村、四川省甘孜藏族\n自治州丹巴县墨尔多山镇基卡依村、江苏省泰州市兴化市千垛镇东罗村、浙江省湖州市南浔区和孚镇荻港\n村等4个乡村入选。截至目前，我国入选总数达到19个。"}, {"title": "10月17日，长江干流乌东德、白鹤滩、溪洛渡、向家坝、三峡和葛洲坝六座电站构成的", "detail": "世界最大\n清洁能源走廊，多年累计发电量突破4万亿千瓦时。世界最大清洁能源走廊由乌东德、白鹤滩、溪洛渡、\n向家坝、三峡和葛洲坝六座大型电站构成，这一绿色走廊跨越1800公里，总装机容量达7169.5万千瓦，年\n均发电量约3000亿千瓦时，在推动全国电网互联互通、保障国家能源安全中发挥着积极作用。"}, {"title": "第三届“良渚论坛”10月18日上午在浙江省杭州市开幕。", "detail": "本届论坛的主题是“文明重光：文化遗\n产与人类文化多样性”。今年是中国加入《保护世界文化和自然遗产公约》40周年，联合国教科文组织《保\n护和促进文化表现形式多样性公约》通过20周年。本届论坛邀请了来自全球60余个国家和地区的文化遗\n产保护管理机构负责人、博物馆馆长、考古学家、历史学家等300余名中外嘉宾参加。"}, {"title": "中国互联网络信息中心10月18日发布《生成式人工智能应用发展报告（2025）》。", "detail": "报告显示，2025\n年上半年，国产生成式人工智能产品用户规模达5.15亿人，较2024年12月增长2.66亿人，用户规模半年\n翻番，普及率达36.5%。"}, {"title": "2025年10月19日11时33分，力箭一号遥八运载火箭在东风商业航天创新试验区", "detail": "发射升空，将搭\n载的巴基斯坦遥感卫星02星、中科卫星03星和04星共3颗卫星顺利送入预定轨道，飞行试验任务获得圆\n满成功。"}, {"title": "10月19日至20日，2025世界VR产业大会在江西南昌举行。", "detail": "本届大会以“VR让世界更精彩——VR+AI\n开启数智未来”为主题，聚焦“发布、研讨、对接、体验”四大核心环节，精心策划了16场活动。"}, {"title": "全球首个国际原子能机构（IAEA）聚变能研究与培训协作中心落地四川省成都市，标志", "detail": "着中国在聚\n变能源领域的国际地位与影响力实现显著跃升，将为成都建设全球聚变能源创新高地、推动可控核聚变商\n业化进程注入动能。"}, {"title": "近日，由中国工程院院刊《Engineering》评选的“2025全球十大工程成就", "detail": "”发布。“2025全球十\n大工程成就”分别是：抗体偶联药物、BlackwellGPU架构、DeepSeek开源大语言模型、全海深载人潜水器、\n高性能碳纤维复合材料、人形机器人、“毅力号”火星探测器、欧几里得空间望远镜、南水北调中线工程、\n塔克拉玛干沙漠锁边工程。"}, {"title": "由该天文台主导建设的全球首台太阳磁场精确测量中红外观测系统（AIMS望远镜）近日", "detail": "已通过国家\n验收并正式启用。该望远镜填补了国际中红外太阳磁场观测的空白。AIMS望远镜建设于青海冷湖赛什腾山\nD观测平台（海拔4000米），作为全球首台中红外波段太阳磁场专用观测设备，自2015年启动研制以来，\n实现了多项关键技术突破。科研团队通过12.3微米中红外波段观测，实现太阳磁场直接测量方法的突破，\n将磁场测量精度提升到优于10高斯量级，解决了太阳磁场测量百年历史中的一个瓶颈问题。"}, {"title": "10月17日至19日，2025中国国际数字经济博览会在河北石家庄举办，本届数博会", "detail": "以“可信数据赋\n能产业发展”为主题，本届数博会围绕“一会、一展、一交流、一大赛”构建多层次、立体化活动体系，\n内容丰富多彩。共启用数字产业生态馆（主场馆）、数字区域发展馆、数字生活应用馆、国际跨境贸易与\n数字发明创新馆4大展馆和1个室外数字未来体验区，总展览面积超5万平方米。"}, {"title": "10月19日晚，第十五届中国音乐金钟奖在四川成都开幕，本届金钟奖以“时代金钟·华", "detail": "彩乐章”\n为主题，在为期11天的赛程中，将开展6个项目的复赛、半决赛、决赛，以及专场音乐会、惠民演出等，\n6\n(cid:3)\n总计80余场赛事及配套活动。中国音乐金钟奖是经中共中央批准设立、全国唯一常设的音乐综合性大奖。"}, {"title": "国家统计局10月20日发布数据显示，初步核算，2025年前三季度中国国内生产总值", "detail": "（GDP）1015036\n亿元，按不变价格计算，同比增长5.2%。"}, {"title": "住房城乡建设部等9部门近日联合发布贯彻落实《中共中央办公厅、国务院办公厅关于推进", "detail": "新型城\n市基础设施建设打造韧性城市的意见》行动方案（2025—2027年），推进数字化、网络化、智能化新型城\n市基础设施建设，增强城市风险防控和治理能力。行动方案明确，探索推动新一代信息技术与城市基础设\n施建设深度融合，进一步夯实城市治理数字底座，筑牢城市安全新防线，创新城市民生服务新模式，培育\n经济发展新动能，推动城市安全发展，助力宜居、韧性、智慧城市建设。到2027年年底前，新型城市基础\n设施建设各项重点任务取得明显进展，形成一批可复制可推广的经验做法。"}, {"title": "国家林草局近日发布通知，将山西省山阴县桑干河等22处湿地列入国家重要湿地名录。", "detail": "至此，我国\n国家重要湿地已达80处。近年来，我国持续推进湿地保护修复，组织实施湿地保护修复项目3700多个，\n新增和修复湿地100多万公顷。全国共指定国际重要湿地82处、认证国际湿地城市22个、认定80处国家\n重要湿地和1205处省级重要湿地，初步构建起湿地分级管理体系。"}, {"title": "10月21日，第23届中国国际人才交流大会开幕，此次大会以“聚天下英才、谋合作共", "detail": "赢”为主题，\n由人力资源社会保障部（国家外国专家局）和上海市人民政府联合主办，来自110多个国家和地区的2600\n多名外国专家出席开幕式。更多公考资料，请加客服微信：jdgk101"}, {"title": "当地时间10月21日，在日本参议院首相指名选举第二轮投票中，自民党总裁高市早苗获", "detail": "得125票，\n在投票中胜出，当选日本第104任首相，也是日本历史上首位女首相。日本自民党和维新会联合政权正式\n成立。"}, {"title": "中国海油近期宣布，中国首个海上二氧化碳封存示范项目——恩平15-1油田碳封存项目", "detail": "累计封存\n二氧化碳突破1亿立方米。恩平15-1油田作为中国南海东部首个高含二氧化碳的油田，若按常规模式开发，\n二氧化碳将随原油一起被采出地面，不仅对海上平台设施和海底管线造成腐蚀，还将逸散至大气，增加二\n氧化碳排放量。"}, {"title": "我国科学家在对嫦娥六号2克月壤样品的科学分析中，识别出来自CI型碳质球粒陨石的撞", "detail": "击残留物，\n而此前在月球样品中检测到的具有正氧同位素特征的水，很可能来自这类陨石的撞击贡献。"}, {"title": "2025年度邵逸夫奖颁奖典礼10月21日在香港会展中心举行。", "detail": "4位科学家分获天文学、生命科学与\n医学、数学科学3个奖项，每项奖金120万美元。天文学奖颁予加拿大理论天体物理研究所教授兼多伦多\n大学教授约翰·理查德·邦德，以及英国剑桥大学天体物理学教授乔治·埃夫斯塔西奥乌；生命科学与医\n学奖颁予德国马克斯·普朗克生物化学研究所荣休所长暨科学会员沃尔夫冈·鲍迈斯特；数学科学奖颁予\n中国北京雁栖湖应用数学研究院兼清华大学丘成桐数学科学中心教授深谷贤治。邵逸夫奖于2002年创立，\n2004年首次颁发，由邵逸夫奖基金会管理及执行。该奖设有3个奖项，分别为天文学、生命科学与医学、\n数学科学，每年颁发一次。"}, {"title": "水利部10月22日发布消息，通过严格监管，“十四五”时期，全国用水总量控制在60", "detail": "00亿立方米\n以内，有力支撑了经济社会高质量发展。"}, {"title": "10月21日至22日，2025中国—东盟环境合作论坛在广西北海市举办。", "detail": "本次论坛主题为“共创绿色\n发展机遇，共筑繁荣美丽家园”，重点围绕气候韧性城市建设、生物多样性保护、绿色价值链构建、循环\n经济与绿色金融、科技创新合作等议题开展深入研讨，共同探寻契合区域发展特点的可持续发展路径。"}, {"title": "据中国政府网消息，国务院同意自2026年起，将每年4月第四周设立为“全民阅读活动", "detail": "周”。\n7\n(cid:3)"}, {"title": "中国共产党第二十届中央委员会第四次全体会议，于2025年10月20日至23日在北", "detail": "京举行。全会\n听取和讨论了习近平受中央政治局委托所作的工作报告，审议通过了《中共中央关于制定国民经济和社会\n发展第十五个五年规划的建议》。\n全会指出，实现社会主义现代化是一个阶梯式递进、不断发展进步的历史过程，需要不懈努力、接续\n奋斗。“十五五”时期是基本实现社会主义现代化夯实基础、全面发力的关键时期，在基本实现社会主义\n现代化进程中具有承前启后的重要地位。“十五五”时期我国发展环境面临深刻复杂变化，我国发展处于\n战略机遇和风险挑战并存、不确定难预料因素增多的时期。我国经济基础稳、优势多、韧性强、潜能大，\n长期向好的支撑条件和基本趋势没有变，中国特色社会主义制度优势、超大规模市场优势、完整产业体系\n优势、丰富人才资源优势更加彰显。"}, {"title": "10月23日，由广船国际建造的我国首艘自研大型出口双燃料客滚船在广州南沙交付。", "detail": "今天交付的\n双燃料客滚船可使用燃油和更清洁的液化天然气作为动力，具备完全自主知识产权。"}, {"title": "10月23日从国铁集团获悉，2025年前三季度，国家铁路累计发送货物30.3亿吨", "detail": "，同比增长3.4%。\n物流产品持续优化升级，助力降低全社会物流成本。"}, {"title": "“十四五”期间，我国水利建设实现跨越式发展，完成投资首次迈上万亿元大台阶，并连续", "detail": "3年突\n破历史纪录，建设了一大批水源工程、调水工程、灌区工程，水利工程供水能力达到9000亿立方米，“南\n北调配、东西互济”的水资源配置格局加快形成。预计“十四五”末，国家水网覆盖率达80.3%。"}, {"title": "10月23日，2025中国计算机大会在黑龙江省哈尔滨市开幕。", "detail": "本届大会以“数智赋能，无限可能”\n为主题，旨在探讨数字智能技术的前沿进展与未来趋势，推动计算技术与经济社会深度融合。"}, {"title": "2025年10月23日22时30分，我国在文昌航天发射场使用长征五号运载火箭，成", "detail": "功将通信技术试\n验卫星二十号发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。该卫星主要用于开展多频段、\n高速率卫星通信技术验证。"}, {"title": "十四届全国人大常委会第十八次会议10月24日经表决，通过了关于设立台湾光复纪念日", "detail": "的决定，\n以法律形式将10月25日设立为台湾光复纪念日，并规定国家通过多种形式举行纪念活动。"}, {"title": "二十届四中全会指出，“十五五”时期经济社会发展必须遵循以下原则，坚持党的全面领导", "detail": "，坚持\n人民至上，坚持高质量发展，坚持全面深化改革，坚持有效市场和有为政府相结合，坚持统筹发展和安全。"}, {"title": "10月24日，2025国际能源变革论坛在江苏省苏州市开幕。", "detail": "论坛以“十年携手能源变革创新领航\n绿色未来”为主题。论坛期间，发布了《全球能源低碳转型发展2030苏州愿景》、中国能源好物及《能源\n变革指数蓝皮书2025》等系列成果，发起成立国际零碳零废城市发展联盟，并举办了《新时代的中国能源\n变革路》主题展览，全方位展示了我国能源转型取得的历史性成就及能源领域的技术创新、应用实践和国\n际合作成果等，为推动全球清洁能源务实合作奠定了坚实基础。"}, {"title": "10月24日，中共中央政治局常委、国务院总理李强主持召开国务院“十五五”规划《纲", "detail": "要草案》\n编制工作领导小组会议并作讲话。李强指出，要创新思路、务求实效，高质量编制规划纲要，进一步明确\n“十五五”发展的施工图、路线图，谋划提出务实管用的发展载体和工作抓手。要培育壮大高质量发展新\n动能，围绕成长性强、牵引性强的领域打造一批新产业新赛道。要坚持扩大内需这个战略基点，充分挖掘\n强大国内市场的潜力。"}, {"title": "10月25日，纪念台湾光复80周年大会在北京召开。", "detail": "王沪宁表示，抗战胜利、台湾光复是全民族的\n伟大胜利，是中国人民和中华民族共同的伟大荣光。党和国家设立“台湾光复纪念日”，展示了全国各族\n人民坚持一个中国原则、捍卫国家主权和领土完整的坚定立场，反映了包括台湾同胞在内的海内外中华儿\n8\n(cid:3)\n女的共同愿望，彰显了中国共产党坚定不移担当历史任务、矢志不渝实现祖国完全统一的坚强意志，巩固\n了国际社会坚持世界上只有一个中国、台湾是中国不可分割一部分的普遍共识，必将激励两岸同胞继承和\n发扬爱国主义传统、伟大抗战精神，为实现祖国完全统一、中华民族伟大复兴而共同奋斗。"}, {"title": "10月25日，2025世界顶尖科学家论坛开幕式暨2025世界顶尖科学家协会奖颁奖", "detail": "典礼在上海临港中\n心举行。本届顶科论坛以“未来科学：上海与世界(ScienceinFuture)”为主题。论坛聚焦全球科技前沿，\n共同探讨基于未来科学的基础研究、技术突破、融合创新、国际合作、科技治理、道德伦理等重大课题，\n进一步搭建全球顶尖科学家思想碰撞的平台，为培育新质生产力、应对人类共同挑战提供科学方案与行动\n路径。更多公考资料，请加客服微信：jdgk101"}, {"title": "二十届四中全会提出了“十五五”时期经济社会发展的主要目标：高质量发展取得显著成效", "detail": "，科技\n自立自强水平大幅提高，进一步全面深化改革取得新突破，社会文明程度明显提升，人民生活品质不断提\n高，美丽中国建设取得新的重大进展，国家安全屏障更加巩固。在此基础上再奋斗五年，到二〇三五年实\n现我国经济实力、科技实力、国防实力、综合国力和国际影响力大幅跃升，人均国内生产总值达到中等发\n达国家水平，人民生活更加幸福美好，基本实现社会主义现代化。"}, {"title": "10月25日，2025世界青年科学家峰会（简称“青科会”）全体大会在浙江省温州市", "detail": "举行，来自47\n个国家和地区、70余家国际科技组织的近800名科学家、创投家、企业家等代表参会。本届大会为刘颖俊\n（中国）、玛丽安杰拉·鲁索（意大利）、沃尔夫冈·特雷斯（德国）、王辉（中国）等4位青年科学家\n颁发了可持续发展青年科学家奖。"}, {"title": "10月26日11时55分，我国在西昌卫星发射中心使用长征三号乙运载火箭，成功将高", "detail": "分十四号02\n星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。高分十四号02星可高效获取全球范围高精\n度立体影像，测制大比例尺数字地形图，生产数字高程模型、数字表面模型和数字正射影像图等产品，为\n国民经济和国防建设提供基础地理信息保障。"}, {"title": "10月26日，2025世界城市日城市可持续发展全球大会在上海世界会客厅开幕，本届", "detail": "大会主题为“创\n新发展，共建以人为本的智慧城市”。"}, {"title": "当地时间10月26日，在第47届东盟峰会召开期间，东帝汶正式成为东盟第11个成员", "detail": "国。其中十\n个成员国分别是：文莱、柬埔寨、印度尼西亚、老挝、马来西亚、菲律宾、新加坡、泰国、缅甸、越南。"}, {"title": "二十届四中全会提出，建设现代化产业体系，巩固壮大实体经济根基。", "detail": "坚持把发展经济的着力点放\n在实体经济上，坚持智能化、绿色化、融合化方向，加快建设制造强国、质量强国、航天强国、交通强国、\n网络强国，保持制造业合理比重，构建以先进制造业为骨干的现代化产业体系。"}, {"title": "10月26日，国务院关于2024年度国有资产管理情况的综合报告提请十四届全国人大", "detail": "常委会第十八\n次会议审议，国有资产最新“家底”公布。截至2024年末，全国国有企业（不含金融企业）资产总额401.7\n万亿元、国有资本权益109.4万亿元。国有金融企业资产总额487.9万亿元、国有金融资本权益33.9万亿\n元。"}, {"title": "10月26日，第三届全国博士后创新创业大赛在福建泉州开幕，本次大赛以“博创引领四", "detail": "十载、智\n汇赋能向未来”为主题，设置创新赛、创业赛、海外境外（“一带一路”）赛和揭榜领题赛等四个组别，\n新一代信息技术与人工智能、高端装备制造与机器人、新能源与节能环保等七大赛道，共吸引8006个项目、"}, {"title": "6万人参赛。", "detail": ""}, {"title": "当地时间10月27日，国务院总理李强在马来西亚吉隆坡出席第20届东亚峰会。", "detail": "李强指出，中方愿\n同各方坚守东亚峰会的初心，围绕全球治理倡议积极行动，共同努力为地区和平与发展注入更多正能量。\n9\n(cid:3)\n一是持续凝聚广泛共识。二是着力解决突出问题。三是改革完善规则体系。"}, {"title": "当地时间10月27日，国务院总理李强在马来西亚吉隆坡出席第28次东盟与中日韩领导", "detail": "人会议。李\n强指出，东亚奇迹不是过去时，而是进行时。中方愿同各方加强发展战略对接，坚持开放合作，持续释放\n经济潜力，开拓更广阔发展空间。一是营造有利于地区发展的良好环境。二是深化产业链供应链协同合作。\n三是共同培育壮大发展新动能。"}, {"title": "2025金融街论坛年会10月27日在北京开幕，本届年会以“创新、变革、重塑下的全", "detail": "球金融发展”\n为主题。"}, {"title": "当地时间10月28日，国务院总理李强在马来西亚吉隆坡出席第28次中国－东盟领导人", "detail": "会议。李强\n指出，中国愿同东盟国家加强发展战略对接，落实好《中国－东盟全面战略伙伴关系行动计划（2026－\n2030）》，继续推动构建更为紧密的中国－东盟命运共同体。一是让战略互信更加坚实。二是让利益融合\n更加深入。三是让情感联结更加牢固。"}, {"title": "十四届全国人大常委会第十八次会议10月28日表决通过了新修订的海商法，自2026", "detail": "年5月1日\n起施行。新修订的海商法共16章310条，积极适应航运贸易的最新发展趋势，合理借鉴最新海事国际公约\n的成果，有效平衡相关主体的利益诉求，对于推动我国航运和贸易高质量发展、加强海洋生态环境保护、\n更好推动高水平对外开放、建设海洋强国和航运强国具有重要意义。"}, {"title": "10月28日，中国－东盟自贸区3.0版升级议定书在马来西亚吉隆坡签署。", "detail": "中国－东盟自贸区3.0\n版升级共涵盖9个领域，包括数字经济、绿色经济、供应链互联互通、标准和技术法规与合格评定程序、\n卫生与植物卫生措施、海关程序和贸易便利化、竞争和消费者保护、中小微企业、经济技术合作。议定书\n签署后，双方将分别履行各自国内核准程序，推动议定书尽早生效实施。中国与东盟自2002年开启自贸区\n建设进程，2010年自贸区1.0版全面建成，2015年完成2.0版升级。"}, {"title": "10月28日，习近平关于《中共中央关于制定国民经济和社会发展第十五个五年规划的建", "detail": "议》的说\n明发布，习近平指出，在《建议》稿起草过程中，我们注意把握以下几点。一是坚持目标导向和问题导向；\n二是坚持系统思维；三是坚持进一步全面深化改革；四是坚持扩大对外开放。\n习近平强调，科学设定发展目标，对制定和实施好五年规划至关重要。《建议》稿把握“十五五”时\n期基本定位和阶段性要求，明确了经济社会发展的主要目标。2035年基本实现社会主义现代化，一个重要\n标志性指标就是人均国内生产总值达到中等发达国家水平，这要求“十五五”时期经济社会发展保持适当\n速度。"}, {"title": "10月27日上午，第七届中美友城大会在浙江杭州开幕。", "detail": "第七届中美友城大会以“更紧密的合作可\n持续的未来”为主题，下设“教育交流”“城市创新发展”“可持续发展的城市实践”“更紧密的中美友\n城合作：中美友城合作优秀案例分享”等四个分议题。"}, {"title": "10月28日，2025中国海洋经济博览会在深圳开幕，为期3天。", "detail": "本届中国海博会以“数智深蓝共\n创未来”为主题，展览面积超4万平方米，汇聚超200家全球领先的海洋科技企业与机构，集中展示海洋\n智能装备、海洋电子信息及数据、深海科技、滨海旅游、海洋现代服务业及海洋能源等领域的科技创新成\n果，举办系列高端论坛，打造集展览、论坛、发布与合作于一体的国家级海洋盛会。"}, {"title": "10月28日发布的《中共中央关于制定国民经济和社会发展第十五个五年规划的建议》提", "detail": "出，要“推\n动量子科技、生物制造、氢能和核聚变能、脑机接口、具身智能、第六代移动通信等成为新的经济增长点”。"}, {"title": "国家统计局10月29日发布数据显示，2024年中国创新指数为174.2，比上年增", "detail": "长5.3%，保持稳步\n增长态势。\n10\n(cid:3)"}, {"title": "10月29日，2025中国品牌论坛在河北雄安新区举行，本届论坛的主题为“向新而行", "detail": "丨新品牌新\n场景新实践新高地”。论坛设主论坛和“2025金融高质量发展报告会”“推动教育高质量发展主题研讨\n会”2个平行分论坛，论坛后还将组织“现代化城市治理的雄安实践”主题采访活动。"}, {"title": "第四届中国IPv6创新发展大会10月29日发布了《中国IPv6发展报告（2025", "detail": "）》，报告显示，截\n至2025年9月，我国IPv6活跃用户数达8.65亿，相较于2017年的293万，增长了294倍，在网民中的占\n比从2017年的0.39%提升至77.02%，位居世界前列。更多公考资料，请加客服微信：jdgk101"}, {"title": "10月29日，以“四海同心祭始祖，共同富裕谱新篇”为主题的乙巳（2025）年中国", "detail": "仙都祭祀轩辕\n黄帝大典在缙云仙都黄帝祠宇举行。据介绍，缙云县黄帝祭祀在东晋时期就有文献记载。1998年，缙云县\n重建黄帝祠宇，恢复黄帝祭祀活动。2011年，“黄帝祭典（缙云轩辕祭典）”列入国家级非物质文化遗产。"}, {"title": "10月29日从人力资源社会保障部了解到，今年以来，我国进一步加大稳就业政策支持力", "detail": "度，面向\n重点群体就业精准施策。2025年1—9月，全国城镇新增就业1057万人，完成全年目标任务的88%，就业形\n势保持总体稳定。"}, {"title": "当地时间10月30日，国家主席习近平在韩国釜山同美国总统特朗普举行会晤。", "detail": "习近平指出，中美\n经贸关系近期经历曲折，也给双方带来一些启示。经贸应该继续成为中美关系的压舱石和推进器，而不是\n绊脚石和冲突点。双方应该算大账，多看合作带来的长远利益，而不应陷入相互报复的恶性循环。双方团\n队可以继续本着平等、尊重、互惠的原则谈下去，不断压缩问题清单，拉长合作清单。"}, {"title": "10月30日，神舟二十一号载人飞行任务新闻发布会在酒泉卫星发射中心举行，介绍神舟", "detail": "二十一号\n载人飞船计划于10月31日23时44分发射，乘组3名航天员集体亮相。飞行乘组由张陆、武飞、张洪章\n组成，张陆担任指令长，3名航天员分别为航天驾驶员、飞行工程师和载荷专家。航天员张陆执行过神舟十\n五号载人飞行任务，武飞和张洪章均来自于我国第三批航天员，是首次执行飞行任务。\n11\n(cid:3)"}]}, {"month": "2025年11月", "year": 2025, "items": [{"title": "10月29日从东方电气集团获悉，我国自主研制的26兆瓦级海上风电机组在山东东营成", "detail": "功并网发电，\n该机组一举刷新全球已并网风机的单机容量与叶轮直径两项纪录。此次并网发电的26兆瓦级海上风电机组，\n轮毂中心高度相当于50多层居民楼，设计叶轮直径超过310米，扫风面积超过10个半标准足球场，是目前\n全球单机容量最大、叶轮直径最长的海上风电机组，并且实现全国产化设计制造。"}, {"title": "10月30日，国家疾控局等七部门发出通知，经国务院同意，将人乳头瘤病毒疫苗也就是", "detail": "HPV疫苗\n纳入国家免疫规划，自2025年11月10日起，组织各地为2011年11月10日以后出生的满13周岁女孩免\n费接种2剂次双价HPV疫苗（间隔6个月）。"}, {"title": "当地时间10月31日上午，亚太经合组织第三十二次领导人非正式会议第一阶段会议在韩", "detail": "国庆州和白\n会议中心举行。国家主席习近平出席会议并发表题为《共建普惠包容的开放型亚太经济》的重要讲话。习\n近平在讲话中指出，亚太经合组织成立30多年来，引领亚太地区走在全球开放发展前列，助力亚太成为全\n球经济最具活力的地区。习近平提出5点建议。一是共同维护多边贸易体制。二是共同营造开放型区域经\n济环境。三是共同维护产业链供应链稳定畅通。四是共同推进贸易数字化绿色化。五是共同促进普惠包容\n发展。"}, {"title": "当地时间10月31日下午，国家主席习近平向在韩国庆州举行的亚太经合组织工商领导人", "detail": "峰会发表题\n为《发挥亚太引领作用共促世界发展繁荣》的书面演讲。习近平强调，中国始终是现行国际秩序的维护\n者、真正多边主义的践行者。中方倡导和平发展，反对国强必霸；倡导合作共赢，反对赢者通吃；倡导文\n明互鉴，反对文明冲突；倡导公道公正，反对强权政治。中国相继提出共建“一带一路”倡议和全球发展\n倡议、全球安全倡议、全球文明倡议、全球治理倡议，为解决当今世界突出问题贡献了中国智慧和中国方\n案。\n习近平指出，亚太经合组织因应经济全球化浪潮而创立，以促进贸易和投资自由化便利化、支持经济\n增长和繁荣为目标宗旨。各方应该重温初心，以更具活力和韧性的亚太合作为世界作出突出贡献。一是带\n头维护和平稳定。二是带头实行开放融通。三是带头坚持合作共赢。四是带头促进普惠包容。"}, {"title": "10月31日23时44分，搭载神舟二十一号载人飞船的长征二号F遥二十一运载火箭在", "detail": "酒泉卫星发射\n中心点火发射，张陆、武飞、张洪章三名航天员顺利进入中国空间站，两个航天员乘组完成中国航天史上\n第7次“太空会师”。神舟二十一号载人飞船入轨后，于北京时间2025年11月1日3时22分，成功对接\n于空间站天和核心舱前向端口，整个对接过程历时约3.5小时，创造了神舟飞船与空间站交会对接的最快纪\n录。"}, {"title": "10月31日从广东省公安厅、广东省交通运输厅获悉，“粤车南下”香港政策正式公布。", "detail": "“粤车南下”\n香港政策分为香港口岸停车场政策和粤车进入香港市区两项政策，第一批先开放4个城市（广州、珠海、\n江门、中山），半年后推广到全省其他地市。"}, {"title": "2025年世界城市日全球主场活动暨第三届全球可持续发展城市奖（上海奖）颁奖活动1", "detail": "0月31日在\n哥伦比亚首都波哥大举办。获得第三届全球可持续发展城市奖（上海奖）的5个城市是哥伦比亚波哥大、\n阿尔及利亚阿尔及尔、韩国仁川、沙特阿拉伯麦地那和芬兰埃斯波。在中国倡议下，第68届联合国大会2013\n年12月通过决议，决定自2014年起将每年的10月31日设为世界城市日。这是联合国首个以城市为主题的\n国际日，也是中国政府在联合国推动设立的首个国际日。今年世界城市日的主题为“以人为本的智慧城市”。"}, {"title": "10月31日，由联合国粮农组织主办的全球重要农业文化遗产授牌仪式在意大利首都罗马", "detail": "举行。此次\n活动是粮农组织成立80周年系列活动之一，为2023年以来新认定的全球重要农业文化遗产举办集中授牌\n1\n(cid:3)\n与交流。中国6项遗产获粮农组织授牌，分别为河北宽城传统板栗栽培系统、安徽铜陵白姜种植系统、浙\n江仙居古杨梅群复合种养系统、甘肃皋兰什川古梨园系统、浙江德清淡水珍珠复合养殖系统和福建福鼎白\n茶文化系统。截至目前，全球重要农业文化遗产总数共102项，其中，中国有25项，数量居世界首位。"}, {"title": "当地时间11月1日上午，国家主席习近平在韩国庆州出席亚太经合组织第三十二次领导人", "detail": "非正式会\n议第二阶段会议，并发表题为《共同开创可持续的美好明天》的重要讲话。亚太各经济体应该加强互利合\n作，把握新机遇，应对新挑战，共同开创可持续的美好明天。为此，我提3点建议。一是强化数智赋能，\n塑造亚太创新发展新优势。二是坚持绿色低碳，打造亚太可持续发展新范式。三是落实普惠共享，展现亚\n太包容发展新气象。"}, {"title": "当地时间11月1日上午，国家主席习近平出席亚太经合组织第三十二次领导人非正式会议", "detail": "东道主交\n接环节，宣布中方将于明年11月在广东省深圳市举办亚太经合组织第三十三次领导人非正式会议。习近平\n指出，深圳地处太平洋沿岸，几十年间从一个落后的小渔村发展成为现代化国际大都市，是中国人民创造\n的世界发展史上的一个奇迹，也是中国坚定不移奉行互利共赢开放战略的重要窗口。"}, {"title": "11月1日出版的第21期《求是》杂志将发表习近平的重要文章《关于〈中共中央关于制", "detail": "定国民经\n济和社会发展第十五个五年规划的建议〉的说明》。习近平指出，在《建议》稿起草过程中，我们注意把\n握以下几点。一是坚持目标导向和问题导向，二是坚持系统思维，三是坚持进一步全面深化改革，四是坚\n持扩大对外开放。\n《建议》稿把握“十五五”时期基本定位和阶段性要求，明确了经济社会发展的主要目标，提出经济\n增长保持在合理区间、全要素生产率稳步提升、经济增长潜力得到充分释放、居民收入增长和经济增长同\n步、劳动报酬提高和劳动生产率提高同步、中等收入群体持续扩大等重要目标。"}, {"title": "第十五届全国运动会火炬传递11月2日在香港、澳门、广州、深圳四个城市同步举行，这", "detail": "也是全运\n会火炬首次在香港和澳门传递。火炬传递结束后，四城火种于2日下午汇聚广州，在广东奥林匹克体育中\n心举行融火仪式，为9日晚开幕式主火炬点燃做准备。"}, {"title": "近日，从中国南水北调集团有限公司获悉：截至2025年10月，南水北调东中线一期工", "detail": "程累计向北\n方调水超830亿立方米，惠及沿线48座大中型城市1.95亿人，随着受水区配套工程完善，受益范围正由大\n中城市向农村拓展。目前南水北调中线一期工程总干渠输水损失率从设计值10%大幅优化至实际运行值3%\n左右。"}, {"title": "10月31日至11月2日，2025世界物联网博览会在江苏省无锡市举办。", "detail": "本届物博会以“万物智联无\n尽前沿”为主题，紧扣“人工智能与物联网双向赋能”主线，重点突出物联网的“全面感知”“泛在连接”\n两大核心能力，集中展示传感器向智能化、微型化、高端化的发展趋势。"}, {"title": "2025年11月3日11时47分,我国在文昌航天发射场使用长征七号改运载火箭，成", "detail": "功将遥感四十六\n号卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。遥感四十六号卫星主要用于防灾减灾、\n国土资源勘察、水利气象等领域。"}, {"title": "11月3日，第十八届中国—拉美企业家高峰会在河南郑州开幕，本届高峰会以“向新向智", "detail": "共赢未\n来”为主题，来自中国与拉美和加勒比国家的政府官员、工商界人士、专家学者以及国际组织代表等1000\n余人出席。"}, {"title": "第十八届世界华商大会11月3日在澳门开幕，第十八届世界华商大会由澳门中华总商会主", "detail": "办，会议\n期间，与会嘉宾将围绕“粤港澳大湾区未来”、“中医药创新发展”、“综合休闲产业与文旅会展经济”、\n“高新技术与现代金融”、“青年华商的成长之路”主题举办专题论坛，并组织商业洽谈和商业考察等活\n2\n(cid:3)\n动。"}, {"title": "近日，福建泉州、江苏无锡正式加入联合国教科文组织“创意城市网络”，分别成为其中的", "detail": "“美食\n之都”“音乐之都”。至此，网络中的中国城市达到20座，包括北京、上海、深圳等。此次共有58座城\n市加入，它们因其对创意产业和文化生活的积极承诺而获得认可。"}, {"title": "11月3日，第七届中法文化论坛在湖南长沙开幕。", "detail": "本届论坛以“多元共生与和谐共进——开辟中法\n文化交流新格局”为主题，设置了开幕式、主旨演讲、平行论坛、市长圆桌对话、闭幕式等环节，涵盖文\n化旅游与城市发展、人工智能与文化创新、艺术教育与人才交流、文博产业与文物保护等领域，旨在进一\n步促进中法两国文化在多元共生中相互借鉴、和谐共进，推动中法文化交流迈向新高度。"}, {"title": "11月3日，2025粤港澳大湾区全球招商大会在广州举行。", "detail": "大会以“投资大湾区，共创美好未来”为\n主题，由粤港澳三地政府联合举办，全面展现大湾区的经济活力、创新动力、区域魅力、投资潜力，为全\n球企业投资兴业搭建广阔平台。"}, {"title": "11月3日-4日，2025世界显示产业创新发展大会在成都举行，大会主题为“显示无", "detail": "处不在，AI点\n靓视界”，作为全球规格高、规模大、影响力广的新型显示产业领域盛会，在巩固以往三届成果的基础上，\n坚持世界眼光、国际标准和中国特色，正成为集行业交流、产业集聚、对接洽谈于一体的国际性平台。"}, {"title": "经过168小时满负荷试运行，位于浙江省宁波市的北仑电厂9号100万千瓦燃煤机组顺", "detail": "利投产。至\n此，北仑电厂的火电装机规模达到734万千瓦，预计年发电量超400亿千瓦时，成为我国装机规模最大的\n火电厂。"}, {"title": "11月4日上午，国务院安委会办公室、应急管理部、国家消防救援局在京举行2025年", "detail": "全国消防宣\n传月活动启动仪式。今年11月9日是第三十四个全国消防日，11月是全国消防宣传月，主题为“全民消防、\n生命至上——安全用火用电”。"}, {"title": "11月4日，第七届东亚峰会清洁能源论坛在福建福州开幕。", "detail": "本次论坛以“高水平互联推动高质量区\n域发展”为主题，聚焦落实东亚合作领导人系列会议共识，会期两天。"}, {"title": "11月5日，第八届中国国际进口博览会（简称“进博会”）在上海拉开帷幕。", "detail": "本届进博会展览面积\n超过36.7万平方米，参展企业在去年3496家的基础上新增了600余家，有290家世界500强和行业龙头企\n业参展，展览面积和企业总数均创历史新高。461项新产品、新技术、新服务将在第八届进博会集中亮相。"}, {"title": "11月5日，国务院总理李强在上海出席第八届中国国际进口博览会暨虹桥国际经济论坛开", "detail": "幕式，并\n发表主旨演讲。李强指出，进博会越办越好，很重要的是因为坚持“与天下同利”。李强同大家分享3点\n看法：一是坚持平等互利，夯实正当的共同利益基础。二是始终坚守道义，切实维护国际公平正义。三是\n推进治理改革，完善国际经贸规则体系。"}, {"title": "正在乌兹别克斯坦撒马尔罕进行的联合国教科文组织大会第43届会议当地时间11月5日", "detail": "审议通过\n决议，将每年3月21日（北半球春分日）设立为“国际太极拳日”。"}, {"title": "11月5日0时，横琴口岸合作智能快捷通道迎来首批旅客，琴澳实现“刷脸”智能通关。", "detail": "随着旅检\n大厅和随车人员验放厅的64条合作智能快捷通道正式启用，横琴口岸成为全国首个在合作快捷通道实现“刷\n脸”智能通关的口岸，标志着琴澳通关便利性再上新台阶。"}, {"title": "11月6日上午，习近平在海南省三亚市听取海南自由贸易港建设工作汇报。", "detail": "习近平指出，高标准建\n设海南自由贸易港，主要目的是促进海南高质量发展，助力全国构建新发展格局。要结合实际科学编制“十\n五五”规划，紧紧围绕建设“三区一中心”的战略定位，全面提高海南经济社会发展水平。着力打造具有\n海南特色和优势的现代化产业体系，推动主导产业优化升级，促进科技创新和产业创新深度融合，努力在\n3\n(cid:3)\n发展新质生产力上取得新突破。"}, {"title": "11月6日，第十二届中国－中亚合作论坛在新疆乌鲁木齐开幕。", "detail": "本届论坛以“弘扬‘中国－中亚精\n神’，推进共同现代化”为主题，发布《乌鲁木齐倡议》。"}, {"title": "11月6日上午，我国首座双层斜拉—悬索协作体系大桥——铜陵长江三桥正式通车，这也", "detail": "是长江安\n徽段第11座跨江大桥。铜陵长江三桥路线全长11.9公里。其中，公铁合建段长2.7公里，江北公路接线长"}, {"title": "8公里，江南公路接线长3.4公里，南北顺接既有G3京台高速公路，集高速公路、城际", "detail": "铁路、货运铁路于\n一体，并兼顾铁水联运功能，其中公路部分率先建成通车。"}, {"title": "《2025中国北斗产业发展指数报告》11月6日发布。", "detail": "数据显示，今年我国北斗产业综合指数为1579\n点，同比提升10.34%，对比2020年，北斗市场化、产业化和国际化相关指数增幅均超过60%。"}, {"title": "11月5日，我国第一艘电磁弹射型航空母舰福建舰入列授旗仪式在海南三亚某军港举行。", "detail": "福建舰是\n我国第一艘电磁弹射型航空母舰，也是我国第三艘航空母舰，舷号为“18”，2022年6月下水命名。福建\n舰由我国完全自主设计建造，其电磁弹射技术处于世界先进水平。"}, {"title": "2025年世界互联网大会乌镇峰会11月7日在浙江乌镇开幕。", "detail": "本届峰会以“共筑开放合作、安全普\n惠的数智未来——携手构建网络空间命运共同体”为主题，将围绕数字经济、文化遗产数字化保护与传承\n等议题举办24场分论坛。来自130多个国家和地区的1600多名嘉宾参会。"}, {"title": "近日，教育部等六部门印发了《关于加强新时代高校青年教师队伍建设的指导意见》，《指", "detail": "导意见》\n指出，要坚持党对教育事业的全面领导，落实立德树人根本任务，遵循高校青年教师成长发展规律，以教\n育家精神铸魂强师，强化高校青年教师全链条建设，全面提升青年教师思想政治素质、教育教学水平、科\n研创新能力、社会服务本领、国际化视野，强化思想政治引领、加强师德师风建设、提升服务战略能力、\n促进专业能力发展、提高管理服务水平，推动形成人才辈出、人尽其才、才尽其用的生动局面，为教育强\n国、科技强国、人才强国建设提供更为有力的师资保障。"}, {"title": "11月7日至8日，习近平近日在广东考察时强调，广东是改革开放的排头兵、先行地、实", "detail": "验区，要\n深入学习宣传贯彻党的二十届四中全会精神，科学谋划未来5年的目标、任务和举措，以全面深化改革开\n放推动高质量发展，久久为功推动粤港澳大湾区建设，纵深推进全面从严治党，不断取得现代化建设新成\n效。\n习近平强调，广东增创新优势、实现新突破，必须大力弘扬改革开放精神、特区精神，以全面深化改\n革开放推动高质量发展。要坚持有效市场和有为政府相结合，促进各种所有制经济优势互补、共同发展。"}, {"title": "国务院新闻办公室11月8日发布《碳达峰碳中和的中国行动》白皮书。", "detail": "白皮书说，节能是从源头减\n少碳排放的重要抓手，循环经济对碳减排具有重要促进作用，生态系统碳汇是实现减排固碳的重要途径。\n中国深入实施节能降碳增效行动、循环经济助力降碳行动、碳汇能力巩固提升行动，取得积极成效。"}, {"title": "《中国互联网发展报告2025》和《世界互联网发展报告2025》蓝皮书11月8日发", "detail": "布。《中国互联\n网发展报告2025》显示，一年来，我国人工智能技术持续突破，算力基础设施不断升级。我国已成为全球\n人工智能专利最大拥有国，占比达60%。"}, {"title": "近日，天问一号成功观测到来自太阳系以外的彗星——阿特拉斯。", "detail": "这是人类已知造访太阳系的第三\n颗星际天体，推测年龄约30亿—110亿年，这也是我国航天器首次观测到星际天体。"}, {"title": "11月8日，中国科协公开发布《中国科协2024年度统计简报》。", "detail": "全国科协系统由中国科协本级、\n地方科协以及各级科协的科技社团、科协基层组织组成。截至2024年12月底，全国共有科协组织12.9万\n个。\n4\n(cid:3)"}, {"title": "2025年11月9日05时01分，我国太原卫星发射中心在山东海阳附近海域使用长征", "detail": "十一号遥六运\n载火箭，成功将试验三十二号卫星01星、02星、03星发射升空，卫星顺利进入预定轨道。该卫星主要用于\n开展空间新技术试验。"}, {"title": "11月9日下午，国家主席习近平在广州白云国际会议中心会见来华出席第十五届全国运动", "detail": "会开幕式\n的国际奥委会主席考文垂和终身名誉主席巴赫。习近平指出，奥林匹克精神是人类文明的重要内容，寄托\n着各国人民对建设更美好世界的期盼，同中方推动构建人类命运共同体的愿景高度契合。中国始终是奥林\n匹克精神的坚定践行者、维护者、传播者。近年来，中国同国际奥委会在推进体育事业中相互支持，携手\n办成了很多大事好事。"}, {"title": "近日，国务院批复同意自然资源部审查通过的《成渝地区双城经济圈国土空间规划（202", "detail": "1—2035年）》。\n批复提出，到2035年，成渝地区双城经济圈耕地保有量不低于7417.58万亩，其中永久基本农田保护面积\n不低于6327.78万亩；生态保护红线面积不低于1.58万平方千米；城镇开发边界扩展倍数控制在基于2020\n年城镇建设用地规模的1.32倍以内；用水总量不超过国家下达指标。"}, {"title": "2025年11月9日11时32分，力箭一号遥九运载火箭在东风商业航天创新试验区发", "detail": "射升空，将搭\n载的楚天二号技术试验01星、02星顺利送入预定轨道，飞行试验任务获得圆满成功。此次任务是力箭一号\n运载火箭的第10次飞行，力箭一号已累计发射75颗卫星。\n更多公考资料，请加客服微信：1716271889845.11月9日上午，2025中国企业全球形象高峰论坛在安\n徽合肥举办。本次论坛以“科技引领智启未来”为主题，萨什科·纳塞夫、李智慧等发言，发布了中国企\n业国际形象建设优秀案例，举行了“科技国际传播中心”签约仪式。"}, {"title": "中华人民共和国第十五届运动会11月9日晚在广东省广州市隆重开幕。", "detail": "习近平出席开幕式并宣布运\n动会开幕。这是首次由粤港澳三地联合举办的全国运动会。以《圆梦未来》为主题的文体展演拉开序幕。\n整个演出由“同根同源”“同心同缘”“同梦同圆”3个篇章组成，创新运用体育元素、艺术手段和前沿科\n技，生动诠释了本届全运会“激情全运会，活力大湾区”的主题。"}, {"title": "被誉为“空中白鲸”的“祥云”AS700载人飞艇近日飞抵浙江省绍兴市越城区鉴水科技", "detail": "城，标志着\n华东地区首架AS700载人飞艇正式交付。AS700载人飞艇由中国航空工业集团特种飞行器研究所自主研制，\n是我国首个按适航规范研制、拥有完全自主知识产权的载人飞艇。"}, {"title": "11月10日10时41分，我国在海南商业航天发射场使用长征十二号运载火箭，成功将", "detail": "卫星互联网\n低轨13组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "以“大时代、大视野、大文学——文明新形态中的网络文学”为主题的2025中国网络文", "detail": "学论坛，11\n月10日在福建泉州启幕。论坛聚焦“创作”“出海”与“出版”三大议题，深入探讨网络文学的创作生态\n与传播趋势，呈现新时代中国网络文学的广泛影响。"}, {"title": "国务院办公厅印发的《关于进一步促进民间投资发展的若干措施》11月10日对外公布，", "detail": "提出进一\n步加大政府采购支持中小企业力度。对超过400万元的工程采购项目中适宜由中小企业提供的，严格按规\n定预留该部分采购项目预算总额的40%以上专门面向中小企业采购，鼓励地方政府结合实际进一步提高预\n留份额。鼓励采购单位将对民营企业的合同预付款比例提高至合同金额的30%以上。"}, {"title": "日前，工信部发布《关于进一步加快制造业中试平台体系化布局和高水平建设的通知》。", "detail": "其中提出，\n到2027年底，高水平中试平台力量进一步壮大，现代化中试平台体系基本建立，多主体参与、多领域布局、\n多层次服务的全国制造业中试服务网络初步形成。"}, {"title": "11月11日，以“文旅体融合·高品质生活”为主题的2025国际山地旅游暨户外运动", "detail": "大会在贵州省\n5\n(cid:3)\n贵阳市开幕。来自全球30个国家和地区的嘉宾齐聚一堂，共同为推动新时代山地旅游高质量发展、探索可\n持续发展新路径汇聚智慧、注入新动能。\n会上，国际山地旅游联盟年会现场公布了通过认定的第二批“世界旅游名山”名单。通过认定，中国-\n黄山、阿根廷-菲茨罗伊山、沙特阿拉伯-苏达山、中国-丹霞山、中国-瓦屋山、俄罗斯-别洛库里哈山脉、中\n国-雪峰山、中国-嶂石岩等8座名山入选第二批“世界旅游名山”。目前国际山地旅游联盟已在全球认定\n22座“世界旅游名山”。"}, {"title": "11月12日上午，国家主席习近平在北京人民大会堂会见来华进行国事访问的西班牙国王", "detail": "费利佩六\n世。习近平欢迎费利佩六世国王访华，指出中国和西班牙都有深厚的历史文化底蕴。建交50多年来，两国\n坚持从战略高度和长远角度看待和发展双边关系，相互尊重、相互支持、相互成就，树立了不同历史文化、\n不同社会制度国家友好相处、共谋发展的典范，也为推动全球开放合作、维护国际公平正义发挥了重要作\n用。"}, {"title": "11月12日，习近平向第二十次中越两党理论研讨会致贺信。", "detail": "习近平指出，中越两国是好邻居、好\n朋友、好同志、好伙伴，是具有战略意义的命运共同体。中越两党都坚持和发展马克思主义，都坚定不移\n走社会主义道路，都领导各自国家进行社会主义建设，面临许多相同或相似的时代课题。"}, {"title": "11月12日上午，2025中国新媒体大会在湖南长沙开幕。", "detail": "本届大会以“智能聚力系统变革”为主题，\n包括开幕式暨主论坛，内容创新论坛、财经传媒论坛、技术应用论坛、青年论坛、国际传播论坛、社会责\n任论坛、“新闻+”论坛等7场平行论坛，以及2025中国新媒体技术展、“强‘四力’促深融”专题培训\n班、“马栏山时间”文创活动、“马栏山新媒体之夜”沉浸式互动活动等6场主题活动。"}, {"title": "当地时间11月12日，世界知识产权组织发布年度报告《世界知识产权指标》。", "detail": "报告显示，2024年\n全球专利申请量实现连续五年增长，创下370万件历史新高，增幅达4.9%。中国以180万件专利申请蝉联\n全球第一，随后是美国（501831件）、日本（419132件）、韩国（295722件）和德国（133485件）。"}, {"title": "11月12日，2025世界动力电池大会在四川省宜宾市开幕。", "detail": "本次大会以“新视野·新生态·新机遇”\n为主题，突出科技创新引领、动力电池产业建圈强链、关联产业融合发展，将进一步促进机遇共享、优势\n互补、合作共赢，助力全球动力电池产业高质量发展。"}, {"title": "11月12日至13日，2025专精特新中小企业发展大会在重庆举行。", "detail": "大会以“专精特新培优育强”\n为主题，聚焦培育专精特新中小企业先进经验与实践案例，广泛汇聚专精特新“小巨人”企业、行业龙头\n企业、服务机构和金融机构等多方力量，将展开深度交流，分享真知灼见。截至目前，我国已累计培育专\n精特新“小巨人”企业超1.76万家，专精特新中小企业超14万家，科技和创新型中小企业超60万家，优\n质中小企业梯度培育工作稳步推进。"}, {"title": "近日，教育部等七部门联合印发《关于加强中小学科技教育的意见》，提出以科学、技术、", "detail": "工程、\n数学为重点，切实加强中小学科技教育，旨在夯实科技创新人才培育基础，助力高水平科技自立自强，支\n撑教育、科技、人才高质量一体化发展。"}, {"title": "11月14日上午，国家主席习近平在北京人民大会堂会见来华进行国事访问的泰国国王哇", "detail": "集拉隆功。\n习近平指出，中方愿同泰方加强战略对接，稳步推进中泰铁路等大项目合作，扩大进口泰国优质农产品，\n拓展人工智能、数字经济、航空航天等新兴领域合作，让两国人民从中泰合作中获得更多实利。要推动两\n国文化交融，促进人文交流，让两国民众越走越亲。中方愿积极支持泰国王室公益项目，加强减贫经验交\n流，助力泰国改善民生。"}, {"title": "11月14日，2025世界中文大会在北京开幕，全球语言学者、文化研究者和教育工作", "detail": "者齐聚一堂，\n6\n(cid:3)\n共同探讨中文的国际传播与未来发展。2025世界中文大会主题为“创新引领数智赋能——让中文零距离”。"}, {"title": "11月14日9时许，我国076两栖攻击舰首舰四川舰从上海沪东中华造船厂码头解缆启", "detail": "航，赴相关\n海域开展首次航行试验任务。这次海试将主要检测验证四川舰动力、电力等系统的可靠性和稳定性。经中\n央军委批准，076两栖攻击舰首舰命名为“中国人民解放军海军四川舰”，舷号为“51”。"}, {"title": "据中国载人航天工程办公室消息，北京时间2025年11月14日16时40分，神舟二", "detail": "十一号载人飞船\n返回舱在东风着陆场成功着陆。神舟二十号航天员陈冬、陈中瑞、王杰全部安全顺利出舱，健康状态良好。\n至此，神舟二十号航天员乘组的太空之旅顺利结束，陈冬成为首个在轨驻留时间超过400天的中国航天员，\n同时也是目前执行出舱任务次数最多的中国航天员。"}, {"title": "11月13日，2025年6G发展大会在北京经济技术开发区开幕。", "detail": "本届大会以“智联全球，共建6G技\n术创新生态”为主题，邀请两院院士、国内外权威专家、国际组织代表、知名企业家等，共同探讨6G应用\n需求、关键技术、国际标准、产业研发、试验验证等议题，推动6G技术及架构形成全球共识，维护全球统\n一的6G国际标准和产业生态。更多公考资料，请加客服微信：yumi9938"}, {"title": "11月14日，以“科技赋能产业融合共创未来”为主题的第二十七届中国国际高新技术成", "detail": "果交易会\n（简称“高交会”）在广东深圳正式开幕。本届高交会汇聚来自全球100多个国家和地区的5000多家知名\n企业及国际组织参展，5000余项代表全球科技前沿的新产品、新技术、新成果集中展示。"}, {"title": "11月14日，拥有7000个车位的液化天然气双燃料动力汽车运输船——“太平洋号”", "detail": "在山东烟台建\n造完工，这是我国首条符合新能源汽车海运国际新标准的汽车运输船。太平洋号总长199.9米，型宽38米，\n设计航速19节，最大运载能力达7000辆汽车。船舶配备两套液化天然气储罐及双燃料主机、辅机，在港\n口作业时可实现零排放，续航力最高可达15800海里，可覆盖全球主要汽车运输航线。"}, {"title": "第五届中国人口与发展论坛11月14日在北京举行。", "detail": "从论坛获悉，目前，我国每千人口拥有3岁以\n下婴幼儿托位数已达到4.73个，超额完成“十四五”规划提出的2025年每千人口托位数达到4.5个的目标。"}, {"title": "近日，国家主席习近平复信青年汉学家，勉励他们当好融通中外文明的使者。", "detail": "习近平强调，汉学源\n自中国、属于世界，是全人类共同的精神财富。希望你们继续与汉学结伴、和中国同行，加强研究阐释，\n向世界介绍真实、立体、全面的中国，当好融通中外文明的使者，为推动构建人类命运共同体贡献智慧和\n力量。"}, {"title": "11月15日晚，第38届中国电影金鸡奖颁奖典礼暨2025年中国金鸡百花电影节闭幕", "detail": "式在福建厦门举\n行，各大奖项逐一揭晓。《好东西》荣获本届金鸡奖最佳故事片奖，《志愿军：存亡之战》荣获本届金鸡\n奖评委会特别奖；演员易烊千玺凭借《小小的我》获得最佳男主角奖，宋佳凭借《好东西》获得最佳女主\n角奖。"}, {"title": "11月16日出版的第22期《求是》杂志将发表习近平的重要文章《因地制宜发展新质生", "detail": "产力》。文\n章强调，新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、高效能、\n高质量特征，符合新发展理念的先进生产力质态。它由技术革命性突破、生产要素创新性配置、产业深度\n转型升级而催生，以劳动者、劳动资料、劳动对象及其优化组合的跃升为基本内涵，以全要素生产率大幅\n提升为核心标志，特点是创新，关键在质优，本质是先进生产力。\n文章指出，科技创新和产业创新，是发展新质生产力的基本路径。科技创新能够催生新产业、新模式、\n新动能，是发展新质生产力的核心要素。抓科技创新，要着眼建设现代化产业体系，既多出科技成果，又\n把科技成果转化为实实在在的生产力。抓产业创新，要守牢实体经济这个根基，坚持推动传统产业改造升\n级和开辟战略性新兴产业、未来产业新赛道并重。抓科技创新和产业创新融合，要搭建平台、健全体制机\n7\n(cid:3)\n制，强化企业创新主体地位，让创新链和产业链无缝对接。"}, {"title": "第十七届海峡两岸茶业博览会11月16日在福建省武夷山市举行。", "detail": "本届茶博会共吸引850多家企业\n参展，其中来自台湾的企业173家。本届茶博会以“‘三茶’统筹·融合发展”为主题，设置展位2300个，\n展览面积4.8万平方米。"}, {"title": "近日，从中国电信量子研究院获悉，搭载“祖冲之三号”同款芯片的超导量子计算机“天衍", "detail": "-287”\n已完成搭建。该量子计算系统具备“量子计算优越性”能力，处理特定问题的速度比目前最快的超级计算\n机快4.5亿倍，未来将接入“天衍”量子计算云平台并首次面向全球开放应用服务。这将是我国首个具备“量\n子计算优越性”的量子计算云平台，标志着我国在推动量子计算实用化道路上迈出重要一步。"}, {"title": "11月17日，位于西藏山南的琼结风电项目正式并网发电。", "detail": "项目风机点位最高海拔5370米，投产后\n成为我国在运行的海拔最高风电场。琼结风电项目总装机60兆瓦，共安装12台风电机组，单台机组装机\n容量为西藏最大。"}, {"title": "近日，多部门联合印发《关于加快建设现代化国有林场的意见》。", "detail": "《意见》提出力争到2030年，国\n有林场管理体制进一步完善，单位面积森林蓄积量提高约5%，初步建成资源质量优良、生态功能稳定、产\n业发展充分的现代化国有林场体系。"}, {"title": "近日，南京大学固体微结构物理全国重点实验室陈延峰教授团队与山东大学晶体材料全国重", "detail": "点实验\n室于浩海教授团队合作，在国际上首次实现电子、声子和光子三种基本粒子的高效耦合，并首次发现“三\n位一体”新型准粒子，这是中国科学家发现的第二个声子相关准粒子。"}, {"title": "据最新发布的英国《自然》杂志增刊《2024自然指数-科研城市》显示，中国城市首次", "detail": "占据全球科研\n城市十强榜单一半以上席位，北京蝉联2016年以来全球科研城市榜首的位置。"}, {"title": "11月17日，2025中国—东盟周在福建福州开幕。", "detail": "此次活动主题为“命运与共：联结东盟2045愿景\n与中国式现代化”，共安排高端主题对话会、中国—东盟青年海洋合作圆桌会、2025中国—东盟经贸合作\n新机遇对接会等多场主体及配套活动。"}, {"title": "11月17日，2025首届商业航天标准化学术交流会在海南海口举行。", "detail": "会上，中国航天标准化与产品\n保证研究院发布我国首个商业航天标准化智能服务平台“天钧”，这标志着我国航天标准化事业进入数字\n智能时代。"}, {"title": "11月18日，第二十届中国经济论坛在广东省广州市举行。", "detail": "本届论坛的主题为“中国式现代化与‘十\n五五’中国经济展望”，设主论坛和“全球经贸新格局：出海的机遇与挑战”“规则衔接机制对接：推进\n大湾区市场一体化”“向海图强：海洋经济新展望”等9个平行论坛，论坛前还组织了相关主题调研活动。"}, {"title": "第二届中欧班列国际合作论坛11月18日在陕西西安开幕。", "detail": "本届中欧班列国际合作论坛主题为“联\n通亚欧，共享未来”。国内外专家学者、企业家、政府官员和国际组织代表等约450人参加开幕式。"}, {"title": "习近平近日对全面依法治国工作作出重要指示指出，新征程上，要全面贯彻新时代中国特色", "detail": "社会主\n义法治思想，坚持党的领导、人民当家作主、依法治国有机统一，聚焦建设更加完善的中国特色社会主义\n法治体系、建设更高水平的社会主义法治国家，更加注重法治与改革、发展、稳定相协同，更加注重保障\n和促进社会公平正义，全面推进科学立法、严格执法、公正司法、全民守法，全面推进国家各方面工作法\n治化，为以中国式现代化全面推进强国建设、民族复兴伟业提供有力法治保障。"}, {"title": "11月18日，第五届公园城市论坛在四川成都举行。", "detail": "本届论坛以“公园城市——更具活力和幸福感\n的现代化人民城市”为主题，设置开幕式、主旨演讲、成果发布、签约仪式等主要环节以及六个分论坛，\n邀请来自相关领域专家学者和知名企业代表等相聚蓉城，深入探讨公园城市示范区的时代价值、科学内涵、\n8\n(cid:3)\n实践路径，共谋人与自然和谐共享的未来绿色城市，提升公园城市生活新价"}, {"title": "2025(cid:1)年(cid:1)11(cid:1)月(cid:1)19(c", "detail": "id:1)日(cid:1)12(cid:1)时(cid:1)01(cid:1)分，我国在酒泉卫星发射中心使用长征二号丙运载火箭，成功将实践三\n值。\n十号A、B、C(cid:3)星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。实践三十号(cid:1)A、B、C(cid:1)星主要\n用于空间环境探测及相关技术验证。"}, {"title": "当地时间(cid:1)11(cid:1)月(cid:1)18(cid:1)日，国", "detail": "务院总理李强在莫斯科出席上海合作组织成员国政府首脑（总理）理事会\n第二十四次会议。李强表示，今年(cid:1)9(cid:1)月召开的上合组织天津峰会上，习近平主席郑重提出全球治理倡议，\n为国际社会合力应对世界变局、破解紧迫难题提供了中国智慧和中国方案。上合组织作为全球治理体系建\n设和改革的重要力量，有条件有能力，以共同落实全球治理倡议为契机，在推动实现“世界之治”中发挥\n更大作用。更多公考资料，请加客服微信：yumi9938"}, {"title": "11(cid:1)月(cid:1)19(cid:1)日，我国首个高压天然气长输管", "detail": "道余压发电项目——海门站天然气余压发电项目在江苏南\n通正式投入运营。项目实现了在高压天然气输送过程中对余压资源的高效利用，标志着我国在长输管道能\n源综合利用领域取得突破。"}, {"title": "近日，教育部、国家发展改革委、财政部、人力资源社会保障部、体育总局等五部门联合印", "detail": "发了《关\n于实施学生体质强健计划的意见》，《意见》提出，积极推进中小学生每天综合体育活动时间不低于2小\n时，一体化推进体育教学改革，构建学段衔接、目标一致、支撑有力的体育与健康课程实施机制。"}, {"title": "11月19日，“2025世界市长对话·南京”活动在江苏南京开幕。", "detail": "本次活动以“扬子潮涌文明共\n启”为主题。活动期间，与会嘉宾将围绕“滨水城市的活力”“滨水文化遗产保护”“滨水生态修复与绿\n色转型”“滨水城市与文学”四大主题，探索中国城市现代化发展成就，分享在文化遗产保护、绿色生态\n发展、智慧城市建设等领域的城市治理先进经验。"}, {"title": "中共中央11月20日上午在人民大会堂举行座谈会，纪念胡耀邦同志诞辰110周年。", "detail": "习近平发表重\n要讲话强调，胡耀邦同志的一生，是光辉的一生、战斗的一生、奉献的一生。在长达60年的革命生涯中，\n他充分展现了坚守信仰、献身理想的高尚品格，心在人民、利归天下的为民情怀，实事求是、勇于开拓的\n探索精神，求真务实、敢于担当的优秀品质，公道正派、廉洁自律的崇高风范。他永远值得我们学习。\n胡耀邦同志志存高远，在为共产主义不懈奋斗的长期实践中表现出坚韧不拔的革命意志，我们要像他\n那样，坚定理想信念，对党忠贞不渝。胡耀邦同志注重一切从实际出发，为推进马克思主义中国化和实现\n组织路线拨乱反正作出了重要贡献，我们要像他那样，坚持实事求是，矢志追求真理。胡耀邦同志积极倡\n导和推进改革开放，为推动社会主义现代化建设倾注了大量心血，我们要像他那样，勇立时代潮头，锐意\n改革创新。胡耀邦同志人民情怀真挚深厚，为发展经济、让人民尽快过上好日子做了大量实事好事，我们\n要像他那样，始终心在人民，做到利归天下。胡耀邦同志高度重视端正党风，为发扬党的优良传统和作风\n树立了光辉典范，我们要像他那样，保持一身正气，处处以身作则。"}, {"title": "11月20日，2025量子科技和产业大会开幕式在安徽合肥举行。", "detail": "大会以“百年量子·智启未来”为\n主题，汇聚知名学者、重点高校院所、央企代表、量子产业链企业、金融机构代表参会，共同探讨量子通\n信、量子计算、量子精密测量等量子前沿技术的发展趋势与产业应用前景。"}, {"title": "11月20日—21日，2025世界计算大会在湖南长沙举行。", "detail": "本次大会以“计算万物湘约未来——智算\n驱动新质生产力”为主题。大会期间举办12场主题活动，包括1场高规格的开幕式暨主题报告会、5场聚\n焦计算核心前沿的专题活动、5场技术赋能行业发展的同期活动和1场创新成果展示。"}, {"title": "2025年11月21日18时55分，我国在西昌卫星发射中心使用长征三号乙运载火箭", "detail": "，成功将通信技\n术试验卫星二十一号发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。通信技术试验卫星二十\n9\n(cid:3)\n一号主要用于卫星通信、广播电视、数据传输等业务，并开展相关技术试验"}, {"title": "全球南方现代化论坛(cid:1)11(cid:1)月(cid:1)21(cid:", "detail": "1)日在北京举行。论坛主题为“携手迈向现代化：共同愿景与发展之路”。\n验证。\n论坛还发布了《世界现代化发展报告》《中国式现代化发展报告》，颁发“全球发展研究与实践奖”，发\n起全球南方现代化研究学术网络。"}, {"title": "第七届中国－东盟法治论坛11月21日在重庆开幕，论坛主题是“加强中国－东盟法治合", "detail": "作，共建\n周边命运共同体”。"}, {"title": "工业和信息化部办公厅日前印发《高标准数字园区建设指南》，提出到2027年，建成2", "detail": "00个左右高\n标准数字园区，实现园区规上工业企业数字化改造全覆盖。"}, {"title": "近日，亚洲基础设施投资银行理事会已批准哥伦比亚加入亚投行的申请，至此，亚投行成员", "detail": "总数增\n至111个，遍布世界六大洲，覆盖全球81%的人口和世界65%的GDP。"}, {"title": "中华人民共和国第十五届运动会11月21日晚在广东深圳闭幕。", "detail": "第十五届全运会是粤港澳三地首次\n联合承办的大型体育赛事，是“一国两制”在体育领域的创新实践。第十六届全运会将于2029年在湖南举\n办。"}, {"title": "11月22日9时32分，全球最大“华龙一号”核电基地——漳州核电2号机组首次并网", "detail": "成功，正式\n向电网送出第一度电。至此，“华龙一号”批量化建设一期工程两台机组全部并网发电。漳州核电规划建\n设6台“华龙一号”核电机组。基地全面建成后，预计每年可提供超600亿度的清洁电能，据估算将可以\n满足福建南部地区厦门市、漳州市用电总和的75%，能够有效改善福建省“北电南送”的电力格局。"}, {"title": "国务院总理李强日前签署国务院令，公布《森林草原防灭火条例》，自2026年1月1日", "detail": "起施行。《条\n例》旨在有效预防和扑救森林草原火灾，保障人民生命财产安全，保护森林草原资源，维护生态安全。《条\n例》共6章63条。"}, {"title": "近日从自然资源部获悉，今年前10个月，我国新建成省级以上绿色矿山300余家。", "detail": "截至目前，全国\n已建成1054家国家级绿色矿山、4055家省级绿色矿山，占持证在产矿山的40.8%，在矿产资源节约集约利\n用、生态修复、节能减排等方面取得显著成效。"}, {"title": "二十国集团（G20）领导人第二十次峰会11月22日在南非约翰内斯堡开幕，会议当天", "detail": "通过了《二\n十国集团领导人约翰内斯堡峰会宣言》。本次峰会以“团结、平等、可持续”为主题，以加强灾害应对能\n力、确保低收入国家债务可持续性、为公正的能源转型筹集资金、利用关键矿产实现包容性增长及可持续\n发展为四大优先议题。"}, {"title": "当地时间11月22日，国务院总理李强在约翰内斯堡出席二十国集团领导人第二十次峰会", "detail": "第一阶段\n会议，就“包容和可持续经济增长”议题发表讲话。李强指出，面对世界经济复苏乏力，我们要坚持和衷\n共济，坚定维护自由贸易，建设开放型世界经济。面对分歧矛盾，我们要坚持求同存异，积极寻找利益最\n大公约数，通过平等协商妥处纷争摩擦，推动解决各自合理关切。面对治理困局，我们要坚持与时偕行，\n带头坚持多边主义，加快推动世界银行、国际货币基金组织、世贸组织等机构改革，提升发展中国家话语\n权，构建更加公平开放的国际经贸秩序。更多公考资料，请加客服微信：yumi9938"}, {"title": "11月22日，中国企业改革与发展研究会发布了《全球能源转型报告（2025）》，数", "detail": "据显示，我国\n已建成全球最大、最完整的清洁能源产业链。作为全球第一大煤炭消费国，我国近年来煤电装机占比持续\n下降，从2015年的58.7%下降到2025年上半年的33.1%。截至目前，我国绿色氢能产能超15万吨/年，占\n全球总量的50%以上；已建成加氢站540座，占全球比重达40%。"}, {"title": "当地时间11月22日晚，《联合国气候变化框架公约》第三十次缔约方大会（COP30", "detail": "）在巴西北部\n10\n(cid:3)\n城市贝伦闭幕。大会通过名为《全球动员团结协作应对气候变化挑战》的总体协议，并就减缓和适应气候\n变化、气候融资、国际合作等多项气候议题达成共识。"}, {"title": "11月22日，以“林木绿业合作共襄——数智赋能林木业高质量发展”为主题的2025", "detail": "年世界林木\n业大会在广西南宁举行。"}, {"title": "当地时间11月22日和23日，国务院总理李强在约翰内斯堡出席二十国集团领导人第二", "detail": "十次峰会\n第二及第三阶段会议，分别围绕“建设一个韧性的世界”和“造福所有人的公平公正未来”议题发言。李\n强表示，当前气候变化、能源、粮食等多重挑战叠加，需要国际社会以团结凝聚力量、靠协作破解难题。\n二十国集团应当推动更为广泛的国际合作，共同应对挑战，合力推动发展。一是加强生态环保合作，提升\n发展韧性。二是加强绿色能源合作，推进公正转型。三是加强粮食安全合作，保障稳定供应。"}, {"title": "11月24日，第六届中俄中小企业实业论坛开幕式在陕西西安举行，本届论坛以“绿色经", "detail": "济时代：\n中俄产业合作新机遇”为主题，设置开幕式暨全体会议、专题平行会议、实地考察等内容。"}, {"title": "11月24日，中国科学院燃烧等离子体国际科学计划在合肥正式启动，紧凑型聚变能实验", "detail": "装置BEST\n的研究计划也同步面向全球发布。来自法国、英国、德国、意大利等10多个国家的聚变科学家齐聚合肥，\n共同签署了《合肥聚变宣言》，呼吁加强国际合作，共同推进聚变能源研发。"}, {"title": "国内首个光量子计算机制造工厂11月24日正式在广东深圳南山区落成。", "detail": "光量子计算机的生产需要\n经过7大制程、223道工序，1000余个工步。"}, {"title": "11月25日12时11分，搭载神舟二十二号飞船的长征二号F遥二十二运载火箭，在酒", "detail": "泉卫星发射\n中心点火发射，约10分钟后，飞船与火箭成功分离并进入预定轨道，发射任务取得圆满成功。飞船入轨后，\n于15时50分成功对接于空间站天和核心舱前向端口。目前，中国空间站再次形成“三舱三船”组合体，\n状态运行正常。神舟二十二号飞船为无人状态，装载了航天食品、航天药品、新鲜果蔬、针对神舟二十号\n飞船舷窗裂纹的处置装置等，后续将作为神舟二十一号航天员乘组的返回飞船。"}, {"title": "11月25日，第七届中俄能源商务论坛在北京钓鱼台国宾馆举行。", "detail": "本届论坛主题为“强化中俄高水\n平战略对接，持续巩固全面能源合作伙伴关系”。双方有关部门单位和企业近400人参加开幕式。"}, {"title": "11月25日，我国自主设计建造的新一代超大型耙吸挖泥船“通浚”轮，在中国黄海海域", "detail": "成功完成\n全部海上试验项目，具备正式投入使用条件。“通浚”轮是我国自主设计建造的35000立方米舱容等级超\n大型耙吸挖泥船，最大舱容达38168立方米，舱容量位列亚洲第一。"}, {"title": "11月22日至23日，2025年非物质文化遗产保护工作会在云南大理举办。", "detail": "“十四五”期间，随着\n“太极拳”“送王船”“中国茶”“春节”等列入联合国教科文组织非物质文化遗产名录名册，我国列入\n该名录名册的项目达44项，数量居世界第一。"}, {"title": "11月25日，国家航天局推进商业航天高质量安全发展行动计划（2025—2027年", "detail": "）发布，计划明确，\n到2027年，商业航天产业生态高效协同，科研生产安全有序，产业规模显著壮大，创新创造活力显著增强，\n资源能力实现统筹建设和高效利用，行业治理能力显著提升，基本实现商业航天高质量发展。"}, {"title": "11月25日，联合国举行“声援巴勒斯坦人民国际日”纪念大会，国家主席习近平向大会", "detail": "致贺电。\n习近平指出，巴勒斯坦问题是中东问题的核心，关乎国际公平正义，牵动地区局势。当前形势下，国际社\n会应进一步凝聚共识，采取更积极行动，确保实现加沙全面持久停火，避免战火重燃。要秉持“巴人治巴”\n原则开展加沙战后治理和重建，尊重巴勒斯坦人民的意愿，照顾地区国家的合理关切。"}, {"title": "近日，在2025国际冬季运动博览会主论坛上发布的《中国冰雪产业发展研究报告（20", "detail": "25）》显示，\n2025年我国冰雪产业规模将突破万亿元大关，达10053亿元。这一数字标志着冰雪经济成为我国经济发展\n11\n(cid:3)\n中不容忽视的新兴力量。"}, {"title": "11月26日，第十四届中国商品市场论坛在浙江杭州召开，本届论坛以“活力大市场，畅", "detail": "通双循环”\n为主题，通过高层对话、权威发布、案例分享、合作签约与主题展区等环节，深入探讨商品市场焕新升级\n的方法与路径，全方位勾勒中国商品市场高质量发展的未来图景。"}, {"title": "国务院新闻办公室11月27日发布《新时代的中国军控、裁军与防扩散》白皮书。", "detail": "白皮书指出，进\n入新时代，在习近平新时代中国特色社会主义思想指引下，中国坚定不移推进中国式现代化建设，积极顺\n应国际社会共同呼声，践行全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议，推动构建人类\n命运共同体。中国建设性参与国际军控、裁军与防扩散进程，积极贡献中国倡议、中国方案，致力于改善\n国际安全环境，增进国际安全合作，破解国际安全困境，完善全球安全治理。中国始终是世界和平的建设\n者、全球发展的贡献者、国际秩序的维护者。"}, {"title": "今年12月4日是第十二个国家宪法日。", "detail": "日前，中央宣传部、司法部、全国普法办联合印发通知，\n以“学习宣传贯彻习近平法治思想，推动宪法深入人心”为主题，在全国组织开展2025年“宪法宣传周”\n活动。今年“宪法宣传周”活动时间为12月1日至7日。"}, {"title": "国家发展改革委近日印发《信用修复管理办法》，将从2026年4月1日起施行。", "detail": "办法从明确分类\n标准、优化办理流程、加强协同联动三方面入手，推动建立以“信用中国”网站为统一总窗口的协同机制，\n实现失信信息的精准分类、修复办理流程的标准化、修复结果的全国同步更新，帮助信用主体依法依规、\n高效便捷重塑信用，切实保障信用主体合法权益。"}, {"title": "11月27日，2025世界智能制造大会在江苏省南京市召开。", "detail": "大会以“数智驱动新质领航”为主题，\n设置主题大会和12场专题活动，成立了新一届国家智能制造专家委员会，发布了首批国家领航级智能工厂\n联合倡议、2025年度世界及中国智能制造十大科技进展等成果。"}, {"title": "11月27日，2025世界绿色发展投资贸易博览会暨中国绿色食品博览会在江西南昌开", "detail": "幕。大会以“数\n智赋能绿色发展开放江西链接全球”为主题，吸引了来自全球68个国家和地区嘉宾参会。"}, {"title": "中共中央政治局11月28日召开会议，审议《关于二十届中央巡视省（自治区、直辖市）", "detail": "情况的综\n合报告》。会议强调，各省区市党委要深入学习贯彻习近平新时代中国特色社会主义思想，牢牢把握党中\n央对本地区的战略定位，一以贯之抓好党中央重大决策部署贯彻落实，以实际行动做到“两个维护”。"}, {"title": "11月28日12时许，随着X8086次中欧班列从成都青白江区国际铁路港缓缓驶出，", "detail": "中欧班列历年\n累计开行突破12万列，发送货值超4900亿美元。中欧班列已通达欧洲26个国家232个城市，连接11个亚\n洲国家超过100个城市，为服务高质量共建“一带一路”更高水平对外开放注入新动能。"}, {"title": "中国气象局近日印发《全国农业气象试验站网布局优化调整方案》。", "detail": "我国将优化调整农业气象试验\n站网布局，由目前的72个调整为91个，站网覆盖率提升26%，在全国均衡分布。\n12\n(cid:3)"}]}, {"month": "2025年12月", "year": 2025, "items": [{"title": "11月26日，2025科创大会在上海举行。", "detail": "本次大会以“科创领航，智启新程”为主题，来自知名院校、\n科研机构的专家学者和科技企业、金融机构的相关负责人，深度探讨新一轮科技革命与产业变革的核心趋\n势，共话科技如何赋能产业升级、重塑未来生态。"}, {"title": "中共中央政治局11月28日下午就加强网络生态治理进行第二十三次集体学习。", "detail": "习近平在主持学习时\n强调，网络生态治理是网络强国建设的重要任务，事关国家发展和安全，事关人民群众切身利益。要健全\n网络生态治理长效机制，着力提升治理的前瞻性、精准性、系统性、协同性，持续营造风清气正的网络空\n间。\n习近平指出，党的十八大以来，我们把网络生态治理摆在重要位置，不断壮大网上主流价值、主流舆\n论、主流文化，有效打击遏制网络乱象，网络生态总体向上向好。这些年的实践让我们深刻认识到，抓网\n络生态治理必须坚持党的领导、坚持人民至上、坚持守正创新、坚持法治护航、坚持系统观念。"}, {"title": "11月28日，我国首套1500℃等级单轴重型燃机项目——大唐重庆江津燃机全容量投", "detail": "产发电，填补了\n国内“F”级改进型单轴重型燃机的空白。"}, {"title": "国际海事组织第34届大会11月28日在英国伦敦举行新一届理事国选举。", "detail": "中国以最高票当选A类理\n事国，这是中国连续第19次成功当选。当天选举共169个会员国有选举权，中国以155票获得最高票，凸\n显了中国在维护全球产供链安全畅通方面的特殊地位和重要性。同时当选A类理事国的还有意大利、韩国、\n英国、希腊、日本、巴拿马、美国、挪威和利比里亚。"}, {"title": "11月28日，首届全球万物智联数字经济可持续发展大会暨2025（第十届）世界物联", "detail": "网大会在北京召\n开。大会围绕“万物智联新经济智慧社会新时代”主题，举行了世界新经济论坛、大使论坛、世界物联网\n500强峰会、国际合作论坛、AI+物联网、智慧能源、工业互联、交通车联、低空智能网联等十多场论坛活\n动。"}, {"title": "在中国志愿服务联合会第三届会员代表大会召开之际，习近平发来贺信，向大会的召开表示", "detail": "祝贺，向\n广大志愿者、志愿服务组织、志愿服务工作者致以问候。习近平在贺信中指出，志愿服务是社会文明进步\n的重要标志，是志愿者服务他人、奉献社会的重要渠道。新征程上，希望广大志愿者、志愿服务组织、志\n愿服务工作者大力弘扬志愿精神，积极投身中国式现代化建设的生动实践，努力在服务国家战略、服务百\n姓民生、服务社会治理中传递真善美，传播正能量，为强国建设、民族复兴伟业贡献志愿服务力量。"}, {"title": "12月1日出版的第23期《求是》杂志将发表习近平的重要文章《推进党的自我革命要做", "detail": "到“五个进\n一步到位”》。文章强调，自我革命是我们党跳出治乱兴衰历史周期率的第二个答案。从抓作风入手推进\n全面从严治党是新时代党的自我革命一条重要经验。围绕党的自我革命，思路要求都是明确的，关键在于\n抓落实要真正到位。\n文章指出，党员干部增强党性要进一步到位。推进自我革命，必须固本培元、增强党性。重点是坚定\n理想信念，铸牢对党忠诚，厚植为民情怀，纯正道德品质，保持清正廉洁。要加强理论武装，坚守共产党\n人精神追求。"}, {"title": "国家知识产权局公布的最新数据显示：我国已成为世界上首个国内有效发明专利数量突破5", "detail": "00万件的\n国家，PCT国际专利申请量已连续6年位居全球第一；全球前5000个品牌中，我国品牌价值达1.81万亿美\n元，位居全球第二；地理标志产品直接产值接近9700亿元。"}, {"title": "11月30日，2025年传感器大会在河南郑州启幕。", "detail": "本次大会以“感知世界智创未来”为主题，旨在\n打造技术交流、成果转化、产业对接的全球性平台，为数字经济高质量发展注入“传感动力”。\n1\n(cid:3)"}, {"title": "11月30日20时20分，我国在文昌航天发射场使用长征七号改运载火箭，成功将实践", "detail": "二十八号卫\n星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "12月1日上午，2025年“读懂中国”国际会议开幕式在广东广州举行。", "detail": "本次大会以“新布局、新发\n展、新选择——中国式现代化与全球治理新格局”为主题，800余名中外嘉宾齐聚广州，聚焦我国“十五五”\n规划及其世界意义，就中国式现代化创新发展的新布局及其为世界现代化提供的新机遇，携手践行全球治\n理倡议等相关议题展开研讨。"}, {"title": "由中国航天科技集团一院抓总研制的我国首艘火箭网系回收海上平台于近日被命名为“领航", "detail": "者”并\n成功交付，标志着该院在可重复使用运载火箭技术链条上完成了重要一环，助推从技术验证到工程应用的\n跨越。"}, {"title": "12月1日，第三届中国侨智发展大会在福建福州开幕。", "detail": "本届大会以“五洲聚‘福’汇侨智·同心共\n圆中国梦”为永久主题，以“侨汇天下才·智创新时代”为年度主题，邀请安徽省作为主宾省，哈尔滨市\n作为主宾市，哈尔滨工业大学与同济大学作为主宾高校。"}, {"title": "12月1日，2025年深入学习贯彻习近平生态文明思想研讨会在福建厦门举行。", "detail": "研讨会以“深入学习\n贯彻习近平生态文明思想，奋力推进美丽中国建设取得新的重大进展”为主题，通过开展研讨交流，深入\n学习贯彻习近平生态文明思想，全面落实党的二十届四中全会精神，加快经济社会发展全面绿色转型，建\n设美丽中国。"}, {"title": "“2025从都国际论坛”12月2日在广州开幕，今年论坛以“同球共济共赢未来”为主", "detail": "题，将举行\n开闭幕式、闭门会议、大会讨论、平行论坛、“广州之夜”投资推介会共10场活动，重点探讨“不确定性\n时代所面临的全球安全挑战”“改革完善全球治理，增强稳定性和确定性”“以理解、包容与合作拥抱多\n样性的世界”“人工智能：寻求创新、安全与治理的平衡”“提供全球公共产品，落实2030可持续发展议\n程”“绿色低碳发展动能”“贸易与关税冲突下的世界经济发展走势”等议题。"}, {"title": "国家卫生健康委12月2日发布《2024年我国卫生健康事业发展统计公报》。", "detail": "《公报》显示，我国\n人均预期寿命达到79岁。卫生资源总量持续稳步增长，到2024年末，全国医疗卫生机构总数1093551个，\n比上年增加22766个；卫生技术人员1302.0万人，比上年增加53.1万人。"}, {"title": "12月2日，2025年中国国际海事技术学术会议和展览会（简称中国国际海事会展）在", "detail": "上海新国际博\n览中心开幕。本届会展以“创新与合作，共促海事业可持续发展”为主题，展览持续至5日，展览面积突\n破11万平方米，吸引全球16个国家和地区的超2200家企业参展。"}, {"title": "12月2日，中亚经济合作天山论坛在新疆乌鲁木齐举行，本届论坛以“助力互联互通，释", "detail": "放投资潜\n力”为主题，聚焦中亚区域贸易、交通、能源及数字互联互通，搭建多边对话平台，促进区域合作，发掘\n可持续投资机遇。"}, {"title": "12月3日，国务院以“深入推进以人为本的新型城镇化，着力构建城乡融合发展新格局”", "detail": "为主题，\n进行第十七次专题学习。李强指出，我国城镇化正从快速增长期转向稳定发展期，城市发展正从大规模增\n量扩张阶段转向存量提质增效为主的阶段，人口结构、城镇体系、城乡格局等都在发生深刻变化，人工智\n能等新技术的应用也对城市发展、治理带来新的机遇和挑战。要深刻认识新型城镇化的阶段性趋势性特征，\n进一步增强新型城镇化工作的针对性有效性。"}, {"title": "12月3日12时00分，朱雀三号遥一运载火箭在东风商业航天创新试验区发射升空，运", "detail": "载火箭二子\n级进入预定轨道，一子级未能成功回收，飞行试验任务获得基本成功。朱雀三号是蓝箭航天空间科技股份\n2\n(cid:3)\n有限公司自主研制的新一代低成本、大运力、高频次、可重复使用液氧甲烷运载火箭。"}, {"title": "12月3日上午，2025商业航天论坛在湖北武汉开幕。", "detail": "本届论坛以“统筹发展和安全、聚力商业航天、\n建设航天强国”为主题，将举办1场主论坛、3场主题分论坛、8场专题活动等。"}, {"title": "12月4日上午，国家主席习近平在北京人民大会堂同来华进行国事访问的法国总统马克龙", "detail": "举行会谈。\n习近平强调，中法两国要抓住机遇，拓展合作空间，巩固航空、航天、核能等传统领域合作，挖掘绿色经\n济、数字经济、生物医药、人工智能、新能源等领域合作潜力。中方愿进口更多法国优质产品，欢迎更多\n法国企业来华发展，也希望法方为中国企业提供公平环境和稳定预期。"}, {"title": "12月4日中午，国家主席习近平在北京同法国总统马克龙共同出席中法企业家委员会第七", "detail": "次会议闭\n幕式并致辞。习近平指出，今年是中法关系“新甲子”的开局之年。两国经贸合作领域不断拓展、韧性不\n断增强。一是不断拓展双边经贸合作新领域。二是继续推动中欧互利合作新发展。三是共同为改革完善全\n球治理作出新贡献。"}, {"title": "近日，国务院批复同意了《长三角国土空间规划（2023—2035年）》，规划提出，", "detail": "到2035年，长三\n角耕地保有量不低于16148万亩，其中永久基本农田保护面积不低于14290万亩；生态保护红线面积不低于"}, {"title": "7万平方千米；", "detail": "用水总量不超过国家下达指标。"}, {"title": "2025年12月4日是第十二个国家宪法日，12月1日至7日是第八个“宪法宣传周”。", "detail": "今年以“学\n习宣传贯彻习近平法治思想推动宪法深入人心”为主题，在全国组织开展2025年“宪法宣传周”活动。"}, {"title": "12月4日，第二十二届世界风能大会暨第三届汕头国际风电技术创新大会在广东汕头开幕。", "detail": "本次大\n会以“风能赋能未来：创新、协作与可持续增长”为主题，围绕风电前沿技术、产业链协同、国际交流合\n作等探索风电创新新范式，凝聚国际共识，促进全球风电合作迈入新阶段。"}, {"title": "12月4日，第三届全球南方智库对话会在上海举行，主题为“联合自强：全球南方的责任", "detail": "与行动”。\n来自120多个国家的政党领导人、智库学者等中外代表约350人与会。"}, {"title": "联合国教科文组织12月4日发布公报说，来自46个国家和地区的72座城市新加入其全", "detail": "球学习型城\n市网络，其中包括中国的宁波、天津和沈阳。此举意在认可这些城市为落实全民终身受教育权作出的杰出\n贡献。"}, {"title": "2025年12月5日17时00分，我国在酒泉卫星发射中心使用快舟一号甲运载火箭，", "detail": "成功将交通VDES\n卫星A星、B星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "12月5日，在联合国粮食及农业组织于罗马举行的世界土壤日官方庆典活动上，来自中国", "detail": "科学院南\n京土壤研究所的研究员张甘霖获颁2025年格林卡世界土壤奖。以表彰其在推进土壤保护和可持续管理方面\n的突出贡献。"}, {"title": "12月5日，第三届长三角电商交易会在苏州国际博览中心开幕。", "detail": "交易会以“联众破局增长”为主\n题，聚焦平台融合、产业联动与数字化转型，以更大规模、更强阵容展现长三角电商生态的新成果新活力。"}, {"title": "近日，《全球海上风电产业链发展报告2025》正式发布。", "detail": "《报告》显示，截至2025年9月底，我\n国海上风电累计并网容量达4461万千瓦，其中，海上风电新增并网容量为350万千瓦，连续五年稳居全球\n首位。"}, {"title": "2025年12月6日15时53分，我国在海南商业航天发射场使用长征八号甲运载火箭", "detail": "，成功将卫星\n互联网低轨14组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "“热耦合海水直接电解制氢”成果发布会12月6日在山东日照召开。", "detail": "发布会透露，中国已成功研制\n出首台套110千瓦级热耦合海水直接电解制氢系统装置，并已实现超过500小时的连续稳定运行，标志中\n3\n(cid:3)\n国在海水直接电解制氢这一领域，取得从实验室迈向工程化应用的关键突破。"}, {"title": "12月6日至7日，以“助力自贸港封关运作、共建人才荟萃之岛”为主题的第二届中国（", "detail": "海南）人\n才交流大会在海南海口举办。"}, {"title": "2025大湾区科学论坛开幕式12月7日在广州举行，本届论坛以“智创湾区、产研共融", "detail": "”为主题，\n旨在构建“政产学研用”深度融合的创新生态，探索科技创新与产业变革同频共振的实践路径。"}, {"title": "12月3日，中共中央在中南海召开党外人士座谈会，就今年经济形势和明年经济工作听取", "detail": "各民主党\n派中央、全国工商联负责人和无党派人士代表的意见建议。习近平对各民主党派、全国工商联和无党派人\n士提出3点希望。一是深入学习领会中共二十届四中全会精神。二是积极踊跃为制定实施“十五五”规划\n献计出力。三是凝心聚力推动经济稳定向好。"}, {"title": "从国家数据局获悉：截至2025年9月底，我国已建成高质量数据集总量超500PB（", "detail": "拍字节，计算机\n存储容量单位）；7个数据标注基地引进和培育标注企业362家，标注从业人员达8.5万人，带动数据标注\n相关产值163亿元。"}, {"title": "中共中央政治局12月8日召开会议，分析研究2026年经济工作，审议《中国共产党领", "detail": "导全面依法\n治国工作条例》。会议指出，明年经济工作要坚持稳中求进、提质增效，继续实施更加积极的财政政策和\n适度宽松的货币政策，发挥存量政策和增量政策集成效应，加大逆周期和跨周期调节力度，切实提升宏观\n经济治理效能。要坚持内需主导，建设强大国内市场；坚持创新驱动，加紧培育壮大新动能；坚持改革攻\n坚，增强高质量发展动力活力；坚持对外开放，推动多领域合作共赢；坚持协调发展，促进城乡融合和区\n域联动；坚持“双碳”引领，推动全面绿色转型；坚持民生为大，努力为人民群众多办实事；坚持守牢底\n线，积极稳妥化解重点领域风险。\n会议强调，要坚持和加强党的领导，把党领导立法、保证执法、支持司法、带头守法落到实处，提高\n依法治国、依法执政水平。全面贯彻习近平法治思想，牢牢把握全面依法治国正确政治方向，坚定法治自\n信，坚定不移走中国特色社会主义法治道路。\n获取后续更新及更多考试资料，请加微信：yumi9938"}, {"title": "12月8日，世界首次3.5万吨级重载群组列车开行试验在内蒙古包神铁路取得成功。", "detail": "这是全球首次\n实现多列货运列车不靠机械挂钩、仅靠无线信号就实现协同行驶。这次试验的核心难点，就是让7列各5000\n吨的货运列车不使用传统的机械挂钩进行连接，只依靠我国自主研发的智能系统，通过无线信号，让这7\n列货运列车做到同步加速、同步刹车，全程不撞车、不脱节。"}, {"title": "2025年12月9日6时11分，我国在太原卫星发射中心使用长征六号改运载火箭，成", "detail": "功将卫星互联\n网低轨15组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "中国石油集团12月9日发布消息，我国首个国家级陆相页岩油示范区——新疆吉木萨尔国", "detail": "家级陆相\n页岩油示范区今年原油产量突破170万吨，标志着其国家级示范工程建设任务全面完成。"}, {"title": "2025年12月9日18时45分，经过约8小时的出舱活动，神舟二十一号乘组航天员", "detail": "张陆、武飞、\n张洪章密切协同，出舱活动取得圆满成功。指令长张陆时隔两年半再度漫步太空，航天员武飞成为我国目\n前执行出舱任务最年轻的航天员。"}, {"title": "首届亚太空域峰会12月9日在香港亚洲国际博览馆开幕，超过2000名来自全球各地的", "detail": "航空专业人\n士参与。本届峰会以“塑造亚太天空的未来”为主题，聚焦航空交通管理领域的重要挑战和机遇，探讨如\n何将传统航空运作与先进空中移动方式相融合，并就低空交通管理、城市空中出行及下一代飞行器整合发\n展等议题展开深入交流。\n4\n(cid:3)"}, {"title": "日前，我国通过联合国国际搜索与救援咨询团（INSARAG）国家认证程序（IRNA", "detail": "P）资质认证，\n成为全球第10个获此权威认证的国家，标志着我国城市搜索与救援（USAR）体系达到国际先进水平，救援\n能力获国际社会高度认可。"}, {"title": "12月9日11时41分，我国在酒泉卫星发射中心使用长征四号乙运载火箭，成功将遥感", "detail": "四十七号卫\n星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。遥感四十七号卫星主要用于国土普查、城\n市规划、路网设计、农作物估产、环境治理和综合防灾减灾等领域。"}, {"title": "12月9日23时08分，我国在西昌卫星发射中心使用长征三号乙运载火箭，成功将通信", "detail": "技术试验卫\n星二十二号发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。通信技术试验卫星二十二号主要\n用于卫星通信、广播电视、数据传输等业务，并开展相关技术试验验证。"}, {"title": "第三份《中国对拉丁美洲和加勒比政策文件》12月10日在北京发布。", "detail": "政策文件说，中方愿同拉方\n携手推进团结、发展、文明、和平、民心“五大工程”，共谋发展振兴，共同谱写构建中拉命运共同体新\n篇章。"}, {"title": "国际货币基金组织（IMF）12月10日在北京表示，尽管面临多重冲击，中国经济仍展", "detail": "现出显著韧性。\nIMF预计2025年中国经济增速将达5%，较今年10月发布的《世界经济展望报告》上调0.2个百分点。"}, {"title": "2025年12月10日12时03分，我国在东风商业航天创新试验区使用力箭一号遥十", "detail": "一运载火箭，成\n功将阿联酋813卫星、吉星高分07B01星、吉星高分07C01星、吉星高分07D01星、东坡15号卫星、驭星\n二号09星、逸仙-A星、SPNEX卫星、Slippers2Sat卫星共9颗卫星发射升空，卫星顺利进入预定轨道，发\n射任务获得圆满成功。"}, {"title": "中央经济工作会议2025年12月10日至11日在北京举行。", "detail": "会议认为，通过实践，我们对做好新形\n势下经济工作又有了新的认识和体会：必须充分挖掘经济潜能，必须坚持政策支持和改革创新并举，必须\n做到既“放得活”又“管得好”，必须坚持投资于物和投资于人紧密结合，必须以苦练内功来应对外部挑\n战。\n会议确定，明年经济工作抓好以下重点任务。一是坚持内需主导，建设强大国内市场。二是坚持创新\n驱动，加紧培育壮大新动能。三是坚持改革攻坚，增强高质量发展动力活力。四是坚持对外开放，推动多\n领域合作共赢。五是坚持协调发展，促进城乡融合和区域联动。六是坚持“双碳”引领，推动全面绿色转\n型。七是坚持民生为大，努力为人民群众多办实事。八是坚持守牢底线，积极稳妥化解重点领域风险。"}, {"title": "12月11日至12日，2026年亚太经合组织（APEC）非正式高官会在深圳举行。", "detail": "这是我国担任2026\n年APEC东道主主办的首场活动，拉开APEC“中国年”帷幕。"}, {"title": "联合国教科文组织保护非物质文化遗产政府间委员会（简称“委员会”）12月11日在新", "detail": "德里举行\n第20届常会，通过评审，决定将中国“赫哲族伊玛堪”从急需保护的非物质文化遗产名录（简称“急需保\n护名录”）转入人类非物质文化遗产代表作名录（简称“代表作名录”）。"}, {"title": "12月10日下午，中国足球协会官方宣布，经赛区遴选和亚足联实地考察，2027年亚", "detail": "足联U20亚洲\n杯决赛阶段赛事将由杭州承办。这也是继2025年U20亚洲杯在深圳举办后，中国再次承办该赛事。"}, {"title": "12月11日晚，2025年海上丝绸之路国际文化旅游节在福建泉州开幕。", "detail": "此次旅游节以“丝路交响·融\n通世界”为主题，旨在依托泉州海丝文化、闽南文化的深厚底蕴，构建国际化多元交流平台，打造一场全\n球共享、全民参与的文旅盛宴，进一步促进文明互鉴。"}, {"title": "12月12日，国家统计局发布2025年粮食产量数据。", "detail": "2025年，全国粮食产量14298亿斤，比上年增\n加167.5亿斤，增长1.2%，稳定在1.4万亿斤以上。全国粮食播种面积179113万亩，比2024年增加135万\n5\n(cid:3)\n亩，增长0.1%。全国粮食单位面积产量798斤/亩，比2024年增加8.8斤/亩，增长1.1%。"}, {"title": "2025年12月12日7时0分，我国在海南商业航天发射场使用长征十二号运载火箭，", "detail": "成功将卫星互\n联网低轨16组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "中央经济工作会议2025年12月10日至11日在北京举行。", "detail": "会议指出，要在大局中把握明年经济工\n作的关键着力点，围绕做强国内大循环，拓展内需增长新空间；围绕发展新质生产力，推动科技创新和产\n业创新深度融合；围绕激发高质量发展的动力活力，坚定不移深化改革扩大开放；围绕不断增进民生福祉，\n加大保障和改善民生力度；围绕守牢安全底线，稳妥做好重点领域风险化解。"}, {"title": "12月12日，中国最北卫星数据接收站——中国遥感卫星地面站漠河卫星数据接收站正式", "detail": "投入运行。\n该站由中国科学院空天信息创新研究院布局建设，数据接收系统获国家发展和改革委员会投资支持，具备\n全自动化卫星数据接收能力，现承担资源系列、环境减灾系列、高分系列等共计25颗国家陆地观测卫星的\n数据接收任务。"}, {"title": "12月12日，“国际和平与信任年论坛”在土库曼斯坦阿什哈巴德市举行，国家主席习近", "detail": "平向论坛\n致贺信。习近平指出，今年是土库曼斯坦提议、联合国大会确立的国际和平与信任年，今天又恰逢土库曼\n斯坦获得永久中立地位30周年。习近平强调，不久前，我提出全球治理倡议，为改革完善全球治理体系提\n供了中国方案。中方期待同世界各国携手努力，维护世界和平，促进共同发展，推动构建人类命运共同体。\n获取后续更新及更多考试资料，请加微信：yumi9938"}, {"title": "12月12日从外交部获悉：亚太经合组织（APEC）第三十三次领导人非正式会议将于", "detail": "2026年11月\n18日至19日在广东省深圳市举行。"}, {"title": "2025年12月13日9时08分，快舟十一号遥八运载火箭在酒泉卫星发射中心发射升", "detail": "空，将迪迩五\n号空间试验器、希望五号二期卫星顺利送入轨道，飞行试验任务获得成功。"}, {"title": "中央经济工作会议2025年12月10日至11日在北京举行。", "detail": "会议指出，要按照党的二十届四中全会\n《建议》编制国家和地方“十五五”规划及专项规划，推动高质量、可持续的发展。要营造良好的政治环\n境、人才环境、营商环境、舆论环境，加强政策宣传解读，充分激发社会正能量。"}, {"title": "2025年12月13日是第十二个南京大屠杀死难者国家公祭日。", "detail": "中共中央、国务院12月13日上午在\n南京隆重举行2025年南京大屠杀死难者国家公祭仪式。2014年2月27日，十二届全国人大常委会第七次\n会议通过决定，以立法形式将12月13日设立为南京大屠杀死难者国家公祭日。"}, {"title": "以“量智新纪，产链未来”为主题的2025中关村量子大会12月13日在北京举办，聚", "detail": "焦量子科技前\n沿理论突破、核心技术攻关、应用场景落地、产业生态构建等核心方向，共绘量子规模化发展蓝图。"}, {"title": "中国海油发布消息，我国首个深水油田——流花油田二次开发项目12月14日实现全面投", "detail": "产，日产\n原油攀升至3900吨，创下产能新纪录。标志着我国在深水复杂油藏开发领域实现重大跨越。"}, {"title": "记者从农业农村部了解到，“十四五”期间，我国高质量推进高标准农田建设，累计安排中", "detail": "央资金\n超7000亿元，支持各地新建和改造提升高标准农田4.6亿亩。"}, {"title": "《中国油气行业“十四五”发展成就报告》日前在北京发布。", "detail": "报告显示，中国正加速迈向现代油气\n产业发展新阶段，能源结构日趋多元均衡，2030年我国天然气产量将达到3000亿立方米。"}, {"title": "12月15日，随着最后一台风机成功启动，我国离岸最远海上风电项目——三峡江苏大丰", "detail": "800兆瓦\n海上风电项目实现全容量并网，标志着我国海上风电向深远海迈进取得了又一重大突破。"}, {"title": "12月16日出版的第24期《求是》杂志将发表习近平的重要文章《扩大内需是战略之举", "detail": "》。文章强\n调，大国经济的优势就是内部可循环。要牢牢把握扩大内需这一战略基点，使生产、分配、流通、消费各\n6\n(cid:3)\n环节更多依托国内市场实现良性循环。扩大内需和扩大开放并不矛盾。\n文章指出，总需求不足是当前经济运行面临的突出矛盾。要坚决贯彻落实扩大内需战略规划纲要，尽\n快形成完整内需体系，着力扩大有收入支撑的消费需求、有合理回报的投资需求、有本金和债务约束的金\n融需求。消费是我国经济增长的重要引擎，扩大消费最根本的是促进就业，完善社保，优化收入分配结构，\n扩大中等收入群体，扎实推进共同富裕。"}, {"title": "近日，《GEI中国潜在独角兽企业研究报告2025》，《报告》显示，2024年中国", "detail": "潜在独角兽企业816\n家，新晋企业255家，超九成潜在独角兽企业分布在前沿科技领域。"}, {"title": "习近平近日对未成年人思想道德建设作出重要指示。", "detail": "他指出，新征程上，要落实立德树人根本任务，\n坚持把未成年人思想道德建设作为战略性、基础性工作来抓，持之以恒用新时代中国特色社会主义思想培\n根铸魂，健全学校家庭社会协同育人机制，教育引导广大未成年人树立远大理想，践行社会主义核心价值\n观，养成良好道德品质和行为习惯，努力成为德智体美劳全面发展的社会主义建设者和接班人。"}, {"title": "中华人民共和国第十二届残疾人运动会暨第九届特殊奥林匹克运动会12月15日晚在深圳", "detail": "闭幕，本\n届残特奥会共设46个大项，全国34个代表团的7824名运动员报名参赛，代表团规模和大众项目报名参赛\n运动员数量均创新高。下一届残特奥会将于2029年在湖南举办。"}, {"title": "《全民阅读促进条例》已经2025年11月27日国务院第73次常务会议通过，自20", "detail": "26年2月1日起\n施行。《条例》规定，全民阅读促进工作由党委领导、政府主导、社会力量参与，按照公益性、基本性、\n均等性、便利性的要求，构建全民覆盖、普惠高效的全民阅读促进体系，涵育文明风尚，厚植家国情怀，\n增强实现中华民族伟大复兴的精神力量。规定每年4月第四周为全民阅读活动周。支持利用信息技术开展\n全民阅读推广活动，扩大活动影响力。"}, {"title": "12月16日，2025两岸企业家峰会年会在江苏南京开幕，本届峰会年会以“聚焦转型", "detail": "创新深化多链\n合作”为主题，两岸企业家峰会理事会成员、会员及两岸企业家、专家学者共约800人出席活动。\n获取后续更新及更多考试资料，请加微信：yumi9938"}, {"title": "12月16日11时17分，我国在太原卫星发射中心使用长征四号乙运载火箭，成功将资", "detail": "源三号04星\n发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "第六届世界考古论坛12月16日在上海举办，本届论坛以“技术、社会与考古学”为主题。", "detail": "“玉见\n文明：良渚文化特展”同期在上海大学博物馆新馆举办。"}, {"title": "近日，国家统计局发布2025年粮食产量数据，其中新疆粮食单产每亩552.8公斤，", "detail": "较2024年每亩\n增加28公斤，单产连续两年增加超20公斤，蝉联全国粮食单产第一。"}, {"title": "12月17日从自然资源部中国地质调查局获悉，经国际矿物学会新矿物命名与分类专业委", "detail": "员会评审\n投票，由中国地质科学院科研人员发现并申请的新矿物——镍铋锑砷硫化物获得正式批准，中文名定为金\n秀矿。"}, {"title": "庆祝中国民主建国会成立80周年大会12月17日在京举行。", "detail": "中共中央政治局委员、中央统战部部长\n李干杰出席大会并代表中共中央致贺词。贺词说，历史和实践充分证明，民建作为中国共产党久经考验的\n亲密友党和通力合作的好参谋、好帮手、好同事，始终同中国共产党想在一起、站在一起、干在一起，不\n愧为推进中华民族从站起来、富起来到强起来伟大飞跃的一支重要力量，不愧为夺取新时代中国特色社会\n主义新胜利、全面建设社会主义现代化国家、全面推进中华民族伟大复兴的一支重要力量。"}, {"title": "12月17日，第十四届中国创新创业大赛全国总决赛在辽宁沈阳落幕，本次大赛以“因创", "detail": "而聚，向\n新同行”为主题。全国创新创业50强企业、知名投资机构代表、东北地区高新区等230余名嘉宾齐聚，共\n7\n(cid:3)\n赴这场创新盛会。"}, {"title": "12月17日，由中国科学院紫金山天文台发现的、国际编号336877号的小行星，经", "detail": "天文学联合会批\n准，被正式命名为“戚发轫星”。戚发轫是我国著名空间技术专家。曾参与“东风”导弹、“长征”运载\n火箭和“两弹结合”任务。"}, {"title": "12月18日，2025年中国数字文娱大会在广东广州帷幕。", "detail": "本届大会以“新技术新模式新业态”为\n主题，荟萃国内数字文化领域知名专家、学者、业界大咖等重磅嘉宾。"}, {"title": "2025年12月18日，海南自由贸易港正式启动全岛封关，中国对外开放迎来具有里程", "detail": "碑意义的标志\n性举措。即日起，海南全岛8个对外开放口岸及10个“二线口岸”监管设施悉数启用，标志着3万多平方\n公里的海南岛，正式成为海关监管特殊区域，“‘一线’放开、‘二线’管住、岛内自由”的新篇章就此\n开启。"}, {"title": "12月18日零时，我国首个进入川藏高原腹地的特高压工程——国家电网金上到湖北正负", "detail": "800千伏\n特高压直流输电工程建成投运。据介绍，工程总投资334亿元，起于金沙江上游，途经西藏、四川、重庆、\n湖北4省（区、市），止于湖北黄石大冶换流站，输电距离近1900公里。"}, {"title": "12月19日，2025企业社会责任论坛在陕西西安举行。", "detail": "此次论坛主题为“践行社会责任推动高质量\n发展”。论坛设主论坛和“新质生产力赋能高质量发展论坛”“科技创新和产业创新深度融合论坛”两个\n平行分论坛，论坛前还举办了“AI之夜智耀长安”展演活动，并组织了西安高质量发展主题调研采访。"}, {"title": "12月19日，中国物流与采购联合会在2025大宗商品国际化发展大会上发布《中国大", "detail": "宗商品价格指\n数报告（2025）》。报告指出，2025年中国大宗商品价格指数均值预计为112.1点，较上年下降0.1%。"}, {"title": "“十四五”时期，我国全面推进湿地生态保护修复，累计实施湿地保护项目超1000个，", "detail": "科学修复湿\n地434万亩。截至目前，湿地面积达8.34亿亩，守牢了湿地生态安全底线。"}, {"title": "近日，教育部印发《关于进一步加强中小学日常考试管理的通知》，《通知》针对不同学段", "detail": "分类提\n出考试频次的控制要求。小学一二年级不进行纸笔考试，义务教育其他年级由学校每学期组织一次期末考\n试。初中年级可根据不同学科实际，适当安排一次期中考试。普通高中学校要严格控制考试次数。严禁面\n向小学各年级和初高中非毕业年级组织区域性或跨校际的考试。"}, {"title": "国家互联网信息办公室12月19日发布的数字化绿色化协同转型发展报告（2025）显", "detail": "示，截至2024\n年底，我国累计建设国家绿色数据中心246家，累计推广300余项数据中心、通信基站等数字基础设施节\n能降碳技术，加快先进适用技术应用。"}, {"title": "12月19日，2025中国国际旅游交易会在海南海口开幕。", "detail": "本届旅交会以“你好！中国”为主题，会\n期3天。旅交会展览面积达6.5万平方米，共设置境内展区、境外展区、阳光海南展区、入境旅游消费展区\n和文旅融合展区五个展区，吸引了来自101个国家和地区的1000余名旅行商及代表参会，同时开展多场线\n下买卖家专业洽谈。"}, {"title": "12月20日，全球首台商用超临界二氧化碳发电机组在贵州六盘水首钢水钢集团成功商运", "detail": "，这也是\n超临界二氧化碳余热发电技术“超碳一号”的全球示范工程。\n获取后续更新及更多考试资料，请加微信：yumi9938"}, {"title": "12月20日，从中国石油获悉，位于塔克拉玛干沙漠腹地的我国最大超深油田——富满油", "detail": "田年产油\n气达460万吨，创造历史新高，标志着我国10亿吨级超深油气储量区的勘探开发取得重要进展，为我国深\n地能源保障增添了重要支撑。"}, {"title": "2025年12月20日20时30分，我国在文昌航天发射场使用长征五号运载火箭，成", "detail": "功将通信技术试\n8\n(cid:3)\n验卫星二十三号发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。该卫星主要用于开展多频段、\n高速率卫星通信技术验证。"}, {"title": "中国海油12月21日发布消息，我国海上最大油田——渤海油田2025年累计生产油气", "detail": "当量突破4000\n万吨，创历史新高，为国家能源安全和经济社会高质量发展提供保障。"}, {"title": "中国互联网络信息中心近日发布《数字消费发展报告（2025）》。", "detail": "报告显示，2025年上半年，我国\n数字消费总额达9.37万亿元，占居民消费支出总额近一半。"}, {"title": "中国科学技术协会生命科学学会联合体近日公布了2025年度中国生命科学十大进展，6", "detail": "个知识创新\n类和4个技术创新类项目成果入选。2025年度中国生命科学十大进展分别为：从分子解码到细胞编程的衰\n老新干预；新型菌源代谢物对宿主稳态与失衡的调控及防治新策略；鼻咽癌免疫治疗增效减毒新策略；蝗\n虫群聚信息素的生物合成解码与行为操控；卡路里限制促进健康延寿的效应分子及其机制的发现；开创大\n脑新生神经元治疗中枢神经系统疾病的新途径；表观遗传变异驱动植物逆境适应；隐形眼镜实现人类近红\n外时空色彩视觉；AI驱动蛋白质工程实现染色体精准操纵技术突破；生物多样性新边界探索：解码深渊动\n物演化过程和适应的遗传机制。"}, {"title": "国际篮联12月21日宣布了2026年名人堂人选，中国篮坛名宿王治郅榜上有名，成为", "detail": "继牟作云、郑\n海霞、姚明、苗立杰之后第五位入选国际篮联名人堂的中国篮球人。"}, {"title": "水利部12月22日发布，“十四五”时期，全国新增水土流失治理面积超34万平方公里", "detail": "，净减少水\n土流失面积约11.6万平方公里，水土保持率达到73%以上。重点地区水土流失得到有效治理，生态系统质\n量和稳定性明显增强。"}, {"title": "12月22日，由我国自主设计、建造的全球首艘甲醇双燃料动力智能超大型油轮在辽宁大", "detail": "连交付，\n标志着中国船舶工业在智能化、绿色化发展道路上迈出坚实一步，进一步巩固了在全球造船业竞争中的领\n先优势。"}, {"title": "全国首个城域级场景公共服务平台——南京场景服务平台日前正式运营。", "detail": "南京场景服务平台可实现\n对应用场景寻源、发布、展示、匹配、落地跟踪的全生命周期服务。通过数据共享、流程协同，打破了分\n散在城市各领域的场景“信息孤岛”，初步形成市区联动、多方协同的场景创新工作网络。"}, {"title": "2025年12月23日10时00分，长征十二号甲遥一运载火箭在东风商业航天创新试", "detail": "验区发射升空，\n运载火箭二子级进入预定轨道，一子级未能成功回收，飞行试验任务获得基本成功。"}, {"title": "习近平近日对中央企业工作作出重要指示指出，新征程上，中央企业要充分认识肩负的职责", "detail": "使命，\n更好服务党和国家工作大局，服务经济社会高质量发展，服务保障和改善民生，勇担社会责任，为中国式\n现代化建设贡献更大力量。"}, {"title": "近日，考古学家在四川省甘孜藏族自治州稻城县的高原湖泊——从前措附近，新发现了一处", "detail": "意义\n重大的旧石器时代遗址。作为稻城皮洛遗址群的重要组成部分，它刷新了人类在青藏高原东部迁徙扩散的\n海拔最高纪录。位于从前措湖畔的从前措遗址，最早距今约1.2万年，是皮洛遗址群中的海拔最高点。皮洛\n遗址则是青藏高原上目前已知年代最早、面积最大、文化内涵最丰富的遗址。从前措遗址的发现将皮洛遗\n址“登高纪录”提升到了海拔4300余米。"}, {"title": "国家发展改革委、国家能源局日前印发《关于促进光热发电规模化发展的若干意见》提出，", "detail": "到2030\n年，我国光热发电总装机规模力争达到1500万千瓦左右，度电成本与煤电基本相当。"}, {"title": "12月24日，2025中国民营经济与上市公司发展大会在福建晋江开幕。", "detail": "大会以“创新发展‘晋江经\n验’，助力民营经济健康发展，共谱‘十五五’新华章”为主题，举办主旨演讲、圆桌对话、主题论坛、\n9\n(cid:3)\n时政/公基/笔试/面试/真题资料，请加微信：yumi9938\n闭门会议等一系列活动，从宏观政策解读、经济趋势研判、企业实践分享、产业创新探索等多个维度，剖\n析“晋江经验”在新时代的丰富内涵与实践价值，解构民营经济高质量发展密码；同时搭建政府、交易所、\n学界、金融机构与民营企业的对接平台，共话融合发展的新路径、新机遇。"}, {"title": "12月24日，广东揭阳潮汕国际机场年旅客吞吐量突破1000万人次大关，标志着该机", "detail": "场正式跻身\n全国大型机场行列，继广州白云国际机场、深圳宝安国际机场、珠海金湾机场之后，成为广东第四个年旅\n客吞吐量超千万的机场。广东也成为全国首个拥有四个千万级机场的省份。"}, {"title": "国务院总理李强日前签署国务院令，公布《行政执法监督条例》，自2026年2月1日起", "detail": "施行。《条\n例》旨在加强和规范行政执法监督工作，促进严格规范公正文明执法，提升依法行政水平，强化法治政府\n建设。《条例》共7章44条。"}, {"title": "12月24日，中国科学院重大科技基础设施“载人潜水器与海上作业母船”用户委员会2", "detail": "025年度\n会议在海南三亚举行。我国“奋斗者”号、“深海勇士”号、“蛟龙”号三台深海载人潜水器目前已累计\n下潜1746次，今年预计完成314次下潜。"}, {"title": "12月23日，全球首个陆上商用模块式小型堆——中国核电旗下海南昌江多用途模块式小", "detail": "型堆科技\n示范工程“玲龙一号”非核冲转试验一次成功。冲转过程中各系统运行稳定、汽轮发电机组各项参数满足\n设计要求，标志着“玲龙一号”小堆示范工程汽轮发电机组非核蒸汽冲转试验顺利完成。"}, {"title": "第十一届国家治理高峰论坛暨制造业数智化转型发展大会12月24日在北京举行。", "detail": "本届论坛主题为\n“制造业数智化转型发展”，设置“新型工业化与智能制造”“制造强国与新能源汽车产业数智化转型”\n“共建‘一带一路’倡议与中国品牌全球化布局”“产业链协同发展与地方经济高质量发展”4个议题。\n获取后续更新及更多考试资料，请加微信：yumi9938"}, {"title": "12月25日从水利部获悉，目前全国耕地灌溉面积已超过10.9亿亩，较2020年底", "detail": "增加5300万亩以\n上。2025年耕地灌溉面积上粮食产量占全国粮食总产量的80.76%，较去年80.35%提高0.41个百分点，其中，\n大中型灌区粮食播种面积占全国的38.89%，粮食产量占全国总产量的50.9%。"}, {"title": "近日，国防科技大学磁浮团队在开展磁悬浮实验中，成功在两秒内，将吨级重的试验车加速", "detail": "至700\n公里/小时，这一测试速度打破了同类型平台全球纪录，成为全球最快的超导电动磁悬浮试验速度。"}, {"title": "2025年12月26日7时26分，我国在海南商业航天发射场使用长征八号甲运载火箭", "detail": "，成功将卫星\n互联网低轨17组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "12月26日10点，随着C9309次“复兴号”智能动车组驶出延安站，西安至延安高", "detail": "铁开通运营，革\n命老区延安迈入“高铁时代”。至此，中国高铁运营里程突破5万公里，高铁发展再上新台阶。"}, {"title": "国家统计局12月26日发布关于2024年国内生产总值最终核实的公告，经最终核实，", "detail": "2024年，GDP\n现价总量为1348066亿元，比初步核算数减少1018亿元；按不变价格计算，比上年增长5.0%，与初步核算\n数持平。"}, {"title": "12月25日至26日，中共中央政治局召开民主生活会，习近平强调，党的十八大以来，", "detail": "我们从中\n央政治局做起，从贯彻中央八项规定精神入手，着力纠治“四风”，成效显著。要坚持把中央八项规定作\n为铁规矩、硬杠杠，毫不松懈整治“四风”顽瘴痼疾，不断推进作风建设常态化长效化。中央政治局的同\n志要当好党性党风标杆，在笃信、务实、担当、自律上为全党带好头、作示范。\n获取后续更新及更多考试资料，请加微信：yumi9938"}, {"title": "国家卫健委12月26日召开新闻发布会，相关负责人表示，2025年，全国千人口托位", "detail": "数达到了4.73\n个，新增的普惠性托位达到89万个，超额完成既定目标任务，托育服务工作取得了积极进展。\n10\n(cid:3)"}, {"title": "2025年12月27日0时07分，我国在西昌卫星发射中心使用长征三号乙运载火箭，", "detail": "成功将风云四\n号03星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "十四届全国人大常委会第十九次会议12月27日表决通过新修订的国家通用语言文字法，", "detail": "明确每年\n9月的第三周为国家通用语言文字推广普及宣传周。当前，全国普通话普及率已超过80%，识字人口使用规\n范汉字的比例超过95%，文盲率下降至2.67%。设立国家通用语言文字推广普及宣传周，有利于营造学习使\n用国家通用语言文字的社会氛围。"}, {"title": "十四届全国人大常委会第十九次会议12月27日表决通过《中华人民共和国危险化学品安", "detail": "全法》，\n自2026年5月1日起施行。危险化学品安全法共10章127条。"}, {"title": "12月27日，国家“十四五”规划重大工程、我国在建海拔最高双曲拱坝电站——叶巴滩", "detail": "水电站首\n批机组正式投产发电。叶巴滩水电站位于四川白玉县与西藏贡觉县交界的金沙江干流上，是金沙江上游川\n藏段装机容量最大的水电站，总装机容量224万千瓦，最大坝高217米，具有高寒、高海拔、特高拱坝、\n高地应力、高埋深、大跨度地下厂房等特点。"}, {"title": "全国人大常委会会议12月27日表决通过新修订的民用航空法，自2026年7月1日起", "detail": "施行。此次\n新修订的民用航空法共16章262条。"}, {"title": "中央广播电视总台12月28日在京公布2026年春节联欢晚会分会场——黑龙江哈尔滨", "detail": "、浙江义乌、\n安徽合肥、四川宜宾将与北京主会场一起，为总台春晚注入各具特色的时代气息和别样魅力。"}, {"title": "12月27日至28日，全国财政工作会议在北京召开，会议认为，“十四五”时期，财政", "detail": "实力进一\n步增强，财政宏观调控更加科学有效，财税体制改革接续推进，财政统筹能力明显增强，财政发展与安全\n的基础不断夯实，对外财经交流合作广度和深度持续提升，财政在中国式现代化建设中的支撑和保障作用\n越来越强。\n会议指出，2026年继续实施更加积极的财政政策。一是扩大财政支出盘子，确保必要支出力度。二是\n优化政府债券工具组合，更好发挥债券效益。三是提高转移支付资金效能，增强地方自主可用财力。四是\n持续优化支出结构，强化重点领域保障。五是加强财政金融协同，放大政策效能。"}, {"title": "12月28日，全球首款6吨级倾转旋翼飞行器镧影R6000在四川德阳什邡市成功完成", "detail": "首次飞行。这\n一里程碑事件不仅标志着中国在高端航空制造领域取得重大突破，更为四川低空经济发展注入强劲动力，\n为我国立体交通体系建设开辟全新维度。"}, {"title": "中国法治论坛（2025）暨第十六届中国法学家论坛12月29日在广东深圳开幕，论坛", "detail": "以“深入学习\n贯彻习近平法治思想为‘十五五’经济社会发展提供坚强法治保障”为主题。"}, {"title": "国家统计局发布的数据显示，2025年，全国棉花产量664.1万吨。", "detail": "从播种面积看，2025年全国棉花\n播种面积达4468.7万亩，比2024年增加211.3万亩，增长5.0%。从单位面积产量看，2025年全国棉花单位\n面积产量148.6公斤/亩，比2024年增加3.8公斤/亩，增长2.6%。"}, {"title": "近日，由我国自主研发的30兆瓦级纯氢燃气轮机及氢储能示范项目取得重大突破——“木", "detail": "星一号”\n机组实现纯氢发电并保持稳定运行。这标志着30兆瓦级“电—氢—电”实证示范项目从蓝图迈向现实。"}, {"title": "中央农村工作会议12月29日至30日在北京召开。", "detail": "习近平强调，各级党委和政府要坚持把解决好\n“三农”问题作为重中之重，坚持五级书记抓乡村振兴，奋发进取、真抓实干，努力把农业建成现代化大\n产业、使农村基本具备现代生活条件、让农民生活更加富裕美好。\n会议指出，要进一步深化农村改革，全面开展第二轮土地承包到期后再延长三十年整省试点，规范有\n序做好农村各类资源盘活利用，创新乡村振兴投融资机制，不断增添乡村发展动力活力。\n11\n(cid:3)"}, {"title": "12月30日，随着强一股份鸣锣上市，科创板迎来第600家上市公司。", "detail": "截至目前，科创板总市值超\n10万亿元。"}, {"title": "2025年12月30日12时12分，我国在酒泉卫星发射中心使用长征四号乙运载火箭", "detail": "，成功将天绘\n七号卫星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。该卫星主要用于地理信息测绘、国\n土资源普查和科学试验研究等任务。"}, {"title": "国务院总理李强日前签署国务院令，公布《中华人民共和国增值税法实施条例》，自202", "detail": "6年1月\n1日起施行。《条例》旨在贯彻落实《中华人民共和国增值税法》，共6章54条。\n12\n(cid:3)"}]}, {"month": "2026年1月", "year": 2026, "items": [{"title": "12月30日，我国自主研制的“祥云”AS700获得全国首张国产载人飞艇生产许可证", "detail": "，正式迈入批量\n生产阶段。"}, {"title": "12月31日，全国政协在北京举行新年茶话会。", "detail": "习近平指出，2025年是很不平凡的一年。历经5年的艰\n苦奋斗，“十四五”圆满收官，我国经济实力、科技实力、国防实力、综合国力跃上新台阶。我们在砥砺奋\n进中进一步增强了志气、骨气、底气，更加坚定了推进强国建设、实现民族复兴的决心和信心。\n习近平强调，人民政协要紧扣党和国家中心任务，聚焦“十五五”规划制定和实施深入协商议政、积极\n建言献策、开展民主监督，为推进中国式现代化广泛凝聚人心、凝聚共识、凝聚智慧、凝聚力量。"}, {"title": "2025年12月31日6时40分，我国在文昌航天发射场使用长征七号改运载火箭，成", "detail": "功将实践二十九号\n卫星A星、B星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。"}, {"title": "新年前夕，国家主席习近平通过中央广播电视总台和互联网，发表二口二六年新年贺词。", "detail": "习近平指出，\n这一年，令人难忘的是，我们隆重纪念中国人民抗日战争暨世界反法西斯战争胜利80周年，设立台湾光复纪\n念日。国之盛典威武雄壮，胜利荣光永载史册，激励中华儿女铭记历史、缅怀先烈、珍爱和平、开创未来，\n凝聚起中华民族伟大复兴的磅礴伟力。我们依靠创新为高质量发展赋能。我们以文化滋养精神家园。我们共\n创共享美好生活。我们继续敞开胸怀拥抱世界。"}, {"title": "国家粮食和物资储备局最新统计数据显示，2025年各类企业累计收购粮食达到8300", "detail": "亿斤。全年粮食\n市场运行顺畅，价格整体企稳回升。"}, {"title": "2026年1月1日，我国首套真空式自动系泊系统在山东港口青岛港全自动化集装箱码头", "detail": "正式投用。该\n可自动完成对200米以上大型集装箱船舶的精准吸附与固定，将单船系泊作业时间从传统的20-30分钟大幅缩"}, {"title": "2026年1月1日出版的第1期《求是》杂志将发表习近平的重要文章《学习好贯彻好党", "detail": "的二十届四中全\n会精神》。文章指出，要深入学习领会全会精神。通过各种方式组织好全会精神的学习、宣讲、宣传，使全\n党全社会领会好全会精神。第一，深刻领会“十五五”时期经济社会发展的重大意义。第二，深刻领会党中\n央关于国内外形势的基本判断。第三，深刻领会“十五五”时期经济社会发展的指导思想和重大原则。第四，\n深刻领会“十五五”时期经济社会发展的重大战略任务。第五，深刻领会“十五五”时期经济社会发展的根\n第1页共15页\n本保证。\n文章指出，要认真抓好全会精神贯彻落实。在贯彻落实全会精神过程中，要着重把握以下几点。第一，\n坚定不移推动高质量发展。第二，加快构建新发展格局。第三，推动全体人民共同富裕迈出坚实步伐。第四，\n更好统筹发展和安全。第五，统筹推进各领域工作。[公众号：橙子考公资料站提供更新]\n文章指出，管党治党越有效，经济社会发展的保障就越有力。必须以永远在路上的坚韧和执着，持之以\n恒推进全面从严治党。第一，坚决把党的自我革命要求落实到位。第二，推进党的作风建设常态化长效化。\n第三，坚定不移开展反腐败斗争。"}, {"title": "《四川省古籍保护利用条例》2026年1月1日起正式施行，这是我国首部专门的古籍保", "detail": "护利用地方性\n法规。据介绍，四川普查发现汉文古籍约23万部187万册、民族古籍约50万册，数量居全国前列。根据条例"}, {"title": "国家体育总局日前发布《第六次全国国民体质监测公报》《2025年全民健身活动状况调", "detail": "查公报》。数\n据显示，我国国民体质达到“合格”等级及以上人数比例达84.9%，较2020年提升0.8个百分点，达到“良好\n等级及以上人数比例达到30.9%，较2020年提升1.5个百分点。"}, {"title": "在科技日报创刊40周年之际，习近平发来贺信，向报社全体同志表示祝贺。", "detail": "习近平在贺信中指出，\n40年来，科技日报围绕党和国家中心工作，在宣传党的创新理论、解读科技政策、报道科技成就、普及科学\n知识等方面发挥了积极作用。"}, {"title": "1月4日从国铁集团获悉，截至2025年底，全国铁路营业里程达16.5万公里，其中", "detail": "高铁超5万公里，\n我国建成世界规模最大，先进发达的高速铁路网。"}, {"title": "2025年，我国在载人航天、深空探测、商业航天等领域完成多项突破，实现多个首次。", "detail": "2025年，中\n国航天全年发射次数达到92次，创历史新高。"}, {"title": "国家发展改革委、国家能源局联合印发的关于促进电网高质量发展的指导意见提出，到20", "detail": "30年电网\n资源优化配置能力有效增强，“西电东送”规模超过4.2亿千瓦，新增省间电力互济能力4000万千瓦左右，支\n撑新能源发电量占比达到30%左右，接纳分布式新能源能力达到9亿千瓦，支撑充电基础设施超过4000万台。"}, {"title": "日前，国务院印发《固体废物综合治理行动计划》，《行动计划》提出，到2030年，重", "detail": "点领域固体\n废物专项整治取得明显成效，固体废物历史堆存量得到有效管控，非法倾倒处置高发态势得到遏制，大宗固\n体废弃物年综合利用量达到45亿吨，主要再生资源年循环利用量达到5.1亿吨，固体废物综合治理能力和水平\n显著提升。\n第2页共15页"}, {"title": "1月5日从宁波舟山港获悉，2025年宁波舟山港完成货物吞吐量超14亿吨，连续17", "detail": "年位居全球第一，\n宁波舟山港也由此成为全球首个年货物吞吐量超14亿吨的大港。"}, {"title": "1月5日下午，国家主席习近平在北京人民大会堂同来华进行国事访问的韩国总统李在明举", "detail": "行会谈。\n习近平强调，中韩两国长期坚持“以和为贵”“和而不同”，超越社会制度和意识形态差异，相互成就、共\n同发展。双方应延续这一优良传统，不断增进互信，尊重各自选择的发展道路，照顾彼此核心利益和重大关\n切，坚持通过对话协商妥善解决分歧。"}, {"title": "近日，水利部发布2025年幸福河湖优秀案例名单，北京市亮马河等河湖入选。", "detail": "幸福河湖是让大家在\n生态改善中收获安全感、在亲水近水中增强获得感、在人水和谐中提升满意度的民生工程。截至目前，“十\n四五”期间全国累计建成5500余幸福河湖，为人民群众打造了一大批亲近自然、畅享生活的高品质滨水空间。"}, {"title": "近日，商务部等9部门联合出台了《关于实施绿色消费推进行动的通知》，提出7方面20", "detail": "条具体举措，\n要求提升绿色服务消费，发展绿色餐饮、绿色住宿、绿色家政，满足人民对美好生活向往的需要。"}, {"title": "[公众号：橙子考公资料站提供更新]中共中央政治局常委、国务院总理李强1月3日至5", "detail": "日在广东调研。\n他强调，迈入新的一年，要深入贯彻习近平总书记在中央经济工作会议上的重要讲话精神，紧紧围绕推动高\n质量发展这个主题，牢记在全国发展大局中的使命，厚植创新发展优势，勇立改革开放潮头，只争朝夕做好\n经济社会发展各项工作，奋力实现“十五五”良好开局。"}, {"title": "1月5日，中国上市公司协会发布2025年A股上市公司市值表现报告。", "detail": "报告显示，截至2025年底，A\n股上市公司共5469家，总市值123万亿元，其中2025年新增上市公司116家，2025年1月1日前上市的存量公\n司5353家，2025年存量上市公司总市值同比增长22.5%。\n建设完成投资连续4年超万亿元。2025年我国实施各类水利项目47563个，吸纳就业315万人。"}, {"title": "国务院总理李强日前签署国务院令，公布《商事调解条例》，自2026年5月1日起施行。", "detail": "《条例》旨\n在规范商事调解活动，有效解决商事争议，保护当事人合法权益，促进商事调解行业发展，优化营商环境。\n《条例》共33条。"}, {"title": "1月7日从国家卫生健康委了解到，2025年我国居民健康素养水平达到33.69%，", "detail": "比2024年提高1.82\n个百分点，继续保持稳步提升态势。"}, {"title": "从1月7日举行的2026年全国邮政工作会议上获悉：2025年，邮政行业业务收入和", "detail": "行业寄递业务量\n第3页共15页\n分别完成1.8万亿元和2165亿件，同比分别增长6.4%和11.5%。"}, {"title": "国务院总理李强日前签署国务院令，公布修订后的《殡葬管理条例》。", "detail": "《条例》自2026年3月30日\n起施行，全文共8章73条。强调殡葬事业是重要的公益事业；坚持公益惠民、文明节俭、绿色生态，完善殡葬\n服务，深化殡葬移风易俗；稳妥推进殡葬改革。"}, {"title": "工业和信息化部办公厅日前印发《工业互联网和人工智能融合赋能行动方案》，提出到20", "detail": "28年，工\n业互联网与人工智能融合赋能水平显著提升，推动不少于50000家企业实施新型工业网络改造升级，在20个\n重点行业打造一批高质量数据集，培育一批智能化解决方案供应商。"}, {"title": "中共中央政治局常务委员会1月8日全天召开会议，会议指出，\"十五五”时期，我国发展", "detail": "环境面临\n深刻复杂变化，工作任务艰巨繁重，要坚持好、运用好、发展好党的领导这一最大优势，为中国式现代化建\n设提供根本保证。\n会议认为，过去一年，在中央政治局、中央政治局常委会领导下，中央书记处认真贯彻党中央决策部署，\n积极履职尽责，在完成党中央交办任务、加强党内法规制度建设、指导推动群团工作、整治形式主义为基层\n减负等方面做了大量工作。"}, {"title": "中国载人航天工程办公室1月8日面向全社会发布2025年度《中国空间站科学研究与应", "detail": "用进展报告》。\n《报告》着眼全面促进空间科学、空间技术以及空间应用领域蓬勃发展，重点围绕空间生命科学与人体研究、\n微重力物理科学、空间新技术与应用等领域。截至2025年12月，在空间生命与人体研究、微重力物理科学、\n空间新技术与应用三大领域已在轨部署和实施265项科学与应用项目。"}, {"title": "1月8日从国家铁路局召开的2026年全国铁路监督管理工作会议上获得的消息。", "detail": "2025年，全国铁路\n完成旅客发送量45.88亿人次，同比增长6.4%；完成货物发送量52.73亿吨，同比增长2.0%。"}, {"title": "国家卫生健康委等13部门近日发布了《儿童青少年“五健”促进行动计划（2026一2", "detail": "030年）》，\n数据显示，当前我国6岁至17岁儿童青少年超重肥胖率约为19%，要保障中小学生每天综合体育活动时间不低\n于2小时，在中小学校推进健康食堂、健康餐厅建设等。到2030年，中小学生国家学生体质健康标准达标优良\n率达到60%以上。获取后续更新及更多考试资料，请加微信：szgkzlz7\n平向2026年“中非人文交流年”开幕式致贺信。习近平指出，希望双方以“人文交流年”为契机，续传统\n友好，加强文明互鉴，密切人员往来特别是青年交往，深化治国理政经验交流，携手推进现代化，促进28亿\n多中非人民心相通、情共融、力同聚，为全球南方团结应对全球性挑战、弘扬全人类共同价值、推动构建人\n第4页共15页\n类命运共同体作出新的中非贡献。"}, {"title": "从国铁集团获悉，2025年中欧班列开行20022列，年度开行数量首次超两万列，货", "detail": "值超677亿美元。\n截至2025年底，中欧班列已联通中国境内128个城市，通达欧洲26个国家232个城市。"}, {"title": "1月9日，全国铁路系统先进集体和先进个人表彰大会在京举行。", "detail": "会议指出，“十四五”以来，在以\n习近平同志为核心的党中央坚强领导下，全体铁路工作者以“逢山开路、遇水架桥”的担当气魄，以“人享\n其行、物畅其流”的价值追求，以“勇于创新、攻坚克难”的进取精神，以“人民至上、生命至上”的发展\n理念，以“开放联动、和合共生”的全球胸襟，书写了铁路发展的辉煌篇章。"}, {"title": "在第六个中国人民警察节之际，中央宣传部、公安部向全社会发布“最美基层民警”。", "detail": "张雷、连捷、\n任飞、金亮、冯晶、宋柳丰、崔辉、翁红华、宋清罡、万松、廖天红、闫明、谭建华、赵阳、旦知刀杰、陈\n少峻、居麦·阿卜力孜、林芳德、彭泽栋、易桂平等20名同志光荣入选。"}, {"title": "国务院新闻办公室1月9日举行发布会，水利部相关负责人介绍说，目前，国家水网覆盖范", "detail": "围占国土\n面积的比例达80.3%，为国家重大战略实施、重要经济区、重要城市群、能源基地、粮食主产区、重点生态功\n能区、重要水运通道提供了坚实水安全保障。"}, {"title": "2026年1月10日是第六个中国人民警察节，全国公安机关通过升挂警旗、奏唱警歌、", "detail": "重温入警誓词、\n组织警营开放日、表彰先进等系列活动庆祝节日。"}, {"title": "从国家知识产权局获悉：2025年，我国授权发明专利97.2万件，注册商标420.", "detail": "6万件。截至目前，\n我国国内发明专利有效量超过500万件，每万人口高价值发明专利拥有量达16件，超额完成“十四五”规划目\n标。"}, {"title": "近日从上港集团获悉，2025年上海港集装箱吞吐量突破5506万标准箱，同比增长6", "detail": ".9%，再创新高，"}, {"title": "香港铁路有限公司1月11日宣布，其营运的高速铁路（香港段）将于1月26日起再增1", "detail": "6个站点，令西\n九龙站出发列车的直达站点增至110个。"}, {"title": "近日，2026年全国教育工作会议在北京召开。", "detail": "会议强调，要坚持稳中求进工作总基调，全面把握教\n育的政治属性、人民属性、战略属性，坚决落实立德树人根本任务，着力强化教育对科技和人才的支撑作用，\n着力提升教育公共服务质量和水平，深化教育综合改革和试点探索，加快构建高质量教育体系，推动教育强\n国建设取得实质性新进展，为基本实现社会主义现代化夯实基础、全面发力提供先导性、基础性、战略性支\n撑，确保“十五五”开好局、起好步。\n第5页共15页"}, {"title": "近日商务部印发《大连等9城市服务业扩大开放综合试点任务》，《试点任务》赋予大连、", "detail": "宁波、厦\n会同相关部门和省市主动探索、大胆实践，推动各项试点任务落实落细，更好为全国服务业开放创新和高质\n量发展发挥带动作用。获取后续更新及更多考试资料，请加微信：Szgkzlz7"}, {"title": "近日，国家主席习近平复信由美国佛罗里达州迈阿密钻石领航学院、佛罗里达大学、迈阿密", "detail": "戴德学\n院组成的青少年教育交流团访华师生。习近平指出，中美关系的希望在人民、未来在青年。“5年邀请5万名\n美国青少年来华交流学习”倡议启动以来，有超过4万名美国青少年积极参与，为他们认识真实的中国打开了\n一扇窗，为续两国人民友谊搭建起一座桥。这充分说明，开展友好交流合作是中美两国民心所向。"}, {"title": "1月12日，习近平在二十届中央纪委五次全会上发表重要讲话，他强调，要坚持和加强党", "detail": "的全面领导，\n以更高标准、更实举措推进全面从严治党，更加坚决有力地贯彻落实党中央重大决策部署，更加科学有效地\n把权力关进制度笼子，更加清醒坚定地推进反腐败斗争，为实现“十五五”时期目标任务提供坚强保障。\n习近平指出，纪检监察机关在推进党的自我革命、全面从严治党中责任重大、使命光荣，要坚定维护党\n的团结统一，坚定捍卫党的先进性纯洁性。要持续加强纪检监察工作规范化法治化正规化建设，不断提高监\n督执纪执法质效。[公众号：橙子考公资料站提供更新]要按照政治过硬、能力过硬、作风过硬、廉洁过硬的\n要求，着力锻造忠诚干净担当、敢于善于斗争的纪检监察铁军。"}, {"title": "1月12日，力鸿一号遥一飞行器在我国酒泉卫星发射中心圆满完成亚轨道飞行试验任务，", "detail": "返回式载荷\n舱通过伞降回收系统顺利看陆完成回收。力鸿一号遥一飞行器飞行高度约120千米，具有发射成本低、灵活性\n高以及支持实验载荷回收等特点，主要面向微重力科学实验和近太空原位探测等应用需求，可为科学实验载\n荷提供300秒以上高度稳定且功能多样的实验环境。"}, {"title": "1月12日，国家发展改革委、财政部、科技部、工业和信息化部联合发布《关于加强政府", "detail": "投资基金布\n局规划和投向指导的工作办法》。在优化基金布局方面，要求基金支持重大战略、重点领域和市场难以有效\n配置资源的薄弱环节，推动科技创新和产业创新深度融合，着力培育新兴支柱产业，坚持投早、投小、投长\n期、投硬科技。"}, {"title": "近日，国务院办公厅印发《“高效办成一件事”2026年度第一批重点事项清单》，包含", "detail": "个人和企业\n事项13项。截至目前，国家层面“高效办成一件事”重点事项清单已推出五批共55项，便民惠企清单持续扩\n容，这既是“高效办成一件事”常态化推进机制的延续深化，更是以“钉钉子精神”破解政务服务堵点、传\n递为民服务温度的生动实践，彰显改革初心与攻坚决心。\n第6页共15页"}, {"title": "1月11日，由东福研究院自主研发的国内首台千瓦级水下抽蓄储能系统“东储一号”，在", "detail": "三明闽湖顺\n利完成为期10天的水下综合试验。此次试验的圆满成功，不仅标志着我国在水下储能技术领域实现了从理论\n研究到工程实践的关键跨越，更填补了国内新型水下抽蓄储能技术的空白，使我国路身该领域国际并跑行列。"}, {"title": "1月13日，从三峡集团获悉，全球首台20兆瓦海上风电机组在福建海域完成吊装。", "detail": "这是我国20兆瓦\n级海上风电机组首次在海上完成吊装，标志着我国超大容量机组研发制造和海上施工领域实现重要突破。"}, {"title": "从国务院新闻办1月13日举行的国务院政策例行吹风会上了解到，到2027年全国“无", "detail": "废城市”建设\n比例将达到60%，到2035年实现全覆盖。据介绍，“十四五”期间，生态环境部推动全国113个城市和8个特\n殊地区开展“无废城市”建设，实施各类固体废物治理项目3000多项，投入资金约5600亿元。"}, {"title": "从民政部1月13日举行的新闻发布会上了解到，民政部有关负责人介绍，截至2025年", "detail": "底，我国养老\n机构共4.17万家，从业人员达72.2万人，同比增长12.2%。其中，民营养老机构占比52.2%；民营及公建民营\n养老机构累计达3万家，占比达71.9%。"}, {"title": "2026年1月13日22时16分，我国在太原卫星发射中心使用长征六号改运载火箭，", "detail": "成功将遥感五十号\n01星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。该卫星主要用于国土普查、农作物估产和\n防灾减灾等领域。"}, {"title": "[公众号：橙子考公资料站提供更新]中国汽车工业协会1月14日发布的最新数据显示，", "detail": "2025年，汽\n车产销量分别为3453.1万辆和3440万辆，同比分别增长10.4%和9.4%，产销量再创历史新高，连续17年稳居\n全球第一。新能源汽车产销量均超1600万辆，新能源汽车国内新车销量占比突破50%。"}, {"title": "二十届中央纪委五次全会于2026年1月12日至14日在北京举行。", "detail": "全会强调，“十五五”时期是基本\n实把思想和行动统一到以习近平同志为核心的党中央对形势的准确判断、对任务的科学部署上来，深刻把握\n实现“十五五”时期目标任务对维护党的团结统一提出的更高要求，坚定不移推动全党拥护“两个确立”、\n做到“两个维护”；深刻把握实现“十五五”时期目标任务对把权力关进制度笼子提出的更高要求，坚定不\n移强化制度治权、依规用权；深刻把握实现“十五五”时期目标任务对保持党的先进性纯洁性提出的更高要\n求，坚定不移走好中国特色反腐败之路；深刻把握实现“十五五”时期目标任务对激励担当作为提出的更高\n要求，坚定不移促进党员干部在遵规守纪中干事创业。\n会议指出，强化政治监督，推动全党凝心聚力实现“十五五”时期目标任务。推动加强党的创新理论武\n装，引导党员干部增强使命意识，做到笃信、务实、担当、自律。\n第7页共15页"}, {"title": "国务院新闻办公室1月14日举行发布会，据海关统计，2025年我国货物贸易进出口总", "detail": "值45.47万亿元，\n同比增长3.8%。其中，出口26.99万亿元，增长6.1%；进口18.48万亿元，增长0.5%。"}, {"title": "2026年1月13日23时25分，我国在海南商业航天发射场使用长征八号甲运载火箭", "detail": "，成功将卫星互联\n网低轨18组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "1月15日从全国林业和草原工作会议上获悉，2025年，我国完成国土绿化任务1.2", "detail": "7亿亩，其中营造\n林5345万亩，退化草原修复治理7390万亩。目前全国森林覆盖率达25.09%，森林蓄积量达209.88亿立方米\n绿色发展底色更加鲜明。获取后续更新及更多考试资料，请加微信：szgkziz7"}, {"title": "国务院总理李强1月15日下午在北京人民大会堂同来华进行正式访问的加拿大总理卡尼举", "detail": "行会谈。李\n强指出，中加经济互补性强，两国合作具有很强内生动力和广阔空间。中方愿同加方加强发展战略对接，继\n续恢复和推进各领域各层级交往，用好两国政府间经贸、科技、农业等对话机制，促进双边贸易稳定增长，\n提升贸易便利化水平，深化清洁能源、数字技术、现代农业、航空航天、先进制造、金融等领域合作，培育\n更多新的经济增长点。"}, {"title": "1月16日出版的第2期《求是》杂志发表习近平的重要文章《在中央城市工作会议上的讲", "detail": "话》。文章\n指出，党的十八大以来，党中央深刻把握新形势下我国城市发展规律，坚持党对城市工作的全面领导，坚持\n人民城市人民建、人民城市为人民，坚持把城市作为有机生命体系统谋划，推动城市发展取得历史性成就，\n我国新型城镇化水平和城市发展能级、城市规划建设治理水平、宜业宜居水平、历史文化保护传承水平、生\n态环境质量大幅提升。\n文章提出了当前和今后一个时期城市工作的总体要求，强调要以新时代中国特色社会主义思想为指导，\n深入贯彻党的二十大和二十届二中、三中全会精神，坚持和加强党的全面领导，认真践行人民城市理念，坚\n持稳中求进工作总基调，坚持因地制宜、分类指导，以建设创新、宜居、美丽、韧性、文明、智慧的现代化\n人民城市为目标，以推动城市高质量发展为主题，以坚持城市内涵式发展为主线，以推进城市更新为重要抓\n手，大力推动城市结构优化、动能转换、品质提升、绿色转型、文脉续、治理增效，牢牢守住城市安全底\n线，走出一条中国特色城市现代化新路子。\n文章指出，落实这一总体要求，关键在于坚持城市内涵式发展，切实把握好几个重要原则。一是转变城\n市发展理念，更加注重以人为本。二是转变城市发展方式，更加注重集约高效。三是转变城市发展动力，更\n加注重特色发展。四是转变城市工作重心，更加注重治理投入。五是转变城市工作方法，更加注重统筹协调。"}, {"title": "2026年1月15日12时01分，我国在酒泉卫星发射中心使用长征二号丙运载火箭成", "detail": "功将阿尔及利亚遥\n第8页共15页\n感三号卫星A星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。该卫星主要用于土地规划和防灾\n减灾领域。"}, {"title": "商务部新闻发言人何咏前在1月15日举行的商务部例行新闻发布会上说，亚太经合组织（", "detail": "APEC）第\n三十二届贸易部长会议将于2026年5月在江苏省苏州市举办，这次会议在APEC全年合作进程中具有重要意义\n重点围绕亚太及全球重大经贸问题进行探讨，并为11月APEC领导人非正式会议作经贸方面准备。"}, {"title": "1月16日上午，国家主席习近平在北京人民大会堂会见来华进行正式访问的加拿大总理卡", "detail": "尼。习近平\n就中加关系提出4点意见。一要做相互尊重的伙伴。二要做共同发展的伙伴。三要做彼此信任的伙伴。四要做\n相互协作的伙伴。"}, {"title": "1月16日宣布，邹加怡正式就任亚投行行长兼董事会主席，带领机构迈入第二个十年发展", "detail": "新阶段。自\n2016年正式运营以来，亚投行从57个创始成员发展至目前的111个成员，十年间批准361个项目，累计批准\n融资总额近700亿美元，惠及40个亚洲域内与域外成员。"}, {"title": "1月16日4时10分，我国太原卫星发射中心在山东附近海域成功发射谷神星一号海射型", "detail": "遥七运载火箭，\n搭载发射的天启星座06组卫星顺利进入预定轨道，飞行试验任务取得圆满成功。"}, {"title": "1月16日，由中国科学院紫金山天文台牵头，联合中国科学院国家天文台等国内外多家研", "detail": "究机构组成\n的研究团队在贵州平塘宣布，利用我国500米口径球面射电望远镜（“中国天眼”FAST）首次捕捉到重复快\n速射电暴（FRB）的法拉第旋转量（RM）发生剧烈跃变并随后回落的详细演化过程，为“快速射电暴起源于\n双星系统”的假说提供了关键观测证据。"}, {"title": "[公众号：橙子考公资料站提供更新]国家能源局1月17日宣布，2025年我国全社会", "detail": "用电量历史性突\n破10万亿千瓦时，达到10.4万亿千瓦时，同比增长5%。这一数字在全球单一国家中尚属首次，相当于美国全\n年用电量的两倍多，超过欧盟、俄罗斯、印度、日本四个经济体的年用电量总和。"}, {"title": "近日，农业农村部、财政部、国家发展改革委印发《国家农业现代化示范区创建工作方案》", "detail": "，《方\n案》提出，在创建目标上，到2030年累计创建认定示范区不超过500个。重点建设粮食产业、养殖业、优势\n特色产业、智慧农业、都市农业、旱作农业等6类示范区，推动有条件的示范区率先基本实现农业现代化，形\n成重点突破、梯次推进的建设格局。"}, {"title": "1月16日下午，中国航天科技集团商业火箭有限公司（以下简称“中国商火”）抓总研制", "detail": "的长征十二\n号乙运载火箭（CZ-12B），在东风商业航天创新试验区中国商火研试发射工位顺利完成静态点火试验，试验\n取得圆满成功。CZ-12B运载火箭是为满足我国低轨星座组网等商业发射需求研制的新一代四米级可重复使用\n第9页共15页\n火箭，采用两级构型及全液氧煤油动力方案，具备20吨级近地轨道运载能力。\n未来”为主题，旨在推动创新链、产业链、资金链、人才链的深度融合，构建协同共进的核聚变能创新和产\n业生态。获取后续更新及更多考试资料，请加微信：szgkzlz7\n货值42.3万亿元，体量全球最大，安全总体可控。新设综合保税区19个，新增和扩大开放口岸41个，开放合\n作步伐加快。跨境贸易业务全链条全环节实现“一网通办”，通关便利化显著提升。"}, {"title": "近日从中国汽车流通协会获悉：2025年，我国二手车市场交易规模突破2000万辆大", "detail": "关，创历史新高。\n其中，新能源二手车全年交易量达到160万辆，占全年二手车总交易量的7.9%。"}, {"title": "国家统计局1月19日发布数据显示，2025年我国国内生产总值（GDP）14018", "detail": "79亿元，首次跃上\n140万亿元新台阶，按不变价格计算，比上年增长5.0%。分季度看，一季度国内生产总值同比增长5.4%，二\n季度增长5.2%，三季度增长4.8%，四季度增长4.5%。\n十L"}, {"title": "1月19日，国家统计局发布2025年居民收入和消费支出情况。", "detail": "2025年，全国居民人均可支配收入\n43377元，比上年名义增长5.0%，扣除价格因素，实际增长5.0%。2025年，全国居民人均消费支出29476元\n比上年名义增长4.4%，扣除价格因素，实际增长4.4%。"}, {"title": "2026年1月19日15时48分，我国在海南商业航天发射场使用长征十二号运载火箭", "detail": "，成功将卫星互联\n网低轨19组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "1月19日，神舟二十号飞船返回舱在东风着陆场成功着陆。", "detail": "经现场检查确认，神舟二十号飞船返回舱\n外观总体正常，舱内下行物品状态良好，神舟二十号飞船返回任务取得圆满成功。至此，中国空间站太空应\n急行动主要任务圆满完成。"}, {"title": "国家统计局1月19日发布数据显示，2025年，市场销售规模扩大，服务零售较快增长。", "detail": "2025年社会\n消费品零售总额501202亿元，比上年增长3.7%。"}, {"title": "省部级主要领导干部学习贯彻党的二十届四中全会精神专题研讨班1月20日上午在中央党", "detail": "校（国家行\n政学院）开班。习近平指出，制定和实施五年规划是我们党治国理政一条重要经验，是中国特色社会主义制\n度一个重要政治优势，有利于实现党的领导，有利于集中力量办大事，有利于前瞻性把握战略问题，有利于\n保持事业连续性。在制定实施五年规划的长期实践中，我们党创造积累了丰富经验，包括坚持党中央集中统\n一领导，坚持从实际出发，坚持全国一盘棋，坚持发扬民主、集思广益，坚持规划法定原则等。我们要坚定\n第10页共15页\n制度自信，不断结合新的实际把这一优势发扬光大。\n习近平指出，我国人口多、市场大、产业全、发展动能强，有条件加快构建新发展格局。要坚持以国内\n大循环为主体，正确处理消费和投资、需求和供给的关系，坚持惠民生和促消费、投资于物和投资于人紧密\n结合，努力提高国民经济循环质量和效率，让内需成为经济发展的主动力。"}, {"title": "《海洋生物多样性协定》已于1月17日生效。", "detail": "对此，外交部发言人郭嘉昆20日在例行记者会上说，\n章，是多边主义的胜利。中方决定申请将协定的秘书处设在中国厦门，已于1月16日将有关决定通知联合国秘\n书长。"}, {"title": "中共中央、国务院、中央军委决定，给陈冬同志颁发“一级航天功勋奖章”，授予陈中瑞、", "detail": "王杰同\n志“英雄航天员”荣誉称号并颁发“三级航天功勋奖章”。陈冬、陈中瑞、王杰是神舟二十号载人飞行任务\n航天员。[公众号：橙子考公资料站提供更新]"}, {"title": "经过168小时满负荷试运行，国家能源集团浙江安吉电厂2号84.3万千瓦燃气机组1", "detail": "月20日正式投产，\n标志着我国单机容量最大、效率最高的燃气电厂实现全容量投产。"}, {"title": "1月21日上午，我国自主研发的3.5万吨重载列车刚刚完成世界首次自动编队驾驶试验。", "detail": "它打破了百\n年铁路货运的控制模式，未来将对我国铁路货运带来根本性的变革。"}, {"title": "近日，全球最大、起重量达2300吨的智能化桥面吊机在河北省秦皇岛天业通联重工科技", "detail": "有限公司正\n式下线，标志着我国在大型桥梁施工装备领域取得新的重大突破，为“中国基建”再添重量级“国之重器”"}, {"title": "国家能源局1月21日宣布，截至2025年12月底，我国电动汽车充电设施数量达20", "detail": "09.2万个，突破\n2000万大关，建成全球最大电动汽车充电网络，可支撑超4000万辆新能源汽车充电需求。"}, {"title": "北京市统计局1月21日发布，2025年，北京实现地区生产总值52073.4亿元，", "detail": "比上年增长5.4%。继\n上海之后，北京正式成为我国第二个GDP突破5万亿元的城市。"}, {"title": "在国务院新闻办公室1月22日举行的发布会上，农业农村部发展规划司司长陈邦勋介绍，", "detail": "农业农村部\n先后启动第二轮土地承包到期后再延长30年整乡镇、整县、整省试点，目前已覆盖了7个整省、221个整县、\n349个整乡镇，2500多万农户承包地总体顺延，让农民吃上“定心丸”。"}, {"title": "1月22日上午，国务院新闻办公室举行新闻发布会，农业农村部相关负责人介绍说，20", "detail": "25年，中国\n粮食生产克服局地干旱、洪涝、连阴雨等不利天气影响，产量达到14298亿斤、增产168亿斤，再创历史新高，\n连续两年稳定在1.4万亿斤以上。获取后续更新及更多考试资料，请加微信：Szgkzlz7\n第11页共15页"}, {"title": "1月23日，中共中央总书记习近平致电苏林，祝贺他当选越共中央总书记。", "detail": "习近平在贺电中说，中越\n是社会主义友好邻邦，是具有战略意义的命运共同体。我十分珍视中越两党两国关系，愿同总书记同志一道\n加强战略沟通，弘扬传统友谊，坚定推进社会主义事业，引领中越全面战略合作和命运共同体建设不断结出\n累累硕果，为两国人民带来更多福祉，为地区与世界和平稳定、发展繁荣作出积极贡献。"}, {"title": "从山东省政府新闻办1月23日举行的新闻发布会上获悉，2025年，山东省实现地区生", "detail": "产总值103197\n亿元，比上年增长5.5%。山东成为全国第三个、北方第一个GDP突破10万亿元的省份。"}, {"title": "1月23日上午，国家主席习近平同巴西总统卢拉通电话。", "detail": "习近平强调，当前国际形势动荡不安，中国\n和巴西作为全球南方重要成员，是维护世界和平稳定、改革完善全球治理的建设性力量，应当坚定站在历史\n正确一边，更好捍卫两国和全球南方共同利益，共同维护联合国核心地位和国际公平正义。中方愿始终做拉\n美和加勒比国家的好朋友、好伙伴，推进共建中拉命运共同体。"}, {"title": "中央军委主席习近平日前签署命令，发布《军事理论工作条例》，自2026年3月1日起", "detail": "施行。《条例》\n共7章52条，按照军委管总、战区主战、军种主建的总原则，规范明确军事理论工作的管理体制。"}, {"title": "商务部1月23日发布数据显示，2025年，全国新设立外商投资企业70392家，同", "detail": "比增长19.1%；实\n际使用外资金额7476.9亿元，同比下降9.5%。\n会展出面积约2万平方米，展出内容覆盖火箭与运载系统、卫星制造、航天应用、航天服务与配套等领域。"}, {"title": "1月19日至23日，世界经济论坛2026年年会在瑞士达沃斯举行。", "detail": "本届年会以\"对话的精神”为主题，\n旨在呼吁国际社会在复杂多变的国际局势下通过建设性交流重建信任，共同应对全球性挑战。据悉，来自全\n球130多个国家和地区近3000名不同领域的代表参加本届年会。"}, {"title": "近日，市场监管总局发布数据，2025年我国新建国家标准物质1139项，同比增长6", "detail": "1.8%。其中，国\n家一级标准物质67项，占比5.9%，同比增长21.8%；国家二级标准物质1072项，占比94.1%，同比增长"}, {"title": "2%。截至目前，我国累计建成国家标准物质19441项，为经济社会高质量发展提供有", "detail": "力支撑。"}, {"title": "1月25日凌晨，在2026年U23男足亚洲杯决赛中，中国队以0比4不敌卫冕冠军日", "detail": "本队，收获亚军，\n创参加该项赛事历史最好成绩。中国队是第六次参加U23男足亚洲杯，此前五届均止步于小组赛。"}, {"title": "近日，中共中央办公厅印发了《关于加强对村巡察工作的意见》，《意见》聚焦党中央决策", "detail": "部署在\n农村落实情况。围绕党中央关于进一步深化农村改革、扎实推进乡村全面振兴的决策部署，结合村党组织职\n能责任，重点关注保障粮食安全、巩固拓展脱贫攻坚成果、发展乡村富民产业、推进乡村建设和乡村治理等\n第12页共15页\n情况。"}, {"title": "从中国煤炭工业协会了解到，2025年全国规上煤炭产量完成48.3亿吨，同比增长1", "detail": ".2%，创历史新高。\n山西、陕西、内蒙古和新疆四省区煤炭产量占全国总产量的82%左右，四省区煤炭调出量占全国跨省区外调\n量的95%以上，对保障全国煤炭安全稳定供应发挥了重要作用。"}, {"title": "日前，中央军委印发《军队党组织选举工作规定》，自2026年2月1日起施行。", "detail": "《规定》是规范军队\n党组织选举工作的重要党内法规，对于完善军队党内选举制度，健全落实党的民主集中制，提高党组织领导\n力组织力执行力，推动全面加强军队党的领导和党的建设，为打好实现建军一百年奋斗目标攻坚战提供坚强\n组织保证，具有重要意义。\n驾驶人达5.59亿人，其中汽车驾驶人5.25亿人。2025年全国新注册登记机动车3535万辆，已连续11年超过\n3000万辆。"}, {"title": "文化和旅游部1月26日发布2025年国内居民出游数据情况。", "detail": "根据国内居民出游抽样调查统计结果，\n元，比上年同期增加0.55万亿元，同比增长9.5%。"}, {"title": "1月26日下午，中共中央总书记、国家主席习近平同越共中央总书记苏林通电话。", "detail": "习近平强调，当\n前中国正朝着全面建成社会主义现代化强国、实现第二个百年奋斗目标迈进，越南也开启民族发展新纪元。\n我们必须坚定信念、守正创新，防范化解各类风险挑战，共同捍卫社会主义事业，永葆中越关系的政治本色。\n双方要继续加强治党治国经验交流互鉴；双方要加强发展战略对接；双方要加强在国际和地区事务中的协调\n配合。获取后续更新及更多考试资料，请加微信：szgkzlz7"}, {"title": "中共中央政治局常委、国务院总理李强1月26日下午主持召开各民主党派中央、全国工商", "detail": "联负责人\n和无党派人士代表座谈会，听取对《政府工作报告》和《“十五五”规划纲要（草案）》两个征求意见稿的\n意见建议。李强强调，今年是“十五五”开局之年，外部环境不确定性上升，经济发展面临的风险挑战仍然\n不少。需要科学准确把握形势变化，正视困难，坚定信心，集中精力办好自己的事，实施更加积极有为的宏\n观政策，强化改革举措与宏观政策协同，推动经济实现质的有效提升和量的合理增长。"}, {"title": "1月27日上午，国家主席习近平在北京人民大会堂会见来华进行正式访问的芬兰总理奥尔", "detail": "波。习近\n平指出，芬兰是最早同新中国建交的国家之一。建交76年来，无论国际形势如何变化，中芬关系始终平稳发\n展，坚持相互尊重、平等相待、面向未来、合作共赢。中国和芬兰人民都具有坚韧不拔、自强不息的精神，\n第13页共15页\n双方要增进互信、加强交流、深化合作，助力各自国家发展，为两国人民带来更多福祉。"}, {"title": "1月27日，深圳市南山区八届人大六次会议开幕。", "detail": "会上宣布，2025年南山区迈入万亿城区。这也意\n味着，我国首个GDP过万亿元的地市辖区诞生。"}, {"title": "1月27日，人力资源社会保障部举行例行新闻发布会，介绍2025年人力资源和社会保", "detail": "障工作进展情\n况。会上，人力资源社会保障部政策研究司司长、新闻发言人崔鹏程介绍，截至2025年底，全国社保卡持卡\n人数13.9亿人，其中11.04亿人领用电子社保卡。"}, {"title": "1月27日，国务院召开第四次廉政工作会议，李强指出，习近平总书记在二十届中央纪委", "detail": "五次全会\n想和行动统一到习近平总书记重要讲话精神上来，深刻理解和把握反腐败斗争形势仍然严峻复杂、铲除腐败\n滋生土壤和条件任务仍然艰巨繁重的重大判断，深刻理解和把握管党治党越往后越严、一严到底的鲜明立场，\n深刻理解和把握以全面从严治党为实现“十五五”时期目标任务提供坚强保障的使命要求，坚定拥护“两个\n确立”、坚决做到“两个维护”，把全面从严治党战略方针贯彻到政府工作各方面全过程。"}, {"title": "工业和信息化部1月28日发布数据显示，截至2025年底，我国5G基站数达483.", "detail": "8万个，平均每万人\n拥有5G基站34.4个，高于“十四五”信息通信行业发展规划建设目标8.4个。"}, {"title": "1月28日从国家能源局获悉，截至2025年底，全国累计发电装机容量38.9亿千瓦", "detail": "，同比增长16.1%。\n其中，太阳能发电装机容量12.0亿千瓦，同比增长35.4%；风电装机容量6.4亿千瓦，同比增长22.9%。"}, {"title": "1月28日，国家移民管理局发布最新数据，2025年，全国移民管理机构共查验出入境", "detail": "人员6.97亿人\n次，同比上升14.2%，创历史新高，其中内地(大陆)居民3.35亿人次、港澳台居民2.79亿人次，同比分别上升"}, {"title": "1%、10.1%，外国人8203.5万人次，同比上升26.4%，免签入境外国人3", "detail": "008万人次、占入境外国人"}, {"title": "1%、同比上升49.5%。", "detail": "[公众号：橙子考公资料站提供更新]"}, {"title": "1月28日，国家主席习近平复信津巴布韦解放斗争老战士。", "detail": "习近平强调，2026年是中非开启外交关\n系70周年，也是“中非人文交流年”。70年来，中国始终是非洲民族解放和发展振兴事业的好战友、好伙伴，\n同非洲朋友相互尊重、相互支持，携手走过峥嵘岁月，共同踏上现代化新征程。中方愿以落实中非合作论坛\n北京峰会成果为契机，同非方续传统友谊，共同开创中非关系更加辉煌的未来。希望你们带动更多非洲青\n年投身中津、中非友好事业。"}, {"title": "全国统战部长会议1月28日在北京召开。", "detail": "王沪宁表示，“十五五”时期是基本实现社会主义现代化\n的关键时期，要全面把握统战工作面临的形势任务，把思想和行动统一到党中央精神上来，巩固和发展最广\n第14页共15页\n泛的爱国统一战线。要建好统战干部队伍，树立和践行正确政绩观，在笃信、务实、担当、自律上锻造过硬\n素养、过硬能力、过硬作风。\n同意中英要发展长期稳定的全面战略伙伴关系。习近平强调，中英经贸合作的本质是互利共赢。今年是中国\n十五五”开局之年，双方要拓展教育、医疗、金融、服务业互利合作，开展人工智能、生物科学、新能源\n和低碳技术等领域联合研究和产业转化，实现共同发展繁荣。"}, {"title": "国务院办公厅日前印发《加快培育服务消费新增长点工作方案》，《工作方案》提出聚焦交", "detail": "通服务、\n家政服务、网络视听服务、旅居服务、汽车后市场服务、入境消费等重点领域，从优化服务供给、推进先行\n先试、创新消费场景、加强人才培养等方面发力，激发发展活力。"}, {"title": "近日，我国科研团队通过构建位于合肥与杭州的量子探测网，大幅提升了宇宙中神秘暗物质", "detail": "的探测\n精度，从而为揭开这一宇宙之谜提供了全新路径。"}, {"title": "1月29日下午，国务院总理李强在北京人民大会堂同英国首相斯塔默共同出席中英企业家", "detail": "委员会会\n议闭幕式并分别致辞。李强指出，今年中国将开始实施“十五五”规划，未来5年经济总量将迈上新台阶，结\n构持续优化，新动能不断壮大，这也将为中英合作提供巨大空间。两国企业大有可为，可以围绕四个方面聚\n焦发力。一是做大双边贸易的“新增量”；二是打造创新发展的“新引I擎”；三是开辟三方合作的“新蓝\n海”；四是激发人文交流的“新活力”。获取后续更新及更多考试资料，请加微信：Szgkzlz7"}, {"title": "1月29日，商业航天器及应用产业链共链行动大会在上海举办，本届大会以“链聚产业合", "detail": "力共建航\n天强国”为主题。大会旨在围绕发展商业航天国家战略部署，发挥中央企业战略引领、生态构建等职能，带\n动产业链上中下游企业共谋新发展、共建新能力、共筑新生态。"}, {"title": "中共中央政治局1月30日召开会议，审议《中央政治局常委会听取和研究全国人大常委会", "detail": "、国务院\n全国政协、最高人民法院、最高人民检察院党组工作汇报和中央书记处工作报告的综合情况报告》。会议强\n调，今年是中国共产党成立105周年，是“十五五”开局之年。5家党组要以习近平新时代中国特色社会主义\n思想为指导，坚持党中央集中统一领导，不折不扣把党的二十届四中全会精神和党中央关于今年工作的决策\n部署落到实处。坚持稳中求进工作总基调，锚定“十五五”时期经济社会发展重大战略任务，努力实现良好\n开局。"}, {"title": "财政部1月30日发布数据显示，2025年，全国国有及国有控股企业营业总收入848", "detail": "886.5亿元，同\n比增长0.5%。2025年，国有企业利润总额40380.5亿元，同比下降6.3%。\n第15页共15页"}]}, {"month": "2026年2月", "year": 2026, "items": [{"title": "中共中央政治局1月30日下午就前瞻布局和发展未来产业进行第二十四次集体学习。", "detail": "习近平在听取讲\n解和讨论后发表重要讲话。他指出，培育发展未来产业，对于抢占科技和产业制高点、把握发展主动权，对\n于发展新质生产力、建设现代化产业体系，对于提高人民生活品质、促进人的全面发展和社会全面进步，都\n具有重要意义。\n习近平强调，未来产业具有前瞻性、战略性、颠覆性等特点，需要科学谋划、全局统筹。要聚焦“十五\n五＇时期我国未来产业发展的主攻方向科学论证技术路线，提升前沿技术战略预判能力。要综合考虑国家\n战略需求、技术成熟程度、要素支撑条件等因素，因地制宜、错位发展。要强化产业协同，推动未来产业同\n新兴产业、传统产业相得益彰。"}, {"title": "2026年1月31日12时01分，我国在酒泉卫星发射中心使用长征二号丙运载火箭成", "detail": "功将阿尔及利亚遥\n感三号卫星B星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。阿尔及利亚遥感三号卫星B星主\n要用于土地规划和防灾减灾领域。"}, {"title": "2026年2月1日出版的第3期《求是》杂志将发表习近平的重要文章《走好中国特色金", "detail": "融发展之路，建\n设金融强国》。文章强调，党的十八大以来，我们积极探索新时代金融发展规律，不断加深对中国特色社会\n主义金融本质的认识，不断推进金融实践创新、理论创新、制度创新，积累了宝贵经验，逐步走出—条中国\n特色金融发展之路。第—，坚持党中央对金融工作的集中统—领导。第二，坚持以人民为中心的价值取向。\n第三，坚持把金融服务实体经济作为根本宗旨。第四坚持把防控风险作为金融工作的永恒主题。第五，坚\n持在市场化法治化轨道上推进金融创新发展。第六，坚持深化金融供给侧结构性改革。第七，坚持统筹金融\n开放和安全。第八，坚持稳中求进工作总基调。\n文章指出，建设金融强国，必须加快构建中国特色现代金融体系。一是科学稳健的金融调控体系，二是\n结构合理的金融市场体系，三是分工协作的金融机构体系，四是完备有效的金融监管体系，五是多样化专业\n性的金融产品和服务体系，六是自主可控、安全高效的金融基础设施体系。\n文章指出，推动金融高质量发展、建设金融强国，要坚持法治和德治相结合，大力弘扬中华优秀传统文\n化，积极培育中国特色金融文化。一要诚实守信，不逾越底线。二要以义取利，不唯利是图。三要稳健审填，\n不急功近利。四要守正创新，不脱实向虚。五要依法合规，不胡作非为。"}, {"title": "1月31日从日地LS太阳探测工程”羲和二号”项目启动会暨科学研讨会上了解到，我国", "detail": "计划2028年至\n第1页共11页，\n1时政考点汇总划重点（每月更新）1\n2029年间，择机向日地LS点发射＂羲和二号”。2021年10月，我国成功发射首颗太阳探测科学技术试验卫\n星”羲和号”，正式步入空间探日时代。"}, {"title": "2月1日，工业和信息化部发布我国造船业最新数据。", "detail": "2025年，我国造船业三大指标继续领跑全球，\n连续16年保持世界第—。最新数据显示，2025年我国造船完工量5369万载重吨，同比增长11.4%，占全球市\n场总噩的56.1%；新接订单量10782万载重吨，占全球市场总孟的69%；截至12月末，手持订单量27442万\n载重吨，同比增长31.5%，占全球市场总盘的66.8%，手持订单盘再创历史新高。"}, {"title": "2025年，我国加快农村及偏远地区信息基础设施建设，全国所有乡镇及95％的行政村", "detail": "实现SG网络通\n达，为加快农业农村现代化、推进乡村全面振兴提供坚实支撑。"}, {"title": "近日，国家税务总局发布《关于起征点标准等增值税征管事项的公告》，《征管公告》进—", "detail": "步调整优\n化了自然人增值税起征点标准判定细则。自然人通常适用按次纳税的起征点标准。自今年起，按次纳税起征\n点标准由每次（日）销售额500元提升到1000元。"}, {"title": "近日市场监管总局会同中央空管办、国家发展改革委等十部门联合发布《低空经济标准体系", "detail": "建设指南\n(2025年版）》。指南明确，到2027年，低空经济标准体系基本建立，基本满足低空经济安全健康发展需求。\n到2030年，低空经济领域标准超过300项，结构优化、先进合理、国际茉容的低空经济标准体系基本形成，\n为低空经济安全健康发展提供有力支撑。"}, {"title": "2月2日从中国华能获悉，我国西北地区海拔最高风电项目华能阿合奇县30万干瓦风电项", "detail": "目首批\n风机成功并网。华能阿合奇县30万干瓦风电项目位于新疆克孜勒苏柯尔克孜自治州，最高海拔达3700米，是\n目前我国西北地区已建成投运的海拔最高风电项目。项目拟建设45台单机容量6.7兆瓦的风电机组，配套建设\n1座30兆瓦／60兆瓦时电化学储能站。［公众号：橙子考公资料站提供更新］"}, {"title": "据国家林业和草原局微信公众号消息，今年2月2日是第30个世界湿地日，主题是＂湿地", "detail": "与传统知识：\n致敬文化遗产＇。党的十八大以来，我国持续加强湿地生态保护修复，全国湿地面积位居亚洲第一、世界第\n四，湿地保护取得历史性成就，形成重点治理和分类保护相结合的新格局。"}, {"title": "2026年世界顶尖科学家峰会2月1日至3日在阿联酋迪拜举行，本次峰会以“基础科学", "detail": "：应对人类未\n来的挑战＇为主题，聚焦人工智能与机器学习、量子科学与纳米技术、生物技术与基因组学、数据科学与密\n码学、神经技术与脑科学以及能源与先进材料等多个关系到人类文明未来发展方向的关键领域。"}, {"title": "《现代化首都都市圈空间协同规划(2023—2035年）》2月3日公布。", "detail": "这是全国首个由中共中央、\n国务院批复的都市圈规划，也是时隔5年中共中央、国务院批复的又—部首都规划。规划科学划定约4.2万平\n第2页共11页\n方公里首都都市圈实体范围，提出构建“—核两翼、双城多点、双廊多圈＇的空间格局。"}, {"title": "2月3日上午，国家主席习近平在北京人民大会堂同来华进行国事访问的乌拉圭总统奥尔西", "detail": "举行会谈。\n习近平强调，双方要加强发展战略对接，深化经贸、金融、农牧业、基础设施建设、信息通信等合作，挖掘\n绿色发展、数字经济、人工智能、清洁能源等新兴领域合作潜力，推动经济增长转型升级。中国和乌拉圭人\n民有着天然亲近感，双方要持续深化文化、教育、体育、媒体、地方等交流，便利人员往来，促进民心相通。"}, {"title": "2026年中央—号文件2月3日发布，这是“十五五＇首个中央—号文件，也是党的十八", "detail": "大以来第14个\n指导“三农”工作的中央—号文件，文件题为《中共中央国务院关于描定农业农村现代化扎实推进乡村全面\n振兴的意见》。文件提出，农业农村现代化关系中国式现代化全局和成色。坚持农业农村优先发展，坚持城\n乡融合发展，描定农业农村现代化，以推进乡村全面振兴为总抓手，以学习运用“干万工程＇经验为引领，\n以改革创新为根本动力，提高强农惠农富农政策效能，守牢国家粮食安全底线，持续巩固拓展脱贫攻坚成果，\n提升乡村产业发展水平、乡村建设水平、乡村治理水平，努力把农业建成现代化大产业、使农村基本具备现\n代生活条件、让农民生活更加富裕美好，为推进中国式现代化提供基础支撑。"}, {"title": "《2025年国内外油气行业发展报告》2月3日在北京发布。", "detail": "报告显示，我国炼化产业高端化转型步伐\n加快，化工新材料发展迅速，高端化工材料自给率提升至80％以上。"}, {"title": "2月4日，中国社会科学院发布“2025年中国考古新成果”。", "detail": "河北阳原县新庙庄旧石器时代遗址、河\n南新郑市裴李岗石器时代遗址、河北张家口市郑家沟红山文化遗址、新疆温泉县呼斯塔青铜时代遗址、山东\n青岛市琅哪台战国秦汉时期遗址、新疆吐鲁番市巴达木东晋唐时期墓群共6个项目入选。"}, {"title": "2月4日上午，国务院新闻办公室举行新闻发布会，介绍描定农业农村现代化、扎实推进乡", "detail": "村全面振\n兴有关清况并答记者问。2025年我国入均粮食占有量达到508.9公斤，远超国际公认的400公斤的安全线，\n粮食等重要农产品供给丰富、市场平稳、储备充足。"}, {"title": "近日，2026年中央—号文件发布，文件提出，稳定发展粮油生产。", "detail": "粮食产量稳定在1.4万亿斤左右。\n坚持产量产能、生产生态、增产增收—起抓，加力实施新—轮干亿斤粮食产能提升行动，促进良田良种良机\n良法集成增效，推进粮油作物大面积提单产。"}, {"title": "2月5日，中共中央总书记、国家主席习近平复信老挝人民革命党中央总书记、国家主席通", "detail": "伦，共同\n宣布将2026年确定为＂中老友好年”并启动系列庆祝活动。"}, {"title": "2月5日，中国互联网络信息中心政策与国际合作所发布第57次《中国互联网络发展状况", "detail": "统计报告》。\n报告显示，截至2025年12月，我国网民规模达11.25亿入，互联网普及率达80.1%；生成式人工智能用户规\n第3页共11页\n模达6.02亿人，普及率达42.8%。"}, {"title": "中国机械工业联合会2月5日发布的数据显示，2025年，我国机械工业规模以上企业增", "detail": "加值同比增长\n三，增速高于全国工业和制造业2.3和1.8个百分点。"}, {"title": "近日，2026年中央—号文件发布，文件提出，培育壮大县域富民产业。", "detail": "统筹发展科技农业、绿色农\n业、质量农业、品牌农业，开发农业多种功能，推动农村一二三产业深度融合。"}, {"title": "国务院总理李强2月6日主持召开国务院第十次全体会议，李强指出，坚持政策支持和改革", "detail": "创新并举，\n更好激发市场活力，挖掘内需新增长点。要密切踉踪形势变化，突出稳就业、稳企业、稳市场、稳预期，做\n好政策预研储备，根据需要及时推出，确保全年目标任务顺利完成。"}, {"title": "国家林草局2月6日发布《中国世界自然遗产保护发展报告(1985-2025)》，这", "detail": "是我国首次针对自\n然遗产开展的全面系统评估。我国拥有世界自然遗产15项、世界自然与文化双遗产4项，总数居世界首位。"}, {"title": "近日，商务部数据显示，2025年，我国服务贸易保持稳步增长，服务进出口总额808", "detail": "23.1亿元，同\n比增长7.4%。其中，出口36267.9亿元，同比增长14.2%。"}, {"title": "工业和信息化部等八部门日前联合印发《中药工业高质量发展实施方案(2026—203", "detail": "0年）》，提出\n到2030年，中药工业全产业链协同发展体系初步形成，重点中药原料持续稳定供应能力进—步增强，数智化、\n绿色化水平明显提升，一批关键技术取得突破，产业协同创新水平显著提高。"}, {"title": "2月6日召开的国务院常务会议，研究促进有效投资政策措施。", "detail": "会议指出，要结合制定实施“十五五”\n规划，着眼于长远发展需要和构筑未来竞争优势，在基础设施、城市更新、公共服务、新兴产业和未来产业\n等重点领域深入谋划推动—批重大项目、重大工程。"}, {"title": "从有关部门获悉，2月7日，我国在酒泉卫星发射中心使用长征二号F运载火箭，成功发射", "detail": "—型可重复\n使用试验航天器。试验航天器将按计划开展可重复使用试验航天器技术验证，为和平利用太空提供技术支撑。"}, {"title": "2月7日从国家发展改革委获悉，物流运行情况显示，2025年社会物流总费用与国内生", "detail": "产总值(GDP)\n的比率降至13.9%，首次降低至14％以下，较“十三五＇末下降0.8个百分点，再创有统计以来的最好水平。"}, {"title": "2月7日，由中国科学院南海海洋研究所与中国石油大学（华东）联合研发的“南海区域海", "detail": "－气双向耦\n合智能大模型飞鱼－1.0\"发布。“飞鱼－1.0\"人工智能大模型，是在海量数据中挖掘南海海洋和大气环境\n在时间、空间上的变化规律，再依靠这些习得的变化规律，去分析、推断南海海洋和大气之间复杂又相互影\n响的动态变化过程。"}, {"title": "近日，从三峡集团获悉，全球首台20兆瓦海上风电机组在福建闽南海域顺利完成调试，成", "detail": "功并网发\n第4页共11页\n电。这是我国首次在海上完成20兆瓦超大容量风电机组吊装与调试并网，标志着我国超大容量机组研发制造、\n海上施工及运营能力再上新台阶。"}, {"title": "当地时间2月6日晚，第二十五届冬季奥林匹克运动会在意大利米兰开幕。", "detail": "这是意大利继1956年科尔\n蒂纳丹佩佐冬奥会、2006年都灵冬奥会后，第三次举办冬季奥运会。"}, {"title": "国务院总理李强日前签署国务院令，公布修订后的《中华人民共和国自然保护区条例》，自", "detail": "2026年\n3月15日起施行。规定自然保护区建设应当贯彻党和国家路线方针政策、决策部署，践行绿水育山就是金山银\n山理念，坚持以入民为中心的发展思想，坚持生态保护第—、统筹保护和发展，坚持因地制宜、突出特色，\n构建政府主导、多方参与、社会共享的机制，实现生态保护、绿色发展、民生改善相统一。"}, {"title": "2月9日，世界最大跨度双层斜拉—悬索协作体系桥梁荆州李埠长江公铁大桥南北主塔全部", "detail": "封顶，\n标志着大桥建设取得关键进展，为后续猫道及主缆架设奠定基础。荆州李埠长江公铁大桥主跨1120米，是世\n界最大跨度双层斜拉—悬索协作体系桥梁。"}, {"title": "2月9日，《江苏省人工智能与知识产权双向赋能行动方案(2026—2030年）》正", "detail": "式出台，这是全国首\n个以人工智能与知识产权双向赋能为主题的专项方案。《行动方案》以7个方面23条具体举措，提升人工智能产\n业创新保护力度、知识产权服务效率，推动人工智能与知沪予：权形成\n\"1+1>2\"的协同效应，为江苏抢占人工智能产业制高点注入强劲动力。"}, {"title": "2月10日，中国物流与采购联合会公布2025年全国物流运行数据。", "detail": "2025年全国社会物流想额368.2\n万亿元按可比价格计算，同比增长5.1%。"}, {"title": "2026年亚太经合组织(APEC)第—次高官会2月10日上午在广州开幕。", "detail": "本次会议聚焦2026年APEC\n会议主题“建设亚太共同体，促进共同繁荣＇和“开放、创新、合作＇三大优先领域，全面启动各领域各机\n制合作，深入讨论具体合作，为11月领导人非正式会议积累成果。"}, {"title": "2月9日至10日，习近平在中共中央政治局委员、北京市委书记尹力和市长殷勇陪同下，", "detail": "深入科创园\n区、养老服务街区、新春市集考察，给基层干部群众送上党中央的关怀和祝福。习近平指出，“十五五＇时\n期是基本实现社会主义现代化穷实基础、全面发力的关键时期。北京要深入贯彻党的二十届四中全会精神，\n落实党中央确定的城市战略定位，精准务实推动经济社会发展，确保率先基本实现社会主义现代化取得决定\n性进展，努力在全国发挥示范作用。"}, {"title": "2026年2月11日，在长征十号运载火箭系统低空演示验证与梦舟载人飞船系统最大动", "detail": "压逃逸飞行试\n验中，梦舟载人飞船成功实施最大动压逃逸并在海上安全溅落。11日12时20分，海上搜救分队完成返回舱搜\n第5页共11页\n索回收任务。这是我国首次在海上实施载人飞船搜索回收任务，为后续空间站应用与发展任务和载人登月任\n务积累了重要经验。"}, {"title": "在中华民族传统节日丙午马年春节即将到来之际，习近平2月11日下午在人民大会堂同各", "detail": "民主党派中\n央、全国工商联负责人和无党派人士代表欢聚—堂，共迎新春。习近平指出，过去—年，多党合作事业取得\n丰硕成果。各民主党派中央和无党派人士认真贯彻落实中共中央决策部署，扎实开展”学规定、强作风、树\n形象”主题教育，聚焦经济社会发展重点难点问题积极建言献策，为党和国家事业发展作出了新贡献。"}, {"title": "近日，中共中央宣传部等5部门联合印发《戏剧振兴三年行动计划(2026-2028年", "detail": "）》。《计划》\n提出，推动戏剧创新创造活力不断增强，剧目质量明显提升，推出一批优秀戏剧作品；戏剧人才队伍不断壮\n大，青年领军人才接续涌现；形成较为完善的戏剧创作服务、引导、组织工作机制，行业生态明显改善，人\n民群众的满意度和获得感不断提升。"}, {"title": "日前，国务院办公厅印发《关于完善全国统—电力市场体系的实施意见》，《意见》要求，", "detail": "坚持以\n习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全会精神，完整准确全面贯\n彻新发展理念，按照构建全国统—大市场、深化电力体制改革、建设新型电力系统要求，坚持全国统—、畅\n通循环，着力打破市场分割、破除区域壁垒，促进市场高效联通和有机衔接，统筹推动电力市场供需高水平\n动态平衡，着力扩大规模、改善结构、拓展功能，健全统—开放、竞争有序、安全高效、治理完善的电力市\n场体系，在确保电力系统安全可靠运行的基础上，实现市场运行畅通有序、交易规则统—高效、利益分配公\n平合理，为保障能源安全、经济社会发展和绿色低碳转型提供有力支撑。《意见》明确，到2030年基本建成\n全国统—电力市场体系，到2035年全面建成全国统—电力市场体系。"}, {"title": "2月11日，国务院以深化拓展”人工智能＋＂、全方位赋能干行百业为主题，进行第十八", "detail": "次专题学习。\n李强指出，要加快培育产业生态，优化智算资源布局，加大数、算、电、网等资源协同，推进软硬件适配，\n形成产业链上下游贯通发展的格局。"}, {"title": "2026年2月12日14时37分，我国太原卫星发射中心在广东阳江附近海域使用捷龙", "detail": "三号运载火箭，成\n功将巴基斯坦PRSC-E02卫星、港中大一号卫星、电力红外卫星A星、数天宇星03~05星、空间环境监测卫星\n共7颗卫星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。此次任务是捷龙三号运载火箭的第9\n次飞行。"}, {"title": "中国国家能源局2月12日发布消息称，2025年全国新增风电、太阳能发电装机超4.", "detail": "3亿干瓦，同比增\n长22.0%，再创历史新高。2025年，中国风电、太阳能发电发展取得新成绩。除新增风光装机规模创新高外，\n第6页共11页\n风电、太阳能发电累计并网装机达到18.4亿干瓦，占比达到47.3%，历史性超过火电。"}, {"title": "习近平近日对国家自然科学基金委员会工作作出重要指示指出，新征程上，希望你们深入学", "detail": "习贯彻\n新时代中国特色社会主义思想，抓住新一轮科技革命和产业变革历史机遇，坚持“四个面向＂的战略导向，\n强化基础研究战略性、前瞻性、体系化布局，深化科学基金改革，进—步完善资助体系、提升资助效能，推\n动营造良好科研生态，拓展国际合作空间支持广大科研人员勇攀科学高峰、产出更多原创性成果，为推进\n高水平科技自立自强、建设科技强国作出更大贡献。"}, {"title": "据中国载人航天工程办公室消息，2月13日上午，海上搜索回收分队完成长征十号运载火", "detail": "箭—级箭体\n打捞回收任务，这是我国首次在海上实施此项任务，对推进运载火箭可重复使用技术发展具有重要意义。"}, {"title": "在农历新春佳节即将到来之际，国务院总理李强2月13日下午在人民大会堂与获得202", "detail": "5年度中国政\n府友谊奖和在华工作的外国专家代表座谈交流。李强指出，中国始终坚持对外开放的基本国策，不断拓展各\n领域国际合作。希望外国专家继续致力于当好中国与世界连接的桥梁纽带，为增进理解互信、加强交流互鉴、\n实现互利共赢发挥更大作用。"}, {"title": "近日，国家电影局、商务部组织开展“电影＋“消费综合试点工作。", "detail": "根据有关省市择优选报，北京市\n朝阳区、吉林省长春市、上海市虹口区、江苏省无锡市、浙江省宁波市、福建省福州市、山东省青岛市、河\n南省郑州市、湖北省宜昌市、湖南省长沙市、广东省深圳市、重庆市两江新区、四川省成都市、陕西省延安\n市，以及江苏省昆山市、浙江省湖州市南浔区16个城市为“电影＋“消费综合试点城市。\nso、近日，中共中央办公厅印发了《党委（党组）对下级党组织”—把手”开展监督谈话工作办法》，\n开展监督谈话，应当遵循下列原则：（—)坚持党要管党、全面从严治党；（二）坚持突出重点；（三）坚\n持抓早抓小、防微杜渐；（四）坚持问题导向；（五）坚持实事求是。"}, {"title": "中共中央、国务院2月14日上午在人民大会堂举行2026年春节团拜会。", "detail": "习近平在讲话中指出，—年\n来，我们实施更加积极有为的宏观政策，进—步全面深化改革，扎实推进现代化产业体系建设，我国经济顶\n压前行、向新向优发展，展现出强大韧性和活力。扎实推进社会主义民主法治建设、文化建设、生态文明建\n设、国防和军队建设，各项事业互促共进。着力保障和改善民生，社会大局保持稳定。我们胜利召开党的二\n十届四中全会，擘画了“十五五＇发展蓝图。隆重纪念中国人民抗日战争暨世界反法西斯战争胜利80周年，\n设立台湾光复纪念日，庆祝西藏自治区成立60周年、新疆维吾尔自治区成立70周年，在粤港澳三地联合举办\n第十五届全国运动会，进—步凝聚起推进中国式现代化的磅诵力量。"}, {"title": "2月14日，国家主席习近平向非洲联盟轮值主席、安哥拉总统洛伦索和非；", "detail": "州联盟委员会主席优素福致\n，第7页共11页\n贺电，就第39届非；州联盟峰会召开，向非洲国家和人民表示热烈祝贺。习近平强调，中非开启外交关系70年\n来，双方始终风雨同舟、并肩前行。中方愿同非方—道，传承历史清谊，深化互利合作，增进相知相亲，共\n同书写新时代全天候中非命运共同体新篇章。"}, {"title": "工业和信息化部等五部门印发的《茶产业提质升级指导意见(2026—2030年）》2", "detail": "月14日对外发布，\n提出到2030年，全产业链规模达1.5万亿元，发展质量效益大幅提高，规上精制茶加工业营业收入突破2000\n亿元，基本建成丰足美好、绿色智能、国际—流的茶产业体系。"}, {"title": "2月14日，江苏勤丰船厂码头汽笛长呜，国内首艘以甲醇为单—燃料的江海直达船舶“创", "detail": "新19\"\n轮正式启航，驶往宁波舟山港。这是我国首艘15000吨级甲醇单—燃料特定航线江海直达船舶，其首航标志着\n甲醇燃料在我国航运领域的商业化应用迈出关键—步。"}, {"title": "2月16日，国家主席习近平复信美国艾奥瓦州友人并回赠新春贺卡，致", "detail": "以节日祝福。习近平表示，41年前我访问艾奥瓦州，受到你们热情接待，那些美好回忆至今仍记忆犹新。中\n美关系希望在人民，基础在民间，未来在青年，活力在地方。无论形势如何变化，中美两国人民交流合作的\n愿望不会改变，两国青少年相知相亲的清谊不会改变。"}, {"title": "2月16日出版的第4期《求是》杂志发表习近平的重要文章《当前经济工作的重点任务》。", "detail": "文章强调，\n2026年经济工作头绪多，要抓住关键、纲举目张。坚持内需主导，建设强大国内市场。清理消费领域不合理\n限制措施，释放文旅、赛事、餐饮、康养等服务消费潜力。\n文章指出，要坚持改革攻坚，增强高质量发展动力活力。制定全国统一大市场建设条例，出台地方政府\n招商引资鼓励和禁止聿项清单，综合运用产能调控、标准引领、价格执法、质量监管和反垄断、反不正当竞\n争等手段，深入整治“内卷式＇竞争，营造良好市场生态。文章指出，要坚持“双碳＇引领，推动全面绿色\n转型。协同推进降碳、减污、扩绿、增长，培强绿色发展动能。深入推进重点行业节能降碳改造，稳步推动\n煤炭和石油消费达峰。"}, {"title": "北京时间2月18日晚进行的米兰冬奥会单板滑雪男子坡面障碍技巧决赛中，22岁的中国", "detail": "选手苏翊呜\n在自己生日这—天，凭借第—轮的82.41分的成绩获得冠军，为中国代表团夺得本届冬奥会首枚金牌。"}, {"title": "当地时间2月18日，在日本参议院首相指名选举第二轮投票中，自民党总裁高市早苗获得", "detail": "过半票数，\n确认当选日本新任首相。"}, {"title": "2月22日，全球在建规模最大的混合式抽水誓能电站四川雅砦江两河口抽酱电站，迎来关", "detail": "键节\n点双突破，电站厂房开挖完成、下游水库开启混凝土浇筑。\n第8页共11页"}, {"title": "当地时间2月22日，第25届冬奥会在意大利闭幕。", "detail": "本届冬奥会，中国体育代表团共获得5金4银6铜共\n15枚奖牌，创境外参加冬奥会历史最好成绩，展现了北京冬奥会后我国冰雪运动蓬勃发展新气象。"}, {"title": "北京时间2月23日凌晨3点30分，米兰－科尔蒂纳冬奥会闭幕式在意大利维罗纳举行，", "detail": "苏翊鸣担任中\n国代表团旗手。本届冬奥会，苏翊鸣获得1金1铜，个人奥运奖牌数增加至4枚。"}, {"title": "2月23日，中共中央总书记习近平致电金正恩，祝贺他在朝鲜劳动党第九次代表大会上被", "detail": "推举为朝鲜\n劳动党总书记。习近平在贺电中说，中朝是守望相助的社会主义友好邻邦。维护好、巩固好、发展好中朝关\n系，始终是中国党和政府坚定不移的方针。"}, {"title": "国务院总理李强日前签署国务院令，公布《供水条例》，自2026年6月1日起施行。", "detail": "《条例》旨在促\n进供水事业高质量发展，保障供水安全，提升供水服务水平，更好适应经济社会发展和人民生活需要。《条\n例》共8章50条。"}, {"title": "近日，中共中央办公厅印发《关于在全党开展树立和践行正确政绩观学习教育的通知》，《", "detail": "通知》\n指出，经党中央同意，在全党开展树立和践行正确政绩观学习教育。学习教育以县处级以上领导班子和领导\n干部特别是“一把手”为重点，于2026年春节假期后启动、7月底基本结束。\n《通知》强调，学习教育要坚持聚焦主题、简约务实，不分批次、不划阶段，认真落实学习研讨、查摆\n问题、整改整治、建章立制、开门教育等工作安排。"}, {"title": "近日从人力资源社会保障部获悉，2025年我国深入实施“新八级工＂职业技能等级制度", "detail": "，全年超过\n410万人次取得高级工以上证书，超过27万人次取得技师以上证书，评聘首席技师、特级技师近3000人次，\n技术技能人才队伍建设持续加强。［公众号：橙子考公资料站】"}, {"title": "近日从中国地理信息产业协会获悉，2025年，我国发射遥感卫星120余颗，民用在轨", "detail": "遥感卫星超过\n640颗，继续稳居世界第二。"}, {"title": "中央党的建设工作领导小组2月24日召开会议，会议指出，在全党开展树立和践行正确政", "detail": "绩观学习教\n育，是贯彻落实党的二十届四中全会战略部署、确保基本实现社会主义现代化取得决定性进展的必然要求，\n是践行党的根本宗旨、穷实党的执政根基的重要举措，是巩固拓展党内集中学习教育成果、持之以恒推进全\n面从严治党的有效途径，对于推进党和国家事业、对于推进全面从严治党意义重大。"}, {"title": "2月25日下午，国家主席习近平在北京钓鱼台国宾馆会见来华进行正式访问的德国总理默", "detail": "茨。习近平\n对下—步中德关系发展提出三点意见。—是要做相互支持的可靠伙伴。二是要做开放互利的创新伙伴。三是\n要做相知相亲的人文伙伴。习近平强调，面对加速演进的世界百年变局，各国应该风雨同舟、命运与共。中\n第9页共11页\n德应坚持联合国的核心地位，重振联合国的主导作用，带头做多边主义的维护者、国际法治的践行者、自由\n贸易的捍卫者、团结协作的倡导者。"}, {"title": "2月25日下午，国务院总理李强在北京人民大会堂同德国总理默茨共同出席中德经济顾问", "detail": "委员会座谈\n会。李强指出，目前中德经济都呈现回升向好势头。“十五五”时期，两国经贸合作将迎来更加广阔的空间。\n中德经济、产业优势互补的基本格局没有变，合作面远大于竞争面，完全可以通过塑造良性的竞合关系，更\n好地携手发展。双方可以重点聚焦三个方面协同发力，实现更高水平的互利共赢。一是做强传统合作的基本\n盘。二是把握未来发展的新机遇。三是营造投资兴业的好环境。"}, {"title": "国家林草局最新数据显示：目前全国森林总面积达36.14亿亩；", "detail": "其中时期，我国造林1.85亿亩，\n“十四五”面积与福建省相近，成为全球增绿最多最快的国家。"}, {"title": "水利部近日印发《关于加强重大引调水工程受水区落实节水优先的意见》，意见提出，到2", "detail": "030年，\n节水评价全过程管理逐步完善，受水区万元地区生产总值用水量、万元工业增加值用水量、农田灌溉水有效\n利用系数等优于国内同类地区平均水平；到2035年，受水区水资源总量管理和全面节约制度更加完善，水资\n源节约集约利用效率达到国内先进水平，形成与中国式现代化相适应的水资源集约安全利用新格局。"}, {"title": "2月26日从市场监管总局获悉，2025年全国新设经营主体2574.5万户。", "detail": "其中，新设企业950万户，\n新设个体工商户1619.4万户。"}, {"title": "2月26日从国家管网集团获悉，我国华北地区重要能源大动脉陕京管道系统累计输气量突", "detail": "破\n8000亿立方米。陕京管道系统是我国天然气”全国一张网”的重要组成部分，包括陕京一线、二线、三线和\n四线等，总里程达5599公里。通过整合长庆油田、中亚管道气及液化天然气资源，陕京管道系统年输气能力\n达800亿立方米。"}, {"title": "按照党中央有关规定，中央政治局委员、书记处书记，全国人大常委会、国务院、全国政协", "detail": "党组成\n员，最高人民法院、最高人民检察院党组书记近期就2025年度工作向党中央和习近平总书记书面述职。习近\n平审阅述职报告并提出重要要求。习近平强调，今年是中国共产党成立105周年，是“十五五＇开局之年，要\n严格落实中央八项规定及其实施细则精神，始终头脑清醒、怀德自重，在笃信、务实、担当、自律上当表率、\n作示范。"}, {"title": "近日，中国科学院青岛生物能源与过程研究所研究团队在—种新型太阳能电池材料上，实现", "detail": "了超过\n15％的光电转换效率，并获得了国际权威机构认证。"}, {"title": "中共中央政治局2月27日召开会议，讨论国务院拟提请第十四届全国人民代表大会第四次", "detail": "会议审查的\n第10页共11页\n中华人民共和国国民经济和社会发展第十五个五年规划纲要草案稿和审议的《政府工作报告》稿。会议认为，\n“十五五＇时期是基本实现社会主义现代化穷实基础、全面发力的关键时期。在党中央领导下科学编制实施\n“十五五＇规划纲要，努力巩固拓展优势、破除瓶颈制约、补强短板弱项，对于推动我国经济社会高质盂发\n展为基本实现社会主义现代化奠定更加坚实的基础，具有重大意义。\n会议强调，推动”十五五＇时期经济社会发展，要坚持稳中求进工作总基调，坚持以经济建设为中心，\n以推动高质量发展为主题，以改革创新为根本动力，以满足人民日益增长的美好生活需要为根本目的，以全\n面从严治党为根本保障，推动经济实现质的有效提升和量的合理增长，推动人的全面发展、全体人民共同富\n裕迈出坚实步伐，确保基本实现社会主义现代化取得决定性进展。\n会议指出，做好今年政府工作，要坚持稳中求进工作总基调，统筹国内国际两个大局，更好统筹发展和\n安全，实施更加积极有为的宏观政策，增强政策前瞻性针对性协同性，持续扩大内需、优化供给，做优增星、\n盘活存量，因地制宜发展新质生产力，纵深推进全国统—大市场建设，持续防范化解重点领域风险，看力稳\n就业、稳企业、稳市场、稳预期，推动经济实现质的有效提升和量的合理增长，保持社会和谐稳定，实现\n“十五五”良好开局。"}, {"title": "2月27日，国务院新闻办公室举行例行吹风会，介绍2025年国务院部门办理全国人大", "detail": "代表建议和全\n国政协提案工作有关情况。2025年，国务院各部门共承办全国人大代表建议8754件，全国政协提案4868件，\n分别占建议、提案总数的95.6%,97.3%，均已按时办结。"}, {"title": "2月27日，中国载人航天工程办公室发布消息，2026年，中国载人航天工程将深化推", "detail": "进空间站应用\n与发展和载人月球探测两大任务。目前，中国空间站在轨运行稳定，效益发挥良好。2026年，中国载人航天\n工程计划实施神舟二十三号、神舟二十四号载人飞行任务和天舟十号货运飞船补给任务，来自港澳地区的航\n天员有望最早于今年执行空间站飞行任务，神舟二十三号飞行乘组1名航天员将开展—年期驻留试验。2026年，\n将全力推进文昌航天发射场登月任务相关配套设施设备建设，以及测控通信、着陆场等地面支持系统各项目\n建设工作。\n第11页共11页"}]}, {"month": "2026年3月", "year": 2026, "items": [{"title": "国家统计局2月28日发布《2025年国民经济和社会发展统计公报》。", "detail": "数据显示，2025年，我国国\n内生产总值为1401879亿元，比上年增长5.0%，圆满完成预期目标任务。\n2025年年末全国人口140489万人，比上年末减少339万人，其中城镇常住人口95380万人。年末全\n国常住人口城镇化率为67.89%，比上年末提高0.89个百分点。\n全年全国居民人均可支配收入43377元，比上年增长5.0%，扣除价格因素，实际增长5.0%。全年全\n国居民人均消费支出29476元，比上年增长4.4%，扣除价格因素，实际增长4.4%。"}, {"title": "国家知识产权局数据显示：我国国内有效发明专利达532万件，成为世界上首个国内有效", "detail": "发明专\n利数量突破500万件的国家。“十四五”时期，我国国内有效发明专利数量持续增长，每万人口高价值发\n明专利拥有量达16件。截至2025年，我国发明专利申请量已连续多年位居全球第一，成为名副其实的专\n利大国。"}, {"title": "近日，教育部印发《关于全面推进健康学校建设的指导意见》，《意见》提出健康学校建设", "detail": "的4\n点主要举措。一是持续推进学校健康教育。二是深化学校卫生管理体制改革。三是提高学校健康管理能力。\n四是优化学校健康空间环境。"}, {"title": "国家统计局2月28日发布的2025年国民经济和社会发展统计公报显示，2025年我", "detail": "国节能降碳成效\n显著，初步测算，扣除原料用能和非化石能源消费量的万元GDP能耗比上年下降5.1%，万元GDP二氧化\n碳排放下降5.0%。"}, {"title": "3月1日出版的第5期《求是》杂志发表习近平的重要文章《让愿担当、敢担当、善担当蔚", "detail": "然成\n风》。文章强调，实干兴邦，空谈误国。把党的二十大描绘的宏伟蓝图变成美好现实，需要各级领导干部\n担当作为。新征程上，不可能都是平坦的大道，我们将会面对许多重大挑战、重大风险、重大阻力、重大\n矛盾，领导干部必须有强烈的担当精神。各级领导干部要以身许党、夙夜在公，以时时放心不下的责任感、\n积极担当作为的精气神为党和人民履好职、尽好责。\n文章指出，干部敢于担当作为，这既是政治品格，也是从政本分。要以对党忠诚、为党分忧、为党尽\n职、为民造福的政治担当，以守土有责、守土负责、守土尽责的责任担当，面对大是大非敢于亮剑，面对\n第1页共19页\n矛盾敢于迎难而上，面对危机敢于挺身而出，面对失误敢于承担责任，面对歪风邪气敢于坚决斗争。\n文章指出，领导干部不仅要有担当的宽肩膀，还得有成事的真本领。既要大胆讲政治，又要善于讲政\n治；既要矢志抓发展，又要善于抓发展；既要勇于抓改革，又要善于抓改革；既要敢于直面予盾和问题\n又要善于化解矛盾和问题；既要有想干事、真干事的自觉，又要有会干事、干成事的本领。\n》\n名和全国“两优一先”推荐工作的通知》。\n《通知》指出，党中央决定，在中国共产党成立105周年之际，以中共中央名义颁授“七一勋章”，\n表彰全国优秀共产党员、全国优秀党务工作者和全国先进基层党组织。"}, {"title": "经中央军委批准，全军3月1日起，制发启用《中国人民解放军预备役人员证》，以往制发", "detail": "的《中\n国人民解放军预备役军官证》即行废止。《预备役人员证》为本芯证件式样，具有较高的防伪性和通识度\n是证明预备役人员身份的有效证件，证件号码为系统生成的唯一身份号码，发给《中华人民共和国预备役\n人员法》颁布施行后，在中国人民解放军依法服预备役的预备役军官、预备役军士和预备役兵。"}, {"title": "3月2日，2025年“大国工匠年度人物”宣传活动正式揭晓10位年度人物及40位提", "detail": "名人选。李晓\n宝、朱先波、孟祥志、何光华、唐世彪、管益辉、龙卫国、刘松柏、郭吉平、樊再轩光荣当选2025年\n“大国工匠年度人物”。"}, {"title": "国家能源局发布的数据显示：截至2025年底，我国可再生能源总装机达到23.4亿千", "detail": "瓦。\n。\"十四\n五”时期，我国建成全球最大、发展最快的可再生能源体系，可再生能源装机占比由40%提升至60%左右。"}, {"title": "近日，中国科协、教育部联合印发《关于进一步加强高等学校科普工作的意见》，《意见》", "detail": "明\n确了高校科普工作的总体目标：到2030年，实现高校科普工作全覆盖，高校科普工作体系更加完善，高\n校科普地位作用更加凸显，科学素质和能力培养导向更加鲜明，高校社会化科普服务效能更加彰显，服务\n国家创新驱动发展的贡献度进一步提升。"}, {"title": "2026年3月3日是第13个“世界野生动植物日”，今年全球主题为“药用芳香植物：", "detail": "守护健康、\n遗产和生计”，中国主题为“保护野生植物开创健康未来”。"}, {"title": "近日，国际超导材料探索领域最高奖项一马蒂亚斯奖正式揭晓，中国科学院物理研究所靳常", "detail": "青研究员凭借在超导新材料领域的一系列开创性发现斩获该奖项，成为2026年全球唯一获此殊荣的学者，\n彰显了中国在国际超导材料研究领域的重要贡献。此前，中国科学院物理研究所赵忠贤院士、中国科学技\n第2页共19页\n术大学陈仙辉院士也曾获该奖项"}, {"title": "工业和信息化部等六部门日前印发关于促进光伏组件综合利用的指导意见，提出到2027", "detail": "年，光\n域的应用规模进一步扩大，培育一批废旧光伏组件综合利用骨干企业，光伏组件综合利用量累计达到25\n万吨。"}, {"title": "据国家能源局消息，2025年我国一次能源生产总量达到51.3亿吨标准煤，首次突破", "detail": "50亿吨大关，\n能源保供成效是”十四五”最好的一年。\n全、推动能源结构优化和绿色低碳发展发挥了重要作用。塔里木油田是西气东输主力气源地，也是我国最"}, {"title": "3月4日，十四届全国人大四次会议大会发言人娄勤俭说，全国人大常委会深入推进科学立", "detail": "法、\n民主立法、依法立法。十四届全国人大三次会议以来，共审议法律、法律解释、决定草案40件，通过其\n中24件，包括制定法律6件，修改法律14件，通过法律解释1件、有关法律问题和重大问题的决定3件。"}, {"title": "【公众号：橙子考公资料站】中国人民政治协商会议第十四届全国委员会第四次会议3月4", "detail": "日下\n午在人民大会堂开幕。王沪宁代表政协第十四届全国委员会常务委员会，向大会报告工作。王沪宁总结了\n机结合，坚持人民政协性质定位，坚持围绕中心、服务大局，充分发挥专门协商机构作用。\n王沪宁表示，2026年是“十五五”开局之年，人民政协要坚持以习近平新时代中国特色社会主义思\n想为指导，深入贯彻中共二十大和二十届历次全会精神，认真落实中共二十届四中全会部署，贯彻落实习\n近平总书记关于加强和改进人民政协工作的重要思想，坚持和完善中国共产党领导的多党合作和政治协商\n制度，坚持人民政协性质定位，坚持团结和民主两大主题，坚持聚焦党和国家中心任务履职尽责，组织参\n加人民政协的各党派团体和各族各界人士，为实现“十五五”良好开局广泛凝聚人心、凝聚共识、凝聚智\n慧、凝聚力量。"}, {"title": "农业农村部近日印发《关于开展“精准用药提质增效”行动深入推进农药科学安全使用工作", "detail": "的\n指导意见》，全面部署“十五五”期间农药科学安全使用工作，《意见》指出，按照统筹推进“科技农业、\n绿色农业、质量农业、品牌农业”要求，坚持“预防为主、综合防治”植保方针和“保产与控药、产量与\n第3页共19页\n质量、生产与生态、安全与增效并重”的工作原则，立足生产实际、统筹多元需求，大力推进精准用药、\n提质增效，为保障国家粮食安全、农产品质量安全、生态安全和人畜健康安全提供有力支撑。"}, {"title": "3月3日从长江委获悉，自2011年3月1日修订后的《中华人民共和国水土保持法》施", "detail": "行15年来，\n长江委和流域水利部门统筹推进山水林田湖草沙一体化保护和系统治理，长江流域水土流失面积累计减少"}, {"title": "42万平方公里，相当于三个恩施州的面积。", "detail": "数据显示，与第一次全国水利普查数据相比，2025年长江"}, {"title": "69%。水土流失面积和强度实现“双降”。", "detail": "获取后续更新及更多考试资料，请加微信：Szgkzlz7"}, {"title": "第十四届全国人民代表大会第四次会议3月5日上午在北京人民大会堂并幕。", "detail": "根据会议议程，国\n务院总理李强代表国务院向大会作政府工作报告。报告共分四个部分：一、2025年工作回顾；二、“十\n五五”时期主要目标和重大任务；三、2026年经济社会发展总体要求和政策取向；四、2026年政府工作\n任务。\n报告指出，一年来主要做了以下工作：一是实施更加积极有为的宏观政策，着力稳定经济运行；二是\n坚持创新驱动发展，建设现代化产业体系；三是进一步深化改革开放，畅通国民经济循环；四是统筹推进\n新型城镇化和乡村全面振兴，促进城乡区域协调发展；五是切实抓好民生保障，积极发展社会事业；六是\n加快美丽中国建设，推动绿色低碳发展；七是持续加强政府建设，创新和完善社会治理。\n报告指出，一年来，我国经济顶压前行、展现强大韧性。经济运行总体平稳、稳中有进，国内生产总\n值增长5%，总量达到140.19万亿元。就业总体稳定，城镇新增就业1267万人，城镇调查失业率平均为\n5.2%。"}, {"title": "3月5日，十四届全国人大四次会议首场“部长通道”在人民大会堂举行，科技部部长阴和", "detail": "俊回\n答总台记者提问。阴和俊表示，我国科技事业快速发展，科技实力跃上新台阶，创新指数排名上升至全球\n第10。2025年，全社会研发投入超过3.92万亿元，强度达到2.8%。基础研究投入接近2800亿元，占比\n达7.08%，首次破7，创历史新高。"}, {"title": "3月5日，2026年中央和地方财政预算草案报告正式发布，我国2026年国防支出预", "detail": "算定为\n19095.61亿元人民币，同比增长7%，较2025年7.2%的增速略有下调。"}, {"title": "2026年政府工作报告提出，今年发展主要预期目标是：经济增长4.5%－5%，在实", "detail": "际工作中努\n力争取更好结果；城镇调查失业率5.5%左右，城镇新增就业1200万人以上；居民消费价格涨幅2%左右；\n第4页共19页\n碳排放降低3.8%左右。"}, {"title": "3月5日，位于山西的我国最大煤岩气田一大吉气田年产能突破40亿立方米，产量占比超", "detail": "全国\n煤岩气总产量的四分之三以上，成为我国天然气产量增长的重要接替资源。"}, {"title": "3月5日下午，习近平参加他所在的十四届全国人大四次会议江苏代表团审议。", "detail": "习近平指出，发\n展新质生产力对于推动高质量发展、增强经济竞争力至关重要，江苏这方面基础较好，要努力走在前列。\n要一体推进教育科技人才发展，力争在加强原始创新和关键核心技术攻关、抢占科技制高点上实现新突破\n在促进创新链产业链资金链人才链深度融合、推动科技成果高效转化应用上探索新途径，在优化提升传统\n产业、培育壮大新兴产业、超前布局未来产业上开创新局面，在进一步深化改革、破除制约新质生产力发\n展的体制机制障碍上取得新成果\n习近平强调，管党治党越有效，经济社会发展的保障就越有力。要认真组织开展树立和践行正确政绩\n观学习教育，引导广大党员干部落实“立党为公、为民造福、科学决策、真抓实干”总要求，创造经得起\n实践、人民、历史检验的实绩。"}, {"title": "3月6日，由我国自主设计研发的25000方舱容等级超大型自航耙吸挖泥船完成下水，", "detail": "进入码头\n系泊建造阶段，这艘船也是我国首艘采用分布式泵舱设计的超大型自航耙吸挖泥船。"}, {"title": "【公众号：橙子考公资料站】3月6日下午，习近平看望参加全国政协十四届四次会议的农", "detail": "工党、\n九三学社、医药卫生界、社会福利和社会保障界委员，并参加联组会，听取意见和建议。习近平强调，我\n国是社会主义国家，是人口规模巨大、城乡区域差距仍然较大的发展中国家。建设健康中国，必须坚持从\n我国国情出发，坚定不移走中国特色卫生与健康发展道路，坚定不移贯彻新时代卫生与健康工作方针。\n习近平指出，建设健康中国是一项系统工程。面对人民群众日益增长的多元化卫生健康需求，必须突\n出重点，紧紧抓住那些惠及面广、牵一发而动全身的工作，在健全公共卫生体系、建设优质高效医疗服务\n体系、倡导健康文明生活方式等方面集中力量和资源、采取有效措施加以推动，不断取得新的成效。"}, {"title": "3月6日，我国自主设计建设的亚洲最大圆筒型“海上油气工厂”", "detail": "开平南油田开发项目圆筒\n型浮式生产储卸油装置在青岛开工建造。"}, {"title": "当地时间3月6日晚，第14届冬季残疾人奥林匹克运动会开幕式在意大利维罗纳圆形竞技", "detail": "场举行。\n中国体育代表团旗手是高山滑雪运动员刘思彤和单板滑雪运动员纪立家。\n第5页共19页"}, {"title": "国家卫生健康委主任雷海潮3月7日在十四届全国人大四次会议民生主题记者会上说，20", "detail": "25年中"}, {"title": "3月7日下午，习近平出席十四届全国人大四次会议解放军和武警部队代表团全体会议并发", "detail": "表重\n要讲话。习近平强调，“十五五”时期要如期实现建军一百年奋斗目标、高质量推进国防和军队现代化，\n必须坚持好、运用好、发展好政治建军这个重要法宝，毫不动摇坚持和加强党对军队绝对领导，充分发挥\n政治建军特有优势，凝心聚力推动国防和军队现代化行稳致远。\n习近平指出，要加强革命化专业化人才队伍建设，坚持不懈用党的创新理论铸魂育人，打牢官兵听党\n话、跟党走的思想根基，确保现代化武器装备掌握在革命化人才队伍手中。要完善促进人才发展的制度和\n条件，体系推进联合作战指挥、新型作战力量、高层次科技创新、高水平战略管理“四类人才”培养，实\n现人的能力素质同强军实践协调发展。"}, {"title": "在“三八”国际妇女节来临之际，中央宣传部、全国妇联向全社会发布2026年“最美巾", "detail": "帼奋斗\n者”先进事迹。兰臻、朱蓓薇、祝雪兰、张玉花、张冬香、贺红梅、韩丽、贺娇龙、陈玉文、任萍萍等\n10位同志光荣入选。"}, {"title": "2026年政府工作报告报告指出，继续实施更加积极的财政政策。", "detail": "今年赤字率拟按4%左右安排\n赤字规模5.89万亿元、比上年增加2300亿元。一般公共预算支出规模将首次达到30万亿元、比上年增加\n约1.27万亿元。拟发行超长期特别国债1.3万亿元，持续支持“两重”建设、“两新”工作等。"}, {"title": "十四届全国人大四次会议3月9日上午在北京人民大会堂举行第二次全体会议，赵乐际委员", "detail": "长向\n特色社会主义法治体系、建设更高水平的社会主义法治国家，紧紧围绕中国式现代化建设依法履职、担当\n尽责，各方面工作取得新的进展和成效。一是加强宪法实施和监督，维护国家法治统一。二是加强立法工\n作，以高质量立法服务和保障改革发展。三是履行监督职责，充分发挥人大监督在党和国家监督体系中的\n重要作用。四是深化和拓展代表工作，更好发挥人大代表作用。五是发挥人大对外交往特点优势，主动服\n务国家外交大局。六是全面加强自身建设，不断提高依法履职能力和水平。\n强领导下，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维\n护\"，坚持党的领导、人民当家作主、依法治国有机统一，发展全过程人民民主，坚持好、完善好、运行\n第6页共19页\n好人民代表大会制度，稳中求进推动人大工作高质量发展，为实现“十五五”良好开局作出应有贡献。"}, {"title": "3月9日，十四届全国人大四次会议在北京人民大会堂举行第二次全体会议。", "detail": "最高人民法院院长\n张军作最高人民法院工作报告。张军在报告中回顾了2025年工作：以高质量司法保障高水平安全；以高\n质量司法服务高质量发展；以高质量司法守护高品质生活；以高质量司法助力高水平开放；规范司法权力\n运行：自觉接受各方面监督。\n张军在报告中表示，2026年，人民法院要坚持以习近平新时代中国特色社会主义思想为指导，深入\n贯彻习近平法治思想，坚持党中央集中统一领导，坚定法治自信，更加注重法治与改革、发展、稳定相协\n同，更加注重保障和促进社会公平正义，加强新时代审判工作，为实现“十五五”良好开局提供有力司法\n服务和保障。忠诚履职，做深做实为大局服务、为人民司法；守正创新，健全公正司法体制机制；严管厚\n爱，锻造堪当重任的新时代法院铁军，凝心聚力，实干担当，为建设更高水平的社会主义法治国家作出新\n的更大贡献。获取后续更新及更多考试资料，请加微信：szgkzlz7"}, {"title": "3月9日，十四届全国人大四次会议在北京人民大会堂举行第二次全体会议。", "detail": "最高人民检察院检\n察长应勇作最高人民检察院工作报告。应勇回顾了2025年工作：贯彻总体国家安全观，推进更高水平平\n安中国建设；完整准确全面贯彻新发展理念，服务高质量发展；坚持民生为大，依法维护人民权益；强化\n检察监督，促进公平正义；强化接受监督意识，确保检察权始终在法治轨道上运行；以党的政治建设为统\n领，切实加强过硬检察队伍建设。\n应勇在报告中指出，2026年，全国检察机关要坚持以习近平新时代中国特色社会主义思想为指导，\n深入学习贯彻习近平法治思想，更加注重法治与改革、发展、稳定相协同，更加注重保障和促进社会公平\n正义，履行好国家法律监督机关职责。"}, {"title": "【公众号：橙子考公资料站】当地时间3月9日，总台记者获悉，伊朗专家会议确定新任伊", "detail": "朗最\n高领袖人选为穆杰塔巴·哈梅内伊。公开资料显示，穆杰塔巴·哈梅内伊出生于1969年，是已故伊朗最高领\n袖阿里·哈梅内伊的次子。根据伊朗宪法，最高领袖几乎拥有对各种重大事务的最终决定权，并担任伊朗\n武装力量最高统帅。\n张晓刚表示，2026年全国一般公共预算安排国防支出1.94万亿元，比上年执行数增长6.9%，其中：中央\n本级支出1.91方亿元，比上年执行数增长7%。\n第7页共19页"}, {"title": "我国首艘自主设计建造的集成式大型压裂工程船一一“海洋石油696”3月10日在浙江", "detail": "舟山正式\n交付，填补了我国海上油气压裂增产技术与工程装备的空白，对提升我国海洋油气开发能力、保障国家能\n源安全具有重要意义。"}, {"title": "3月10日上午，最高人民检察院召开“‘四大检察’工作白皮书(2025)”新闻发布", "detail": "会。会上介绍，\n最高检党组副书记、常务副检察长童建明表示，2025年，全国检察机关依法充分履行法律监督职责，共\n件，公益诉讼检察案件13.6万件。"}, {"title": "日前，国务院办公厅印发《关于加强基层消防工作的意见》，《意见》指出，坚持预防为主", "detail": "、\n防消结合，分级负责、属地为主，构建党委和政府组织领导、消防牵头、部门协同、县乡一体、群防群治\n的基层消防工作格局。"}, {"title": "3月10日，世界首台大唐郵城630摄氏度超超临界二次再热国家电力示范项目完成单体", "detail": "调试工作，\n标志着该项目建设取得重要阶段性成果，即将转入机组点火启动阶段。同时，也将成为大唐山东公司上半\n年冲刺装机容量突破干万的关键节点项目。"}, {"title": "3月11日上午，中国人民政治协商会议第十四届全国委员会第四次会议在北京人民大会堂", "detail": "闭幕。\n王沪宁在讲话中说，全国政协十四届四次会议是一次高举旗帜、凝心聚力、求实奋进、风清气正的大会，\n生动展现了广大政协委员为国履职、为民尽责的责任担当，充分彰显了社会主义协商民主的独特优势和生\n机活力\n王沪宁表示，2026年是“十五五”开局之年，中国共产党正带领亿万人民满怀信心行进在中国式现\n代化新征程上。人民政协要立足自身性质定位和职责使命，坚持中国共产党的领导，加强理论武装，更好\n发挥人民政协的政治组织作用、更好发挥人民政协的建言资政作用、更好发挥人民政协的凝心聚力作用\n为“十五五”开好局、起好步广泛凝聚人心、凝聚共识、凝聚智慧、凝聚力量。"}, {"title": "中国建材集团3月11日在北京发布我国自主研发的SYT80（T1200级）超高强度", "detail": "碳纤维。这一研\n发成果标志着我国在超高强度碳纤维生产领域实现了重大跨越。"}, {"title": "第二届核能峰会当地时间3月10日在法国巴黎举行。", "detail": "来自30多个国家的国家元首、政府首脑或高\n峰会联合声明。\n第8页共19页"}, {"title": "3月12日下午，第十四届全国人民代表大会第四次会议在北京人民大会堂闭幕。", "detail": "赵乐际说，制定\n和实施五年规划，是中国共产党治国理政一条重要经验，是中国特色社会主义制度一个重要政治优势。\n具有重大意义。\n赵乐际指出，我们要深入学习贯彻党的二十大和二十届历次全会精神，认真落实四中全会部署，深刻\n认识党中央关于”十五五”时期的战略定位，准确把握“十五五”时期经济社会发展的指导思想、重要原\n则、目标任务、政策举措，按照本次大会部署安排，扎实有效做好各项工作，坚定不移办好自己的事，努\n力实现“十五五”良好开局，一步一步把宏伟愿景变成美好现实。"}, {"title": "【公众号：橙子考公资料站】3月12日下午，第十四届全国人民代表大会第四次会议在北", "detail": "京人民\n大会堂闭幕。会议表决通过了关于国民经济和社会发展第十五个五年规划纲要的决议。决议指出，会议要\n协调推进“四个全面”战略布局，统筹国内国际两个大局，完整准确全面贯彻新发展理念，加快构建新发\n展格局，坚持稳中求进工作总基调，坚持以经济建设为中心，以推动高质量发展为主题，以改革创新为根\n本动力，以满足人民日益增长的美好生活需要为根本目的，以全面从严治党为根本保障，推动经济实现质\n的有效提升和量的合理增长，推动人的全面发展、全体人民共同富裕迈出坚实步伐，确保基本实现社会主\n义现代化取得决定性进展。\n况公报显示，2025年全国完成营造林356.3万公顷、退化草原修复治理492.7万公顷，森林覆盖率达"}, {"title": "09%、林草覆盖率超56%、森林蓄积量达209.88亿立方米。", "detail": ""}, {"title": "近日，国家主席习近平复信法国普罗旺斯－阿尔卑斯－蓝色海岸大区国际学校中文班师生，", "detail": "向\n他们和全校师生致以良好祝愿。习近平强调，欢迎你们和更多法国、欧洲青少年到中国学习、访问、旅游，\n亲身了解体验真实立体、开放进步的中国，使中文成为伴随你们人生成长的朋友。"}, {"title": "2026年3月12日下午，十四届全国人大四次会议高票表决通过了《中华人民共和国生", "detail": "态环境法\n典》。这是我国继民法典之后，第二部以“法典”命名的法律，旨在用最严格制度、最严密法治保护生态\n环境、推动绿色发展。生态环境法典共5编、1242条，各编依次为：总则、污染防治、生态保护、绿色低\n碳发展、法律责任和附则。生态环境法典将自2026年8月15日起施行。环境保护法等10部法律同时废止。\n第9页共19页"}, {"title": "据中广核发布的消息，3月12日，长三角地区首台“华龙一号”核电机组一一浙江三澳核", "detail": "电项目\n1号机组首次并网成功，发出第一度电，标志着该机组正式具备向电网输入电力的能力，预计于今年上半\n年正式投产发电，助力长三角地区绿色低碳转型。"}, {"title": "2026年3月13日3时48分，我国在海南商业航天发射场使用长征八号甲运载火箭，", "detail": "成功将卫星互\n联网低轨20组卫星发射升空，卫星顺利进入预定轨道，发射任务获得圆满成功。"}, {"title": "3月13日，自然资源部发布《2025年中国海洋经济统计公报》。", "detail": "初步核算，2025年全国海洋生\n产总值110180亿元，比上年增长5.5%，占国内生产总值比重为7.9%，比上年高0.1个百分点。"}, {"title": "《中华人民共和国民族团结进步促进法》已由中华人民共和国第十四届全国人民代表大会第", "detail": "四\n次会议于2026年3月12日通过，自2026年7月1日起施行。"}, {"title": "2026年3月13日6时33分，长征二号丁运载火箭在西昌卫星发射中心点火起飞，随", "detail": "后将试验三十\n号卫星03、04星送入预定轨道，发射任务取得圆满成功。该卫星主要用于对地观测技术试验验证。"}, {"title": "3月14日从交通运输部获悉，2026年春运40天（2026年2月2日至3月13日", "detail": "），全社会跨区域人\n员流动量为94.1亿人次，比2025年春运增长4.3%，创历史新纪录。"}, {"title": "【公众号：橙子考公资料站】近日，055型导弹驱逐舰东莞舰、安庆舰同步列装东部战区", "detail": "海军\n并开展首次海上实战化训练。至此，我国055型导弹驱逐舰列装数量达到10艘。055型驱逐舰是我国自主\n研制建造的吨位最大、技术最先进、综合作战能力最强的方吨驱逐舰，集先进雷达、通用垂发、综合射频\n于一体。"}, {"title": "3月15日，中国体育代表团宣布，越野滑雪和冬季两项男运动员蔡佳云、轮椅冰壶女运动", "detail": "员王蒙\n将担任米兰冬残奥会闭幕式中国体育代表团旗手。"}, {"title": "2026年3月15日21时22分，我国在太原卫星发射中心使用长征六号改运载火箭，", "detail": "成功将遥感五\n十号02星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。遥感五十号02星主要用于国土普\n查、农作物估产和防灾减灾等领域。获取后续更新及更多考试资料，请加微信：Szgkzlz7"}, {"title": "3月16日出版的第6期《求是》杂志将发表习近平的重要文章《推动海洋经济高质量发展", "detail": "》。文\n章指出，大的思路上，要更加注重创新驱动，尽快突破关键核心技术，推动海洋科技实现高水平自立自强；\n更加注重高效协同，坚持陆海统筹、山海联动，增强协同发展合力；更加注重产业更新，推动海洋传统产\n业转型升级，大力发展海洋新兴产业，积极培育海洋未来产业，建设现代海洋产业体系；更加注重人海和\n第10页共19页\n谐，统筹海洋资源开发和保护，建设可持续的海洋生态环境，形成人海良性互动的新格局；更加注重合作\n共赢，主动参与全球海洋治理，共同和平利用海洋能源资源，坚决维护我国领土主权和海洋权益。\n文章指出，具体工作上，要重点抓好6个方面。第一，加强顶层设计和政策支持。第二，提高海洋科\n技自主创新能力。第三，做强做优做大海洋产业。第四，加强主要海湾整体规划。第五，加强海洋生态环\n境保护。第六，深度参与全球海洋治理。"}, {"title": "中央军委办公厅日前发出通知，要求解放军和武警部队认真传达学习十四届全国人大四次会", "detail": "议\n精神，认真学习贯彻习近平主席在解放军和武警部队代表团全体会议上的重要讲话精神。通知强调，要把\n学习大会精神特别是习主席重要讲话精神，纳入团级以上党委理论学习中心组学习、干部理论培训、部队\n思想政治教育和院校政治理论教学，及时把思想和行动统一到党中央、习主席决策部署上来。"}, {"title": "3月15日晚，第14届冬季残疾人奥林匹克运动会在意大利科尔蒂纳奥林匹克冰壶馆闭幕。", "detail": "本届冬\n残奥会，中国体育代表团以15枚金牌、13枚银牌、16枚铜牌，总计44枚奖牌的成绩，位居金牌榜和奖牌\n榜第一。这一成绩创造了中国队境外参加冬残奥会最佳战绩，书写了中国残疾人冬季运动的新篇章。"}, {"title": "国家医保局3月16日发布《2025年医疗保障事业发展统计快报》。", "detail": "《快报》显示，截至2025年\n底，基本医疗保险参保人数达133068.14万人，同比增加406万人，参保率巩固在95%，医保基金运行平\n稳。"}, {"title": "2026年3月16日12时12分，快舟十一号遥七运载火箭在酒泉卫星发射中心发射升", "detail": "空，将钧天一\n号04A卫星，东坡11、12、16卫星，驭星三号05、06星，微瞳一号01星，西光壹号06星等8颗卫星顺利\n送入预定轨道，飞行试验任务取得圆满成功。"}, {"title": "3月16日，国务院总理李强主持召开国务院第十一次全体会议，深入学习贯彻习近平总书", "detail": "记在全\n国两会期间的重要讲话和全国两会精神，对落实国务院2026年重点工作进行部署。李强指出，今年是\n‘十五五”开局之年，面对复杂严峻的外部环境和艰巨繁重的改革发展稳定任务，国务院及各部门要始终\n保持战略定力、更加积极主动作为，以更高标准当好贯彻党中央决策部署的执行者、行动派、实干家。这\n难的更大实效上；三是体现在破解长期问题的持续努力上。\n五”规划纲要作了具体安排，要不折不扣推动落实，特别是要抓好一批牵引性、撬动性强的重点工作。…\n第11页共19页\n是纵深推进全国统一大市场建设，二是积极谋划推动服务业扩能提质，三是加快发展新一代智能制造，四\n冲击挑战。"}, {"title": "3月16日19时35分，经过7小时的出舱活动，神舟二十一号乘组航天员张陆、武飞、", "detail": "张洪章密切\n协同，在空间站机械臂和地面科研人员的配合支持下，圆满完成空间碎片防护装置安装等任务。出舱航天\n员张陆、武飞已安全返回问天实验舱，出舱活动取得圆满成功。至此，张陆已累计进行6次舱外活动，成\n为目前在舱外执行任务次数最多的中国航天员之一。"}, {"title": "【公众号：橙子考公资料站】2025年，全国市场监管系统持续贯彻落实《全国市场监管", "detail": "系统深\n化信用提升助力经营主体高质量发展三年行动方案（2024一2026）》部署，紧扣“提质增效”主题，完\n善全链条全生命周期信用监管服务机制，中国企业信用指数162.66，较2024年上升2.82，为经济社会高\n质量发展提供有力支撑。"}, {"title": "近日，国家发展改革委、国务院妇女儿童工作委员会办公室日前联合印发《关于在全社会推", "detail": "进\n儿童友好建设的意见》，意见系统总结国家儿童友好城市试点建设经验，部署全面开展儿童友好建设，以\n城市为基本单元，统筹社会政策、公共服务、权利保障、成长空间、发展环境等重点领域，系统集成政策\n举措。聚焦公共政策、公共设施、公共服务等重点方向，推动在政策制定、规划编制、资源配置中充分保\n障儿童权益、优先满足儿童需求，加快推进公共空间适儿化改造，持续优化公共服务供给，落实儿童免费\n及优待政策，围绕上学、就医、出行、运动、游玩等推出务实举措。"}, {"title": "近日，中国科学技术大学科研团队在光钟研制方面取得里程碑式进展。", "detail": "科学家将锶原子光晶格\n钟的稳定度和不确定度，双双突破10的负19次方量级，就是说这台“超级钟表”运行300亿年，误差不超\n过1秒。"}, {"title": "3月18日，《中共中央办公厅国务院办公厅关于做好第二轮土地承包到期后再延长30年", "detail": "试点工作\n的意见》对外发布，对第二轮土地承包到期后再延长30年试点工作（以下简称延包试点）作出具体部署。"}, {"title": "3月18日下午，国家主席习近平在北京钓鱼台国宾馆会见来华进行友好访问的土库曼斯坦", "detail": "民族领\n袖、人民委员会主席别尔德穆哈梅多夫。习近平强调，相互支持是中土全面战略伙伴关系的核心要义。无\n论国际形势如何变化，中方将始终支持土方维护国家独立、主权和领土完整，始终支持土方奉行永久中立\n政策，始终做土方值得信赖的合作伙伴。双方要加快推进共建“一带一路”倡议和“复兴丝绸之路”战略\n第12页共19页\n对接，扩大天然气领域合作规模，提升贸易和投资水平，拓展互联互通、农业、人工智能、数字经济、清\n洁能源等非资源领域合作，加快推进鲁班工坊、中医药中心、互设文化中心工作，打造全方位合作新格局。\n技术开发区、天津市滨海新区、辽宁省沈阳市、上海市浦东新区、浙江省宁波市、安徽省合肥市、福建\n省泉州市、山东省青岛市、河南省郑州市、湖北省武汉市、湖南省长沙市、广东省深圳市、重庆市两江新\n区、四川省成都市、陕西省西安市等16个创建城市上榜。"}, {"title": "阿根廷政府已于2026年3月17日正式完成了退出世界卫生组织的程序。", "detail": "报道称，阿根廷于2025\n年3月17日提交退出世卫组织的通报。根据相关国际条约规定，退出该组织的决定将在提交通报一年后生\n效。"}, {"title": "3月18日，第22届中国（天津）国际装备制造业博览会在国家会展中心（天津）开幕。", "detail": "本次展会\n以“工业数智转型赋能绿色发展”为主题，设置人工智能与机器人、算力基础设施与应用、机床与激光加\n工、自动化、焊接及切割、电子、智能泵阀、铸造与压铸等展区，构建起覆盖制造业研发、生产、加工、\n配套全链条的产业生态矩阵。"}, {"title": "3月18日，国家主席习近平夫人、世界卫生组织结核病和艾滋病防治亲善大使彭丽媛向世", "detail": "界卫生\n组织2026年世界防治结核病日视频会议发表书面致辞。彭丽媛表示，世界卫生组织和国际社会始终坚持\n以守护人类健康为使命、以终结结核病流行为目标，做了大量富有成效的工作，扭转了近年来结核病患者\n人数连续增长的势头。世界卫生组织召开视频会议，聚焦“政府赋能、全民聚力”这一主题展开讨论，对\n推动国际社会共同应对结核病公共卫生挑战具有重要意义。"}, {"title": "当地时间3月19日，泰国国会下议院举行会议投票选举新总理，自豪泰党党首阿努廷获得", "detail": "过半数\n议员支持，当选泰国第33任总理。"}, {"title": "【公众号：橙子考公资料站】财政部日前发布《2025年中国财政政策执行情况报告》。", "detail": "2025年，\n我国经济运行总体平稳、稳中有进，财政运行平稳有序。全国一般公共预算收入21.6万亿元，税收收入实\n现增长；全国一般公共预算支出28.7万亿元，保持必要强度。"}, {"title": "3月20日从2026年全国群众体育工作会议了解到，截至2025年底，全国共有体育", "detail": "场地500.37万\n个，体育场地面积43.72亿平方米，人均体育场地面积3.11平方米。"}, {"title": "3月20日，第二艘中国国产大型邮轮“爱达·花城号”（H1509）在中国船舶集团旗", "detail": "下上海外高桥造\n第13页共19页\n船有限公司出坞，全面转入码头调试阶段，并预期于今年年中试航、年底前完工交付。"}, {"title": "3月21日是国际森林日。", "detail": "3月20日从国家林草局获悉，目前我国森林面积达36.14亿亩，全国森\n林覆盖率达25.09%，森林蓄积量达209.88亿立方米，森林面积和森林蓄积连续40年实现双增长，成为全\n球增绿最多最快的国家。获取后续更新及更多考试资料，请加微信：szgkzlz7"}, {"title": "中共中央办公厅印发了《关于加强党建带团建工作的意见》，对加强党建带团建工作作出部", "detail": "署。\n《意见》指出，加强党建带团建工作，坚持和加强党对共青团的领导，坚持党管青年工作原则，健全党建\n带团建制度机制，贯通党、团、队一体化育人链条，带动共青团进一步增强政治性、先进性、群众性，提\n升引领力、组织力、服务力，全面从严管团治团，切实肩负起新时代新征程党赋予的使命任务，动员引领\n广大青年坚定不移听党话、跟党走。"}, {"title": "3月21日，长春2027第33届世界大学生冬季运动会（简称“长春大冬会”）迎来倒", "detail": "计时300天，\n，，，呈，“，，\n梦冰雪，长驻青春”。"}, {"title": "3月21日从国家能源局获悉，根据国家充电设施监测服务平台数据，截至2026年2月", "detail": "底，我国电\n动汽车充电基础设施（充电枪）总数达到2101万个。"}, {"title": "3月21日，我国首台550兆瓦F级燃气机组一华电重庆潼南燃机项目1号机组顺利完成", "detail": "168小时\n满负荷运行，正式投产发电，标志看我国在大容量高效清洁能源装备应用上取得新突破。"}, {"title": "近日，工业和信息化部、国家发展改革委、国务院国资委、国家能源局四部门共同印发了《", "detail": "节\n能装备高质量发展实施方案（2026一2028年）》。《实施方案》聚焦节能电机、变压器、工业热泵、工\n业制冷（热）与加热设备、水电解制氢装备、信息通信设备等六类节能装备，提出以推动重点行业领域节\n能降碳为目标，以用能系统优化提升为主攻方向，以先进技术装备研发和应用为主要抓手，以绿色设计制\n造、设备更新改造、人工智能赋能为路径，加快节能装备智能化、绿色化、融合化发展。"}, {"title": "3月21日，拉美和加勒比国家共同体第十届峰会在轮值主席国哥伦比亚举行，国家主席习", "detail": "近平向\n峰会致贺电。习近平指出，去年5月，中国－拉共体论坛第四届部长级会议在北京成功举行，我出席开幕\n式并宣布中拉携手启动团结、发展、文明、和平、民心五大工程，得到拉方积极响应。一年来，中拉双方\n密切协作，推动五大工程不断走深走实，给双方人民带来实实在在的福祉。"}, {"title": "【公众号：橙子考公资料站】3月22日，中国发展高层论坛2026年年会在北京开幕，", "detail": "主题为\n第14页共19页\n‘十五五的中国：高质量发展与共创新机遇”。\n国际局势正在经历深刻复杂变化。正如习近平主席指出，这是一个充满挑战的时代，也是一个充满希望的\n时代。放眼全球，我们看到的是一幅多种态势并存、交织、碰撞的景象：单边主义、保护主义甚嚣尘上，\n同时求合作、促发展的力量也在不断壮大；传统领域的经济增长面临困境，同时新兴领域的发展动能也在\n篷勃兴起；国际规则秩序遭受严重破坏和冲击，同时许多国家也在积极推动全球治理的改革和完善；强权\n政治大行其道、肆意妄为，同时捍卫公平正义的呼声也在日益高涨。这些现象深层次反映的是思想观念的\n冲突，从经济发展角度看，主要是如何看待市场、看待发展、看待未来的问题。"}, {"title": "3月22日是第三十四个“世界水日”，第三十九个“中国水周”同步开启。", "detail": "当日从2026年“节\n水中国行·安徽合肥”主题宣传活动上了解到，2025年我国非常规水利用量已超过250亿立方米。"}, {"title": "近日，中共中央办公厅、国务院办公厅印发了《国有企业领导人员廉洁从业规定》，《规定", "detail": "》\n提出，国有企业领导人员廉洁从业应当做到：对党忠诚、担当作为、依规依法、保障民生、作风过硬。"}, {"title": "2026年3月22日23时49分，我国太原卫星发射中心在山东海阳附近海域使用捷龙", "detail": "三号运载火箭\n成功将“微厘空间”低轨卫星系统02组10颗组网卫星发射升空，卫星顺利进入预定轨道，发射任务取得\n圆满成功。"}, {"title": "3月22日，全国首部省级水利综合典籍《福建水典》新书发布会在福州举行。", "detail": "《福建水典》由省\n水利厅主导、省幸福河湖促进会牵头组织，历时三年编纂完成，全书248万余字，分《水情卷》《文化卷》\n《治水卷》三卷，以严谨真实为原则，系统梳理福建水利发展全貌，精准收录核心水利数据、涉水文保单\n位及典型治水案例，兼具史料性、实践性与文化性。"}, {"title": "习近平3月23日在河北雄安新区考察，主持召开深入推进雄安新区高质量建设和发展座谈", "detail": "会并发\n表重要讲话。他强调，要牢牢把握雄安新区作为北京非首都功能疏解集中承载地的首要功能定位，保持战\n略定力和历史耐心，进一步解放思想、开拓思路、加强协调、凝聚合力，以改革创新为引领增强内生发展\n动力，以要素资源合理集聚为重点激发新区活力，努力建设新时代创新高地和推动高质量发展样板。\n习近平指出，雄安新区要以改革创新为动力，推动科技创新与产业创新深度融合，因地制宜发展新质\n生产力，培育符合新区实际的现代化产业体系。"}, {"title": "3月23日，中共中央总书记、国家主席习近平致电通伦，祝贺他当选连任老挝国家主席。", "detail": "习近平\n第15页共19页\n指出，中老两国是命运与共的社会主义友好邻邦，双方始终肝胆相照、守望相助，在涉及彼此核心利益和\n重大关切问题上坚定相互支持，体现了“同志加兄弟”的深厚情谊。2026年是中老建交65周年暨“中老\n友好年”，双方将举办系列庆祝活动，为增进两国人民友谊注入新动力。"}, {"title": "从国网新疆电力有限公司了解到，截至3月23日，我国距离最远特高压工程一准东一皖南", "detail": "±\n1100千伏特高压直流输电工程累计外送电量突破4000亿千瓦时大关，达4021.9亿千瓦时，日均外送电量"}, {"title": "69亿千瓦时，居全国特高压直流输电工程日均外送电量首位。", "detail": ""}, {"title": "3月24日从中国科学院国家天文台获悉，截至目前，国家重大科技基础设施", "detail": "郭守敬望远镜\n（LAMOST）发布的光谱数已突破三千万条，继续稳居国际上发布光谱数量最多的巡天项目。这些光谱"}, {"title": "从国家数据局获悉：2024年初，中国日均词元（Token）调用量为1000亿；", "detail": "至2025年底，跃\n升至100万亿；今年3月，已突破140万亿，两年增长超千倍。"}, {"title": "【公众号：橙子考公资料站】近日，国家医保局会同国家发展改革委、国家卫生健康委印发", "detail": "《关于医保支持基层医疗卫生服务发展的指导意见》。意见提出14条具体措施，更好支持服务强在基层，\n促进改革举措落在基层、实现便捷服务优在基层，推动实现基层医疗卫生机构得发展，参保群众得实惠，\n医保基金可持续。"}, {"title": "3月24日，由国家移民管理局、国家民委、农业农村部、国家边海防委员会办公室联合部", "detail": "署开展\n的平安边境模范创建活动在京举办平安边境模范县市乡镇经验交流会，辽宁省丹东市宽甸满族自治县、吉\n林省延边朝鲜族自治州图们市、黑龙江省佳木斯市抚远市、云南省文山壮族苗族自治州马关县、甘肃省酒\n泉市肃北蒙古族自治县等5个县市和内蒙古自治区呼伦贝尔市新巴尔虎左旗罕达盖苏木等19个乡镇获第二\n批平安边境模范县市、乡镇命名。"}, {"title": "2026中关村论坛年会3月25日在京开幕。", "detail": "今年中关村论坛年会主题是“科技创新与产业创新深\n度融合”。国内外科技人员、企业负责人、政府官员和国际组织负责人等约1000人参加开幕式。"}, {"title": "3月25日，国家自然科学基金委员会在2026中关村论坛年会开幕式上发布了2025", "detail": "年度“中国\n科学十大进展”。此次入选进展包括：娥六号样品首次揭示月背演化历史和巨型撞击效应、创新方法实\n现规模化制备柔性超平金刚石薄膜、可控核聚变大科学装置实现“亿度”运行、发现神经酰胺受体和菌源\n调控物及其在心血管与代谢性疾病中的作用、基因编辑猪肝植入人体突破跨物种器官移植壁垒、炎性衰老\n第16页共19页\n机制解析与多维靶向干预、深渊海沟最深处发现繁盛的化能合成生物群落、全功能二维半导体/硅基混合\n柔性叠层太阳能电池。获取后续更新及更多考试资料，请加微信：szgkzlz7"}, {"title": "2026年3月26日6时51分，我国在太原卫星发射中心使用长征二号丁运载火箭，成", "detail": "功将四维高\n景二号05、06星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。"}, {"title": "中办、国办3月25日发布《关于加快建立长期护理保险制度的意见》，建立适应我国基本", "detail": "国情，\n覆盖全民、统筹城乡、公平统一、安全规范、可持续的长期护理保险制度。这标志着长期护理保险制度从\n局部试点转向全国推行。"}, {"title": "国务院总理李强日前签署国务院令，公布修订后的《全国农业普查条例》，自2026年5", "detail": "月1日\n起施行。《条例》共7章44条。《条例》规定，农业普查工作按照全国统一领导、部门分工协作、地方分\n级负责、各方共同参与的原则组织实施。"}, {"title": "博鳌亚洲论坛2026年年会于3月24日至27日在海南博鳌举行。", "detail": "本届年会以“塑造共同未来：新\n形势、新机遇、新合作”为主题，将举办50多场分论坛、圆桌会、对话会等系列活动。"}, {"title": "2026年3月27日12时11分，我国在酒泉卫星发射中心使用长征二号丙运载火箭/", "detail": "远征一号S上\n面级，将试验三十三号卫星发射升空，卫星顺利进入预定轨道，发射任务取得圆满成功。该卫星主要用于\n空间环境探测科学试验。"}, {"title": "【公众号：橙子考公资料站】中共中央政治局3月27日召开会议，审议《中国共产党地方", "detail": "委员\n会工作条例》。会议强调，地方党委在谋发展保安全上责无旁贷，要脚踏实地、真抓实干。要树立和践行\n正确政绩观，坚持为人民出政绩、以实干出政绩，努力创造经得起实践、人民、历史检验的实绩。"}, {"title": "国务院总理李强3月27日主持召开国务院常务会议，会议指出，服务业是现代化产业体系", "detail": "的重\n要组成部分，关系高质量发展和现代化建设全局。要充分挖掘服务业发展潜力，推进生产性服务业向专业\n化和价值链高端延伸，促进生活性服务业高品质多样化便利化发展。要聚焦带动性强的重点领域，完善政\n策配套和体制机制，加大财税、金融、要素保障等支持，扩大服务业市场准入和开放领域，充分释放市场\n活力。"}, {"title": "第六届中国出版政府奖表彰座谈会3月27日在京召开，与会人员表示，要以改革的精神推", "detail": "动出\n第17页共19页\n版业创新发展，加强规划引领，强化科技赋能，改进版权工作，以《全民阅读促进条例》施行为契机建设\n书香社会，加快出版走出去。"}, {"title": "2026中国科幻大会于3月27日至29日在北京石景山首钢园举办。", "detail": "大会以“科学梦想创造未来\n为主题，设置论坛会议、产业促进和群众性活动20余场活动。今年的中国科幻大会首次推出“未来数字\n街区”，集中展示了北京未来数字空间创新试验区的建设成果。"}, {"title": "联合国秘书长零废物咨询委员会3月27日发布全球“20个迈向零废物的城市”倡议首批", "detail": "入选名\n单，肯定入选城市在减少废物、推动循环经济并建设更可持续和包容的城市系统方面所作努力。我国的杭\n州、三亚和苏州三座城市入选。"}, {"title": "新版《商品条码管理办法》3月27日发布，商品条码是商品的\"身份证”，强化其在质量", "detail": "追溯\n管理中的作用，将于2026年5月1日起实施。"}, {"title": "3月28日，西南首个商业卫星遥感测运控站", "detail": "环天星座”卫星地面接收站（简称“眉山站”）\n在四川天府新区眉山片区视高街道正式投入运行。该站具备全自动化卫星数据接收能力，将承担“环天星\n座”遥感数据接收、卫星运行控制、任务规划等核心职责，为星座稳定运行提供全天候支撑。"}, {"title": "国家外汇管理局3月27日发布《2025年中国国际收支报告》。", "detail": "报告显示，2025年，我国经常\n账户收支合计8.3万亿美元，较上年增长3%；经常账户顺差7350亿美元，与国内生产总值（GDP）比值\n为3.7%。"}, {"title": "中国科学技术发展战略研究院3月29日在2026中关村论坛年会上发布的《国家创新指", "detail": "数报告\n2025》显示，中国国家创新指数综合排名上升至世界第9位，向创新型国家前列和科技强国目标稳步迈进。"}, {"title": "3月29日，以“发挥主流媒体引领力激发多元主体创造力", "detail": "共创繁荣网络内容生态”为主题\n的2026中国网络媒体论坛在河南郑州开幕。各界与会人士围绕网络内容建设的新形势、新任务、新路径\n展开交流探讨。"}, {"title": "【公众号：橙子考公资料站】日前，中华人民共和国外交部、文化和旅游部与巴西联邦共和", "detail": "国\n外交部、文化部、旅游部发布关于2026“中巴文化年”的联合公告。公告说，根据《中华人民共和国和\n2026年共同庆祝“中巴文化年”。"}, {"title": "3月30日19时00分，力箭二号遥一运载火箭在东风商业航天创新试验区发射升空，将", "detail": "搭载的新\n第18页共19页\n征程01卫星、新征程02卫星和天视卫星01星共3颗卫星顺利送入预定轨道，飞行试验任务取得圆满成功。"}, {"title": "习近平3月30日上午在参加首都义务植树活动时强调，良好生态人人共享，也需要合力共", "detail": "建。\n习近平强调，今年是“十五五”开局之年，也是全民义务植树运动开展45周年。新形势下推进国土绿化，\n要更加注重提质、兴业、利民，实现种与管共抓、生态与产业共促、人与自然共生。"}, {"title": "3月30日，世界数据组织在北京完成组建，选举产生首届理事、监事和组织负责人。", "detail": "这标志着\n世界数据组织正式投入运行。这是全球首个旨在推动数据发展与治理实践的专业性国际组织，总部设在北\n京"}, {"title": "3月30日，国家主席习近平向世界数据组织成立致贺信。", "detail": "习近平指出，当今世界正在加速迈入\n智能时代，数据的基础资源作用和创新引引擎作用日渐显现。世界数据组织以“弥合数据鸿沟、释放数据价\n值、繁荣数字经济”为宗旨，为深化数据国际合作、完善全球数据治理提供了有益平台。\n第19页共19页"}]}, {"month": "2026年4月", "year": 2026, "items": [{"title": "4月1日，新H社发文《学习贯彻BOSS全国俩会期间关于发展新质生产力重要论述系列", "detail": "述评》。\n科技创新是发展新质生产力的核心要素，加强原始创新和关键核心技术攻关，是抢占科\n技制高点、实现高水平科技自立自强的根本所在。\n原始创新是科技创新的“源头活水”，决定着新质生产力发展的根基与后劲。\n科技成果转化，是连接基础研究与产业应用的桥梁，是科技创新从实验室走向生产线的\n关键一跃，更是培育壮大新质生产力的关键抓手。今年全国俩会期间，BOSS在参加江苏代\n表团审议时指出，在促进创新链产业链资金链人才链深度融合、推动科技成果高效转化应用\n上探索新途径。\n创新链是引领、产业链是载体、资金链是血液、人才链是根基，推动创新链产业链资\n金链人才链深度融合，让更多技术突破变为发展动能，已成为抢占未来制高点、塑造发展新\n优势的必然选择。\n加强企业主导的产学研深度融合，发挥科技型骨干企业引领支撑作用。\n要做好科技金融这篇文章，引导金融资本投早、投小、投长期、投硬科技。\n人是科技创新最活跃的因素，成果转化关键在人才。\n在我国产业体系中，传统产业是家底、是优势，是保持经济增长的基本盘，也是接续新\n产业的基础、形成新质态的关键。通过传统产业改造升级，也能发展新质生产力。发展新质\n生产力，科技创新是核心要素。\n新兴产业是加快形成新质生产力的关键抓手。推动战略性新兴产业发展，有利于快速\n形成规模化产业集群，发挥“一业带百业”的乘数效应，带动上下游产业协同发展，为高质\n量发展注入强劲动力。\n发展新质生产力，既是发展命题，也是改革命题。新质生产力的形成与发展，离不开对\n现有生产关系的适应性调整。如果体制机制欠佳，就容易在创新、发展、应用等各环节形成\n堵点卡点，就无法形成与新质生产力相匹配的生产关系。改革是解放和发展社会生产力的关\n键，是推动国家发展的根本动力。发展新质生产力，必须进一步全面深化改革，形成与之相\n适应的新型生产关系、"}, {"title": "4月23日，BOSS作出重要指示指出，义乌小商品闯出大市场、做成大产业，形成“义", "detail": "乌发展经验”，这是因地制宜发展县域经济的成功实践。\n强调，要结合开展树立和践行正确政绩观学习教育，把“义乌发展经验”进一步总结好、\n运用好，引导各地区立足自身资源禀赋，尊重基层和群众首创精神，改革创新、真抓实干、\n久久为功，探索走出符合各自实际的高质量发展之路，更好服务和融入全国发展大局。\n这些年来，义乌不断书写“小商品、大市场”新篇章，目前小商品市场经营主体突破\n1\n126万户，与230多个国家和地区有贸易往来，2025年外贸出口额居全国县（市、区）首\n位。"}, {"title": "4月1日出版的第7期《Q是》杂志发表重要文章《树立和践行正确政绩观》。", "detail": "我们讲宗旨，讲了很多话，但说到底还是为人民服务这句话。古时候讲，食君之禄，忠\n君之事，现在就是要服务人民。\n概括起来说，好干部要做到信念坚定、为民服务、勤政务实、敢于担当、清正廉洁。\n政绩观问题是一个根本性问题，关乎立當为公、执政为民。干事创业一定要树立正确政\n绩观，做到“民之所好好之，民之所恶恶之”。树立和践行正确政绩观，起决定性作用的是\n當性。只有當性坚强、摒弃私心杂念，才能保证政绩观不出偏差。衡量當性强弱的根本尺子\n是公、私二字。有人说，现在不要讲“大公无私”了，因为干部的合理合法利益也要承认，\n应该是“大公有私”。这是一个谬论！干部合理合法的利益当然要承认，也要保障，但这同\n私心、私利、私欲不是同一个概念，不能混为一谈。作为當的干部，就是要全心全意为人民\n服务，就是要诚心诚意为當和人民事业奋斗，就是要讲大公无私、公私分明、先公后私、公\n而忘私。\n“近水知鱼性，近山识鸟音。”我讲过，要近距离接触干部，看干部对重大问题的思考、\n对群众的感情、对待名利的态度、为人处世方式、处理复杂问题能力。\n要树立正确政绩观，处理好稳和进、立和破、虚和实、标和本、近和远的关系，坚持\n底线思维，强化风险意识，自觉把新发展理念贯穿到经济社会发展全过程。\n干部干事创业要树立正确政绩观，有功成不必在我的精神境界、功成必定有我的历史担\n当，发扬钉钉子精神，脚踏实地干。中国共产当把为民办事、为民造福作为最重要的政绩，\n把为老百姓办了多少好事实事作为检验政绩的重要标准。共产當人必须牢记，为民造福是最\n大政绩。\n《关于在全當开展树立和践行正确政绩观学习教育的通知》提出，要紧扣贯彻“立當为\n公、为民造福、科学决策、真抓实干”总要求，一体推进学查改。\n公基时政考点一社会"}, {"title": "4月1日，美国航空航天局实施“阿耳忒弥斯2号”载人绕月飞行任务，使用美国新一", "detail": "代登月火箭“太空发射系统”和“猎户座”飞船，将4名宇航员送往月球轨道，展开为期\n10天的绕月飞行。\n这是美国自1972年阿波罗17号登月任务以来的首次载人探月之旅。“猎户座”飞船飞\n至月球背面期间，与地球的最远距离约为40.68万公里，创下人类太空飞行距离的新纪录。"}, {"title": "4月2日，印发《关于建立企业信用状况综合评价体系的实施方案》。", "detail": "企业信用状况综合评价主要包括公共信用评价和市场化信用评价。公共信用评价由政\n府部门遵循公益性原则组织开展，反映企业遵守法律法规和相关管理规定情况，主要服务政\n府管理。市场化信用评价由征信机构、信用评级机构、行业协会商会等第三方机构依法依规\n开展，反映企业参与市场活动的违约风险，主要服务融资授信、商业往来等市场活动。更好\n发挥公共信用评价结果在企业信用状况综合评价中的基础性作用，推动公共信用评价和市场\n化信用评价相互融合，逐步形成统一的企业信用状况综合评价体系。\n2\n公共信用评价指标数据原则上应当来源于公共信用信息，可以视情将有关部门在履职过\n程中产生或获取的其他能够反映企业信用状况的信息纳入指标数据范围。评价结果由高至低\n原则上划分为“A”、“B”、“C”、“D”四级；评价结果采取分数制的，应明确四级对应的分\n数段。\n行业主管部门将公共信用综合评价结果纳入行业信用评价指标体系，具体权重根据实际\n情况确定。公共信用综合评价为“D”级的，行业信用评价不得评为“A”级。"}, {"title": "4月9日，印发《中国（内蒙古）自由贸易试验区总体方案》。", "detail": "自贸试验区的实施范围119.74平方公里，涵盖三个片区：呼和浩特片区76.28平方公\n里（含呼和浩特综合保税区0.88平方公里），满洲里片区25.11平方公里（含满洲里综合保\n税区1.44平方公里），二连浩特片区18.35平方公里。\n呼和浩特片区重点发展新能源、新材料、生物医药、新一代信息技术等战略性新兴产业\n及绿色农畜产品加工、乳业等特色产业，积极培育商贸物流、数字经济、科技服务、会展、\n文旅等现代服务业，打造国家向北开放重要桥头堡的核心枢纽、特色产业高质量发展的创新\n集聚区。\n满洲里片区重点发展进口资源落地加工、跨境旅游、跨境金融、口岸服务等特色产业，\n打造辐射东北亚和欧洲的重要窗口、中俄蒙开放合作的重要平台。\n二连浩特片区重点发展国际贸易、国际物流、跨境旅游、国际医疗等特色产业，打造中\n蒙俄经济走廊的重要枢纽、与周边国家友好合作的示范样板。\n赋予自贸试验区更大改革自主权，鼓励先行先试，在更广领域、更深层次开展首创性、\n集成式、差别化探索。\n以制度创新为核心，以可复制可推广为基本要求，因地制宜发挥内蒙古“内联八省近京\n畿、外接俄蒙通欧亚”的区位优势，深入参与共建“一带一路”和中蒙俄经济走廊建设，着\n力打造联通内外、辐射周边的信息交流中心、交通物流中心、要素资源配置中心、重点领域\n科技创新中心和产业合作中心，建设沿边内陆开发开放战略高地和服务保障全国高质量发展\n示范区域，打造稳边固边、经略周边、服务全国的战略支点。"}, {"title": "4月7日，BOSS给上海交通大学、西安交通大学、西南交通大学、北京交通大学全体师", "detail": "生回信，对学校发展提出殷切期望。\n指出，你们四所高校根脉相连，今年共同迎来建校130周年。希望你们秉持“求实学、\n务实业”办学宗旨，传承弘扬西迁精神，聚焦国家重大战略需求，加强科技自主创新和人才\n自主培养。\n上海交通大学、西安交通大学、西南交通大学、北京交通大学的前身，分别是1896年\n成立的南洋公学、北洋铁路官学堂和1909年成立的铁路管理传习所，1921年合并组建为交\n通大学。\n“西迁精神”的核心是爱国主义，精髓是听党指挥跟党走，与党和国家、与民族和人民\n同呼吸、共命运，内容是“胸怀大局，无私奉献，弘扬传统，艰苦创业”。"}, {"title": "4月10日，BOSS向中美“乒乓外交”55周年纪念大会暨中美青少年体育交流系列活", "detail": "动\n启动仪式致贺信。\n指出，55年前，中美老一辈领导人以卓越的政治智慧和战略远见，重新开启两国人民\n友好往来的大门，成就了“小球转动大球”的历史佳话。\n1971年4月，美国乒乓球队应中方邀请，历史性地访问中国，中美“乒乓外交”打开\n了两国人民友好往来的大门。\n3"}, {"title": "4月13日，发布《关于加强网络直播打赏规范管理的通知》，明确网站平台不得向八周", "detail": "岁以下的未成年人提供打赏服务。"}, {"title": "4月13日，印发《关于健全药品价格形成机制的若干意见》。", "detail": "优化创新药等新上市药品首发价格机制。对新上市药品价格制定，区分高水平创新药、\n改良新药、通用名药（即仿制药）等情形，分别予以政策支持和引导。\n对创新程度高、临床价值大的高水平创新药，支持在上市初期制定与高投入、高风险相\n符的价格，在一定时期内保持价格相对稳定。对改良新药等，鼓励引导制定与患者获益相匹\n配的价格。对通用名药等其他新上市药品，引导医药企业参照同通用名、同作用机制、同功\n能主治药品价格合理定价。"}, {"title": "4月15日，在法国巴黎召开的联合国教科文组织执行局第224届会议上，我国浙江常山", "detail": "（浙江衢州，拥有大量笔石、三叶虫等古生物化石）和四川四姑娘山（四川省阿坝藏族羌族\n自治州，记录了所在地区从古特提斯洋演化到青藏高原东缘隆起的地质演变历程）顺利通过\n会议审议，正式成为世界地质公园。\n至此，我国世界地质公园增至51处，分布在全国24个省（区、市）及香港特别行政区。"}, {"title": "4月15日，中国科学院微小卫星创新研究院自主研制的轻舟初样试飞船（白象号）正式", "detail": "发布首批科学与工程试验成果。\n轻舟货运飞船凭借低成本和技术创新优势胜出，成为新一代空间站货物运输系统的备份\n力量及重要组成部分。"}, {"title": "4月15日，国W院副Z理丁同志访问土库曼斯坦，出席复兴气田四期项目开工仪式。", "detail": "西芒杜铁矿－一西非几内亚；钱凯港一一南美洲秘鲁；雅万高铁一一印尼；中老铁路－一\n老挝；蒙内铁路一一肯尼亚；巴基斯坦一一瓜达尔港。"}, {"title": "4月15日，人民日报发文《新的“之最”不断产生，彰显创新中国蓬勃生机》。", "detail": "成功首飞！4月4日，中国航发研制的发动机配装7.5吨级无人运输机在湖南株洲首飞，\n这是全球首次兆瓦级氢燃料航空涡桨发动机试飞。\n项目在拉萨开工建设。\n水深最深！4月7日，我国水深最深的海上风电项目－－华能山东半岛北L场址海上风\n电项目全容量并网发电。"}, {"title": "4月16日，国家统计局发布数据显示，一季度中国国内生产总值（GDP）334193", "detail": "亿元，\n按不变价格计算，同比增长5.0%。"}, {"title": "4月17日，国办转发海关总署《关于促进综合保税区扩能提质的若干措施》的通知。", "detail": "综合保税区，是设立在内陆地区的具有保税港区功能的海关特殊监管区域，由海关参照\n《海关综合保税区管理办法》进行管理，执行保税港区的税收和外汇政策，集保税区、出口\n加工区、保税物流区、港口的功能于一身，可以发展国际中转、配送、采购、转口贸易和出\n口加工等业务。\n综合保税区和保税港区一样，是我国开放层次最高、优惠政策最多、功能最齐全、手续\n最简化的特殊开放区域。\n4"}, {"title": "4月20日，国W院进行第十九次专题学习。", "detail": "李BOSS指出，要充分挖掘可再生能源供给潜力，坚持全国一盘棋，加快推进西北地区\n风电光伏、西南地区水电、东部地区海上风电等清洁能源基地建设，大力发展分布式光伏、\n分散式风电，因地制宜开发生物质能、地热能、海洋能，促进新能源集成融合开发。要不断\n提升化石能源清洁高效利用水平，加快现役煤电机组节能降碳改造，推动煤电向基础保障性\n和系统调节性电源并重转型。\n（），\n五届全民阅读大会，在江西南昌市同步启幕，活动主题为“共促全民阅读，共建书香社会”。\n4月15日，为深入贯彻BOSS关于“爱读书、读好书、善读书”的重要指示精神，教育\n部发布《中国青少年阅读素养框架》教育行业标准，创建了“知识一能力一价值”三维阅读\n素养模型，将阅读素养划分为奠基、拓展、深化、融通四个阶段并细化为十二个梯级。知识、\n能力、价值三者并非简单并列，而是构成“以知导行、以行促信、以信励知”的循环系统，\n深刻体现了“知、行、信”融合的育人理念。"}, {"title": "4月21日，BOSS在京同来华进行国事访问的莫桑比克总统查波举行会谈。", "detail": "两国一致同\n意将双边关系提升至新时代中莫命运共同体。"}, {"title": "4月21日，印发《关于推进服务业扩能提质的意见》。", "detail": "到2030年，服务业高质量发展取得明显进展，服务业总规模迈上100万亿元台阶，质\n量更高、结构更优、品质更佳、活力更足的发展格局基本形成，培育更多“中国服务”品牌，\n服务业全球竞争力、影响力明显增强，人民群众获得感持续提升。"}, {"title": "4月26日，2026伦敦马拉松赛场上，肯尼亚选手塞巴斯蒂安·萨维以1小时59分3", "detail": "0秒\n打破男子马拉松世界纪录，成为全程马拉松首位跑进2小时大关的人类运动员。"}, {"title": "4月29日，BOSS向上海合作组织绿色和可持续发展论坛致贺信。", "detail": "BOSS指出，今年是上海合作组织成立25周年。中国秉持绿水青山就是金山银山理念，\n坚定不移走生态优先、绿色发展之路，是全球生态文明建设的参与者、贡献者、引领者。\n本次论坛当日在浙江宁波开幕，主题为“践行全球治理倡议，共促上合组织绿色和可\n持续发展”。"}, {"title": "4月29日，2025年度全国十大考古新发现揭晓。", "detail": "吉林东部长白山旧石器时代遗址群、河南新郑裴李岗遗址、河北宣化郑家沟遗址、甘肃\n庆阳南佐遗址、山西昔阳钟村遗址、河南郑州商城遗址、陕西富平长春遗址、山东青岛琅琊\n台遗址、浙江绍兴越国都城和汉六朝会稽郡遗址、宁夏贺兰苏峪口瓷窑址上榜。"}, {"title": "4月29日，自然资源部发布我国最新矿产资源家底。", "detail": "我国稀土、钨、锡、钼、锑、镓、锗、铟、萤石、石墨等14种矿产储量居世界第一。\n2025年，我国煤炭、钒、钛、锌、稀土、钨、锡、钼、锑、镓、铟、金、碲等17种矿\n产产量居世界第一。\n5\n公基时政考点一政治"}, {"title": "4月8日，BOSS就服务业发展作出重要指示。", "detail": "當的十八D以来，我国服务业规模稳步扩大，质效持续提升，在支撑产业升级、满足\n民生需要、带动就业扩容等方面发挥了重要作用。\n新征程上，要突出需求牵引、改革攻坚、科技赋能、开放合作，深入实施服务业扩能提\n质行动，推进生产性服务业向专业化和价值链高端延伸，促进生活性服务业高品质多样化便\n利化发展，培育更多“中国服务”品牌，努力开创服务业高质量发展新局面。"}, {"title": "4月10日，BOSS在京会见了郑丽文率领的中国国民當访问团。", "detail": "大陆和台湾同属一个中国，中国是中华民族的共同家园。两岸同胞要守护好、建设好这\n个共同家园，根本在于坚持“九二共识”、反对“台独”，核心是认同两岸同属一个中国。\n今年是孙中山先生诞辰160周年，振兴中华、国家统一是他的毕生追求。"}, {"title": "4月16日出版的第8期《Q是》杂志发表重要文章《推动全民阅读，建设书香社会》。", "detail": "对领导干部特别是高级干部来说，要把系统掌握马克思主义基本理论作为看家本领。著\n名学者王国维论述治学有三种境界：一是“昨夜西风凋碧树，独上高楼，望尽天涯路”；二\n是“衣带渐宽终不悔，为伊消得人憔悴”；三是“众里寻他千百度，募然回首，那人却在灯\n火阑珊处”\n图书馆是国家文化发展水平的重要标志，是滋养民族心灵、培育文化自信的重要场所。\n要发扬“挤”和“钻”的精神，多读书、读好书，从书本中汲取智慧和营养，不能自我\n感觉良好、不屑学习，不能借口工作太忙、放松学习，不能为了装点门面、应付学习。哪怕\n一天挤出半小时，即使读几页书，只要坚持下去，必定会积少成多、积沙成塔，积步以至\n千里。数字阅读要和传统阅读结合起来，守住我们的内核和素养。"}, {"title": "4月28日，中局就提高防灾减灾救灾能力进行第二十五次集体学习。", "detail": "实践中深刻认识到，做好防灾减灾救灾工作必须坚持當的全面领导，坚持人民至上、生\n命至上，坚持尊重自然规律，坚持预防为主，坚持改革创新，坚持系统观念，坚持社会共治。\n强调，降低灾害风险，减轻灾害损失，重在事前预防。要坚持源头管控，将安全韧性要\n求贯穿国土空间规划及各类建设规划之中。\n树立和践行正确政绩观，坚决纠正重发展轻安全、重救灾轻预防等倾向。"}, {"title": "4月30日，BOSS在上海出席加强基础研究座谈会并发表重要讲话。", "detail": "强调，基础研究是整个科学体系的源头，是所有技术问题的总机关。要强化国家科研\n机构、高水平研究型大学等引领作用，鼓励和规范发展新型研发机构，推动企业主导的产学\n研用深度融合，促进应用学科与基础学科协调发展。优化科教协同育人机制，注重在科研一\n线发现和培养人才。逐步提高基础研究经费占比，形成多元化投入格局。\n法律法规"}, {"title": "《中华人民共和国监狱法》已由第十四届全人常于2026年4月30日修订通过，现予公", "detail": "布，\n自2026年11月1日起施行。\n6\n第二条监狱是国家的刑罚执行机关。\n依照《刑法》和《刑事诉讼法》的规定，被判处死刑缓期二年执行、无期徒刑、有期\n徒刑的罪犯，在监狱内执行刑罚。\n第三条监狱工作坚持中国共产党的领导，坚持总体国家安全观，建立公正、法治、文明、\n廉洁、高效的监狱刑罚执行体制。\n第四条监狱工作应当坚持惩罚和改造相结合、教育和劳动相结合，以改造人为宗旨，坚\n持依法管理，尊重和保障人权，将罪犯改造成为守法公民，促进其重新融入社会。\n第十九条监狱设监狱长、政治委员各一人，副监狱长若干人，并根据实际需要设置必要的\n工作机构，配备其他监狱管理人员。\n监狱的管理人员是人民警察。监狱人民警察是人民警察的重要组成部分。\n第三十一条人民法院应当在判决、裁定生效后十日以内将人民检察院的起诉书副本或者自\n诉案件的自诉状复印件、判决书、裁定书、执行通知书、结案登记表送达公安机关，生效裁\n判中有财产性判项的，应当一并送达财产性判项实际执行情况的材料。公安机关应当自收到\n上述材料之日起一个月以内将该罪犯送交监狱执行刑罚。对交付执行时未被羁押的罪犯，公\n安机关应当依法先行将罪犯收押或者追捕归案。\n罪犯在被交付执行刑罚前，剩余刑期在三个月以下的，由看守所代为执行。\n第四十二条监狱在执行刑罚过程中，认为判决、裁定、决定可能有错误的，应当提请人民\n检察院或者作出生效裁判的人民法院处理，人民检察院或者作出生效裁判的人民法院应当自\n收到监狱提请处理意见书之日起三个月以内将处理结果通知监狱。案情复杂或者情况特殊需\n要延长的，延长时间不超过三个月。\n第五十一条有期徒刑减刑建议由监狱提请所在地中级人民法院裁定；无期徒刑减为有期徒\n刑的，由监狱提出减刑建议，报经省、自治区、直辖市监狱管理机关审核同意后，提请高级\n人民法院裁定。减刑建议书应当抄送人民检察院。人民检察院可以向人民法院提出书面意见。\n人民法院应当自收到减刑建议书之日起一个月以内作出裁定；案情复杂或者情况特殊的，\n可以延长一个月。裁定书的副本应当抄送同级人民检察院。\n第五十二条被判处死刑缓期二年执行的罪犯，在死刑缓期执行期间，符合法律规定的减为\n无期徒刑、有期徒刑条件的，死刑缓期执行期满时，所在监狱应当及时提出减刑建议，报经\n省、自治区、直辖市监狱管理机关审核同意后，提请高级人民法院裁定。\n第五十三条被判处有期徒刑和被减为有期徒刑的罪犯，符合法律规定的假释条件的，由监\n狱提请所在地中级人民法院裁定；被判处无期徒刑和被减为无期徒刑的罪犯，符合法律规\n定的假释条件的，由监狱提出假释建议，报经省、自治区、直辖市监狱管理机关审核同意后，\n提请高级人民法院裁定。假释建议书应当抄送人民检察院。人民检察院可以向人民法院提出\n书面意见。\n人民法院应当自收到假释建议书之日起一个月以内作出裁定；案情复杂或者情况特殊的，\n可以延长一个月。裁定书的副本应当抄送同级人民检察院。\n7\n第五十四条人民法院裁定假释的，监狱应当按期假释并发给假释证明书。\n对被假释的罪犯，依法实行社区矫正，由社区矫正机构负责执行。被假释的罪犯，在\n假释考验期限内有违反法律、行政法规或者国务院有关部门关于假释的监督管理规定的行为，\n尚未构成新的犯罪的，社区矫正机构应当向人民法院提出撤销假释的建议，人民法院应当自\n收到撤销假释建议书之日起一个月以内作出裁定。人民法院裁定撤销假释的，由公安机关将\n罪犯送交监狱收监。\n第六十八条监狱应当依法保障罪犯的通信权利。\n罪犯在服刑期间可以与他人通信，但是来往信件应当经过安全检查。发现涉嫌危害国家\n安全或者犯罪活动的信件，应当扣留并依法作出处理。\n罪犯写给监狱的上级机关和监察、司法等国家机关的信件，不受检查。\n第八十六条被判处有期徒刑和被减为有期徒刑的罪犯，其配偶、直系亲属或者监护人病危、\n死亡的，或者家中发生重大变故，确需本人离监处理的，经本人书面申请，监狱可以根据情\n况特许其离监探望或者处理，由监狱人民警察押解。\n第一百零四条监狱对参加劳动的罪犯，应当按照有关规定给予报酬并执行国家有关劳动保\n护的规定。"}, {"title": "《中华人民共和国社会救助法》已由第十四届全人常于2026年4月30日通过，现予公", "detail": "布，\n自2026年7月1日起施行。\n第三条社会救助坚持城乡统筹，坚持尽力而为、量力而行，坚持保基本、兜底线、救急难、\n可持续，坚持与其他社会保障制度相衔接，坚持与经济社会发展相适应。\n社会救助工作遵循公开、公平、公正、便民、及时的原则。\n第四条社会救助实行党委领导、政府负责、民政牵头、部门协同、社会参与的工作机制。\n县级以上人民政府建立社会救助协调机制，统筹、协调、督促、指导有关部门在各自职\n责范围内做好社会救助工作。协调机制具体工作由县级以上人民政府民政部门承担。\n第十三条社会救助对象包括特困人员、最低生活保障家庭、最低生活保障边缘家庭、刚性\n支出困难家庭、受灾人员、基本生活暂时出现严重困难的人员、需要疾病应急救助人员以及\n生活无着的流散人员等。\n第十五条社会救助分为基本生活救助、专项社会救助和急难社会救助。\n基本生活救助包括特困人员供养和最低生活保障。\n专项社会救助包括医疗救助、教育救助、住房救助、就业救助、受灾人员救助。\n急难社会救助包括临时救助、疾病应急救助、生活无着的流散人员救助。\n第十六条对无劳动能力、无生活来源且无法定赡养、抚养、扶养义务人，或者其法定义务\n人无履行义务能力的老年人、未成年人、残疾人等特困人员，由社会救助管理部门给予特困\n人员供养，提供基本生活条件、必要的照料服务、疾病治疗，办理丧葬事宜等。\n特困人员可以在供养服务机构集中供养，也可以在家分散供养。特困人员可以自行选择\n供养形式。\n8\n特困人员中的未成年人年满十八周岁后，仍在义务教育或者高中阶段教育（含中等职业\n教育）阶段就学的，继续予以供养。\n第五十六条社会救助管理部门和乡镇人民政府、街道办事处可以将社会救助中属于政府职\n责范围且适合通过市场化方式提供的服务事项，通过政府购买服务方式实施。\n第七十六条对社会救助管理部门或者乡镇人民政府、街道办事处作出的关于社会救助的行\n政行为不服的，可以依法申请行政复议或者提起行政诉讼。"}, {"title": "4月10日，最高人民法院、最高人民检察院联合发布《关于办理贪污贿赂刑事案件适用", "detail": "法律若干问题的解释（二）》。\n第一条单位受贿数额在二十万元以上的，或者数额在十万元以上不满二十万元，具有下列\n情形之一的，应当认定为刑法第三百八十七条【单位受贿罪】第一款规定的“情节严重”：\n（一）多次索贿的；\n（二）为他人谋取不正当利益，致使公共财产、国家和人民利益遭受损失的；\n（三）赃款赃物用于非法活动的;\n（四）拒不交代赃款赃物去向或者拒不配合追缴工作，致使无法追缴的；\n（五）造成恶劣影响或者其他严重后果的。\n单位受贿数额在二百万元以上的，或者数额在一百万元以上不满二百万元，具有前款规\n定的情形之一的，应当认定为刑法第三百八十七条【单位受贿罪】第一款规定的“情节特别\n严重”。\n第二条对单位行贿，个人行贿数额在二十万元以上、单位行贿数额在四十万元以上的，或\n者个人行贿数额在十万元以上不满二十万元、单位行贿数额在二十万元以上不满四十万元，\n具有下列情形之一的，应当依照刑法第三百九十一条【对单位行贿罪】的规定，以对单位行\n贿罪追究刑事责任：\n（一）向三个以上单位行贿的；\n（二）将违法所得用于行贿的；\n（三）在生态环境、财政金融、安全生产、食品药品、防灾救灾、社会保障、教育、医\n疗等领域行贿，实施违法犯罪活动的；\n（四）为谋取公职、荣誉称号行贿的；\n（五）为谋取职务、职级普升、调整行贿的；\n（六）造成恶劣影响或者其他严重后果的。\n对单位行贿，个人行贿数额在二百万元以上、单位行贿数额在四百万元以上的，或者个\n人行贿数额在一百万元以上不满二百万元、单位行贿数额在二百万元以上不满四百万元，具\n有前款规定的情形之一的，应当认定为刑法第三百九十一条【对单位行贿罪】第一款规定的\n“情节严重”。\n第三条向国家工作人员介绍贿赂，介绍个人行贿数额在十万元以上、介绍单位行贿数额在\n五十万元以上的，或者介绍个人行贿数额在五万元以上不满十万元、介绍单位行贿数额在二\n十五万元以上不满五十万元，具有下列情形之一的，应当认定为刑法第三百九十二条【介绍\n贿赂罪】规定的“情节严重”：\n（一）为三个以上请托人介绍贿赂的；\n9\n（二）向三个以上国家工作人员介绍贿赂的；\n（三）为请托人谋取不正当利益而介绍贿赂，致使公共财产、国家和人民利益遭受损失\n的；\n（四）造成恶劣影响或者其他严重后果的。\n第四条单位行贿数额在二十万元以上的，或者数额在十万元以上不满二十万元，具有下列\n情形之一的，应当认定为刑法第三百九十三条【单位行贿罪】规定的“情节严重”：\n（一）向三人以上行贿的；\n（二）将违法所得用于行贿的；\n（三）在生态环境、财政金融、安全生产、食品药品、防灾救灾、社会保障、教育、医\n疗等领域行贿，实施违法犯罪活动的；\n（四）对监察、行政执法、司法工作人员行贿，影响办案公正的；\n（五）造成恶劣影响或者其他严重后果的。\n单位行贿数额在二百万元以上的，或者数额在一百万元以上不满二百万元，具有前款规\n定的情形之一的，应当认定为刑法第三百九十三条【单位行贿罪】规定的“情节特别严重”。\n第五条国家工作人员的财产、支出明显超过合法收入，不能说明来源，差额在三百万元以\n上不满一千万元、差额在一千万元以上的，应当分别认定为刑法第三百九十五条【巨额财产\n“子，“子，一集【类\n实施前款行为，具有下列情形之一的，从重处罚：\n（一）将支出用于非法活动的；\n（二）曾因瞒报财产依纪依法被处分的。\n第六条隐瞒在境外的存款，折合人民币数额在三百万元以上的，应当认定为刑法第三百\n九十五条第二款【隐瞒境外存款罪】规定的“数额较大”。\n实施前款行为，具有下列情形之一的，从重处罚：\n（一）将存款用于非法活动的；\n（二）曾因隐瞒在境外的存款依纪依法被处分的。\n在被追诉前主动交代并积极配合将存款转回境内的，可以认定为刑法第三百九十五条第\n二款规定的“情节较轻”。\n第七条私分国有资产，数额在二十万元以上不满二百万元的，或者私分救灾、抢险、防汛、\n优抚、帮扶、移民、救济、防疫、社会捐助、社会保险基金等特定款物，数额在十万元以上\n不满二十万元的，应当认定为刑法第三百九十六条第一款【私分国有资产罪】规定的“数额\n较大”；数额在二百万元以上的，或者私分上述特定款物，数额在一百万元以上不满二百万\n元的，应当认定为刑法第三百九十六条第一款【私分国有资产罪】规定的“数额巨大”。\n第八条刑法第一百六十三条规定的非国家工作人员受贿罪、第一百六十四条规定的对非国\n家工作人员行贿罪、第二百七十一条规定的职务侵占罪、第二百七十二条规定的挪用资金罪\n定罪量刑标准分别参照受贿罪、行贿罪（单位行贿罪）、贪污罪、挪用公款罪定罪量刑标准\n执行。\n第九条个人通过虚构付款事由或者将单位应收账款不按规定入账等逃避单位监管的方式，\n将公款提供给其他单位使用的，应当认定为《全国人民代表大会常务委员会关于（中华人民\n10\n共和国刑法）第三百八十四条第一款的解释》第二项规定的“以个人名义将公款供其他单位\n使用”。\n注：国家工作人员利用职务上的便利，挪用公款“归个人使用”的含义问题，解释如下：\n有下列情形之一的，属于挪用公款“归个人使用”：\n(一)将公款供本人、亲友或者其他自然人使用的；\n(二)以个人名义将公款供其他单位使用的；\n(三)个人决定以单位名义将公款供其他单位使用，谋取个人利益的。\n第十条挪用公款数额巨大，因客观原因在提起公诉前不能退还的，应当认定为刑法第三百\n八十四条【挪用公款罪】规定的“挪用公款数额巨大不退还”。在提起公诉前办案机关依照\n职权将公款追回的，可以不认定为“挪用公款数额巨大不退还”，但是量刑时应当考虑其与\n被告人自己退还情形的区别。\n第十一条受贿数额一般按照收受财物时的财物价值认定。\n以收受股票、股权的预期收益作为贿赂形式，构成犯罪的，受贿数额按照案发时实际获\n利认定；案发时尚未实际获利的，受贿数额一般按照案发时涉案资产的市场价格与支付价格\n的溢价认定。\n第十二条对于真伪不明的财物和珠宝、玉石、字画、手表、贵重金属等特定财物，应当进\n行真伪鉴定。\n对于价值不明的财物，应当进行价格认定。对于珠宝、玉石、字画、手表、贵重金属等\n特定财物，一般应当进行价格认定，但是购买票据齐全，能够有效证明收受财物当时真实价\n格，行受贿双方无异议的，不作价格认定。\n经过价格认定的财物，一般以认定价格认定受贿数额，但是行贿人按照受贿人授意购买\n特定物品后给予受贿人的，应当以行贿人实际支付的购买金额认定受贿数额。\n第十三条国家工作人员利用本人职权或者地位形成的便利条件，收受请托人财物，向请托\n人承诺通过其他国家工作人员职务上的行为为请托人谋取不正当利益的，应当依照刑法第三\n百八十八条的规定，以受贿论处。明知请托人有不正当的具体请托事项而收受财物的，视为\n承诺为请托人谋取不正当利益。国家工作人员是否向其他国家工作人员转达请托事项，不影\n响受贿罪的认定。\n第十四条国家工作人员通过职务上有隶属、制约关系的其他国家工作人员为请托人谋取利\n益，应当认定为“利用职务上的便利”。职务上的隶属、制约关系，不限于主管关系，也不\n限于直接上下级关系，应当结合国家工作人员任职单位的性质、职能、所任职务以及法律规\n定、制度安排、政策影响、实践惯例等具体认定。\n第十五条以单位名义收受财物，但以个人非法占有为目的或者收受的财物归个人所有的，\n以受贿罪定罪处罚。\n第十六条为谋取不正当利益向国家工作人员行贿，具有下列情形之一的，以单位行贿罪定\n罪处罚：\n（一）单位集体决定，违法所得归单位所有的；\n（二）单位实际控制人或者主管人员决定，违法所得归单位所有的。\n11\n个人财产和单位财产高度混同，单位通过行贿获得不正当利益实际归个人所有的，以行\n贿罪定罪处罚。\n第十七条刑法第三百九十二条【介绍贿赂罪】规定的“介绍贿赂”，是指在请托人和国家\n工作人员之间沟通关系、撮合条件，使贿赂行为得以实现的行为。\n实施介绍贿赂行为，又与请托人或者国家工作人员共同实施行贿或者受贿行为，同时构\n成介绍贿赂罪和行贿犯罪或者受贿犯罪共犯的，依照处罚较重的规定定罪处罚。\n介绍贿赂过程中，在国家工作人员不知情的情况下收受请托人的财物占为己有，符合刑\n法第三百八十八条之一规定的，以利用影响力受贿罪定罪处罚；在国家工作人员不知情的情\n况下截留部分财物占为己有，同时构成利用影响力受贿罪和其他犯罪的，以利用影响力受贿\n罪和其他犯罪数罪并罚。\n以非法占有为目的，虚构与国家工作人员关系密切的事实，骗取请托人财物的，以诈骗\n罪定罪处罚。\n第十八条私分国有资产虽经集体研究，但私分范围仅限于单位领导和管理层人员，且对单\n位其他人员隐瞒实情的，以贪污罪定罪处罚。\n单位非法收受财物后，以单位名义集体私分给个人，依照刑法第三百八十七条的规定，\n以单位受贿罪定罪从重处罚，集体私分行为作为量刑情节考虑。\n第十九条司法机关、行政执法机关以外的单位违反国家规定，将应当上缴国家的罚没财物，\n以单位名义集体私分给个人的，对直接负责的主管人员和其他直接责任人员以滥用职权罪定\n罪处罚，但具有本解释第十八条第一款规定的情形的，以贪污罪定罪处罚。\n第二十条国家工作人员不以个人占有为目的，利用职务上的便利，用公共财物向他人行贿，\n同时构成行贿罪和渎职犯罪的，数罪并罚。\n第二十一条监察机关掌握的被调查人贪污贿赂行为尚未达到数额较大，被调查人主动、如\n实供述监察机关尚未掌握的本人绝大部分犯罪事实的，以自首论。\n第二十二条犯罪分子具有下列情形之一的，可以认定为刑法第三百八十三条【对犯贪污罪\n的处罚规定】第三款规定的“积极退赃”：\n（一）全部退赃的；\n（二）积极配合办案机关追缴赃款赃物，且大部分赃款赃物已被查封、扣押、冻结的；\n（三）共同犯罪的犯罪分子对实际分取的赃款赃物已经全部退缴，并自愿继续退缴赃款\n赃物的。\n应犯罪分子要求或者经犯罪分子同意，犯罪分子亲友自愿代其退赃，具有前款情形之一\n的，视为犯罪分子积极退赃。\n第二十三条犯罪分子违法所得的财物及其收益，应当予以追缴或者责令退赔。\n对犯罪分子违法所得，一般应当追缴原物。行受贿双方形成贿赂房屋合意的，应当追缴\n房屋。有确实、充分证据证明原物已经转化为其他财物的，追缴转化后的财物。犯罪分子违\n法所得与其他合法财产共同转化为其他财物的，追缴与犯罪分子违法所得对应的份额及其收\n益。有确实、充分证据证明依法应当追缴、没收的涉案财物无法找到、被他人善意取得、价\n值灭失减损或者与其他合法财产混合且不可分割的，可以依法追缴、没收其他等值财产。\n12\n赃款赃物尚未交付给受贿人或者已经退还给行贿人的，依法向行贿人追缴；赃款赃物由\n第三人代为持有、保管的，依法向第三人追缴。\n模拟题"}, {"title": "关于BOSS发展新质生产力重要论述，下列说法不准确的是（）", "detail": "A.原始创新是科技创新的“源头活水”，决定着新质生产力发展的根基与后劲\nB.科技成果转化，是连接基础研究与产业应用的桥梁，是科技创新从实验室走向生产线的关\n键一跃\nC.创新链是引领、产业链是载体、资金链是血液、人才链是根基\nD.加强政府主导的产学研深度融合，发挥科技型骨干企业引领支撑作用\n【答案】D"}, {"title": "关于义乌发展经验，下列说法不准确的是（）", "detail": "A.“义乌发展经验”是因地制宜发展县域经济的成功实践\nB.“义乌发展经验”的精髓的精髓，是“莫名其妙”的发展、“无中生有”的发展、“点石成\n金”的发展\nC.各地区要引进义乌发展经验，坚持小商品大市场、无中生有创业创新\nD.义乌被称为世界小商品之都，全球小商品贸易中心，2025年外贸出口额居全国县（市、\n区）首位\n【答案】C"}, {"title": "关于树立和践行正确政绩观，下列说法不准确的是（）", "detail": "A.好干部要做到信念坚定、为民服务、勤政务实、敢于担当、清正廉洁\nB.树立和践行正确政绩观，起决定性作用的是當性\nC.在社会主义市场经济条件下，“大公无私”已不合时宜，因为干部的合理合法利益也要承\n认\nD.树立正确政绩观，必须处理好稳和进、立和破、虚和实、标和本、近和远的关系\n【答案】C"}, {"title": "关于《中华人民共和国监狱法》，下列说法不准确的是（)", "detail": "A.被判处死刑缓期二年执行、无期徒刑、有期徒刑的罪犯，在监狱内执行刑罚。\nB.监狱工作应当坚持惩罚和改造相结合、教育和劳动相结合，以改造人为宗旨\nc.罪犯在被交付执行刑罚前，剩余刑期在三个月以下的，由看守所代为执行\nD.无期徒刑减为有期徒刑的，由监狱提出减刑建议，报经省、自治区、直辖市监狱管理机关\n审核同意后，提请所在地中级人民法院裁定\n【答案】D\n13\n公基全程精讲班\n（送政治理论+常识判断+时政课）\n公基80+必备刷题课\n刺猬\n刺猬\n云印\n云印\nT：\n五分打印首单免费\n五分打印首单免费\n超高质量满1.9包邮\n超高质量满1.9包邮\n时政热点专项班\n政治理论+常识判断+时政课\n刺猬\n刺猬\n云印\n云印\n.\nS\nS\n五分打印首单免费\n五分打印首单免费\n超高质量满1.9包邮\n超高质量满1.9包邮\n14"}]}, {"month": "2026年5月", "year": 2026, "items": [{"title": "5月1日出版的第9期《求是》杂志发表重要文章《在省部级主要领导干部学习", "detail": "贯彻党的二十届四中全会精神专题研讨班上的讲话》"}, {"title": "制定和实施五年规划是我们党治国理政一条重要经验，是中国特色社会主义制", "detail": "度一个重要政治优势，有利于实现党的领导，有利于集中力量办大事，有利于前瞻性把\n握战略问题，有利于保持事业连续性"}, {"title": "在制定实施五年规划的长期实践中，我们党创造积累了丰富经验，包括坚持党", "detail": "中央集中统一领导，坚持从实际出发，坚持全国一盘棋，坚持发扬民主、集思广益，坚\n持规划法定原则等。我们要坚定制度自信，不断结合新的实际把这一优势发扬光大。"}, {"title": "党的二十届四中全会对“十五五”时期经济社会发展作出战略部署，要全面深", "detail": "刻准确领会和把握。"}, {"title": "我国发展处于战略机遇和风险挑战并存、不确定难预料因素增多的时期。", "detail": "(5）\n建设现代化产业体系、实现产业体系整体跃升，是“十五五”时期的重要战略\n任务。各地区各行业要找准定位，坚持智能化、绿色化、融合化方向。要保持制造业合\n理比重，大力发展先进制造业。"}, {"title": "我国人口多、市场大、产业全、发展动能强，有条件加快构建新发展格局。", "detail": "要\n坚持以国内大循环为主体，坚持惠民生和促消费、投资于物和投资于人紧密结合，努力\n提高国民经济循环质量和效率，让内需成为经济发展的主动力"}, {"title": "经济发展和社会发展相辅相成，必须协调并进。", "detail": "要把改善民生作为促进社会发\n展的重点，在发展经济的同时稳步提高人民生活品质。"}, {"title": "4月29日上午，第九届数字中国建设峰会在福建省福州市开幕。", "detail": "本届峰会的主\n题是“加快数智技术创新发展，深入推进数字中国建设”，将举办50余场对话交流活动，\n并设有数字中国创新大赛和现场体验区，同步举办闽江数字夜话、院士专家行等特色活\n动100余场。"}, {"title": "5月1日，第139届广交会第三期在广东广州开幕。", "detail": "本期广交会以“美好生活\"\n为主题，展览面积51.5万平方米，展位2.5万个，共有1.2万家参展企业携智慧医疗、\n功能纺织、绿色材料等领域的前沿成果与会。"}, {"title": "国家数据局近日发布的《数字中国发展报告（2025年)》显示，2025年数字中", "detail": "国发展指数达到170.1，比上年增长12.99%，数字中国建设取得新成效。数字经济核心\n产业增加值占国内生产总值的比重达到10.5%以上"}, {"title": "在五四青年节到来之际，中共中央总书记、国家主席、中央军委主席习近平给中", "detail": "国青年五四奖章暨新时代青年先锋奖获奖者代表回信，向全国各族青年致以节日祝贺并\n提出殷切期望。\n习近平在回信中说，你们牢记党的嘱托，扎根科技创新、乡村振兴、社会服务、卫\n国戌边等基层一线，以实干担当书写无悔青春，展现了新时代中国青年自信自强、昂扬\n向上的良好风貌。\n习近平强调，今年是“十五五”开局之年，青年建功正当其时。希望你们胸怀远大\n理想，矢志拼搏奋斗，带动广大青年把个人追求融入国家发展大局，立足各自岗位不断\n创造新业绩，在新征程上贡献青春力量。"}, {"title": "三峡集团发布消息，全球单机容量最大16兆瓦漂浮式海上风电平台一一\"三峡", "detail": "领航号”2日在广东阳江海域完成安装，我国在深远海漂浮式风电技术领域取得新进展。"}, {"title": "截至2025年12月底，全国共有共青团员7833.6万名，共青团组织515.0万", "detail": "个，分别比 2024 年底净增 301.8万名、75.3 万个。2025 年共发展团员913.7万名。"}, {"title": "5月3日，随着“江海号”盾构机在长江入海口水域下75米深处完成掘进任务，", "detail": "被誉为新\"万里长江第一隧”的海太长江隧道掘进抵达最深点。这是目前国产16.6米级\n超大直径盾构机在水下隧道掘进的最深纪录，标志着我国在超大直径、超高水压、超大\n埋深条件下的水下盾构施工技术取得关键突破。"}, {"title": "北京时间5月5日凌晨，2026斯诺克世界锦标赛在英国谢菲尔德落下惟幕。", "detail": "中\n国00后小将吴宜泽以18比17力克英格兰名将肖恩墨菲夺冠，成为首位00后斯诺克世\n锦赛冠军，也是继赵心童后第二位在世锦赛登顶的中国球员。"}, {"title": "今年5月是第六个“民法典宣传月”。", "detail": "记者5月6日从司法部获悉，为推动民\n法典宣传活动深入开展，中央宣传部、司法部、全国普法办联合印发《2026年“民法典\n宣传月”工作方案》，部署开展相关工作。"}, {"title": "《中华人民共和国监狱法》已由中华人民共和国第十四届全国人民代表大会常", "detail": "务委员会第二十二次会议于2026年4月30日修订通过，现予公布，自2026年11月\n1日起施行。"}, {"title": "《中华人民共和国社会救助法》已由中华人民共和国第十四届全国人民代表大", "detail": "会常务委员会第二十二次会议于2026年4月30日通过，现予公布，自2026年7月1\n日起施行。"}, {"title": "中共中央办公厅、国务院办公厅印发《美丽中国建设成效考核办法》", "detail": ""}, {"title": "在党中央集中统一领导下，考核工作由中央生态环境保护督察工作领导小组牵", "detail": "头组织，由中央生态环境保护督察工作领导小组办公室、中央组织部会同有关部门开展。"}, {"title": "考核工作应当:", "detail": "坚持注重实绩、激励担当，推动树立和践行正确政绩观，提高对党中央生态文明建\n设决策部署的执行力;\n坚持目标导向、问题导向，针对人民群众反映强烈的突出生态环境问题，持续深入\n打好污染防治攻坚战，围绕美丽中国建设目标任务设置关键性、引领性考核指标，狠抓\n重点领域和关键环节；\n坚持依规依法、群众认可，严格依照有关党内法规、生态环境法典等法律要求，规\n范考核方式和程序，做到精准科学、客观公正，注重减轻基层负担，充分发挥社会监督\n作用;\n坚持考用结合、以考促干，强化考核结果运用，以考核促进生态环境质量改善和相\n关工作落实，压实生态环境保护责任。"}, {"title": "考核采用百分制评分，合理设置加分项和减分项，根据评分情况，考核结果划", "detail": "分为优秀、良好、合格、不合格4个等级。省（自治区、直辖市）发生特别重大环境污\n染事件或者特别重大生态破坏事件的，年度考核结果不得确定为“良好”及以上"}, {"title": "考核工作每年开展1次，原则上于次年6月底前完成，其中综合评价工作于次", "detail": "年3月底前基本完成。"}, {"title": "考核采取下列步骤：自评总结，核实核证，综合评价，结果反馈。", "detail": ""}, {"title": "今年5月8日是第79个世界红十字日，中国红十字会总会和各地红十字会将", "detail": "围绕“守望人道、协力前行”这一主题集中开展一系列人道服务、人道传播、资源动员\n等活动。"}, {"title": "5月3日，2026年世界泳联跳水世界杯总决赛在北京落幕，中国队包揽全部9", "detail": "枚金牌。中国选手王宗源、蒋林静分获2026年世界泳联跳水世界杯最佳男、女运动员。"}, {"title": "北京时间2026年5月6日16时34分，天舟九号货运飞船顺利撤离空间站组", "detail": "合体，转入独立飞行阶段，将于近期择机受控再入大气层，飞船再入过程中烧蚀残存的\n少量残骸将落入预定安全海域。"}, {"title": "5月5日，中国首艘民资建造科考船“海鹰加科”号在浙江温岭市松门镇建成", "detail": "下水。这艘由民间资本投资约1.5亿元建造的科考船总长82米，计划满载排水量3500\n吨，续航力1万海里，自持力大于60天，具备在无限航区执行多学科综合考察的能力。"}, {"title": "2026年是中国越剧诞生120周年。", "detail": "第六届中国越剧艺术节将在越剧故乡绍兴\n拉开帷幕，整体活动为期一个月。第六届中国越剧艺术节以“百廿正青春，浙里越有戏”\n为核心主题。\n越剧：中国五大戏曲剧种之一，全国第二大剧种。代表作：《梁山伯与祝英台》、\n《西厢记》、《红楼梦》、《祥林嫂》、《孔雀东南飞》。"}, {"title": "5月7日至9日，2026北京香山论坛先导会在北京举办，本届先导会以\"全球", "detail": "安全治理：挑战与出路”为主题。"}, {"title": "5月2日，国家“十四五”规划重点能源项目-", "detail": "浙江松阳抽水蓄能电站两条\n深度超600米的竖井实现全线贯通，刷新我国抽水蓄能领域最深竖井工程纪录。"}, {"title": "5月7日，国际奥委会宣布，中国上海、日本东京、加拿大蒙特利尔和美国奥", "detail": "兰多成为2028年洛杉矶奥运会资格系列赛举办城市。这是继2024年巴黎奥运会资格赛\n后，该项赛事再次落户上海。"}, {"title": "国家知识产权局发布《二〇二五年中国知识产权保护状况》白皮书，截至2025", "detail": "年底，我国发明专利有效量达631.8万件，同比增长11.1%；有效注册商标量达5303.2\n万件，同比增长6.5%；著作权年登记总量1067.7万件；累计认定地理标志产品5066\n个。全年受理农业植物新品种权申请17104件，同比增长15.26%。"}, {"title": "5月9日，记者从安徽省量子计算芯片重点实验室获悉，搭载单核180个计算", "detail": "比特自主超导量子芯片的“本源悟空-180”量子计算机已上线运行，5月9日起开始接\n收全球量子计算任务。\n）\n届时，会议将围绕“建设开放、可预期的区域和多边经贸秩序”“打造创新、有活力的\n贸易投资合作新引I擎”等议题开展深入讨论，为11月APEC领导人非正式会议贡献经贸\n成果。"}, {"title": "新华社北京5月8日电国务院总理李强日前签署国务院令，公布修订后的《中", "detail": "华人民共和国行政复议法实施条例》，自2026年7月1日起施行。"}, {"title": "2026年5月8日是第79个世界红十字日，中国红十字会总会和各地红十字会", "detail": "将围绕“守望人道、协力前行”这一主题集中开展一系列人道服务、人道传播、资源动\n员等活动。"}, {"title": "5月6日，2026全球数字合作交流会暨全球数据周在上海开幕。", "detail": "大会以\"数据\n产业化、产业数字化、数据国际化”为主题，采用“1+1+N+X”国际化布局，汇聚全\n球政企学研精英，共商数据要素国际合作大计，助力上海建设国际数字之都。"}, {"title": "5月8日，全球首艘2.4万箱甲醇双燃料集装箱船在江苏南通建造完工并命名。", "detail": "该船是目前世界最大级别甲醇双燃料集装箱船，标志着我国在超大型清洁能源船舶设计\n建造领域取得又一重大突破。该船被命名为\"东方智慧”轮。"}, {"title": "5月8日，全球首个具备室内降雪场景的智能网联新能源汽车全季冰雪试验基", "detail": "地项目在内蒙古牙克石市正式奠基开工，标志着我国汽车极端环境测试领域建设迈出里\n程碑式一步。"}, {"title": "为表彰我国青年运动员的突出贡献，共青团中央、全国青联决定，授予苏翊鸣、", "detail": "王心迪、党鹤松、王涛、余爽、刘子旭、纪立家等7名青年运动员中国青年五四奖章。"}, {"title": "5月10日，由教育部等九部门联合主办的2026年职业教育活动周正式启动，", "detail": "活动周时间为5月10日至16日，主题为“一技在手，一生无忧”"}, {"title": "5月9日，由教育部等七部门联合主办的2026年全民终身学习活动周在江苏", "detail": "苏州启动。今年全民终身学习活动周以“让学习成为一种生活方式”为主题。"}, {"title": "5月1日晚，北京梅兰芳大剧院，国家京剧院新创的京剧诗乐《春·秋》首次亮", "detail": "相。\n2025年，国家京剧院建院70周年之际，总书记给国家京剧院青年艺术工作者回信，\n强调“践行艺术为民，坚持崇德尚艺、守正创新，让京剧艺术持续焕发时代光彩”。\n《春·秋》以二十四节气为脉络，融汇古典诗词、京剧声腔与民族管弦乐，构建“新\n国风”美学表达。"}, {"title": "5月11日8时14分，搭载天舟十号货运飞船的长征七号遥十一运载火箭在我", "detail": "国文昌航天发射场点火发射，飞船顺利进入预定轨道，发射任务取得圆满成功。13时11\n分，天舟十号货运飞船成功对接于空间站天和核心舱后向端口。交会对接完成后，天舟\n十号将转入组合体飞行段。\n天舟十号货运飞船是世界现役货物运输能力最大、在轨支持能力最全面的货运飞船\n也被称为运载能力最强的货运飞船\n是“箭上故障诊断与处置系统”。“扁鹊”故障诊断系统具备三个主要功能，分别是故\n障诊断、弹道重规划和制导姿控重构"}, {"title": "北京时间5月11日凌晨，2026伦敦世界乒乓球团体锦标赛男子团体决赛，中", "detail": "国队总比分3比0战胜日本队，实现世乒赛男团十二连冠"}, {"title": "5月10日，粤港澳大湾区首个\"华龙一号”核电项目-", "detail": "中广核广东太平岭核\n电4号机组核岛开始首罐混凝土浇筑。这是继该核电项目1号机组投产、2号机组装料\n后的又一关键节点，标志着太平岭核电二期工程进入全面建设阶段。"}, {"title": "2026年国际博物馆日中国主会场活动将于5月18日在内蒙古举行，围绕“博", "detail": "物馆：联结世界的桥梁”主题，集中展示“十四五”期间我国博物馆事业发展的最新成\n果，进一步搭建博物馆与公众沟通的桥梁。"}, {"title": "2026世界品牌莫干山大会5月10日在浙江德清开幕。", "detail": "本次大会以“品牌，让\n世界更美好”为主题，搭建品牌交流对话平台，汇聚政府部门、中外企业、高等院校、\n行业协会等深入探讨品牌建设，推动中国品牌高质量发展，促进世界品牌交流互鉴。"}, {"title": "5月10日，“探索一号”科考船搭载“奋斗者”号载人潜水器顺利抵达广州，", "detail": "圆满完成“全球深渊探索计划”太平洋穿越科考航次暨首次中国-智利阿塔卡马海沟载人\n深潜联合科考航次。这是我国深海科技力量持续挺进全球深渊、深化国际海洋科技合作\n的重要实践，也是积极参与全球海洋治理、推动构建海洋命运共同体的又一标志性成果。"}, {"title": "5月11日，2026世界数字教育大会在浙江省杭州市开幕。", "detail": "本次大会主题为\"人\n工智能+教育：变革发展治理”，探讨人工智能如何推动教育系统性变革、促进教育高\n质量发展。大会同期举办全球数字教育成果展。"}, {"title": "2026年5月12日，是第18个全国防灾减灾日，主题是“人人讲安全、个个", "detail": "会应急一提高防灾减灾救灾能力\""}, {"title": "在第二次青藏科考中，中国科学院青藏高原研究所环境变化与多圈层过程团队", "detail": "高晶研究员和姚檀栋院士联合国内外多家科研机构和大学，经过八年科学攻关，成功完\n成了32次高海拔区浮空艇大气水汽稳定同位素和气象要素三维综合观测，并结合同位素\n理论模型及同位素示踪大气环流模式模拟，揭示了在西风主导的冬春季稳定天气条件下\n‘亚洲水塔”水汽输送的垂直输送带调控机制。\n这项研究表明，“亚洲水塔”水汽垂直输送由双重“输送带”驱动：高空西风带来\n外源水汽，近地面以局地蒸发水汽为主。"}, {"title": "习近平会见联合国教科文组织总干事阿纳尼，指出，联合国教科文组织为增进", "detail": "各国人民相互了解信任、推动不同文明交流互鉴作出了重要贡献，也为改革完善全球教\n育、科学、文化治理发挥了积极作用。中方积极支持联合国教科文组织工作，双方共同\n为维护世界和平、促进全球发展做了很多事情。\n强调，当前，和平、发展、合作、共赢的时代潮流没有变，但冷战思维、霸权主义、\n单边主义卷土重来，全球治理走到新的十字路口。中方始终坚定践行真正的多边主义\n支持和维护联合国权威，支持联合国教科文组织在全球治理中发挥重要作用"}, {"title": "5月13日，记者从中国科学院空间应用工程与技术中心了解到，随天舟十号上", "detail": "行太空的人类“人工胚胎”实验样本，已装置于中国空间站实验模块，目前实验进展顺\n利。这是世界首次在太空开展的人类”人工胚胎”实验"}, {"title": "5月13日，中央社会工作部公布《志愿服务标识基本规范（试行）》，对志愿", "detail": "服务标识含义以及设计、使用、管理等作出规定。志愿服务标识可用于志愿服务活动会\n议、场所站点、文化产品等，不得用于商标、商业广告以及其他任何营利性活动。开展\n重大志愿服务活动和涉外志愿服务活动时，应当使用“中国志愿服务标识”，有自有志\n愿服务标识的可同时使用，但应当突出“中国志愿服务标识”\n志愿\n志愿\n国\n国\n服\n中"}, {"title": "记者从中国科学院大连化学物理研究所获悉，近期成功研发了以氢气和金属为", "detail": "电极的气-固氢负离子原型电池\n（简称“气固电池”），通过“氢电共储”模式，为常温\n常压高效储氢提供了原型验证。相关成果5月13日在国际学术期刊《焦耳》发表。该电\n池以氢气、金属镁分别为正负极活性物质，可实现充氢放电、充电放氢，同步完成电化\n学储能与氢气储放。"}, {"title": "崇太长江隧道正在加紧施工，它连接着上海崇明和江苏太仓，是我国目前建设", "detail": "标准最高、掘进距离最长、规模最大的世界级高铁越江隧道。"}, {"title": "5月12日晚，第79届法国戛纳国际电影节在法国南部海滨城市戛纳拉开惟幕。", "detail": "法国夏纳国际电影节与德国柏林国际电影节、意大利威尼斯国际电影节并称为欧洲三大\n国际电影节。"}, {"title": "5月14日上午，国家主席习近平在北京人民大会堂同来华进行国事访问的美国", "detail": "总统特朗普举行会谈。\n习近平指出，当前百年变局加速演进，国际形势变乱交织，中美两国能不能跨越“修\n昔底德陷阱”，开创大国关系新范式？能不能携手应对全球性挑战，为世界注入更多稳\n定性？能不能着眼两国人民福祉和人类前途命运，共同开创两国关系美好未来？这些是\n历史之问、世界之问、人民之问，也是大国领导人需要共同书写的时代答卷。我愿同特\n朗普总统共同为中美关系这艘大船领好航、掌好舵，让2026年成为中美关系继往开来的\n历史性、标志性年份。\n习近平强调，中方致力于中美关系稳定、健康、可持续发展。我同特朗普总统赞同\n将构建“中美建设性战略稳定关系”作为中美关系新定位，将为未来3年乃至更长时间\n的中美关系提供战略指引l，相信会受到两国人民和国际社会的欢迎。\n‘建设性战略稳定”应该是合作为主的积极稳定，应该是竞争有度的良性稳定，应\n该是分歧可控的常态稳定，应该是和平可期的持久稳定。“中美建设性战略稳定关系\n不是一句口号，而应该是相向而行的行动。\n习近平指出，中美经贸关系的本质是互利共赢，面对分歧和摩擦，平等协商是唯一\n正确选择。昨天两国经贸团队达成了总体平衡积极的成果，这对两国老百姓和世界都是\n好消息。双方应一道维护好当前来之不易的良好势头。中国开放的大门只会越开越大，\n美国企业正在深度参与中国改革开放，中方欢迎美国对华加强互利合作。\n习近平指出，双方要落实我们达成的重要共识，进一步用好政治外交、两军沟通渠\n道。拓展经贸、卫生、农业、旅游、人文、执法等领域交流合作。\n习近平强调，台湾问题是中美关系中最重要的问题。处理好了，两国关系就能保持\n总体稳定。处理不好，两国就会碰撞甚至冲突，将整个中美关系推向十分危险的境地。\n台独”与台海和平水火不容，维护台海和平稳定是中美双方最大公约数，美方务必慎\n之又慎处理台湾问题。"}, {"title": "5月15日上午，国家主席习近平在中南海同美国总统特朗普举行小范围会唔。", "detail": "指出，特朗普总统此访是一次历史性、标志性的访问，我们共同确定了中美建设性战略\n稳定关系的新定位，就保持经贸关系稳定、拓展各领域务实合作、妥善解决彼此关切达\n成重要共识，同意就国际和地区问题加强沟通和协调。访问有利于促进相互理解、加深\n彼此信任、增进两国人民福祉。这也再次表明，中美在相互尊重基础上实现和平共处、\n合作共赢，走出一条正确相处之道，是两国人民所愿和世界各国人民所盼。"}, {"title": "潘建伟院士领衔的科研团队联合国内多家科研机构、大学，近期成功研制出可", "detail": "编程量子计算原型机“九章四号”，其针对特定问题的算力远超当前全球最快超级计算\n机ElCapitan，成功建立了国际上最强的“量子计算优越性”。相关成果5月13日在国\n际学术期刊《自然》发表。"}, {"title": "5月16日出版的第10期《求是》杂志发表习近平重要文章《做强做优做大实", "detail": "体经济》"}, {"title": "不论经济发展到什么时候，实体经济都是我国经济发展、我们在国际经济竞争", "detail": "中赢得主动的根基。我国经济是靠实体经济起家的，也要靠实体经济走向未来。"}, {"title": "实体经济是一国经济的立身之本，是财富创造的根本源泉，是国家强盛的重要", "detail": "支柱。"}, {"title": "制造业是立国之本、强国之基。", "detail": "要把制造业高质量发展放到更加突出的位置，\n采取有力措施，推动先进制造业和现代服务业深度融合，坚定不移建设制造强国。制造\n业是实体经济的基础，实体经济是我国发展的本钱，是构筑未来发展战略优势的重要支\n撑。"}, {"title": "要深刻把握发展的阶段性新特征新要求，坚持把做实做强做优实体经济作为主", "detail": "攻方向，一手抓传统产业转型升级，一手抓战略性新兴产业发展壮大，推动制造业加速\n向数字化、网络化、智能化发展，提高产业链供应链稳定性和现代化水平。"}, {"title": "坚持把发展经济的着力点放在实体经济上", "detail": ""}, {"title": "当前，全球产业体系和产业链供应链呈现多元化布局、区域化合作、绿色化转", "detail": "型、数字化加速的态势，这是经济发展规律和历史大趋势，不以人的意志为转移。"}, {"title": "新时代新征程，以中国式现代化全面推进强国建设、民族复兴伟业，实现新型", "detail": "工业化是关键任务。"}, {"title": "坚持把金融服务实体经济作为根本宗旨。", "detail": "实体经济是金融的根基，金融是实体\n经济的血脉，服务实体经济是金融的天职。"}, {"title": "“十五五”时期，必须把因地制宜发展新质生产力摆在更加突出的战略位置,", "detail": "以科技创新为引领、以实体经济为根基，坚持全面推进传统产业转型升级、积极发展新\n兴产业、超前布局未来产业并举，加快建设现代化产业体系。"}, {"title": "必须坚持投资于物和投资于人紧密结合。", "detail": "既要扩大对实体经济和科技创新的\n有效投资，又要加强人力资源开发，促进物质资本和人力资本积累相协调，做到投资于\n物和投资于人双向赋能、相互促进。"}, {"title": "5月15日，国务院总理李强主持召开国务院常务会议。", "detail": "会议指出，当前我国城市发展正从大规模增量扩张阶段转向存量提质增效为主的阶\n段。要把城市更新摆在突出位置，坚持远近结合、突出重点，有力有序推进各项工作，\n建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市。\n会议指出，农业农村现代化关系中国式现代化全局和成色。要坚持把“三农”工作\n作为重中之重，不断夯实基础、提高发展质效。要遵循规律、因地制宜，提升农业综合\n生产能力，持续巩固拓展脱贫攻坚成果，拓宽农民增收致富渠道，推进宜居宜业和美乡\n村建设，始终守牢保障粮食安全和不发生规模性返贫的底线，\n会议指出，要适应人口发展面临的新形势，着力提高人口整体素质，努力保持适度\n生育水平和人口规模，持续积累和释放人力资源红利，推动人口高质量发展。要加快建\n设生育友好型社会，加强生育服务保障，完善婴幼儿照护服务，健全家庭综合支持政策\n体系。要积极应对人口老龄化，加强老年人社会保障，推动养老服务提质增效，大力发\n展银发经济。要围绕人口布局调整，完善土地供应、财政转移支付等与人口增减挂钩机\n制，实现公共服务资源利用最优化。\n会议指出，要锚定2035年建成教育强国目标任务，顺应人民群众对教育的新期待和\n经济社会发展新形势，全面提升基础教育质量。要加强基础教育资源统筹调配，落实随\n迁子女在常住地平等接受基础教育政策，加强农村留守儿童、困境儿童关心关爱，逐步\n缩小城乡、区域、校际、群体差距。要积极推进育人方式、办学模式、管理体制、保障\n机制改革，更好激发办学活力。"}, {"title": "5月28日至31日，2026世界智能产业博览会将在天津举办。", "detail": "本届博览会主\n题为“智行天下能动未来”，聚焦人工智能、智能网联车、低空经济等前沿领域。"}, {"title": "5月16日，第二艘国产大型邮轮\"爱达·花城号”从中船集团上海外高桥造船5", "detail": "号码头启航，开始为期12天的试航任务。按计划，第二艘国产大型邮轮\"爱达·花城号\"\n将在试航结束后逐步向船东完成项目报验，计划于2026年11月6日完成交付，交付后\n将从广州南沙国际邮轮母港开启首航季。"}, {"title": "5月16日，广东肇庆浪江抽水蓄能工程变速机组启动电气安装，这也是我国安", "detail": "装的首台国产变速机组。"}, {"title": "习近平近日就推动哲学社会科学高质量发展作出重要指示指出，党的十八大以", "detail": "来，哲学社会科学战线认真贯彻落实党中央决策部署，坚持“两个结合”，扎实推进知\n识创新、理论创新、方法创新，推出一批有价值的研究成果，有力服务了党和国家工作\n大局。\n强调，新征程上，要以新思想为指导，坚持和加强党的全面领导，深化党的创新理\n论体系化学理化研究阐释，加快构建中国哲学社会科学自主知识体系，更好回答中国之\n问、世界之问、人民之问、时代之问，努力开创哲学社会科学高质量发展新局面，为中\n国式现代化建设贡献更多智慧和力量。"}, {"title": "5月17日，国家主席习近平同俄罗斯总统普京分别向第十届中俄博览会致贺信。", "detail": "指出，今年是中俄战略协作伙伴关系建立30周年和《中俄睦邻友好合作条约》签署25\n周年。在双方共同努力下，中俄各领域合作不断走深走实，取得丰硕成果。\n强调，希望两国各界以本届博览会为契机，发挥中俄毗邻和互补优势，深化全方位\n务实合作，更好促进两国经济社会发展，持续增进两国人民福祉，为推动中俄新时代全\n面战略协作伙伴关系行稳致远作出新贡献。"}, {"title": "5月13日至15日，\"2026世界市长对话·成都”活动在四川成都举行。", "detail": "来自\n26个国家的32个城市及5个国际组织代表共同参加了活动。本次活动以“公园城市·和\n美共生”为主题"}, {"title": "5月15日，我国在东风商业航天创新试验区使用力箭一号遥十三运载火箭，成", "detail": "功将\"电建一号”卫星发射升空。“作为全球能源基建行业首颗专用×波段SAR卫星，\n填补了我国能源领域专用天基监测卫星的空白，标志着中国电建成功打通卫星研制、数\n据应用全链条，实现重大工程监测核心技术与数据完全自主可控。“"}, {"title": "5月18日，中国卫星导航定位协会发布《2026中国北斗时空产业发展白皮书》。", "detail": "白皮书显示，2025年我国北斗时空产业总体产值达到13323亿元，稳步迈入高质量发\n展的新阶段。"}, {"title": "第79届世界卫生大会将于18日至 23日在日内瓦举行。", "detail": "第79 届世界卫生大会\n的主题为“重塑全球健康，携手共担责任”"}, {"title": "5月18日，中国举重协会消息，2026年亚洲举重锦标赛5月17日在印度甘", "detail": "地讷格尔落幕。中国队16位选手出战，最终获得21金12银8铜，位列金牌和奖牌榜\n首位。"}, {"title": "2026年5月18日是第50个国际博物馆日，今年的主题为“博物馆：联结世", "detail": "界的桥梁”"}, {"title": "5月19日，从中国华能获悉，我国首个地热能超临界二氧化碳取热项目在河南", "detail": "郑州正式投产，标志着我国地热能高效开发利用领域实现新突破。"}, {"title": "5月19日上午，2026年中国网络文明大会在广西南宁开幕，今年的主题是\"文", "detail": "明网络空间昂扬奋进力量”，会期一天半。大会期间，将举办开幕式及主论坛、14场分\n论坛。"}, {"title": "5月18日电近日，中共中央办么厅印发了《中国共产党发展党员工作细则》，", "detail": "并发出通知，要求各地区各部门认真遵照执行。\n通知指出，发展党员工作是党的建设一项重要的基础性工程。各级党委及其组织部\n门要深入贯彻新时代党的建设总要求，贯彻全面从严治党战略方针，把抓好发展党员工\n作作为重大政治责任，认真贯彻执行《细则》各项规定并加强督促指导，坚持标准，严\n格程序、严格把关、严肃纪律，不断提高发展党员工作质量。要把政治标准放在首位\n加强教育培养，强化思想入党，从严政治审查，深入考察发展对象的入党动机、政治素\n质和现实表现，严把入口关。不断优化党员队伍结构，注重从青年和产业工人、农民、\n知识分子中发展党员，做好在新兴领域发展党员工作，进一步夯实基础，不断增强党的\n号召力凝聚力影响力。"}, {"title": "5月18日，首届“杰出外交使者奖章”颁授仪式在北京举行。", "detail": "包括俄罗斯前驻\n华大使杰尼索夫在内的8位中国人民的好朋友获得了这个奖章。中国外交部专门设立这\n一奖章，主要授予为促进中外友好作出重要贡献的驻华使节。"}, {"title": "5月20日上午，习近平在北京人民大会堂同来华进行国事访问的俄罗斯总统普", "detail": "京举行会谈。两国元首一致同意《中俄睦邻友好合作条约》继续延期。\n指出，今年是中俄战略协作伙伴关系建立30周年和《中俄睦邻友好合作条约》签署\n25周年。中俄两国签署睦邻友好合作条约，以法律形式确立了长期睦邻友好、全面战略\n协作的制度基础，中俄关系由此实现跨越式发展。中俄关系一步一个脚印走到今天这个\n高度，是因为双方以“干磨万击还坚劲”的毅力不断深化政治互信和战略协作，以“更\n上一层楼”的精神拓展各领域合作，以“乱云飞渡仍从容”的勇气捍卫国际公道正义、\n推动构建人类命运共同体。\n指出，中俄两国坚持在平等相待、相互尊重、重信守义、合作共赢的基础上发展新\n时代全面战略协作伙伴关系，政治互信不断深化，经贸、投资、能源、科技、人文、地\n方等合作持续推进，民心相通更加牢固。中俄关系进入更有作为、更快发展的新阶段。\n坚定不移推动中俄关系长期、健康、稳定、高质量发展，是双方着眼两国根本利益和世\n界发展大势作出的战略选择。\n强调，双方要聚焦两国发展振兴目标，充分发挥中俄合作机制全面、完备的特点，\n加强对全方位合作的统筹设计，推动经贸投资、能源资源、交通运输、科技创新等务实\n合作提质升级，积极布局前沿领域合作，以新质生产力打造增长新引擎；要立足续世\n代友好，加强教育、文化、电影、旅游、体育等人文交流合作，夯实两国友好的社会民\n意基础；要深化多边协作，进一步密切在联合国、上海合作组织、金砖国家、亚太经合\n组织等多边平台的协调和配合，坚定不移维护战后国际秩序和国际法权威，团结全球南\n方，引领全球治理体系改革的正确方向。\n会谈后，两国元首签署并发表《中华人民共和国和俄罗斯联邦关于进一步加强全面\n战略协作、深化睦邻友好合作的联合声明》，见证签署经贸、教育、科技等领域20项合\n作文件。\n访问期间，双方发表《中华人民共和国和俄罗斯联邦关于倡导世界多极化和新型国\n际关系的联合声明》，并达成了其他领域20项合作文件。"}, {"title": "5月20日下午，习近平在北京人民大会堂同俄罗斯总统普京会谈后共同会见记", "detail": "者。\n指出，这是普京总统第二十五次访问中国，充分体现出中俄关系的高水平和特殊性。\n主席指出，在我和普京总统的共同战略引引领下，中俄关系已经迈上新起点。双方要顺应\n和平、发展、合作、共赢的时代潮流，推动中俄关系实现更高质量发展。\n一是筑牢更高质量政治互信，坚定彼此战略支持。政治互信是中俄关系最鲜明的特\n征，也是《中俄睦邻友好合作条约》的宗旨和根本原则。\n二是赋能更高质量互利合作，携手推进各自发展振兴\n三是推进更高质量民心相通，厚植两国世代友好根基。我和普京总统决定今明两年\n举办两国第十个国家级主题年\n一一“中俄教育年”\n四是开展更高质量国际协作，改革完善全球治理"}, {"title": "5月20日下午，习近平同俄罗斯总统普京在北京人民大会堂共同出席“中俄教", "detail": "育年”开幕式。\n指出，教育是国与国之间连接民心、传承友谊的重要桥梁，是功在当代、利在干秋\n的崇高事业。长期以来，中俄教育合作持续深化、成效明显，丰富了中俄新时代全面战\n略协作伙伴关系的内涵。以“中俄教育年”为契机，双方要进一步凝聚合作共识、拓展\n合作领域、提升合作水平\n强调，教育兴则国家兴，教育强则国家强。中俄要深化人才培养合作，共同培育国\n际顶尖人才队伍和国家战略科技力量，携手攻克前沿科学难题，助力两国创新发展；要\n践行文明互鉴理念，推动文明传承和教育治理经验交流，共同提高工作水平；要续传\n统友好情谊，进一步释放教育合作潜力，促进两国民众相知相亲，让青少年在深入交流\n中增进友谊，培育中俄世代友好的接班人。"}, {"title": "习近平同巴基斯坦总统扎尔达里就中巴建交75周年互致贺电。", "detail": "指出，中国和巴\n基斯坦是山水相连、命运与共的好朋友和全天候战略合作伙伴。建交75年来，无论国际\n形势如何变化，中巴友谊始终坚如磐石、牢不可破。两国长期保持高水平政治互信、高\n水平务实合作、高水平安全合作、高水平国际协作，树立了国与国关系的典范。"}, {"title": "第十届丝绸之路国际博览会暨中国东西部合作与投资贸易洽谈会5月21日在陕", "detail": "西西安开幕。本届丝博会以“丝路融通新机遇·开放合作新篇章”为主题。\n74. 小满\n①夏天的第二个节气——小满\n②小满时节，小麦灌浆，暑气渐长，标志着夏天逐渐走向成熟。\n③满而不溢，是为小满。小满是时序的智慧，人在其中偶得点拨一一万事小满，便\n是圆满。\n④三候物候：一候苦菜秀。二候靡草死。三候麦秋至。\n③与小满有关的诗句:\n小满一一物\n物至于此小得盈满。\n小满一一麦穗初齐稚子娇，桑叶正肥蚕食饱。"}, {"title": "2026上海国际碳中和技术、产品与成果博览会（以下简称“上海国际碳中和博", "detail": "览会”）将于6月10日到12日在上海新国际博览中心举办。\n本届上海国际碳中和博览会聚焦“零碳变革，要素赋能”，由主题展览、系列活动、\n贸易对接三大板块构成。"}, {"title": "5月21日，2026文化强国建设高峰论坛在广东深圳开幕。", "detail": "本届论坛主题为\"文\n脉文运的传承与文化的创新创造”，由中央宣传部主办。"}, {"title": "5月21日，国务院总理李强主持召开国务院常务会议，研究推进全国统一大市", "detail": "场建设有关工作，审议通过《现代化应急体系建设“十五五”规划》，讨论《中华人民\n共和国中国人民银行法（修订草案）》。"}, {"title": "全国统一大市场建设", "detail": "①会议指出，建设全国统一大市场是构建新发展格局、推动高质量发展的需要。近\n年来，全国统一大市场建设取得积极成效和重要进展，但仍需持续用力、久久为功。\n2\n“三个纵深推进”：\n要纵深推进相关制度建设，进一步完善产权保护、市场准入、公平竞争、社会信用、\n市场退出等制度，做到有章可循、有法可依。\n要纵深推进市场设施高标准联通，畅通经济循环，有效降低全社会物流成本。\n要纵深推进重点领域市场统一，以点带面、点面结合，让群众和企业更加可感可及。\n要以更大力度打通卡点堵点，破除各种显性和隐性壁垒，充分释放市场活力和潜能。\n(2）应急管理\n会议指出，应急管理关乎人民群众生命财产安全，关乎改革发展稳定大局。\n要适应新形势新要求，加快建设现代化应急体系，深化应急管理改革创新，完善协\n同应对机制，推动构建大安全大应急格局。\n要突出风险源头管控，加强监测预报预警，提升本质安全水平，加快治理模式向事\n前预防转型。\n要优化应急力量布局，强化全要素支撑，夯实基层应急基础，统筹落实好人防、技\n防、工程防、管理防等措施。\n要全链条推动重点行业领域安全整治，压紧压实各级各方面责任，切实形成齐抓共\n管、协同联动的良好局面。"}, {"title": "会议指出，修订中国人民银行法是完善我国金融法律体系的基础工程。", "detail": "要加强\n金融法治建设，加快完善中央银行制度，依法全面履行好中央银行职责。"}, {"title": "5月22日，2026年APEC贸易部长会议在江苏苏州正式拉开惟幕。", "detail": "今年是中国第三次担任亚太经合组织（APEC）东道主。作为每个“APEC 年”中固\n定举行的重要机制性会议，本次APEC贸易部长会议将聚焦亚太自贸区建设、维护多边\n贸易体制、数字合作和绿色经济四个重点领域。\n作为亚太乃至全球经贸政策的“风向标”，今年APEC贸易部长会议将围绕APEC\n中国年合作主题“建设亚太共同体促进共同繁荣”，聚焦四个重点领域深化合作。"}, {"title": "国务院印发《关于推行常住地提供基本公共服务的实施意见》", "detail": ""}, {"title": "由常住地提供基本公共服务，促进未落户常住人口与户籍人口同等享有基本公", "detail": "共服务，有利于满足人民日益增长的美好生活需要，对提升城镇化质量、释放国内需求\n潜力、构建新发展格局具有重要意义。\n(2）重点任务\n①要加强随迁子女教育保障。巩固提升义务教育阶段随迁子女就读公办学位比例\n推动将随迁子女纳入常住地学前教育、高中阶段教育公共服务范围。\n②扩大公租房保障范围。推动更多城市将稳定就业居住的未落户常住人口家庭纳入\n公租房保障范围，稳步推进灵活就业人员参加住房公积金制度。\n③健全就业地参加职工社会保险制度。全面取消在就业地参加职工社会保险的户籍\n限制，引导支持各类劳动者在就业地参加职工社会保险，健全农民工、灵活就业人员、\n新就业形态人员参加社会保险制度。\n④加强常住地基本医疗保障。加力落实持居住证参加城乡居民基本医疗保险政策，\n加强异地就医直接结算管理服务。\n③强化就业基本公共服务。按规定落实就业援助政策，做好未落户自主创业人员创\n业扶持。\n③完善兜底性基本公共服务。逐步将未落户常住人口纳入常住地儿童关爱、养老助\n老、社会救助、扶残助残等基本公共服务范围。\n（3）支持保障\n①优化公共服务设施空间布局。要按常住人口和服务半径完善公共服务设施空间布\n局，加强人口流入城市和县城的公共服务能力。\n②规范基本公共服务梯度供给。促进基本公共服务资源公平有序分配，逐步减少梯\n度层次和差异、降低享有门槛\n加强财政转移支付保障，完善相关转移支付考虑常住人口因素进行分配的做法。\n④优化城镇建设用地配置。建立新增城镇建设用地指标配置同常住人口增加协调机\n制，优先保障学校、医疗卫生机构、保障性住房等建设需要。\n③促进公共服务共建共享。推广居住证互通互认、常住年限或常住积分转换等经验，\n保障流动人口连续享有基本公共服务，推动城市群、都市圈跨行政区合作办学办医。\n加强服务事项协同经办。推进基本公共服务事项省内通办、跨省通办\n①完善常住人口登记统计。推行电子居住证，加强与就业、社保、住房等信息共享,\n更好发挥居住证登记常住人口以及作为基本公共服务事项申请、核验、排序、享受等凭\n证的功能。"}, {"title": "第四届链博会将于6月22日至6月26日在北京中国国际展览中心顺义馆举办,", "detail": "由中国贸促会主办，中国国际展览中心集团有限公司承办，主题是“链接世界，共创未\n来”。本届链博会将“数字科技链”升级为“数智科技链”，首次设立人工智能专区。\n【来源：央视网】"}, {"title": "神舟二十三号", "detail": "①5月23日上午,神舟二十三号载人飞行任务新闻发布会在酒泉卫星发射中心召开。\n发言人介绍，经研究决定，瞄准北京时间5月24日23时08分发射神舟二十三号载人\n飞船，飞行乘组由朱杨柱、张志远、黎家盈组成，朱杨柱担任指令长。\n②3名航天员分别为飞行工程师、航天驾驶员和载荷专家，涵盖了我国现役3种航天\n员类型。航天员朱杨柱执行过神舟十六号载人飞行任务，张志远和黎家盈分别来自于我\n国第三批、第四批航天员，是首次执行飞行任务。其中，张志远入选前是空军飞行员，\n黎家盈入选前在香港特别行政区政府警务处工作。\n③紫荆花首次出现在神舟载人飞行任务标识中，对应这一元素的，就是神舟二十三\n号航天员乘组中首位来自香港的载荷专家\n黎家盈。【来源：央视网】"}, {"title": "人类首次！", "detail": "“微笑”卫星将为地球磁层拍下全景照。5月19日，中欧联合研制\n的“微笑”卫星成功发射升空，将实现人类首次对地球磁层的软×射线整体成像，为提\n升空间天气预报能力、保障航天和通信导航活动等提供核心科学支撑。"}, {"title": "神舟二十三号载人飞船发射取得圆满成功", "detail": "北京时间2026年5月24日23时08分，搭载神舟二十三号载人飞船的长征二号F\n遥二十三运载火箭在酒泉卫星发射中心点火发射，约10分钟后，飞船与火箭成功分离，\n进入预定轨道，航天员乘组状态良好，发射取得圆满成功。\n神舟二十三号载人飞船入轨后，于北京时间2026年5月25日2时45分，成功对\n接于空间站天和核心舱径向端口，整个对接过程历时约3.5小时\n北京时间2026年5月25日5时13分，在轨执行任务的神舟二十一号航天员乘组\n打开“家门”，欢迎远道而来的神舟二十三号航天员乘组入驻中国空间站，这是中国航\n天史上第8次“太空会师”，也是“天宫”首次有来自香港的航天员进驻"}, {"title": "全球首次我国万米深海试验再破世界纪录", "detail": "验，刷新全球同类型试验持续时长纪录，标志着我国深海原位试验技术实现从深度全覆\n盖到周期全掌握的关键跨越。"}, {"title": "5月23日，由我国自主研制的600公斤推力级F406涡扇发动机，双发配装先", "detail": "进气象无人机圆满完成首次飞行试验验证，这标志着我国通航动力领域，首次实现中小\n推力高端涡扇发动机的自主可控与国产化应用。"}, {"title": "5月25日晚，国家主席习近平在北京人民大会堂为塞尔维亚总统武契奇举行\"友", "detail": "谊勋章”颁授仪式。\n强调，“友谊勋章”是中华人民共和国对外最高荣誉勋章，这枚勋章不仅是对武契\n奇总统为中塞友好所作贡献的高度肯定，也寄托着两国人民对新时代中塞命运共同体建\n设的殷切期望。中塞友谊经历过血与火的淬炼，在当前国际风云激荡中更显弥足珍贵。\n中塞人民坚定追求独立自主，坚定捍卫民族尊严，坚定维护国际公平正义，必将在各自\n发展振兴征途上不断取得新的胜利。"}, {"title": "5月25日，2026 国际电路与系统研讨会在上海举行，华为公司董事、半导体", "detail": "业务部总裁何庭波在题为《半导体新路径探索与实践》的主旨演讲中，正式发表“韬()\n定律”。这是中国在全球半导体领域首次提出指导产业发展的新原则。基于该定律，华\n为过去六年已成功设计并量产了381款芯片。今年秋季，华为将发布新的麒麟手机芯片，\n完整采用逻辑折叠技术，大幅提升相关性能。\n“韬定律”提出以“时间缩微”替代“几何缩微”，以系统性降低时间常数（韬T)\n为目标，通过逻辑折叠等创新技术，持续压缩信号传播时延，不断提升晶体管密度，实\n现半导体与电子系统的持续演进。"}, {"title": "神舟二十三号飞船有多项创新", "detail": ""}, {"title": "神舟飞船大幅升级改造，舷窗拥有三重防烧蚀功能。", "detail": "专家介绍，此前的窗采\n用一层防烧蚀玻璃，团队将新舷窗的防烧蚀玻璃增加到两层，再增加一层舱内保护，使\n得神舟二十三号飞船舷窗总共拥有三重防烧蚀功能，提升了抵御空间碎片撞击的能力，\n为航天员在轨安全、安心工作生活新增一重“保险”。"}, {"title": "我国将首次挑战3.5小时径向快速交会对接。", "detail": "神舟二十三号载人飞行任务中,\n神舟飞船与中国空间站的径向交会对接，是我国载人飞船第一次挑战3.5小时快速交会\n对接模式下的径向交会对接。“径向交会对接”，是所有飞船和空间站交会对接模式中\n技术难度最高的，被誉为“太空穿针”。神舟十三号、神舟十四号任务虽然验证了径向\n交会对接技术，但均为6.5小时交会对接模式；神舟二十一号、神舟二十二号开启了3.5\n小时快速交会对接模式，但均采用前向对接。本次任务首次将3.5小时快速交会技术与径\n向对接模式深度结合，实现了两种模式首次“组合应用”。"}, {"title": "水稻将在太空“二次播种”，实现首次在轨连续两代水稻培养。", "detail": "这一次，随神\n舟二十三号上天的水稻，要先收获，然后用收获的种子再种一茬水稻，实现首次在轨连\n续两代水稻培养，解析长期空间微重力对水稻遗传稳定性作用。"}, {"title": "第七次中国一中东欧国家地方领导人会议5月26日在山东济南开幕。", "detail": "本次会\n议以\"携手同行共创未来”为主题，来自40多个国家的600多名中外嘉宾相聚齐鲁，\n围绕数字经济、绿色能源、现代农业等多个领域，共商合作新机遇。"}, {"title": "第21届联合国卫塞节5月26日在中国江苏无锡开幕。", "detail": "本次联合国卫塞节以\"佛\n教智慧在促进全球可持续发展和构建人类共同未来方面的作用”为主题，展现了佛教界\n关注人类前途命运的责任感。卫塞节是世界佛教徒纪念佛陀诞生、成道、涅的重要节\n日。"}, {"title": "近日，水利部发布2025年《中国河流泥沙公报》。", "detail": "公报显示，2025年主要河\n流代表水文站总径流量为11710亿立方米，较多年平均年径流量偏小18%；代表站年\n总输沙量为4.01亿吨，较多年平均年输沙量偏小71%"}, {"title": "2026媒体融合发展论坛5月26日在湖北省武汉市举行。", "detail": "本届论坛主题为“系\n统变革向新向优”"}, {"title": "5月27日，第二艘国产大型邮轮“爱达·花城号”完成为期12天的试航任务并", "detail": "靠港。试航结束后，第二艘国产大型邮轮将逐步推进区域完工和系统完工并向船东完成\n项目报验，计划于今年11月交付运营。交付后，将从广州南沙国际邮轮母港开启首航季。"}, {"title": "5月27日，世界规模最大的海上换流站", "detail": "—“海风之心”将从江苏南通正式发\n运。换流站长85.5米、宽82.5 米、高44 米，平面面积相当于一个标准足球场，高度约\n等于15层居民楼，重达25000吨，是世界首个±500干伏、2000兆瓦柔性直流海上换\n流站。"}, {"title": "5月27日，国务院新闻办公室举行新闻发布会，第七届跨国公司领导人青岛峰", "detail": "会将于6月15 日至 17 日在青岛举行。\n本届峰会将围绕“携手‘十五五”向新向未来”这一主题，设置开幕式、跨国公司\n高质量发展论坛及一系列平行论坛等活动，还将继续发布《跨国公司在中国》研究报告。"}, {"title": "5月23日，国家主席习近平复信参加“共航蔚蓝：中美青年友谊行”活动的两", "detail": "国学生。\n表示，中美友好的故事由人民书写，中美关系的未来由青年创造。2023年11月我\n提出“5年邀请5万名美国青少年来华交流学习”倡议以来，已有超过5万名美国青少\n年来华参访，提前两年半实现预期目标。\n指出，青少年最富有朝气，最富有梦想，是中美关系的未来和希望，也是世界的未\n来和希望。期待更多中美青少年接过两国友好事业的接力棒，相互学习、共同进步，成"}, {"title": "国务院关于印发《城市更新“十五五”规划》的通知", "detail": "城市是现代化建设的重要载体、人民幸福生活的重要空间\n总体要求：坚持以人民为中心，坚持系统观念，坚持规划引领，坚持统筹发展和安\n全，坚持保护第一、应保尽保、以用促保，因地制宜、分类指导，尽力而为、量力而行\n建立可持续的城市更新体制机制和政策法规，高质量推进城市更新，为建设现代化人民\n城市提供坚实基础。\n目标：到2030年，城市更新行动取得重要进展。到2035年，城市更新体制机制更\n加完善，城市结构优化、动能转换、品质提升、绿色转型、文脉赓续、治理增效取得显\n著成效，创新、宜居、美丽、韧性、文明、智慧的现代化人民城市基本建成。"}, {"title": "5月28日，为期四天的2026世界智能产业博览会在天津开幕。", "detail": "本届博览会以\n“智行天下能动未来”为主题，集中发布涵盖低空经济、具身智能、智能制造等领域的\n200余项新标准、新产品、新技术，全景展现智能产业领域的前沿科技应用。"}, {"title": "5月27日晚，第六届超越国际科技创新博览会在澳门开幕。", "detail": "本届博览会由澳门\n科技总会主办，以“AI：数实共生”为主题，聚焦人工智能从数字系统走向物理世界的\n产业进程，集中展示全球科技创新的最新成果与发展趋势。"}, {"title": "神二十一乘组凯旋", "detail": "北京时间2026年5月29日20时11分，神舟二十一号航天员乘组搭乘神舟二十二\n号载人飞船在东风着陆场成功着陆，现场医监医保人员确认航天员张陆、武飞、张洪章\n身体状态良好，任务取得圆满成功。\n在轨飞行期间，神舟二十一号航天员乘组亲身经历和见证了我国载人航天工程史上\n首次飞船受空间碎片撞击推迟返回、首次航天员乘组换船返回、首次飞船应急发射等历\n史时刻，经历和见证了载人航天工程全线天地同心、万众一心开展应急行动的难忘瞬间。\n神舟二十一号航天员乘组此次返回搭乘的神舟二十二号载人飞船于2025年11月25\n日从酒泉卫星发射中心升空，执行我国载人航天工程首次应急发射任务，随后成功对接\n于空间站天和核心舱前向端口；该乘组出征时搭乘的神舟二十一号载人飞船，已于2025\n年11月14日接替遭空间碎片撞击的神舟二十号飞船，护送神舟二十号航天员乘组安全\n回家。"}, {"title": "5月29日，从国务院国资委获悉，“十四五”期间，中央企业研发投入连续", "detail": "元，首次破干亿元"}, {"title": "当地时间5月29日，在南非开普敦举行的国际测量师联合会（FIG）2026年", "detail": "大会全体会议上，经会员代表投票，中国青岛以78票对28票战胜西班牙塞维利亚，获\n得2030年国际测量师联合会大会举办权。拥有148年历史的国际测量师联合会大会将\n首次在中国举办。"}, {"title": "太空算力，指的是将芯片、服务器等算力硬件直接部署到太空当中的卫星上", "detail": "让卫星在天上处理数据，优势主要体现在“实时性”和“覆盖性”。业内机构预测，到\n2030年，全球太空经济市场规模将超过万亿美元。其中，太空算力是重要的基础设施。"}, {"title": "5月30日，习近平同埃及总统塞西互致贺电，庆祝两国建交70周年", "detail": "指出，埃及是最早同新中国建交的阿拉伯和非洲国家。建交70年来，无论国际和地\n区形势如何变化，两国始终相互尊重、平等相待、彼此信任、守望相助，中埃关系已经\n成为发展中国家友好相处、团结协作的典范和中阿、中非集体合作的样板，正朝着构建\n面向新时代命运共同体的目标阔步前行。"}, {"title": "2026年5月30日是第十个全国科技工作者日。", "detail": "5月30日上午，2026年全\n国科技工作者日主场活动暨第四届全国创新争先奖表彰大会在京举行，291位科技工作\n者和9个团队获得奖项。今年全国科技工作者日系列活动由中国科协会同中央宣传部、\n科技部联合举办，主题为“奋进‘十五五科技谱新篇"}, {"title": "5月29日，国际山地旅游联盟授予湖北神农架“世界旅游名山”称号。", "detail": "“世\n界屋脊”喜马拉雅山脉的安纳普尔纳峰与“华中屋脊”神农架缔结为“姊妹”名山。两\n者在促进地质遗迹保护利用、推动可持续发展、信息共享、客源互送等方面将有多方面\n合作。\n神农架是中国首个获得联合国教科文组织人与生物圈自然保护区、世界地质公园、\n世界自然遗产三大保护制度共同录入名录的“三冠王”，拥有欧亚大陆最完好的森林生\n态系统、北半球同纬度最显著的生物多样性，全球最完整的垂直自然带谱。"}, {"title": "德国当地时间5月29日，射击世界杯慕尼黑站，在男子25米手枪速射比赛", "detail": "中，中国选手苏连博凡以35中夺冠，并创造新的世界纪录。\n刺猬\n云印\n五分打印首单免费\n超高质量满1.9包邮"}]}, {"month": "2026年6月", "year": 2026, "items": [{"title": "6月1日出版的第11期《求是》杂志发表习近平重要文章《前瞻布局和发展未来产业》", "detail": ""}, {"title": "背景：新一轮科技革命和产业变革加速演进，前沿技术不断涌现，引领和支撑未来产业快速", "detail": "崛起。"}, {"title": "战略高度：要站在推进强国建设、民族复兴伟业的战略高度，立足客观条件，发挥比较优势", "detail": "，\n坚持稳中求进、梯度培育，推动我国未来产业发展不断取得新突破。"}, {"title": "5条措施：", "detail": "第一，加强统筹谋划。未来产业具有前瞻性、战略性、颠覆性等特点，需要科学谋划、全局统筹。\n要把准发展方向。方向明，才能路子正、步履坚。要科学论证技术路线。重点是提升前沿技术战略预判\n能力。要把握发展节奏。做到先易后难、由近及远，积极稳步推进。要强化产业协同。要坚持联动发展,\n防止单兵突进，推动未来产业同新兴产业、传统产业相得益彰。\n第二，坚持以科技创新为引领。科技突破的程度，很大程度上决定未来产业发展的速度、广度、深\n度。要充分发挥新型举国体制优势，坚持“产业出题、科技答题”，加大重点领域关键核心技术攻关力\n度，加强基础研究战略性、前瞻性、体系化布局，加快科技成果转化应用。\n第三，发挥企业主体作用。企业是创新的主体，很多未来产业的兴起是靠企业一步步突破带动的。\n中央企业是科技创新的国家队，也应成为未来产业的主力军。\n第四，营造良好政策环境。未来产业培育周期长、市场风险大，政策上要支持，政府要做好服务。\n人才是未来产业发展最宝贵的资源。要全方位做好人才培养、引进、使用工作，在全社会营造鼓励创新、\n宽容失败的浓厚氛围，充分调动人才创新创业积极性。\n第五，健全治理体系。未来产业发展涉及面广，必须加强协同治理，防止出现政出多门、力量分散\n等情况。要统筹发展和安全，探索科学有效的监管方式。要深化国际合作，积极推动各方标准共建、规\n则共商、产业共促。"}, {"title": "习近平给中共一大纪念馆、南湖革命纪念馆少先队红领巾讲解员的回信，习近平强调，今年", "detail": "是中\n国共产党成立105周年，党的事业需要一代又一代人接续奋斗。希望你们高举队旗跟党走，传承红色基\n因，增长知识本领，磨练意志品质，做党和人民的红孩子，在新征程上跑好历史接力赛。"}, {"title": "5月31日，从中核集团获悉，近日，位于贵州六盘水的超临界二氧化碳余热发电项目一一", "detail": "“超\n碳一号”的第二台机组，成功实现并网发电，标志着全球首个超临界二氧化碳余热发电技术示范工程全\n面建成。两台机组全部投运后，“超碳一号”将形成30兆瓦稳定装机容量。"}, {"title": "5月27日发布，波士顿咨询公司《2026年全球财富报告》显示，截至2025年底，", "detail": "香港跨境财富\n管理规模达到2.95万亿美元，首次超越瑞士，成为全球最大的跨境财富管理中心。"}, {"title": "5月 29日，由中铁十一局和铁建重工联合打造的超大直径盾构机“焦平一号”在长沙下", "detail": "线，是\n目前世界最大直径土压平衡盾构高铁隧道盾构机。"}, {"title": "5月 28日，平陆运河航道主体工程开挖全部完成，平陆运河全长134.2公里，是新", "detail": "中国成立以\n来建设的首条通江达海的大运河，计划今年9月建成通航。通航后，平陆运河将直接开辟广西及我国西\n南地区通往东盟地区运距最短、最经济、最便捷的水运通道。"}, {"title": "国务院总理李强日前签署国务院令，公布《国务院关于对外投资的规定》，自2026年7", "detail": "月1日\n起施行。《规定》共34条，主要规定了以下内容：\n一是明确适用范围。对外投资即境外投资，中国境内投资者直接或者间接获得其他国家（地区）的\n企业、资产等相关权益的活动适用本规定。对投资者在港澳台投资的管理参照本规定执行。\n二是明确总体要求。对外投资工作贯彻总体国家安全观，健全对外投资管理服务体系，提升对外投\n资质量与水平。主动对接国际高标准经济贸易规则，推进高质量共建“一带一路”，推动产业链供应链\n国际合作。支持投资者按照市场化原则开展对外投资活动。\n三是健全综合服务。国家健全海外综合服务体系，省级以上人民政府及其有关部门提升公共服务能\n力和水平。支持专业服务机构提供高质量专业服务。行业协会商会、贸易投资促进组织按照章程提供有\n关的信息咨询、权益保护等方面的服务。\n第1页,共15页\n四是有效实施管理。完善调控措施，分类分级实施全过程监管，加强风险防控，提高对外投资科学\n性、安全性。国务院有关部门制定、调整和实施对外投资政策，指导、监督投资者规范投资经营行为。\n投资者应当依照国家有关规定办理核准备案、信息报告、跨境资金登记等手续。强化投资者主体责任，\n不得扰乱对外投资市场秩序。\n五是强化对外投资保护。国务院有关部门加强监测预警和风险评估，指导和帮助投资者做好安全风\n险防范。开展国际合作交流，积极商签国际经贸协定，提高保护水平。鼓励通过协商、调解、仲裁、诉\n讼等多种方式化解投资纠纷。建立投资壁垒调查制度等，切实维护投资者及其对外投资的安全和正当权\n益以及国家的海外利益。"}, {"title": "继2024年首届世界古典学大会在北京举行后，第二届世界古典学大会将于6月9日至1", "detail": "0日在希\n腊雅典召开。据介绍，本届大会主题为“古今对话：古典智慧的现代启示”，旨在引导与会专家思考古\n典学的当代角色和时代使命，特别是如何在机遇与挑战并存的百年变局中激发古典智慧之现代活力，为\n推动当今人类社会发展与文明进步提供启迪和指引。"}, {"title": "5月28日，国务院办公厅发布通知，国务院决定自2026年6月起开展第三次全国残疾", "detail": "人抽样调\n查。调查对象为我国境内抽取调查小区的全部常住人口，全国共抽取约280万人。"}, {"title": "国务院印发《加快农业农村现代化“十五五”规划》", "detail": "农业农村现代化关系中国式现代化全局和成色。“十五五”时期是基本实现农业农村现代化的关键\n时期。\n坚持农业农村优先发展，坚持城乡融合发展，锚定建设农业强国目标，以推进乡村全面振兴为总抓\n手，以学习运用“千万工程”经验为引领，以改革创新为根本动力，一体推进农业现代化和农村现代化，\n统筹发展科技农业、绿色农业、质量农业、品牌农业，统筹建立常态化防止返贫致贫机制。\n到2030年，粮食等重要农产品供给保障能力稳步提升，粮食安全根基持续夯实，农业质量效益和\n竞争力不断提高。农业科技自立自强水平大幅提高，农民收入持续较快增长。城乡融合发展实现新突破，\n基本公共服务均等化水平明显提升，农村改革扎实推进，农业农村高质量发展取得显著成效。\n到2035年，乡村全面振兴取得决定性进展，农业现代化基本实现，农村基本具备现代生活条件，\n农业强国建设取得显著成效。"}, {"title": "6月1日，第13届亚洲体操锦标赛和第19届亚洲青年体操锦标赛组委会在京举行新闻发", "detail": "布会，\n发布赛事口号、赛徽、吉祥物和奖牌。\n赛事口号为“韵动无界”。\n吉祥物“遵义三宝”以遵义辣椒、生态茶叶和酱香白酒为创意来源。\n奖牌的灵感源自明代玉石器\n“白玉透雕龙凤纹鸡心佩”，奖牌外圈采用“莫比乌斯环”拓扑结构，\n象征着“永无止境”。\n【拓展阅读】本次赛事由亚洲体操联合会主办，国家体育总局体操运动管理中心、中国体操协会、\n贵州省体育局、遵义市人民政府承办，将于2026年6月15日至29日在遵义市奥体中心体育馆举办。\n作为亚洲最高规格体操洲际专项赛事，本次赛事为世锦赛、亚运会资格选拔赛，系首次落户贵州遵义。"}, {"title": "我国自主研发工艺路线生产的T1000级高性能碳纤维，在上海实现批量化生产。", "detail": "产品可用于航\n空航天、具身智能、低空经济等高端领域和未来产业，将为我国关键领域发展提供核心战略材料支撑。"}, {"title": "日前，人社部会同国家卫生健康委、应急部、税务总局、国家医保局等5部门联合出台了《", "detail": "超\n龄劳动者基本权益保障暂行规定》。\n《暂行规定》自2026年7月1日起施行，这是我国首部明确超龄劳动者权益的专门规章，填补了\n我国现行劳动法律制度的短板，明确了用人单位与超龄劳动者的权利和义务，保障超龄劳动者的劳动报\n酬、休息休假、劳动安全卫生、工伤保障等合法权益。\n（1）适用范围\n中华人民共和国境内的用人单位招用超过法定退休年龄的劳动者，超龄劳动者受用人单位的劳动管\n理，从事用人单位安排的有报酬的劳动适用《暂行规定》\n符合规定已提前退休的劳动者，退休后被用人单位招用的也属于《暂行规定》的适用范围。\n第2页,共15页\n需要说明的是：按国家有关规定弹性延迟退休的劳动者，在弹性延迟退休期间，根据其所在单位性\n质，分别适用劳动合同法、《事业单位人事管理条例》等法律法规。\n（2）基本权益\n劳动报酬方面：明确要求及时足额支付劳动报酬，劳动报酬不低于最低工资标准\n休息休假方面：明确要求遵守法定工作时间规定和年节纪念日放假办法，二般不安排超龄劳动者加\n班，安排加班的应当遵守劳动法的有关规定。\n劳动安全卫生方面：明确用人单位应当安排合适的工作岗位和劳动强度，进行安全生产和职业卫生\n的教育和培训。\n工伤保障方面：明确用人单位应当按照国家规定为超龄劳动者参加工伤保险等。\n（3）养老保险\n按照现行政策规定，参加职工基本养老保险的个人，达到法定退休年龄时累计缴费不足最低缴费年\n限的，可以缴费至满最低缴费年限，按月领取基本养老金。\n为更好保障超龄劳动者权益，《暂行规定》明确规定，需延长费的超龄劳动者，可以个人身份继\n续缴纳养老保险费；经与用人单位协商一致，用人单位也可为其缴纳养老保险费，个人应当缴纳的养老\n保险费由用人单位代扣代缴。"}, {"title": "2026重庆国际动画电影周，将于6月9日至13日在重庆市永川区举办。", "detail": "本届动画电影周以“智\n绘无界·万象竞辉”为主题，旨在搭建国际动画交流平台，推动中国动画电影产业高质量发展。"}, {"title": "6月2日，国家统计局发布的《“十四五”经济社会发展成就系列报告》显示，我国坚持创", "detail": "新\n在现代化建设全局中的核心地位，深入实施创新驱动发展战略，推动科技实力从点的突破迈向系统能力\n提升、创新动能从规模积累迈向质效飞跃。五年来，我国成功身全球创新型国家前列，科技创新能力\n显著提升，关键核心技术攻关加快突破，科技创新与产业创新深度融合，新质生产力培育壮大，为高质\n量发展注入强劲动能，为推进中国式现代化提供有力支撑。"}, {"title": "多部门近日联合启动打击网络侵权盗版“剑网2026”专项行动，这是四部门第22次聚", "detail": "焦重点\n作品领域及重点网络平台开展专项治理工作。"}, {"title": "6月2日，由中国侨联、四川省人民政府、重庆市人民政府共同主办的2026“一带一路", "detail": "”华侨\n华人合作发展大会在成都开幕。大会以“汇聚侨界力量谱写丝路新篇”为主题，邀请来自全球120个\n国家和地区的近700位嘉宾参会。"}, {"title": "6月5日下午，习近平在人民大会堂同来华进行国事访问的老挝通伦举行会谈。", "detail": "习近平指出中方愿同老方弘扬传统友谊，深化互利合作，密切团结协作，推动中老关系实现新的跃\n升，携手打造新时代全天候中老命运共同体。\n习近平就推进中老关系和两国命运共同体建设不断向高标准、高质量、高水平迈进提出四点看法:\n第一，要坚持社会主义方向。双方要共同捍卫社会主义制度和共产党执政地位，保持密切战略沟通，\n执行好两党新的五年合作计划，深化治党治国经验交流。\n第二，要筑牢互利合作基石。中方愿同老方加强战略对接，拓展合作增长点。\n第三，要巩固人民传统友好。\n第四，要加强对外政策协调。"}, {"title": "6月5日，全国首张“无目的地海上游”出入境通行证在上海签发。", "detail": "该证件落地后，游客可依\n托相关政策实现免办签证、短途出海度假，进一步丰富国内邮轮出游选择。"}, {"title": "《国务院办公厅关于加强监管防范风险促进私募投资基金高质量发展的指导意见》", "detail": ""}, {"title": "坚持目标导向和间题导向，针对私募基金行业准入机制有待完善、监管不到位、制度不健全", "detail": "、\n部际央地协调配合不足、部分政府投资基金和国有企业投资基金出资人责任落实不到位以及部分私募基\n金成为违法犯罪、新型腐败和隐性腐败工具等问题，构建加强监管、防范风险的制度体系和长效机制，\n推动行业在规范中发展、在发展中提升。坚守功能定位，统筹总体布局，优化增量、盘活存量，扶优限\n劣、提质增效，严格禁止私募基金违规从事借贷、“名股实债”等行为。坚持分类监管，根据出资主体、\n产品类型等不同维度实施“一类一策”监管。坚持既管合法更管非法，对合法机构从严监管，对非法机\n构坚决取缔，对非法行为严厉打击。\n第3页,共15页"}, {"title": "优化私募基金登记备案规则，坚决防止不符合私募基金特征和运作规律的机构和产品作为私", "detail": "募基金登记备案。严控新设政府投资基金，县区原则上不得新设，确有必要新设的应当报上级人民政府\n批准。"}, {"title": "严格落实涉金融经营主体登记管理要求，未经国务院证券监督管理机构派出机构、省级和计", "detail": "划单列市人民政府金融管理部门同意，不得在经营主体名称、经营范围中使用“私募基金”、“创业投\n资基金”等涉及私募基金字样。\n“，“““（，（)\n护，发挥社会监督和预警作用。"}, {"title": "严厉打击违规募集、侵占挪用、自融自用、利益输送、资金违法跨境流动以及私募基金参与", "detail": "非法集资等行为，依法加大处理处罚力度。"}, {"title": "6月5日，国务院总理李强主持召开国务院常务会议，听取关于做好就业工作的汇报，审议", "detail": "通\n过《实施就业优先战略“十五五”规划》，研究推进新型工业化有关工作，研究未来产业发展有关工作，\n审议通过《退役军人就业创业促进条例（草案）》。\n①就业是民生之本，要以实施就业优先战略为引领，全面贯彻劳动者自主就业、市场调节就业、政\n府促进就业和鼓励创业的方针，加强产业和就业协同，持续用力推动就业扩容提质，努力实现高质量充\n分就业。要健全就业促进机制，完善就业创业服务体系，拓展高校毕业生等青年就业成才渠道，加大重\n点群体就业支持力度，推动灵活就业、新就业形态健康发展，加强劳动者就业权益保障。要加快培育壮\n大现代化人力资源，提高教育供给与人才需求匹配度，深入开展大规模职业技能培训，持续提升劳动者\n知识技能。\n②推进新型工业化是一项长期战略任务。要把握新一轮科技革命和产业变革趋势，坚持智能化、绿\n色化、融合化方向，统筹推进传统产业改造提升、新兴产业发展壮大、未来产业前瞻布局。要以发展新\n一代智能制造为主攻方向，加力实施产业基础再造工程、制造业重点产业链高质量发展行动，加快关键\n核心技术攻关，提升能源资源保障能力，增强产业链韧性和安全水平。要扩大高水平开放合作，实施好\n鼓励外商投资产业目录，引导外资更多投向先进制造业和生产性服务业。\n③要根据未来产业特点，进一步加强前瞻布局、加大推动力度，牢牢把握发展主动权。要筑牢技术\n根基，持续增加基础研究投入，系统布局原创性、颠覆性技术攻关。要注重生态建设，推动产学研用深\n度融合，鼓励产业链上下游密切合作，在重点赛道培育更多初创企业和独角兽企业。要完善支持政策,\n发挥好政府投资基金等引导作用，建立投入增长和风险分担机制。要引导科学合理布局，完善监管治理，\n防止一哄而上、盲目跟风。\n④要坚持普惠与优待叠加，采取政府推动、市场引导、社会支持相结合的方式，鼓励和扶持退役军\n人就业创业。要加强指导和服务，在教育资助、招录招聘、技能培训等方面予以支持，形成促进退役军\n人就业创业的合力。"}, {"title": "6月6日下午，中国首艘国产大型邮轮“爱达·魔都号”搭载4000多名旅客从上海吴淞", "detail": "口国际\n邮轮港启航，开启国内首次无目的地海上游。"}, {"title": "6月1日 16时 40 分，长征十二号乙遥一运载火箭在东风商业航天创新试验区发射", "detail": "升空，将搭\n载的千帆极轨08组卫星顺利送入预定轨道，飞行试验任务取得圆满成功。这次任务是长征十二号乙运\n载火箭的首次飞行。\n长征十二号乙运载火箭总高72米，直径4.37米，底部安装九台发动机，它是我国目前首飞成功的\n最高的火箭。"}, {"title": "6月10日，第五届全球媒体创新论坛将在重庆拉开惟幕。", "detail": "本届论坛以“恪守与重塑：智能时代\n的媒体使”为主题，汇聚来自全球多个国家和地区的约300位代表，共话智能浪潮下的媒体变革与责\n任。"}, {"title": "6月3日上午，西部陆海新通道骨干工程一一平陆运河实现全线通水，进入有水调试阶段。", "detail": "平\n陆运河位于广西，全长134.2公里，是新中国成立以来，我国第一条国家层面统筹的通江达海的运河工\n第4页,共15页\n程，计划今年9月建成通航。通航后，平陆运河将直接开辟我国广西及我国西南地区通往东盟地区运距\n最短、最经济、最便捷的水运通道。"}, {"title": "6月6日，全球首个预制算力中心底座在山东青岛正式启用。", "detail": "相较于传统算力中心节约施工周\n期近70%，为当前算力基础设施建设提供更高效、更低碳的新方案。"}, {"title": "6月4日，生态环境部在广东举办2026年中国生态文化论坛。", "detail": "论坛以“文润绿水青山共建美\n丽中国”为主题，围绕生态文化的理论、政策和实践进行研讨交流。"}, {"title": "当地时间6月8日下午，中共中央总书记、国家主席习近平在平壤锦绣山迎宾馆同朝鲜劳动", "detail": "党\n总书记、国务委员长金正恩举行会谈。\n强调，中朝两国同为共产党领导的社会主义国家。中朝传统友谊植根于双方共同的理想信念和奋斗\n目标，有深厚历史积淀、坚实政治基础、牢固情感纽带，世代友好、命运与共、守望相助始终是中朝关\n系的鲜明特征。无论国际形势如何变化，中国党和政府高度重视中朝传统友好的坚定立场不会改变，对\n决心不会改变。\n就发展中朝关系提出4点意见。\n第一，坚持以高层交往为引领，夯实政治互信根基。最高领导人战略引领是中朝关系的最大优势。\n今年是《中朝友好合作互助条约》签订65周年，双方要隆重举办纪念活动。\n第二，坚持以为民造福为目标，提升务实合作水平。\n第三，坚持以友谊传承为动力，拉紧民心相通纽带。中朝用鲜血凝成的传统友谊是两国人民共同的\n宝贵财富。\n第四，坚持以公平正义为理念，丰富战略协作内涵。"}, {"title": "6月8日，在赴平壤对朝鲜民主主义人民共和国进行国事访问之际，中共中央总书记、国家", "detail": "主\n席习近平在朝鲜《劳动新闻》发表题为《继往开来、砥砺同行续写中朝传统友谊崭新篇章》的署名文\n章。\n今年是《中朝友好合作互助条约》签订65周年\n中朝两国是守望相助、命运与共的社会主义友好邻邦。中朝传统友谊是两党两国和两国人民共同的\n宝贵财富。\n最高层战略引领是中朝关系的最大优势\n社会主义共同理想是中朝关系的鲜明底色\n命运与共的传统友谊是中朝关系的深厚根基。\n高水平战略协作是中朝关系的时代内涵。促进地区长治久安、世界和平稳定是两党两国和两国人民\n的共同追求。\n维护好、巩固好、发展好中朝关系始终是中国党和政府坚定不移的方针。当前，中朝关系站在新的\n历史起点，面临新的发展机遇，肩负新的时代使命。中方愿同朝方一道，从战略高度把握中朝关系，推\n动中朝关系与时俱进、得到更大发展。\n一一深化战略沟通，牢牢把握中朝关系发展正确方向。以《中朝友好合作互助条约》签订65周年\n为契机，加强党政军各部门各层级沟通交往，落实好双方重要共识，为中朝关系发展注入强劲动力。\n一加强交流互鉴，共同推动两国社会主义事业行稳致远。\n拓展务实合作，持续增进两国人民福祉和友谊。\n密切多边协作，坚定捍卫国际公平正义。"}, {"title": "6月8日，我国“十五五”时期开工建设的首个国家重大标志性工程三峡水运新通道正式开", "detail": "工。\n工程包含三峡枢纽新通道和葛洲坝航运扩能，设计通航船舶为10000吨级，三峡水运新通道工程规模巨\n大、难度空前，历经十余年论证设计、数十年技术储备，总投资约772.08亿元。"}, {"title": "国务院举行宪法宣誓仪式，宣誓后，国务院总理李强作了讲话。", "detail": "李强强调，当前全党正在深入\n开展树立和践行正确政绩观学习教育。我们要全面落实“立党为公、为民造福、科学决策、真抓实干”\n总要求，坚持说实话、办实事、求实效，当好贯彻党中央决策部署的执行者、行动派、实于家，以实干\n实绩践行对党的忠诚。要坚持实事求是，深入开展调查研究和分析研判，全面了解各方面实情，准确把\n第5页,共15页\n握发展大势，及时发现苗头性、倾向性问题。要坚持实干兴邦，始终以实干立身，以更大力度、更实举\n措解决发展中的卡点堵点，不断推动高质量发展取得新成效。要坚持以实绩说话，把各项工作抓实抓细，\n努力创造经得起实践、人民、历史检验的实绩。"}, {"title": "近日，国家网信办、市场监管总局联合印发《网络测评活动规范》。", "detail": "《规范》明确，从事网络测评活动，应当遵守法律、行政法规和国家有关规定，遵循商业道德、公\n序良俗，坚持客观、公正、全面、准确原则。\n《规范》要求，从事网络测评活动，涉及对产品功能、性能等项目测试，应当委托具有法定检验检\n测资质许可的检验检测机构按照相关标准以及技术规范开展测试。对食品开展检验检测的，测试方应当\n具备相应资质，不得使用非标方法，不得测评无国家标准检验方法的项目。不得采取不同标准、不同方\n法对同类产品进行横向、纵向比较。\n《规范》提出，未对产品开展测试，仅凭主观感受对产品进行评价，应当进行说明。网站平台要加\n强对网络测评信息内容管理，及时受理处置相关投诉举报。"}, {"title": "国务院关于印发《现代化应急体系建设“十五五”规划》的通知。", "detail": "坚持以习近平新时代中国特色社会主义思想为指导，全面贯彻党的二十大和二十届历次全会精神，\n认真落实四中全会部署，坚持人民至上、生命至上，坚持总体国家安全观，坚持统筹发展和安全，以高\n水平安全保障高质量发展为主题，以推动治理模式向事前预防转型为主线，以改革创新为根本动力，一\n体提升减灾预防、抗灾设防、救灾保障能力，“一件事”全链条推动重点行业领域安全整治，坚决遏制\n重特大事故，有效防范重大涉险和较大事故，最大限度降低自然灾害损失，坚决维护人民群众生命财产\n安全和社会大局稳定。\n到2030年，我国应急管理体系和能力现代化建设取得明显进展，以事前预防为主的治理模式有效\n建立，集中统二、高效权威的中国特色应急管理体制更加完善，大安全大应急框架下应急指挥机制更加\n健全，重特大突发事件处置保障能力和基层应急能力显著增强，应急管理法治化、科学化、智能化水平\n大幅提高，安全生产、防灾减灾救灾形势持续稳定。\n到2035年，建成与基本实现现代化相适应的中国特色大国应急体系，全面实现依法应急、科学应\n急、智慧应急，高质量发展和高水平安全实现良性互动。\n依法采取“一案双罚”（查处同一违法案件或生产安全事故时，既处罚违法生产经营单位，又处罚\n负有责任的个人）、联合惩戒、行刑衔接等措施，加大重点行业领域安全生产执法力度。\n加强高危行业领域生产经营单位主要负责人和从业人员安全生产培训，探索建立从业人员安全准入\n和退出机制，严格特种作业人员“考培分离”。\n综合考虑华北、东北、西北等不同区域洪水形成机制和灾害特点，有效开展工程治理，加紧补齐北\n方地区防洪排涝抗灾基础设施短板。依法开展森林草原火灾重大隐患动态清零和查处违规用火行为专项\n行动，系统推进大兴安岭、小兴安岭、长白山、横断山脉、武夷山等重点林区火险综合治理。以青藏高\n原及周边地区为重点，加强冰川冰湖科学考察、资源调查和灾害风险监测防治。\n健全中央和地方应急物资储备协同联动机制，完善实物储备、协议储备、产能储备模式，优化应急\n物资储备库布局，推动前置储备，提高配置效率，确保自然灾害发生8小时之内受灾人员基本生活得到\n有效救助。\n以“人人讲安全、个个会应急”为主题，办好全民安全公开课等特色活动和安全生产月、防灾减灾\n日、消防宣传月等主题活动。\n，9一国中\n欧新活力”。"}, {"title": "6月9日是第19个国际档案日，我国今年的主题为“档案与时代同行”。", "detail": "全国各级档案部门陆\n续启动档案开放、史料展览、便民查档系列活动，深挖红色档案资源，让档案走出库房、服务社会。"}, {"title": "2026年6月10日是第二个“文明对话国际日”，中国国际问题研究院发布《推动全球", "detail": "文明对\n话的中国行动》专题研究报告。\n【拓展阅读】2023年3月，习近平提出全球文明倡议，呼吁各方共同倡导尊重世界文明多样性、共\n同倡导弘扬全人类共同价值、共同倡导重视文明传承和创新、共同倡导加强国际人文交流合作，为促进\n第6页,共15页\n人类文明进步提供了中国方案。2024年6月，第78届联合国大会协商一致通过中国等83个国家提出的\n决议，将每年6月10日设立为“文明对话国际日”，得到国际社会热烈响应和广泛支持。"}, {"title": "2026 年6月10日，自然指数2026 科研领导者榜单发布，中国继续居于全球科", "detail": "研产出榜首。全\n球十强机构中有九家来自中国。\n数据显示，中国2024年至2025年科研产出增长了22.4%，是全球十强中唯一实现两位数增长的国\n家。其他十强国家依次为美国、德国、英国、日本、法国、韩国、印度、加拿大和意大利。\n在机构层面，中国科学院总体排名第二，且在除了健康科学和社会科学以外的所有学科领域均居榜\n首。全球十强机构中中方有九家，较去年再增一席。"}, {"title": "第10届中国一南亚博览会将于2026年6月11日至16日在云南昆明举办。", "detail": "截至目前，本届南\n博会已有超过66个国家和地区、国际组织报名参展参会，南亚、东南亚及《区域全面经济伙伴关系协\n定》（RCEP）成员国首次实现全覆盖。本届南博会首次设立服务贸易馆，目前各项工作已准备就绪。"}, {"title": "在6月11日举办的“2026·全球人权治理高端论坛”开幕式上，国家人权行动计划联", "detail": "席会议机\n制成员单位代表共同发布了《国家人权行动计划（2026一2030年）》。\n行动计划的基本原则是：呵护人的生命、价值、尊严，以系统性思维谋划人权建设，依法、平等、\n务实、协调、合力推进人权事业发展，在物质文明、政治文明、精神文明、社会文明、生态文明协调发\n展中全方位提升各项人权保障水平，促进人的全面发展、社会全面进步。\n行动计划的目标是：尊重人民主体地位，维护人民根本利益，促进社会公平正义，让现代化建设成\n果更多更公平惠及全体人民。"}, {"title": "2026年6月11日，“2026·全球人权治理高端论坛”在北京举办。", "detail": "本次论坛以“携手发展_共\n享人权：《发展权利宣言》通过40周年与全球人权治理新愿景”为主题。"}, {"title": "2026年6月11日，在江苏连云港港口，纯电拖轮“云港电拖九号”顺利实现向电网反", "detail": "向送电，\n这是我国首次实现新能源电动船舶与电网双向互动，标志着能源互联网从陆地“车网互动”向海洋应用\n场景迈出了关键一步。"}, {"title": "2026年6月11日，第十二届中国（上海）国际技术进出口交易会在上海世博展览馆开", "detail": "幕，本\n届展会于6月11日至13日举办，本届展会以“打造技术贸易新生态共绘全球合作新篇章”为主题。"}, {"title": "当地时间6月 11日，2026 年美加墨世界杯正式开幕。", "detail": "6月12日凌晨，美加墨世界杯拉开序幕，\n两只穿着世界杯主题球衣的拉布布作为特邀嘉宾惊喜亮相，成为世界杯历史上首个受邀的中国原创IP。"}, {"title": "6月12日，随着最后一片钢混组合梁在百米高空完成精准对位并吊装锁定，重庆武隆至两", "detail": "江新\n区高速公路控制性工程一一凤来大溪河特大桥钢混组合梁顺利合龙。至此，这座世界最大跨径钢拱桥主\n体钢结构施工圆满收官，工程正式转入桥面系及附属设施施工冲刺阶段。"}, {"title": "6月12日发布的《中国可再生能源发展报告》显示，2025年全国可再生能源新增发电", "detail": "量已完全\n覆盖全社会用电增量，经济增长的新增能耗首次全部由绿电支撑。"}, {"title": "6月13日是2026年文化和自然遗产日。", "detail": "从国务院确定2006年起每年6月的第二个星期六为“文\n化遗产日”，2017年起进一步调整设立为“文化和自然遗产日”，至今已走过20年。\n2026年6月13日，2026年文化和自然遗产日主场城市活动在湖北武汉举行，今年文化和自然遗产\n日的主题是“文物属于人民服务人民”。"}, {"title": "6月13日是2026年文化和自然遗产日。", "detail": "记者从国家林草局了解到，近年来我国不断强化世界\n自然遗产、自然与文化双遗产的科学性、系统性、整体性保护，保护状况持续提升。世界自然保护联盟\n评估显示，我国90%遗产地综合评估为优良，明显高于全球61%、亚洲68%的平均水平。\n目前，我国拥有世界自然遗产15项，世界自然与文化双遗产4项，总数居世界首位，总面积达8\n万多平方公里，遍布20个省份，囊括山岳、森林、湿地、荒漠、海岸等多元生态系统，填补了全球多\n项空白。"}, {"title": "《辽宁沿海船舶定线制》正式发布，2026年8月15日起实施，辽宁成为全国首个在沿", "detail": "海海域\n实现全域船舶定线制的省份。船舶定线制是国际通用的海上交通管理模式，通过划定分道通航制、警戒\n区等，规范船舶航行秩序，降低对遇与交叉会遇风险。通俗而言，它如同“车道线”，可实现船舶“各\n行其道”。\n第7页,共15页"}, {"title": "6月13日，第十八届海峡论坛大会在福建厦门举办。", "detail": "本届论坛延续“扩大民间交流、深化融合\n发展”的主题。海峡论坛是两岸规模最大、范围最广、影响最深远的民间交流活动，自 2009 年首次举\n办以来，共吸引超过10万人次的台胞参与。"}, {"title": "贵州遵义是革命老区，1935年1月召开的遵义会议，是中国共产党历史上生死攸关的伟", "detail": "大转折,\n在极端危急的历史关头，挽救了党、挽救了红军、挽救了中国革命。\n习近平总书记指出，要运用好遵义会议历史经验，让遵义会议精神永放光芒。今天，“坚定信念、\n坚持真理、独立自主、团结统一”的遵义会议精神跨越时空、历久弥新，激励老区人民传承红色基因，\n扎根红色沃土，绘出一幅壮阔的高质量发展长卷。"}, {"title": "2026年是联合国《发展权利宣言》通过40周年。", "detail": "《宣言》的达成，将发展权正式确立为一项\n人权。《宣言》亦强调，发展应当秉持“以人为本”的理念，要求全体人民和所有个人确保有意义地参\n与发展，公平分配发展成果，并为此采取持久的行动。在当前全球气候危机加剧的背景下，发展权所蕴\n含的以人为中心、公平发展、可持续性、自决原则和国际合作等内涵，为推动公平有序的全球气候治理\n行动提供重要依据。"}, {"title": "近日，国华投资江苏如东光氢储一体化项目全面建成，这是全国规模最大的光氢储一体化海", "detail": "上\n光伏示范项目。作为国内首个融合发电、制氢、储能，兼顾综合能源利用与滨海生态治理的项目，它实\n现了“电一储一氢”的复合高效利用。"}, {"title": "近日，中国科学院金属研究所科研团队联合多家单位，在高频晶体管领域取得重要突破，成", "detail": "功\n研制出一种新型高频晶体管一一“硅-石墨烯-锗”势垒晶体管。\n该器件创造了晶体管电流增益的世界最高值，为未来太赫兹通信、6G技术及超高速传感系统提供了\n全新器件方案。"}, {"title": "2026年6月16日出版的第12期《求是》杂志发表习近平重要文章《一体推进教育科", "detail": "技人才发\n展》"}, {"title": "综合国力竞争归根到底是人才竞争。", "detail": "哪个国家拥有人才上的优势，哪个国家最后就会拥有实\n力上的优势。"}, {"title": "人才资源是第一资源，也是创新活动中最为活跃、最为积极的因素。", "detail": "要把科技创新搞上去,\n就必须建设一支规模宏大、结构合理、素质优良的创新人才队伍。"}, {"title": "人是科技创新最关键的因素。", "detail": "我国要在科技创新方面走在世界前列，必须在创新实践中发现\n人才、在创新活动中培育人才、在创新事业中凝聚人才，必须大力培养造就规模宏大、结构合理、素质\n优良的创新型科技人才。"}, {"title": "把发展科技第一生产力、培养人才第一资源、增强创新第一动力更好结合起来，更好为改革", "detail": "开放和社会主义现代化建设服务。"}, {"title": "培养人才是国家和民族长远发展的大计，当今世界人才的竞争首先是人才培养的竞争。", "detail": "中国\n是一个大国，对人才数量、质量、结构的需求是全方位的，满足这样庞大的人才需求必须主要依靠自己\n培养，提高人才供给自主可控能力。"}, {"title": "人才培养首先要聚焦解决基础研究人才数量不足、质量不高问题。", "detail": ""}, {"title": "教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑。", "detail": "必须坚持科技是\n第一生产力、人才是第一资源、创新是第一动力，深入实施科教兴国战略、人才强国战略、创新驱动发\n展战略，开辟发展新领域新赛道，不断塑造发展新动能新优势。"}, {"title": "要按照发展新质生产力要求，畅通教育、科技、人才的良性循环，完善人才培养、引进、使", "detail": "用、合理流动的工作机制。"}, {"title": "一体推进教育科技人才事业发展，构筑人才竞争优势。", "detail": "科技创新靠人才，人才培养靠教育，\n教育、科技、人才内在一致、相互支撑。"}, {"title": "在教育体制改革方面，提出分类推进高校改革，建立科技发展、国家战略需求牵引引的学科", "detail": "设\n置调整机制和人才培养模式，超常布局急需学科专业；完善高校科技创新机制，提高成果转化效能。\n第8页,共15页"}, {"title": "在科技体制改革方面，提出加强国家战略科技力量建设；", "detail": "强化企业科技创新主体地位；允许\n科研类事业单位实行比一般事业单位更灵活的管理制度，探索实行企业化管理。"}, {"title": "强化教育对科技和人才的支撑作用。", "detail": "要坚持推动教育科技人才良性循环，统筹实施科教兴国\n战略、人才强国战略、创新驱动发展战略，一体推进教育发展、科技创新、人才培养。"}, {"title": "实现科技自主创新和人才自主培养良性互动，教育要进一步发挥先导性、基础性支撑作用。", "detail": ""}, {"title": "坚持任务牵引、以老带新，大力扶持青年人才。", "detail": ""}, {"title": "全国党建工作座谈会15日在京召开，会议认为，党的十八大以来，以习近平同志为核心的", "detail": "党\n中央围绕建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党的重大时代课\n题，提出一系列新理念新思想新战略，形成习近平党建思想。习近平党建思想是习近平新时代中国特色\n社会主义思想的重要组成部分，为发展马克思主义建党学说作出重大原创性贡献，对强党强国具有重大\n现实意义和长远指导意义。\n会议指出，习近平党建思想是加强新时代党的建设的根本遵循。这一思想鲜明提出（十四个坚持）：\n坚持党的领导是中国特色社会主义最本质的特征，\n坚持党中央集中统一领导，\n坚持全面从严治党，\n坚持不忘初心、牢记使命，\n坚持以党的政治建设为统领，\n坚持用党的创新理论凝心铸魂，\n坚持锤炼坚强党性，\n坚持健全上下贯通、执行有力的组织体系，\n坚持建设堪当民族复兴重任的高素质于部队伍，\n坚持推进作风建设常态化长效化，\n坚持用严明的纪律管全党治全党，\n坚持一体推进不敢腐不能腐不想腐，\n坚持制度治党、依规治党\n坚持落实管党治党政治责任，内涵丰富、体系严密。\n这一思想源自于马克思主义科学理论，植根于中华优秀传统文化，孕育于新时代全面从严治党的伟\n大实践，具有坚实的实践基础和深厚的理论渊源。这一思想彰显了坚定的理想信念、高度的历史主动、\n鲜明的问题导向、强烈的使命担当、深厚的为民情怀、科学的思想方法，明体达用、体用贯通，具有鲜\n明的理论品格。这一思想贯通历史、现实和未来，将随着新时代党的建设实践发展而不断丰富和发展。"}, {"title": "6月15日是上海合作组织成立 25周年。", "detail": "25 年来，上合组织秉持互信、互利、平等、协商、尊\n重多样文明、谋求共同发展的“上海精神”，已经成为当今世界人口最多、幅员最广、最具发展潜力的\n区域合作组织。"}, {"title": "6月15日，国务院以“强化主体功能区战略实施，促进区域协调发展”为主题，进行第二", "detail": "十次\n专题学习。国务院总理李强在主持学习时强调，立足各地资源禀赋和比较优势，统筹优化农业、生态、\n城镇等各类空间布局，进一步健全主体功能区制度，分区分类施策，促进形成主体功能明显、优势互补、\n高质量发展的国土空间开发保护新格局，为推动区域协调发展、优化重大生产力布局提供有力支撑。\n李强指出，这些年来，主体功能区战略从理念到实践取得重大进展，战略格局基本形成，“三区三\n线”全面划定。进入“十五五”时期，面对新的形势和任务，要深刻认识主体功能区战略的基础性作用、\n全局性影响，强化主体功能区战略实施，以钉钉子精神抓好推进落实。\n【拓展阅读】“三区三线”：“三区”包括城镇空间、农业空间和生态空间，分别承担经济发展、\n农业生产和生态保护功能；“三线”即永久基本农田、生态保护红线和城镇开发边界。\n李强指出，要优化主体功能区划，推动空间治理更加精准精细。充分考虑国家战略需求和地方发展\n条件的变化，在科学评估基础上对主体功能定位进行动态调整。根据地方独特区位和资源票赋，对特殊\n功能区实施差异化管理。拓展国土空间规划“一张图”信息集成功能，推动跨部门跨层级共享共用，构\n建国土空间治理基础平台。要完善与主体功能区相适应的政策制度体系，引导不同地区差异化协同化发\n第9页,共15页\n展。对城市化地区给予更多激励性政策，引导资源要素适当倾斜配置。对农产品主产区和重点生态功能\n区给予更多保障性政策，健全强化转移支付、保护补偿等机制。\n李强强调，区域协调发展战略、区域重大战略、新型城镇化战略等都是基于国土空间的重大战略，\n要系统梳理不同国家战略中明确的空间发展格局、区域功能和实施重点，统筹推动主体功能区战略与其\n他国家重大战略协同叠加。"}, {"title": "6月15日，第七届跨国公司领导人青岛峰会在青岛国际会议中心举行。", "detail": "本届峰会围绕“跨国公\n司与中国一一携手‘十五五’向新向未来”主题。"}, {"title": "6月15日，2026年世界青年发展论坛在湖北举行。", "detail": "本届论坛主题为“青年引领发展共创美好\n世界”"}, {"title": "习近平近日对常态化做好东西部协作工作作出重要指示指出，东西部协作开展30年来，在", "detail": "助力\n脱贫攻坚、促进区域协调发展等方面发挥了重要作用，彰显了我们党的政治优势和我国社会主义制度的\n优越性。\n强调，2026年是“十五五”开局之年，也是开展常态化帮扶第一年。要总结运用闽宁协作等有益经\n验，进一步完善协作机制，优化协作方式，拓展协作领域，推动东西部产业互补、人员互动、技术互学、\n观念互通、作风互鉴，实现互利共赢、共同发展。各级党委和政府要认真落实常态化帮扶责任，坚决守\n牢不发生规模性返贫致贫底线，扎实推进乡村全面振兴，不断增强区域发展协调性，推动全体人民共同\n富裕迈出坚实步伐。"}, {"title": "6月17日，国务院新闻办公室发布《构建更加公正合理的全球治理体系：中国的理念、倡", "detail": "议与\n行动》白皮书。\n中国提出全球治理倡议，旨在推动构建更加公正合理的全球治理体系。落实全球治理倡议，最根本\n的是坚定维护联合国的权威和地位，最关键的是大国展现责任担当，最需要的是各国团结合作，最紧迫\n的是弥补和平与发展赤字。\n全球治理倡议以维护联合国宪章宗旨和原则、践行共商共建共享的全球治理观为基本遵循，提出奉\n行主权平等、遵守国际法治、践行多边主义、倡导以人为本、注重行动导向五大核心理念。\n主权平等是联合国宪章开宗明义提出的基本原则，是规范国与国关系最重要的准则。主权平等是团\n结应对挑战的必然要求。\n讲平等讲包容是治理体系演进的历史大势。\n多元共生是人类社会本来的面貌，多极共存是国际格局发展的要求。\n国际法治是全球治理的根本保障。\n多边主义的要义是国际上的事由大家共同商量着办，世界命运由各国共同掌握。\n人类福祉是全球治理的核心关切，各国人民是全球治理的根本参与者和受益者。全球治理的活力源\n于实践，关键在于行动，根本要看成效。"}, {"title": "国务院印发《实施就业优先战略“十五五”规划》", "detail": ""}, {"title": "就业是最基本的民生，事关人民群众切身利益，事关经济社会健康发展，事关国家长治久安。", "detail": ""}, {"title": "全面贯彻劳动者自主就业、市场调节就业、政府促进就业和鼓励创业的方针，聚焦促进高质", "detail": "量充分就业目标，围绕就业领域人力资源供需不匹配的主要矛盾，坚持投资于物和投资于人紧密结合，\n以推动高质量发展为基础，以实施就业优先战略为引领，以强化就业优先政策为抓手，以破解结构性就\n业矛盾为着力点，以深化就业体制机制改革为动力，以不发生规模性失业风险为底线。"}, {"title": "“十五五”时期，就业保持总体稳定，高质量充分就业取得新进展。", "detail": "就业机会更加充分。就\n业环境更加公平。就业结构更加优化。人岗匹配更加高效。劳动关系更加和谐。"}, {"title": "把高质量充分就业作为经济社会发展的优先目标，使高质量发展的过程成为就业提质扩容的", "detail": "过程。"}, {"title": "稳定传统制造业就业基本盘，支持轻工、纺织等行业企业稳岗扩岗。", "detail": ""}, {"title": "以市场化培训为主导、行业企业自主培训为主体，以政府补贴性培训为有益补充，以就业技", "detail": "能培训、在岗转岗培训、创业能力培训为主要形式，健全贯穿劳动者学习和职业生涯全过程的终身职业\n技能培训制度。\n第10页,共15页："}, {"title": "打造覆盖全民、贯穿全程、辐射全域、便捷高效的全方位就业公共服务体系。", "detail": ""}, {"title": "加快发展多层次、多支柱养老保险体系，扩大企业年金覆盖范围，稳妥实施个人养老金制度。", "detail": ""}, {"title": "习近平给新华社老党员张连生回信，在回信中说，您当年作为中央纵队“四大队”报务员，", "detail": "在\n烽火硝烟中跟随党中央转战陕北，扎根通信技术岗位辛勤付出一辈子，期颐之年仍关心党和国家事业发\n展，向您表示敬意。新时代共产党人要传承红色基因，不忘初心、牢记使命，履职尽责、实于担当，在\n新征程上书写优异答卷。\n【拓展阅读】中央纵队“四大队”，是解放战争时期新华社跟随党中央和毛主席转战陕北的工作队,\n负责新闻通讯联络。"}, {"title": "2026年是闽宁协作30年，三十载山海同心，福建与宁夏携手创造了双向奔赴的发展奇", "detail": "迹，铸\n就东西部协作的时代样板。\n【拓展阅读】闽宁协作是习近平亲自开创、亲自部署、亲自推动的重要战略决策，贯穿脱贫攻坚与\n乡村振兴全过程，创造了东西部对口帮扶的“闽宁模式”，成为全国东西部协作的典范。"}, {"title": "6月17日晚，由中央广播电视总台主办的第二十二届中国国际动漫节“金猴奖”颁奖仪式", "detail": "在浙\n江杭州举行。作为中国动漫领域极具权威性的品牌赛事，“金猴奖”始终以挖掘原创精品、助力国漫扬\n帆出海为己任，长期引领中国动漫产业发展方向，被誉为“中国动漫至高荣誉”"}, {"title": "6月16日，福州召开的新闻发布会上披露，全国首部专门保护华侨历史文化遗存的省级地", "detail": "方性\n法规一一《福建省华侨历史文化遗存保护条例》将于2026年7月1日起施行。"}, {"title": "6月19日，2026 年世界斯诺克台球团体锦标赛在广东东莞落幕，决赛面对印度队，", "detail": "中国一队顶\n住压力，逆转战胜对手，首次夺得该赛事冠军。"}, {"title": "近日，中国科学院脑科学与智能技术卓越创新中心王凯研究团队和徐圣进研究团队联合攻克", "detail": "世\n界级难题，实现全球首次同一神经元三模态完整解析，相关成果于6月18日在国际学术期刊《细胞》\n发表。"}, {"title": "端午节历史悠久，意蕴丰富，是中国四大传统节日之一，亦是中国首个入选联合国教科文组", "detail": "织\n人类非物质文化遗产代表作名录的节日。\n赛龙舟、吃粽子、挂艾草、佩香囊，各类节俗传承千年，历久弥新，交织出独属于中国人的节日浪\n漫。"}, {"title": "坚持以党的政治建设为统领", "detail": "党的政治建设是党的根本性建设，决定党的建设方向和效果。\n讲政治，是马克思主义政党的突出特点和优势。对于一个马克思主义政党来说，如果政治上的先进\n性丧失了，党的先进性和纯洁性就无从谈起。\n党的十八届六中全会通过关于新形势下党内政治生活的若干准则，推动党员干部在党内政治生活中\n接受政治体检、打扫政治灰尘;\n党的十九大首次把党的政治建设纳入党的建设总体布局，强调把党的政治建设摆在首位；\n党的二十大进一步明确“以党的政治建设统领党的建设各项工作”，对严明政治纪律和政治规矩等\n提出明确要求。"}, {"title": "当地时间6月18日，2030年法国阿尔卑斯冬奥组委发布了两款会徽，它们以“光芒映", "detail": "照下显\n现的山峰”为共同意象，将分别作为2030年冬奥会和冬残奥会的标志性视觉符号。"}, {"title": "6月20日晚，第28届上海国际电影节金爵奖在上海揭晓，中国影片《大西洋》斩获金爵", "detail": "奖最\n佳影片、最佳摄影两项大奖。比利时影片《微光女孩》获得评委会大奖。"}, {"title": "夏至，是二十四节气的第10个节气。", "detail": "斗指午；太阳黄经90°；于公历6月20~22日交节。夏\n至这天，太阳直射地面的位置到达一年的最北端，几乎直射北回归线，此时，北半球各地的白昼时间达\n到全年最长。\n夏至分为三候:\n一候鹿角解，意思是鹿的角朝前生，所以属阳，并且认为夏至日阴气生而阳气始衰，所以阳性的鹿\n角便开始脱落。\n二候蝉始鸣，意思是雄性的知了在夏至后因感阴气之生便鼓翼而鸣。\n第11页,共15页\n三候半夏生，意思是半夏是一种喜阴的药草，因在仲夏的沼泽地或水田中出生所以得名，由此可见，\n在炎热的仲夏，一些喜阴的生物开始出现，而阳性的生物却开始衰退了。"}, {"title": "6月21日，以“续文脉凝聚力量，传承智慧永励后人”为主题的2026（丙午）年公祭", "detail": "中华人\n文始祖伏羲大典在天水举行。天水是伏羲文化的发祥地，有“羲皇故里”之称。每年夏至举行的公祭中\n华人文始祖伏羲大典，是中华民族的传统大典。"}, {"title": "作为硅的稳定同位素，硅-28被誉为“世界上最纯净的硅”，是比钻石还纯净的晶体，是", "detail": "研制\n硅基量子芯片不可或缺的核心材料。\n我国科学家在稳定同位素富集与高纯硅制备领域取得关键性突破，首次成功实现丰度超过99.99%\n的硅-28同位素自主量产，产品关键指标达到国际先进水平。"}, {"title": "6月16日，全球单机储热容量最大、镜场面积最大的光热电站一一中广核格尔木350兆", "detail": "瓦光热\n示范项目在青海省格尔木市乌图美仁光伏光热园区正式开工建设。"}, {"title": "6月22日至26日，第四届中国国际供应链促进博览会（以下简称“链博会”）在中国国", "detail": "际展\n览中心（顺义馆）举办，本届链博会以“链接世界，共创未来”为主题，是全球首个以供应链合作为主\n题的国家级展会，本届链博会首次设置人工智能专区。"}, {"title": "6月 23日，世界经济论坛第十七届新领军者年会（夏季达沃斯论坛）开始在辽宁大连举", "detail": "办，为\n期三天，本届年会的主题为“规模化创新”。"}, {"title": "6月23日，贵州贵阳、天津塘沽、云南腾冲和湖南岳阳4个气象站最新入选世界气象组织", "detail": "（WM0)\n百年气象站认可名单。至此，我国共有22个气象站获WMO百年气象站认证。"}, {"title": "6月22日，商务部、国家发展改革委、财政部联合印发《利用外资固稳促优行动方案》，", "detail": "围绕\n扩大市场准入、提升外商投资便利度、提高投资促进水平、健全外商投资服务保障体系、优化外资管理\n五方面提出举措。"}, {"title": "支持北京提升国家服务业扩大开放综合示范区建设水平，推动数字经济、医药健康等现代服", "detail": "务业重点领域开放举措先行先试。\n“，（)"}, {"title": "落实境外投资者以分配利润直接投资税收优惠政策，确保政策红利精准释放。", "detail": ""}, {"title": "建设融信息归集、办事咨询、专业支持、互动反馈等于一体的“投资中国”门户网站。", "detail": ""}, {"title": "开展“投资中国”境内外专项宣传，针对性加强涉企政策解读和宣介，强化“机遇中国”“", "detail": "世\n界相信中国”“全球合作共赢”叙事。"}, {"title": "6月21日，以“开放·互通·协同：链接亚太·共创未来”为主题的2026年亚太经合", "detail": "组织（APEC)\n工商领导人中国论坛在北京举行。"}, {"title": "6月22日，总理李强在辽宁省大连市调研。", "detail": "他强调，要深入贯彻落实关于新时代东北全面振兴\n和建设现代化产业体系的重要指示精神，坚持智能化、绿色化、融合化方向，加强原创性、引领性科技\n攻关，强化产业基础再造，大力发展高端装备制造业，加快建设现代化产业体系，为高质量发展不断注\n入新动能。\n他指出，高端船舶制造具有高技术、高难度、高附加值的特点，产业链条长、辐射带动效应大。要\n强化企业创新主体地位，支持整机和零部件企业、装备和用户企业开展协同攻关，加快关键技术研发突\n破，培养造就一批掌握精湛技艺、具有丰富经验的技术骨干和产业工人。"}, {"title": "6月23日，全球首艘10万吨级三文鱼养殖工船“苏海1号”在山东威海海域启动首批商", "detail": "品鱼\n起捕工作。“苏海1号”于2025年底正式投产运营，首批鱼苗经陆基培育后登船，在天然深远海冷水\n环境中舱养至今。"}, {"title": "6月23日，随着最后两钢箱梁同步提升到位，由中国铁建大桥局、中国铁建港航局联合承", "detail": "建\n的世界最大跨度三塔钢箱梁斜拉桥一一青龙门特大桥主桥顺利合龙，大桥主体结构施工圆满收官，为宁\n波舟山港六横公路大桥二期工程按期通车奠定了坚实基础。"}, {"title": "6月24日，习近平在山东省德州市考察时强调，农业农村现代化关系中国式现代化全局和", "detail": "成色，\n要以扎实举措做好各项工作，着力提升农业综合生产能力和质量效益，确保粮食等重要农产品稳定供给，\n因地制宜推进宜居宜业和美乡村建设，引导广大农民群众用勤劳和智慧创造更加美好生活。\n第12页,共15页"}, {"title": "6月 24日上午，国务院总理李强在大连出席 2026 年夏季达沃斯论坛开幕式并致", "detail": "辞。李强表示，\n正如主席指出，抓创新就是抓发展，谋创新就是谋未来。这次论坛以“规模化创新”为主题，点出了当\n今世界经济发展的一项重大命题。结合中国经济发展实践，我同大家分享中国创新的故事，以及对全球\n创新合作的一些思考。\n第一，“十五五”伊始，中国经济在应变局中开新局。在国际形势愈发动荡不安背景下，中国经济\n不惧风雨、奋破浪，呈现出“稳、新、活、融”的一幅多维图景，展现了坚韧向前、蓬勃向好的开局\n之势，为不确定性增多的世界注入了宝贵的确定性。\n第二，创新驱动是中国经济长期向好、行稳致远的关键密码。多年来，中国经济之所以能够始终平\n稳健康发展，有两大要诀：一个是稳定的环境，一个是创新的驱动。\n第三，创新合作是破解全球增长困境的必然选择"}, {"title": "6月 24日，世界气象组织在日内瓦为中国工程院院士、中国气象局卫星气象专家许健民", "detail": "颁发第\n70届国际气象组织奖，表彰他为天气预报、卫星气象事业以及气象业务服务作出的卓越贡献。据介绍，\n许健民全额捐赠奖金用于中国气象局设立“妈祖”奖。"}, {"title": "2026年6月23日，德国汉堡ISC2026大会（国际超算大会）发布全球超算To", "detail": "p500榜单：全国\n产自主研制的“灵晟”超级计算机以2.19EFlops（每秒1018次浮点运算）持续双精度浮点性能登顶全\n球超算TOP500，时隔九年，我国超算再次排名全球第二。"}, {"title": "6月25日是全国土地日，主题为“珍惜每一寸土地促进高质量发展”。", "detail": "记者从自然资源部了\n解到，今年以来，我国节约集约用地取得积极成效，土地资源利用效率全面提升。"}, {"title": "6月25日，国家能源局公布的数据显示，截至5月底，全国累计发电装机容量突破40亿", "detail": "千瓦\n大关，居世界首位，我国电力供给能力迈上新台阶。"}, {"title": "6月23日，金砖国家女性工商联盟是金砖合作机制的重要内容，主题为“凝力成金，共绘", "detail": "华章汇\n聚、绽放、共荣”的2026金砖国家女性领导力论坛在北京举办。"}, {"title": "记者从三峡集团获悉，为全力保障长江流域汛期安全，由乌东德、白鹤滩、溪洛渡、向家坝", "detail": "、\n三峡和葛洲坝六座梯级水电站构成的世界最大清洁能源走廊，日前全面完成年度消落工作，累计腾空防\n洪库容358亿立方米。\n临前有序将库水位，从正常蓄水位附近逐步降低至防洪限制水位、腾空防洪库容的过程，是水库水量调\n度的核心常规环节。"}, {"title": "6月24日起到28日，第十三届APEC 旅游部长会议在澳门举行。", "detail": "今年是APEC“中国年”，这次\n会议活动也是今年中国担任APEC东道主期间约300场会议活动的重要组成部分。"}, {"title": "《永乐大典》是明成祖永乐年间编纂的一部大型类书，全书22877卷、11095册，", "detail": "约4.5亿字。\n它采先秦至明初典籍七八千种，内容包罗万象，且对引文一字不改、原文存录，不仅被誉为“有史以\n来最大的百科全书”，而且成为保存中国古典文献的渊。历经百年流散，今所存者，每一册皆为不可\n再生的文明孤本。\n6月24日下午，浙江杭州国家版本馆举行国宝《永乐大典》捐赠入藏仪式，两册流失海外多年的明\n写本《永乐大典》正式入藏该馆。"}, {"title": "6月26日，十四届全国人大常委会第二十三次会议表决通过新修订的商标法，2027年", "detail": "1月1日\n起施行。\n商标作为知识产权的重要组成部分，不仅是商誉的载体和诚信的象征，更是企业参与市场竞争的核\n心工具。新修订的商标法共9章87条，聚焦商标领域突出问题，明确商标工作的总体要求，规范商标\n注册，优化商标授权确权程序，强化商标管理，加强商标专用权保护。"}, {"title": "日前，新疆吉木萨尔全钒液流电池储能电站全面转入商业运行。", "detail": "该电站是我国目前规模最大的\n全钒液流电池储能电站，标志着我国在大容量、长时储能技术规模化应用方面取得新进展。\n全钒液流电池是一种长时储能技术，主要通过电解液中钒离子价态变化，实现电能储存和释放，具\n有安全性高、循环寿命长、扩容能力强等特点。新疆吉木萨尔全钒液流电池储能电站由储能单元、能量\n转换单元和动力系统等组成，相当于为光伏发电配套建设了一座“巨型充电宝”。\n第13页,共15页"}, {"title": "6月 26日，拥有世界第一高坝的大渡河双江口水电站，迎来首台机组并网发电，为西南", "detail": "地区清\n洁能源供应体系建设和我国“双碳”目标落地再添新的支撑。大渡河流域是我国第五大水电基地，水能\n资源富集、开发潜力巨大。"}, {"title": "6月26日，全球首制2.4万箱甲醇双燃料集装箱船“东方智慧”轮从江苏南通长江段码", "detail": "头交付\n启航。作为目前全球最大级别的甲醇双燃料集装箱船，该船舶搭载先进甲醇双燃料动力系统，使用绿色\n甲醇时碳排放显著降低，兼具大型化、低碳化、智能化技术优势，是我国清洁能源船舶制造领域的突破\n性产品。"}, {"title": "关于印发《美丽中国建设全民行动促进计划（2026-2030年）》的通知", "detail": "到2030年，生态文明思想更加深入人心，全社会生态文明主流价值观牢固树立，美丽中国建设文\n化支撑更加坚实，公众生态文明素养显著提升，建设美丽中国成为全体人民自觉行动，绿色低碳生活方\n式蔚然成风，美丽中国建设全民行动体系基本形成。"}, {"title": "国际奥委会第146次全会25日在洛桑审议通过，滑雪登山成为2030 年法国阿尔卑", "detail": "斯冬奥会正\n式竞赛项目。"}, {"title": "国家发展改革委、国家能源局日前印发《新型能源体系建设“十五五”规划》，提出六方面", "detail": "共\n14条举措，明确到2030年初步建成清洁低碳安全高效的新型能源体系。"}, {"title": "6月28日，全球首座单机容量最大的张力腿浮式风电平台一一“海油安澜号”，在珠海高", "detail": "栏\n港完成一体化集成后，由珠海海事部门护送，顺利出港，正式向粤东陆丰油田群海域进发。这座总高逾\n307米、总重近8000吨的“海上大风车”从珠海高栏港启程出海，标志着我国深远海浮式风电技术正从\n示范应用加速向规模化、商业化迈进。"}, {"title": "党的十八大以来，以习近平为核心的党中央围绕建设什么样的长期执政的马克思主义政党、", "detail": "怎\n样建设长期执政的马克思主义政党的重大时代课题，提出一系列新理念新思想新战略，形成主席党建思\n想。\n习近平党建思想是加强新时代党的建设的根本遵循。这一思想以“十四个坚持”，深刻把握管党治\n党、兴党强党和强国复兴的内在联系，全面深刻阐明新时代党的建设的最高原则、战略方针、价值追求、\n工作布局、方法路径。\n围绕关系党千秋伟业的重大问题，指出，中国特色社会主义最本质的特征是中国共产党领导，中国\n特色社会主义制度的最大优势是中国共产党领导。坚持党中央集中统一领导是最高政治原则。\n提出新时代党的建设总要求，以党的政治建设为统领，以坚定理想信念宗旨为根基，全面推进党的\n政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争，\n确保党始终成为中国特色社会主义事业的坚强领导核心。\n以政治建设为统领，把思想建设作为党的基础性建设，加强组织建设，健全上下贯通、执行有力的\n组织体系。"}, {"title": "6月25日至29日，主题为“丝路新机遇亚欧新活力”的第九届中国一亚欧博览会在鸟鲁", "detail": "木\n齐举办，新产品、新技术集中亮相，彰显亚欧经贸合作新活力。"}, {"title": "2026全球数字经济大会将于7月2日至5日在国家会议中心举行，以“建设数字友好城", "detail": "市一\n一智惠无界，数联全球”为主题带来一场数字盛宴。"}, {"title": "《中华人民共和国民族团结进步促进法》", "detail": "民族团结是我国各族人民的生命线。作为新时代实施宪法有关规定、处理民族事务和开展民族工作的基\n本法律，民族团结进步促进法将于2026年7月1日起施行。党的十八大以来，以习近平为核心的党中\n央高度重视民族工作，鲜明提出把铸牢中华民族共同体意识作为新时代党的民族工作主线、民族地区各\n项工作的主线，形成了习近平关于加强和改进民族工作的重要思想。民族团结进步促进法在体例上专门\n设置序言，这是30多年来第一部设置序言的法律。"}, {"title": "6月29日上午，习近平在北京钓鱼台国宾馆会见白俄罗斯总统卢卡申科。", "detail": "指出，中国和白俄罗斯是相互信任支持的真朋友，是共同发展繁荣的好伙伴，是全天候全面战略伙\n伴。事实证明，深化中白全天候、全方位合作顺应历史发展潮流，符合两国人民根本利益。\n第14页,共15页"}, {"title": "6月 29曰，从中国石油了解到，位于新疆吐鲁番火焰山下，世界海拔最低超深特稠油油", "detail": "田\n一鲁克沁油田累计产油量突破1000万吨。"}, {"title": "6月27日，中国科学院合肥物质科学研究院等离子体物理研究所“人造太阳”项目取得最", "detail": "新\n进展，我国两款自主研制的核聚变堆使用的超导磁体分别完成技术验收和满工况参数测试。其中，国家\n重大科技基础设施“聚变堆主机关键系统综合研究设施”最大的超导部件一一\n环向场磁体完成最后制备\n工艺，并通过专家技术验收。"}, {"title": "6月29日，首届中国一上海合作组织科技创新合作大会在山东青岛举行。", "detail": "本次大会以“智汇\n上合，创享未来一一共筑开放普惠的国际科技合作新生态”为主题。\n刺猬\n云印\n五分打印首单免费\n超高质量满1.9包邮\n第15页,共15页"}]}, {"month": "2026年7月", "year": 2026, "items": [{"title": "习近平总书记系列重要讲话", "detail": ""}, {"title": "庆祝中国共产党成立105周年大会在京隆重举行", "detail": "庆祝中国共产党成立105周年大会7月1日上午在北京人民大会堂隆重举行。中共中央总书记、国家主席、中央军委主席习近平向“七一勋章”获得者颁授勋章并发表重要讲话。他强调，105年来，我们党始终坚守为中国人民谋幸福、为中华民族谋复兴的初心使命，在不懈奋斗中创造了彪炳史册的伟大成就。新征程上，全党同志要坚定信心、接续奋斗，不断创造无愧于时代和人民的新业绩。\n中共中央政治局常委李强、赵乐际、王沪宁、蔡奇、丁薛祥、李希，国家副主席韩正出席大会。\n上午9时许，“七一勋章”获得者集体乘坐礼宾车从住地出发，由礼宾摩托车队护卫前往人民大会堂。人民大会堂北门外，礼兵分列道路两侧，青少年热情欢呼致意。“七一勋章”获得者沿着红毯拾级而上，进入人民大会堂。党和国家功勋荣誉表彰工作委员会有关领导同志等，在这里集体迎接他们到来。\n人民大会堂大礼堂气氛隆重热烈。主席台上方悬挂着“庆祝中国共产党成立105周年大会”会标，后幕正中是熠熠生辉的中国共产党党徽，党徽下方是“1921－2026”字标，10面红旗分列两侧。二楼眺台悬挂着标语：“紧密团结在以习近平同志为核心的党中央周围，全面贯彻习近平新时代中国特色社会主义思想，弘扬伟大建党精神，践行初心使命，为以中国式现代化全面推进强国建设、民族复兴伟业而不懈奋斗！”\n10时整，李强宣布庆祝大会开始，全场起立，高唱国歌。\n蔡奇宣读《中共中央关于授予“七一勋章”的决定》。《决定》指出，为隆重表彰长期扎根基层、为党工作、为民服务、作出突出贡献的功勋模范党员，激励全党不忘初心、牢记使命，踔厉奋发、勇毅前行，党中央决定，授予马善祥、王於昌、李连成、吾哈斯·苏来曼、吴亚琴、陈俊武、赵亚夫、钟掘同志“七一勋章”。\n2名旗手高擎党旗，1名礼兵手捧“七一勋章”，迈着雄健的步伐，行进到仪式现场。\n在雄壮的《向祖国英雄致敬》乐曲声中，习近平为“七一勋章”获得者一一颁授勋章，并同他们亲切握手、表示祝贺。随后，“七一勋章”获得者受邀到主席台就座。全场响起一阵阵热烈的掌声。\n蔡奇宣读《中共中央关于表彰全国优秀共产党员、全国优秀党务工作者和全国先进基层党组织的决定》。\n习近平等为受表彰的全国“两优一先”代表颁奖。\n在全场热烈的掌声中，习近平发表重要讲话。他表示，今天，我们隆重集会，庆祝中国共产党成立105周年，回顾我们党走过的光辉历程，展望党和人民事业发展的光明前景，动员全党全国各族人民满怀信心朝着全面建成社会主义现代化强国、实现中华民族伟大复兴的宏伟目标奋勇前进。习近平代表党中央，向全体中国共产党员致以节日问候！向“七一勋章”获得者，向受表彰的全国优秀共产党员、优秀党务工作者、先进基层党组织表示热烈祝贺！\n习近平指出，105年前，在中国人民和中华民族的伟大觉醒中，在马克思列宁主义同中国工人运动的紧密结合中，中国共产党应运而生。从此，中国人民和中华民族有了最可靠的主心骨，内忧外患、积贫积弱的中国开启了翻天覆地的历史巨变。\n习近平强调，105年来，我们党团结带领全国各族人民不懈奋斗，创造了新民主主义革命、社会主义革命和建设、改革开放和社会主义现代化建设、新时代中国特色社会主义的伟大成就，书写了中华民族几千年历史上最恢宏的史诗。105年不懈奋斗，从根本上改变了中国人民的前途命运，开辟了实现中华民族伟大复兴的正确道路，展示了马克思主义的强大生命力，深刻影响了世界历史进程，锻造了强大的中国共产党。我们党完全无愧为伟大光荣正确的党。\n习近平指出，中国共产党之所以能够在105年奋斗中不断铸就辉煌，历史和人民之所以选择中国共产党，根本在于我们党具有其他政党和政治力量无可比拟的优秀特质。我们党矢志追求真理、始终把准前进方向，深深植根人民、始终拥有坚实根基，勇担历史使命、始终掌握战略主动，顺应发展潮流、始终走在时代前列，敢于善于斗争、始终保持必胜信心，注重强健自身、始终充满生机活力。我们要结合新的实际，把党的优秀特质不断发扬光大，确保党永远不变质不变色不变味，始终具有强大创造力凝聚力战斗力。\n习近平强调，实现新时代新征程党的使命任务，要求全体中国共产党人坚定信心、接续奋斗，不断创造无愧于时代和人民的新业绩。坚定信心、接续奋斗，必须坚持党的基本理论、基本路线、基本方略，坚持党的全面领导和党中央集中统一领导，深入贯彻新时代中国特色社会主义思想，坚定道路自信、理论自信、制度自信、文化自信，继往开来、守正创新，做到不畏浮云遮望眼、乘风破浪不迷航。必须紧紧依靠人民创造历史伟业，践行以人民为中心的发展思想，充分激发亿万人民的积极性主动性创造性，统筹推进“五位一体”总体布局、协调推进“四个全面”战略布局，完整准确全面贯彻新发展理念，加快构建新发展格局，扎实推动高质量发展。必须积极应对前进道路上的风险挑战，强化忧患意识、坚持底线思维，发扬斗争精神、增强斗争本领，更好统筹国内国际两个大局，统筹发展和安全。必须持续推动构建人类命运共同体，高举和平、发展、合作、共赢旗帜，弘扬全人类共同价值，推动落实全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议，为世界和平与发展注入更多正能量。必须持之以恒推进全面从严治党，全面贯彻新时代党建思想，健全全面从严治党体系，以党的政治建设为统领加强党的各方面建设，坚决打好反腐败斗争攻坚战持久战总体战，不断增强党的政治领导力、思想引领力、群众组织力、社会号召力。\n习近平指出，强国必须强军，军强才能国安。必须全面贯彻新时代党的强军思想，坚持党对人民军队的绝对领导，全面推进政治建军、改革强军、科技强军、人才强军、依法治军，高质量推进国防和军队现代化，如期实现建军一百年奋斗目标，加快把人民军队建成世界一流军队。\n习近平强调，促进香港、澳门长期繁荣稳定，是中华民族伟大复兴的内在要求。要全面准确、坚定不移贯彻“一国两制”、“港人治港”、“澳人治澳”、高度自治的方针，促进港澳经济社会发展，支持港澳更好融入和服务国家发展大局。\n习近平指出，解决台湾问题、实现祖国完全统一，是我们党矢志不渝的历史任务，是全体中华儿女的共同愿望。要深入贯彻新时代党解决台湾问题的总体方略，坚持一个中国原则和“九二共识”，团结广大台湾同胞，深化两岸交流合作和融合发展，坚决打击“台独”分裂势力，反对外部势力干涉，坚定推进祖国统一大业。\n习近平强调，青年是实现中华民族伟大复兴的生力军。全党要重视青年、关心青年、支持青年，为青年成长成才创造条件。新时代中国青年要坚定不移听党话、跟党走，树立远大志向，勇担时代重任，在新征程上跑好历史接力赛，用青春铺路、让理想闪光。\n习近平强调，中国共产党105年的辉煌历史令人自豪，但我们决不能骄傲自满、止步不前。到本世纪中叶，我们要全面建成社会主义现代化强国、实现第二个百年奋斗目标。全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争，紧紧依靠和团结带领全国各族人民奋进新征程、建功新时代，奋力创造新的历史辉煌。\n李强在主持大会时指出，习近平总书记的重要讲话，全面回顾总结了105年来中国共产党团结带领全国各族人民走过的光辉历程、创造的伟大成就，深刻揭示了中国共产党之所以能够不断铸就辉煌的优秀特质，对新征程上全体中国共产党人坚定信心、接续奋斗提出了明确要求，向全党发出了奋力创造新的历史辉煌的伟大号召。习近平总书记的重要讲话高屋建瓴、思想深邃、内涵丰富，为新时代新征程实现党的中心任务进一步指明了方向、提供了遵循。全党同志要认真学习领会，切实把讲话精神贯彻落实到各项工作中去，弘扬伟大建党精神，践行初心使命，为以中国式现代化全面推进强国建设、民族复兴伟业而不懈奋斗。\n会上，“七一勋章”获得者代表、吉林省长春市宽城区长山花园社区党委第一书记吴亚琴发言。\n大会在雄壮的《国际歌》声中结束。"}, {"title": "《求是》杂志发表习近平总书记重要文章《做焦裕禄式的县委书记》", "detail": "7月1日出版的第13期《求是》杂志重新发表中共中央总书记、国家主席、中央军委主席习近平的重要文章《做焦裕禄式的县委书记》。这是习近平总书记2015年1月12日在中央党校县委书记研修班学员座谈会上的讲话。\n文章强调，在我们党的组织结构和国家政权结构中，县一级处在承上启下的关键环节，是发展经济、保障民生、维护稳定、促进国家长治久安的重要基础。县委是我们党执政兴国的“一线指挥部”，县委书记就是“一线总指挥”。怎样才能当好县委书记？焦裕禄同志为县委书记树立了榜样。做县委书记，就要做焦裕禄式的县委书记。\n文章指出，当好县委书记，必须始终做到心中有党。对党忠诚，是县委书记的重要标准。衡量一个县委书记当得怎么样，可以讲很多条，但主要看这一条。县一级阵地，必须由心中有党、对党忠诚的人坚守。要把牢政治方向，强化组织意识，相信组织、依靠组织、服从组织，自觉维护党的团结统一。把学习掌握马克思主义理论作为看家本领，注重解决好世界观、人生观、价值观这个“总开关”问题。严守政治纪律，在政治方向、政治立场、政治言论、政治行为方面守好规矩，自觉坚持党的领导，自觉同党中央保持高度一致，自觉维护党中央权威。\n文章指出，当好县委书记，必须始终做到心中有民。全心全意为人民服务是我们党的根本宗旨。县委书记是直接面对基层群众的领导干部，必须心系群众、为民造福。要着力解决好人民最关心最直接最现实的利益问题，特别是要下大气力解决好人民不满意的问题，多做雪中送炭的事情。干事创业一定要树立正确政绩观，决不能为了树立个人形象，搞华而不实、劳民伤财的“形象工程”、“政绩工程”。要把调查研究作为基本功，深入基层、深入群众、深入实际，了解情况、问计于民。树立良好作风，做到勤政、务实、为民，自觉抵制和纠正“四风”问题。\n文章指出，当好县委书记，必须始终做到心中有责。县一级领导要谋几十万、上百万人的改革发展稳定大计，管千头万绪的事务。要意气风发、满腔热情干好，为官一任、造福一方。对定下来的工作部署，要一抓到底、善始善终。一张好的蓝图，只要是科学的、切合实际的、符合人民愿望的，就要像接力赛一样，一棒一棒接着干下去。面对工作难题，要有明知山有虎、偏向虎山行的劲头，积极寻找克服困难的具体对策，豁得出来、顶得上去。对突出矛盾要有责任意识，主动去解决而不是回避推卸。对突发事件要临危不惧、沉着冷静、敢于负责。\n文章指出，当好县委书记，必须始终做到心中有戒。我们的权力是党和人民赋予的，是为党和人民做事用的，姓公不姓私，只能用来为党分忧、为国干事、为民谋利。要正确行使权力，依法用权、秉公用权、廉洁用权，做到心有所畏、言有所戒、行有所止，处理好公和私、情和法、利和法的关系。带头执行民主集中制，按照程序进行决策。善于把党委一班人、几大家班子和各级干部智慧集中起来，做到总揽不包揽、分工不分家、放手不撒手。做学法尊法守法用法的模范，善于运用法治思维谋划县域治理。始终严格要求自己，做到清清白白做人、干干净净做事、坦坦荡荡为官。自觉弘扬和践行社会主义核心价值观，加强道德修养，追求健康情趣，引导全县形成健康向上的社会风尚。"}, {"title": "中央军委举行晋升上将军衔仪式 习近平颁发命令状并向晋衔的军官表示祝贺", "detail": "中央军委晋升上将军衔仪式7月3日在北京八一大楼举行。中央军委主席习近平出席晋衔仪式。\n上午10时30分许，晋衔仪式在庄严的中华人民共和国国歌声中开始。中央军委副主席张升民主持晋衔仪式，宣读中央军委主席习近平签署的晋升上将军衔命令。\n习近平向晋升上将军衔的中央军委纪律检查委员会书记兼中央军委监察委员会主任张曙光、空军司令员王刚颁发命令状，表示祝贺。佩戴上将军衔的2位军官向习近平敬礼，向参加仪式的全体同志敬礼，全场响起热烈掌声。\n晋衔仪式在嘹亮的中国人民解放军军歌声中结束。随后，习近平等领导同志同晋升上将军衔的军官合影。\n军委机关各部门、军队驻京有关单位主要负责同志等参加晋衔仪式。"}, {"title": "《习近平关于基层工作方法论述摘编》出版发行", "detail": "中共中央党史和文献研究院编辑的《习近平关于基层工作方法论述摘编》一书，近日由中央文献出版社出版，在全国发行。\n基层是党的执政之基、力量之源，是一切工作的落脚点。无论是在地方工作期间还是到中央工作以后，习近平同志始终重视基层、关心基层、深入基层、支持基层，坚持把抓基层打基础作为长远之计和固本之策，探索形成了一系列富有理论意义和实践价值的基层工作方法。习近平同志围绕基层工作方法发表的一系列重要论述，立意高远，内涵丰富，思想深刻，科学回答了什么是基层、如何深入基层、如何服务基层等重大理论和实践问题，深化了对基层工作的规律性认识，对于树立大抓基层的鲜明导向，树立和践行正确政绩观，走好新时代党的群众路线，不断增强人民群众的获得感、幸福感、安全感，使中国式现代化拥有最可靠、最深厚、最持久的力量源泉，具有十分重要的意义。\n《论述摘编》分9个专题，共计287段论述，摘自习近平同志1983年4月至2026年4月期间的报告、讲话、文章、指示、批示等190多篇重要文献。其中部分论述是第一次公开发表。"}, {"title": "习近平致电祝贺藤森庆子当选秘鲁总统", "detail": "7月6日，国家主席习近平致电藤森庆子，祝贺她当选秘鲁共和国总统。\n习近平指出，中国和秘鲁是全面战略伙伴，两国关系保持良好发展势头。双方高层交往频繁，各领域务实合作成果丰硕，人民友好深入人心。今年是中秘建交55周年。我高度重视中秘关系发展，愿同藤森庆子当选总统一道努力，赓续两国传统友谊，引领中秘全面战略伙伴关系不断迈上新台阶，更好造福两国人民。\n同日，国家副主席韩正向秘鲁当选第一副总统加拉雷塔致贺电。"}, {"title": "习近平同黑山总统就中国同黑山建交20周年互致贺电", "detail": "7月6日，国家主席习近平同黑山总统米拉托维奇互致贺电，庆祝两国建交20周年。\n习近平指出，中黑两国传统友谊深厚，建交20年来，始终相互尊重、平等相待、互利共赢，树立了不同大小国家友好相处、共同发展的典范。我愿同米拉托维奇总统一道努力，以两国建交20周年为新起点，传承发扬传统友谊，持续深化互利合作，引领中黑关系再上新台阶，更好造福两国人民。\n米拉托维奇表示，黑中两国始终在相互尊重和理解基础上发展友好合作关系。黑方愿同中方以建交20周年为契机，进一步巩固深化友好关系，拓展各领域合作，造福两国人民，为促进世界和平发展作出积极贡献。"}, {"title": "习近平对防汛救灾工作作出重要指示强调 要全力组织抢险救援、伤员救治、群众安置 扎", "detail": "实做好防灾救灾各项工作 确保人民群众生命财产安全 李强作出批示\n中共中央总书记、国家主席、中央军委主席习近平对防汛救灾工作作出重要指示。\n习近平指出，近日，广西、湖北、甘肃等地因降雨大风天气，接连发生水库溃坝、山体滑坡等灾情，造成重大人员伤亡和经济损失。要全力组织抢险救援、伤员救治、群众安置等工作，最大限度减少人员伤亡，防范次生灾害。\n习近平强调，当前防汛形势严峻复杂，各地各有关部门要抓好既定部署措施落实，坚决克服麻痹思想和侥幸心理，盯紧压实防灾救灾责任，深入开展江河湖泊、病险水库、地质灾害易发区等风险隐患排查整治，强化监测预警和应急救援准备，扎实做好防灾救灾各项工作，确保人民群众生命财产安全。\n中共中央政治局常委、国务院总理李强作出批示指出，近期极端天气多发，国家防办、国家防减救灾办要指导各地密切关注雨情汛情，加强险情监测预警，全力开展抢险救援，深入排查灾害风险隐患，落实落细各项防汛救灾措施，严防发生重大次生灾害。"}, {"title": "国家科学技术奖励大会 两院院士大会 中国科协第十一次全国代表大会在京召开 习近平", "detail": "发表重要讲话\n国家科学技术奖励大会、中国科学院第二十二次院士大会和中国工程院第十八次院士大会、中国科学技术协会第十一次全国代表大会7月8日上午在人民大会堂隆重召开。中共中央总书记、国家主席、中央军委主席习近平出席大会，为国家最高科学技术奖获得者等颁奖并发表重要讲话。他强调，“十五五”时期是科技强国建设的关键攻坚期。必须抓住历史机遇，迎接时代挑战，加快推进高水平科技自立自强，向着到2035年建成科技强国的目标坚定迈进，扎扎实实以科技创新支撑和引领中国式现代化。\n李强主持大会，赵乐际、王沪宁、蔡奇、李希出席大会，丁薛祥宣读奖励决定。\n上午10时30分，大会开始，全场起立，高唱国歌。\n丁薛祥宣读《中共中央、国务院关于2025年度国家科学技术奖励的决定》。\n仪式号角响起，习近平首先向获得2025年度国家最高科学技术奖的中国科学院物理研究所陈立泉院士和中国电子科技集团第十四研究所贲德院士颁发奖章、证书，同他们热情握手表示祝贺。随后，习近平等党和国家领导人同两位最高奖获得者一道，为获得国家自然科学奖、国家技术发明奖、国家科学技术进步奖和中华人民共和国国际科学技术合作奖的代表颁发证书。\n在热烈的掌声中，习近平发表重要讲话。他指出，党的十八大以来，党中央把科技创新摆在现代化建设突出位置，系统擘画科技强国建设蓝图，深入推动实施创新驱动发展战略，全面深化科技体制改革，推动科技事业取得历史性成就、发生历史性变革。我国正从全球科技参与者、贡献者向开拓者、引领者加速转变，成为创新力上升最快的国家之一。\n习近平强调，新一轮科技革命和产业变革深刻改变人类生产生活方式和世界发展格局。我们要适应新形势新要求，采取更加有力的措施，切实解决我国科技发展中存在的问题，全力抓好党中央关于科技事业各项部署的落实。\n习近平指出，要增强科技创新体系化攻关能力，提升国家创新体系整体效能。坚持“四个面向”战略导向，进一步加强科技战略规划、政策措施、重大任务、科研力量、资源平台、区域创新等方面统筹。完善国家重大科技创新任务部署和组织实施机制，强化科研基础条件自主保障。优化国家战略科技力量功能定位和布局，推动任务协同、资源共享、优势互补。加强对各层级科技工作的统筹指导，形成央地协同、区域联动的制度安排。\n习近平强调，要推动科技创新和产业创新深度融合，打通科技加速向现实生产力转化的通道。科技创新要突出应用导向，产业创新要提出科学问题。加强国家技术转移体系建设，打造多元化应用场景和高水平产业集群，促进自主研发技术产品推广应用和迭代升级。完善知识产权保护制度。构建同科技创新相适应的科技金融体制。\n习近平指出，科学的未来在青年，要优化科教协同育人机制，大力培养优秀青年科技人才。加大对科研人员支持力度，帮助解决实际困难，让他们潜心钻研、安身安心安业。注重挖掘和培养青少年兴趣特长、科学素养、实验能力，吸引更多具有科研潜质的青少年立志投身科技事业。\n习近平强调，要提高科技创新投入效能，实现投入规模增加与效能提升的统一。完善中央财政科技经费分配和管理使用机制，健全重大科技任务央地投入共担机制。改进科技计划管理，加强科技项目监督检查和绩效评估。引导企业增加研发投入，调动更多社会力量支持科技创新。\n习近平指出，要深化科技评价改革，用好科技评价指挥棒。项目评审、机构评估、人才评价都要强化创新能力、质量、实效、贡献导向。加快“破四唯”，持续深化科教界“帽子”治理。大力弘扬科学家精神，加强科研诚信建设，营造风清气正的科研生态。\n习近平强调，要加强科技伦理和安全治理，推动科技向上向善、安全可控、造福人民。完善政策制度、法律法规和治理规范，健全多方参与、协同共治的体制机制。明确重点领域伦理标准和指引，加强科技安全风险研判、监测预警和应急响应。深度参与全球科技治理，广泛宣介中国主张和中国方案。\n习近平指出，推动我国科技事业欣欣向荣，需要全党全社会共同努力。各级党委和政府要把科技工作摆上重要日程，树立和践行正确政绩观，真抓实干，久久为功，不断抓出新成效。中国科学院、中国工程院要团结全国科技界把握新一轮科技革命方向，勇攀世界科学高峰。中国科协要坚持探索创新，尽心尽力为科技工作者服务、为创新驱动发展服务、为提高全民科学素质服务、为党和政府科学决策服务。\n习近平表示，希望两院院士珍视荣誉、不懈奋斗，在开拓科技前沿、担纲重大任务、培育青年人才、践行科学家精神方面发挥示范引领作用。希望广大科技工作者发扬服务国家、造福人民的优良传统，为建设科技强国多立新功。\n李强在主持大会时指出，习近平总书记的重要讲话，充分肯定了近年来我国科技事业取得的重大成就，深刻分析了科技发展面临的新形势，就进一步增强责任感紧迫感使命感、全力抓好党中央关于“十五五”时期科技事业各项部署的落实提出了明确要求。习近平总书记的重要讲话高屋建瓴、思想深邃、内涵丰富，具有很强的政治性、战略性、指导性，为做好新时代科技工作指明了前进方向、提供了根本遵循。我们要深入学习领会，坚决贯彻落实，切实把思想和行动统一到党中央决策部署上来，进一步增强做好科技工作的决心和信心，为以中国式现代化全面推进强国建设、民族复兴伟业作出新的更大贡献。\n会上，陈立泉和贲德代表全体获奖人员发言。\n会前，习近平等领导同志亲切会见了国家科学技术奖获奖代表，并同大家合影留念。\n部分中共中央政治局委员，中央书记处书记，全国人大常委会、国务院、全国政协、中央军委有关领导同志出席大会。\n中央党政军群有关部门主要负责同志，中央科技委员会委员，国家科学技术奖励委员会委员，各省区市和计划单列市、新疆生产建设兵团有关负责同志，国家科学技术奖获奖代表，两院院士、部分外籍院士，中国科协第十一次全国代表大会代表等约4300人参加大会。\n2025年度国家科学技术奖共评选出258个项目和11名科技专家。其中，国家最高科学技术奖2人；国家自然科学奖51项，其中一等奖3项、二等奖48项；国家技术发明奖58项，其中一等奖3项、二等奖55项；国家科学技术进步奖149项，其中特等奖3项、一等奖13项、二等奖133项；授予9名外国专家中华人民共和国国际科学技术合作奖。"}, {"title": "习近平对福建泉州晋江市一鞋厂火灾事故作出重要指示强调 深入排查整治各类风险隐患", "detail": "抓实抓细安全生产措施落实 坚决防止重特大事故发生 李强作出批示\n7月9日12时许，福建泉州晋江市一鞋厂发生火灾，造成重大人员伤亡。\n事故发生后，中共中央总书记、国家主席、中央军委主席习近平高度重视并作出重要指示指出，福建泉州晋江市一鞋厂发生火灾，造成重大人员伤亡。要全力做好人员搜救、善后安抚等工作，尽快查明事故原因并严肃追责。\n习近平强调，今年以来，国内发生多起重大生产安全事故，各地区各有关部门要深刻汲取教训，更好统筹发展和安全，时刻绷紧安全生产这根弦，深入排查整治各类风险隐患，抓实抓细安全生产措施落实，坚决防止重特大事故发生，切实维护人民群众生命财产安全。\n中共中央政治局常委、国务院总理李强作出批示指出，要全力组织搜救，做好善后处置，防范次生事故，同时尽快查明原因，依法严肃追责。国务院安委办要进一步指导督促各地树牢底线思维、极限思维，全面排查安全生产风险隐患，狠抓责任措施落实，严防重特大事故发生。\n根据习近平重要指示和李强要求，应急管理部已派出工作组赶赴现场指导。福建省已组织力量全力做好伤员救治和现场处置等工作。目前，各项工作正在进行中。"}, {"title": "习近平同纳米比亚总统会谈", "detail": "7月10日下午，国家主席习近平在北京人民大会堂同来华进行国事访问的纳米比亚总统恩代特瓦举行会谈。两国领导人共同宣布将双边关系定位提升为新时代中纳命运共同体。\n习近平指出，中国和纳米比亚有着深厚传统友谊和共同发展追求。建交以来，两国始终平等相待、相互支持，友好合作不断深化，有力造福两国人民。中国共产党正团结带领全国各族人民，以中国式现代化全面推进强国建设、民族复兴伟业，纳米比亚正朝着2030年远景目标前进，深化两国友好合作正当其时、前景可期。中方愿同纳方加强发展理念交流和发展战略对接，在实现各自现代化的道路上携手前行。\n习近平就构建新时代中纳命运共同体提出3点意见。一是坚定相互支持，深化理念融通。双方要密切高层交往，深化治国理政经验交流，就双边关系中的全局性、战略性问题保持经常性沟通，在涉及彼此核心利益和重大关切问题上继续相互支持。二是挖掘合作潜力，提升合作水平。中方已经对53个非洲建交国全面实施零关税举措，这是中国扩大高水平对外开放的重大创举，也是支持非洲国家加快发展的“及时雨”。希望纳方用足零关税、升级后的输华产品“绿色通道”以及其他优惠政策，让纳米比亚优质产品更多更快进入中国市场。中方愿同纳方深化基础设施建设、能源、矿产、农业、教育、青年、科技等领域合作，推动两国互利合作不断迈上新台阶。三是坚持团结协作，捍卫多边主义。中纳两国同为全球南方重要成员，拥有广泛共同利益和相近价值追求，应该加强团结协作，坚定相互支持，共同维护国际公平正义。中方愿同包括纳米比亚在内的非洲国家继续加强协调配合，持续壮大全球南方声势和力量，为推动构建人类命运共同体作出新贡献。\n习近平指出，帮助非洲开发丰富矿产资源、切实将资源优势转化为发展动能，是加快非洲现代化进程的重要途径。中方愿继续同包括纳米比亚在内的非洲国家加强矿业合作，重点把握好3条原则。一是互利共赢。非方拥有丰富自然资源，中方拥有先进技术和超大规模市场，双方要充分发挥互补优势，深化利益融合。二是友好协商。牢固政治互信是中非合作的独特优势和重要保障，要坚持从中非友好大局出发，通过沟通协商妥善处理合作中的问题。三是开拓进取。中方愿同非方按照市场化商业化原则，创新合作思路，推动中非矿业合作不断提质升级。\n恩代特瓦表示，纳米比亚同中国的友谊源远流长，两国关系长期高水平发展。热烈祝贺中国共产党成立105周年。中国是伟大的国家，在习近平主席英明领导下，经济社会发展取得令世人钦佩的成就。纳方高度重视对华关系，坚定奉行一个中国原则。愿学习借鉴中国经验，加强团结、巩固互信、拓展合作，推动两国全面战略合作伙伴关系取得更大发展。纳米比亚人组党愿同中国共产党加强党际交流，密切沟通合作。纳米比亚愿同中国扩大贸易往来，欢迎更多中国企业赴纳投资兴业，期待双方加强工业、矿业、基础设施、航空航天、科技、农业、水利资源等领域合作，帮助纳经济社会发展。中方长期以来为包括纳米比亚在内的非洲国家提供无私支持帮助，在国际地区事务中秉持公正立场，纳方愿同中方加强沟通协调，维护发展中国家共同利益，共建人类命运共同体。\n会谈后，两国元首共同见证签署经济贸易、医疗卫生、教育和人力资源等领域多项合作文件。\n双方发表《中华人民共和国和纳米比亚共和国关于构建新时代中纳命运共同体的联合声明》。\n会谈前，习近平和夫人彭丽媛在人民大会堂北大厅为恩代特瓦和丈夫埃帕夫拉斯举行欢迎仪式。\n恩代特瓦抵达时，礼兵列队致敬。两国元首登上检阅台，军乐团奏中纳两国国歌，天安门广场鸣放礼炮21响。恩代特瓦在习近平陪同下检阅中国人民解放军仪仗队，并观看分列式。\n当晚，习近平和彭丽媛在人民大会堂金色大厅为恩代特瓦夫妇举行欢迎宴会。"}, {"title": "习近平会见朝鲜内阁总理", "detail": "7月10日下午，中共中央总书记、国家主席习近平在北京人民大会堂会见来华进行正式访问的朝鲜劳动党中央政治局常委、国务委员会副委员长、内阁总理朴泰成。\n习近平指出，上个月，我对朝鲜进行国事访问，同金正恩总书记为巩固和发展中朝传统友好并不断赋予其新的时代内涵作出战略指引。世代友好、命运与共、守望相助始终是中朝关系的鲜明特征。《中朝友好合作互助条约》为巩固两国人民用鲜血凝成的战斗友谊奠定重要政治法律基础。我和金正恩总书记一致同意，以共同隆重纪念条约签订65周年为契机，不忘两党两国老一辈领导人的初心宗旨，引导两国人民继承和发扬中朝传统友谊，让两国关系在新的历史时期持续焕发蓬勃生机。\n习近平强调，当前，国际形势变乱交织。中朝两国应当保持战略定力，增强战略自信，加快落实我同金正恩总书记达成的共识，确保两党两国关系与时俱进，始终朝着有助于巩固各自社会主义事业、有利于促进各自国家现代化建设的方向发展。要稳步推进务实合作，持续巩固民意基础，用好共同的红色记忆和红色资源，让两国青年铭记中国人民志愿军的历史功绩，让伟大的中朝友谊世世代代传承下去。要加强战略协作，坚定捍卫各自主权、安全、发展利益，为两国走好符合自身国情的社会主义道路营造有利外部环境。\n朴泰成首先转达金正恩总书记对习近平总书记的亲切问候，表示在《朝中友好合作互助条约》签订65周年之际，金正恩总书记祝愿习近平总书记在领导中国党和人民的崇高事业中不断取得新成就。朴泰成表示，热烈祝贺中国共产党成立105周年，祝贺习近平总书记领导中国人民取得伟大发展成就。习近平总书记今年首次出访就选择了朝鲜，两党两国最高领导人举行历史性会晤，树立了双边关系新的里程碑，进一步巩固了朝中友好的民意基础。《朝中友好合作互助条约》从战略高度、长远角度为推动两国关系发展提供了强有力的法律保障。朝中两国本着条约精神，守望相助，共同推动社会主义事业发展，携手捍卫地区和世界和平。两国隆重举行条约签订65周年纪念活动，再次彰显朝中友谊经受住国际风云变幻考验，具有高度战略性。金正恩总书记要求将朝中关系发展为最强有力的战略关系。朝方将坚决落实两党两国最高领导人达成的重要共识，坚定支持中方在台湾等问题上捍卫核心利益，竭尽全力推动朝中团结、友好和社会主义事业迈上新的更高台阶。"}, {"title": "习近平同朝鲜劳动党总书记、国务委员会委员长金正恩就《中朝友好合作互助条约》签订6", "detail": "5周年互致贺电\n7月11日，中共中央总书记、国家主席习近平同朝鲜劳动党总书记、国务委员会委员长金正恩就《中朝友好合作互助条约》签订65周年互致贺电。\n习近平指出，1961年，中朝两国老一辈领导人签订《中朝友好合作互助条约》，为巩固两国人民用鲜血凝成的战斗友谊奠定了重要政治法律基础，对传承弘扬中朝友好、维护地区乃至世界和平稳定发挥了重要作用。65年来，双方秉持条约精神，相互支持、团结协作、并肩奋斗，生动诠释了中朝关系世代友好、命运与共、守望相助的鲜明特征。\n习近平强调，今年6月，我成功对朝鲜进行国事访问，同总书记同志就巩固传承中朝传统友谊并注入新的时代内涵达成重要共识，为新时期中朝关系发展作出战略指引、擘画新的蓝图。面对加速演进的世界百年变局，我愿同总书记同志进一步密切战略沟通，把牢两国关系发展方向，引领双方友好合作更好造福两国人民，为促进地区和平与发展作出积极贡献。\n习近平指出，我愿重申，无论国际形势如何变化，中国党和政府高度重视中朝传统友好的坚定立场不会改变，对金正恩总书记同志领导朝鲜社会主义事业的坚定支持不会改变，维护中朝双方共同利益和良好战略环境的坚定决心不会改变。相信在以总书记同志为首的朝鲜劳动党领导下，朝鲜人民必将全面贯彻落实朝鲜劳动党九大各项决策部署，在社会主义建设事业中不断取得新的更大成就。\n金正恩表示，65年前，双方签订《朝中友好合作互助条约》，为在实现反帝自主、和平和社会主义伟业的浴血奋战历程中结成的朝中战斗友谊和团结互助合作关系永续发展奠定了坚实的法律基础。过去一段时期，朝中两国历经历史风雨，始终相互坚定支持、密切合作，向全世界充分彰显了因传统友谊而特殊、因共同的社会主义伟业而特殊、因坚定不移传承而特殊的朝中友好关系的永不褪色和牢不可破。\n金正恩表示，朝中友好合作关系作为两党和两国人民的战略性选择和共同宝贵财富，正在新的战略高度得到升华和发展，并在复杂多变的国际局势中，为维护两国主权、安全和发展利益，捍卫地区乃至世界和平稳定作出重要贡献。推动以社会主义为核心的朝中传统友好合作关系顺应时代变迁和两国人民意愿，并在各领域实现更活跃发展，是朝鲜党和政府坚定不移的立场。我愿同总书记同志一道，引领以悠久历史和优秀传统为基础的朝中友谊迈向新高度，发展成为最强有力、最富战略性的社会主义国家间关系典范。"}, {"title": "习近平在上海考察时强调 全面践行人民城市理念 高质量推进城市更新", "detail": "中共中央总书记、国家主席、中央军委主席习近平7月15日在上海考察时强调，高质量推进城市更新是城市现代化建设的重要抓手，要全面践行人民城市理念，坚持问需于民、问计于民、问效于民，做深做细做实城市更新各项工作，不断增强居民群众的获得感、幸福感、安全感。\n15日下午，习近平在中共中央政治局委员、上海市委书记陈吉宁和市长龚正陪同下，来到位于黄浦区的半淞园路街道市民新村居民区考察调研。\n市民新村居民区4幢上世纪50年代建成的楼房，通过改建更新，设立独立厨卫、加装电梯，居住条件明显改善。习近平走进社区综合服务点，听取上海市推进无卫生设施旧房提升改造、历史性解决老城区居民“拎马桶”问题和小区改造介绍，并向现场工作人员详细询问有关情况。习近平强调，党中央高度重视城市工作，明确提出要建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市，改造城市老旧小区是重要一环。工作中要牢固树立和践行正确政绩观，想群众之所想，急群众之所急，制定实施有效的政策举措，坚持久久为功，把老百姓关切的事一件一件办好，持续增进民生福祉。要以“绣花功夫”不断提升小区物业管理和便民服务水平，努力让居民群众满意。\n在退休居民朱国莉家，习近平仔细察看居住情况。朱国莉告诉总书记，现在有了自家的厨房、卫生间，生活方便多了。习近平听了很高兴。他说，“一枝一叶总关情”，老百姓的生活是家事，更是国事。共产党就是为老百姓服务的，只有人民群众安居乐业、生活舒心，党和政府才放心。希望你们把退休生活安排好，把家庭建设搞得更好。\n随后，习近平来到社区党群服务站，察看便民菜摊果蔬供应情况，在“市民客厅”同居民代表、街道干部、社区工作者等亲切交流。习近平指出，社区是城市治理体系的基本单元。要提高社区治理水平，推动资源、服务、管理等下沉基层一线，持续为基层减负赋能。要进一步加强党建引领，积极探索社区党组织领导下的居委会、业委会、物业服务企业协调运行新模式，建设完整社区和便民生活圈，用心用情为居民做好事、办实事、解难事。\n考察途中，习近平强调，当前，正处于防汛关键期，各地区各有关方面要树牢底线思维、极限思维，密切关注雨情汛情和台风形势，深入细致开展风险隐患排查，扎实做好防汛抗洪、抢险救灾等工作，切实维护人民群众生命财产安全。\n中共中央政治局常委、中央办公厅主任蔡奇陪同考察。\n中央和国家机关有关部门负责同志陪同考察。"}, {"title": "习近平会见哈萨克斯坦总统", "detail": "7月16日下午，国家主席习近平在上海西郊宾馆会见来华出席2026世界人工智能大会暨人工智能全球治理高级别会议的哈萨克斯坦总统托卡耶夫。\n习近平指出，世界百年变局深刻复杂演进，中哈关系在考验和洗礼中历久弥坚，两国永久全面战略伙伴关系保持高水平运行，展现了巨大合作潜力和广阔发展空间。中方刚刚庆祝了中国共产党成立105周年。中国共产党之所以能够在奋斗中不断铸就辉煌，历史和人民之所以选择中国共产党，根本在于中国共产党具有矢志追求真理、深深植根人民、勇担历史使命、顺应发展潮流、敢于善于斗争、注重强健自身等优秀特质。这是中国共产党为什么能的关键密码。哈萨克斯坦正在大力推进全面改革，这是着眼国家未来作出的战略规划。中哈双方要加强发展战略和政策对接，不断提升务实合作水平，助力共同发展，推动中哈战略协作不断迈上新台阶、取得新成果。\n习近平强调，坚定推进中哈全面合作，符合两国和两国人民根本利益。双方要推动贸易创新发展，优化贸易结构，培育跨境电商、服务贸易新业态；拓展能源矿产合作，加快推进重点项目落地实施；推进互联互通建设，增开更多直航航班，提升国际道路运输便利化水平；培育新质生产力，中方愿分享数字经济、人工智能等技术，助力哈萨克斯坦实现数字化转型；办好“中哈文化交流年”，加强教育、科技、医疗、卫生、体育、媒体等合作，夯实世代友好根基。中方愿同哈方共同践行四大全球倡议，在联合国、上海合作组织、中国—中亚机制等多边机制内加强协调和配合，共同捍卫国际公平正义。\n托卡耶夫表示，很高兴来到上海这一充满创新活力的城市出席世界人工智能大会。热烈祝贺中国共产党成立105周年，祝贺中国在习近平主席英明领导下取得举世瞩目的发展成就。哈萨克斯坦视对华关系为哈外交首要方向，致力于不断加强同中国的永久全面战略伙伴关系。哈方完全同意并将同中方积极落实习近平主席关于发展双边关系的重要意见，期待同中方密切高层交往，加强贸易、投资、交通、能源、农业、数字经济等方面务实合作，促进人文交流，让两国关系发展取得更多实实在在的成果。哈方高度赞赏和支持习近平主席提出的四大全球倡议和构建人类命运共同体理念，愿同中方在联合国、上海合作组织、中国—中亚机制、亚信等多边平台继续保持高水平协作，积极开展人工智能全球治理合作，共同促进全球可持续发展与和平稳定。\n会见后，两国元首共同见证签署和宣布经贸、交通、财政、媒体等领域多项合作文件。\n蔡奇、丁薛祥、王毅、陈吉宁等参加上述活动。"}, {"title": "《求是》杂志发表习近平总书记重要文章《在庆祝中国共产党成立105周年大会上的讲话", "detail": "》\n7月16日出版的第14期《求是》杂志发表中共中央总书记、国家主席、中央军委主席习近平的重要文章《在庆祝中国共产党成立105周年大会上的讲话》。\n文章强调，105年来，我们党团结带领全国各族人民不懈奋斗，创造了新民主主义革命、社会主义革命和建设、改革开放和社会主义现代化建设、新时代中国特色社会主义的伟大成就，书写了中华民族几千年历史上最恢宏的史诗。105年不懈奋斗，从根本上改变了中国人民的前途命运，开辟了实现中华民族伟大复兴的正确道路，展示了马克思主义的强大生命力，深刻影响了世界历史进程，锻造了强大的中国共产党。\n文章指出，中国共产党之所以能够在105年奋斗中不断铸就辉煌，历史和人民之所以选择中国共产党，根本在于我们党具有其他政党和政治力量无可比拟的优秀特质：矢志追求真理，始终把准前进方向；深深植根人民，始终拥有坚实根基；勇担历史使命，始终掌握战略主动；顺应发展潮流，始终走在时代前列；敢于善于斗争，始终保持必胜信心；注重强健自身，始终充满生机活力。这些优秀特质，是中国共产党为什么能的关键密码。我们要结合新的实际，把党的优秀特质不断发扬光大，确保党永远不变质不变色不变味，始终具有强大创造力凝聚力战斗力。\n文章指出，实现新时代新征程党的使命任务，要求全体中国共产党人坚定信心、接续奋斗，不断创造无愧于时代和人民的新业绩。必须坚持党的基本理论、基本路线、基本方略，坚持党的全面领导和党中央集中统一领导，深入贯彻新时代中国特色社会主义思想，坚定道路自信、理论自信、制度自信、文化自信，继往开来、守正创新。必须紧紧依靠人民创造历史伟业，践行以人民为中心的发展思想，充分激发亿万人民的积极性主动性创造性，统筹推进“五位一体”总体布局、协调推进“四个全面”战略布局，完整准确全面贯彻新发展理念，加快构建新发展格局，扎实推动高质量发展。必须积极应对前进道路上的风险挑战，强化忧患意识、坚持底线思维，发扬斗争精神、增强斗争本领，更好统筹国内国际两个大局，统筹发展和安全。必须持续推动构建人类命运共同体，高举和平、发展、合作、共赢旗帜，弘扬全人类共同价值，推动落实全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议，为世界和平与发展注入更多正能量。必须持之以恒推进全面从严治党，全面贯彻新时代党建思想，健全全面从严治党体系，以党的政治建设为统领加强党的各方面建设，坚决打好反腐败斗争攻坚战持久战总体战，不断增强党的政治领导力、思想引领力、群众组织力、社会号召力，确保党在新时代坚持和发展中国特色社会主义的历史进程中始终成为坚强领导核心。\n文章强调，中国共产党105年的辉煌历史令人自豪，但我们决不能骄傲自满、止步不前。全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争，紧紧依靠和团结带领全国各族人民奋进新征程、建功新时代，奋力创造新的历史辉煌。"}, {"title": "习近平出席2026世界人工智能大会暨人工智能全球治理高级别会议开幕式并发表主旨讲", "detail": "话\n7月17日上午，国家主席习近平在上海世界会客厅出席2026世界人工智能大会暨人工智能全球治理高级别会议开幕式并发表主旨讲话。\n黄浦江畔，潮启新澜。世界会客厅内嘉宾云集。\n习近平同与会的国家元首、政府首脑、国际组织负责人及各国代表团团长集体合影。\n在热烈的掌声中，习近平发表题为《携手构建公正合理的全球人工智能治理体系》的主旨讲话。\n习近平指出，当前，世界百年变局加速演进，新一轮科技革命和产业变革加速突破，全球人工智能技术创新进入前所未有的活跃期，既蕴含巨大机遇，也面临治理挑战。人类不得不直面时代之问：当机器开始思考，人类如何与之相处？当算法参与决策，安全如何保障？当技术挑战伦理，治理如何跟上？当鸿沟不断拉大，普惠如何实现？中方认为，各国应当秉持以人为本、向上向善理念，让人工智能成为促进共同繁荣、维护共同安全的一个重要动力源，携手构建公正合理的全球人工智能治理体系。\n习近平就此提出4点意见：\n第一，坚持开放共赢，驱动创新发展。抓住难得的历史性机遇，鼓励开源开放、合作共享，全面促进人工智能科技创新、产业发展、场景应用，协同推进传统产业改造升级、新兴产业培育壮大、未来产业前瞻布局，让人工智能赋能千行百业。\n第二，强化风险意识，确保安全可控。高度重视人工智能引发的各类内生和衍生风险，推动构建法律法规、技术监测、风险预警、应急响应体系，筑牢安全底线，防范滥用恶用，确保人工智能始终处于人类控制之下。共同反对在人工智能领域泛化国家安全概念、把本国安全凌驾于他国安全之上的做法。\n第三，鼓励包容并蓄，促进文明互鉴。用全人类共同价值塑造人工智能的价值观，善用人工智能技术增进不同文明的理解和包容，促进不同文明交流互鉴，精心培育各美其美、美美与共的文明百花园。\n第四，倡导和衷共济，完善全球治理。践行真正的多边主义，切实发挥联合国的重要作用，加强人工智能发展战略、治理规则、技术标准的对接协调，早日形成具有广泛共识的全球治理框架，让这一前沿技术更好造福人类社会。帮助全球南方国家加强能力建设，弥合数智鸿沟，促进可持续发展，避免在人工智能领域造成新的历史不公。\n习近平强调，今年是中国“十五五”开局之年。“十五五”规划为未来5年中国经济社会发展擘画蓝图，也为国际社会提供机遇清单。近年来，中国坚持有效市场和有为政府相结合，加强人工智能科技创新，积极推进“人工智能+”行动，培育各类主体共生共荣的健康生态，智能经济核心产业规模已经超过万亿元人民币，“中国智造”已成为中国式现代化的又一亮丽名片。同时，中国坚持发展和安全并重，不断完善相关法律法规、政策制度、应用规范、伦理准则，确保人工智能安全、可靠、可控。作为负责任大国，中国在人工智能领域始终致力于做国际公共产品的提供者，源源不断贡献中国方案。\n习近平指出，在各方共同努力下，世界人工智能合作组织在上海应运而生。这是中方响应全球南方呼声、团结国际社会积极推动人工智能发展和治理的重大举措，将成为人工智能发展史上的一个重要里程碑。为进一步支持全球人工智能发展、推进全球人工智能能力建设，未来5年，中国将面向发展中国家提供5000个人工智能专题研修培训名额；面向东盟、阿盟、非盟、拉共体、上合组织、金砖国家建设国际人工智能应用合作中心；推动气象智能预警方案“妈祖”在30个国家落地应用。中国愿以更加开放的姿态、更加务实的行动、更加长远的目光，同各方一道把握和应对人工智能发展的机遇和挑战，携手共创人类社会更加美好的未来。\n哈萨克斯坦总统托卡耶夫、柬埔寨首相洪玛奈、泰国总理阿努廷、联合国秘书长古特雷斯分别致辞。他们热烈祝贺世界人工智能合作组织协定签署仪式在上海举行，高度评价中国为推动人工智能全球治理作出的重要贡献，积极呼应习近平主席提出的倡议和举措。各方表示，人工智能有望成为人类最大的发展机遇，也潜藏着风险。中国倡导智能向善、普惠包容、安全可控，积极帮助发展中国家加强相关能力建设，推动人工智能国际合作，彰显了负责任的大国担当。人工智能技术应由各国共享共治，使其公平惠及所有国家，服务全人类可持续发展，消弭全球数智鸿沟和南北发展差距。人工智能带来的机遇与挑战跨越国界，需要各方携手合作把握和应对。希望并相信世界人工智能合作组织将为此发挥重要作用，通过开放包容、平等互惠的合作，共同打造安全、繁荣、不让任何国家掉队的美好未来。\n大会发表《2026世界人工智能大会暨人工智能全球治理高级别会议主席声明》。\n7月16日晚，习近平和夫人彭丽媛在世界会客厅为与会国际贵宾举行欢迎宴会。\n蔡奇、丁薛祥、王毅等出席上述活动。\n陈吉宁主持开幕式。"}, {"title": "习近平会见柬埔寨首相", "detail": "7月17日下午，国家主席习近平在上海西郊宾馆会见来华出席2026世界人工智能大会暨人工智能全球治理高级别会议并进行工作访问的柬埔寨首相洪玛奈。\n习近平指出，中柬两国同舟共济、守望相助，铁杆友谊历经了岁月洗礼和风雨考验。历史证明，中柬友好不是一时一事之交，而是穿越风云变幻、世代相传的共识，是双方共同的宝贵财富。双方要传承两国老一辈领导人缔造的铁杆友谊，增进战略互信，密切团结协作，充实“钻石六边”合作内涵，推动新时代全天候中柬命运共同体建设不断迈向更高水平，更好造福两国人民。\n习近平强调，中国共产党在管党治党、兴党强党的伟大实践中形成新时代党建思想，将持续凝聚中国式现代化建设的磅礴伟力。今年是柬埔寨人民党成立75周年，中方愿同柬方加强治党治国经验交流，坚定走好新时代中柬友好合作之路。双方要发挥中柬政府间协调委员会作用，加快“工业发展走廊”和“鱼米走廊”建设，优化电力、农业等传统产业，培育人工智能、数字经济等新兴产业，统筹推进有利于柬埔寨国计民生的基础设施建设项目。要用好中柬外交、国防、公安“3+3”战略对话机制，联手严打制假走私、网赌电诈等跨境犯罪，维护好共同利益和安全。中方愿同柬方共同推动落实四大全球倡议，推动构建更加公正合理的全球治理体系。巩固柬泰停火态势、逐步建立互信符合两国的根本和长远利益，中方支持柬泰双方通过对话谈判找到解决方案，愿继续为此发挥积极作用。\n洪玛奈表示，祝贺中国成功举办2026世界人工智能大会，习近平主席提出的重要理念和主张对于人工智能全球治理具有重要意义。柬中高层交往密切，各领域合作成果丰硕，感谢中方长期以来为柬埔寨经济社会发展提供的无私支持和帮助。无论国际形势如何变化，柬方密切对华友好合作的政策决不会改变，将积极致力于共建柬中命运共同体。柬方坚定奉行一个中国原则，愿同中方弘扬传统友谊，落实好两国领导人达成的重要共识，深化政治互信，扩大两国贸易，开展基础设施等重大项目合作，加大力度打击电信诈骗，推动两国关系发展取得更多成果。柬方感谢中方积极劝和促谈，推动和平解决柬泰边境争端，柬方将坚持对话谈判、缓和局势。\n蔡奇、丁薛祥、王毅、陈吉宁等参加会见。"}, {"title": "习近平会见泰国总理", "detail": "7月17日下午，国家主席习近平在上海西郊宾馆会见来华出席2026世界人工智能大会暨人工智能全球治理高级别会议并进行正式访问的泰国总理阿努廷。\n习近平指出，中泰友好绵延千年、历久弥坚。双方以诚相待、以心相交，结成“中泰一家亲”情谊。中方将发展中泰关系置于周边外交重要位置，始终是泰方可信赖、可依靠的战略合作伙伴。中泰双方要进一步增进战略互信，加强战略协作，携手应对挑战，加快构建更为稳定、更加繁荣、更可持续的中泰命运共同体，助力两国各自现代化进程，为促进地区和平稳定和发展繁荣作出积极贡献。\n习近平强调，中方坚定支持泰国走好符合自身国情的发展道路，支持泰国新政府顺利施政。面对复杂深刻变化的国际形势，中泰双方要密切高层交往，用好两国外长、防长“2+2”战略对话机制，推动战略协作迈向更高水平。加快推进中泰铁路建设和中老泰铁路互联互通，拓展人工智能、航空航天、清洁能源等新兴领域合作。加强旅游、媒体、教育等合作，推动两国民众越走越亲。继续大力打击网赌电诈等跨境犯罪，为两国务实合作和人员往来营造安全环境。中方支持泰方在国际和地区事务中发挥更大作用，愿同泰方密切在亚太经合组织、中国－东盟、澜湄合作等多边机制内的协调和配合。妥善处理泰柬边境争端符合泰柬两国人民共同和长远利益，希望双方坚持对话协商，和平解决争端，中方愿继续为此发挥建设性作用。\n阿努廷表示，很高兴作为总理首次对中国进行正式访问，热烈祝贺中国共产党成立105周年。中国一直是泰国得以依靠、信赖的好朋友，两国始终相互尊重、相互信任、相互支持，泰方坚定奉行一个中国政策。泰方致力于深化对华关系，密切高层交往，拓展贸易、投资、高新技术、互联互通等多领域务实合作，共同打击网赌电诈，开展人工智能全球治理合作，让泰中全面战略合作伙伴关系更好造福两国人民。习近平主席提出四大全球倡议，彰显对多边主义的承诺，泰方积极支持。泰方愿同中方加强协调和配合，促进地区和世界的和平稳定和发展繁荣。泰方致力于和平解决泰柬冲突，赞赏中方为此发挥公平公正作用。\n蔡奇、丁薛祥、王毅、陈吉宁等参加会见。"}, {"title": "习近平会见联合国秘书长", "detail": "7月17日下午，国家主席习近平在上海西郊宾馆会见来华出席2026世界人工智能大会暨人工智能全球治理高级别会议的联合国秘书长古特雷斯。\n习近平指出，古特雷斯先生担任联合国秘书长10年来，领导联合国坚定捍卫多边主义、积极应对气候变化等全球性挑战、推动人工智能等新兴领域全球治理、开启联合国改革进程，中方予以高度评价。今年是新中国恢复联合国合法席位55周年。55年来，中国坚持做世界和平的建设者、全球发展的贡献者、国际秩序的维护者，始终坚定支持联合国。我提出构建人类命运共同体理念和四大全球倡议，一个重要考虑就是维护联合国地位和权威。中方将一如既往同联合国深化合作，促进世界和平与发展事业，推动构建人类命运共同体。\n习近平强调，当前，国际形势变和乱的一面更加突出，需要进一步践行真正的多边主义、重振联合国地位和作用。一是坚持公道正义。每个国家都是国际社会平等一员，每个国家的主权、领土完整和合法权益都应该得到尊重，决不能让世界重回丛林法则时代。二是坚持守正创新。守正就是要遵守联合国宪章宗旨，维护好第二次世界大战结束后确立的国际体系和国际规则；创新就是要推动联合国因时而变，勇于自我革新，进一步提质增效。三是坚持担当作为。全球190多个国家乘坐在一条命运与共的大船上，应该同舟共济、携手应对全球性挑战。大国应该承担更多责任，展现更大格局。中国始终以实际行动积极推动探索新时代大国正确相处之道，为世界注入更多稳定性和确定性。\n古特雷斯表示，在习近平主席坚强领导下，无论国际形势多么困难复杂，中国始终坚定支持多边主义、支持联合国事业、推动国际合作，为世界树立了榜样。中国一直致力于纠正发展不平衡、应对气候变化、推动智能向善、弥合发展鸿沟、维护公道正义，提出一系列重大理念和倡议，令人钦佩。联合国将继续加强同中方的合作，反对单边主义、保护主义和霸道霸凌，维护联合国宪章和国际法，推动世界多极化进程，维护国际社会共同利益。\n蔡奇、丁薛祥、王毅、陈吉宁等参加会见。"}, {"title": "习近平对重庆彭水县山体崩塌作出重要指示强调 科学组织搜救 加强监测预警和巡查排险", "detail": "切实保障人民群众生命财产安全 李强作出批示\n7月17日9时10分许，重庆彭水县汉葭街道发生一起山体崩塌，造成多人被埋失联。\n灾害发生后，中共中央总书记、国家主席、中央军委主席习近平高度重视并作出重要指示指出，重庆彭水县发生山体崩塌造成多人失联，要科学组织搜救，防止发生次生灾害，妥善做好伤员救治、善后处置等工作。要查明原因，举一反三，深入排查消除地质灾害等隐患。\n习近平强调，各地区各有关部门要进一步落实安全工作责任，加强监测预警和巡查排险，抓实抓细各项工作，切实保障人民群众生命财产安全。\n中共中央政治局常委、国务院总理李强作出批示指出，要指导帮助重庆市全力开展救援处置、伤员救治、受灾群众安置等工作，并严防次生灾害。要进一步压实各地各有关方面责任，全面排查风险隐患，扎实做好灾害防范应对。\n根据习近平重要指示和李强要求，中共中央政治局委员、国务院副总理张国清率有关部门负责同志赶赴现场指导救援处置工作。重庆已组织力量全力做好现场搜救、伤员救治和善后处置等工作。目前，有关工作正在进行中。"}, {"title": "习近平对基础教育工作作出重要指示强调 全面贯彻党的教育方针落实立德树人根本任务", "detail": "不断开创基础教育高质量发展新局面 丁薛祥出席全国基础教育工作会议并讲话\n中共中央总书记、国家主席、中央军委主席习近平近日对基础教育工作作出重要指示指出，党的十八大以来，党中央把基础教育作为基础性、先导性工作来抓，多措并举推动基础教育实现长足发展，为建设教育强国提供了有力支撑。\n习近平强调，新征程上，要以新时代中国特色社会主义思想为指导，全面贯彻党的教育方针，落实立德树人根本任务，坚持不懈用党的创新理论铸魂育人，培养德智体美劳全面发展的社会主义建设者和接班人。要遵循教育规律，落实健康第一教育理念，提升教育教学质量，促进广大学生身心健康、成长成才。要适应人民群众新期盼，推进基础教育扩优提质，牢牢守住教育公平底线。要弘扬教育家精神，加强师德师风建设，培养造就高素质专业化教师队伍。各级党委和政府要切实扛起政治责任，优化办学资源配置，深化教育综合改革，推动学校、家庭、社会同向发力，不断开创基础教育高质量发展新局面。\n全国基础教育工作会议7月22日在京召开。会上传达了习近平重要指示。中共中央政治局常委、国务院副总理丁薛祥出席会议并讲话。\n丁薛祥在讲话中指出，习近平总书记的重要指示具有很强的政治性、思想性、指导性，为做好新时代新征程基础教育工作指明了方向。我们要深入学习领会，抓好贯彻落实。\n丁薛祥强调，新时代基础教育事业取得历史性成就、发生格局性变化，要从中深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”。要以习近平新时代中国特色社会主义思想为指导，深刻把握教育的政治属性、人民属性、战略属性，适应经济社会发展新形势和人民群众新期盼，深入推进基础教育高质量发展。\n丁薛祥指出，要全面贯彻党的教育方针，坚持不懈用党的创新理论铸魂育人，坚持五育并举、五育融合，促进学生健康成长、全面发展。要严格招生入学管理，加强对农村留守儿童、进城务工人员子女的关心关爱，牢牢守住教育公平底线，推进基础教育均衡发展。要适应人口变化优化教育资源配置，统筹做好经费保障、学校布局、学位供给、师资调配等工作。要以学生成长为中心深化教育教学改革，守正创新塑造基础教育新优势。要进一步强化协同共育，压实各方责任，充分发挥学校、家庭、社会作用，形成育人合力。要弘扬教育家精神，提升教师专业素养，加强教师待遇保障，吸引更多优秀人才安心从教。各地区各有关部门和学校要强化组织保障，以钉钉子精神推动党中央和国务院相关决策部署落地见效。"}, {"title": "就当前经济形势和下半年经济工作 中共中央召开党外人士座谈会 习近平主持并发表重要", "detail": "讲话\n7月24日，中共中央在中南海召开党外人士座谈会，就当前经济形势和下半年经济工作听取各民主党派中央、全国工商联负责人和无党派人士代表的意见建议。中共中央总书记习近平主持座谈会并发表重要讲话强调，做好下半年经济工作，要坚持稳中求进工作总基调，完整准确全面贯彻新发展理念，加快构建新发展格局，更好统筹国内国际两个大局，统筹发展和安全，坚持深化改革开放，加快推动新旧动能转换，实施好更加积极的财政政策和适度宽松的货币政策，充分发挥各项存量政策效能，及时谋划出台务实管用的增量政策，加大逆周期调节力度，加力扩大内需、优化供给，切实保障和改善民生，增强发展动力、激发社会活力，推动经济持续向新向优向好发展，努力实现“十五五”良好开局。\n中共中央政治局常委李强、王沪宁、蔡奇、丁薛祥出席座谈会。李强受中共中央委托通报了上半年经济工作有关情况，介绍了关于下半年经济工作有关考虑。\n座谈会上，民革中央主席郑建邦、民盟中央主席丁仲礼、民建中央主席郝明金、民进中央主席蔡达峰、农工党中央主席何维、致公党中央主席蒋作君、九三学社中央主席武维华、台盟中央主席苏辉、全国工商联主席高云龙、无党派人士代表邵峰先后发言。大家完全赞同中共中央对当前经济形势的分析判断和下半年经济工作的考虑，并就培育壮大新动能、促进创新链与产业链融合发展、健全智能经济产业应用标准制度体系、统筹发挥经济社会文化建设合力、稳住重点群体就业、加强基础研究、精准落实扩大消费规划、进一步扩大有效投资、持续推进高水平对外开放、加大逆周期政策力度等提出意见建议。\n在认真听取大家发言后，习近平发表重要讲话。他指出，今年上半年，在中共中央坚强领导下，各地区各部门靠前发力、主动作为，有效应对内外风险挑战，我国经济顶压前行、向新向优，展现出强大韧性和活力。\n习近平强调，当前我国经济运行也面临一些困难挑战，要坚定信心、攻坚克难，推动高质量发展行稳致远。下半年，要增强宏观政策效能，重点做好挖掘内需潜力、推动科技创新和产业创新深度融合、全面深化改革、扩大高水平对外开放、有力有效保障和改善民生、持续化解重点领域风险等工作。\n习近平指出，上半年，各民主党派中央、全国工商联和无党派人士坚决贯彻中共中央决策部署，主动服务国家大局，聚焦经济社会发展中的一些重点问题建言献策，为党和政府科学决策提供了重要参考。他代表中共中央向大家表示衷心感谢。\n习近平对各民主党派、全国工商联和无党派人士提出3点希望。一是把思想和行动统一到中共中央关于当前经济形势的分析判断和对经济工作的决策部署上来，坚定发展信心，共同推动实现全年经济社会发展目标任务。二是积极履职尽责，在深入调研基础上提出有针对性的建议，为促进经济稳中向好贡献智慧力量。三是持续加强对广大成员和所联系群众的思想政治引领，引导大家学习领会党的创新理论，不断增进对中国共产党领导和中国特色社会主义的政治认同、思想认同、理论认同、情感认同，为推动高质量发展营造良好氛围。\n刘国中、李干杰、何立峰、张国清、吴政隆，中共中央、国务院有关部门负责人出席座谈会。\n出席座谈会的党外人士还有邵鸿、何报翔、王光谦、秦博勇、朱永新、杨震和张恩迪、方光华、张斌等。"}, {"title": "习近平同巴西总统通电话", "detail": "7月27日上午，国家主席习近平应约同巴西总统卢拉通电话。\n习近平指出，近年来，中巴命运共同体建设和两国发展战略对接取得积极进展，为促进中巴两国发展和两国人民福祉发挥重要作用，也为动荡的国际局势注入宝贵的稳定性。今年是中国共产党成立105周年和中国“十五五”开局之年，巴西也将迎来重要国内政治议程。中方愿同巴方进一步加强双边和多边战略协作，延续两国命运共同体建设的良好态势。\n习近平强调，面对新形势、新挑战，中国和巴西作为全球南方重要成员，应当坚定站在历史正确和文明进步一边，为改革完善全球治理体系、捍卫国际公平正义发挥更大建设性作用。双方要携手推动“大金砖合作”高质量发展，把准合作方向，维护团结势头，打造更多成果，谱写全球南方团结自强新篇章。中方高度重视巴方的国际地位和重要影响力，支持巴西维护自身主权独立，反对外来干涉，并为维护地区和世界和平稳定作出巴方的贡献。\n卢拉表示，巴中构建更公正世界和更可持续星球的命运共同体取得积极进展，各领域合作发展迅速，两国贸易额再创新高，“巴中文化年”各项活动进一步夯实两国友好民意基础。巴方期待同中方加强人工智能、能源矿产等领域合作，欢迎更多中国企业赴巴投资，让两国合作更加多元、取得更多成果。巴方祝贺中国成功举办2026世界人工智能大会，高度赞赏习近平主席提出开放包容的人工智能国际合作和全球治理理念。巴方愿同中方密切多边协调，维护联合国权威，加强金砖团结合作，坚定捍卫多边主义，坚决反对强权政治，坚持通过对话协商解决热点问题，共同维护国际公平正义和世界和平稳定。"}, {"title": "习近平对侨务工作作出重要指示强调 更好凝聚侨心侨力 促进海内外中华儿女团结奋斗", "detail": "王沪宁出席全国侨务工作会议并讲话\n中共中央总书记、国家主席、中央军委主席习近平近日对侨务工作作出重要指示指出，党的十八大以来，侨务战线认真落实党中央决策部署，团结动员广大海外侨胞和归侨侨眷，在推动国家经济社会发展、传承弘扬中华文化、增进中外交流合作等方面作出了积极贡献。\n习近平强调，新征程上，要以新时代中国特色社会主义思想为指导，全面贯彻党的侨务政策，紧紧围绕党和国家工作大局，更好凝聚侨心侨力，引导广大海外侨胞和归侨侨眷秉承优良传统、厚植家国情怀，发挥独特优势、展现更大作为，积极服务祖国统一大业，促进海内外中华儿女团结奋斗，为以中国式现代化全面推进强国建设、民族复兴伟业汇聚磅礴力量。\n全国侨务工作会议7月27日至28日在京召开。会上传达了习近平重要指示。中共中央政治局常委、全国政协主席王沪宁出席会议并讲话。\n王沪宁在讲话中表示，习近平总书记高度重视侨务工作，近日专门作出重要指示，高度评价广大海外侨胞和归侨侨眷在推动国家经济社会发展、传承弘扬中华文化、增进中外交流合作等方面作出的积极贡献，对凝聚侨心侨力、促进海内外中华儿女团结奋斗提出任务要求，为做好新时代新征程侨务工作指明了方向、提供了重要遵循。我们要认真学习领会，抓好贯彻落实。\n王沪宁表示，侨务工作是党和国家的一项长期性战略性工作。新时代以来，侨务工作全面加强、成效显著，有力服务了党和国家事业发展。新征程上，要以习近平新时代中国特色社会主义思想为指导，深入贯彻落实习近平总书记关于做好新时代党的统一战线工作的重要思想、关于侨务工作的重要论述，贯彻落实党的二十大和二十届三中、四中全会关于加强和改进侨务工作的决策部署，坚持凝心聚力同圆共享中国梦的主题，坚持为大局服务和为侨服务相统一、国内侨务和国外侨务工作相协同、涵养资源和发挥作用相统筹，推动新时代侨务工作高质量发展。要更好把广大海外侨胞和归侨侨眷紧密团结起来，引导激励他们在支持和参与祖国现代化建设、弘扬中华文化、促进祖国统一、密切中外交流合作等方面发挥更大作用。\n中共中央政治局委员、中央统战部部长李干杰在总结讲话中表示，要深刻理解把握习近平总书记关于侨务工作重要论述和重要指示的重大意义、时代价值、核心要义、实践要求，坚持党的全面领导特别是党中央集中统一领导，不折不扣抓好党中央关于侨务工作决策部署的贯彻落实，进一步夯实团结奋斗根基，依法维护侨胞权益。要牢固树立和践行正确政绩观，凝心聚力、接续奋斗，广泛汇聚各方力量，同心协力做好新时代侨务工作。"}, {"title": "习近平同斯洛伐克总统会谈", "detail": "7月28日上午，国家主席习近平在北京人民大会堂同来华进行国事访问的斯洛伐克总统佩列格里尼举行会谈。\n习近平指出，斯洛伐克是最早同新中国建交的国家之一，中斯友谊之树根深叶茂。2024年两国关系提升为战略伙伴关系。在双方共同努力下，两国互信持续深化，合作成果不断涌现，传统友好深入人心。中方愿同斯方一道，打造互尊互信、平等互利、稳定坚韧的中斯战略伙伴关系，更好造福两国人民。\n习近平强调，下阶段双方可以重点做好4方面工作。一是巩固战略互信，坚定相互支持。尽管中斯两国政治体制不同，但双方能够尊重各自选择的发展道路，坚持友好合作的双边关系主旋律，这是中斯关系健康快速发展的基础。中方赞赏斯方恪守一个中国原则，愿继续同斯方充分照顾彼此核心利益和重大关切。二是深化互利合作，促进共同发展。斯洛伐克积极参与共建“一带一路”和中国—中东欧国家合作，取得丰硕成果。双方要进一步用好两国政府间合作委员会等机制，为深化两国合作提供政策支持，挖掘清洁能源、数字经济、机器人制造、人工智能等新兴产业和前沿领域合作潜力，打造更多合作新亮点。三是增进民心相通，赓续传统友谊。拓展文化、体育、旅游、青年、地方等领域合作，便利人员往来，继续鼓励两国青年开展交流，在互学互鉴中增进了解、收获友谊。四是捍卫国际公平正义，改革完善全球治理。加强多边协调，坚定维护以联合国为核心的国际体系和以国际法为基础的国际秩序，携手推进平等有序的世界多极化、普惠包容的经济全球化，推动构建人类命运共同体。\n习近平指出，世界百年变局加速演进，中欧关系既面临新的重要机遇，也有不少挑战，能不能化挑战为机遇，关键是要平等协商、聚同化异。中方始终视欧盟为伙伴，秉持诚意和善意发展对欧关系。希望斯方为推动欧盟聚焦中欧共识、妥处矛盾分歧，推动中欧关系健康稳定发展发挥建设性作用。\n佩列格里尼表示，斯方高度评价中国在习近平主席领导下取得举世瞩目的发展成就，中方制定并接续实施五年规划，稳扎稳打推进中国式现代化建设的能力令人钦佩，值得借鉴。斯方珍视两国战略伙伴关系，坚定奉行一个中国原则，期待同中方增进互信、加强合作、深化友谊，拓展合作新领域，在经贸、人工智能、数字经济、机器人、新能源等领域取得更多合作成果，更好造福两国人民。欢迎中国企业赴斯投资合作。作为欧盟成员国，斯方愿积极推动欧中合作，通过对话协商妥处分歧。斯方高度重视和赞赏中国的国际地位和影响，愿同中方坚持多边主义，维护联合国宪章宗旨和国际法，促进地区和世界和平稳定。斯方完全赞同习近平主席在2026世界人工智能大会上提出的理念和倡议，愿同中方密切协调，加强人工智能全球治理，使之真正造福全人类。\n会谈前，习近平在人民大会堂北大厅为佩列格里尼举行欢迎仪式。\n佩列格里尼抵达时，礼兵列队致敬。两国元首登上检阅台，军乐团奏中斯两国国歌，天安门广场鸣放礼炮21响。佩列格里尼在习近平陪同下检阅中国人民解放军仪仗队，并观看分列式。\n当天中午，习近平在人民大会堂金色大厅为佩列格里尼举行欢迎宴会。\n王毅参加上述活动。"}, {"title": "习近平致电祝贺诺瓦当选连任圣多美和普林西比总统", "detail": "7月29日，国家主席习近平致电卡洛斯·诺瓦，祝贺他当选连任圣多美和普林西比民主共和国总统。\n习近平指出，近年来，中圣普关系发展势头良好，双方政治互信持续深化，在涉及彼此核心利益和重大关切问题上坚定相互支持，各领域务实合作成果显著。我高度重视中圣普关系发展，愿同诺瓦总统一道努力，以落实中非合作论坛北京峰会成果为契机，推动中圣普战略伙伴关系不断迈上新台阶，更好造福两国人民。"}, {"title": "中共中央政治局召开会议 决定召开二十届五中全会 分析研究当前经济形势和经济工作", "detail": "中共中央总书记习近平主持会议\n中共中央政治局7月30日召开会议，决定今年10月在北京召开中国共产党第二十届中央委员会第五次全体会议，主要议程是，中共中央政治局向中央委员会报告工作，研究持之以恒推进全面从严治党若干重大问题。会议分析研究当前经济形势，部署下半年经济工作。中共中央总书记习近平主持会议。\n会议指出，党的十八大以来，全面从严治党取得伟大成就，开辟了百年大党自我革命新境界，推动党和国家事业取得历史性成就、发生历史性变革，党和人民赢得强党强国的历史主动。同时，随着世情国情党情发生深刻变化，全面从严治党也面临许多新情况新问题。全党必须从巩固党的执政地位、实现党的使命任务的战略高度，深刻认识持之以恒推进全面从严治党的重大意义，坚定信心，保持定力，以更高标准、更实举措把新时代全面从严治党宝贵经验坚持好、运用好，把党的建设面临的突出问题整治好、解决好，把管党治党形成的良好政治局面巩固好、发展好。\n会议强调，持之以恒推进全面从严治党要坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思想，深入学习贯彻习近平党建思想，落实新时代党的建设总要求，以党章为根本，坚持和加强党中央集中统一领导，着眼于提高党的长期执政能力、保持党的先进性和纯洁性、保持党同人民群众的血肉联系，坚持严的基调不动摇，健全全面从严治党体系，以党的政治建设为统领，全面推进党的各方面建设，充分激发全党积极性主动性创造性，不断实现党的自我净化、自我完善、自我革新、自我提高，确保党始终成为走在时代前列、人民衷心拥护、经得起各种风浪考验、朝气蓬勃的马克思主义执政党，始终成为中国特色社会主义事业的坚强领导核心。\n会议认为，今年以来，以习近平同志为核心的党中央团结带领全党全国各族人民锐意进取、奋勇拼搏，坚持统筹国内国际两个大局，统筹发展和安全，有效应对各种外部冲击和内部困难，我国经济呈现动能向新、结构向优的发展态势。同时，要高度重视经济运行中的困难挑战，坚定信心，迎难而上，用好各种机遇和优势，推动高质量发展行稳致远。\n会议强调，做好下半年经济工作，要坚持以习近平新时代中国特色社会主义思想为指导，坚持稳中求进工作总基调，完整准确全面贯彻新发展理念，加快构建新发展格局，更好统筹国内国际两个大局，统筹发展和安全，坚持深化改革开放，加快推动新旧动能转换，实施好更加积极的财政政策和适度宽松的货币政策，充分发挥各项存量政策效能，及时谋划出台务实管用的增量政策，加大逆周期调节力度，加力扩大内需、优化供给，切实保障和改善民生，增强发展动力、激发社会活力，推动经济持续向新向优向好发展，努力实现“十五五”良好开局。\n会议指出，宏观政策要发力提效，加快财政支出和债券资金使用进度，有力推进“两重”建设和“两新”工作。兜牢基层“三保”底线。综合运用并适时调整货币政策工具，优化实施财政金融协同促内需政策。\n会议强调，要有效扩大国内需求，适应不同群体消费需求扩大优质供给，挖掘服务消费潜力。扎实推进“六张网”规划建设。加快现代化产业体系建设，加强对基础研究的长期稳定支持，深入实施“人工智能+”行动，发展智能经济新形态，完善人工智能治理体系。积极推动前沿技术突破和未来产业发展，着力打造新兴支柱产业，持续推动传统产业改造升级。\n会议强调，要营造公平有序的市场竞争环境，制定实施全国统一大市场建设条例，继续综合整治“内卷式”竞争，常态化解决企业账款拖欠问题。深化国资国企改革，优化民营经济发展环境，推动平台经济规范健康发展。\n会议指出，要拓展国际经贸互利合作空间，大力发展服务贸易，促进贸易平衡发展。完善对外投资管理制度和海外综合服务体系，积极吸引和利用外资。\n会议强调，要毫不放松做好“三农”工作，持续巩固拓展脱贫攻坚成果，建立健全高标准农田建设、运营、管护机制，稳定生猪等农畜产品生产和价格，促进农民稳定增收。做好农资保供稳价，抓好农业生产，夺取秋粮和全年粮食丰收。\n会议指出，要多措并举加强民生保障，加大重点群体就业支持力度，做好灵活就业人员和新就业形态人员权益保障工作。抓好“一老一小”服务保障，健全分层分类的社会救助体系。加强生态环境保护，打好“三北”工程攻坚战，积极稳妥推进碳达峰碳中和。\n会议强调，要切实筑牢安全屏障。稳定房地产市场，实施好一揽子化债方案，扎实推进地方中小金融机构改革化险、减量提质。深化资本市场投融资综合改革，提升资本市场韧性和信心。深入排查整治各类风险隐患，坚决遏制重特大事故发生。加强对病险水库、江河堤防、山洪和地质灾害危险区、城市低洼易涝点等隐患排查治理，扎实做好防汛应急抢险救灾各项工作，全力维护人民群众生命财产安全。\n会议指出，要巩固拓展树立和践行正确政绩观学习教育成果，推动各级领导干部以更加昂扬向上的精气神，不断创造高质量发展新业绩。\n会议还研究了其他事项。"}, {"title": "习近平在中共中央政治局第二十七次集体学习时强调 强化政治引领 深化创新发展 高质", "detail": "量推进国防和军队现代化\n中共中央政治局7月30日下午就高质量推进国防和军队现代化进行第二十七次集体学习。中共中央总书记习近平在主持学习时强调，“十五五”时期，要坚持以新时代中国特色社会主义思想为指导，深入贯彻新时代强军思想，强化政治引领，深化创新发展，高质量推进国防和军队现代化，如期实现建军一百年奋斗目标，推动基本实现国防和军队现代化取得决定性进展，为以中国式现代化全面推进强国建设、民族复兴伟业提供坚强战略支撑。\n这次中央政治局集体学习在八一建军节前夕举行。习近平代表党中央和中央军委，向全体人民解放军指战员、武警部队官兵、军队文职人员、预备役人员和民兵致以节日的祝贺！\n中央军委战略规划办公室孙正同志就高质量推进国防和军队现代化问题进行讲解，提出工作建议。中央政治局的同志认真听取讲解，并进行了讨论。\n习近平在听取讲解和讨论后发表重要讲话。他指出，高质量推进国防和军队现代化，是推进中国式现代化的应有之义。党的十八大以来，党中央统筹中华民族伟大复兴战略全局和世界百年未有之大变局，把强军兴军摆在党和国家事业的突出位置，毫不动摇坚持和加强党对军队的绝对领导，鲜明提出党在新时代的强军目标，谋划实施国防和军队现代化新“三步走”战略，全面推进政治建军、改革强军、科技强军、人才强军、依法治军，边斗争、边备战、边建设，我军现代化水平和实战能力显著提升，强军事业取得历史性成就、发生历史性变革。\n习近平强调，政治建军是人民军队立军之本，关乎国防和军队现代化建设方向和底色。要坚持和加强党对军队的绝对领导，全面落实新时代政治建军方略，加强理论武装，深化思想整风，打牢官兵听党话、跟党走的思想根基，确保枪杆子永远听党指挥。要深入推进反腐败斗争，健全重大项目监管体系，确保各项建设质量托底、能力托底、廉洁托底。\n习近平指出，高质量推进国防和军队现代化，根本指向和检验标准始终是战斗力。要加强无人智能技术军事应用，深化网络信息体系建设运用，逐步构建智能化军事体系。要加强作战能力体系集成，搞好实战化检验评估，扎实推进练兵备战，有效捍卫国家主权、安全、发展利益。\n习近平强调，巩固提高一体化国家战略体系和能力，是高质量推进国防和军队现代化的必由之路。要加强军事治理，结合落实跨军地改革任务，优化体制机制，完善政策制度，形成各司其职、紧密协作、规范有序的跨军地工作格局。中央和国家机关有关部门、地方党委和政府要大力支持国防和军队建设，在全社会营造关心国防、热爱国防、建设国防、保卫国防的浓厚氛围。"}, {"title": "中央军委主席习近平签署通令 给1名个人记功", "detail": "中央军委主席习近平日前签署通令，给中国人民解放军91548部队杨勇记国防科技一等功。"}, {"title": "李强总理系列讲话", "detail": ""}, {"title": "李强主持召开国务院党组会议 学习贯彻习近平总书记在庆祝中国共产党成立105周年大", "detail": "会上的重要讲话精神和习近平党建思想 丁薛祥出席\n7月1日，国务院总理、党组书记李强主持召开国务院党组会议，学习贯彻习近平总书记在庆祝中国共产党成立105周年大会上的重要讲话精神和习近平党建思想。\n会议指出，习近平总书记在庆祝大会上的重要讲话，对新征程上全体中国共产党人坚定信心、接续奋斗提出了明确要求，向全党发出了奋力创造新的历史辉煌的伟大号召。习近平党建思想是习近平新时代中国特色社会主义思想的重要组成部分，为发展马克思主义建党学说作出重大原创性贡献，对强党强国具有重大现实意义和长远指导意义。国务院党组和国务院各部门要把学习贯彻习近平总书记重要讲话精神同学习贯彻习近平党建思想结合起来，深入领会核心要义、丰富内涵和实践要求，全面贯彻到政府工作当中。\n会议强调，要始终坚持和加强党的领导，坚定拥护“两个确立”、坚决做到“两个维护”，以更高标准当好贯彻党中央决策部署的执行者、行动派、实干家。要自觉践行以人民为中心的发展思想，不断深化对党的性质宗旨、初心使命的认识与理解，走好新时代党的群众路线。要努力推动高质量发展取得新成效，真抓实干、担当作为，奋力跑好历史的接力棒，为强国建设、民族复兴作出更大贡献。要纵深推进全面从严治党，毫不松懈推进政府党风廉政建设和反腐败斗争，为做好经济社会发展工作提供坚强保障。"}, {"title": "李强会见纳米比亚总统", "detail": "7月9日下午，国务院总理李强在京会见来华进行国事访问的纳米比亚总统恩代特瓦。\n李强表示，纳米比亚是中国在非洲的重要伙伴。明天，习近平主席将同总统女士举行会谈，就进一步深化两国关系与合作作出新的战略规划。中方愿同纳方弘扬传统友谊，坚定相互支持，深化贸易、基建、矿业、油气、人文等领域合作，更好实现互利共赢。双方要加强在联合国等机制下的协调配合，推动各方一道践行真正的多边主义，积极落实四大全球倡议。\n恩代特瓦表示，纳方坚定恪守一个中国原则，期待同中方深化经贸、农业、矿业、基建等领域合作，密切人文交流，加强多边协作，推动纳中全面战略合作伙伴关系取得更多成果。"}, {"title": "李强主持召开国务院常务会议", "detail": "国务院总理李强7月10日主持召开国务院常务会议。\n会议进一步部署防汛抗洪救灾工作。会议强调，各地区各部门要深入贯彻习近平总书记重要指示要求和党中央决策部署，切实强化政治责任，始终绷紧防汛抗洪救灾这根弦，牢固树立底线思维、极限思维，坚决克服麻痹思想和侥幸心理，坚持问题导向，举一反三，加强防范，群策群力打赢防汛抗洪救灾这场硬仗。要坚决守牢安全防线，扎实做好风险隐患排查，加密薄弱堤段、超警河段等巡查防守，加强病险水库、中小水库监管，科学做好重大水利工程调度，确保大江大河大湖防洪安全。进一步提高监测预报精准度，及时预警“叫应”，特别要紧盯高风险区域、重点部位、脆弱人群，遇到险情果断组织人员转移，最大限度减少人员伤亡。要加强协同形成合力，国家防总要强化统筹协调和指挥调度，各相关部门要主动靠前、密切配合，各级政府要加强应急值守，做好力量、装备、物资准备，快速高效开展抢险救援、生活救助等工作，全力以赴维护人民群众生命财产安全。\n会议听取数字中国建设情况汇报。会议指出，要系统推进数字中国建设，加快新一代通信网、算力网建设，全面赋能经济社会发展。要加强前沿科技攻关，增强对新型安全风险的评估和防控能力。\n会议听取现代流通体系建设进展情况汇报。会议指出，要补齐流通基础设施短板弱项，大力发展多式联运，进一步降低流通成本。要提升流通治理能力和水平，发展新业态新模式新场景。\n会议研究新兴支柱产业培育有关工作。会议指出，要全链条推动新兴支柱产业规模化发展，加强基础研究和关键软硬件攻关，加速技术迭代和生态完善。要优化监管模式，引导各地因地制宜、错位发展。\n会议研究自然资源保护利用有关工作。会议指出，要强化主体功能区战略实施，优化国土空间发展格局，依托都市圈、城市群打造高质量发展动力源。要增强国土空间安全韧性，提升自然灾害防灾减灾能力。\n会议审议通过《全民健身计划（2026—2030年）》。会议指出，要多渠道增加全民健身场地设施，优化健身普及方式，创新发展健康产业，更好守护人民群众全生命周期健康。"}, {"title": "李强同朝鲜内阁总理会谈", "detail": "7月11日上午，中共中央政治局常委、国务院总理李强在北京人民大会堂同来华进行正式访问的朝鲜劳动党中央政治局常委、国务委员会副委员长、内阁总理朴泰成举行会谈。\n李强表示，中朝是命运与共、守望相助的友邻。上月初，习近平总书记对朝鲜进行国事访问，同金正恩总书记就深化中朝关系达成一系列重要共识，共同作出战略指引。维护好、巩固好、发展好中朝关系，始终是中国党和政府坚定不移的方针。中方愿同朝方落实好两党两国最高领导人重要共识，继续秉持《中朝友好合作互助条约》精神，密切高层交往，巩固政治互信，拓展务实合作，更好造福两国人民，为地区乃至世界的和平发展作出积极贡献。\n李强指出，中方愿同朝方对接发展战略，稳步扩大经贸往来，促进互联互通，深化医疗卫生、教育等民生领域合作，增进两国民众福祉。双方要赓续弘扬传统友谊，加强人文交流，进一步拉紧民心相通纽带。当前国际形势正经历深刻复杂变化，中朝同为社会主义国家，应当加强战略协调与配合，携手捍卫自身正当权益和国际公平正义。\n朴泰成表示，金正恩总书记和习近平总书记不久前在平壤举行历史性会晤，充分彰显朝中两党两国团结友好牢不可破，为双边关系发展提供了战略引领。朝方坚定支持中方维护核心利益，愿同中方遵循两党两国最高领导人重要共识，以隆重庆祝《朝中友好合作互助条约》签订65周年为契机，密切高层交往和战略沟通，拓展经贸、科技、人文等领域交流合作，加强国际协作，共同促进社会主义事业发展，谱写朝中关系新篇章。"}, {"title": "李强主持召开经济形势专家和企业家座谈会", "detail": "中共中央政治局常委、国务院总理李强7月13日下午主持召开经济形势专家和企业家座谈会，听取对当前经济形势和下一步经济工作的意见建议。\n座谈会上，黄汉权、杨志勇、王文、章俊、侯启军、于东来、王志坚、历军等先后发言。大家认为，在国际形势变乱交织的背景下，上半年我国经济总体平稳，以自身发展的确定性有力应对外部环境的不确定性。大家还就解决经济运行中的矛盾和问题提出意见建议。\n在听取专家和企业家发言后，李强说，今年以来，在以习近平同志为核心的党中央坚强领导下，各地区各部门认真落实国家宏观政策，努力促进经济持续向好。要全面客观认识当前经济形势，既充分肯定成绩，又清醒看到问题，对经济运行中的新变化新动向，要善于研机析理，更好地趋利避害。要注重从整体上把握形势，特别是要看到我国经济正全面转入高质量发展轨道，长期向好的内在支撑更加坚实。\n李强强调，做好下半年经济工作，直接关系全年发展目标实现，关系“十五五”良好开局。要按照党中央决策部署，保持高质量发展战略定力，加大逆周期调节力度，系统施策释放内需潜力，推进新旧动能平稳接续转换，深入做好稳就业稳企业工作，切实巩固拓展经济稳中向好态势。\n李强希望广大企业家坚定发展信心，深入挖掘需求升级和产业升级机遇，为稳就业促发展多作贡献。希望专家学者加强前瞻性研究，多提建设性意见。\n吴政隆参加座谈会。"}, {"title": "李强同柬埔寨首相会谈", "detail": "7月16日上午，国务院总理李强在北京人民大会堂同来华出席2026世界人工智能大会并进行工作访问的柬埔寨首相洪玛奈举行会谈。\n李强表示，中柬是共同发展的好伙伴，有着牢不可破的铁杆友谊。习近平主席不久前同来华访问的洪森主席举行会晤，达成一系列重要共识，此次将同首相先生会见，进一步加强战略沟通。中方始终把对柬关系置于周边外交优先位置，愿同柬方坚定相互支持、紧密团结协作，推动新时代全天候中柬命运共同体建设取得更多成果。\n李强指出，中方愿同柬方推动“钻石六边”合作、“工业发展走廊”和“鱼米走廊”建设等走深走实，深化基础设施、贸易、新能源、人工智能、数字经济等领域合作。中方支持更多有实力的中国企业赴柬投资。双方要加强教育、文化、媒体等人文合作，增进国民相知相亲，同时协力铲除网赌电诈犯罪滋生土壤，更好保障两国民众安全。今年以来，国际形势动荡不安，对世界经济造成较大冲击。中柬应当加强立场协调，捍卫两国共同利益，携手维护多边贸易体制和国际公平正义。\n洪玛奈表示，柬中传统友谊深厚，中国是柬埔寨最信赖的全面战略伙伴和铁杆朋友，柬方坚定不移恪守一个中国原则，愿同中方密切高层往来，促进贸易、投资、基建、新能源、互联互通、人文等领域交流合作，加强打击网赌电诈安全执法合作，深化多边协作，推动两国新时代全天候命运共同体建设取得更多实质成果。\n吴政隆参加会谈。"}, {"title": "李强同泰国总理会谈", "detail": "7月20日上午，国务院总理李强在北京人民大会堂举行仪式，欢迎泰国总理阿努廷对我国进行正式访问。\n欢迎仪式后，李强同阿努廷举行会谈。\n李强表示，在两国领导人战略引领下，中泰命运共同体建设正不断走深走实，为双方合作开辟更加广阔前景。总理先生这次访华期间，习近平主席同你举行会晤，就深化发展两国关系作出新的规划。中方始终把泰国置于周边外交重要位置，愿同泰方弘扬传统友谊，巩固政治互信，坚定相互支持，推动各领域互利合作迈向更高水平，持续提升两国人民福祉。\n李强指出，中方愿同泰方加强发展战略对接，推动高质量共建“一带一路”，加快实施中泰铁路等重点项目，提升跨境支付、本币结算等便利化水平，保持双边贸易良好增长势头，深化产业互融互嵌，拓展人工智能、新能源汽车等新兴领域合作，携手促进共同繁荣。希望泰方为赴泰中国企业提供良好营商环境。双方还要深化人文交流，坚决打击网赌电诈等跨境犯罪。中方愿同泰方加强多边协调配合，共同维护两国正当权益和国际公平正义。\n阿努廷表示，泰方坚定奉行一个中国政策，愿同中方密切高层往来，促进经贸、农业、互联互通、人工智能、人文等领域合作，加强在东盟—中国等多边框架内沟通协作，推动泰中全面战略合作伙伴关系取得更多务实成果，共促地区与世界和平、稳定、繁荣。\n会谈后，两国总理共同见证签署贸易、农业、海关、打击跨国犯罪等领域多项合作文件。\n吴政隆参加上述活动。\n访问期间，双方共同发表《中华人民共和国政府和泰王国政府关于面向繁荣中泰命运共同体的联合声明》。"}, {"title": "李强主持召开国务院常务会议", "detail": "国务院总理李强7月20日主持召开国务院常务会议，听取对服务业扩能提质和水网、新型电网、算力网、新一代通信网、城市地下管网、物流网等“六张网”规划建设督查情况汇报，审议通过《知识产权保护和运用“十五五”规划》，研究优化社会保障体系有关工作，听取2025年度中央预算执行和其他财政收支审计查出问题整改工作建议汇报。\n会议指出，要充分释放服务业发展潜力，分门别类完善支持政策，加快破除各种制约和障碍。生产性服务业要加力支持科技创新和价值创造，进一步发挥对实体经济的支撑作用，生活性服务业要着力扩大优质供给，更好满足人民群众多样化多层次需求。要系统推进“六张网”规划建设，因地因业加快实施，加强资金要素保障，切实把重大基础设施网络建设好。同时统筹好建和用的关系，更加重视管理机制等“软建设”，增强运营服务能力。\n会议指出，要抓紧补齐制度短板，加快推动相关法律法规立改废释，完善配套政策措施，持续优化支持全面创新的知识产权保护环境。要强化知识产权高质量供给，深化权益分配改革，加强政策支持和市场服务，提升转化运用效能。要建立全链条人才培养体系，加快建设高层次、复合型、应用型人才队伍，全面提升知识产权管理服务水平。\n会议指出，要提高社会保障体系的整体性协同性，优化相关制度安排，高效配置各种资源，增强社保制度可持续发展能力。要深化政策机制创新，丰富多层次社保体系，积极探索灵活就业人员社保新模式，优化农民工等群体住房保障措施，推进失能照护等服务资源共享，增强社保体系适应性。要完善社保平台功能，加强精细化管理，积极运用先进技术提高社保经办服务便利度。\n会议指出，要全面抓好审计整改工作，对审计查出问题高度重视、严肃对待，逐项分解任务、压紧压实责任，举一反三务求整改实效。要进一步强化预算管理，深化财税体制改革，切实发挥好财政资金的使用效益。要把审计整改作为改进工作的有力抓手，推动党中央决策部署和政策措施更好落地见效，扎实做好下半年各项工作，确保完成全年经济社会发展目标任务。"}, {"title": "李强致电祝贺伯纳姆就任英国首相", "detail": "7月20日，国务院总理李强致电安迪·伯纳姆，祝贺他就任英国首相。\n李强表示，中英同为联合国安理会常任理事国和世界主要经济体，加强对话合作不仅有利于促进两国各自发展，也将为全球和平注入稳定性。我愿同首相先生一道努力，加强交往，增进互信，促进交流合作，推动中英长期稳定的全面战略伙伴关系不断向前发展，更好造福两国和两国人民。"}, {"title": "李强在河北唐山调研慰问", "detail": "受习近平总书记委托，在唐山抗震救灾和新唐山建设50年之际，中共中央政治局常委、国务院总理李强7月28日到河北省唐山市调研慰问。他强调，要深入贯彻落实习近平总书记关于做好防灾减灾救灾工作和弘扬伟大抗震救灾精神的重要指示，坚持人民至上、生命至上，树牢底线思维、极限思维，不断完善监测预警、应急处置、抢险救援、灾后重建等机制，持续提升防灾减灾救灾能力，切实保障人民群众生命财产安全。\n李强首先来到唐山地震遗址纪念公园，以党中央、国务院名义向唐山大地震罹难同胞和在抗震救灾中捐躯的英雄敬献花篮，并向纪念墙三鞠躬。李强说，50年前那场灾难令人难以忘记，当年可歌可泣的抗震救灾情景感人至深。半个世纪以来，唐山人民在一片废墟上重建了一座现代化新兴城市，这是我们党领导人民战胜各种困难挑战的生动典范。踏上新的征程，我们要牢记习近平总书记的殷切嘱托，传承弘扬在抗击灾害、重建家园中凝聚的强大精神力量，扎实做好经济发展、民生保障等各项工作，把这座英雄的城市建设得更加美好。\n在唐山市截瘫疗养院，李强听取疗养院近年发展情况汇报，看望慰问地震截瘫伤员，并与他们亲切交流。他说，习近平总书记十分牵挂大家，一直惦念大家的身体、生活状况，这次专门委托我来看望大家。今天看到大家的状态很好，我感到非常欣慰，大家身上展现出的坚强不屈精神和积极乐观生活态度更是值得敬佩，祝愿大家健康幸福、越来越好！李强叮嘱有关方面持续完善医疗康复、日常照料等服务，加强科技创新应用，不断提高助残保障水平。李强感谢医护人员的辛勤付出，勉励他们以专业细致的服务为伤残人员带来更多温暖。\n李强来到安能集团第一工程局唐山分公司有关救援基地，了解基地承担救援任务等情况，察看各类装备，与救援人员交流。李强指出，要时刻绷紧应急救援这根弦，常态化开展实战训练，全面提升快速响应、科学施救能力。要强化应急领域装备技术支撑，提高救援精准度和安全性。李强强调，当前正处在“七下八上”防汛关键期，要全面压实责任，在灾害来临时第一时间响应、科学有序应对。"}, {"title": "李强会见斯洛伐克总统", "detail": "国务院总理李强29日下午在京会见来华进行国事访问的斯洛伐克总统佩列格里尼。\n李强表示，中斯建交以来，始终相互尊重、平等相待，两国友谊历久弥坚。昨天，习近平主席同总统先生举行会晤，进一步规划双边关系发展。中方愿同斯方一道弘扬传统友谊，巩固战略互信，推动高质量共建“一带一路”，深化互联互通、新能源汽车、人文等领域合作，共促两国发展繁荣。希望斯方推动欧盟对华政策朝着更加积极、理性的方向调整，促进中欧经贸关系稳健发展。\n佩列格里尼表示，斯中关系当前处于历史最好时期。斯方愿同中方加强往来，拓展经贸、人文等领域交流合作。斯方愿为推动欧中对话与合作发挥积极作用。"}, {"title": "李强主持召开国务院常务会议", "detail": "国务院总理李强7月31日主持召开国务院常务会议，学习贯彻习近平总书记关于上半年经济形势和做好下半年经济工作的重要讲话精神。\n会议强调，要把思想和认识统一到党中央关于经济形势的科学判断上来，以更实举措推动经济持续向新向优向好发展，努力实现“十五五”良好开局。要切实提升宏观政策实施效能，用好用足各项存量政策，及时谋划出台务实管用的增量政策。要有效扩大国内需求，抓住潜力大、带动强的领域推出一批有力举措，加快实施“十五五”规划确定的重大项目，扎实推进“六张网”规划建设。要不断增强发展内生动力，在统一大市场建设、优化营商环境等方面拿出更多实招硬招。要持续用力防范化解重点领域风险，扎实做好防灾减灾救灾、安全生产等工作，加强困难群众帮扶，兜牢民生底线。\n会议听取新型电网、物流网建设情况汇报。会议指出，要高质量建设新型电网，加强统筹协调和政策支持，狠抓工程质量和安全生产，确保电网建设顺利推进。要加快推进物流网建设，增强枢纽节点、骨干通道功能，完善城乡末端配送体系，推动跨区域跨方式物流规则标准衔接，着力补短板、畅联通、提能级。\n会议研究健康优先发展战略实施有关工作。会议指出，要牢固树立健康优先导向，健全公共卫生、医疗服务和医疗保障体系，推动医药科技创新，加快形成有利于健康的生产生活方式。要普及健康知识，提高全民健康素养，凝聚促进健康事业发展合力。\n会议审议通过《国务院关于修改〈住房公积金管理条例〉的决定（草案）》。会议指出，要更好发挥住房公积金功能作用，拓宽提取和使用范围，扩大制度覆盖面，更好满足居民多样化住房消费需求。\n会议审议通过《国务院关于修改和废止部分行政法规的决定（草案）》，决定对《全国污染源普查条例》等12部行政法规的部分条款予以修改，对《中华人民共和国防治陆源污染物污染损害海洋环境管理条例》等3部行政法规予以废止。\n会议决定核准辽宁庄河一期工程等四个核电项目。会议指出，要按照全球最高安全标准建设和运营核电机组，加强全链条全领域安全监管，务必确保核电安全万无一失。\n3.时事热点"}, {"title": "五大类重点液态食品散装运输明起须持准运证", "detail": "自7月1日起，我国对植物油、调味品等五大类重点液态食品散装运输，实施准运证管理，道路运输经营者须依法取得准运证方可上路。相关罐式容器须按要求喷涂食品专用标识，液态食品的交付、运输、装卸将实现全流程可追溯。"}, {"title": "我国首个流域型国家排放标准发布", "detail": "《丹江口库区及上游主要水污染物（总锑、总钼等）排放控制标准（试行）》日前发布，这是我国首个以国家标准形式出台的流域型排放标准。新标准通过收严城镇污水集中处理设施排放限值、补齐面源污染管控短板等，为南水北调中线工程水源安全提供制度保障。"}, {"title": "2026年大国工匠人才推选工作启动", "detail": "近日，全国总工会印发通知，启动2026年大国工匠人才推选，全国计划推选420人。本次推选面向数智化转型制造业、新兴产业及未来产业，重点从国家重大工程、链主企业、头部企业、专精特新“小巨人”企业遴选技能人才。"}, {"title": "中央档案馆向社会集中开放一批馆藏档案", "detail": "为庆祝中国共产党成立105周年，7月1日，中央档案馆向社会集中开放一批馆藏档案，共计4.4万余件。此次开放的档案时间跨度长，内容丰富，展现了105年来中国共产党始终践行初心使命、不懈拼搏奋斗的光辉历程、宝贵经验和精神风范。"}, {"title": "公平竞争审查制度实施十周年来 全国累计审查政策措施188万件", "detail": "市场监管总局7月3日公布，我国公平竞争审查制度实施十年来，全国累计审查政策措施188万件，废止和修订排除、限制竞争的政策措施12.3万件，有效破除地方保护、推动全国统一大市场建设。"}, {"title": "长三角发布首批重点产业国际标准联合攻关项目", "detail": "7月3日，长三角发布首批重点产业国际标准联合攻关项目清单，涵盖人工智能、新材料、新能源等8个项目。至2027年底，长三角计划牵头制定20项以上联合研制国际标准。"}, {"title": "全球数字经济首批灯塔案例在北京发布", "detail": "近日，国际电信联盟、国际贸易中心、全球数字经济城市联盟共同在北京发布首批13个全球数字经济灯塔案例，系统展示城市治理、公共服务等领域的数字化转型经验，包括北京智能政务协同办公平台在内的7个中国案例入选。"}, {"title": "中央宣传部新命名一批全国爱国主义教育示范基地", "detail": "在庆祝中国共产党成立105周年之际，中央宣传部新命名77个全国爱国主义教育示范基地。中央宣传部要求，加大对各类文物、遗址旧址等的保护力度。设计分众化、精准化的解说内容和参观线路，积极开展形式多样、富有教育意义的群众性活动，更好打造爱国主义教育的生动课堂。"}, {"title": "“习近平新时代中国特色社会主义思想与世界”国际研讨会在银川举行", "detail": "7月9日，“习近平新时代中国特色社会主义思想与世界”国际研讨会在宁夏银川举行。本次研讨会的主题为“迈向现代化之路：中国减贫理论和实践的启示”，50多个国家的120多名外国政党领导人、部分驻华使节、智库学者和媒体代表等与会。与会外宾热烈祝贺中国共产党成立105周年，表示中共十八大以来，在习近平总书记的坚强领导和习近平新时代中国特色社会主义思想指引下，中国取得彻底消除绝对贫困的历史性胜利，这是人类文明进程中里程碑式的成就。中国的实践证明，贫穷并非不可改变的宿命，中国为发展中国家提供了值得学习借鉴的丰富经验。"}, {"title": "2030年我国基本形成供给优质的现代零售体系", "detail": "商务部等9部门7月9日联合发布《关于加快零售业创新发展的意见》，围绕系统规划新布局、引领零售新供给、创造消费新需求等6大方向，出台20条具体举措。力争到2030年，我国基本形成布局合理、供给优质、业态多元、智慧便捷、竞争有序的现代零售体系。"}, {"title": "我国城乡三级养老服务网络2029年基本建成", "detail": "民政部日前发布《城乡三级养老服务网络建设管理指引》，明确到2029年基本建成覆盖城乡的“县级—乡镇（街道）—村（社区）”三级养老服务网络，重点聚焦失能失智照护刚需，同时兼顾高龄、特殊困难老年人等多样化的养老服务需求，整合一张家门口的养老“服务网”。"}, {"title": "新版国家基本药物目录发布", "detail": "国家卫生健康委等部门7月9日正式发布了《国家基本药物目录（2026版）》，共收录药品794种。其中，新增化学药品和生物制品68种，中成药品种48种，儿童适宜品种31种。"}, {"title": "央企首批十大标志性开放场景公布", "detail": "7月9日，由国务院国资委牵头组织开展的中央企业“场景万象”专项行动在京启动，发布了首批央企十大标志性场景，涉及人工智能、算电碳协同等，将央企自身场景转化为产业创新的共享平台，让全社会共同参与，构建开放共赢的场景生态，让产业链之间共同发展。"}, {"title": "2026年中国航海日上海主题活动启动", "detail": "7月10日，2026年中国航海日上海主题活动启动。目前，上海全球航运城市竞争力在43座城市中跃居第二。"}, {"title": "七部门联合部署开展规范农药兽药综合整治行动", "detail": "农业农村部等七部门日前联合部署开展进一步规范农药兽药生产经营使用综合整治行动，通过明察暗访、线下线上排查等方式深挖问题线索，依法严打禁限用农药兽药非法生产经营使用行为。"}, {"title": "全国已建成高质量数据集12万个", "detail": "记者7月18日从国家数据局了解到，我国持续加大优质数据供给，截至今年6月底，已建成高质量数据集12万个，涵盖科研、工业等领域；总体量超1565拍字节，较一季度末增长超60%，现有体量相当于中国国家图书馆数字资源总量的547倍左右。"}, {"title": "我国部署七大行动促进海水淡化产业发展", "detail": "记者从国家发展改革委了解到，我国将部署实施七大行动，促进海水淡化产业发展。到2030年，全国海水淡化工程总规模提升至450万吨/日以上，城市应急供水保障能力进一步增强，沿海工业园区海水淡化水利用比例进一步提高。"}, {"title": "多项首发技术和创新成果亮相世界人工智能大会", "detail": "正在上海举行的2026世界人工智能大会上，多项重要举措和创新成果公布。同时，一批前沿技术集中首发，展现我国人工智能领域的最新突破。\n大会上，国家发展改革委会同中央广播电视总台等部门共同发布了两项成果。其中，《人工智能合作发展行动计划》提出优质数据供给、智能算力普惠、人工智能向善等8项行动。《中国智·惠世界（2026）》案例集收录了我国在人工智能领域开展国际合作的10个生动故事。此外，《国际人工智能伦理治理行动计划》《智能体互信互联互操作全球合作倡议》等创新成果也相继发布。\n7月18日，本届大会多项首发前沿技术集中亮相。这是一个设计蛋白质研发的智能体，过去设计一个性能优异的蛋白质得进行成千上万次试验。\n不仅有瞄准源头突破的原创科研成果，丰富的AI应用场景也不断涌现。\n今天，本届大会的多场分论坛陆续举行。论坛聚焦AI全球治理、具身智能、智能算力等热点，开展了一系列高端对话、成果发布等活动。首次创办的高水平国际学术会议——世界人工智能大会·学术，由图灵奖得主领衔，打造具有国际影响力的世界级AI学术主场。\n7月20日下午在上海落下帷幕，为期四天的大会取得丰硕成果。与会嘉宾表示，期待与中国深化合作，让科技更好赋能各国发展。\n本次大会共吸引了1568位国内外顶尖专家参加，展品总数4486项，展商数量与展览面积均较去年增长超三分之一。\n同时，大会期间还发布了一系列重磅成果：启动“一网通办·免申即享”创新型企业专项金融支持服务战略合作，设立1.18万亿元创新企业意向性信贷支持额度；聚焦智能体失控风险与应急管理等主题，发布了多份人工智能安全领域的重要报告和成果。\n此外，本届大会在活动数量与形式上全面升级。大会共组织近160场论坛，开展“图灵对话”“世界青年说”等特色活动。首次创设自主学术会议，举办系列品牌赛事，组织海内外180余个优秀初创项目集中开展路演和展示。"}, {"title": "水利部启动水文现代化建设三年行动", "detail": "为加快构建现代化雨水情监测预报预警体系、大力推进水文现代化建设，水利部近日印发《水文现代化建设三年行动方案（2026—2028年）》，启动水文现代化建设三年行动。\n记者了解到，方案从完善国家水文站网体系、加快雨水情监测预报“三道防线”建设应用、提升水资源监测分析评价能力、增强水文科技创新能力、深化水文行业管理等五方面明确了重点任务。方案提出，到2028年，推动国家水文站网体系进一步优化，雨水情监测立体感知能力进一步提升，“三道防线”耦合贯通范围进一步扩大至有防洪任务的主要江河流域，水资源水生态监测分析评价体系更加完善，水文新质生产力加速发展，水文行业管理能力明显提升。"}, {"title": "我国首次启动实施质量督察工作", "detail": "我国于近日首次启动实施质量督察工作，4个质量督察组将陆续进驻有关省份，对“内卷式”竞争突出领域、社会关切和群众反映强烈的重点领域存在的突出质量问题开展抽查核查，切实提升质量治理能力。"}, {"title": "我国将启动建设国家级零碳工厂", "detail": "业和信息化部日前印发通知，组织开展国家级零碳工厂（含零碳算力设施）建设工作。\n零碳工厂建设是指通过技术创新、结构调整和管理优化等减排措施，实现边界内二氧化碳排放的持续降低、逐步趋向于近零的过程。《通知》提出，选择具备一定建设基础、建设目标明确、实施路径清晰，并承诺在规定期限内完成建设目标的制造型企业、算力设施，择优纳入国家级零碳工厂建设名单。\n通知明确建设过程，零碳工厂建设工作“重技术、重建设、重实效”，而非一次性评价认定。工业和信息化部将不定期对建设单位开展抽查核验，并按照“成熟一批，验收一批”的原则组织验收，通过验收评估的，正式成为国家级零碳工厂。\n通知还通过附件形式印发《国家级零碳工厂建设评估指标体系及指标说明（试行）》，明确了核心指标、引导指标两部分。其中，核心指标是对零碳工厂建设具有基础性、决定性和约束性的关键因素；设置过程脱碳、协同降碳、智能控碳、碳抵销和信息披露4类8项引导指标，系统引导企业在节能降碳改造、节能装备应用、数字化能碳管理等方面持续提升。\n中国电子技术标准化研究院副院长陈大纪说，通知聚焦国家级零碳工厂“建成什么样、应该怎么建、如何确保建设成效”等关键问题，将引导建设单位从科学算碳、源头减碳、过程脱碳、协同降碳、智能控碳、碳抵销和信息披露等方面，系统推进零碳工厂建设。"}, {"title": "2026世界互联网大会数字丝路发展论坛开幕", "detail": "7月22日，2026世界互联网大会数字丝路发展论坛在西安开幕。本次论坛以“智汇丝路 数启新程——携手构建网络空间命运共同体”为主题，来自全球50多个国家和地区以及7个国际组织约800名嘉宾出席论坛。"}, {"title": "张国清出席2026年亚太经合组织数字和人工智能部长会议开幕式并致辞", "detail": "2026年亚太经合组织（APEC）数字和人工智能部长会议7月23日在四川成都举行，中共中央政治局委员、国务院副总理张国清出席开幕式并致辞。\n张国清表示，习近平主席深刻指出，人工智能是世界经济增长的新引擎和新旧动能转换的加速器，要让人工智能成为促进共同繁荣、维护共同安全的一个重要动力源。在习近平主席战略引领下，中国深入实施创新驱动发展战略，积极融入全球创新网络。中方愿同各方一道，积极落实四大全球倡议，深化数字和人工智能领域务实合作，为构建亚太共同体注入更强大动力。坚持创新驱动，全面促进人工智能科技创新、产业发展、场景应用，引领亚太数智升级。坚持开放共赢，推动标准共建、规则共商、产业共促，推进技术开源开放合作，促进亚太数字繁荣。坚持普惠共享，推进数字和人工智能基础设施建设，促进数据安全有序流动和高效开发利用，更多造福亚太人民。坚持智能向善，加强发展战略、治理规则、技术标准对接协调，携手构建公正合理的全球人工智能治理体系。\n本次会议以“数字和人工智能技术赋能亚太共同体”为主题，来自APEC经济体、秘书处、观察员等170余位代表参会。\nAPEC数字周在成都举行。7月24日，成果文件《APEC人工智能高级别论坛关于促进亚太地区人工智能发展的声明》发布，中方宣布将在深圳设立“促进APEC数据跨境流动合作中国中心”，为推动亚太地区数字化、智能化贡献中国力量。"}, {"title": "我国造船业三大指标保持全球领先", "detail": "工业和信息化部发布上半年我国船舶工业统计数据。造船业三大指标再创历史新高，持续领跑全球市场。\n今年1—6月，我国造船完工量为3650万载重吨，同比增长51.2%；手持订单量达到36325万载重吨，同比增长54.9%；新接订单量达到12106万载重吨，同比增长173.1%，超过历史全年订单峰值。其中，在散货船、集装箱船和油轮三大主流船型中，我国的新接订单量继续保持全球第一。\n此外，上半年，新接绿色船舶订单占国际市场份额超过68%，绿色船舶继续保持全球领先优势，成为我国造船产业转型升级的核心赛道。"}, {"title": "第34届全国图书交易博览会今天开幕", "detail": "第34届全国图书交易博览会7月24日在杭州开幕，将持续到27日。书博会以“书香中国 阅读之美”为主题，全国千余家参展单位参展，线上线下展销图书近百万种。其间，还将发放惠民购书券、举办各类阅读活动等。"}, {"title": "中国数学家邓煜、王虹获得菲尔兹奖", "detail": "当地时间7月23日，中国数学家邓煜、王虹在2026年国际数学家大会上获得菲尔兹奖。这是中国籍数学家首次获得这一奖项。二人分别因为在偏微分方程领域、调和分析和几何测度论领域的成就而获奖。"}, {"title": "“景德镇手工瓷业遗存”成功列入《世界遗产名录》", "detail": "7月25日，在韩国釜山举办的第48届世界遗产大会上，我国申报的“景德镇手工瓷业遗存”成功列入《世界遗产名录》。“景德镇手工瓷业遗存”是纵贯10至19世纪中国制瓷产业体系的代表性遗存，填补了《世界遗产名录》“瓷”主题遗产的空白。遗产区总面积达1979公顷，包含镇区瓷业生产中心、湖田古瓷窑址、蛟潭窑柴燃料产区、高岭瓷土矿遗址、长岭瓷石矿遗址5大片区。遗产要素囊括了原料、燃料产地，瓷业生产中心和水路运输系统，全面覆盖手工制瓷全产业链的关键环节。遗产实证了中国古代南北方制瓷技术的融合，高岭土加瓷石“二元配方”的重大技术飞跃；见证了匠人们巧妙利用中东钴料创烧惊艳天下的青花瓷，以及融合欧洲彩料创新生产粉彩、珐琅彩；全景呈现中国瓷器贸易在工业化之前的全球化发展。至此，我国世界遗产总数达61项。"}, {"title": "我国成为世界上少数红树林面积持续增加的国家之一", "detail": "7月26日是保护红树林生态系统国际日。记者从国家林业和草原局了解到，我国红树林保护取得积极进展，成为世界上少数实现红树林面积持续增加的国家之一。\n今天，国际红树林中心正式运行，作为全球首个致力于红树林保护与合作的政府间国际组织，从全球倡议正式迈入实体化运行新阶段。\n2022年11月，中国在《湿地公约》第十四届缔约方大会上倡议，在深圳建立国际红树林中心。目前，国际红树林中心包括8个成员国和13个签署国，覆盖亚洲、非洲、美洲等全球红树林主要分布区域。实体化运行后，将进一步深化各方的政策交流、技术合作和经验分享，通过开展联合科研攻关、能力培训等，推动形成全球红树林保护合力。\n红树林被称作“海岸卫士”，是全球生态系统不可或缺的重要组成部分。我国始终高度重视红树林保护，出台湿地保护法及配套制度，建设新型自然保护地体系，强化红树林地用途管制，实施保护修复专项行动，全面加强红树林湿地保护修复。\n截至2025年底，我国红树林面积达3.17万公顷，比本世纪初增加44%，是世界上少数实现红树林面积持续增加的国家之一，红树林的生态完整性、生物多样性与蓝碳固碳能力显著提升。"}, {"title": "国务院批复同意将山东省潍坊市列为国家历史文化名城", "detail": "国务院近日批复同意将山东省潍坊市列为国家历史文化名城。\n批复指出，潍坊市历史悠久、文化厚重，文化遗产资源丰富，传统格局和历史风貌保存较好，地域特色鲜明，具有重要的历史文化价值。\n批复要求，山东省及潍坊市人民政府要落实《中华人民共和国文物保护法》《历史文化名城名镇名村保护条例》要求，深入研究发掘文化遗产内涵与价值，系统开展文物资源调查和史料研究，厘清潍县古城的空间格局和发展脉络，明确保护的原则和重点，强化文化遗产保护利用，传承弘扬中华优秀传统文化，讲好中国故事。编制实施好潍坊市历史文化名城保护规划和各级文物保护单位保护规划，制定并严格实施保护管理规定，明确各类保护对象的清单以及保护内容、要求和责任。\n批复还要求，正确处理城市建设与文化遗产保护的关系，摸清文物资源家底，加强文物保护，完善“先调查、后建设”“先考古、后出让”制度，重视城市格局保护和风貌管控，加强整体性保护、系统性保护；保护修复历史文化街区，补足配套基础设施和公共服务设施短板，不断提升人居环境品质；加强不可移动文物和历史建筑修缮保护，推动文物活化利用。"}, {"title": "网信部门严管“自媒体”未规范标注信息来源行为", "detail": "网信部门针对一些“自媒体”在发布涉国内外时事相关内容时，未规范标注信息来源行为，近期加大巡查处置力度，督促网站平台依法依约处置违规账号3704个，纠正错标漏标短视频4.8万余次，持续优化信息来源标注功能。"}, {"title": "辽宁长山群岛纳入世界自然遗产", "detail": "7月27日，在韩国釜山召开的第48届联合国教科文组织世界遗产委员会会议，审议通过了中国黄（渤）海候鸟栖息地世界自然遗产边界调整项目，辽宁大连长山群岛候鸟栖息地成功纳入世界自然遗产。"}, {"title": "【“十五五”开好局起好步】推动残疾人事业全面发展高质量发展", "detail": "国务院新闻办公室7月27日举行“开局起步‘十五五’”系列主题新闻发布会。中国残联相关负责人介绍了“十五五”时期推进残疾人事业全面发展高质量发展有关情况。\n“十五五”时期是基本实现社会主义现代化夯实基础、全面发力的关键时期，也是残疾人事业加快补上短板，推进全面发展、高质量发展的重要时期。发布会上，中国残联负责人介绍，《残疾人保障和发展“十五五”规划》提出了9项主要指标、7个方面32项重点任务、45项重点服务项目和专项行动。\n“十五五”期间，我国将开展孤独症全生命周期关爱促进行动，持续深化无障碍环境共建共享，着力提升残疾人康复、教育、就业质量。同时，加快助残科技成果场景转化，不断完善残疾人社会保障和关爱服务体系，让残疾人民生保障更稳定、助残服务更有温度。"}, {"title": "商务部就所谓“产能过剩”问题介绍中方立场", "detail": "国务院新闻办公室7月28日举行新闻发布会，商务部有关负责人就所谓“产能过剩”问题介绍中方立场。\n商务部表示，产业补贴与产能过剩不存在必然联系，合理合规的产业补贴政策有助于纠正市场失灵、推进技术创新、保护生态环境、减少贫困、促进均衡发展，并不会造成所谓的“产能过剩”。\n出口多、顺差大不等于产能过剩，中国从不刻意追求贸易顺差，顺差虽然在中国，但利益在各方。\n此外，“中国内需不足导致产能过剩”的论调不符合事实。内需一直是中国经济的主引擎，2013—2024年，内需对中国经济增长的平均贡献率为93%。"}, {"title": "中央宣传部授予王戟“时代楷模”称号", "detail": "中央宣传部日前授予王戟“时代楷模”称号。王戟长期奋战在军事教学科研一线，在遭受重大疾病打击、高位截肢的情况下，仍带领团队取得了多项达到国际先进水平的创新成果，为保障多项重大装备关键软件安全可靠作出重要贡献，是新时代军队教育和科技工作者的优秀代表。7月29日，总台央视综合频道播出的《时代楷模发布厅》栏目将讲述他的先进事迹。"}, {"title": "【“十五五”开好局起好步】2030年我国知识产权综合实力进一步增强", "detail": "国务院新闻办公室7月29日上午举行“开局起步‘十五五’”系列主题新闻发布会，国家知识产权局相关负责人介绍，今年以来，我国知识产权各项工作实现平稳起步、良好开局。\n今年上半年，我国共授权发明专利45.3万件，核准注册商标205.5万件，认定地理标志产品64个，我国作为知识产权大国的地位更加巩固。截至6月底，我国高价值发明专利拥有量达到236万件，创新实力持续提升。战略性新兴产业发明专利有效量达到174.6万件，较上年底增长了4.3%，在多个产业领域布局了一批关键核心技术专利。\n国家知识产权局相关负责人介绍，“十五五”时期知识产权工作将突出高质量发展导向，优化“每万人口高价值发明专利拥有量”等指标。进一步完善人工智能、大数据等领域知识产权保护规则。持续推进审查模式创新，不断提升知识产权审查质量和效率。"}, {"title": "【“十五五”开好局起好步】我国推动退役军人工作提质增效", "detail": "国务院新闻办公室7月31日举行“开局起步‘十五五’”系列主题新闻发布会。退役军人事务部相关负责人介绍了“十五五”时期推动退役军人工作提质增效有关情况。\n按照“十五五”规划相关部署，我国将持续拓宽退役军人优质安置渠道，完善就业创业支持体系。2018年以来，全国已有122万名退役军人参与职业技能培训，164万名退役军人参加适应性培训。与此同时，各地将持续常态化搭建就业供需对接平台，帮助退役军人稳定就业创业。\n“十五五”时期，我国将提升退役军人服务保障效能。加强全国61万余个退役军人服务中心和站点标准化、数字化建设，筑牢精细化的基层服务阵地。退役军人事务部将联合相关部门完善困难退役军人帮扶援助体系，继续健全抚恤补助标准动态调整机制，持续拓展优待证使用场景。\n此外，我国双拥共建、英烈褒扬工作也将同步推进。各地继续引导社会资源加大拥军力度，持续完善随军家属就业、军人子女教育优待机制。同时，实施烈士纪念设施提质改造，有序推进零散烈士墓集中管护。"}, {"title": "中国维和警队赴联合国中非 塞浦路斯任务区执行维和任务", "detail": "7月30日，中国赴联合国中非、塞浦路斯任务区维和警队出征仪式在北京举行。到达任务区后，他们将重点开展平民安全防护、协助当地警务体系建设、配合人道主义救援和保护联合国人员设施等工作。"}, {"title": "中央宣传部 中央军委政治工作部联合发布12名“最美新时代革命军人”", "detail": "在中国人民解放军建军99周年之际，中央宣传部、中央军委政治工作部联合发布12名“最美新时代革命军人”。李灿、王晓明、王涛、步佳文、周宏潮、高德宝、顾巧云、王文彬、张峰、常超、范汉杰、陈玉浩等12名官兵，是全军部队在党的旗帜下，加强政治上的革命性锻造、推动实现建军一百年奋斗目标的伟大实践中涌现出的先进典型。他们牢记初心使命、忠实履行职责，充分彰显了广大官兵坚决听党指挥、坚定维护核心的忠诚品格，反映了全军部队加强练兵备战、奋斗攻坚百年的生动实践，展现了人民军队强化整训锻造、奋进强军一流的昂扬风貌。"}, {"title": "四部门联合发布22条健全金融机构治理机制措施", "detail": "金融监管总局、中国人民银行等四部门7月31日联合发布22条措施健全金融机构治理。明确到2029年，基本形成权责边界清晰、激励约束相容、风险管理严格、运转规范高效的金融机构治理机制，金融体系内在稳定性和抗风险能力明显增强。"}, {"title": "科技与工程", "detail": ""}, {"title": "太平岭核电2号机组成功并网", "detail": "中广核广东太平岭核电项目2号机组7月4日首次并网成功，标志着机组正式具备向电网输送电力的能力。太平岭核电2号机组采用我国具有完全自主知识产权的三代核电技术“华龙一号”，预计于今年下半年正式投产发电。"}, {"title": "天问二号探测器抵达目标小行星展开科学探测", "detail": "国家航天局7月6日发布消息，天问二号探测器历经约400天、行程约10亿公里的“追星”之旅，与小行星2016HO3成功交会，并开始科学探测。在抵近小行星过程中，探测器获得了小行星影像数据。后续，天问二号探测器还将对小行星逐步开展更精细科学探测，为采样作准备。"}, {"title": "我国成功发射千帆极轨15组卫星", "detail": "7月5日，长征八号甲运载火箭在海南商业航天发射场成功发射，将千帆极轨15组卫星准确送入预定轨道。这是长征八号甲运载火箭首次发射千帆组网卫星，至此，千帆星座卫星数量已增至238颗。"}, {"title": "历史性突破 长征十号乙完成全球首次海上网系回收", "detail": "7月10日，长征十号乙运载火箭在海南商业航天发射场发射升空，将卫星送入预定轨道，一子级完成全球首次海上网系回收。网系回收是依靠回收船的井字形阻拦索，挂住火箭挂钩，从而实现一子级回收。该技术实现了箭上设备的轻量化和简单化，提高火箭可靠性。截至目前，我国是唯一将这项技术用于实践的国家。\n本次任务成功突破了复杂力热环境适应性、高精度导航控制、海上平台网系捕获回收等关键核心技术。为后续的火箭复用飞行奠定了坚实基础。"}, {"title": "塔里木油田向西气东输供气突破4000亿立方米", "detail": "记者7月13日从中国石油获悉，塔里木油田作为主力气源地，已累计向西气东输管网供气超4000亿立方米，为下游近5亿人口生产生活用气提供了保障。截至目前，塔里木油田在天山南麓已发现两个万亿方大气区，连续6年保持年产气量310亿立方米以上。"}, {"title": "我国中西部地区最大乙烯产业基地建成", "detail": "我国中西部地区最大乙烯产业基地——中国石油独山子石化塔里木120万吨乙烯绿色低碳示范工程7月16日在新疆建成投产，工程构建起全链条低碳技术闭环体系，实现了二氧化碳、副产氢气全部回收再利用，每年可消纳10亿千瓦时清洁电力，减碳137万吨。"}, {"title": "神舟二十三号乘组在轨近两月 各项工作有序推进", "detail": "神舟二十三号乘组朱杨柱、张志远、黎家盈进驻中国空间站将近两个月，目前，航天员身心状态良好，空间科学实验和试验等各项工作进展顺利。\n日前，神舟二十三号乘组“在轨实验清单”不断更新。在航天医学领域，三名航天员利用脑电采集设备、VR眼镜等，持续开展在轨脑电测试研究实验。在航天员心理与行为能力研究方面，乘组完成了应急决策能力评估和在轨情绪状态测试，探究长期在轨航天员应急决策能力与情绪状态的变化规律。根据实验安排，乘组还更换了相关科学实验机柜的样品。\n在轨期间，乘组通过梦天舱货物气闸舱，成功实施了空间辐射生物学暴露实验装置和“天韵相机”的出舱安装，常态化开展空间站组合体平台照料，对首次亮相空间站的改进型在轨质量测量仪进行货包测试。\n据了解，神舟二十三号乘组新开展100余项科学与应用项目已经陆续展开。乘组1名航天员将执行1年期在轨驻留试验，实施我国首个太空人体研究计划，全面获取航天员更长期飞行数据。在航天技术领域，开展新型空间储能电池在轨验证，相关成果有望应用于后续空间站功能升级。"}, {"title": "全球最大煤制油项目智能化改造完成", "detail": "7月19日，全球单体规模最大的煤制油项目——国家能源集团宁夏煤业400万吨/年煤炭间接液化项目完成智能化改造并投入运营。改造后，装置自控率达99.8%，工艺平稳率也从85%提升至99.5%以上。"}, {"title": "全球首艘41800吨双向航行自卸船在江苏交付", "detail": "2026年7月21日，我国自主研制的全球首艘双向航行自卸船在江苏交付。该船载重吨41800吨，卸货能力12000吨/小时，艏艉各设驾驶室，在狭窄水域航行无须掉头，是全球载重吨最大、卸货速度最快的双向航行浅水自卸船。"}, {"title": "西渝高铁七星坪隧道贯通", "detail": "2026年7月21日，西渝高铁七星坪隧道贯通。隧道位于四川达州，全长约13600米。西渝高铁正线全长739公里，设计时速350公里，建成通车后，重庆至西安通行时间将从现在最快5小时左右缩短至2小时左右。"}, {"title": "强流重离子加速器装置建成试运行", "detail": "7月21日，国家重大科技基础设施——强流重离子加速器装置通过工艺验收，转入试运行，面向全球科研用户开放，标志着这台取得多项全球首创技术的大国重器正式建成，将为探索原子核存在极限、推动核能开发等提供重要平台。"}, {"title": "引力一号火箭首次远海发射任务成功", "detail": "7月22日，引力一号运载火箭在上海东部海域成功发射9颗卫星。引力一号是我国研制的全球最大固体运载火箭，近地轨道运载能力6.5吨。这是该火箭首次执行远海发射任务，成功验证了该火箭的远海机动发射能力。"}, {"title": "海军“吉祥方舟”号医院船起航执行“和谐使命-2026”任务", "detail": "7月22日上午，海军“吉祥方舟”号医院船从山东青岛起航，赴非洲、南亚执行“和谐使命-2026”任务，其间将开展医疗卫生服务和文化交流等活动。这是“吉祥方舟”号医院船入列后首次赴海外执行任务。"}, {"title": "三体计算星座加速建设 2032年实现千颗卫星规模", "detail": "7月24日，力箭一号火箭成功发射“一箭五星”。其中，吉天星A-04星、西光贰号03星是三体计算星座的一员。该星座是我国正在建设的太空计算基础设施，按照规划，2032年三体计算星座将达成千星规模。"}, {"title": "国内首条穿越长江高铁隧道贯通", "detail": "7月24日，渝厦高铁重庆菜园坝长江铁路隧道顺利贯通。该隧道全长11942米，是国内首条穿越长江实现贯通的高铁隧道，未来隧道建成通车后将实现重庆站与重庆东站互联互通。渝厦高铁是我国“八纵八横”高铁网的重要组成部分，起自重庆，途经湖南省、江西省，终至福建厦门。"}, {"title": "C919高原型首架机完成首次飞行试验", "detail": "7月29日，C919高原型首架机在上海浦东国际机场开展首次飞行试验，完成全部预定试飞科目，标志着C919飞机系列化发展迈出重要一步。C919高原型在基本型基础上，采取了机身缩短、系统功能改进等针对性设计，以满足高原运行要求。"}, {"title": "内蒙古送电上海配套过江工程开工建设", "detail": "内蒙古送电上海配套过江工程日前开工建设，工程起于上海崇明岛，下穿长江主航道至江苏太仓，是我国设计输送容量最大、江底埋设最深的电力专用隧道，计划于2030年底建成投运。内蒙古送电上海工程全长约1800公里，预计每年向上海输送电量超400亿千瓦时。"}, {"title": "连霍高速改扩建工程星星峡至吐峪沟段正式通车", "detail": "7月30日，全长537.25公里的连霍高速改扩建工程星星峡至吐峪沟段正式通车运营。本段道路由双向四车道升级为双向八车道，设计时速120公里。"}, {"title": "9000吨级气膜粮仓完成首次装粮压仓", "detail": "日前，我国第四代新型粮仓——9000吨级气膜粮仓在湖南长沙完成首次装粮压仓。新型气膜粮仓气密性达到国家高标准粮仓要求的6倍以上，平均温度稳定在15℃以下，每吨粮用电费用降低超4%，运维成本较传统粮仓可节约30%以上。"}, {"title": "烟威1000千伏特高压工程今天实现全线贯通", "detail": "7月27日，国家重点电力工程——烟威1000千伏特高压工程实现全线贯通。线路总长1197公里，途经烟台、青岛、日照、潍坊、临沂5地市，是胶东半岛新能源送出的关键通道。投运后，将大幅提升山东省内的绿电供给能力。"}, {"title": "“文物01星”首批空间采集图像公布", "detail": "我国首颗聚焦文物保护的定制遥感监测卫星——“文物01星”，日前对我国文物资源空间信息进行了首批图像采集。“文物01星”全色分辨率优于0.5米，组网后大幅提升了我国对各级文物保护单位高精度、高频次、常态化的动态监测能力。\n5.新法速递\n李强签署国务院令 公布《退役军人就业创业促进条例》\n国务院总理李强日前签署国务院令，公布《退役军人就业创业促进条例》（以下简称《条例》），自2026年8月1日起施行。《条例》共6章48条。\n一是明确总体要求。坚持普惠与优待叠加的原则，采取政府推动、市场引导、社会支持相结合的方式，鼓励和扶持退役军人就业创业。二是确定教育培训政策。退役军人参加国家教育考试和接受学历教育时按照国家有关规定享受优待和资助政策。三是完善就业优待措施。机关、群团组织、事业单位和国有企业在招录或者招聘人员时，对退役军人的年龄和学历条件可以适当放宽，同等条件下优先招录、招聘退役军人。各地设置一定数量的基层公务员职位，面向服现役满5年的高校毕业生退役军人招考。明确艰苦边远地区县乡事业单位招聘、国家综合性消防救援队伍消防员等特殊岗位招录时对退役军人的优待政策。四是优化创业扶持举措。明确对退役军人创业给予税收、融资、信贷等扶持政策。\n6.地方要闻"}, {"title": "北京市郊铁路城市副中心线西段开通运营", "detail": "7月1日，北京市郊铁路城市副中心线西段开通运营。作为连接北京中心城区、城市副中心与房山区的重要轨道交通走廊，该线路打通了北京西南地区的通勤瓶颈。为构建首都“1小时通勤圈”提供了有力支撑。"}, {"title": "北京人工智能赋能科学研究实施方案启动", "detail": "北京人工智能赋能科学研究实施方案7月1日启动，围绕自主实验室建设、标杆场景应用、科学数据供给等方面，发布了18项具体任务。提出到2028年，北京人工智能赋能科学研究取得重大原创突破，努力建成辐射全球的科学智能创新中枢。"}, {"title": "中俄蒙“万里茶道”十条跨境精品旅游线路发布", "detail": "7月2日，中俄蒙“万里茶道”国际旅游联盟在内蒙古呼和浩特发布十条跨境精品旅游线路，包括茶路之旅、世界自然遗产之旅、跨境自驾之旅等，有效串联中俄蒙三国优质文旅资源。"}, {"title": "西渝高铁石家梁隧道贯通", "detail": "7月4日，西安至重庆高速铁路控制性工程全长11908米的石家梁隧道顺利贯通。西渝高铁全线预计2028年建成通车，届时，重庆到西安的列车运行时间，将由现在的最快5个多小时缩短至2小时左右。"}, {"title": "珠海至肇庆高铁将军岭隧道贯通", "detail": "7月10日，珠海至肇庆高铁项目将军岭隧道实现贯通。隧道全长3500米，是珠肇高铁控制性工程。珠肇高铁全长184.5公里，设计时速350公里，串联起珠海、江门、佛山、肇庆4个城市，对构建粤港澳大湾区“一小时交通圈”有重要作用。"}, {"title": "第二十五届环大美青海国际公路自行车赛开赛", "detail": "第二十五届环大美青海国际公路自行车赛7月11日开赛，来自全球12个国家的22支车队参赛。比赛为期8天，途经青海西宁、海东、海南、海北四市州，总里程1627公里，串联起草原、湖泊、雪山等多元地貌，最高海拔达4000米。"}, {"title": "“世界树之巅：美洲古代文明大展”在上海举办", "detail": "“世界树之巅：美洲古代文明大展”在上海博物馆举办。展览汇聚来自墨西哥、秘鲁与中国文博机构的近3000件珍贵文物，全景式勾勒古代中南美洲的文明长卷。展览将持续至明年11月14日。"}, {"title": "第三十二届中国兰州投资贸易洽谈会今天闭幕", "detail": "第三十二届中国兰州投资贸易洽谈会7月13日闭幕。本届兰洽会有国内外近1900家企业参展，签约10亿元以上的项目占比达到61%，涉及传统产业升级、未来产业布局、服务业扩容等方面。"}, {"title": "“2026世界市长对话·西双版纳”活动举行", "detail": "7月14日至16日，“2026世界市长对话·西双版纳”活动在云南省西双版纳傣族自治州举行。来自全球24个国家和地区的上百位嘉宾走进景洪市、勐海县等地，了解中国实践、中国经验，共同探讨人与自然和谐共生路径及城市可持续发展方案。"}, {"title": "2026年中国文明乡风大会在山东临沂举行", "detail": "7月16日，2026年中国文明乡风大会在山东临沂举行。与会代表围绕推动党的创新理论进村入户、保护发展传统村落、用好乡土文化资源、加强家庭家教家风建设、以互联网赋能文明乡风等方面进行深入研讨交流。"}, {"title": "上海市人形机器人中试服务平台正式启用", "detail": "上海市人形机器人中试服务平台7月18日启用。该平台位于浦东张江机器人谷，构建研发试制、精密装配、全项测试、仓储交付一体化中试闭环。平台将面向人形机器人整机测试、供应链对接等，服务初创企业、中小企业，降低研发成本。"}, {"title": "内蒙古第36届旅游那达慕开幕", "detail": "内蒙古第36届旅游那达慕7月18日在锡林浩特开幕。本届那达慕包含搏克、赛马、射箭等经典竞技赛事。现场，还有非遗体验、民俗互动、草原美食等，让游客沉浸式感受草原风情。活动将持续至8月下旬。"}, {"title": "西康高铁全线拉通试验正式启动", "detail": "7月25日，随着55301次综合检测列车从西安东站平稳驶出，穿越秦岭山脉直达安康西站，标志着西康高铁全线拉通试验正式启动，联调联试工作取得重要阶段性进展，为后续试运行和开通运营奠定了坚实基础。\n全线拉通试验是高铁开通运营前的综合大考与实战彩排，将此前单项测试成果整合，对轨道、供电、接触网、信号、通信等全系统开展综合验证，确保各项指标全面达标、系统匹配稳定，满足高速行车安全标准。\n西安至安康高速铁路是国家中长期铁路网规划“八纵八横”高铁通道中包（银）海通道、京昆通道的重要组成部分，新建正线全长约171公里，设计时速350公里。线路自西安东站南端引出，跨越浐河、穿越秦岭，经过柞水、镇安、旬阳，接入在建安康西站。\n西康高铁通车后，西安至安康铁路运行时间将由目前的3小时左右缩短至1小时以内，大幅缩短关中城市群与陕南秦巴山区的时空距离，提高沿线地区客货运输服务水平。"}, {"title": "北京162项公安政务服务事项实现“全程网办”", "detail": "目前，北京市居民身份证补领、机动车驾驶证核发等162项公安政务服务事项实现“全程网办”。今年上半年，公安政务服务网办量4700余万件，网办率达95.6%。"}, {"title": "第十二批援疆干部人才赴新疆工作", "detail": "第十二批中央单位援疆干部人才7月26日从北京出发前往乌鲁木齐，开始为期三年的援疆。今年，130多家中央单位和21个省市共选派8300多名援疆干部人才，将聚焦教育、水利、医疗卫生、农业技术推广等重点领域，继续加大支持力度。"}, {"title": "上半年上海外贸出口首破万亿元大关", "detail": "今年上半年，上海市进出口总值达2.55万亿元，同比增长18.6%，外贸规模创历史新高，其中，对36个国家和地区外贸规模均超百亿元。出口首次突破万亿元大关，达1.14万亿元，同比增长20.1%。"}, {"title": "2026“新疆是个好地方”非遗援疆主题展示活动举办", "detail": "2026“新疆是个好地方”非遗援疆主题展示活动，7月30日在新疆石河子市举办。活动汇聚全国31个省区市和新疆生产建设兵团的651项非遗代表性项目、549位非遗传承人，展示非遗传承和文化润疆的丰硕成果。\n二、国际部分"}, {"title": "美国称不同意以现有形式续签美墨加协定", "detail": "美国贸易代表格里尔7月1日称，美方不同意以现有形式续签“美国—墨西哥—加拿大协定”。美国将继续与墨西哥和加拿大就贸易逆差等问题进行沟通，在问题得到解决或该协定终止前，现有协定依然有效。墨西哥和加拿大方面表示，应继续进行磋商。\n美墨加协定于特朗普首个总统任期谈成，取代了此前的北美自贸协定，涉及汽车产业、数字贸易、知识产权等领域。据美国媒体报道，美方目前对美墨加协定的不满主要集中在贸易逆差问题上。"}, {"title": "欧盟法院驳回上诉 谷歌面临巨额罚单", "detail": "位于卢森堡的欧盟法院7月2日作出裁决，驳回美国互联网巨头谷歌就2018年欧盟委员会巨额罚单提起的上诉，认定谷歌利用安卓操作系统滥用市场支配地位。谷歌面临创纪录的41亿欧元反垄断罚款。过去数年，欧盟多次就垄断问题向谷歌开出巨额罚单。"}, {"title": "以官员首次承认曾在阿联酋部署“铁穹”", "detail": "据以色列媒体7月5日报道，以色列交通部长雷格夫证实，在今年美国和以色列对伊朗发动军事打击初期，以色列曾在阿联酋部署一套“铁穹”防空系统。以色列媒体报道说，这是以色列政府官员首次公开承认曾向阿联酋部署“铁穹”系统。今年4月美国媒体曾报道说以色列向阿联酋部署一套“铁穹”防空系统，这是“铁穹”系统首次部署到以色列和美国以外国家。阿联酋官方尚未就以色列在该国部署“铁穹”防空系统一事作出表态。2020年，以色列与阿联酋签署了关系正常化协议。"}, {"title": "国际奥委会暂时恢复俄奥委会会员资格", "detail": "国际奥委会执委会7月7日宣布，暂时解除自2023年10月12日起对俄罗斯奥委会实施的暂停其会员资格的处罚。这一决定为俄罗斯运动员全面回归国际体育赛事扫清了政策障碍。俄体育部长兼奥委会主席杰格佳廖夫表示，这是俄方通过持久的法律和外交努力达成的成果，并将鼓励各国际单项体育联合会恢复俄运动员的参赛权利。"}, {"title": "2026年亚太经合组织工商咨询理事会第三次会议举行", "detail": "6日至9日，2026年亚太经合组织工商咨询理事会第三次会议在泰国首都曼谷举行。来自21个亚太经合组织经济体的官员、工商咨询理事会代表、专家等200多人参会。\n会议期间，亚太工商界围绕区域经济一体化、可持续发展、数字创新和互联互通四大重点领域深入交流。会议通过了亚太经合组织工商咨询理事会致领导人的信函和报告，亚太经合组织工商咨询理事会致各经济体财政、能源、中小企业、数字、粮食、交通部长的信函等10份核心成果文件，为11月领导人非正式会议积累了高质量工商界成果。"}, {"title": "日内瓦“全球治理之友小组”举办人工智能向善普惠发展研讨会", "detail": "7月7日，在首届人工智能治理全球对话和人工智能造福人类全球峰会期间，日内瓦“全球治理之友小组”举办人工智能向善普惠发展研讨会。中国代表在研讨会上介绍中国人工智能发展成就并表示，人工智能全球治理呼唤更强有力的国际协作，各方应深化创新合作，加强协同共治，充分释放智能红利，共创美好智能时代。\n与会各方强调应加强团结合作，推动人工智能向善发展、普惠各方、造福人类，为“全球治理之友小组”举办研讨会，为人工智能全球治理作出积极贡献。"}, {"title": "国际乒联恢复俄罗斯运动员参赛资格", "detail": "国际乒联7月13日宣布，其执行董事会决定自2026年7月28日起恢复俄罗斯运动员参赛资格。国际奥委会执委会7日宣布，暂时解除自2023年10月12日起对俄罗斯奥委会实施的暂停其会员协会资格的处罚，同时明确，此前向各国际单项体育联合会发布的关于俄罗斯运动员及运动队参赛的相关指导建议不再适用。\n国际乒联表示，基于上述背景，其执行董事会作出了当天的决定。国际乒联近期还恢复了白俄罗斯运动员的参赛资格。"}, {"title": "2026上合组织国家文明对话在比什凯克举行", "detail": "2026上合组织国家文明对话7月14日在吉尔吉斯斯坦首都比什凯克举行。与会嘉宾表示，中国国家主席习近平先后提出构建人类命运共同体理念和全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议，为国际社会应对世界变局、破解紧迫难题提供了重要国际公共产品。上合组织始终把人文交流作为行稳致远的重要支撑，各成员国开展了一系列务实合作。“各美其美、美美与共”的文明传统已深度融入地区各国人民的文化基因，成为上合组织文明对话最深厚的历史底蕴。"}, {"title": "我国派专家组加入埃博拉“突发事件管理支持小组”支援非洲疫情防控", "detail": "应非洲疾控中心和世界卫生组织的联合邀请，我国派出专家组7月15日启程赴乌干达，加入埃博拉“突发事件管理支持小组”，支援疫情防控。专家组将与各国专家一同参与非洲埃博拉疫情研判、防控方案制定和现场应急协调等工作。"}, {"title": "英将对16至17岁青少年实施社媒“宵禁”", "detail": "英国政府7月14日宣布，将对16岁至17岁青少年使用社交媒体实施“宵禁”，即在0时到6时不能使用社交媒体。这是英国政府继上月宣布将禁止16岁以下人群使用一系列社交媒体应用程序后，又一项新的限制举措。"}, {"title": "德总理称德常规部队将首次参加法核演习", "detail": "德国总理默茨7月17日在与到访的法国总统马克龙会面后称，德国今年将首次派遣常规部队参与法国武装部队核演习。德国还将参与支持乌克兰的“意愿联盟”拟于今年秋季举行的军事演习。俄罗斯外长拉夫罗夫此前表示，当前局势显示存在北约与俄罗斯直接对抗的风险，这种对抗可能迅速升级为相互核打击。"}, {"title": "伯纳姆当选英国工党党首 将出任首相", "detail": "英国执政党工党7月17日宣布，安迪·伯纳姆当选该党新任党首。按计划，伯纳姆将于20日接替此前宣布辞职的斯塔默出任英国首相。伯纳姆当选党首后表示，新一届政府将打造新政治格局，推动英国整体发展。现年56岁的伯纳姆曾担任英国文化大臣、卫生大臣、大曼彻斯特市长等职。"}, {"title": "美国对贸易伙伴征收新关税 多方反对", "detail": "美国贸易代表办公室7月23日发布公告，以未能对所谓“强迫劳动”采取行动为由，对60个国家和地区征收10%至12.5%的关税。澳大利亚、新西兰、巴西等多国均对美方做法表示反对。\n今年2月20日，美国最高法院裁定美国联邦政府大规模征收关税违法。美国总统特朗普随即于同一天宣布，对所有国家征收10%的全球进口关税，为期150天，于7月24日到期。"}, {"title": "美国和伊朗暂停互袭 国际油价大幅下跌", "detail": "据伊朗媒体报道，伊朗军方26日称，美国在过去两晚停止了针对伊朗的袭击，因此伊方也暂停了报复性打击行动。伊朗外交部发言人巴加埃同一天表示，伊朗与美国之间的信息传递仍在持续，斡旋方也正继续开展相关工作。\n美国常驻联合国代表迈克尔·华尔兹26日称，美方作出暂停打击伊朗的决定，给外交谈判留出空间。他没有透露关于谈判的具体情况。\n由于美国和伊朗暂停相互袭击，国际原油期货价格26日一度大幅下跌超6%。"}, {"title": "非法移民持续进入西班牙飞地休达", "detail": "西班牙位于北非的飞地——休达30日发生大规模非法移民闯入事件。据西班牙媒体今天（7月31日）报道，至少18人在此过程中丧生。为应对非法移民闯入，西班牙另一处北非飞地——梅利利亚30日宣布关闭与摩洛哥之间的陆路口岸。\n此外，意大利政府30日称，因非法移民对欧洲边境安全构成威胁，正考虑暂停执行与西班牙之间的申根协定。\n2026年7月时政文件"}, {"title": "《国际科技组织成立登记指引》出台", "detail": "7月4日，民政部、科技部、中国科协联合公布《国际科技组织成立登记指引》，推动构建开放、公平、公正、非歧视的国际科技发展环境。\n登记指引适用于在民政部申请成立登记的国际科技组织，即由中外高等学校、科研院所、科技组织、企业等单位或者个人共同发起，在中国境内成立登记，旨在促进自然科学和工程技术领域国际合作、国际交流和国际治理的国际性（或者区域性）、非营利性、非政府的社会团体法人。在经济、教育、文化、卫生、体育、环保等领域发起设立国际性社会组织，可参照适用。\n登记指引规定，在华设立国际科技组织，外籍会员占比不低于三分之一，运行中应当坚持国际性、非营利性。\n登记指引要求，成立国际科技组织须有适当的中外发起人，发起人为初始会员；有规范的名称，应按照国家有关规定经过批准，冠以“国际”“世界”“全球”“亚洲”等体现组织国际性或者区域性的字样；有合法的资产和经费来源，成立时的活动资金为捐赠资金，不低于200万元等。\n在申请程序上，主要包括5个环节，分别是明确业务主管单位，业务主管单位审核，登记管理机关审查，准予登记和发放证书，以及刻制印章、办理税务登记和开立银行账户。"}, {"title": "中共中央组织部印发《关于在防汛救灾工作中充分发挥基层党组织战斗堡垒作用和广大党员", "detail": "先锋模范作用的通知》\n一、各级领导干部要牢固树立和践行正确政绩观，加强值守、靠前指挥。要进一步提高思想认识，坚持人民至上、生命至上，坚决克服惯性思维、麻痹思想、侥幸心理，严格落实防灾救灾责任，扎实做好防灾救灾各项工作，确保人民群众生命财产安全和社会大局稳定。要树牢底线思维、极限思维，加强统筹部署和预置布防，落实应急值班值守制度，强化多部门会商研判，提高监测预报精准度，完善各类应急预案，进一步做好力量、装备、物资准备，确保发生突发紧急情况时能快速反应、高效处置。要坚持资源向基层倾斜、力量向一线下沉，着力提升基层防汛减灾救灾能力。要根据实际情况深入灾情最严重、抢险最困难、群众最需要的地方，加强现场调度指挥，科学调配救援力量和救灾物资，全力搜救失联被困人员，及时果断转移安置受威胁群众，最大限度减少人员伤亡，防范次生灾害。要坚持防汛抗旱两手抓，有效防范应对旱涝急转带来的灾害风险。\n二、基层党组织和党员干部要守土尽责、挺膺担当，筑牢守护人民群众生命财产安全的坚实防线。要充分发挥基层党组织政治功能和组织功能，组织动员广大党员干部和群众积极投身抢险救灾工作，让党旗在防汛救灾一线高高飘扬。要做好群众宣传动员，深入开展入户走访，利用互联网、手机、乡村广播、流动宣传车、宣传栏等媒介，第一时间把灾害预警、防范措施、应对策略等信息传递到每一户、每个人，提高群众防灾避险意识和自救互救能力。要压实联点包片责任，发挥村（社区）网格作用，加强山洪灾害危险区、地质灾害易发区、城市易淹易涝点、江河湖泊、病险水库、河道堤防、漫水桥等重点部位风险隐患排查整治，提前做好安全管控。要做好人员转移避险，严格落实直达基层责任人的临灾预警“叫应”机制，突出抓好人口相对聚集的山沟沟口、行洪河道、临坡临崖等高风险地段和养老院、施工工地、工棚、民宿等重点部位人员转移，针对老弱病残孕等重点群体实施“一对一”帮扶措施，做到应转早转、应转尽转，严防出现群死群伤。要用心用情做好受灾群众安置救助和情绪疏导工作，挨家挨户排查受灾情况，全力解救、妥善安置被困群众，确保受灾群众有饭吃、有衣穿、有住处、有干净饮水，有病能够及时医治。要健全落实党员应急动员发挥作用机制，通过组建党员突击队和志愿服务队、设置党员先锋岗和责任区等方式，组织村（社区）党员带领群众合力抢险救灾。灾情严重的地区，要组织机关和国有企事业单位党员干部下沉一线，会同乡镇（街道）、村（社区）干部以及驻村第一书记和工作队等共同防汛救灾。要积极动员货车司机、网约车司机、网约配送员、快递员等新就业群体中的党员立足自身优势，带头就近就便参与防汛救灾。\n三、各级党委组织部门要充分发挥职能作用，激励广大党员干部在防汛救灾一线勇挑重担、冲锋在前。要把做好防汛救灾工作与开展树立和践行正确政绩观学习教育结合起来，用防灾救灾、守护人民群众生命财产安全的实绩检验学习教育成效。注重在防汛救灾一线考察识别干部，把在急难险重任务中的表现作为评价干部的重要参考。要指导基层党组织发现和考验入党积极分子，对表现突出、符合条件的，及时发展入党。要注重发现、宣传和表彰防汛救灾中涌现的基层党组织和党员干部先进典型。要关心关爱防汛救灾一线党员、干部，对因公牺牲党员、干部的家属，会同有关方面及时给予抚恤、慰问，帮助解决实际困难。相关地区要用好划拨的中管党费，并结合实际从本级管理党费中落实配套资金，及时划拨给基层，做到专款专用。"}, {"title": "国务院印发《“十五五”碳达峰行动方案》", "detail": "国务院日前印发《“十五五”碳达峰行动方案》（以下简称《行动方案》）。\n《行动方案》强调，发挥碳达峰碳中和战略牵引作用，更好统筹保障能源安全和经济社会发展，深入推进产业绿色化、低碳化，稳步实现煤炭和石油消费达峰，加快形成绿色生产生活方式，培育更多绿色经济增长点，厚植高质量发展绿色底色。\n《行动方案》部署了加快能源结构调整优化、推进产业绿色化低碳化、深化重点领域绿色低碳转型等5方面重点任务，安排了省间电力互济、煤炭消费清洁替代、重点行业节能降碳、低碳零碳供热制冷和绿色照明、零碳运输走廊建设、碳达峰碳中和基础能力提升等重点工程。\n坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全会精神，认真落实四中全会部署，完整准确全面贯彻新发展理念，发挥碳达峰碳中和战略牵引作用，更好统筹保障能源安全和经济社会发展，以能源绿色低碳转型为关键，深入推进产业绿色化、低碳化，更高水平、更高质量做好节能降碳工作，稳步实现煤炭和石油消费达峰，将绿色低碳导向融入国民经济循环各领域各环节，加快形成绿色生产生活方式，培育更多绿色经济增长点，厚植高质量发展绿色底色。\n到2030年，我国单位国内生产总值二氧化碳排放比2025年降低17%，非化石能源消费占比达到25%，确保如期实现碳达峰目标，为实现2035年国家自主贡献目标、推进碳中和奠定坚实基础。"}, {"title": "中共中央办公厅、国务院办公厅印发《关于全力做好防汛抗旱工作的通知》", "detail": "近日，中共中央办公厅、国务院办公厅印发《关于全力做好防汛抗旱工作的通知》（以下简称《通知》），对全力做好防汛抗旱、抢险救灾各项工作作出部署。\n《通知》要求，各地区、各有关部门和单位要深入贯彻党中央决策部署和习近平总书记重要指示要求，深刻认识洪涝干旱灾害的极端性和复杂性，立足防大汛、抗大旱、防强台风，牢固树立底线思维、极限思维，全面压实政治责任。坚决克服麻痹思想和侥幸心理，夯实地方党委和政府主体责任、行业部门监管责任，压实有关企事业单位主要负责人防洪保安全第一责任人责任。各级防汛抗旱指挥机构要强化统筹协调和指挥调度，各有关部门和单位要履职尽责、高效协同。基层党组织和广大党员干部要充分发挥战斗堡垒作用和先锋模范作用，在防汛抗旱、抢险救灾一线勇挑重担、冲锋在前，有力维护人民群众生命财产安全和社会大局稳定。"}, {"title": "《推动平台企业赋能个体工商户发展行动方案》印发", "detail": "记者了解到，市场监管总局印发《推动平台企业赋能个体工商户发展行动方案》（以下简称《行动方案》）。《行动方案》提出，2027年年底前，滚动形成“五个一批”工作成果，即推出一批精准“滴灌”、直达快享的帮扶举措，培育一批特色鲜明、转型发展的优质商户，定制一批“解渴”管用、生动务实的培训课程，搭建一批数字赋能、有形有感的应用场景，选树一批创新融合、可学可鉴的典型案例，探索构建平台企业赋能个体工商户发展的长效实践路径。\n《行动方案》部署开展5方面专项行动。\n一是开展初创帮扶行动。加大对平台新入驻个体工商户的支持力度，便利经营准入，降低经营成本。\n二是开展重点培育行动。打造“名特优新”金字招牌，引导平台企业开展资源对接，支持地方特色产业发展。\n三是开展能力提升行动。加强政策法规宣传和技能培训，引导个体工商户守法合规经营，提升市场竞争能力。\n四是开展数字赋能行动。鼓励平台企业推出更多轻量化、低成本数字化运营工具，减轻个体工商户运营负担。\n五是开展创新示范行动。鼓励各地结合实际出台支持个体工商户线上发展的一揽子举措，用好“全国个体工商户发展网”等载体平台。"}, {"title": "我国公路运力持续扩容 数智化升级加快", "detail": "《2026中国公路运力发展报告》7月10日发布。报告显示，超六成调研企业运力规模较上一年有所扩张。货车高速使用整体呈上升趋势，以消费品及制造业成品运输为主。整体来看，公路运力组织模式正加速向平台化、数字化、绿色化迈进。"}, {"title": "明年起企业年金个人账户可线上转移接续", "detail": "《企业年金个人账户转移接续规程（暂行）》日前对外发布，确保职工换工作时，企业年金个人账户不会丢、方便转。\n规程明确，自2027年1月1日起，职工可通过登录国家社会保险公共服务平台、全国人社政务服务平台、电子社保卡、掌上12333App等全国统一线上服务渠道，申请转移接续本人企业年金个人账户，并查询办理进度。个人缴费、已归属个人的单位缴费、已转入的职业年金以及相应投资收益均可随账户转移。\n职工已参加新就业单位企业年金的，选择名下新就业单位的企业年金个人账户作为归集账户；新就业单位没有建立企业年金或者未参加新就业单位企业年金、且需归集多个企业年金个人账户时，区分不同情形，选择一个企业年金集合计划管理的保留账户或者最后一个原就业单位管理的企业年金账户作为归集账户。之后，职工向管理归集账户的企业年金受托人提出转移接续申请。\n退休人员正在领取企业年金待遇的，可以申请将本人其他企业年金个人账户资金转移至正在领取的企业年金个人账户。"}, {"title": "我国将系统推进能源领域节能降碳", "detail": "国家能源局近日印发《能源领域节能降碳行动计划（2026—2028年）》。计划提出到2028年，非化石能源消费比重年均提升约1个百分点，建成一批零碳低碳煤炭矿区、油区，推动重点行业节能降碳取得显著进展，绿色用能水平不断提升。"}, {"title": "国务院印发《国民健康“十五五”规划》", "detail": "国务院日前印发《国民健康“十五五”规划》，对“十五五”时期加快建设健康中国作出部署，推动医疗卫生发展方式更加注重以健康为中心、服务体系更加注重质量效益提升、改革治理更加注重系统协同，增强健康服务均衡性和可及性，推动人民群众更加注重主动健康，加快形成有利于健康的生产生活方式和经济社会发展模式，全面提高国民健康水平。\n《规划》围绕优化全人群全方位全周期健康服务、持续筑牢高水平卫生健康安全屏障、加快完善优质高效整合型医疗卫生服务体系等5个方面，部署了24项重点任务，提出了高品质健康服务、高水平卫生健康安全、面向人民生命健康的重大创新、公立医院改革与高质量发展等重大工程和项目，以及“十五五”时期医疗卫生资源配置指导原则。"}, {"title": "中共中央办公厅 国务院办公厅印发《关于完善自然资源资产管理制度体系的意见》", "detail": "中共中央办公厅、国务院办公厅日前印发《关于完善自然资源资产管理制度体系的意见》。《意见》提出，以健全自然资源资产产权制度为主线，强化自然资源整体保护，促进自然资源资产高效配置，维护自然资源资产所有者权益，健全自然资源资产管理体制机制，加强监督管理，守牢资源安全底线，为推进人与自然和谐共生的现代化提供有力支撑和保障。\n主要目标是，到2030年，自然资源资产管理制度体系更加健全，履职主体更加明确、资产家底更加清晰、整体保护更加有力、资产配置更加高效、考核监督更加完善，各类自然资源资产和全部国土空间得到有效保护，自然资源资产管理水平明显提升。到2035年，自然资源资产管理体制机制运转顺畅，系统完备的自然资源资产管理制度体系全面建立，自然资源资产管理水平全面提升。"}, {"title": "《扩大消费“十五五”规划》出台 多项举措促进消费扩容提质", "detail": "《扩大消费“十五五”规划》近日出台，《规划》围绕服务消费、商品消费、消费新业态新模式新场景、消费能力、消费环境等6个方面，部署涉及增收、育儿、养老、住房、汽车等一系列政策举措，力争实现到2030年，社会消费品零售总额达到60万亿元左右，消费对经济增长的拉动作用进一步增强。"}, {"title": "“十五五”时期我国将打造一批海洋特色文化和旅游目的地", "detail": "根据《旅游强国建设“十五五”规划》，我国将打造一批海洋特色文化和旅游目的地，构建串联南北的海洋旅游带，完善近海观光、潜水体验等旅游产品体系；支持上海邮轮旅游发展示范区建设，推进大连、天津、青岛等邮轮港口建设。"}, {"title": "“十五五”时期支持建设200个左右“无废城市”", "detail": "《固体废物污染防治“十五五”规划》日前出台，明确提出：将支持200个左右城市开展“无废城市”建设。到2030年，重点领域固体废物专项整治取得明显成效，固体废物历史堆存量得到有效管控，固体废物综合治理能力和水平显著提升。"}, {"title": "《人工智能拟人化互动服务管理暂行办法》施行", "detail": "《人工智能拟人化互动服务管理暂行办法》7月15日起正式施行。办法明确了人工智能拟人化互动服务“辅助人类、服务人类”的定位，要求服务提供者不得将替代社会交往、控制用户心理、诱导沉迷依赖等作为服务目标；要求确立“身份提醒”和风险干预机制，引导用户平衡虚拟互动与现实社交。"}, {"title": "长三角一体化示范区建设三年行动计划发布", "detail": "《长三角生态绿色一体化发展示范区建设三年行动计划》日前正式印发，围绕协同提升科技创新策源功能、联合做强新兴产业集聚功能等方面明确了34项任务举措，赋予示范区更大改革探索空间，更好发挥对长三角一体化发展和区域协调发展的示范带动作用。"}, {"title": "《市场监督管理严重违法失信名单管理办法》施行", "detail": "新修订的《市场监督管理严重违法失信名单管理办法》7月15日开始施行。办法从严约束企业信息公示行为，对隐瞒实情、弄虚作假，情节严重的，列入严重违法失信名单。将未依法取得许可从事重点液态食品道路散装运输、明知特种设备存在同一性缺陷但未立即停止生产并召回的违法行为，纳入严重违法失信惩戒，保障人民群众生命财产安全。"}, {"title": "我国社会组织评比表彰新规出台 8月1日起施行", "detail": "7月16日，民政部、中央社会工作部联合发布《社会组织评比表彰活动管理办法》，自今年8月1日起施行。新规明确，评比表彰严格实行清单管理，一般每五年开展一次，严禁违规收费和发放奖金。未经批准，不得以“国家”“全球”等名义开展评比，不得借峰会、论坛等活动颁奖。"}, {"title": "我国国家物流枢纽发展取得明显成效", "detail": "中国物流与采购联合会日前发布《国家物流枢纽创新发展报告（2026）》。截至目前，我国已有181个国家物流枢纽。2025年，国家物流枢纽平均货物吞吐量同比增长5.5%，增速高于全国货运量平均水平2.3个百分点。近八成国家物流枢纽建有铁路场站或专用线。数字化、智能化普及应用提速。超九成枢纽应用智能设施设备，无人闸口、智能调度、自动化作业场景广泛落地。超七成枢纽配备新能源载货汽车，半数以上枢纽使用可再生能源发电，绿色物流、低碳运营成为行业发展新风向。"}, {"title": "中国发布《中国关于数智时代全球网络治理的立场文件》", "detail": "联合国全球网络安全常设机制首次会议20日至24日在纽约联合国总部举行。中国代表团向全球机制提交了《中国关于数智时代全球网络治理的立场文件》。继网络主权后，中方此次提出了数字主权的重要原则，是中国落实全球治理倡议和推动构建网络空间命运共同体的最新举措。\n文件强调，为维护和平稳定，各国在网络空间应遵守联合国宪章宗旨和原则；倡导尊重数字主权，共促普惠发展，各国有权基于国情自主选择包括人工智能在内的数智技术发展路径，有权自主选择人工智能技术、产品和服务，不应当被胁迫选边站队；重申坚持多边主义，有效应对人工智能等新兴技术对网络安全带来的风险，与时俱进制定新的网络国际规则。\n中国代表团团长、外交部网络和数字事务协调员在全球机制会议期间全面介绍了中方立场文件。"}, {"title": "中共中央 国务院印发《关于加强新时代社会工作的意见》", "detail": "近日，中共中央、国务院印发《关于加强新时代社会工作的意见》（以下简称《意见》）。\n《意见》指出，社会工作是党和国家工作的重要组成部分，事关党长期执政和国家长治久安，事关社会和谐稳定和人民幸福安康。加强新时代社会工作，要坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全会精神，认真落实四中全会部署，全面贯彻习近平总书记关于社会工作的重要论述，坚持和加强党对社会工作的全面领导，坚持以人民为中心，走好新时代党的群众路线，坚持和发展新时代“枫桥经验”，完善共建共治共享的社会治理制度，坚定不移走中国特色社会主义社会治理之路，推动新时代社会工作高质量发展，以高效能治理促进高质量发展和高水平安全良性互动，更好服务保障党和国家工作大局。\n《意见》从健全党领导社会工作的体制机制、加强新兴领域党的建设、加强党建引领基层治理和基层政权建设、做好凝聚服务群众工作、加强基础保障等方面提出具体要求。"}, {"title": "国务院印发《全民健身计划（2026—2030年）》", "detail": "国务院日前印发《全民健身计划（2026—2030年）》（以下简称《计划》），对“十五五”时期推动全民健身事业高质量发展作出部署。\n《计划》强调，推动全民健身和全民健康深度融合，不断完善全民健身公共服务体系，进一步提升全民健身基本公共服务均衡性、可及性，加快建设体育强国、健康中国。\n《计划》部署了不断完善全民健身制度体系、进一步加强群众身边健身场地设施建设、开展丰富多彩的群众赛事活动、健全全民健身组织服务网络、提高科学健身指导服务能力、运用人工智能赋能全民健身发展、满足不同人群差异化健身需求等10个方面的主要任务，并围绕目标任务的完成提出了保障措施。"}, {"title": "《体育强国建设“十五五”规划》发布 系统部署体育高质量发展", "detail": "经国务院批复同意，国家体育总局近日发布《体育强国建设“十五五”规划》。这是首个以“体育强国”为主题的国家级专项规划，对“十五五”时期加快建设体育强国、推动体育高质量发展作出系统部署。\n规划提出，到2030年，体育整体发展质量和效益显著提升，综合价值和多元功能充分彰显，体育成为中华民族伟大复兴的标志性事业基础更加坚实，并设定5项主要发展指标：人均体育场地面积达到4平方米左右，经常参加体育锻炼人数比例达到40%左右，国民体质优良率达到31.1%，获得世界冠军数量位居前列，体育产业总规模突破7万亿元。\n规划全文共11个部分，分为总论、重点任务和保障措施三大板块。围绕全民健身、竞技体育、青少年体育、“三大球”、体育产业、体育文化、体育对外及对港澳台交往以及体育教育、科技、人才、法治、反兴奋剂、安全等方面提出了38项重点任务。规划配套设置了8个专栏工程，涉及场地设施建设、运动项目布局、训练基地提升、后备人才培养、体育科技创新、体育人才培养等关键领域。\n规划要求，坚持和加强党对体育工作的领导，将党的领导贯穿规划实施全过程。地方各级人民政府要落实主体责任，健全完善统筹协调、承接实施和监督保障机制。国家体育总局要会同有关部门加强统筹指导和协同支持，推动规划实施与年度工作计划有效衔接，开展规划实施情况动态监测、中期评估和总结评估。"}, {"title": "国家林草局等部门联合印发《林业草原保护利用“十五五”规划》", "detail": "国家林草局等四部门近日联合印发《林业草原保护利用“十五五”规划》。规划提出，到2030年，“三北”工程三大标志性战役取得决定性胜利，完成自然保护地整合优化，森林、草原、湿地、荒漠生态系统质量和服务功能不断增强，林草多元供给和消费场景更加丰富，林草产业总产值迈上新台阶。\n规划部署了科学开展大规模国土绿化行动、全面推进自然保护地体系建设、培育壮大林草产业、协同强化生态安全能力建设、持续深化重点领域改革、全力推动创新驱动与开放合作等方面任务。\n规划明确了系列指标：力争到2030年，林草覆盖率达到56.4%，森林覆盖率达到25.8%，森林蓄积量达到224亿立方米，林草产业总产值达到14万亿元。\n规划还布局了9项林草重大工程。如“三北”六期工程以防沙治沙为主攻方向，完成各类建设和巩固任务3亿亩以上；自然保护地体系建设工程加强自然保护地能力建设，有序设立新的国家公园；野生动植物保护工程开展165种极度濒危国家重点保护野生动植物抢救性保护和监测预警等。"}, {"title": "《中医药振兴发展“十五五”规划》", "detail": "《规划》实施要坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全会精神，认真落实四中全会部署，全面贯彻习近平总书记关于健康中国建设和中医药工作的重要论述，坚定不移走中国特色卫生与健康发展道路，坚定不移贯彻新时代卫生与健康工作方针，坚持中西医并重，坚持守正创新，遵循中医药规律和特点，完善中医药传承创新发展机制，加快推进中医药现代化，推动中医药走向世界，为推动“十五五”时期健康中国建设取得决定性进展提供有力支撑。\n各省、自治区、直辖市人民政府要把中医药振兴发展作为本地区“十五五”时期经济和社会发展的重要任务，加强组织领导，明确责任分工，完善工作机制，细化落实举措，确保《规划》各项目标任务和政策措施落到实处。鼓励各地发挥比较优势，因地制宜创新中医药振兴发展措施。\n明确提出到2030年，覆盖全民和全生命周期的中医药服务体系更加健全，基层服务提质升级；中医药防治重大疾病取得新突破，新增一批中医药国际标准等。"}, {"title": "四部门印发《综合运输服务发展“十五五”规划》", "detail": "交通运输部、国家铁路局、中国民用航空局、国家邮政局日前印发《综合运输服务发展“十五五”规划》，全面系统推动综合运输服务高质量发展。\n规划提出，到2030年，基本建成现代化综合运输服务体系。多层次、高品质、优体验的公众出行服务系统基本建成，全链条、一体化、韧性强的交通物流服务系统加快完善，交通物流降本提质增效稳步推进，跨区域、跨方式、跨领域运输服务一体融合程度显著提升，数智赋能应用场景有序拓展，运输本质安全水平大幅提高，重特大事故有效遏制，行业治理效能明显提高，人民群众出行服务满意度和货运物流服务品质进一步提高，服务支撑现代化经济体系和交通强国建设的能力显著增强。\n根据规划，到2030年，我国重点综合货运枢纽多式联运1小时换装率预计将达到90%，“一箱制”集装箱铁水联运箱量预计将提升到1000万标箱，中心城市绿色出行比例预计将达到76%，建有村级寄递物流综合服务站的建制村比例预计将达到90%，新能源重型卡车保有量占比预计将达到20%，小微型客车租赁服务覆盖主要客运枢纽比例预计将达到100%。\n交通运输部有关负责人表示，根据规划，将通过加快旅客联程运输服务升级、提升综合交通枢纽服务质效、推动运输服务与旅游融合发展、促进小微型客车租赁高质量发展、推动多式联运高质量发展、深入推进农村客货邮融合发展等方式推动综合运输协同融合发展。\n“到2035年，现代化综合运输服务体系更加完善，‘全国123出行交通圈’（都市区1小时通勤、城市群2小时通达、全国主要城市3小时覆盖）和‘全球123快货物流圈’（快货国内1天送达、周边国家2天送达、全球主要城市3天送达）基本形成，更好支撑‘人享其行、物畅其流’。”这名负责人说。"}, {"title": "中共中央 国务院转发《中央宣传部、司法部关于开展法治宣传教育的第九个五年规划（2", "detail": "026—2030年）》\n中共中央、国务院近日转发《中央宣传部、司法部关于开展法治宣传教育的第九个五年规划（2026—2030年）》（以下简称《规划》）。\n《规划》提出，法治宣传教育是全面依法治国的长期基础性工作，要以推动习近平法治思想深入人心为首要任务，以贯彻实施法治宣传教育法为抓手，以繁荣发展社会主义法治文化为支撑，以健全法治宣传教育工作体系为保障，践行社会主义核心价值观，弘扬社会主义法治精神，推进法治社会建设，为以中国式现代化全面推进强国建设、民族复兴伟业营造良好法治环境。\n到2030年，领导干部依法办事能力水平和公民法治素养持续提升，全社会崇尚法治、恪守规则、尊重契约、维护公正的良好环境进一步形成；法治宣传教育与依法治理、法治实践深度融合，全面依法治国的社会基础进一步夯实；“谁执法谁普法”普法责任制深入落实，法治宣传教育工作制度化规范化科学化水平全面提升。"}, {"title": "《2026年APEC林业部长级会议联合声明》发布", "detail": "7月28日，APEC林业部长级会议通过《2026年APEC林业部长级会议联合声明》。声明指出，期望各经济体促进生物多样性保护，将森林治理和可持续森林管理纳入经济发展计划，加强亚太区域在城市林业和水资源管理方面的合作。"}, {"title": "我国“十五五”期间单位国内生产总值二氧化碳排放将降17%", "detail": "《国家应对气候变化“十五五”规划》7月29日出台，明确到2030年，我国单位国内生产总值二氧化碳排放较2025年降低17%，全国碳排放权交易市场覆盖行业单位产品二氧化碳排放比2025年下降3%左右。"}, {"title": "自然资源部修订印发《临时用海管理办法》", "detail": "近日，自然资源部修订印发《临时用海管理办法》（以下简称《管理办法》）。《管理办法》首次提出通过差异化的管理方式匹配不同类型临时用海需求，并简化了审批流程，进一步规范各类临时用海活动。"}, {"title": "国务院印发《知识产权保护和运用“十五五”规划》", "detail": "国务院日前印发《知识产权保护和运用“十五五”规划》（以下简称《规划》）。\n《规划》锚定建设中国特色、世界水平的知识产权强国目标，部署了持续优化支持全面创新的知识产权保护环境、大力提升促进经济高质量发展的知识产权运用效能、不断健全推进高效能治理的知识产权综合管理体系、积极构建服务高水平对外开放的知识产权国际合作新格局等四方面重点任务，设立了战略性新兴产业知识产权保护工程、知识产权与人工智能双向赋能工程、知识产权服务区域发展工程、“一带一路”知识产权高质量合作工程等12个专项工程。"}, {"title": "《工业绿色低碳发展“十五五”规划》发布", "detail": "工业和信息化部7月31日印发《工业绿色低碳发展“十五五”规划》，推进钢铁、有色、建材、石化化工等重点行业用能结构转型、低碳工艺改造，提升绿色装备产品供给能力。到2030年，规模以上工业单位增加值能耗下降10%以上、二氧化碳排放下降17%以上，培育建设500个零碳工厂。"}, {"title": "“十五五”时期全国新建改造上百个战略农资储备库", "detail": "近日，《全国供销合作社“十五五”发展规划》（以下简称《规划》）发布。《规划》提出，到2030年，我国将新建改造上百个国家战略农资储备库，打造全国仓储设施骨干网。同时，在产粮大县新建改造1000个左右县域农资配送中心，全面提升农资保供稳价能力，夯实国家粮食安全根基。"}]}];
